P.entries["quest:1451"] = {n="拉普索迪·铁铲",s="狮鹫管理员塔隆艾克斯提到了拉普索·闪掘，他曾经是鸟舍里最优秀的飞行员，但因为沉迷烈酒，不得不被解雇。塔隆艾克斯听说拉普索现在在鸟舍东边的辛特兰建立了一个酿酒营地。",h="狮鹫管理员塔隆艾克斯提到了拉普索·闪掘，他曾经是鸟舍里最优秀的飞行员，但因为沉迷烈酒，不得不被解雇。塔隆艾克斯听说拉普索现在在鸟舍东边的辛特兰建立了一个酿酒营地。",kw={"鹰巢山","鸟舍","布罗汉","狮鹫管理员塔隆艾克斯","辛特兰","拉普索·闪掘"},sec={{t="坠落的飞行员",b="塔隆艾克斯强调，鸟舍的矮人们都很喜欢喝上好的麦芽酒，但拉普索对烈酒的痴迷就像狮鹫对天空的渴望一样强烈。在塔隆艾克斯看来，再没有人能比得上拉普索的飞行技术，这真是太可惜了。麻烦的最初迹象出现在拉普索与布罗汉的一次飞行回来后步履蹒跚之时，从此情况便急转直下。最终，拉普索只能被解雇。最后的传闻是，现在鹰巢山东边有一个酿酒营地。"}},faq={{q="是谁派你去寻找拉普索·闪掘的？",a="位于鹰巢山鸟舍的狮鹫管理员塔隆艾克斯指引你去寻找拉普索。",al={"谁开启了拉普索·闪掘任务","谁给予了拉普索任务","在哪里开始拉普索的任务"}},{q="拉普索·闪掘为什么会被鸟舍解雇？",a="拉普索对烈酒的痴迷就像狮鹫对天空的渴望一样强烈。麻烦的最初迹象出现在他与布罗汉的一次飞行回来后步履蹒跚之时，情况随后急转直下，塔隆艾克斯不得不解雇了拉普索。",al={"拉普索为什么被解雇","拉普索发生了什么","拉普索·闪掘背景故事"}},{q="拉普索现在在哪里？",a="塔隆艾克斯听说拉普索现在在鸟舍东边的辛特兰建立了一个酿酒营地。",al={"拉普索·闪掘在哪里","拉普索的营地位置","如何找到拉普索"}}},fp="19,249,14.431.0,42.72.0,51.211.0,22.94.0"}
P.entries["quest:1452"] = {n="拉普索迪的卡利姆多鸡尾酒",s="拉普索·辛迪格隐居在辛特兰，他只有在喝下烈酒之后才肯吐露在那片沼泽里究竟发生了什么。要调制一份卡利姆多鸡尾酒，需要塔纳利斯的巨鹏胃囊，以及来自菲拉斯的戈多克和铁鬃肝脏。",h="拉普索·辛迪格隐居在辛特兰，他只有在喝下烈酒之后才肯吐露在那片沼泽里究竟发生了什么。要调制一份卡利姆多鸡尾酒，需要塔纳利斯的巨鹏胃囊，以及来自菲拉斯的戈多克和铁鬃肝脏。",kw={"布罗汉","菲拉斯","戈多克肝脏","铁鬃肝脏","卡利姆多鸡尾酒","拉普索·辛迪格","巨鹏胃囊","塔纳利斯"},sec={{t="烈酒",b="拉普索打着嗝向布罗汉的信使打招呼。他们俩曾经有过一段冒险经历，而关于沼泽中发生的那些令人不快的事情，他只有在喝下一杯烈酒后才愿意诉说。拉普索脑子里有一个配方，也就是卡利姆多鸡尾酒，并答应一旦酿好就全盘托出。"},{t="来自卡利姆多的配料",b="这份鸡尾酒需要三个来自塔纳利斯的巨鹏胃囊，三个来自菲拉斯的戈多克肝脏，以及同样来自菲拉斯的三个铁鬃肝脏。即使是拉普索最好的麦芽酒，也不足以让他有勇气面对那次飞越沼泽的惨痛回忆。"}},faq={{q="拉普索调配卡利姆多鸡尾酒需要什么？",a="三个巨鹏胃囊、三个戈多克肝脏和三个铁鬃肝脏。拉普索在谈论沼泽里发生的事情之前，想要喝杯烈酒。",al={"为什么需要鸡尾酒","为什么需要巨鹏胃囊","为什么需要肝脏"}},{q="配料产自哪里？",a="巨鹏胃囊产自塔纳利斯。戈多克和铁鬃肝脏产自菲拉斯。",al={"哪里寻找胃囊","鸡尾酒配料地点","戈多克在哪里"}},{q="是谁派你来找拉普索·辛迪格的？",a="是布罗汉派你来的，拉普索管他叫疯子。在那之前，狮鹫管理员塔隆内克斯告诉了你拉普索的所在位置。",al={"谁派我去找拉普索","前置任务","布罗汉"}}},fp="28,231,13.324.0,25.237.0,50.144.0,35.85.0,36.128.0"}
P.entries["quest:1453"] = {n="寻物公司的业务",s="《Reclaimers' Business in Desolace》是一项联盟指引任务，引导冒险者从铁炉堡前往凄凉之地的严酷荒原。该任务由罗顿·石锤发布，要求新兵渡海前往尼耶尔前哨站寻找克雷迪格·安戈尔，协助Reclaimers回收失落的财宝和遗物以换取报酬。",h="《Reclaimers' Business in...",kw={"半人马","凄凉之地","铁炉堡","克雷迪格·安戈尔","尼耶尔前哨站","reclaimers","罗顿·石锤","石爪山脉"},ang={["faction:Alliance"]="尼耶尔前哨站是卡利姆多中部西部荒原中主要的联盟避难所，作为一个被敌对半人马氏族包围的集结地。",["race:Dwarf"]="无论是通过探险者协会，还是像Reclaimers这样的独立打捞团体，矮人的事业触角甚至伸向了卡利姆多最荒凉的角落。"},sec={{t="荒原的召唤",b="当铁炉堡还是一片熙熙攘攘、充满矮人事务的景象时，遥远的卡利姆多依然是一片未被驯服的边境。罗顿·石锤担任Reclaimers的城市联络人，这是一个热衷于利用被遗忘的废墟和荒芜之地的进取型组织。他招募路过这座伟大山城的渴望冒险的勇士，并警告他们：凄凉之地是一片遭受交战的半人马氏族蹂躏的恐怖荒原，但对那些勇于踏上旅程的人来说，这里也充满了有利可图的机会。"},{t="尼耶尔前哨站与Reclaimers",b="道路向西延伸，穿过石爪山脉进入凄凉之地北部，那里坐落着联盟的据点——尼耶尔前哨站，这是一处隐藏在悬崖高处的坚固避难所。在那里，克雷迪格·安戈尔欢迎新手的加入。Reclaimers的运作前提非常直截了当：在这个饱受战争蹂躏的世界里，人们不断丢失传家宝、魔法神器和家庭财宝。只要有足够的勇气和合适的报酬，克雷迪格和他的同伴就能确保这些失落的财物从荒野中被找回。"}},faq={{q="谁发布这个任务？",a="罗顿·石锤在铁炉堡提供此任务。他将寻找诚实、高薪工作的冒险者引向卡利姆多，去联系他的同事。",al={"任务发布者","谁开启reclaimers business in desolace任务","罗顿·石锤位置"}},{q="尼耶尔前哨站在哪里？",a="尼耶尔前哨站位于凄凉之地的东北部岩壁上。从石爪山脉向南进入凄凉之地时，沿着悬崖向东走，直到找到那条有火炬照明、蜿蜒通往联盟前哨站的山路。",al={"寻找尼耶尔前哨站","如何前往尼耶尔前哨站","尼耶尔前哨站位置"}},{q="Reclaimers是谁？",a="Reclaimers是一个由像克雷迪格·安戈尔这样的矮人特工领导的进取型企业。他们专门代表付费客户从世界各地的危险角落回收失落的传家宝、珍稀古董和魔法遗物。",al={"什么是reclaimers","reclaimers阵营","reclaimers背景故事"}},{q="凄凉之地潜伏着什么威胁？",a="凄凉之地是一片干旱、阴森的荒原，被交战的半人马部落、亡灵残部和敌对野生生物所统治。对于那些冒险走出石爪山脉的经验丰富的旅行者来说，这里是一个严酷的试炼场。",al={"凄凉之地的危险","凄凉之地有什么"}},{q="克雷迪格·安戈尔是谁？",a="克雷迪格·安戈尔是一名驻扎在凄凉之地尼耶尔前哨站的矮人。他负责协调该地区的打捞行动和遗物搜寻工作，招募有能力的冒险者去勇闯废墟和半人马营地。",al={"克雷迪格·安戈尔背景故事","克雷迪格是谁"}},{q="在凄凉之地做任务需要这个任务吗？",a="不需要，这只是一个可选的指引任务。你可以自行直接前往尼耶尔前哨站，但在出发前与罗顿·石锤交谈可以提供便捷的背景信息和指引。",al={"我需要做这个任务吗","reclaimers business in desolace是必须的吗"}}},fx={["7014e979"]={q="罗顿·石锤为什么派你去凄凉之地？",a="罗顿·石锤在铁炉堡负责联络回收者。他在尼耶尔前哨站的同伴身处凄凉之地的险恶环境，需要可靠能干的人手来处理委托。罗顿把像你这样的能干冒险者引荐给克雷迪格·安戈尔，确保他们的寻宝团队即使身处敌对的半人马领地，也能人手充足、维持盈利。",al={"为什么派我去凄凉之地","罗顿·石锤的动机","为什么要帮克雷迪格·安戈尔"}},f82b8baa={q="罗顿·石锤为什么招募冒险者，而不亲自前往？",a="在各个大陆经营回收业务，既需要在大城市打探消息，也需要在野外出力。罗顿留在铁炉堡招募新人、洽谈机会，把穿越石爪山脉的艰苦跋涉和凄凉之地的危险留给那些愿意为钱冒险的老练旅人。",al={"罗顿·石锤为什么需要我","为什么不亲自去","为什么招募冒险者"}}},fp="32,321,23.489.0,32.515.0,21.152.0,23.241.0,23.239.0,31.198.0,21.197.0,44.196.0"}
P.entries["quest:1454"] = {n="卡尼托的海难",s="克雷迪格·安戈尔向你提到了卡尼托，一位暴风城的贵族法师。海巨人在凄凉之地的西北水域袭击了他的船，他丢下一个贵重的箱子后传送离开了。现在必须找到那个箱子及其内容物。",h="克雷迪格·安戈尔向你提到了卡尼托，一位暴风城的贵族法师。海巨人在凄凉之地的西北水域袭击了他的船，他丢下一个贵重的箱子后传送离开了。现在必须找到那个箱子及其内容物。",kw={"凄凉之地","艾瑟雷索","卡尼托","克雷迪格·安戈尔","发掘者","海巨人","沉船","暴风城"},sec={{t="贵族的逃亡",b="在完成凄凉之地的“发掘者的生意”后，克雷迪格·安戈尔告诉了你第一件要务。这与卡尼托有关，他是暴风城的一位贵族法师。海巨人在凄凉之地的西北水域袭击了卡尼托的船。卡尼托和他的仆人试图将他最昂贵的箱子之一搬上岸，但巨人们蜂拥而至，他被迫放弃箱子，将自己和仆人传送走了。现在必须找到这个箱子及其内容物，然后交还给暴风城的卡尼托。它位于北海岸线，艾瑟雷索延伸地带。"},{t="箱子里有什么",b="箱子没有水渍，但盖子被强行撬开了，边缘的烧灼痕迹显示守护它的魔法陷阱早已被触发。"}},faq={{q="卡尼托是谁？",a="暴风城的一位贵族法师。海巨人在凄凉之地的西北水域袭击了他的船。",al={"卡尼托","谁是卡尼托","谁想要那个箱子"}},{q="卡尼托的船发生了什么？",a="海巨人在凄凉之地的西北水域袭击了它。卡尼托和他的仆人试图将一个贵重的箱子搬上岸，但巨人们蜂拥而至，于是他丢下箱子，带着仆人传送离开了。",al={"沉船故事","船为何沉没","海巨人袭击"}},{q="谁在寻找这个箱子？",a="克雷迪格·安戈尔，他说卡尼托想要找回这个箱子及其内容物，并送还给身在暴风城的他。",al={"谁给任务","克雷迪格·安戈尔的角色"}},{q="箱子在哪里？",a="在凄凉之地的北海岸线，艾瑟雷索延伸地带。",al={"卡尼托的箱子位置","卡尼托的箱子在哪里","艾瑟雷索箱子"}}},fp="22,250,16.559.0,20.160.1,16.110.0,33.211.0,29.105.0,25.70.0"}
P.entries["quest:1455"] = {n="卡尼托的海难",s="法师卡尼托的箱子被撬开了，里面空空如也。箱子侧面和顶部的长而深的抓痕表明，这既不是人类也不是巨人的杰作。你决定回到尼耶尔前哨站找克雷迪格·安戈尔复命。",h="法师卡尼托的箱子被撬开了，里面空空如也。箱子侧面和顶部的长而深的抓痕表明，这既不是人类也不是巨人的杰作。你决定回到尼耶尔前哨站找克雷迪格·安戈尔复命。",kw={"凄凉之地","卡尼托","卡尼托的箱子","克雷迪格·安戈尔","尼耶尔前哨站","沉船"},sec={{t="一个空箱子",b="你仔细观察了是什么撬开了这个箱子。箱子侧面和顶部布满了长而深的抓痕。它们表明作案者既不是人类也不是巨人，而且看起来也不像是匕首或剑留下的痕迹。箱子里面完全是空的。别无他法，你合上箱子准备离开，你知道克雷迪格·安戈尔肯定会很失望。"}},faq={{q="卡尼托的箱子里有什么？",a="什么都没有。箱子是完全空的。",al={"卡尼托的箱子里有什么","卡尼托的箱子是空的吗","箱子里的物品"}},{q="是什么在箱子上留下了痕迹？",a="长而深的抓痕布满了侧面和顶部。这表明既不是人类也不是巨人所为，而且看起来也不像是匕首或剑留下的痕迹。",al={"是什么打开了箱子","谁拿走了货物","箱子上的爪痕"}},{q="你需要向谁汇报？",a="凄凉之地尼耶尔前哨站的克雷迪格·安戈尔。",al={"我该去哪交任务","克雷迪格·安戈尔在哪里","接下来去哪"}},{q="在此之前发生了什么？",a="寻找卡尼托的箱子，这是克雷迪格·安戈尔交给你的任务。",al={"上一个任务","卡尼托的沉船任务线"}}},fp="22,218,14.340.0,32.39.0,33.158.0,21.44.0,22.66.0"}
P.entries["quest:1456"] = {n="卡尼托的海难",s="克雷迪格·安戈尔仍然认为可以找到卡尼托的遗物。沿着海岸往上走，在拉纳加尔岛附近，滑刃娜迦占据了沉在海底的暗夜精灵废墟，克雷迪格认为那个皮包最有可能就在那里。",h="克雷迪格·安戈尔仍然认为可以找到卡尼托的遗物。沿着海岸往上走，在拉纳加尔岛附近，滑刃娜迦占据了沉在海底的暗夜精灵废墟，克雷迪格认为那个皮包最有可能就在那里。",kw={"凄凉之地","卡尼托","克雷迪格·安戈尔","拉纳加尔岛","回收者","皮包","海巫","滑刃","潮汐捕猎者"},sec={{t="深海遗迹",b="在卡尼托船难搜寻任务的第二部分之后，克雷迪格·安戈尔告诉你希望并没有破灭。沿着同一海岸向北，靠近拉纳加尔岛的地方，海底沉没着暗夜精灵的废墟，滑刃娜迦以那里为家。克雷迪格判断那是卡尼托的皮包最可能所在的地方。他提供了一瓶“回收潜水药剂”。"},{t="更强大的娜迦",b="克雷迪格认为能走这么远的侦察队一定是一支精锐部队。因此，在搜寻卡尼托的物品时，克雷迪格建议先找那些更强大的娜迦，也就是潮汐捕猎者和海巫。"}},faq={{q="谁让你去寻找卡尼托的皮包？",a="位于凄凉之地的克雷迪格·安戈尔。",al={"谁发布此任务","卡尼托的皮包任务发布者","谁是克雷迪格·安戈尔"}},{q="克雷迪格认为这些遗物在哪里？",a="在海岸北面，靠近拉纳加尔岛的沉没暗夜精灵废墟中，那里是滑刃娜迦的据点。",al={"卡尼托的皮包在哪里","皮包位置","滑刃娜迦在哪里"}},{q="克雷迪格建议先搜寻哪种娜迦？",a="潮汐捕猎者和海巫，这些更强大的娜迦。克雷迪格推断，能深入到如此南方的侦察队一定非常强大。",al={"谁拥有这个皮包","哪些娜迦拥有它","潮汐捕猎者还是海巫"}},{q="在此之前的任务是什么？",a="卡尼托船难搜寻任务的第二部分。",al={"卡尼托船难任务线","之前的任务"}}},fp="22,245,17.355.0,17.205.0,40.27.0,44.120.0,48.138.0,22.67.0"}
P.entries["quest:1457"] = {n="卡尼托的背包",s="克雷迪格·安戈尔让你带着卡尼托的挎包前往铁炉堡，把它交给罗顿·石锤，他会为你支付报酬。",h="克雷迪格·安戈尔让你带着卡尼托的挎包前往铁炉堡，把它交给罗顿·石锤，他会为你支付报酬。",kw={"凄凉之地","铁炉堡","卡尼托","卡尼托的挎包","克雷迪格·安戈尔","勘探者协会","罗顿·石锤"},sec={{t="返回铁炉堡",b="克雷迪格·安戈尔让你把卡尼托的物品送回铁炉堡的罗顿·石锤那里，他会为你支付报酬。克雷迪格笑着补充说，罗顿可能会很高兴，你甚至会被邀请全职加入勘探者协会。回去的路应该小心，不要磨蹭，因为卡尼托虽然慷慨，但没什么耐心。"},{t="在铁炉堡",b="罗顿·石锤对你在凄凉之地处理卡尼托生意的方式表示赞许。箱子本身毁坏了，但里面的东西都在，罗顿把这些留给卡尼托去评判。勘探者协会的职责是寻找失物，而不是保证它们完好无损。然后，罗顿开始为你安排报酬。"}},faq={{q="我应该把卡尼托的挎包交给谁？",a="铁炉堡的罗顿·石锤。",al={"我该把挎包带到哪","卡尼托的沉船任务交付","谁收卡尼托的挎包"}},{q="是谁让我回铁炉堡的？",a="克雷迪格·安戈尔，他对你完成的工作表示赞赏。",al={"谁发布任务","卡尼托的沉船任务发布者第四部分"}},{q="为什么必须尽快交付挎包？",a="克雷迪格说卡尼托虽然非常慷慨，但没什么耐心。",al={"为什么要赶往铁炉堡","卡尼托有耐心吗"}},{q="罗顿·石锤是谁？",a="勘探者协会在铁炉堡的人。他的生意非常兴隆，小事都交给了手下。",al={"罗顿·石锤背景故事","罗顿是谁"}}},fp="22,139,17.359.0,12.346.1,39.34.0,31.50.0,51.70.0,27.111.0"}
P.entries["quest:1458"] = {n="寻物公司的委托",s="克雷迪格·安戈尔正在为居住在卡拉诺斯的侏儒法师莱夫特威奇收集施法材料，而挖掘者协会的人手有些不足。在处理清单上的其他事项之前，他需要从东边的仇恨之怒萨特那里弄到一些爪子和角。",h="克雷迪格·安戈尔正在为居住在卡拉诺斯的侏儒法师莱夫特威奇收集施法材料，而挖掘者协会的人手有些不足。在处理清单上的其他事项之前，他需要从东边的仇恨之怒萨特那里弄到一些爪子和角。",kw={"凄凉之地","仇恨之怒","卡拉诺斯","克雷迪格·安戈尔","莱夫特威奇","挖掘者协会","罗滕","萨格隆","萨特"},sec={{t="莱夫特威奇的清单",b="在处理完凄凉之地的挖掘者协会事务后，克雷迪格·安戈尔手头还有另一件活儿：为居住在卡拉诺斯的侏儒法师莱夫特威奇去取施法材料。罗滕认为这是一笔轻松的生意，因为挖掘者协会的人已经在凄凉之地了，而克雷迪格则表示他并不在乎人手不足的问题。"},{t="角和爪",b="清单上的第一批物品应该很容易搞定。克雷迪格想要从东边的仇恨之怒萨特身上弄到十个爪子和十个角，这些萨特就在尼耶尔前哨站正东方的萨格隆废墟里。一旦他拿到这些东西，清单上的其余工作就可以开始了。"}},faq={{q="谁在索要这些施法材料？",a="克雷迪格·安戈尔正为一位名叫莱夫特威奇的侏儒法师收集这些材料，他住在卡拉诺斯。罗滕认为这是一笔轻松的生意，因为挖掘者协会的人已经在凄凉之地了。",al={"莱夫特威奇是谁","为挖掘者协会准备的施法材料任务给予者","谁想要施法材料"}},{q="仇恨之怒萨特在哪里？",a="仇恨之怒萨特在萨格隆的废墟中，位于尼耶尔前哨站的正东方。",al={"仇恨之怒萨特位置","仇恨之怒爪子在哪里","仇恨之怒角位置"}},{q="克雷迪格想要从萨特那里得到什么？",a="十个仇恨之怒爪子和十个仇恨之怒角。只要拿到这些，他和你就能继续处理莱夫特威奇清单上的下一批物品了。",al={"我需要收集什么","为挖掘者协会准备的施法材料物品","需要的萨特部位"}},{q="克雷迪格怎么看萨特？",a="他称它们为卑鄙的生物。他听说它们与暗夜精灵有某种联系，尽管他对此表示怀疑。在他看来，这个故事源于几年前将它们带入战争的那位精灵，从那以后，世界就变得更加危险和令人恐惧了。",al={"克雷迪格关于萨特的背景故事","萨特是暗夜精灵吗"}}},fp="28,226,16.302.0,15.247.0,33.171.0,38.82.0,39.124.0,37.271.0"}
P.entries["quest:1459"] = {n="寻物公司的委托",s="在Leftwitch的清单上，接下来要为克雷迪格·安戈尔准备的是Scorpashi的毒液和年迈科多兽的皮。克雷迪格说不出这两样东西在哪里，因为他并不了解凄凉之地。",h="在Leftwitch的清单上，接下来要为克雷迪格·安戈尔准备的是Scorpashi的毒液和年迈科多兽的皮。克雷迪格说不出这两样东西在哪里，因为他并不了解凄凉之地。",kw={"年迈科多兽皮","凄凉之地","铁炉堡","克雷迪格·安戈尔","leftwitch","reclaimers inc","scorpashi毒液"},sec={{t="接下来要准备的物品",b="在完成了Leftwitch清单的第一部分后，克雷迪格·安戈尔转而处理接下来的物品。它们看起来很简单，但要求很具体。那个法师想要Scorpashi的毒液，任何Scorpashi的都可以；还有科多兽的皮，但必须是年迈科多兽的皮。垂死和古老的科多兽皮没用。克雷迪格需要七瓶毒液和三张皮。克雷迪格思忖道，法师们总是要求一些奇怪的东西。"},{t="不熟悉的地带",b="克雷迪格根本不知道科多兽和Scorpashi在哪里游荡。他对这个地区知之甚少，也没有时间去探索它。"}},faq={{q="谁在请求这些试剂？",a="Leftwitch，一位法师，克雷迪格·安戈尔正在处理他的清单。",al={"谁想要试剂","leftwitch是谁","克雷迪格的上司"}},{q="为什么克雷迪格需要帮助来寻找这些生物？",a="克雷迪格几乎不了解凄凉之地，也没有时间去探索，所以说不出科多兽和Scorpashi在哪里游荡。",al={"为什么克雷迪格无法获得它们","克雷迪格对区域的了解"}},{q="任何科多兽的皮都可以用吗？",a="不行。Leftwitch的要求仅限于年迈科多兽；垂死和古老的科多兽皮没用。",al={"任意科多兽皮","古老科多兽皮","垂死科多兽皮"}},{q="什么是Scorpashi？",a="它们是在凄凉之地各处都能找到的蝎子。Leftwitch说任何Scorpashi的毒液都可以。",al={"scorpashi毒液","scorpashi在哪里"}},{q="年迈科多兽在哪里游荡？",a="成群的科多兽沿着小径行走，主要分布在南部和西部，许多最终会聚集在科多兽坟场附近。",al={"年迈科多兽位置","年迈科多兽在哪里"}}},fp="28,175,14.378.0,17.123.0,33.63.0,51.117.0,32.88.0,23.96.0,28.104.0"}
P.entries["quest:146"] = {n="送往夜色镇的信",s="“夜色镇的信使”终结了湖畔镇与夜色镇之间那场绝望的外交通信。艾尔罗·埃伯洛克公爵断然拒绝了所罗门镇长对于军事增援的恳求，揭露了一个苦涩的事实：这两个城镇都已被暴风城抛弃，只能自生自灭。",h="“夜色镇的信使”终结了湖畔镇与夜色镇之间那场绝望的外交通信。艾尔罗·埃伯洛克公爵断然拒绝了所罗门镇长对于军事增援的恳求，揭露了一个苦涩的事实：这两个城镇都已被暴风城抛弃，只能自生自灭。",kw={"夜色镇","埃伯洛克","湖畔镇","信使","守夜人","所罗门","暴风城"},ang={["faction:Alliance"]="这份公文揭露了导致南部王国分裂的深刻裂痕，偏远的联盟定居点发现自己已被抛弃且毫无防备。",["race:Human"]="对于人类旅行者来说，这份通信是一个发人深省的例证，展示了当王室宫廷对此视而不见时，王国各城镇变得多么孤立无援。"},sec={{t="被拒绝的绝望请求",b="面对黑石兽人和豺狼人的猛攻，Redridge的所罗门镇长希望他在暮色森林的老友能分出一些部队。但艾尔罗·埃伯洛克公爵的反应近乎愤怒。夜色镇几乎无法抵挡从森林各个角落涌来的活死人、贪婪的野兽和被诅咒的魔法。埃伯洛克直言不讳地指出，守夜人的存在仅仅是因为暴风城率先抛弃了暮色森林。抽调夜色镇的防御力量，只会导致该定居点在巡逻队还没穿过林边空地之前就陷落。"},{t="被遗弃的先例",b="当所罗门读到埃伯洛克的回复时，他对王国严酷的现实有了切身体会。暴风城军队撤出了西部荒野，让夜色镇自生自灭，如今又无视了湖畔镇的求援。所罗门不得不面对整个王国的各地领导人们私下里的窃窃私语：这不仅仅是官僚主义的疏忽或无能，而是潜伏在暴风城核心之中的可疑背叛。"}},faq={{q="为什么埃伯洛克公爵不派守夜人去帮助湖畔镇？",a="夜色镇四面受敌，亡灵、野兽和邪恶的巫术环伺。守夜人是一支非正规的地方民兵组织，其成立正是因为暴风城撤走了驻军。如果埃伯洛克把他的卫兵派往Redridge，夜色镇会在部队抵达林边空地之前就沦陷。",al={"埃伯洛克为何拒绝","湖畔镇为何没有守夜人","夜色镇拒绝提供援助"}},{q="所罗门镇长在读到回复后意识到了什么？",a="所罗门意识到，湖畔镇的困境只是王国范围危机的一部分。随着军队从西部荒野撤离，守卫完全离开了夜色镇，所罗门怀疑暴风城的领导层内部存在积极的背叛，而不仅仅是简单的疏忽。",al={"所罗门的反应","所罗门意识到了什么"}},{q="谁组建了守夜人？",a="在暴风城的正规军将暮色森林抛弃给黑暗与腐朽之后，守夜人是由暮色森林饱受困扰的市民和领袖们在艾尔罗·埃伯洛克公爵的领导下组建的。",al={"守夜人的起源","谁组建了守夜人"}},{q="所罗门接下来该去哪里寻求帮助？",a="随着夜色镇拒绝提供援助，而西部荒野被迪菲亚潜行者占领，湖畔镇陷入了彻底的孤立。所罗门不得不更加审视暴风城的宫廷，以查明为什么王室拒绝保护其边远领土。",al={"所罗门接下来做什么","还有谁能帮助湖畔镇"}},{q="暴风城是否正式撤出了暮色森林和西部荒野？",a="是的。当黑暗魔法腐蚀了暮色森林，而西部荒野爆发动乱时，暴风城的正规部队撤离了，留下了边境城镇自行组建当地民兵组织，如守夜人和人民军，以求生存。",al={"暴风城为何离开","暴风城抛弃了城镇"}},{q="所罗门和埃伯洛克之间是什么关系？",a="他们是长期共事的同僚，也是管理王国边境城镇的镇长。所罗门在请求派遣部队时寄希望于这种私人关系，但暮色森林严峻的危局使得对方无法提供援助。",al={"所罗门和埃伯洛克是朋友吗","所罗门和艾尔罗的关系"}}},fx={ec08915e={q="伊伯洛克领主为什么派你送信，而不是派自己的卫兵？",a="伊伯洛克领主一个守夜人都抽调不出来。夜色镇被黑暗和可怕的邪物围困，每一把剑都急需用于防守，以免城镇沦陷。你从湖畔镇赶来，是所罗门镇长派出的信使；由你带着他的回信返回，夜色镇就不必牺牲宝贵的防守力量。",al={"为什么派我去","为什么不派守夜人","为什么派冒险者去"}}},fp="22,292,26.542.0,24.418.1,64.301.0,63.257.0,27.189.0,44.245.0,59.213.0,51.234.0"}
P.entries["quest:1462"] = {n="大地灵契",s="大地萨普塔是鸦羽先知在纳拉其营地提供的一种补充仪式用品。正在进行启蒙仪式以与大地之灵沟通的年轻萨满需要这种药剂来开启他们的内在视野。如果新手在完成仪式前不慎丢失或洒掉了准备好的药剂，先知会再准备一份，以确保他们的试炼能够继续进行。",h="大地萨普塔是鸦羽先知在纳拉其营地提供的一种补充仪式用品。正在进行启蒙仪式以与大地之灵沟通的年轻萨满需要这种药剂来开启他们的内在视野。如果新手在完成仪式前不慎丢失或洒掉了准备好的药剂，先知会再准备一份，以确保他们的试炼能够...",kw={"call of earth","纳拉其营地","药剂","大地萨普塔","元素","莫高雷","鸦羽先知","萨满"},ang={["class:Shaman"]="萨普塔是你早期训练的基础工具，它是开启你双眼、让你首次见到指引世界的元素力量的精神催化剂。",["faction:Horde"]="部落对萨满传统的依赖是在莫高雷这样的地方培育起来的，部落先知们耐心地培养着下一代的精神领袖。",["race:Tauren"]="敬畏大地母亲始于学会聆听土地，纳拉其营地的长者们非常用心地确保没有任何年轻人会被挡在神圣的道路之外。"},sec={{t="幻象药剂",b="萨满之路始于将凡人的感官与物理视野之外的力量调和。为了感知土地的元素之灵，萨满学徒必须饮用一种被称为萨普塔的强效仪式药剂。大地萨普塔注入了与土元素和大地紧密结合的自然精华，揭开了物质世界与精神位面之间的面纱，使新手能够直接与莫高雷的土元素进行沟通。"},{t="开启视野的第二次机会",b="精神领域的修行需要极高的纪律性，但经验丰富的先知们明白，年轻的学徒在野外磨练时往往会犯错或弄丢神圣的试剂。鸦羽先知在纳拉其营地时刻保持警惕，确保任何在石碑前进行沟通仪式前丢失药剂的学徒都能重新获得准备。她怀着平静的耐心，再次提供容器，让新手能够毫无阻碍地面对精神之灵。"}},faq={{q="什么是大地萨普塔？",a="大地萨普塔是由萨满长者酿制的一种神圣草药制剂。当学徒饮用后，它能唤醒他们的内在感官，赋予他们所需的精神视野，使其能够感知并与普通人眼中不可见的土元素进行沟通。",al={"什么是萨普塔","大地萨普塔背景知识","药剂的作用"}},{q="为什么学徒需要另一份大地萨普塔？",a="在野外进行试炼的受训者有时会在到达指定的圣地之前丢失、洒掉或过早饮用他们的药剂。鸦羽先知会提供另一份药剂，以免他们的精神修行因一个小小的失误而永久中断。",al={"萨普塔丢失了","为什么需要再拿一份萨普塔","大地萨普塔丢失"}},{q="鸦羽先知是谁？",a="鸦羽先知是一位驻守在莫高雷纳拉其营地的牛头人精神向导。她负责监督年轻牛头人萨满的早期试炼，引导他们完成与大地之灵的第一次沟通。",al={"谁是鸦羽先知","鸦羽先知背景知识","纳拉其营地先知"}},{q="为什么萨满必须喝萨普塔才能看到元素？",a="初级萨满尚未磨练出与元素之间的内在羁绊，无法随心所欲地感知它们。萨普塔充当了一座桥梁，改变了饮用者的精神知觉，直到他们学会通过自己的力量去倾听并与元素沟通。",al={"为什么需要药水才能看见灵魂","为什么要喝萨普塔"}},{q="大地萨普塔的试炼在哪里进行？",a="仪式试炼在莫高雷纳拉其营地附近的红云台地山丘上进行。新手将药剂带到当地土元素栖息的一座神圣石碑前。",al={"我在哪里使用萨普塔","大地的召唤位置"}},{q="所有的萨满都使用萨普塔吗？",a="牛头人和兽人的萨满传统在最初的元素启蒙仪式中都会使用萨普塔。他们首次沟通的每一种元素，如大地、火焰和水，都有其各自的萨普塔，以帮助调整萨满的感官去适应特定的元素位面。",al={"兽人使用萨普塔吗","萨普塔是牛头人专用的吗"}}},fx={["5f71bc62"]={q="鸦羽先知为什么又给你一份大地灵契？",a="鸦羽先知负责引导年轻的牛头人新兵完成元素试炼。不饮用大地灵契，新兵就无法与大地之灵交流，也无法完成沟通仪式。如果你弄丢或洒掉了药剂，鸦羽先知会再给你一份，以免你还没见到元素就不得不中断这趟神圣旅程。",al={"鸦羽先知为什么给大地灵契","鸦羽先知的动机","为什么再次给灵契"}}},fp="11,355,19.433.0,24.422.0,23.266.0,47.265.0,25.214.0,48.248.0,51.181.0,25.255.0"}
P.entries["quest:1463"] = {n="大地灵契",s="这个差事是对试炼谷中萨满祭司学徒的一项责任考验。如果学徒在与大地之灵沟通前弄丢了神圣的大地药水，坎纳甘·地鸣会提供补给，并严厉提醒他们要妥善保管这些神圣的药剂。",h="这个差事是对试炼谷中萨满祭司学徒的一项责任考验。如果学徒在与大地之灵沟通前弄丢了神圣的大地药水，坎纳甘·地鸣会提供补给，并严厉提醒他们要妥善保管这些神圣的药剂。",kw={"call of earth","坎纳甘·地鸣","药剂","杜隆塔尔","大地药水","萨满","图腾","试炼谷"},ang={["class:Shaman"]="对于学徒来说，丢失药水是关于纪律的早期教训：与元素沟通需要稳定的专注力，而不是漫不经心的手。",["race:Orc"]="在杜隆塔尔干旱的岩缝中，学习萨满古老之道的年轻兽人必须证明他们对先祖和足下大地的奉献精神。",["race:Troll"]="在试炼谷行走于元素之道的暗矛巨魔学会了在他们传统的洛阿崇拜与对元素之灵的直接敬畏之间保持平衡。"},sec={{t="元素给予的第二次机会",b="萨满祭司的道路需要绝对的专注和对世界灵体的尊重。大地药水是一种经过特殊仪式准备的元素药剂，旨在稀释物质世界与岩石和土壤之灵之间的帷幕。当学徒在穿越杜隆塔尔时无意中弄丢或洒掉了这瓶药剂，坎纳甘·地鸣愿意凭善意再准备一份，但也会警告新手必须更加小心对待这些神圣的礼物。"},{t="坎纳甘的指引",b="坎纳甘·地鸣负责照看从试炼谷大兽穴中走出的萨满新兵。虽然他理解年轻的兽人和巨魔容易在最初的试炼中犯错，但他强调元素之灵并不喜欢这种疏忽。接受第二瓶药水也是一个小小的谦逊教训，确保年轻的萨满记住大地赋予的力量必须得到守护和尊重。"}},faq={{q="大地药水是什么？",a="大地药水是一种供萨满祭司学徒使用的、经过特殊制备的仪式药剂。饮用后可获得灵视，使饮用者能够感知并与凡眼无法看见的大地元素之灵对话。",al={"什么是药水","大地药水用途","药水的目标"}},{q="为什么坎纳甘·地鸣会提供这个任务？",a="如果学徒在完成大地之唤试炼的沟通仪式前丢失或弄丢了大地药水，坎纳甘·地鸣会提供补给。他凭善意授予另一份，以便学徒能够完成他们的灵魂任务。",al={"为何坎纳甘提供药水","我弄丢了大地药水"}},{q="这个仪式在哪里进行？",a="这一交接发生在试炼谷，也就是杜隆塔尔西南部那片被阳光炙烤的峡谷，年轻的兽人和巨魔在那里开启了他们纪律与荣誉的旅程。",al={"坎纳甘在哪里","试炼谷药水位置"}},{q="弄丢药水会被灵体视为不敬吗？",a="虽然灵体是宽容的，但坎纳甘提醒学徒，草率对待神圣药剂体现出缺乏专注。真正的萨满必须以绝对的敬畏之心对待每一份元素礼物。",al={"丢失药水有影响吗","关于丢失药水的传说"}},{q="谁可以进行这种沟通？",a="大地药水的准备和饮用仅限于正在寻求调和并获得他们的第一个元素图腾——大地图腾——的练习萨满祭司。",al={"谁可以获得大地药水","药水的职业要求"}},{q="学徒喝下药水后会发生什么？",a="饮下药剂会开启学徒的内在视觉，使他们能够找到并与躲藏在试炼谷岩缝中的当地大地之灵化身交谈。",al={"饮用药水的效果","大地药水之后"}}},fp="11,293,33.494.0,17.415.0,23.229.0,45.248.0,34.167.0,47.197.0,33.161.0,48.189.0"}
P.entries["quest:1465"] = {n="瓦拉里尔的搜寻",s="继续搜寻玛雷姆一家的马车，你找到了一枚坠饰，还有向南延伸的脚印。远处的巨大堡垒升起了炊烟。你应该将坠饰拿给尼耶尔前哨站的瓦拉里尔·屠魔者看，并告诉他玛雷姆一家可能还活着的迹象。",h="继续搜寻玛雷姆一家的马车，你找到了一枚坠饰，还有向南延伸的脚印。远处的巨大堡垒升起了炊烟。你应该将坠饰拿给尼耶尔前哨站的瓦拉里尔·屠魔者看，并告诉他玛雷姆一家可能还活着的迹象。",kw={"火刃氏族","屠魔者","凄凉之地","堡垒","玛雷姆","尼耶尔前哨站","坠饰","瓦拉里尔"},sec={{t="生命迹象",b="进一步搜查马车时，你发现了一枚坠饰，在那之外还有通往南方的脚印。远处，一座大堡垒冒出了烟。那是由有人照看的火堆产生的，并不是建筑燃烧引起的。你的直觉告诉你，如果玛雷姆一家还活着，他们就是被带往了那个方向。"},{t="给瓦拉里尔的消息",b="尼耶尔前哨站的瓦拉里尔·屠魔者应该看看这枚玛雷姆坠饰，并听听关于那通往南方的脚印的消息。"},{t="当地人的说法",b="瓦拉里尔对整件事感到愤怒。他曾警告过那两个玛雷姆，凄凉之地非常危险，而现在两人失踪了，甚至可能遭遇了更糟的情况。听到有足迹通往附近的堡垒，瓦拉里尔认为这是目前最好的线索。据当地人所说，那座堡垒被火刃氏族占领了，那是一群投身于恶魔事业的兽人。他们不代表大多数部落成员，但他们是邪恶的，任何被抓到窥探他们的人都会被当场处死。"}},faq={{q="你在马车里发现了什么？",a="一枚坠饰，还有通往南方的脚印。在远处，一座大堡垒升起了烟。",al={"箱子里有什么","马车线索","玛雷姆坠饰"}},{q="这些足迹通向哪里？",a="向南，通往一座大堡垒。上面的烟是由有人照看的火堆产生的，而不是建筑燃烧的烟，这说明如果玛雷姆一家还活着，他们是被带往了那个方向。",al={"脚印通向哪里","堡垒在哪里","足迹方向"}},{q="瓦拉里尔·屠魔者在哪里？",a="瓦拉里尔·屠魔者位于凄凉之地的尼耶尔前哨站。那就是你应该带上坠饰和足迹消息去的地方。",al={"瓦拉里尔位置","哪里上交玛雷姆坠饰","瓦拉里尔·屠魔者地点"}}},fp="19,264,13.261.0,19.118.0,19.448.1,31.99.0,25.174.0,40.108.0"}
P.entries["quest:1466"] = {n="寻物公司的委托",s="克雷迪格·安戈尔手里有Leftwitch想要的最后一些物品，但他承认这可不是什么好差事，而且会比之前的任务花更久的时间。所有这些东西都来自恶魔：大脑、翅膀和血瓶。",h="克雷迪格·安戈尔手里有Leftwitch想要的最后一些物品，但他承认这可不是什么好差事，而且会比之前的任务花更久的时间。所有这些东西都来自恶魔：大脑、翅膀和血瓶。",kw={"凄凉之地","末日守卫血液","地狱犬大脑","克雷迪格·安戈尔","leftwitch","玛诺洛克集会所","虚空之翼","reclaimers inc"},sec={{t="清单上的最后一项",b="克雷迪格警告说这最后一批物品处理起来很麻烦，收集速度比以往任何时候都要慢。Leftwitch需要三种部件，每种十个。大脑来自地狱犬：法力吞噬者、法师猎手或魔网猎手。翅膀来自虚空女妖、虚空姐妹或虚空女巫。血液来自末日守卫队长或领主。克雷迪格说如果你拒绝这个任务，他完全理解。"},{t="凄凉之地的恶魔",b="克雷迪格甚至都没意识到这些恶魔竟然在凄凉之地。据他阅读的资料，自从暗夜精灵多年前离开后，凄凉之地大部属于半人马，他很纳闷这些恶魔是怎么来的，为什么要在这里定居。它们就栖息在凄凉之地南部的玛诺洛克集会所附近，越过科多兽坟场就能找到。"}},faq={{q="是谁在索要这些恶魔部件？",a="克雷迪格·安戈尔转交了Leftwitch的清单，而这些恶魔部件就是上面的最后几项物品。",al={"谁发布的任务","谁想要恶魔部件","克雷迪格·安戈尔是谁"}},{q="哪些生物身上有所需的物品？",a="地狱犬大脑来自法力吞噬者、法师猎手和魔网猎手。翅膀来自虚空女妖、虚空姐妹和虚空女巫。血液来自末日守卫队长和领主。",al={"什么掉落地狱犬大脑","去哪获得虚空之翼","哪些末日守卫有血液"}},{q="在哪里可以找到这些恶魔？",a="它们聚集在凄凉之地南端的玛诺洛克集会所附近，越过科多兽坟场。",al={"恶魔位置","玛诺洛克集会所在哪里","恶魔在哪里游荡"}},{q="为什么克雷迪格觉得这些恶魔很奇怪？",a="他曾读到过，在暗夜精灵多年前离开后，半人马占据了凄凉之地，所以恶魔的出现让他感到困惑。",al={"为什么恶魔在凄凉之地","凄凉之地半人马背景"}}},fp="28,188,20.389.0,18.291.0,36.92.0,39.177.0,32.92.0,44.116.0"}
P.entries["quest:1467"] = {n="寻物公司的委托",s="克雷迪格·安戈尔把莱夫特维奇的包裹交给你，并让你回到铁炉堡。你应该找罗顿·石锤领取报酬，克雷迪格承诺回到家乡后会美言你几句。",h="克雷迪格·安戈尔把莱夫特维奇的包裹交给你，并让你回到铁炉堡。你应该找罗顿·石锤领取报酬，克雷迪格承诺回到家乡后会美言你几句。",kw={"凄凉之地","铁炉堡","克雷迪格·安戈尔","莱夫特维奇的包裹","回收者公司的试剂","罗顿·石锤"},sec={{t="在铁炉堡领取报酬",b="克雷迪格说你的报酬在铁炉堡等着你，罗顿·石锤本人会负责。罗顿会很高兴能甩掉莱夫特维奇的包裹，把包裹交给他足以换取你应得的报酬。克雷迪格预计在凄凉之地待不了多久了，他依然打算回到家乡后好好夸奖你。"},{t="罗顿的感谢",b="罗顿·石锤接收了来自凄凉之地的莱夫特维奇的包裹，并感谢你的辛勤工作以及如此迅速地完成了任务。你的报酬已经准备好了，罗顿表示，回收者公司总是会给辛勤工作一周的员工丰厚的报酬。"}},faq={{q="是谁让你回到铁炉堡的？",a="在收集完试剂后，克雷迪格·安戈尔让你带着莱夫特维奇的包裹回到铁炉堡。",al={"任务发布者","谁发布任务","谁开启任务"}},{q="莱夫特维奇的包裹需要送到哪里？",a="它需要送到铁炉堡的罗顿·石锤那里。",al={"包裹送到哪里","包裹目的地","谁接收包裹"}},{q="为什么要带包裹去找罗顿？",a="克雷迪格说你的报酬是由罗顿亲自发放的，所以必须在铁炉堡把包裹交给他。",al={"为什么要带包裹","为什么要拜访罗顿"}},{q="克雷迪格·安戈尔还会留在凄凉之地吗？",a="根据克雷迪格的说法，他不会再待太久了。他依然打算回到家乡后好好夸奖你。",al={"克雷迪格会离开凄凉之地吗","克雷迪格要去哪里"}}},fp="28,189,20.296.0,16.225.1,32.99.0,42.44.0,40.90.0,39.95.0"}
P.entries["quest:1469"] = {n="拉普索迪的故事",s="在拉普索迪·辛迪格喝下他的卡利姆多鸡尾酒后，他终于讲述了与布罗哈恩·铁桶一起飞行的故事。他交出一块阿塔莱石板碎片，并请求将其送到暴风城的布罗哈恩那里。",h="在拉普索迪·辛迪格喝下他的卡利姆多鸡尾酒后，他终于讲述了与布罗哈恩·铁桶一起飞行的故事。他交出一块阿塔莱石板碎片，并请求将其送到暴风城的布罗哈恩那里。",kw={"阿塔莱","布罗哈恩","铁桶","碎片","辛特兰","拉普索迪","辛迪格","暴风城","石板"},sec={{t="给布罗哈恩的碎片",b="喝了鸡尾酒之后，拉普索迪·辛迪格终于肯开口了。飞行之前，他喝了一整桶烈性黑啤酒，而布罗哈恩紧跟在他身后飞越天空。他从那次飞行中保留了一件巨魔纪念品，即一块阿塔莱石板碎片，他希望你能把它送到暴风城的布罗哈恩·铁桶那里。"},{t="飞行终点在哪里",b="拉普索迪在空中没有看到任何神庙。然后，因为喝得太醉，他从坐骑上掉了下来，一头扎进水里。他被吸了进去，发现自己置身于阴森的巨魔之中，于是迅速游了出来，还顺手带走了一件纪念品。所以，布罗哈恩的神庙确实在水下。"}},faq={{q="谁接收阿塔莱石板碎片？",a="拉普索迪请求将其带给暴风城的布罗哈恩·铁桶。",al={"我要把碎片给谁","布罗哈恩的位置","石板送到哪里"}},{q="拉普索迪对与布罗哈恩的飞行有何记忆？",a="飞行前，拉普索迪喝了一整桶烈性黑啤酒，然后他在天空中飞驰，布罗哈恩紧随其后。",al={"为什么拉普索迪要飞行","布罗哈恩和拉普索迪"}},{q="此步骤之前发生了什么？",a="拉普索迪的卡利姆多鸡尾酒是先决条件。在喝到那杯酒之前，拉普索迪不愿讲述这个故事。",al={"前置任务","拉普索迪的传说前置要求"}}},fp="15,209,22.278.0,22.259.1,41.67.0,55.112.0,27.105.0"}
P.entries["quest:147"] = {n="猎杀收货人",s="“搜捕行动”是一个由闪金镇的治安官杜汉发布的联盟任务，旨在消灭一名被称为“收税人”的迪菲亚潜行者骨干。这名特工盘踞在遭受入侵的布莱克威尔南瓜田，将从艾尔文森林矿井偷窃的黄金直接输送至迪菲亚潜行者的金库中。",h="“搜捕行动”是一个由闪金镇的治安官杜汉发布的联盟任务，旨在消灭一名被称为“收税人”的迪菲亚潜行者骨干。这名特工盘踞在遭受入侵的布莱克威尔南瓜田，将从艾尔文森林矿井偷窃的黄金直接输送至迪菲亚潜行者的金库中。",kw={"布莱克威尔南瓜田","收税人","迪菲亚潜行者","闪金镇","搜捕行动","治安官杜汉","戒指","石匠工会"},ang={["class:Rogue"]="收税人在南瓜田的潜行勾当凸显了在艾尔文森林各地生根发芽的劫匪与扒手网络正在不断扩张。",["faction:Alliance"]="保护暴风城的本地资源至关重要；阻止收税人也就切断了王国黄金的非法外流，这些资金本被用于在首都门前资助叛乱。",["race:Human"]="取回石匠的戒指触动了暴风城近代史上的一根敏感神经，让人回忆起首都重建后那场分裂王国的惨痛劳资纠纷。"},sec={{t="南瓜田的正义",b="在发现艾尔文森林的豺狼人身上携带的一份采金日程表后，治安官杜汉派遣冒险者前往布莱克威尔南瓜田。这片曾经宁静的农场现已被迪菲亚强盗和豺狼人所占据。在那杂草丛生的藤蔓间潜伏着“收税人”，他是一名负责掠夺王国矿产并为集结中的叛军组织运输物资的中间人。"},{t="工匠印戒",b="在击杀“收税人”后，冒险者取回了他的戒指并交给治安官杜汉。令杜汉感到困惑的是，这枚戒指上印的并非普通的罪犯徽记，而是旧暴风城石匠工会的标志。这一发现揭示了一个令人不安的事实：那些扼住艾尔文森林咽喉的劫匪不仅仅是投机取巧之徒，他们竟是暴风城重建之后因心怀不满而堕落为不法之徒的前工匠们。"}},faq={{q="我在哪里可以找到收税人？",a="收税人潜藏在布莱克威尔南瓜田，位于艾尔文森林东南部，马科伦农场以东，河流边界以北。",al={"收税人位置","收税人在哪","收税人地点"}},{q="收税人为什么要从艾尔文森林的矿井偷窃黄金？",a="他收集从狗头人出没的法戈第矿洞和石碑湖矿洞中走私出的矿石及勒索所得，用以资助迪菲亚潜行者在整个王国境内的秘密行动。",al={"为什么要偷黄金","迪菲亚矿洞","收税人在干什么"}},{q="收税人的戒指有什么重要意义？",a="这是一枚旧石匠工会的成员戒指，该工会的工匠们在第一次战争后重建了暴风城。治安官杜汉无法解释为什么一名与迪菲亚潜行者合作的底层窃贼会持有一枚工匠工会戒指，他希望这个问题终有一天能得到解答。",al={"收税人戒指背景","石匠戒指","戒指意味着什么"}},{q="治安官杜汉知道是谁在幕后操纵迪菲亚潜行者吗？",a="并没有立刻知道。治安官杜汉认出了戒指上的工匠徽记，但他很困惑为什么一个普通的窃贼会持有一枚工匠工会印戒，这使得更广泛的阴谋在闪金镇仍然是一个未解之谜。",al={"杜汉知道吗","杜汉的反应","治安官杜汉石匠工会"}},{q="是谁指派你执行这次搜捕行动？",a="在取回迪菲亚采金日程表后，驻扎在闪金镇Lion's Pride Inn的卫戍部队指挥官——治安官杜汉会向你提供这个任务。",al={"谁发布搜捕行动","搜捕行动任务发布者","治安官杜汉任务"}},{q="布莱克威尔一家发生了什么事？",a="布莱克威尔南瓜田已经沦为废墟，被主人遗弃，并被迪菲亚潜行者、强盗以及在东南部林地游荡的河爪豺狼人所占据。",al={"布莱克威尔背景","谁拥有南瓜田","布莱克威尔农场"}}},fp="7,224,28.325.0,17.371.1,31.145.0,55.184.0,49.271.1,61.207.1,30.143.0,38.176.0"}
P.entries["quest:1470"] = {n="控制小鬼",s="“刺穿面纱”是丧钟镇的温雅·玛山德给予术士的一项入门试炼。它要求新生的术士从附近的无脑骷髅身上收集头骨，以此考验他们的意志。完成这项任务后，新手就能获得召唤并奴役小鬼仆从所需的知识。",h="“刺穿面纱”是丧钟镇的温雅·玛山德给予术士的一项入门试炼。它要求新生的术士从附近的无脑骷髅身上收集头骨，以此考验他们的意志。完成这项任务后，新手就能获得召唤并奴役小鬼仆从所需的知识。",kw={"丧钟镇","小鬼","刺穿面纱","断骨骷髅的颅骨","提瑞斯法林地","温雅·玛山德","术士"},ang={["class:Warlock"]="这一成人礼标志着你真正踏入了恶魔学领域，证明了混乱魔法必须服从于钢铁意志这一基本课程。",["race:Undead"]="被遗忘者术士利用他们与死亡超然的疏离感，在丧钟镇的阴影中无所畏惧地研究混乱与黑暗魔法。"},sec={{t="新手的第一步",b="刚刚苏醒的被遗忘者术士在丧钟镇开始他们的旅程，并接受温雅·玛山德的指导。她教导说，真正的力量不在于原始的蛮力，而在于知识和对混乱力量的精确掌握。为了证明他们具备刺穿世界之间的面纱并奴役虚空生物所需的专注力和能力，新手们被派往丧钟镇废弃铁匠铺附近，收割那些游荡的摇铃骷髅的头骨。"},{t="奴役虚空",b="一旦收集到骸骨，温雅便认为这位学徒已经准备好超越简单的暗影法术。这些回收的材料是一次成人礼，证明了新手能够战胜无脑的亡灵，并承受他们职业的凄凉现实。作为回报，温雅传授了将小鬼置于召唤者命令之下的仪式，并警告说尽管这个恶魔身材矮小，但它的狡诈和火焰将使它成为一个危险的盟友。"}},faq={{q="谁发布了“刺穿面纱”任务？",a="该任务由提瑞斯法林地丧钟镇的被遗忘者术士训练师温雅·玛山德发布。",al={"谁开启刺穿面纱","刺穿面纱任务发布者","温雅·玛山德任务"}},{q="完成此任务需要收集什么？",a="你必须收集三个摇铃骷髅头骨，这是通过摧毁在丧钟镇废弃铁匠铺附近徘徊的摇铃骷髅获得的。",al={"刺穿面纱目标","刺穿面纱收集什么","摇铃骷髅头骨"}},{q="温雅·玛山德为什么要这些骷髅头骨？",a="在温雅将更危险的恶魔仪式托付给这些术士新手之前，狩猎无脑的骷髅可以测试他们的控制力、意志力和基本的魔法能力。",al={"为什么收集摇铃骷髅头骨","骷髅任务的目的"}},{q="你学会了召唤什么力量或仆从？",a="完成这项课程后，术士就能召唤并奴役小鬼，这是施法者学会命令的第一个恶魔同伴。",al={"刺穿面纱奖励法术","我获得了什么恶魔","小鬼召唤任务"}},{q="摇铃骷髅在哪里？",a="它们在丧钟镇的郊外徘徊，特别是在主城镇空地西北方向那座摇摇欲坠的废弃铁匠铺周围。",al={"摇铃骷髅位置","丧钟镇的骷髅在哪里","丧钟镇废弃铁匠铺"}},{q="谁有资格接受这个任务？",a="只有在丧钟镇达到适当入门训练等级的被遗忘者术士才能接受此任务。",al={"谁能接受刺穿面纱","其他职业可以做这个吗","这是术士专属吗"}}},fx={["149b6242"]={q="断骨骷髅的颅骨有什么用？",a="温雅·玛山德用这些颅骨来考验你逐渐掌握的黑暗魔法。术士相信，知识与意志是自己最强大的武器。证明你能从躁动的亡者身上收集这些遗骸，就表明你有足够的自制力召唤并束缚一个小鬼，让它为你效力。",al={"断骨骷髅的颅骨有什么用","为什么要收集断骨骷髅的颅骨","断骨骷髅颅骨的作用"}},d722d37c={q="断骨骷髅是什么？",a="断骨骷髅是没有心智的天灾亡灵，徘徊在丧钟镇废弃的铁匠铺周围。和提瑞斯法林地的许多地方一样，这片区域仍被瘟疫遗迹和巫妖王溃败的军队所纠缠，因此成了被遗忘者新手术士检验自身力量的方便目标。",al={"断骨骷髅是什么","丧钟镇的断骨骷髅","这里为什么有断骨骷髅"}},d14f3c7d={q="温雅·玛山德为什么派你去，而不自己处理？",a="温雅·玛山德是你的术士训练师，不是雇佣兵头目。收集颅骨并不是她需要你替她完成的差事，而是你必须学习的重要一课。若想洞穿帷幕，将虚空混沌生物纳入自己的掌控，你必须先独自证明自己的力量与决心。",al={"洞悉帷幕任务为什么派我去","温雅为什么让你收集颅骨","温雅·玛山德为什么不自己去拿"}}},fp="17,294,21.468.0,22.460.0,38.100.0,45.148.0,45.165.0,44.131.0,43.144.0,40.126.0"}
P.entries["quest:1471"] = {n="誓缚",s="“羁绊”是遗忘者术士为了能够驾驭虚空行者而必须完成的终极仪式。在幽暗城的Magic Quarter，凯伦丁·哈加尔要求初学者召唤、征服并永久奴役一个来自虚空的生物。",h="“羁绊”是遗忘者术士为了能够驾驭虚空行者而必须完成的终极仪式。在幽暗城的Magic Quarter，凯伦丁·哈加尔要求初学者召唤、征服并永久奴役一个来自虚空的生物。",kw={"凯伦丁·哈加尔","magic quarter","召唤符文","奴役","羁绊","幽暗城","虚空行者","术士任务"},ang={["class:Warlock"]="这场仪式标志着术士从利用小鬼进行琐碎戏法的阶段，转变到了真正能够支配那些在战场上承受巨大物理伤害的实体的阶段。",["race:Undead"]="对于遗忘者而言，束缚一个阴影生物是他们自身坚韧的自然延伸，而且他们对禁忌魔法没有任何道德上的顾忌。"},sec={{t="奴役仪式",b="不同于那些通过黑魔法就能轻易诱使其签订契约的小鬼，虚空生物蔑视现实世界，并拥有强大的物理力量。为了获得召唤虚空行者的权利，幽暗城的术士学徒必须证明自己对其拥有绝对的掌控力。在Magic Quarter的阴影区域，遗忘者导师凯伦丁·哈加尔会提供必要的神秘符文，将虚空行者从虚空撕裂并带入物理位面。"},{t="法阵之内",b="仪式是在导师高台下刻绘的闪光召唤法阵中进行的。一旦符文被激活，一个未受束缚的虚空行者就会在狂怒中现身。制服它并非外交辞令般的谈判；召唤者必须通过纯粹的奥术力量和强大的意志击垮这个实体。只有当这个实体被彻底压制后，凯伦丁才会传授真正的召唤公式，从而将该生物的本质无限期地束缚在施法者身上。"}},faq={{q="这个仪式的目的是什么？",a="这项仪式旨在考验术士学徒压制虚空生物的能力。通过在战斗中击败一个未受束缚的虚空行者，召唤者证明了自己的意志足以掌控它，凯伦丁·哈加尔才会传授他们永久性的召唤法术。",al={"为何进行羁绊仪式","羁绊任务的作用","羁绊任务奖励"}},{q="召唤在哪里进行？",a="召唤是在幽暗城Magic Quarter内，凯伦丁·哈加尔平台下方的地板上刻绘的紫色召唤法阵中进行的。",al={"在哪里召唤虚空行者","召唤法阵的位置","幽暗城召唤法阵"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是居住在幽暗城Magic Quarter的主要术士训练师，负责监督新复生的遗忘者施法者的教学与黑暗启蒙仪式。",al={"哈加尔是谁","凯伦丁·哈加尔背景故事"}},{q="术士是否需要击败他们想要召唤的每一个恶魔？",a="术士在指挥强大的异次元生物之前，必须确立自己的权威。虽然像小鬼这样的小型实体可以通过简单的契约和仪式来束缚，但虚空行者需要施法者展现出身体和魔法上的绝对支配权，才会臣服并效命。",al={"术士是否总是需要与恶魔战斗","为何要与虚空行者战斗"}},{q="如果术士没能制服虚空行者会怎样？",a="一个未受束缚的虚空行者会无情地攻击并摧毁周围的一切。正如哈加尔所警告的那样，没能达到他的期望与被法阵中失控的实体撕成碎片相比，根本不值一提。",al={"如果羁绊失败会怎样","术士失败设定"}},{q="什么是虚空行者？",a="虚空行者是源自虚空的阴影异次元生物。它们拥有极强的物理抗性，且天生渴望熄灭活着的生命光芒与能量，这使它们成为黑暗魔法使用者理想的防护盾。",al={"什么是虚空行者","虚空行者背景"}}},fx={abacfa90={q="凯伦丁·哈加尔为什么要进行这个仪式？",a="凯伦丁·哈加尔致力于增强幽暗城术士的力量。通过要求你召唤一个未受束缚的虚空生物，并完全将其意志折服于你，他确保被遗忘者的施法者能够掌握真正的控制之道，而不会沦为自己试图支配的异界生物的猎物。",al={"凯伦丁·哈加尔为什么要进行束缚仪式","凯伦丁·哈加尔的动机","为什么召唤虚空行者"}},["68d93197"]={q="你奉命召唤并击败的是什么生物？",a="你要把一个未受束缚的虚空行者从扭曲虚空直接召唤到召唤法阵中。虚空行者是由纯粹虚空能量构成的暗影恶魔，敌视并憎恨被奴役；只有以魔法和武力将其彻底击败，它才会服从主人的意志。",al={"束缚任务中要和什么交手","束缚任务的目标","我在召唤谁"}},["15849809"]={q="为什么必须由你亲自降服虚空行者，而不是让凯伦丁·哈加尔来做？",a="恶魔学要求你亲自确立支配地位。被召唤的恶魔只会屈服于那个以魔法权威和坚韧体魄将它征服的人。如果凯伦丁或城卫介入并降服它，虚空行者就会受他们的意志束缚，而非听命于你。",al={"为什么必须由我来战斗","凯伦丁为什么不帮忙","束缚任务为什么派我去"}}},fp="11,234,21.440.0,17.447.0,35.262.0,36.154.0,23.182.0,59.255.0,57.218.0,21.246.0"}
P.entries["quest:1472"] = {n="噬魂者",s="“灵魂吞噬者”是亡灵术士在学习召唤并奴役魅魔之路上的入门任务。在幽暗城诅咒神殿中，凯伦丁·哈加尔指引学员去向他的助手高德瑞克·法杉请教，学习如何从扭曲虚空中诱捕这种生物。仪式需要一种无法抗拒的诱饵：纯洁且充满爱意的凡人之心。",h="“灵魂吞噬者”是亡灵术士在学习召唤并奴役魅魔之路上的入门任务。在幽暗城诅咒神殿中，凯伦丁·哈加尔指引学员去向他的助手高德瑞克·法杉请教，学习如何从扭曲虚空中诱捕这种生物。仪式需要一种无法抗拒的诱饵：纯洁且充满爱意的凡人之...",kw={"诱饵","凯伦丁·哈加尔","高德瑞克·法杉","纯洁的心","魅魔","诅咒神殿","幽暗城"},ang={["class:Warlock"]="奴役魅魔是术士训练中的一个重要里程碑，展示了利用恶魔固有的恶习和欲望来奴役它们的黑暗艺术。",["race:Undead"]="诅咒神殿中的被遗忘者术士导师们行事毫无道德约束，随意地将鲜活的纯洁与奉献视为虚空仪式的消耗性试剂。"},sec={{t="诱饵与虚空",b="凯伦丁·哈加尔教导说，魅魔并不能仅仅通过命令就被强行拉过界限，它必须受到引诱。这种恶魔受到腐蚀美德和吞噬凡人精华的无尽饥渴驱动，需要特定的诱饵。术士的策略在于利用这种单一的欲望，将真正有美德、有爱心的男人的心脏作为诱饵奉上。哈加尔指引他的侍僧去找高德瑞克·法杉，因为他知道在哪里可以收割这种稀有的猎物。"},{t="盲眼助手",b="高德瑞克·法杉位于诅咒神殿深处，协助凯伦丁进行恶魔奴役的实践准备工作。虽然法杉失去了肉体的视力，但他声称自己的状况赋予了他深邃的“第二视力”，使他能够以惊人的清晰度感知底层的精神流向和远方的灵魂。他担任向导，负责定位引出恶魔所需的纯洁之心。"}},faq={{q="这个任务的目的是什么？",a="此任务连接了凯伦丁·哈加尔的初步召唤与奴役魅魔所需的实际狩猎阶段。它将术士指引向高德瑞克·法杉，由后者详细说明仪式所需的病态材料。",al={"为什么要完成灵魂吞噬者","幽暗城魅魔任务","20级术士任务"}},{q="为什么召唤魅魔需要纯洁之心？",a="魅魔以腐蚀善良、诱惑凡人之心和吞噬纯洁灵魂为生。凯伦丁·哈加尔解释说，没有无法抗拒的刺激，恶魔很难闯入这个世界，而善良之人不染尘埃的奉献便是诱惑其跨越界限的理想诱饵。",al={"为什么要纯洁的心","魅魔诱饵传说"}},{q="高德瑞克·法杉是谁？",a="高德瑞克·法杉是一名亡灵术士侍僧，在诅咒神殿协助凯伦丁·哈加尔。尽管双目失明，他却拥有能够感知精神真相并定位东部王国各地合适猎物的神秘感官。",al={"法杉是谁","盲眼术士助手"}},{q="这个任务在哪里完成？",a="该任务直接在幽暗城的诅咒神殿中交付，就在凯伦丁·哈加尔几步之遥的地方，高德瑞克·法杉正在那里等待。",al={"高德瑞克·法杉在哪里","灵魂吞噬者任务交付"}},{q="“灵魂吞噬者”之后是什么？",a="法杉会立即指派任务“纯洁的心”，要求术士前往湿地和银松森林的格雷迈恩之墙，夺取两名拥有美德的凡人的心脏。",al={"灵魂吞噬者后续任务","纯洁的心后续"}},{q="任何种族都可以进行这个仪式吗？",a="虽然任务地点位于幽暗城，由被遗忘者导师指导，但任何寻求通过幽暗城导师奴役魅魔的部落术士，都可以执行哈加尔和法杉提供的仪式步骤。",al={"谁能做灵魂吞噬者","仅限亡灵的术士任务"}}},fx={["99fee797"]={q="凯伦丁·哈加尔为什么想召唤魅魔？",a="凯伦丁·哈加尔负责指导幽暗城术士的成长。魅魔狡诈、善于诱惑且心怀恶意，是操纵敌人意志、将欲望化为致命弱点的强大工具。凯伦丁指导你完成仪式，让你能直接将恶魔束缚于自己的命令之下，扩充被遗忘者的黑暗武备，同时证明你已掌握扭曲虚空的力量。",al={"凯伦丁·哈加尔的动机","凯伦丁为什么要召唤魅魔","凯伦丁在灵魂吞噬者任务中的目标"}},["2acf7f0a"]={q="凯伦丁为什么派你去，而不亲自处理？",a="恶魔奴役仪式不能由另一名施法者代为完成。魅魔只会服从亲自引诱、束缚并支配她的那个人。作为导师，凯伦丁·哈加尔会指导你的学习，并传授仪式的基础知识；但只有你能准备诱饵、面对恶魔，并彻底掌控它的灵魂。",al={"凯伦丁·哈加尔为什么需要我","灵魂吞噬者任务为什么派我去","为什么让术士玩家召唤魅魔"}}},fp="17,385,18.458.0,19.420.0,34.211.0,52.283.0,22.257.0,30.162.0,35.200.0,35.210.0"}
P.entries["quest:1473"] = {n="虚空中的生物",s="“虚空生物”是亡灵术士的一个关键试炼，要求他们从血色十字军手中夺回一本遗失的奥术典籍。为了学习如何召唤并束缚混乱的虚空行者，受训者必须向西前往提瑞斯法林地，从敌对狂热者的手中夺回埃加林的魔典。",h="“虚空生物”是亡灵术士的一个关键试炼，要求他们从血色十字军手中夺回一本遗失的奥术典籍。为了学习如何召唤并束缚混乱的虚空行者，受训者必须向西前往提瑞斯法林地，从敌对狂热者的手中夺回埃加林的魔典。",kw={"凯伦丁·哈加尔","埃加林","埃加林的魔典","佩林","血色十字军","诅咒神庙","提瑞斯法林地","幽暗城","虚空行者"},ang={["class:Warlock"]="这个任务标志着你从摆弄小鬼转变为控制能够吸收巨大物理伤害的前线重型暗影实体。",["faction:Horde"]="在幽暗城实践的黑暗艺术基于严谨的学术技巧，将危险的位面力量转化为部落边境战争中可靠的资产。",["race:Undead"]="打击血色十字军以夺回黑暗知识，突显了被遗忘者与占据洛丹伦废墟的生者狂热者之间的苦涩斗争。"},sec={{t="导师的遗产",b="在幽暗城的诅咒神庙阴暗的壁龛中，凯伦丁·哈加尔负责监督亡灵术士新手的成长。当学徒证明自己有能力驾驭超越小鬼的力量时，哈加尔就会引导他们去束缚一种由纯粹阴影和混乱锻造而成的生物：虚空行者。亡灵术士们并不依赖简单的直觉，而是基于哈加尔的前任导师埃加林的详尽研究来进行召唤，正是埃加林首次记录了降服这些虚空居民所需的仪式。"},{t="被窃的魔典",b="如果不得到埃加林的魔典，就无法掌握虚空行者，因为它包含了引导这种极不稳定魔法的精确方法。然而，这本珍贵的书籍被血色十字军的一名特工——一个名叫佩林的狂热者偷走了，他驻扎在西边的一座哨塔里。虽然佩林和他的十字军战士很可能只是把这本魔典视为需要没收和私藏的亵渎违禁品，但如果被遗忘者想要在试图撕开虚空面纱之前确保仪式的秘密，夺回它就至关重要。"}},faq={{q="什么是埃加林的魔典？",a="埃加林的魔典是一本由术士埃加林撰写的魔法手册，他曾是凯伦丁·哈加尔的导师。书中详细记载了突破虚空并将虚空行者召唤至施法者绝对控制之下所需的复杂引导技巧和法术。",al={"埃加林的魔典","什么是这本书","埃加林是谁"}},{q="为什么血色十字军要偷这本书？",a="血色十字军认为所有的恶魔和暗影魔法本质上都是腐化的。一名叫佩林的特工在一次小规模冲突或渗透中夺取了这本魔典，并将其藏在提瑞斯法林地西边的一座瞭望塔中，他们似乎并不知道书中所蕴含的特定召唤力量。",al={"为什么血色十字军要拿走它","佩林 魔典","血色哨塔 西边"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是幽暗城诅咒神庙里的一名术士训练师。他指导亡灵术士新手，教导他们尊重动荡的宇宙力量，并用他自己过去召唤失败的教训告诫他们要保持谨慎。",al={"凯伦丁·哈加尔","术士训练师 幽暗城","诅咒神庙 训练师"}},{q="如果术士失去了对虚空行者的控制会怎样？",a="虚空行者是纯粹的混乱与阴影生物。正如凯伦丁·哈加尔所警告的那样，如果受训者在没有完美的纪律和束缚意志的情况下尝试召唤它，该实体将残暴地撕碎它的召唤者。",al={"虚空行者会杀了你吗","虚空行者的危险","召唤失败"}},{q="夺回魔典之后要做什么？",a="一旦哈加尔拿到了书，他就会研读其中的文字并将仪式的符文传授给你。这直接引出了“束缚”任务，受训者必须利用召唤法阵召唤出一只虚空行者，并通过个人战斗击败它以确立统治地位。",al={"魔典之后是什么","下一个任务","束缚仪式"}},{q="血色十字军的前哨站位于哪里？",a="这本魔典被藏在位于提瑞斯法林地西侧的一座血色十字军瞭望塔内，由佩林指挥下的十字军守卫着。",al={"佩林在哪里","血色哨塔位置","书在哪里"}}},fx={["4bce35a3"]={q="凯伦丁·哈加尔为什么要你完成这件事？",a="凯伦丁·哈加尔看出你的力量日渐增强，认为你已经准备好召唤虚空行者。这门危险的技艺需要严格遵循他自己的导师埃加林记载的仪式。哈加尔不仅要训练你，也不能让这份强大而黑暗的知识落入血色十字军手中；那些狂热分子会毫不犹豫地利用或销毁这份被盗的文本。",al={"哈加尔的目的","为什么要取回魔典","哈加尔为什么需要这本书"}},b85cee29={q="谁拿着埃加林的魔典？",a="一个名叫 Perrine 的血色十字军成员偷走了魔典，并把它藏在西边的一处血色十字军哨站里。Perrine 很可能还不知道那些发霉书页中蕴藏着怎样的恶魔学力量，但狂热分子一直驻守在那里，监视并伺机袭击幽暗城。",al={"谁偷走了魔典","谁拿着埃加林的魔典","血色十字军成员的目标"}},["9e338ab7"]={q="凯伦丁·哈加尔为什么派你去，而不是亲自前往？",a="哈加尔在诅咒神殿担任召唤大师，指导初出茅庐的术士，并监管被遗忘者的黑暗技艺。更重要的是，取回魔典是对你才智与决心的重要考验。若一名术士连自己的工具都无法从狂热的人类十字军手中夺回，那么在试图支配从扭曲虚空撕扯而来的混乱生物时，必定会失败。",al={"为什么派我去","哈加尔为什么不能自己拿回书","哈加尔为什么需要我"}}},fp="20,304,18.549.0,19.515.0,26.244.0,43.285.0,23.242.0,56.210.0,41.253.1,45.154.0"}
P.entries["quest:1474"] = {n="誓缚",s="“束缚”是幽暗城术士召唤并掌控魅魔的旅程中最终的试炼。在凯伦丁·哈加尔的指导下，施法者使用纯洁的心将恶魔从扭曲虚空拉入仪式法阵，并通过战斗征服它的意志。",h="“束缚”是幽暗城术士召唤并掌控魅魔的旅程中最终的试炼。在凯伦丁·哈加尔的指导下，施法者使用纯洁的心将恶魔从扭曲虚空拉入仪式法阵，并通过战斗征服它的意志。",kw={"束缚","凯伦丁·哈加尔","magic quarter","纯洁的心","魅魔","幽暗城","术士"},ang={["class:Warlock"]="这项仪式代表了你黑暗道路上至关重要的一步，证明了你有能力驾驭诱人的精神力量，并将狡诈的虚空生物束缚在你的意志之下。",["race:Undead"]="被遗忘者修行者以务实的眼光看待恶魔奴役，使用任何必要的黑暗工具来确保在洛丹伦的生存与统治。"},sec={{t="意志的试炼",b="在Magic Quarter阴暗的壁龛中，被遗忘者术士们精进着对恶魔实体的掌控力。召唤魅魔被视为一道关键的晋升仪式。不同于虚空行者的蛮力或是小鬼那种微不足道的恶意，魅魔拥有能够诱惑并囚禁施法者心智的魅惑和精神魔法。凯伦丁·哈加尔要求初学者证明他们的意志和魔法坚不可摧，才会放心地让他们永久支配此类实体。"},{t="法阵中的征服",b="通过使用从湿地和银松森林的无辜灵魂身上采集到的纯洁的心，术士开启了一扇通往扭曲虚空的裂隙。一旦被召唤进入束缚法阵，恶魔便会立刻发动攻击，试图制服或魅惑施法者。只有击碎它的物理形态并将它的精华打回虚空，术士才能确立绝对的支配地位，从而获得随心所欲召唤该恶魔的知识。"}},faq={{q="这个任务的目的是什么？",a="这项仪式使被遗忘者术士能够证明他们对高等恶魔的掌控力。通过在Magic Quarter召唤并击败魅魔，术士证明了自己不会被其魅惑所动摇，从而获得在战斗中召唤并指挥魅魔的法术。",al={"为什么要进行束缚","束缚有什么奖励","这个任务是做什么的"}},{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是位于幽暗城Magic Quarter的一名术士训练师。他负责监督被遗忘者施法者的训练和试炼，在准许他们进行更危险的召唤仪式前，测试他们的精神耐力和黑暗技艺。",al={"谁发布了束缚任务","凯伦丁·哈加尔背景故事"}},{q="为什么要用纯洁的心来召唤恶魔？",a="魅魔这种恶魔以情感、纯洁和腐化为食。在之前的任务中获取的纯洁的心起到了无法抗拒的形而上诱饵的作用，引诱恶魔通过召唤法阵直接在凡人位面显形。",al={"为什么需要纯洁的心","纯洁的心的用途"}},{q="召唤在哪里进行？",a="召唤直接在幽暗城的Magic Quarter进行，使用凯伦丁·哈加尔和术士导师们附近的专业仪式法阵。",al={"在哪里召唤魅魔","幽暗城召唤法阵位置"}},{q="为什么必须杀死魅魔？",a="术士从不与奴仆进行谈判，他们只进行征服。通过在召唤法阵中粉碎恶魔的形态，术士使其精神屈服于自己的统治，确保它作为顺从的奴仆回归，而非作为主人。",al={"为什么要与魅魔战斗","为什么要杀死被召唤的魅魔"}},{q="魅魔对幽暗城的术士危险吗？",a="是的。尽管被遗忘者对恐惧和睡眠具有相当强的精神抵抗力，但凯伦丁·哈加尔明确警告过，魅魔的魅惑曾束缚过许多强大的心智。仪式期间的疏忽大意将导致死亡或成为奴隶。",al={"魅魔能魅惑亡灵吗","魅魔的危险性"}}},fx={c35097a2={q="被召唤的魅魔是什么？它为什么会在这里？",a="你正要穿越虚空，将一只魅魔直接召唤到魔法区的召唤法阵中。魅魔是狡诈的恶魔，擅长迷惑凡人的心智，因此是术士最危险的可束缚仆从之一。这只恶魔并非生来就居于此地；它是被你收集的纯洁之心引入我们的世界，专为让你在战斗中击溃它的意志。",al={"被召唤的魅魔是谁","我在和什么战斗","魅魔的目标"}},["8c406b80"]={q="为什么必须由你亲自召唤并击败魅魔？",a="降服恶魔是只能亲自面对的试炼，无法假手他人。凯伦丁·哈加尔虽是你的导师，但要缔结恶魔契约，必须由召唤者亲自运用心智与魔法击破恶魔的防御。若哈加尔或城卫出手替你制服魅魔，恶魔便绝不会服从你的命令，而你作为术士的权威也仍不完整。",al={"凯伦丁为什么不能对付魅魔","凯伦丁为什么需要我","为什么让我对付魅魔"}}},fp="11,266,14.469.0,25.459.1,34.250.0,23.245.0,48.246.0,36.155.0,39.237.0,44.240.0"}
P.entries["quest:1476"] = {n="纯洁者之心",s="“纯洁之心”是高德瑞克·法杉代表凯伦丁·哈加尔在幽暗城指派的一项邪恶术士试炼。为了准备召唤魅魔所需的祭品，一名渴望获得召唤能力的术士必须追踪并屠杀两名极其正直的人类。他们纯洁的心是诱捕这名即将被召唤的恶魔魅魔无法抗拒的诱惑。",h="“纯洁之心”是高德瑞克·法杉代表凯伦丁·哈加尔在幽暗城指派的一项邪恶术士试炼。为了准备召唤魅魔所需的祭品，一名渴望获得召唤能力的术士必须追踪并屠杀两名极其正直的人类。他们纯洁的心是诱捕这名即将被召唤的恶魔魅魔无法抗拒的诱...",kw={"凯伦丁·哈加尔","科马尔·维拉德","达林·福杰莱特","高德瑞克·法杉","格雷迈恩之墙","纯洁之心","魅魔","诅咒神殿","萨多尔大桥","幽暗城"},ang={["class:Warlock"]="这一成年礼教会了术士：必须学会武器化的不仅仅是痛苦和恐惧，还有他人的高尚品德，才能将恶魔束缚在自己的意志之下。",["faction:Alliance"]="受害者是联盟和人类残余中悲剧性的人物——一个保护着被吉尔尼斯拒之门外的饥饿难民，另一个在沼泽地里徒劳地寻找失踪的配偶。",["race:Undead"]="这项任务展现了被遗忘者令人不寒而栗的世界观，他们随手将洛丹伦的幸存者及其持久的美德视为进行祭祀屠宰的便利牲畜。"},sec={{t="恶魔的诱饵",b="想要束缚魅魔，必须透彻理解双向的诱惑。虚空的塞壬们以欲望和毁灭为食，但没有什么比未受腐化的纯真更能将她们从扭曲虚空吸引出来。在诅咒神殿中，召唤大师凯伦丁·哈加尔将基础工作委托给了高德瑞克·法杉，由他在人类土地上搜寻那些善良纯洁、未受侵蚀的灵魂。"},{t="猎物",b="法杉锁定了两名德行高尚的典范。第一位是达林·福杰莱特，一位正直的人，正在照顾那些被隔绝在银松森林南部格雷迈恩之墙外，无法进入避难所的绝望的洛丹伦难民。第二位是科马尔·维拉德，一位忠诚的丈夫，他不知疲倦地在湿地的危险沼泽中搜寻失踪妻子的踪迹。对于被遗忘者术士来说，他们的奉献、同理心和忠诚使他们成为了绝佳的祭品。"},{t="被遗忘者的视角",b="执行狩猎任务需要术士穿越危险的联盟领地和荒野，最终屠杀这两名男子。当把血淋淋的战利品带回诅咒神殿时，凯伦丁·哈加尔带着阴暗的讽刺观察道，好人的器官外表看起来与普通尸体的残骸并无二致。然而，在恶魔学的黑暗艺术中，附着在他们血肉上的精神纯洁性足以引诱魅魔落入囚笼。"}},faq={{q="为什么术士需要纯洁的心来召唤魅魔？",a="魅魔以腐蚀凡人的纯真和美德为食。为了将她引诱出虚空并困在束缚法阵中，凯伦丁·哈加尔需要她无法抗拒的诱饵。那些真正纯洁无私的人的心灵，提供了这种不可抗拒的精神诱惑。",al={"为什么需要纯洁之心","魅魔诱饵传说","为什么要杀达林和科马尔"}},{q="达林·福杰莱特是谁？",a="达林·福杰莱特是一位正直的人类，骑马在银松森林南部的格雷迈恩之墙紧闭的大门沿线巡逻。他毕生致力于照顾和保护那些被吉尔尼斯王国拒绝和排斥的洛丹伦流离失所的难民。",al={"达林·福杰莱特背景故事","达林是谁","格雷迈恩之墙的那个人"}},{q="科马尔·维拉德是谁？",a="科马尔·维拉德是一位虔诚的人类流浪者，在萨多尔大桥南侧的湿地北路搜寻。与普通的旅行者不同，他完全是被悲伤和坚定不移的爱所驱使，拒绝放弃寻找他失踪的妻子。",al={"科马尔·维拉德背景故事","科马尔是谁","湿地人类之心"}},{q="这条任务链通向哪里？",a="将两颗心交给凯伦丁·哈加尔，他就能在诅咒神殿准备召唤法阵。这会立即触发“束缚”，术士将在其中召唤并征服一名魅魔作为永久的仆从。",al={"what comes next","纯洁之心任务之后","魅魔任务奖励"}},{q="谁发布了这个任务？",a="位于幽暗城Magic Quarter的诅咒神殿内的一名助手，高德瑞克·法杉发布了这项任务。他投射出达林和科马尔的魔法幻象，向术士展示确切的狩猎目标。",al={"谁开启了纯洁之心任务","高德瑞克·法杉任务"}},{q="为什么凯伦丁·哈加尔对心的外表不以为然？",a="在完成任务后，凯伦丁冷漠地指出，好人的肉体心脏看起来几乎与任何其他血肉没有任何区别。作为一名不死族的黑暗艺术修行者，对他而言，道德的物理层面除了作为魔法试剂的用途外，几乎毫无意义。",al={"凯伦丁对话","心脏外观"}}},fx={["4332c870"]={q="高德瑞克·法杉为什么要收集这些心脏？",a="高德瑞克协助凯伦丁·哈加尔训练有资格的被遗忘者术士。要召唤并支配魅魔，哈加尔需要稀有的媒介——具体来说，是品德高尚、真正纯洁的男子之心，它们能诱使擅长诱惑的恶魔进入束缚法阵。高德瑞克找到了合适的目标，让你收取他们的心脏，以证明你的黑暗技艺。",al={"高德瑞克为什么需要心脏","高德瑞克·法杉的目的","为什么要收取纯洁之心"}}},fp="18,365,16.415.0,10.449.0,22.470.1,54.268.0,25.283.0,21.250.0,33.240.1,21.215.0,62.282.0"}
P.entries["quest:1478"] = {n="哈加尔的召唤",s="“哈加尔的召唤”是发给那些在黑暗技艺上达到关键门槛的被遗忘者术士学员的一项正式指令。凯伦丁·哈加尔大师要求他们前往幽暗城的Magic Quarter，以开始严苛的高阶训练。响应他的召唤，便意味着要开始从虚空领域召唤并束缚危险的实体。",h="“哈加尔的召唤”是发给那些在黑暗技艺上达到关键门槛的被遗忘者术士学员的一项正式指令。凯伦丁·哈加尔大师要求他们前往幽暗城的Magic...",kw={"埃格隆·卡加尔","凯伦丁·哈加尔","哈加尔的召唤","magic quarter","诅咒神庙","幽暗城","虚空行者","术士"},ang={["class:Warlock"]="这一通过仪式架起了从基础训练到真正位面奴役的桥梁，使你处于幽暗城最顶尖的黑暗技艺大师的审视之下。",["race:Undead"]="被遗忘者术士以冷酷无情、肆无忌惮的野心追求暗影和邪能，而哈加尔的圣所正是他们对生者那种谨慎态度的务实摒弃的典范。"},sec={{t="大师的通知",b="当一名在布瑞尔或提瑞斯法林地活动的术士展现出对基础邪能的足够掌控力时，消息便会传达到幽暗城更深处的地下大厅。像埃格隆·卡加尔这样的资深从业者会担任人才选拔官，将通知传达给那些展现出真正潜力的学员。能够得到凯伦丁·哈加尔的召唤既是一种难得的殊荣，也是一项危险的重任，这表明基础的小鬼和低级的诅咒对于该学员的教育来说已不再足够。"},{t="Magic Quarter",b="哈加尔在Magic Quarter的阴影深处监督术士的仪式，该区域位于被称为诅咒神庙的邪恶祭坛附近。被遗忘者黑暗施法者们在行动时不会受到生者那种谨小慎微的道德束缚，但即使是他们，在涉足位面召唤时也要求严苛的纪律。哈加尔容不得迟疑或情感用事；他的召唤意味着绝对的服从，以及做好随时面对扭曲虚空中敌对恐怖的万全准备。"}},faq={{q="凯伦丁·哈加尔是谁？",a="凯伦丁·哈加尔是居住在幽暗城Magic Quarter的主要术士训练师。他监督着被遗忘者召唤师的黑暗成长，并在教导他们束缚强大的虚空生物之前测试他们的决心。",al={"凯伦丁·哈加尔","哈加尔大师","哈加尔是谁"}},{q="谁指引我去找哈加尔？",a="在收到哈加尔大师对你的成长产生个人兴趣的消息后，驻扎在布瑞尔的资深术士训练师埃格隆·卡加尔会派你前去报道。",al={"谁发出的哈加尔的召唤","埃格隆·卡加尔","谁发布任务"}},{q="我在幽暗城的哪里可以找到凯伦丁·哈加尔？",a="哈加尔位于幽暗城的Magic Quarter，靠近被称为诅咒神庙的黑暗祭坛。",al={"哈加尔位置","哈加尔在哪","magic quarter哈加尔"}},{q="为什么这个召唤很重要？",a="这次召唤标志着你从初级施法向高风险恶魔奴役的转变，特别是启动了将虚空行者束缚为你仆从所需的试炼。",al={"为什么需要这个任务","任务目的","哈加尔的召唤会带来什么"}},{q="哈加尔愿意教导任何人吗？",a="哈加尔特别关注那些有前途的术士。他不会在无谓的寒暄上浪费时间，并要求任何被带到他面前的学徒都必须证明自己有能力驾驭不稳定的邪能技艺。",al={"谁都能和哈加尔交谈吗","哈加尔的要求"}},{q="向哈加尔报到后会发生什么？",a="一旦你向哈加尔报到，他会立即通过分配任务来测试你的魔法能力，你需要获取召唤并束缚一个异界暗影爪牙所需的组件。",al={"what comes next","哈加尔的召唤之后"}}},fx={["169af240"]={q="埃格隆·卡加尔为什么让你去找凯伦丁·哈加尔？",a="埃格隆·卡加尔在布瑞尔担任术士导师，但你日益精进的技艺需要更高深的指导，村里的导师无法满足。当凯伦丁·哈加尔大师亲自传讯召你前往时，埃格隆便恭敬地指引你前往幽暗城。对埃格隆而言，指引有前途的术士更进一步，既能增强被遗忘者的黑暗技艺，也能维护魔法区术士之间的传承秩序。",al={"埃格隆·卡加尔的目的","为什么派我去找哈加尔","埃格隆为什么要我做这件事"}},be0d43df={q="凯伦丁·哈加尔为什么专门召见你？",a="凯伦丁·哈加尔很少主动指导普通的新手。你在提瑞斯法林地证明了自己对黑暗技艺的天赋，如今已达到技艺上的关键阶段，基础法术不再足够。哈加尔直接召见你，是因为开启更深奥、更不稳定的力量——例如深入扭曲虚空、号令更强大的恶魔——需要真正的大师亲自监督。",al={"哈加尔为什么需要我","哈加尔为什么召见我","为什么召见我"}}},fp="16,349,17.484.0,17.481.0,23.229.0,25.171.0,46.129.0,30.181.0,34.208.0,39.177.0"}
P.entries["quest:148"] = {n="来自夜色镇的货物",s="“夜色镇的补给”是暮色森林中的一个联盟任务，隐士亚伯克隆比会请求过往的旅行者替他去夜色镇跑趟腿。他声称自己太过虚弱，无法在闹鬼的森林中进行危险的长途跋涉，因此想从伊瓦夫人那里寻求一种名为“幽灵的发丝”的稀有材料。",h="“夜色镇的补给”是暮色森林中的一个联盟任务，隐士亚伯克隆比会请求过往的旅行者替他去夜色镇跑趟腿。他声称自己太过虚弱，无法在闹鬼的森林中进行危险的长途跋涉，因此想从伊瓦夫人那里寻求一种名为“幽灵的发丝”的稀有材料。",kw={"亚伯克隆比","夜色镇","暮色森林","幽灵的发丝","伊瓦夫人","夜色镇的补给","隐士"},ang={["faction:Alliance"]="寻求帮助饱受困扰的夜色镇定居点的联盟冒险者们，常常会发现自己在为住在危险小路旁的隐士们跑腿。",["profession:Tailoring"]="纺织品通常依赖亚麻或丝绸，这使得伊瓦夫人将虚空之发纺成线的技艺对任何裁缝来说都显得既怪异又好奇。"},sec={{t="虚弱的请求",b="隐士亚伯克隆比独自居住在暮色森林西部乌鸦岭墓地北边的一间小屋里，显得十分可怜。当旅行者靠近时，他会哀叹自己年事已高、身体虚弱，声称无法在穿越森林前往夜色镇购买物资的旅途中存活下来。他请求跑腿的事情看起来很简单：回到镇上的广场，与伊瓦夫人交谈，去获取一卷幽灵的发丝。"},{t="奇怪的材料",b="找到伊瓦夫人后就会发现，亚伯克隆比的要求绝非普通的缝纫用品。伊瓦夫人是当地的占卜师，也是奇特手工艺品的纺织者，她的库存里并没有现成的幽灵的发丝。要完成这位隐士的差事，就需要从盲眼玛丽那里获取幽灵发丝。盲眼玛丽是一个徘徊在夜色镇南边一座农舍里的悲伤幽灵，这次简单的跑腿任务标志着一个更为邪恶的阴谋的开始。"}},faq={{q="谁发布了“夜色镇的补给”这个任务？",a="该任务由亚伯克隆比发布，他是一位住在暮色森林西部乌鸦岭墓地北边一间孤零零小屋里的隐士。",al={"夜色镇的补给任务发布者","谁开启夜色镇的补给","亚伯克隆比跑腿"}},{q="我在夜色镇应该找谁获取补给？",a="你必须与伊瓦夫人交谈，她住在夜色镇中心广场旁的一间屋子里。",al={"夜色镇的补给在哪里交任务","夜色镇的补给交任务","伊瓦夫人位置"}},{q="亚伯克隆比具体想要什么物品？",a="亚伯克隆比索要的是幽灵的发丝，这是一种由伊瓦夫人纺织的、不同寻常且令人毛骨悚然的材料。",al={"亚伯克隆比想要什么","什么是补给品","亚伯克隆比物品"}},{q="伊瓦夫人有现成的幽灵的发丝吗？",a="没有，当你到达时，伊瓦夫人的库存里并没有这种材料。她同意为你纺织，但前提是你必须从附近的灵魂那里收集她所需要的灵质材料。",al={"伊瓦夫人有线吗","完成夜色镇的补给"}},{q="“夜色镇的补给”的前置任务是什么？",a="前置任务是“隐士”，该任务指引冒险者离开夜色镇，去寻找住在偏僻住所里的亚伯克隆比。",al={"夜色镇的补给前置任务","夜色镇的补给前置"}},{q="“夜色镇的补给”的后续任务是什么？",a="完成与伊瓦夫人的这段对话后，会立即接到任务“幽灵的发丝”，任务要求你将鬼梳带给幽灵盲眼玛丽，以收集她的头发。",al={"夜色镇的补给后续任务","夜色镇的补给后续"}}},fx={b4c47635={q="亚伯克隆比为什么需要夜色镇的补给？",a="亚伯克隆比声称自己只是个贫困体弱的老人，独自住在危险的暮色森林荒野中，无法长途跋涉进镇。他特意索要幽灵的发丝，据称是想从伊瓦夫人那里买些日常裁缝用品，以维持自己在林中的独居生活。",al={"为什么要去夜色镇拿补给","亚伯克隆比为什么需要线","亚伯克隆比的幽灵的发丝"}},["2d5a916c"]={q="亚伯克隆比为什么让你去拿线，而不是自己去？",a="亚伯克隆比恳求说，他年纪太大、身体太虚弱，无法冒险走过小屋与夜色镇之间闹鬼且遍布野兽的道路。让一名健壮的旅人替他穿过阴森荒野，是他从伊瓦夫人那里取得所需材料的唯一办法。",al={"亚伯克隆比为什么不能进镇","为什么让我去拿夜色镇的补给","亚伯克隆比为什么不自己拿补给"}}},fp="23,302,16.421.0,18.427.1,45.118.0,53.99.0,46.92.0,49.157.0,44.130.0,43.182.0"}
P.entries["quest:1480"] = {n="堕落者",s="一块被剥下的恶魔皮肤，是从雷斧堡垒的火刃氏族那里得来的，闻起来很腐臭，但却出奇地柔韧。一面覆盖着某种文字的红色标记，底部有一个清晰的符号，看起来像是个签名。幽灵岗哨的玛乌林·碎骨或许能告诉你更多信息。",h="一块被剥下的恶魔皮肤，是从雷斧堡垒的火刃氏族那里得来的，闻起来很腐臭，但却出奇地柔韧。一面覆盖着某种文字的红色标记，底部有一个清晰的符号，看起来像是个签名。幽灵岗哨的玛乌林·碎骨或许能告诉你更多信息。",kw={"火刃氏族","艾瑞达语","剥下的恶魔皮肤","幽灵岗哨","阿兹雷索克领主","玛乌林·碎骨","堕落者","雷斧堡垒"},sec={{t="一块皮",b="这块撕下的皮肤散发着腐烂的臭味，但却很容易弯曲，尽管看起来又干又脆。展开后，上面一面印有红色的标记，这是一种文字。底部有一个明显的符号，你认为那是一个签名。"},{t="玛乌林的看法",b="幽灵岗哨的玛乌林·碎骨可能对这块皮肤有更多了解。玛乌林认为火刃氏族很快就会明白自己有多么软弱，他们的魔法拙劣，力量微薄。他们所拥有的任何力量都来自于他们所效忠的主子，而不是源于对真实力量和知识的掌握。"},{t="这些标记的含义",b="玛乌林认出这些符文是一种古老的语言，有点像艾瑞达语，但在细节上却大不相同。如果玛乌林说得没错，这块皮肤是一份某种契约，而底部的符号就是恶魔阿兹雷索克领主的签名。"}},faq={{q="被剥下的皮肤上写了什么？",a="一面覆盖着红色的标记，这是一种文字。底部有一个清晰的符号，看起来像是一个签名。幽灵岗哨的玛乌林·碎骨或许了解更多。",al={"剥下的皮肤符文","皮肤上写着什么","皮肤上的红色标记"}},{q="这块皮肤是从哪里来的？",a="它是从凄凉之地的雷斧堡垒的火刃氏族那里夺来的。",al={"皮肤位置","在哪里获得恶魔皮肤","如何开始堕落者任务"}},{q="玛乌林·碎骨是谁？",a="玛乌林·碎骨位于凄凉之地的幽灵岗哨，你需要把皮肤带到那里。",al={"玛乌林在哪里","玛乌林·碎骨位置","玛乌林是谁"}},{q="玛乌林是怎么看火刃氏族的？",a="玛乌林认为他们很软弱，魔法拙劣，力量微薄。依他看来，他们所拥有的任何力量都来自于他们所效忠的对象。",al={"玛乌林 火刃氏族","火刃氏族的力量"}}},fp="13,308,15.229.0,13.282.0,22.233.1,35.179.0,30.71.0,27.95.0,44.130.0"}
P.entries["quest:1481"] = {n="堕落者",s="玛乌林·碎骨相信那个恶魔领主是可以被找到的，但首先必须打破它所持有的反侦测结界。为此，玛乌林想要一个怒火暗影追踪者的头皮，可以在凄凉之地东北部的古老废墟中猎取。",h="玛乌林·碎骨相信那个恶魔领主是可以被找到的，但首先必须打破它所持有的反侦测结界。为此，玛乌林想要一个怒火暗影追踪者的头皮，可以在凄凉之地东北部的古老废墟中猎取。",kw={"凄凉之地","怒火暗影追踪者","玛乌林·碎骨","萨格隆","萨特","侦测","暗影追踪者头皮","腐蚀者"},sec={{t="打破结界",b="玛乌林·碎骨相信，只要有合适的试剂，就可以找到那个恶魔领主。如果那位领主正如玛乌林所怀疑的那样强大，那么试剂必须来自致命的生物。玛乌林确信，你作为大酋长的代表，定会接受这项挑战。首要任务是打破恶魔的反侦测结界。为此，玛乌林需要一个萨特头皮，不过只有怒火暗影追踪者的头皮才行。你可以在萨格隆附近的凄凉之地东北部的古老废墟中寻找它们。"},{t="正确的头皮",b="玛乌林告诫你不要带回错误的头皮。错误的试剂可能会导致人员伤亡，因为那位恶魔领主身上可能带有预设的应急法术，旨在杀死任何试图侦测他的人。玛乌林补充说，命运带来的痛苦已经够多了。"},{t="当你归来时",b="玛乌林认为这个头皮非常适合他的法术。在你离开的时候，他已经收集了一些所需的其他试剂，并且准备工作即将完成。他现在只缺少一个法术焦点，即一个可以投射出恶魔领主影像并标示其方位的媒介。"}},faq={{q="是谁派你去收集头皮的？",a="玛乌林·碎骨要的，为了施展寻找恶魔领主的法术。",al={"任务发布者","谁发起的任务","玛乌林·碎骨"}},{q="为什么玛乌林特别需要怒火暗影追踪者的头皮？",a="必须首先打破恶魔领主所设下的任何反侦测结界。为此，玛乌林需要一个萨特的头皮，而且只有怒火暗影追踪者的才行。",al={"为什么要暗影追踪者头皮","萨特头皮的用途","为什么是萨特"}},{q="在哪里可以找到怒火暗影追踪者？",a="在凄凉之地东北部的古老废墟中，萨格隆附近。",al={"暗影追踪者在哪里","暗影追踪者位置","萨特位置"}},{q="使用错误的试剂会有什么危险？",a="玛乌林警告说，错误的试剂可能会导致死亡。恶魔领主身上可能带有旨在杀死任何试图侦测他的人的应急法术。",al={"为什么需要正确的头皮","错误试剂的风险","应急法术"}},{q="这一步在寻找恶魔领的过程中处于什么位置？",a="这是《腐蚀者》的第一部分之后，当时你把剥下的恶魔皮交给了玛乌林。",al={"任务线进度","任务顺序","之前的任务"}}},fp="13,239,18.495.0,15.256.0,15.221.1,34.68.0,65.155.0,47.56.0,49.147.0,60.93.0"}
P.entries["quest:1482"] = {n="堕落者",s="玛乌林·碎骨想要一个神谕水晶，这是纳迦为他们的神谕者制作的，目的是找到恶魔领主Azrethoc。西北方的海岸沿线有一片巨大的珊瑚礁，那里是滑刃纳迦的家园，他们可不会欢迎你。",h="玛乌林·碎骨想要一个神谕水晶，这是纳迦为他们的神谕者制作的，目的是找到恶魔领主Azrethoc。西北方的海岸沿线有一片巨大的珊瑚礁，那里是滑刃纳迦的家园，他们可不会欢迎你。",kw={"azrethoc","腐蚀者","凄凉之地","玛乌林·碎骨","纳迦","神谕水晶","滑刃","大酋长"},sec={{t="神谕水晶",b="玛乌林·碎骨说，神谕水晶足以帮他找到恶魔领主Azrethoc，你带来的那张皮上就有他的签名。纳迦会制作这种水晶，他们的神谕者也会使用。沿着海岸向西北方走，那里有一片巨大的珊瑚礁，纳迦在靠近岸边时便以此为家，而神谕者就在那里。那里的滑刃纳迦非常致命，他们不会欢迎你的入侵，所以玛乌林催促你务必小心行事，迅速行动。"},{t="共同的奖赏",b="玛乌林指出，找到并消灭Azrethoc领主能让你们俩都赢得大酋长的青睐。通力合作，迅速行动，对双方都有好处。"}},faq={{q="为什么玛乌林·碎骨需要神谕水晶？",a="他打算以此找到恶魔领主Azrethoc，而神谕水晶就是他实现这一目标的所需之物。",al={"为什么需要神谕水晶","水晶的用途","玛乌林的水晶目标"}},{q="在哪里可以找到神谕水晶？",a="纳迦会为自己的神谕者制作水晶，而这些神谕者就在玛乌林西北方、海岸沿线的那片巨大珊瑚礁里。",al={"去哪里找水晶","神谕水晶位置","滑刃神谕者在哪里"}},{q="滑刃纳迦是什么人？",a="他们是纳迦，在靠近岸边的一片巨大珊瑚礁里安了家。玛乌林称他们非常致命，并说他们绝不会欢迎入侵者。",al={"滑刃是什么","滑刃纳迦","谁住在珊瑚礁里"}},{q="Azrethoc是谁？",a="Azrethoc是那个在皮上留下签名的恶魔领主，那张皮是你带给玛乌林的。玛乌林想要找到并消灭他。",al={"azrethoc是谁","恶魔领主azrethoc","玛乌林在狩猎什么恶魔"}},{q="玛乌林狩猎这个恶魔的动机是什么？",a="玛乌林说，找到并消灭Azrethoc领主能让你们俩都赢得大酋长的青睐。",al={"玛乌林的动机","为什么要狩猎azrethoc","大酋长的青睐"}}},fp="13,238,17.467.0,14.173.0,52.93.0,36.124.0,25.138.0,16.116.0,41.101.0"}
P.entries["quest:1483"] = {n="菲兹克斯",s="这个任务将旅行者从棘齿城派去查看齐兹·菲兹克斯，一位驻扎在狂风峭壁西侧山脊上的不满的地精工程师。当荆棘谷地精雇佣了一名侏儒工程师取代他时，他感到被冒犯了，于是投奔了在斯布特瓦夫苛刻指导下的修补匠工会。",h="这个任务将旅行者从棘齿城派去查看齐兹·菲兹克斯，一位驻扎在狂风峭壁西侧山脊上的不满的地精工程师。当荆棘谷地精雇佣了一名侏儒工程师取代他时，他感到被冒犯了，于是投奔了在斯布特瓦夫苛刻指导下的修补匠工会。",kw={"格伦佐·扳手哨","斯布特瓦夫","石爪山脉","修补匠工会","荆棘谷地精","狂风峭壁","齐兹·菲兹克斯"},ang={["faction:Horde"]="在石爪山脉活动的部落冒险者经常协助像斯布特瓦夫和齐兹这样的修补匠工会特工，以破坏荆棘谷地精在狂风峭壁的统治地位。",["profession:Engineering"]="齐兹和格伦佐之间激烈的恩怨完美地反映了地精和侏儒工程学理念之间长期存在的、不稳定的竞争关系。"},sec={{t="职业尊严问题",b="荆棘谷地精依赖残酷的剥削和机械创新，但当他们带来了一名名叫格伦佐·扳手哨（Gerenzo Wrenchwhistle）的侏儒工程师时，这触及了齐兹·菲兹克斯的底线。齐兹因不得不与侏儒竞争对手共事而深受侮辱，他立即寻找出路。他联系了代表修补匠工会的联络人斯布特瓦夫，恳求调离格伦佐的监管。"},{t="逃离煎锅",b="在修补匠工会获得新职位并没有给齐兹带来他预期的轻松生活。驻扎在狂风峭壁的西缘，他很快发现斯布特瓦夫和任何荆棘谷地精的工头一样，都是个压榨工人的监工。尽管如此，齐兹认为在苛刻的地精上司手下从事繁重的劳动，远比与一个侏儒共用一个工程车间要好得多。"}},faq={{q="齐兹·菲兹克斯是谁？",a="齐兹·菲兹克斯是一位地精工程师，曾受雇于石爪山脉的荆棘谷地精。在以前的雇主雇佣了一名侏儒工程师后，他投奔了修补匠工会。",al={"谁是齐兹","齐兹·菲兹克斯npc","关于齐兹·菲兹克斯"}},{q="齐兹·菲兹克斯为什么要离开荆棘谷地精？",a="在荆棘谷地精雇佣了侏儒工程师格伦佐·扳手哨后，他以罢工抗议。齐兹拒绝与侏儒竞争对手共事，请求斯布特瓦夫为他提供新的工作。",al={"齐兹为何辞职","为何离开荆棘谷地精","齐兹与荆棘谷地精"}},{q="在哪里可以找到齐兹·菲兹克斯？",a="他位于石爪山脉的狂风峭壁西缘，俯瞰着荆棘谷地精的伐木和挖掘作业。",al={"齐兹·菲兹克斯位置","齐兹在哪里","寻找齐兹·菲兹克斯"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是修补匠工会的一名地精特工，他从荆棘谷地精那里挖走熟练的工程师，让他们从事竞争性项目。",al={"谁是斯布特瓦夫","斯布特瓦夫的角色"}},{q="格伦佐·扳手哨是谁？",a="格伦佐是荆棘谷地精带到狂风峭壁的侏儒工程师，这一任命激怒了齐兹，并引发了激烈的职业竞争。",al={"格伦佐·扳手哨","谁是那个侏儒工程师"}},{q="什么是修补匠工会？",a="修补匠工会是一个成熟的地精工程贸易协会。他们积极与荆棘谷地精等竞争对手展开竞争，并尽可能招募或收回顶尖人才。",al={"修补匠工会","地精修补匠工会"}}},fx={["39c75067"]={q="斯布特瓦夫为什么要你去查看 Ziz Fizziks 的情况？",a="荆棘谷地精公司经常挖走优秀的地精人才，但当 Ziz 因公司雇用了一名地精对手而愤然辞职时，斯布特瓦夫抓住机会，想把这名工程师争取回来。如今，作为技师工会的代表，斯布特瓦夫立刻派 Ziz 去狂风峭壁工作。他想确认新招揽的技工确实有所作为，而不是独自在险境中一筹莫展。",al={"为什么要去查看 ziz fizziks","斯布特瓦夫的目的","为什么派我去找 ziz"}}},fp="11,288,30.405.0,21.383.0,19.190.0,46.185.0,31.150.0,20.176.0,29.153.0,27.186.0"}
P.entries["quest:1484"] = {n="堕落者",s="玛乌林·碎骨发现那个恶魔领主比预想的要危险得多。他肯定塔卡塔·钢刃在怀疑他的能力，如果让这位剑士对刚才发生的事一无所知，那就是对塔卡塔荣誉的侮辱。玛乌林让你去和就在附近的塔卡塔谈谈。",h="玛乌林·碎骨发现那个恶魔领主比预想的要危险得多。他肯定塔卡塔·钢刃在怀疑他的能力，如果让这位剑士对刚才发生的事一无所知，那就是对塔卡塔荣誉的侮辱。玛乌林让你去和就在附近的塔卡塔谈谈。",kw={"恶魔领主","凄凉之地","科多兽坟场","玛乌林·碎骨","剑士","塔卡塔·钢刃","腐蚀者"},sec={{t="荣誉问题",b="玛乌林·碎骨发现那个生物比他预想的要危险得多。毫无疑问，塔卡塔·钢刃在质疑玛乌林是否能对付它，如果不告诉他刚才发生了什么，那就是对塔卡塔荣誉的侮辱。玛乌林让你去和这位剑士谈谈，如果塔卡塔允许的话，主动提出去击杀那个恶魔。玛乌林告诫你不要逼塔卡塔太紧，最好让他以为这主意是他自己想出来的。"},{t="路对面",b="塔卡塔·钢刃就在附近，就在玛乌林的路对面，一处俯瞰科多兽坟场的悬崖上。"},{t="塔卡塔的答复",b="塔卡塔目睹了玛乌林和恶魔领主之间发生的一切。即使只是一个幻影，那个生物似乎也比塔卡塔的术士同伴玛乌林拥有更强大的力量，塔卡塔怀疑玛乌林是否能击败它。如果塔卡塔亲自前往，对大酋长更有利，但塔卡塔在此处的职责让他无法仅仅为了个人荣誉而离开去对抗这个邪恶，那样会使氏族蒙羞。"}},faq={{q="为什么玛乌林·碎骨想让塔卡塔·钢刃知道这件事？",a="玛乌林发现恶魔领主远比他预想的危险。他肯定塔卡塔在怀疑他的能力，如果让这位剑士对刚才发生的事一无所知，那就是对塔卡塔荣誉的侮辱。",al={"为什么要和塔卡塔谈话","玛乌林·碎骨的理由","为什么要告诉塔卡塔"}},{q="塔卡塔·钢刃在哪里？",a="就在附近，在凄凉之地科多兽坟场上方的一处悬崖上，路对面就是玛乌林。",al={"塔卡塔的位置","塔卡塔在哪里","寻找塔卡塔·钢刃"}},{q="为什么玛乌林建议不要逼塔卡塔太紧？",a="玛乌林想让你在不强迫的情况下，提议去击杀恶魔，前提是塔卡塔允许。如果塔卡塔认为这主意是他自己想出来的，那就最好不过了。",al={"为什么不能逼迫塔卡塔","应对塔卡塔","塔卡塔的自尊"}}},fp="13,269,17.424.0,15.112.0,15.395.1,57.190.0,35.98.0,56.141.0"}
P.entries["quest:1485"] = {n="邪灵劣魔",s="在试炼谷干旱的山谷中，术士训练师鲁赞要求黑暗艺术的追求者们证明他们有能力对抗邪恶的魔仆。为了获得召唤恶魔的知识，新手们必须在战斗中面对这些小鬼般的生物，并取回它们的首级。这标志着在部落的注视下，他们掌握邪能迈出了谦卑而危险的第一步。",h="在试炼谷干旱的山谷中，术士训练师鲁赞要求黑暗艺术的追求者们证明他们有能力对抗邪恶的魔仆。为了获得召唤恶魔的知识，新手们必须在战斗中面对这些小鬼般的生物，并取回它们的首级。这标志着在部落的注视下，他们掌握邪能迈出了谦卑而危...",kw={"火刃集会所","杜隆塔尔","小鬼","鲁赞","大兽穴","试炼谷","邪恶的魔仆","术士"},ang={["class:Warlock"]="这次试炼标志着你作为术士的首次成人礼，证明了你在进行召唤小鬼的仪式之前，有能力制服恶魔之火。",["faction:Horde"]="虽然部落允许术士在杜隆塔尔进行训练，但他们的黑暗艺术被严格限制在大兽穴等偏僻区域内。",["race:Orc"]="兽人术士每天都必须面对他们民族的黑暗历史，在一个铭记着邪能腐蚀恐怖记忆的社会中证明自己的控制力和忠诚。"},sec={{t="在部落中尴尬的地位",b="术士在萨尔新组建的部落中地位尴尬。曾经给兽人种族带来毁灭的恶魔腐蚀和鲜血契约留下了深刻的伤痕和挥之不去的猜忌。尽管杜隆塔尔容忍了邪能的使用者，但他们既不受欢迎，也不被广泛接纳。许多术士选择在大兽穴这样阴暗的角落过着隐居的生活，远离窥探的目光练习法术，同时教导那些敢于踏上这条道路的少数新手。"},{t="精通的试炼",b="在传授学徒屈服小鬼所需的危险仪式之前，鲁赞要求看到支配力的证明。在大兽穴东北方向的一个洞穴附近，邪恶的魔仆潜伏着，并向任何靠近的人投掷火焰箭。通过击杀这些低阶恶魔并取回它们的首级，新手证明了他们能够压制住自己试图控制的火热对手，从而确保他们不会被自己想要掌控的魔法所吞噬。"}},faq={{q="鲁赞为什么要派遣术士去对抗邪恶的魔仆？",a="鲁赞要求新手面对邪恶的魔仆，是为了让他们在尝试召唤小鬼之前，先了解小鬼的火热本性和危险性。由于术士人数稀少且不受信任，他拒绝在学徒证明自己能在直接战斗中胜过这些生物之前，就冒险传授召唤恶魔的艺术。",al={"为什么要杀邪恶的魔仆","鲁赞的测试","小鬼试炼"}},{q="邪恶的魔仆在哪里？",a="它们聚集在试炼谷大兽穴东北方的一个洞穴周围和洞内，在那里的游荡野猪和蝎群之外。这个洞穴是邪恶的火刃集会所的营地。",al={"邪恶的魔仆位置","魔仆在哪里","鲁赞的洞穴"}},{q="部落如何看待杜隆塔尔的术士？",a="由于曾经腐蚀过兽人人民的恶魔历史，整个部落对术士都怀有深深的怀疑和不信任。虽然萨尔的政府容忍了他们的存在，并认可了他们的战斗效用，但仍与他们保持距离，这导致许多术士过着孤独的生活。",al={"术士被憎恨吗","部落术士背景","为什么不信任术士"}},{q="完成这个试炼有什么奖励？",a="击杀这些生物并将它们的首级交给鲁赞，证明了你拥有掌控恶魔所需的纪律和力量，这将直接引导你学习如何召唤小鬼仆从。",al={"我能学到什么","鲁赞的任务奖励","小鬼法术"}},{q="邪恶的魔仆是真正的恶魔吗？",a="是的，邪恶的魔仆是与邪能有关的小型恶魔小鬼。虽然身材矮小，但它们是强大的对手，能够向敌人投掷火球。",al={"什么是邪恶的魔仆","魔仆是小鬼吗","魔仆的恶魔类型"}},{q="鲁赞是谁？",a="鲁赞是一位驻扎在试炼谷大兽穴内的兽人术士训练师。他指导新晋兽人术士如何安全地利用邪能并控制召唤的仆从。",al={"鲁赞","鲁赞是谁","试炼谷术士"}}},fx={["2f864f20"]={q="邪灵劣魔的头颅有什么用？",a="鲁赞需要这些头颅作为你在战斗中战胜那些生物的实物证明。选择术士之路的新手寥寥无几，因此在你证明自己拥有支配恶魔的力量与意志之前，他不会教你危险的恶魔召唤术。",al={"邪灵劣魔的头颅用途","为什么要收集邪灵劣魔的头颅","鲁赞与邪灵劣魔的头颅"}},["58d905b2"]={q="邪灵劣魔为什么会出现在试炼谷？",a="这些凶残、形似小鬼的生物聚集在大兽穴东北方的一处洞穴周围，那里被称为火刃集会所。它们或是被腐化的魔法吸引而来，或是受潜伏的邪教徒驱使，成为初出茅庐的术士检验决心、对抗低等恶魔仆从的致命试炼。",al={"邪灵劣魔为什么会在这里","试炼谷的邪灵劣魔","邪灵劣魔所在的洞穴"}},cca9ea14={q="鲁赞为什么派你去，而不亲自处理这些劣魔？",a="这是对个人掌控力的试炼，不是公共防务任务。若由鲁赞或步兵赶走劣魔，你便学不到任何东西。若一名术士无法在正面战斗中压制一个低等恶魔，那么他一旦尝试召唤恶魔，必然会被吞噬或毁灭。",al={"鲁赞为什么不杀掉它们","鲁赞为什么派我去","鲁赞为什么考验我"}}},fp="14,398,31.472.0,20.441.0,53.326.0,35.202.0,44.315.0,45.197.0,33.174.0,13.180.0"}
P.entries["quest:1486"] = {n="变异皮革",s="“变异皮革”是纳尔帕克发布的一项任务，他是纳拉雷克斯的学徒，驻扎在哀嚎洞穴的入口上方。当纳拉雷克斯被困在扭曲的梦魇中时，纳尔帕克试图从贫瘠之地地下滋生的变异野兽身上寻找有用的东西。通过收集这些变异掠食者的兽皮，他希望将它们奇怪的、超自然特性用于实际用途。",h="“变异皮革”是纳尔帕克发布的一项任务，他是纳拉雷克斯的学徒，驻扎在哀嚎洞穴的入口上方。当纳拉雷克斯被困在扭曲的梦魇中时，纳尔帕克试图从贫瘠之地地下滋生的变异野兽身上寻找有用的东西。通过收集这些变异掠食者的兽皮，他希望将它...",kw={"贫瘠之地","变异","变异皮革","翡翠梦魇","制皮","纳尔帕克","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="纳尔帕克的营地代表了幸存的学徒们对一项彻底失败的计划所进行的严峻守望，这使得遏制洞穴变异的任务对德鲁伊同伴来说具有个人的意义。",["profession:Herbalism"]="喂养变异野兽的异常生长直接与蜿蜒穿过洞穴网络的腐化植物群和地下泉水有关。"},sec={{t="腐蚀的显现",b="当暗夜精灵德鲁伊纳拉雷克斯试图利用贫瘠之地地下的泉水来恢复这片干旱平原的生机时，他的意识陷入了一个可怕的梦魇。那个黑暗的幻想渗入了现实，将哀嚎洞穴的原生野生动物变异成了凶猛的变异野兽。迅猛龙、鳄鱼、毒蛇和蹒跚的怪物在梦中主人的翡翠腐蚀影响下发生了扭曲，变得极具攻击性。"},{t="务实的德鲁伊",b="纳尔帕克栖身于洞穴口上方的岩石结构中，怀着恐惧和务实的好奇心注视着这场灾难。尽管他认识到这些变异生物本质上是恶性和不自然的，但他认为它们腐化的形态可能会产生独特的材料。特别是它们坚硬、扭曲的兽皮具有韧性，可以造福熟练的制皮师，从而将悲剧性梦魇的产物转化为耐用的装备。"}},faq={{q="我在哪里可以找到纳尔帕克？",a="Nalpak and his fellow disciples have established a small camp high up in the rock formation resembling a skull above the Wailing Caverns entrance. Rather than walking straight into the main tunnel, climb the mountain slopes behind the cave mouth and carefully drop down into the upper cavern eye-socket ledge overlooking the oasis.",al={"纳尔帕克位置","纳尔帕克在哪里","如何找到纳尔帕克","变异皮革任务发布者"}},{q="什么是变异生物？",a="变异生物是当地野兽受到从纳拉雷克斯沉睡意识中逃逸出来的翡翠梦魇的影响而转变的产物。贫瘠之地原生的迅猛龙、毒蛇、鳄鱼和翼蛇已被扭曲成更黑暗、更凶猛的形态，具有奇怪的魔法属性和斑驳、不自然的兽皮。",al={"什么是变异生物","变异野兽","为什么哀嚎洞穴里的动物会变异"}},{q="为什么纳尔帕克想要这些皮革？",a="纳尔帕克认识到，虽然这些野兽源于邪恶的腐蚀，但它们的皮革展现出不同寻常的、超自然的强度。他相信通过研究和加工这些皮革，制皮师可以将梦魇的污染转化为具有韧性的装备。",al={"为什么需要变异皮革","纳尔帕克想要皮革做什么","变异皮革的用途"}},{q="任何变异生物都会掉落这种皮革吗？",a="在哀嚎洞穴的隧道和内部出没的变异野兽身上带有这些兽皮。猎人和制皮师经常发现，剥皮获得的兽皮比单纯从遗骸中搜寻到的要多。",al={"哪些怪物掉落变异皮革","谁掉落变异皮革","变异皮革刷怪"}},{q="纳尔帕克是部落还是联盟阵营？",a="纳尔帕克是一位牛头人德鲁伊，也是纳拉雷克斯的学徒之一。他保持中立，并会接受任何有能力的冒险者的帮助，无论是联盟还是部落，只要他们有足够的勇气进入这些被腐蚀的洞穴。",al={"纳尔帕克是部落吗","变异皮革是联盟任务吗","联盟可以做变异皮革任务吗"}},{q="纳拉雷克斯发生了什么事？",a="纳拉雷克斯试图通过将他的意识连接到翡翠梦境来唤醒贫瘠之地的地下泉水。然而，他的沉睡被梦魇所控制，将洞穴系统变成了一个怪物滋生的温床，并使他昏迷在洞穴深处。",al={"谁是纳拉雷克斯","纳拉雷克斯梦魇","哀嚎洞穴里的德鲁伊发生了什么"}}},fx={["58e10be2"]={q="变异皮革有什么用？",a="变异皮革具有奇异的异界特性，源自侵蚀洞穴的梦魇。它们的来源生物虽然扭曲而凶恶，纳尔帕克却相信，可以通过制皮将这些异样的毛皮制成结实的护甲和背包，从腐化之中变出有用之物。",al={"变异皮革用途","为什么要收集变异皮革","变异皮革的用途"}}},fp="13,382,24.451.0,17.451.0,24.331.0,27.292.0,33.244.0,40.238.0,49.206.0,25.281.0"}
P.entries["quest:1487"] = {n="清除变异者",s="“清除变异者”是暗夜精灵德鲁伊厄布鲁在哀嚎洞穴入口上方布置的一项任务。当其他门徒专注于唤醒他们沉睡的领袖时，厄布鲁请求冒险者清理洞穴中因他扭曲的愿景而产生的变异生物。清除这些潜伏在地下绿洲的恐怖生物，对于阻止威胁贫瘠之地的腐化至关重要。",h="“清除变异者”是暗夜精灵德鲁伊厄布鲁在哀嚎洞穴入口上方布置的一项任务。当其他门徒专注于唤醒他们沉睡的领袖时，厄布鲁请求冒险者清理洞穴中因他扭曲的愿景而产生的变异生物。清除这些潜伏在地下绿洲的恐怖生物，对于阻止威胁贫瘠之地...",kw={"贫瘠之地","变异恐牙","清除变异者","变异掠夺者","变异蹒跚者","变异蝰蛇","厄布鲁","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="洞穴内扭曲的生态系统是一个令人忧心的警示，提醒着人们当与翡翠梦境的沟通演变成灾难时会发生什么。",["faction:Horde"]="由于哀嚎洞穴位于卡利姆多中心平原的核心地带，清理这些极具攻击性的掠食者对于保护十字路口等附近的定居点至关重要。",["race:NightElf"]="目睹纳拉雷克斯的高尚愿望崩溃为噩梦中诞生的恐怖，对于卡多雷旅行者来说是一个沉重的负担，他们感到有责任去帮助他们受困的族人。"},sec={{t="一个糟糕透顶的梦境",b="暗夜精灵德鲁伊纳拉雷克斯带着他的追随者来到贫瘠之地的地下泉水，怀揣着一个雄心勃勃的愿景：利用翡翠梦境的力量，将干涸的平原重新培育为郁郁葱葱、生机勃勃的林地。然而，纳拉雷克斯却陷入了梦境之中，他的沉睡变成了一场令人痛苦的噩梦。涌入洞穴的力量非但没有治愈这片土地，反而将当地的野生动植物扭曲成了怪物，即被称为变异生物的极具攻击性的突变体。"},{t="厄布鲁的立场",b="厄布鲁和少数幸存的纳拉雷克斯的门徒蜷缩在俯瞰洞穴入口的悬崖岩洞中，绝望地看着他们的人数不断减少。虽然他们中的一些人将精力投入到唤醒他们倒下的主人上，但厄布鲁意识到眼下存在严重的危机。如果放任不管，不断繁衍的变异蝰蛇、变异蹒跚者、变异掠夺者和变异恐牙将会涌入贫瘠之地。因此，厄布鲁招募路过的冒险者深入地下的隧道，从源头处扑杀这些变异怪物。"}},faq={{q="我在哪里可以找到厄布鲁来开始这个任务？",a="厄布鲁与几位纳拉雷克斯的门徒同伴驻扎在哀嚎洞穴主入口上方的一个隐蔽洞穴中，位于那块形似头骨的岩石结构右眼眶内。想要找到她，通常需要沿着山脊攀爬，然后小心地跳到上方的平台上。",al={"厄布鲁位置","厄布鲁在哪里","如何找到厄布鲁","哀嚎洞穴眼眶洞穴"}},{q="是什么导致这些野兽发生变异的？",a="这些生物是被从翡翠梦境中渗出的黑暗能量所突变的。当德鲁伊纳拉雷克斯将他的意识与地下泉水连接以复苏贫瘠之地时，他的心智被一场噩梦劫持，将原本的修复能量扭曲成了一种腐化力量，使当地的野生动物突变成了变异怪物。",al={"为什么它们会发生变异","变异生物起源","是什么腐化了哀嚎洞穴里的动物"}},{q="谁是纳拉雷克斯的门徒？",a="纳拉雷克斯的门徒是一个德鲁伊教团，他们陪同纳拉雷克斯前往哀嚎洞穴，以帮助振兴贫瘠之地。在他被困在噩梦中之后，许多人变得野性难驯或陷入疯狂，只剩下极少数神志清醒的门徒试图挽救这场灾难。",al={"纳拉雷克斯的门徒","纳拉雷克斯的追随者","哀嚎洞穴里的德鲁伊是谁"}},{q="联盟和部落都可以接受这个任务吗？",a="是的。厄布鲁和她的同伴是保持中立的德鲁伊，他们关心自然的保护和对噩梦的遏制。他们接受来自部落或联盟的有能力的勇士提供的帮助。",al={"清除变异者是联盟还是部落任务","清除变异者是中立任务吗"}},{q="你需要为厄布鲁杀死哪些生物？",a="厄布鲁指引你去猎杀洞穴深处四种特定的被腐化的动物：变异掠夺者、变异蝰蛇、变异蹒跚者和变异恐牙，每种需要击杀七只。",al={"清除变异者怪物","清除变异者目标","需要击杀哪种变异生物"}},{q="完成这个任务能唤醒纳拉雷克斯吗？",a="不能。厄布鲁的任务严格专注于虫害防治和减损，通过减少危险野兽的数量来缓解危机。唤醒纳拉雷克斯需要在他洞穴深处的圣所内进行直接的仪式。",al={"这能唤醒纳拉雷克斯吗","如何唤醒纳拉雷克斯"}}},fx={["62e049f1"]={q="厄布鲁为什么要消灭变异野兽？",a="纳拉雷克斯的其他门徒都专注于唤醒被困的主人，而厄布鲁认为哀嚎洞穴中正滋生着迫在眉睫的威胁。纳拉雷克斯曾想让贫瘠之地恢复成郁郁葱葱的森林，如今他的愿景却化为梦魇，令腐化而不自然的生物遍布隧道。厄布鲁认为，在清除这些扭曲的野兽之前，这片土地无望得到治愈，他们的首领也无望获救。",al={"厄布鲁的目的","为什么要杀死变异野兽","厄布鲁为什么想杀死变异野兽"}},b4bfe70b={q="哀嚎洞穴里的变异生物是什么？",a="它们原本是当地的动物——毒蛇、迅猛龙和蹒跚的植物怪物，却被纳拉雷克斯梦魇泄出的黑暗能量扭曲成了怪物。纳拉雷克斯曾试图引导翡翠梦境，让干旱的贫瘠之地重焕生机；但他的梦境变得污浊后，逸散的魔法能量便使野生动物发生变异，成为凶猛而不自然的掠食者，如今它们遍布洞穴深处。",al={"什么是变异掠夺者","哀嚎洞穴的变异野兽","哀嚎洞穴的腐化生物"}},ab17f40e={q="纳拉雷克斯的门徒为什么不能自行清理洞穴？",a="门徒们人手紧缺，根本无力独自发动攻击。自从纳拉雷克斯陷入梦魇，他们的教派便大幅衰落；仅存的几人还分身乏术，一边准备唤醒他的仪式，一边守卫他们仅剩的据点。他们人数不足，战力也不够强，无法深入洞穴并消灭野兽，只能寻求外援。",al={"厄布鲁为什么需要我的帮助","门徒们为什么不能清理洞穴","纳拉雷克斯的门徒为什么需要帮助"}}},fp="19,393,27.477.0,12.537.0,41.337.0,41.324.0,33.299.0,44.210.0,44.194.0,40.219.0"}
P.entries["quest:1488"] = {n="堕落者",s="塔卡塔·钢刃并不了解阿兹雷索克领主，但赞同莫林的观点，认为必须阻止这位恶魔领主，特别是如果阿兹雷索克正试图将火刃氏族拉拢过去的话。塔卡塔相信你能召集一支队伍去对付阿兹雷索克和他的术士仆从：加格尔·死咒。",h="塔卡塔·钢刃并不了解阿兹雷索克领主，但赞同莫林的观点，认为必须阻止这位恶魔领主，特别是如果阿兹雷索克正试图将火刃氏族拉拢过去的话。塔卡塔相信你能召集一支队伍去对付阿兹雷索克和他的术士仆从：加格尔·死咒。",kw={"火刃氏族","恶魔","凄凉之地","加格尔·死咒","阿兹雷索克领主","莫林","塔卡塔·钢刃","术士"},sec={{t="南方的队伍",b="塔卡塔从未听说过阿兹雷索克领主，但赞同莫林的观点，认为必须阻止这位恶魔领主，尤其是当阿兹雷索克试图影响火刃氏族时。你已经证明了自己想要协助大酋长，因此塔卡塔相信你能召集一支队伍，消灭阿兹雷索克和他的术士仆从：加格尔·死咒。塔卡塔告诉你直接向南前往玛诺洛克集会所，他们就在那里。"},{t="塔卡塔的忧虑",b="塔卡塔称凄凉之地的恶魔威胁比以往任何时候都要大。每一个新来的邪恶生物都让回到大酋长身边的希望变得更加渺茫，塔卡塔有时甚至希望半人马才是唯一的敌人。"},{t="塔卡塔的定论",b="一旦威胁消除，塔卡塔称这是一场伟大的胜利，并表示这里的前景不像曾经担心的那样黯淡。塔卡塔谈到了恶魔被消灭，火刃氏族的企图破产，以及一个可以再次被称作安全家园的地方。"}},faq={{q="是谁在派遣冒险者去对付阿兹雷索克领主？",a="塔卡塔·钢刃，他站在莫林这一边，并相信你能召集一支队伍去对付那位恶魔领主。",al={"谁发布腐蚀者任务","腐蚀者任务发布者","塔卡塔·钢刃任务"}},{q="谁必须被击败？",a="恶魔领主阿兹雷索克，以及侍奉他的术士加格尔·死咒。",al={"我该杀谁","腐蚀者任务目标","阿兹雷索克和加格尔"}},{q="目标位于何处？",a="塔卡塔说直接往南走。他们都在玛诺洛克集会所附近，位于凄凉之地的南部。",al={"阿兹雷索克在哪里","加格尔·死咒位置","腐蚀者任务去哪里"}},{q="为什么阿兹雷索克领主构成了如此大的危险？",a="塔卡塔从未听说过阿兹雷索克，但必须阻止这位恶魔领主，尤其是当阿兹雷索克试图影响火刃氏族的时候。",al={"为什么要杀阿兹雷索克","阿兹雷索克在做什么","与火刃氏族的关系"}},{q="这个任务链的前序是什么？",a="此步骤紧随“腐蚀者”任务链的第四部分之后。",al={"前置任务","腐蚀者任务前序","腐蚀者任务链"}},{q="塔卡塔对凄凉之地的恶魔有什么担忧？",a="塔卡塔称他们是前所未有的巨大威胁。每一个新来的邪恶生物都让回到大酋长身边的希望变得更加渺茫，塔卡塔希望半人马才是唯一的敌人。",al={"塔卡塔背景故事","塔卡塔为什么在这里","塔卡塔·钢刃的角色"}}},fp="13,279,20.399.0,14.230.0,16.261.1,49.96.0,21.77.0,30.98.0,42.139.0,36.57.0,51.190.0"}
P.entries["quest:1489"] = {n="哈缪尔·符文图腾",s="这个任务将部落冒险者从贫瘠之地那郁郁葱葱但饱受困扰的绿洲，指引向雷霆崖的高处。图加·符文图腾怀疑哀嚎洞穴内存在深层的精神腐化，因此派你前往寻求哈缪尔·符文图腾大德鲁伊的指引。",h="这个任务将部落冒险者从贫瘠之地那郁郁葱葱但饱受困扰的绿洲，指引向雷霆崖的高处。图加·符文图腾怀疑哀嚎洞穴内存在深层的精神腐化，因此派你前往寻求哈缪尔·符文图腾大德鲁伊的指引。",kw={"长者高地","哈缪尔·符文图腾","绿洲","污染","贫瘠之地","雷霆崖","图加·符文图腾","哀嚎洞穴"},ang={["class:Druid"]="对于牛头人德鲁伊来说，向哈缪尔·符文图腾大德鲁伊汇报是一次朝圣，去见那位在玛法里奥·怒风教导下建立现代牛头人德鲁伊教义的导师。",["faction:Horde"]="由于贫瘠之地是年轻部落的十字路口，调查蔓延的污染可以保护连接杜隆塔尔、莫高雷和北部哨所的补给线。",["race:Tauren"]="这项任务将贫瘠之地祖传狩猎场的忧虑与居住在莫高雷神圣悬崖上的部落长者的指引联系在了一起。"},sec={{t="令人不安的梦境",b="在研究贫瘠之地的野生动物时，图加·符文图腾发现了一种奇怪的痛苦正折磨着绿洲附近的生物。这些变异的野兽背着被不自然力量所污染的甲壳，这让图加意识到这片土地本身正困在一个混乱、不安的梦境中。深信这些源自地底哀嚎洞穴的水流是腐化的根源，图加知道，进入洞穴所需要的智慧远超他这个孤独的自然学家所具备的。"},{t="长者高地的建议",b="为了了解洞穴内的威胁，图加指引你前往雷霆崖，去与他的族人，哈缪尔·符文图腾大德鲁伊商议。哈缪尔是牛头人德鲁伊中地位最高的，也是莫高雷塞纳里奥议会受人尊敬的精神领袖。哈缪尔驻守在宁静的长者高地上，监视着整个卡利姆多的动荡，并证实了蔓延在贫瘠之地上的梦魇是一个迫切需要部落勇士全力以赴去应对的严重威胁。"}},faq={{q="图加为什么让我去找哈缪尔？",a="图加发现贫瘠之地的绿洲受到了一种源自哀嚎洞穴的怪异痛苦的污染。因为这种现象就像一个困扰大地的梦魇，在他人在尝试进入洞穴之前，他把你派往长者高地找哈缪尔·符文图腾大德鲁伊寻求高阶德鲁伊的指引。",al={"为什么找哈缪尔","为什么要和哈缪尔交谈","哈缪尔任务目的"}},{q="哈缪尔·符文图腾在哪里？",a="哈缪尔·符文图腾大德鲁伊位于莫高雷的牛头人主城雷霆崖。他站在长者高地上，与其他德鲁伊和萨满祭司一起俯瞰着周围的平原。",al={"哈缪尔位置","哈缪尔在哪里","寻找哈缪尔·符文图腾"}},{q="图加发现的污染源是什么？",a="这种污染源自哀嚎洞穴的地下泉水。这些奇异的水正在腐蚀当地的野生动植物，导致这片土地的行为表现得就像被困在无法逃脱的梦魇中一样。",al={"什么是污染","绿洲腐化","哀嚎洞穴污染"}},{q="与哈缪尔交谈后会发生什么？",a="哈缪尔会欢迎你来到雷霆崖，并让你为即将到来的试炼做好准备。他警告说，处理贫瘠之地地下的梦魇是一项严峻的任务，并指引你去找Nara Wildmane，为进入哀嚎洞穴做准备。",al={"哈缪尔之后的任务","下一步做什么","哈缪尔后续任务"}},{q="哈缪尔·符文图腾是谁？",a="哈缪尔·符文图腾大德鲁伊是牛头人德鲁伊的首领，也是大酋长凯恩·血蹄儿时的好友和顾问。在第三次战争后学习了荒野之道，他引导着牛头人德鲁伊与自然及塞纳里奥议会沟通。",al={"哈缪尔是谁","哈缪尔背景故事","大德鲁伊哈缪尔"}},{q="进入哀嚎洞穴需要做这个任务吗？",a="进入哀嚎洞穴不需要前置任务，但这个任务是部落将贫瘠之地绿洲的谜团与副本内的探险联系起来的剧情桥梁。",al={"哀嚎洞穴前置任务","这个任务是必须的吗"}}},fx={a40fa735={q="图加·符文图腾为什么要冒险者去找哈穆尔？",a="图加·符文图腾驻扎在十字路口，密切观察贫瘠之地及其绿洲中蔓延的种种异变。由于他必须留在前线亲自研究遭到腐化的野生动物，因此需要有能力的旅人替他递交报告，并前往雷霆崖的长者高地直接向大德鲁伊哈穆尔·符文图腾寻求指引。",al={"为什么派我去找哈穆尔","图加为什么不能去找哈穆尔","图加为什么派我去"}}},fp="16,269,18.485.0,21.447.0,33.311.0,34.200.0,46.204.0,40.241.0,24.284.0,52.200.0"}
P.entries["quest:149"] = {n="幽灵的发丝",s="“幽灵的发丝”是夜色镇的占卜师伊瓦夫人委托的一项差事。为了收集纺制“幽灵的发丝”所需的鬼发，旅行者会被派往南方的废弃农舍寻找盲眼玛丽，那是一个饱受折磨的灵魂。通过把一把鬼梳交给她，人们可以从她那幽灵般的发丝中收集到必要的发缕。",h="“幽灵的发丝”是夜色镇的占卜师伊瓦夫人委托的一项差事。为了收集纺制“幽灵的发丝”所需的鬼发，旅行者会被派往南方的废弃农舍寻找盲眼玛丽，那是一个饱受折磨的灵魂。通过把一把鬼梳交给她，人们可以从她那幽灵般的发丝中收集到必要的...",kw={"盲眼玛丽","夜色镇","暮色森林","农舍","幽灵","幽灵的发丝","伊瓦夫人","鬼梳"},ang={["class:Priest"]="目睹一个因精神折磨而挖出自己双眼的灵魂，展现了暮色森林中那些不安的亡灵所遭受的深重悲剧和挥之不去的阴影。",["faction:Alliance"]="在夜色镇周围的农场中徘徊的悲剧幽灵提醒着人们，繁荣的Grand Hamlet是如何迅速陷入黑暗与孤立的。",["profession:Tailoring"]="用鬼魂的虚体残余来纺线是一种罕见的神秘技术，与标准的纺车和织布机大不相同。"},sec={{t="占卜师的请求",b="夜色镇的伊瓦夫人需要特殊的异界材料，以便为亚伯克隆比纺制“幽灵的发丝”。普通的亚麻线和毛线无法用于暮色森林的仪式；相反，她需要直接从灵魂身上采集的以太发丝。为了在不诉诸暴力的情况下获得这种骇人的材料，伊瓦提供了一把精致的鬼梳，它能够穿过死亡的面纱，采集散落的幽灵发丝。"},{t="盲眼玛丽的悲伤",b="在夜色镇南方的阴影山丘中，坐落着一座废弃的农舍，徘徊着哀嚎的怨灵——盲眼玛丽。这个灵魂因自我厌恶而深受折磨，她不断为自己丑陋的外表感到悲伤，并尖叫着让闯入者移开视线，因为她在痛苦中挖出了自己的双眼，无法接受自己变成这般模样。赠予她鬼梳可以让她获得片刻的安慰，尽管身陷Unending Torment，她还是会梳理自己的幽灵发丝。"}},faq={{q="盲眼玛丽是谁？",a="盲眼玛丽是一个悲伤的鬼魂，徘徊在夜色镇南方山丘上的一座废弃农舍中。她因绝望和自认为丑陋而发疯，挖出了自己的双眼，这样就永远不必再看到自己。尽管失去了视力，但她依然能敏锐且痛苦地察觉到任何注视她的人。",al={"盲眼玛丽背景故事","盲眼玛丽是谁暮色森林","鬼梳女人"}},{q="伊瓦夫人为什么需要鬼发？",a="伊瓦夫人需要鬼发来纺制幽灵线。在暮色森林这种闹鬼的环境中，普通的工艺材料往往无法满足需求，她必须依靠神秘的材料来完成她的仪式和防护附魔。",al={"为什么需要幽灵的发丝","幽灵的发丝有什么用","伊瓦夫人幽灵的发丝"}},{q="盲眼玛丽的房子在哪里？",a="她那破败的家园坐落在夜色镇正南方的山丘上，穿过城镇墓地，周围徘徊着肆虐黑暗森林的恐怖生物和亡灵。",al={"盲眼玛丽在哪里","盲眼玛丽位置","夜色镇南部的农舍"}},{q="鬼梳如何对灵魂起作用？",a="鬼梳是为不可见的世界制作或附魔的，它可以与无形的幻象产生互动。它穿过灵体就像普通的梳子梳理活人的头发一样，可以收集保留着以太形态的脱落发丝。",al={"鬼梳如何使用","鬼梳背景故事","梳理幽灵发丝"}},{q="盲眼玛丽对旅行者有敌意吗？",a="不会。尽管她会发出可怕的尖叫和哭泣，但盲眼玛丽对活着的访客并无敌意。她的痛苦完全源于内心，尽管周围的森林和附近的建筑中潜伏着许多充满攻击性的生物和亡灵。",al={"盲眼玛丽会攻击吗","盲眼玛丽危险吗"}},{q="给玛丽梳子后会发生什么？",a="玛丽用过梳子后，会将其归还，上面缠绕着她的幽灵发丝。冒险者必须把梳子带回夜色镇交给伊瓦夫人，这样她就能把这些发丝纺成“幽灵的发丝”。",al={"获得幽灵的发丝后","归还梳子任务","幽灵的发丝之后"}}},fx={["212c26a1"]={q="伊瓦夫人为什么需要冒险者去拜访盲眼玛丽？",a="伊瓦夫人留在夜色镇，以占卜和仪式帮助镇民；但要找到盲眼玛丽，就必须深入村庄南边闹鬼的山丘。周围的森林和玛丽的农场爬满了亡灵与阴影野兽，普通镇民不敢独自前往。",al={"为什么派我去","她为什么不亲自去","伊瓦夫人为什么需要我"}}},fp="17,370,25.430.0,24.467.0,18.307.0,36.240.0,38.172.0,44.246.0,35.232.0,40.187.0"}
P.entries["quest:1490"] = {n="纳拉·蛮鬃",s="纳拉·狂鬃是一位居住在雷霆崖的年轻牛头人德鲁伊，她正寻求揭开在哀嚎洞穴深处上演的悲剧。在大德鲁伊哈缪尔·符文图腾窥探了翡翠梦境并从那里的腐蚀中撤出后，他派遣冒险者去与纳拉商议。纳拉意志坚定，坚持观察了足够长的时间，亲眼见证了笼罩她族人的梦魇。她是部落的关键联系人，引导勇士们去终结尖牙德鲁伊。",h="纳拉·狂鬃是一位居住在雷霆崖的年轻牛头人德鲁伊，她正寻求揭开在哀嚎洞穴深处上演的悲剧。在大德鲁伊哈缪尔·符文图腾窥探了翡翠梦境并从那里的腐蚀中撤出后，他派遣冒险者去与纳拉商议。纳拉意志坚定，坚持观察了足够长的时间，亲眼见...",kw={"贫瘠之地","尖牙德鲁伊","长者高地","翡翠梦境","哈缪尔·符文图腾","纳拉·狂鬃","雷霆崖","哀嚎洞穴"},ang={["class:Druid"]="德鲁伊们会赞赏纳拉在探索翡翠梦境那些凶险、腐化的领域时所展现出的勇气，连像哈缪尔这样的资深大师都犹豫是否要在那里久留。",["faction:Horde"]="纳拉的警觉保护了部落领地的核心，确保扭曲贫瘠之地的黑暗力量不会肆无忌惮地蔓延进莫高雷。",["race:Tauren"]="对于那些刚刚在哈缪尔指导下踏上德鲁伊之路的牛头人来说，纳拉代表了年轻、坚定的一代，愿意直面非自然的腐化。"},sec={{t="腐蚀的幻象",b="当奇怪且不自然的现象开始在贫瘠之地蔓延时，大德鲁伊哈缪尔·符文图腾进入了翡翠梦境，试图探究其根源。在那里，他目睹了一个德鲁伊教派，他们本意是为干旱的草原恢复生机，却因堕落的污秽而丧失了心智。由于年事已高，无法长时间抵御梦魇的侵袭，哈缪尔逃回了现实世界。然而，他年轻的学徒纳拉·狂鬃却不愿轻易放弃。她炽热的意志使她得以在梦境中停留得更久，从而让她能近距离观察那些已经变异的教派成员。"},{t="直面梦魇",b="虽然哈缪尔为雷霆崖的塞纳里奥议会提供了总体的指导，但纳拉·狂鬃拥有净化腐烂所需的战术洞察力。她曾直视那些堕落德鲁伊扭曲且布满蛇鳞的面孔，因此她深知他们的罪行，以及他们打算在卡利姆多引发的毁灭。她的决心标志着部落对哀嚎洞穴的进攻拉开了序幕，旨在消灭那些背弃了神圣誓言的领袖。"}},faq={{q="谁是纳拉·狂鬃？",a="纳拉·狂鬃是一位年轻且充满活力的牛头人德鲁伊，居住在雷霆崖的长者高地上。她在师从大德鲁伊哈缪尔·符文图腾，并不惧于直面那些威胁自然平衡的腐蚀性梦魇。",al={"谁是纳拉","纳拉·狂鬃背景故事","雷霆崖的纳拉·狂鬃"}},{q="为什么哈缪尔·符文图腾要派旅行者去找她？",a="哈缪尔坦言，由于年纪较大且力量衰退，他无法在尖牙德鲁伊所在的腐化梦境中长久停留。因为纳拉年轻且意志坚定，她在梦境中停留的时间更长，并收集到了关于该教派计划的关键情报。",al={"为什么要和纳拉交谈","哈缪尔推荐纳拉","为什么哈缪尔派我来这里"}},{q="纳拉在翡翠梦境中看到了什么？",a="纳拉亲眼目睹了盘踞在哀嚎洞穴中的堕落德鲁伊。她看到他们的面孔扭曲成了蛇一样的鳞片形象，并察觉到了他们打算对贫瘠之地实施的黑暗阴谋和罪行。",al={"纳拉看到了什么","纳拉的梦境幻象","梦境中的鳞片德鲁伊"}},{q="纳拉·狂鬃在哪里？",a="你可以在雷霆崖长者高地的一顶德鲁伊帐篷里找到她，就在大德鲁伊哈缪尔·符文图腾对面。",al={"纳拉在哪里","纳拉·狂鬃的位置","寻找纳拉·狂鬃"}},{q="向纳拉·狂鬃汇报后会发生什么？",a="一旦你与她交谈，纳拉会指引你进入哀嚎洞穴并击杀那些堕落的尖牙德鲁伊，从而开启重要的地下城任务“尖牙的首领”。",al={"纳拉之后的任务","纳拉想让我做什么","尖牙的首领后续"}},{q="为什么哀嚎洞穴里的德鲁伊会腐化？",a="在纳拉雷克斯的领导下，德鲁伊们进入了洞穴，希望借此连接翡翠梦境，为贫瘠之地带来郁郁葱葱的生机。然而，纳拉雷克斯的沉睡却变成了一场恐怖的梦魇，困住了他的追随者，并将他们扭曲成了蛇形的尖牙德鲁伊。",al={"哀嚎洞穴教派","为什么尖牙德鲁伊会变邪恶","为什么贫瘠之地的德鲁伊变邪恶了"}}},fx={["2cdff5a8"]={q="为什么大德鲁伊哈缪尔·符文图腾让你去找纳拉，而不是亲自前往？",a="大德鲁伊哈缪尔·符文图腾年事已高，且多次深入灵界令他身心俱疲。当他进入翡翠梦境调查哀嚎洞穴的异变时，力量不支，只得退了出来。纳拉·蛮鬃年轻而勇猛，在他离开后仍留在梦境之中。哈缪尔如今身在雷霆崖，负责协调牛头人德鲁伊；他所剩无几的精力也经不起奔波传话或独自面对威胁，因此只能托付给有能力的旅人，去打探纳拉的发现。",al={"哈缪尔为什么让我去找纳拉","哈缪尔为什么不能和纳拉谈","为什么派冒险者去找纳拉"}}},fp="13,481,22.598.0,25.471.1,21.230.0,59.289.0,39.210.0,33.127.0,46.169.0,52.263.0"}
P.entries["quest:1491"] = {n="智慧饮料",s="“聪明饮料”是棘齿城的商贾麦伯克·米希瑞克斯策划的一项创业计划。在尝试用日鳞迅猛龙角酿制智力药水失败后，麦伯克现在派遣冒险者深入哀嚎洞穴，收集粘液残渣来调制他最新的饮料配方。",h="“聪明饮料”是棘齿城的商贾麦伯克·米希瑞克斯策划的一项创业计划。在尝试用日鳞迅猛龙角酿制智力药水失败后，麦伯克现在派遣冒险者深入哀嚎洞穴，收集粘液残渣来调制他最新的饮料配方。",kw={"贫瘠之地","粘液","麦伯克·米希瑞克斯","迅猛龙角","棘齿城","聪明饮料","哀嚎洞穴","哀嚎香精"},ang={["class:Druid"]="当德鲁伊们进入哀嚎洞穴，试图净化扭曲了翡翠梦境的梦魇时，麦伯克却仅仅将这惨痛的生态污染视为他零售生意的廉价液体糖浆。",["faction:Horde"]="对于穿行在贫瘠之地十字路口的旅者来说，棘齿城的商人们提供了很多赚快钱的机会，只要你不去过问他们打算用你送来的怪物部位做什么就行。",["profession:Cooking"]="任何烹饪大师都会立刻看出棘齿城正在上演的食品卫生灾难：将未经处理、被梦魇污染的粘液直接浸泡成可饮用的补药，这违反了所有的食品安全标准。"},sec={{t="灾难配方",b="麦伯克·米希瑞克斯在繁忙的港口城镇棘齿城开展业务，他完美体现了地精的一贯哲学：将任何离奇的地区现象转化为真金白银。他坚信一种能提升智力的药水能让他一夜暴富，起初他认为迅猛龙角粉就是其中的秘密。当那一批产品表现平平后，他便将目光投向了一种更为可疑的成分：从附近的哀嚎洞穴中渗出的腐蚀性香精。"},{t="哀嚎香精",b="贫瘠之地经历了一场令人不安的生态突变，繁茂的绿洲突然涌现，当地的野生动物也扭曲成了充满攻击性的恐怖生物。米希瑞克斯推测，一种他称为“哀嚎香精”的奇特物质正是导致这些突变的催化剂。他断定，任何能如此剧烈改变生物特性的东西一定是一种强效的秘密配方，于是他派遣雇佣兵去消灭潜伏在洞穴迷宫深处的渗液粘液怪，并将它们发光的体液直接虹吸到饮料瓶中。"}},faq={{q="谁是麦伯克·米希瑞克斯？",a="麦伯克·米希瑞克斯是一位驻扎在棘齿城港口的进取型地精。他完全不在乎卫生标准，一心只想创造一种可以在卡利姆多各地销售的“聪明饮料”以发大财。",al={"麦伯克·米希瑞克斯","谁提供聪明饮料任务","聪明饮料任务发放者"}},{q="为什么迅猛龙角没用？",a="麦伯克最初认为，将日鳞迅猛龙的角磨成粉可以制成一种强效的增智药水。然而酿造出来的饮料并没有带来预期的智慧，这迫使他不得不转向一种更危险的活性成分。",al={"为什么迅猛龙角会失败","迅猛龙角饮料"}},{q="什么是哀嚎香精？",a="哀嚎香精是一种从哀嚎洞穴深处的不自然粘液怪身上滴落的粘液物质。麦伯克认为这种不稳定的物质正是导致贫瘠之地蔓延的离奇植物和动物突变的驱动催化剂。",al={"什么是哀嚎香精","来自哀嚎洞穴的香精"}},{q="在哪里可以找到携带这种香精的粘液怪？",a="这种香精可以从徘徊在棘齿城以西、哀嚎洞穴地下隧道中的粘液生物（如进化粘液怪、吞噬粘液怪和梦魇粘液怪）身上收集到。",al={"粘液怪在哪里","聪明饮料任务怪物","谁掉落哀嚎香精"}},{q="这种聪明饮料可以安全饮用吗？",a="考虑到这种香精是从与贫瘠之地各处的腐蚀性突变有关的梦魇粘液怪身上采集的，将其装瓶作为商业药水销售是极其鲁莽的。秉承地精的商业道德，麦伯克显然更关心产品的市场潜力，而非顾客的健康安全。",al={"聪明饮料有毒吗","这种饮料有效吗"}},{q="完成“聪明饮料”任务后接下来做什么？",a="“聪明饮料”是麦伯克目前饮料项目的终点。他对你送来的哀嚎香精感到满意，并会给予你奖励。他还承诺，一旦这种可疑的药水为他带来巨额财富，他会与你分享未来的利润。",al={"聪明饮料后续","完成聪明饮料后做什么"}}},fx={b3462a0e={q="麦伯克·米希瑞克斯为什么想要哀嚎香精？",a="麦伯克·米希瑞克斯是棘齿城一名野心勃勃的地精商人，一心想发大财。他最初试图用迅猛龙角制作增强智力的饮料，却没能成功，于是转而采用一种危险得多的原料。他认为，贫瘠之地动植物身上那些扭曲的奇异变异，源自哀嚎香精蕴含的强大能量；他打算将香精直接加入自己的配方，制成号称神奇的聪明饮料，大赚一笔。",al={"麦伯克的动机","麦伯克为什么想要聪明饮料","为什么要制作聪明饮料"}},["6730f7d3"]={q="携带香精的外质是什么？",a="外质是栖居在哀嚎洞穴深处的奇异软泥状实体。绿洲裂隙下方聚集着不稳定的腐化能量，当地的地下精华便凝结成不断变异、吞噬一切的梦魇幽灵软泥怪。这些没有心智的实体吸收着洞穴中原始而致变异的能量，将奇异的哀嚎香精聚集在不断变形的躯体之中，直到有人将其采集。",al={"什么是外质","哀嚎洞穴的外质","谁携带着香精"}}},fp="12,312,21.488.0,19.518.0,22.207.0,33.250.0,24.258.0,54.194.0,35.266.0,41.203.0"}
P.entries["quest:1492"] = {n="码头管理员迪兹维格",s="Wharfmaster Dizzywig的快递差事是将一箱药水和试剂穿越贫瘠之地，送到棘齿城。这批货物将通过当地码头租用的船只跨越无尽之海，运往旧大陆。它为旅行者提供了一个直接了解以棘齿城码头为中心的繁忙中立贸易的机会。",h="Wharfmaster Dizzywig的快递差事是将一箱药水和试剂穿越贫瘠之地，送到棘齿城。这批货物将通过当地码头租用的船只跨越无尽之海，运往旧大陆。它为旅行者提供了一个直接了解以棘齿城码头为中心的繁忙中立贸易的机会。",kw={"黑水湾","码头","栈桥","棘齿城","保险箱","航运","贫瘠之地","wharfmaster dizzywig"},ang={["faction:Horde"]="对于在贫瘠之地干旱平原上冒险的部落探险者来说，向棘齿城运送货物让他们接触到了连接卡利姆多与东部王国的重要中立海上航线。"},sec={{t="前往港口的信使",b="当货物需要在卡利姆多和东部王国之间进行海上运输时，中立的棘齿城港口是卡利姆多中部旅行者的主要门户。随着商队已经出发，炼金用品等待运往旧大陆的同事手中，旅行者经常被要求直接将保险箱手工运送到水边。"},{t="棘齿城码头",b="Wharfmaster Dizzywig在棘齿城的木质码头上监管着海上货物的进出。Dizzywig需要平衡账簿、货运清单和货舱，确保私人货物能有空间装载在向东横跨无尽之海、前往黑水湾等港口的船只上。"}},faq={{q="Wharfmaster Dizzywig是谁？",a="Wharfmaster Dizzywig是驻扎在棘齿城主码头上的地精港口官员。他负责管理卡利姆多与海外港口之间的船只货运清单、货舱和航线。",al={"wharfmaster dizzywig","dizzywig是谁","dizzywig在哪里"}},{q="这只箱子要送到哪里？",a="这箱药水和试剂计划运往旧大陆，已预订了下一艘从棘齿城出发、前往黑水湾的船只舱位。",al={"箱子运往何处","黑水湾","箱子的目的地"}},{q="棘齿城在哪里？",a="棘齿城位于贫瘠之地的东海岸，坐落于十字路口正东面的一个隐蔽海湾中。",al={"棘齿城位置","如何找到棘齿城"}},{q="为什么要通过地精港口发送货物？",a="棘齿城是一个对部落和独立商人开放的中立港口，提供横跨无尽之海的定期航线，绕过了军事封锁和政治敌对。",al={"为什么选择棘齿城","为什么要使用地精港口"}},{q="保险箱里装的是什么？",a="这个箱子里装满了各种配置好的药水、制作试剂和各类炼金产品，准备运往东部王国的合作伙伴手中。",al={"箱内物品","箱子里有什么"}},{q="是谁将货物发送给Dizzywig的？",a="这批货物是由贫瘠之地的一位炼金从业者发送的，他错过了定期的出发商队，需要一个可靠的跑腿人赶在下一次潮汐之前到达码头。",al={"谁发布了任务","任务发布者"}}},fx={["14e5c3eb"]={q="为什么药剂师赫布瑞姆要把这个箱子送给码头管理员迪兹维格？",a="十字路口的药剂师赫布瑞姆必须把一箱药剂、试剂和其他物品送给旧世界的同伴。他抽不出时间亲自把箱子送到棘齿城的码头，而最后一支商队已经出发了。把箱子交给你，才能确保它赶上下趟前往黑水湾的船。",al={"为什么要送保险箱","阿克泽洛斯和迪兹维格的动机","为什么要把箱子送到棘齿城"}},c036c897={q="为什么药剂师赫布瑞姆要找冒险者帮忙，而不亲自送货？",a="药剂师赫布瑞姆没有足够的时间亲自从十字路口一路赶到海岸。最后一支商队已经出发，他无法依靠常规运输。请一位旅人帮忙，是他确保箱子能在船只随下一次涨潮启航前送到码头的唯一可靠办法。",al={"为什么派我去找迪兹维格","阿克泽洛斯为什么不能送箱子","阿克泽洛斯为什么不去棘齿城"}}},fp="20,347,21.359.0,15.294.0,28.192.0,30.152.0,25.123.0,37.185.0,32.148.0,35.181.0"}
P.entries["quest:1498"] = {n="防御之道",s="“防御之路”是年轻的部落战士必须经历的成人礼，由前沿哨所的资深战士犹塞克指派。新兵们被要求猎杀雷霆山的雷霆野兽，以此证明他们具备成为部落之盾所需的坚韧。",h="“防御之路”是年轻的部落战士必须经历的成人礼，由前沿哨所的资深战士犹塞克指派。新兵们被要求猎杀雷霆山的雷霆野兽，以此证明他们具备成为部落之盾所需的坚韧。",kw={"贫瘠之地","杜隆塔尔","前沿哨所","防御之路","烧焦的鳞片","雷霆蜥蜴","雷霆山","犹塞克"},ang={["class:Warrior"]="这项任务标志着新兵步入了防御训练的阶段，它教会战士，真正的武力在于将盟友从毁灭中保护下来。",["faction:Horde"]="前沿哨所是防御进入贫瘠之地道路的关键据点，因此守卫们的韧性对部落的安全至关重要。"},sec={{t="部落之盾",b="部落的战争不仅仅是狂野地冲向战场。在前沿哨所，坐落在贫瘠之地与杜隆塔尔的交界处，资深战士犹塞克正在教导年轻的战士们关于防御的严肃职责。对于犹塞克而言，战士的最高使命是站在危险与弱者之间，承受沉重的打击，以确保部落的存续。"},{t="雷霆试炼",b="为了证明他们拥有纪律性防御所需的耐力和决心，犹塞克派遣新兵进入雷霆山。这处峡谷位于杜隆塔尔境内，穿过怒水河向北即可到达，到处都是雷霆蜥蜴和闪电皮兽。在这些野兽的震荡冲击下幸存并收集它们烧焦的鳞片，足以证明新兵拥有守住前线的坚毅。"}},faq={{q="谁发布了“防御之路”任务？",a="该任务由资深战士犹塞克发布，他是一位经验丰富的战士，驻扎在守护杜隆塔尔与贫瘠之地东部边缘交界处的前沿哨所。",al={"任务发布者","谁开启防御之路","犹塞克位置"}},{q="雷霆山位于何处？",a="雷霆山位于杜隆塔尔西部，穿过怒水河上的桥梁向北，在主干道北侧。该峡谷中栖息着具有攻击性的雷霆蜥蜴和闪电皮兽。",al={"雷霆山位置","雷霆蜥蜴在哪里","烧焦的鳞片位置"}},{q="为什么犹塞克专门要求烧焦的鳞片？",a="烧焦的鳞片只能通过猎杀雷霆山中操控电流的野兽获得。忍受它们的电气攻击，证明了战士具备学习进阶防御技巧所需的身体素质和韧性。",al={"为什么需要烧焦的鳞片","鳞片用途"}},{q="这项试炼背后的哲学意义是什么？",a="犹塞克教导说，身为战士不仅仅是杀戮，更是要成为一道坚不可摧的壁垒。在狂野野兽的猛攻中生存下来，能教会新兵如何结合强健的体魄与精妙的动作，以保护弱小的盟友。",al={"战士哲学","防御之路背景","防御姿态设定"}},{q="完成“防御之路”后接下来要做什么？",a="在向犹塞克证明了你的防御能力后，他会指引你寻找萨恩格里姆·火眼，以继续你的武艺训练。",al={"后续任务","防御之路后做什么","后续"}},{q="非战士职业可以进行这项试炼吗？",a="不能。防御之路是战士专属的成人礼，旨在考察并教导新兵关于守卫职责和防御战斗的基础知识。",al={"这是战士专属吗","谁能做这个任务"}}},fx={["47a57f01"]={q="你要去雷霆山猎杀哪些生物？",a="犹塞克派你去对付栖居在杜隆塔尔雷霆山的雷霆蜥蜴和雷电蜥蜴。这些凶猛的野兽能发动噼啪作响的电击，足以击穿普通防御。与它们交战，你必须承受持续不断的物理和元素攻击，以证明自己的体魄和意志足够坚韧，能够成为部落的盾牌。",al={"雷霆山里要打什么","防御之道的目标","雷霆蜥蜴和雷电蜥蜴"}},["3d8ed519"]={q="为什么犹塞克要考验你，而不亲自处理这些任务？",a="犹塞克是驻扎在前沿哨所的教官，他的职责是考察有志成为战士的人，而不是替自己收集战利品。战士在部落中的首要使命，是成为弱小同胞的盾牌。犹塞克不能把防御技巧随便传授给任何来求教的人；你必须亲自证明自己能承受猛烈的打击，他才会认为你配得上他的教导。",al={"为什么派我去","犹塞克为什么需要我","为什么我必须猎杀蜥蜴"}}},fp="15,278,23.412.0,16.391.0,36.169.0,31.197.0,49.235.0,51.239.0,49.129.0,38.155.0"}
P.entries["quest:1499"] = {n="邪灵劣魔",s="这项任务标志着年轻术士首次在试炼谷对抗潜藏的恶魔爪牙的行动圆满完成。在鲁赞的指导下消灭邪恶魔仆后，这位初学者会将战果报告给祖雷萨，由她负责统筹肃清入侵的火刃氏族。",h="这项任务标志着年轻术士首次在试炼谷对抗潜藏的恶魔爪牙的行动圆满完成。在鲁赞的指导下消灭邪恶魔仆后，这位初学者会将战果报告给祖雷萨，由她负责统筹肃清入侵的火刃氏族。",kw={"火刃集会所","杜隆塔尔","小鬼","鲁赞","大兽穴","试炼谷","邪恶魔仆","术士任务","祖雷萨"},ang={["class:Warlock"]="对于一名研习暗影技艺的学徒来说，对抗邪恶魔仆是一项至关重要的考验，这证明了你能驯服并拆解野生的邪能实体，而不是沦为它们的猎物。",["race:Orc"]="恶魔魔仆的存在时刻提醒着人们，那曾经奴役兽人种族的黑暗契约有多么邪恶，因此将它们从杜隆塔尔的土地上铲除，关乎整个文化的生存。",["race:Troll"]="与试炼谷共享领地的暗矛巨魔对恶魔魔法深表怀疑，因此对于年轻的修行者来说，向这些流亡的邪教徒展示自己的忠诚至关重要。"},sec={{t="纪律问题",b="当试炼谷的其他年轻战士和斥候被祖雷萨直接派遣去遏制火刃集会所的入侵时，术士学徒首先要听命于他们阴影中的导师。鲁赞要求学徒在将其指引回部落整体防线的职责范围之前，必须展示对低等恶魔的控制力，以确保他们的努力既能服务于术士集会，又能保障大兽穴的安全。"},{t="集会所的威胁",b="祖雷萨密切注视着俯瞰试炼谷的北方洞穴。潜伏在其中的邪恶魔仆不过是火刃氏族邪教徒最弱小的宠物，但它们在神圣的训练场中公然出现，不仅是一种明目张胆的侮辱，更是一个日益严重的威胁。报告你对抗它们的成果，证实了即使是那些追求邪能技艺的人，也依然致力于保护杜隆塔尔免受真正的腐化。"}},faq={{q="为什么鲁赞不亲自奖励我，而是把我打发去见祖雷萨？",a="祖雷萨正在协调试炼谷针对火刃氏族的整体防御和肃清工作。鲁赞首先会测试你对低等邪能生物的掌控力，但随后会将你指引给祖雷萨，以便你的服务能得到正式的认可，并融入到试炼谷的整体防务之中。",al={"为什么要见祖雷萨","从鲁赞到祖雷萨","为什么要和祖雷萨交谈"}},{q="邪恶魔仆是什么？",a="邪恶魔仆是隶属于火刃集会所的低级恶魔小鬼和爪牙。虽然它们个体脆弱，但它们服务于潜伏在俯瞰试炼谷的洞穴深处的更黑暗的主人。",al={"邪恶魔仆是什么","邪恶魔仆背景","火刃氏族的魔仆"}},{q="我在哪里可以找到祖雷萨？",a="祖雷萨就驻扎在试炼谷大兽穴中央的空地上，从鲁赞所在的训练师营地往上走一小段路就能看到。",al={"祖雷萨在哪里","祖雷萨的位置","祖雷萨地图"}},{q="为什么会有另一个同名的任务？",a="大多数冒险者都是直接从祖雷萨那里接到猎杀这些生物的“邪恶魔仆”任务。然而，术士会从鲁赞那里接到他们专属的职业任务，在完成后会引导他们将战果移交给祖雷萨。",al={"两个邪恶魔仆任务","重复的邪恶魔仆","术士邪恶魔仆"}},{q="火刃氏族在试炼谷做什么？",a="火刃氏族邪教在杜隆塔尔各处的隐秘角落运作，试图从内部瓦解萨尔的新部落。在试炼谷内部的一个洞穴扎根，让他们得以在兽人监督者的眼皮底下捕猎那些经验不足的新兵，并散布恶魔的腐化。",al={"试炼谷的火刃氏族","为什么大兽穴里有邪教徒"}},{q="消灭这些魔仆能消灭邪教吗？",a="不能。正如祖雷萨所言，这些邪恶魔仆仅仅是集会所中更黑暗势力的宠物和侦察兵。击败它们只是揭露并清除正在谷内滋生的邪教徒威胁的第一步。",al={"火刃氏族被击败了吗","邪教徒走了吗"}}},fp="14,288,22.439.0,23.442.0,75.298.0,27.216.0,34.169.0,52.245.0,56.294.0,47.225.0"}
P.entries["quest:15"] = {n="回音山调查行动",s="“调查回音山”是治安官玛克布莱德在北郡山谷发布的一项早期军事任务。新兵被指派去探测北方的回音山矿洞，并被要求铲除那些步步紧逼的狗头人矿工，以确定威胁到修道院矿产资源的侵扰究竟有多严重。",h="“调查回音山”是治安官玛克布莱德在北郡山谷发布的一项早期军事任务。新兵被指派去探测北方的回音山矿洞，并被要求铲除那些步步紧逼的狗头人矿工，以确定威胁到修道院矿产资源的侵扰究竟有多严重。",kw={"回音山","艾尔文","狗头人","狗头人矿工","治安官玛克布莱德","矿洞","北郡","北郡山谷"},ang={["faction:Alliance"]="狗头人在北郡这个暴风城的精神中心附近日益猖獗，这表明在正规军兵力分散的情况下，王国已经变得多么脆弱。",["profession:Mining"]="回音山矿洞是北郡铁匠获取铜矿的重要来源，清理这些地下矿道对于矿工们来说直接关系到经济生存问题。",["race:Human"]="对于在北郡山谷开始服役的年轻人类来说，保卫回音山免受地下害虫的侵扰，是他们向王国证明自己价值的最早考验之一。"},sec={{t="日益严重的侵扰",b="虽然北郡早期的冲突主要集中在森林外围游荡的零散害虫上，但侦察兵的报告很快揭示了一个组织更加严密的威胁。狗头人不仅仅是在树林里搜寻食物；它们已经在回音山矿洞周围集结了兵力。治安官玛克布莱德命令新兵北上，去对付聚集在矿洞入口处的狗头人矿工，并评估这些害虫的盘踞到底有多深。"},{t="对修道院财富的威胁",b="回音山矿洞是北郡兄弟会和驻扎在此的暴风城卫兵重要的矿石和原材料来源。让这些鼠辈般的拾荒者占领矿道，不仅使开采工作陷入瘫痪，还暴露了当地防御力量的薄弱。清理掉十名矿工仅仅是第一步，玛克布莱德的担忧也得到了证实：侵扰的深度远非简单的地面巡逻所能解决，它们已经深入矿井内部。"}},faq={{q="是谁派我执行这项任务的？",a="驻扎在北郡修道院的暴风城卫兵指挥官，治安官玛克布莱德，在侦察兵发现北方的狗头人正在集结后，下达了调查矿洞的命令。",al={"任务发布者","谁发布任务","治安官玛克布莱德"}},{q="回音山矿洞位于哪里？",a="回音山矿洞位于北郡山谷的最北端，直接坐落在修道院及其葡萄园上方的山麓中。",al={"回音山位置","矿洞在哪里","寻找回音山"}},{q="为什么狗头人对北郡来说很危险？",a="虽然单个狗头人只是懦弱的拾荒者，但它们繁殖迅速，并且会成群结队地涌入地下矿道。通过占领回音山矿洞，它们阻断了至关重要的采矿作业，并威胁要淹没这个防守人手不足的山谷。",al={"为什么要杀狗头人","为什么狗头人是威胁","狗头人威胁"}},{q="我击败外面的矿工后会发生什么？",a="回去向治安官玛克布莱德复命证实了他最坏的怀疑：矿洞里已经是彻底的灾难了。他立即再次请求你的援助，让你在“回音山的冲突”任务中更深入地挺进地下矿井。",al={"接下来做什么","后续任务","下一个任务"}},{q="为什么暴风城的军队不亲自去清理矿洞？",a="由于国王瓦里安·乌瑞恩失踪，且艾尔文及周边边境的资源捉襟见肘，北郡当地的守备部队人手太少，无法抽出完整的巡逻队来进行除害工作，只能转而依靠新到的有能力的招募新兵。",al={"暴风城卫兵在哪里","为什么要使用新兵","暴风城守备军"}},{q="在矿洞入口周围能发现什么样的狗头人？",a="地表环境和上层入口处是由狗头人矿工在活动，它们是挖掘地道并为它们的地下聚居地收集蜡烛蜡油的基础劳动力。",al={"狗头人种类","要杀死什么敌人","狗头人矿工"}}},fp="22,201,23.280.0,28.331.0,29.146.0,37.111.0,40.183.0,48.192.1,57.216.0,56.136.0"}
P.entries["quest:150"] = {n="鱼人偷猎者",s="湖畔镇的码头管理员巴伦需要冒险者们去减少止水湖沿岸不断增多的鱼人数量，以防它们耗尽镇上的主要食物来源。这起初只是一次实用的害虫清理赏金任务，却引出了一个令人不安的生态问题：为什么海岸生物会定居在如此深入内陆的山区？",h="湖畔镇的码头管理员巴伦需要冒险者们去减少止水湖沿岸不断增多的鱼人数量，以防它们耗尽镇上的主要食物来源。这起初只是一次实用的害虫清理赏金任务，却引出了一个令人不安的生态问题：为什么海岸生物会定居在如此深入内陆的山区？",kw={"码头管理员巴伦","矮人钓鱼竿","止水湖","湖畔镇","鱼人的鳍","偷猎者","赤脊山"},ang={["faction:Alliance"]="湖畔镇本已深受黑石兽人和豺狼人的困扰，导致这座联盟城镇几乎没有多余的防御力量来保卫其在止水湖的重要食物供应。",["race:Human"]="赤脊山曾经是暴风城王国的宁静度假胜地；看到它那原始的山间水域被敌对的鱼人所占据，凸显出秩序已经崩坏到了何种程度。"},sec={{t="对小镇粮仓的威胁",b="止水湖是湖畔镇的生命线，它不仅喂养着这座山中小镇，还为市场供应新鲜的渔获。当大群鱼人开始在浅滩抛锚定居时，码头管理员巴伦意识到小镇面临着一场生态危机。这些贪婪的鱼人正在疯狂地扫荡水域，如果放任不管，它们将彻底消灭当地的鱼群。"},{t="奇怪的内陆迁徙",b="鱼人通常是海岸上的食腐生物，它们大规模出现在高海拔的赤脊山是一个异常现象。码头管理员巴伦公开表示，他很纳闷它们为什么会离开茫茫大海来到这么远的地方。无论是被海洋捕食者驱赶、逃避领地争端，还是被止水湖富饶的水域所吸引，它们的迁徙暗示着该地区其他地方发生了更深层次的变故。"}},faq={{q="码头管理员巴伦是谁？",a="码头管理员巴伦负责监管湖畔镇止水湖岸边的码头和渔业交通。他处理水上物资，并雇佣冒险者来保卫湖泊资源，抵御水生威胁。",al={"巴伦","谁发布鱼人偷猎者任务","码头管理员巴伦"}},{q="为什么赤脊山会有鱼人？",a="鱼人通常栖息在海岸和沼泽地，因此它们出现在高海拔的止水湖是很不寻常的。码头管理员巴伦推测，这些鱼人部落迁徙到深入内陆的地方，是因为它们在逃避海岸上更糟糕的东西。",al={"为什么止水湖有鱼人","赤脊山内陆鱼人","为什么湖里有鱼人"}},{q="鱼人对湖畔镇构成了什么威胁？",a="湖畔镇的捕鱼业和商业极其依赖止水湖。鱼人部落正在疯狂过度捕捞，威胁到了小镇的主要食物来源，并扰乱了当地经济。",al={"为什么要杀鱼人","湖畔镇鱼人问题","止水湖鱼群减少"}},{q="为什么码头管理员巴伦要收集鱼人鳍？",a="巴伦收集八个鱼人鳍作为捕杀的实物证明。这些鳍证实了冒险者正在积极减少岸边的鱼人数量，并震慑了那些入侵的部落。",al={"为什么要收集鱼人鳍","湖畔镇鱼鳍赏金"}},{q="是否还有其他关于止水湖鱼人的任务？",a="是的，码头管理员巴伦还提供一个配套任务“卖鱼”，该任务要求冒险者为他带来湖中著名的斑点太阳鱼，这些鱼可以通过垂钓获得，也可以从鱼人身上夺取。",al={"卖鱼任务关联","赤脊山其他鱼人任务"}},{q="码头管理员巴伦对清理偷猎者给予什么奖励？",a="在收到八个鳍后，码头管理员巴伦会奖励冒险者一把做工精良的矮人钓鱼竿，以鼓励他们妥善管理湖泊水域。",al={"鱼人偷猎者任务奖励","矮人钓鱼竿任务"}}},fx={["04b19c02"]={q="码头管理员巴伦为什么要猎杀鱼人？",a="巴伦负责管理止水湖的码头和渔业。湖岸边不断扩大的鱼人群落正肆意偷捕，威胁着小镇赖以为生的主要食物来源；再不阻止它们，湖里的鱼很快就会被捕尽。",al={"巴伦的动机","为什么要清剿鱼人","为什么要杀偷猎者"}},["38e35746"]={q="鱼人的鳍有什么用？",a="鱼人的鳍是证明你完成了清剿的实物凭证。巴伦并没有打算拿它们制作什么特殊工艺品或炼金物品；收集八片割下来的鳍，只是为了确认你确实赶走了那些正在耗尽止水湖鱼群的偷猎者。",al={"鱼人的鳍有什么用","鱼人的鳍是做什么的","为什么要收集鱼人的鳍"}},["4daf19f8"]={q="止水湖的鱼人偷猎者是什么人？",a="你要猎杀的是聚集在止水湖东岸、不断侵入当地的鱼人。这些两栖捕食者通常远离海岸，如今却开始在湖边建立营地，吞食湖中的淡水鱼。",al={"偷猎者是什么人","鱼人偷猎者的目标","止水湖的鱼人为什么在这里"}}},fp="15,317,29.394.0,24.401.0,24.209.0,38.253.0,45.211.0,46.189.0,57.185.0,65.166.0"}
P.entries["quest:1501"] = {n="虚空中的生物",s="“虚空生物”是奥格瑞玛术士学徒的一次关键成人礼。为了拓展学徒的召唤能力，使其能够召唤出虚空行者，甘鲁尔·血眼派遣这名术士前往骷髅石，从隐藏在那里的火刃氏族邪教徒手中夺回被窃的维尔加石板。",h="“虚空生物”是奥格瑞玛术士学徒的一次关键成人礼。为了拓展学徒的召唤能力，使其能够召唤出虚空行者，甘鲁尔·血眼派遣这名术士前往骷髅石，从隐藏在那里的火刃氏族邪教徒手中夺回被窃的维尔加石板。",kw={"火刃氏族","cleft of shadow","虚空生物","甘鲁尔·血眼","奥格瑞玛","骷髅石","维尔加石板","虚空行者","术士任务"},ang={["class:Warlock"]="这场试炼标志着部落术士的一次基本成人礼，使他们从只能指挥小鬼进阶为能指挥前线阴影仆从的强者。",["faction:Horde"]="虽然萨尔的部落普遍不信任邪能使用者，但像甘鲁尔这样的导师致力于确保那些研究黑暗艺术的人完全是为了大酋长的利益而使用他们的力量。",["race:Orc"]="对于那些被暗影议会历史所困扰的兽人来说，追捕火刃氏族可以让他们向那些仍拥抱恶魔毁灭的人进行一定程度的复仇。"},sec={{t="危险的技艺",b="在奥格瑞玛大断崖（Cleft of Shadow）的地底阴影中，甘鲁尔·血眼注视着部落术士们的修行。在萨尔的新疆域中，邪能魔法因其与兽人氏族黑暗历史的牵连，而受到深深的猜忌。甘鲁尔承认，部落中真正的术士所剩无几，但他坚持认为，他们所掌握的危险技能对于部落的生存至关重要。若想效忠大酋长，学徒不能仅仅依赖小鬼的混沌烈焰；他们必须学会驾驭这些纯粹由阴影与耐力构成的生物。"},{t="被窃的石板",b="召唤虚空行者需要维尔加石板上铭刻的特殊符文。不幸的是，这件圣物被火刃氏族洗劫了，这是一个在大酋长眼皮底下、潜伏在骷髅石洞穴中的疯狂阴影教派。甘鲁尔派遣他的学生深入教徒的巢穴，夺回石板，并给这些玷污了所有术士名声的叛徒以沉痛的打击。"}},faq={{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是一位资深的术士训练师，位于奥格瑞玛下方的大断崖（Cleft of Shadow）。他负责指导年轻的部落术士，教授他们如何安全地驾驭黑暗力量并束缚异界仆从，而不受腐蚀的影响。",al={"甘鲁尔","甘鲁尔·血眼","谁发布了这个任务"}},{q="维尔加石板是什么？",a="维尔加石板是一件刻有特殊召唤符文的圣物，是召唤虚空行者从虚空降临所必需的物品。它被火刃氏族窃取，必须将其夺回，甘鲁尔才能引导学徒完成仪式。",al={"维尔加石板","石板是什么"}},{q="骷髅石在哪里？",a="骷髅石是一个阴暗的洞穴，位于奥格瑞玛的正东方，沿着杜隆塔尔崎岖的悬崖分布。它是火刃氏族教徒的秘密藏身处。",al={"骷髅石位置","骷髅石在哪里","在哪里寻找石板"}},{q="为什么甘鲁尔·血眼鄙视火刃氏族？",a="火刃氏族公开侍奉恶魔主宰，并积极破坏萨尔的部落。甘鲁尔认为他们是大酋长不可容忍的祸患，也是一种不计后果的毒瘤，给所有修习此道的术士带来了怀疑与恶名。",al={"火刃氏族术士","为什么讨厌火刃氏族"}},{q="为什么术士需要召唤虚空行者？",a="虚空行者是来自虚空的生物，能够承受巨大的伤害并保护召唤者免受伤害。掌握束缚虚空行者的方法标志着术士在实战生存与召唤能力上的重要飞跃。",al={"为什么需要虚空行者","虚空行者的用途"}},{q="夺回石板后会发生什么？",a="一旦甘鲁尔收到维尔加石板，他就会向学徒提供必要的符文，并召唤他们完成“束缚”仪式，在那场仪式中，术士必须亲自制服所召唤的虚空行者以将其掌控。",al={"后续任务","what comes next"}}},fx={b65e3db1={q="甘鲁尔·血眼为什么想让你完成这件事？",a="甘鲁尔·血眼深感部落中的术士所剩无几。他认为，促使你这样的有潜力的侍僧尽快成长，对部落和大酋长至关重要。夺回被盗的维尔加石板，不但能让你学会召唤虚空行者的符文，推进你的修行，也能打击盗走石板的火刃氏族教徒；这些人不断玷污所有术士的名声。",al={"甘鲁尔的动机","甘鲁尔为什么派你去","为什么要找回石板"}},["6701b0d8"]={q="你要去骷髅石对付谁？",a="你要对付的是藏身于奥格瑞玛以东骷髅石的火刃氏族教徒。这些叛党的术士密谋反抗部落，还从甘鲁尔手中偷走了维尔加石板。他们潜伏在杜隆塔尔的阴影中，施展不受大酋长律法约束的恶魔法术，不断给这个年轻的国家制造麻烦。",al={"骷髅石里有什么人","骷髅石的火刃氏族","谁偷走了石板"}},["2e9ce581"]={q="为什么甘鲁尔·血眼派你去，而不让城里的卫兵处理？",a="暗火营地在萨尔的奥格瑞玛只能在紧张的默许下活动。若叫城卫军追查被盗的秘术神器，甘鲁尔那些隐秘行事就会受到不必要的审视。更重要的是，骷髅石的考验是检验你力量增长的必要试炼：术士必须证明自己有能力直面恶魔腐化，才能获准召唤并束缚虚空生物。",al={"为什么派学徒去","为什么不派卫兵","为什么让我去对付虚空生物"}}},fp="20,320,16.544.0,17.411.0,24.261.0,28.230.0,20.167.0,52.242.0,44.237.0,41.229.1"}
P.entries["quest:1502"] = {n="索恩格瑞姆·火眼",s="在完成防御战术的初步训练后，部落战士会被指引穿过贫瘠之地，去寻找瑟恩格瑞姆·火眼。这位深居简出的武器大师在十字路口以东的荆棘岭崎岖山脊上设立了他的营地。对于寻求与自己日益增长的实力相匹配的武器的战士来说，找到他是一次成长的试炼。",h="在完成防御战术的初步训练后，部落战士会被指引穿过贫瘠之地，去寻找瑟恩格瑞姆·火眼。这位深居简出的武器大师在十字路口以东的荆棘岭崎岖山脊上设立了他的营地。对于寻求与自己日益增长的实力相匹配的武器的战士来说，找到他是一次成长...",kw={"铁匠","十字路口","锻造钢材","贫瘠之地","荆棘岭","瑟恩格瑞姆·火眼","犹塞克","战士武器"},ang={["class:Warrior"]="每一位年轻的部落战士都会被送往荒野去寻找瑟恩格瑞姆，并获得一件标志性的锻造武器，以完善他们的战斗训练。",["faction:Horde"]="部落不仅依靠庞大的人数，还依靠那些技艺精湛的老工匠，他们为保卫卡利姆多的前线士兵打造优质的钢材。",["profession:Blacksmithing"]="瑟恩格瑞姆代表了兽人独有的铁匠传统，他无惧孤独和失明，致力于将灼热的金属锻造成致命武器的艺术。"},sec={{t="山脊上的隐士",b="一旦有抱负的战士在像犹塞克这样的资深训练师指导下展示了防御艺术的精通，他们就会被告知要用合适的钢铁来磨练自己的武艺。常规的军械库只能让前线战士走到这一步；真正的大师境界需要由一位享有盛誉的工匠量身打造的武器。在贫瘠之地那严酷的草原上，那位铁匠就是瑟恩格瑞姆·火眼，一位年迈的兽人隐士，他退出了定居点的生活，在平原高处维持着一座与世隔绝的熔炉。"},{t="炉火中的一生",b="要找到瑟恩格瑞姆，需要攀登荆棘岭，这是一座位于十字路口以东、有野生迅猛龙和敌对野猪人出没的崎岖山丘。这位铁匠远离城镇围墙的庇护，将他独处的时光完全奉献给了金属锻造。数十年来盯着灼热的炉火使他的视力受损，但他的直觉依然敏锐。当有流浪者攀上高地打扰他的清修时，火眼早就知道原因：战士是来寻求锻造钢材的。"}},faq={{q="是谁派遣战士去寻找瑟恩格瑞姆·火眼？",a="该任务由犹塞克指派，他是一位驻扎在东贫瘠之地前沿哨所附近道路旁的战士训练师，在你展示了防御训练成果后即可领取。",al={"谁提供此任务","瑟恩格瑞姆·火眼任务开启者","任务发布者"}},{q="瑟恩格瑞姆·火眼位于哪里？",a="瑟恩格瑞姆居住在贫瘠之地十字路口正东的一处高耸山脊——荆棘岭上的一处孤立营地中。",al={"瑟恩格瑞姆的位置","瑟恩格瑞姆在哪里","寻找火眼"}},{q="为什么瑟恩格瑞姆独自住在山里？",a="他将自己的毕生精力完全投入到了远离城镇喧嚣的金属工艺中。尽管周围的山脊上有危险的野兽和野猪人出没，他依然独自在荆棘岭上专注于铁砧旁的工作。",al={"为什么瑟恩格瑞姆是隐士","火眼隐士"}},{q="瑟恩格瑞姆·火眼的眼睛怎么了？",a="数十年来在炽热的煤炭上不断工作，并直视强烈的熔炉热浪，这使得他的视力大受损伤，几近失明。",al={"瑟恩格瑞姆失明了吗","火眼的眼睛"}},{q="见到瑟恩格瑞姆·火眼之后会发生什么？",a="一旦你向瑟恩格瑞姆汇报，他就会意识到你需要武器，并提供任务“锻造钢材”，要求你收集原材料以便他为你打造武器。",al={"下一个任务","见到瑟恩格瑞姆后","锻造钢材后续"}},{q="任何职业都能接这个任务吗？",a="不能。这个任务线是专为寻求特制武器的部落战士而设计的试炼。",al={"这是战士专属吗","谁能做瑟恩格瑞姆·火眼任务"}}},fx={["65de68fe"]={q="为什么犹塞克让你去找萨恩格瑞姆·火眼？",a="犹塞克知道，光有武艺训练，没有合适的装备，战士也难以保住性命。战士的武器必须以最高标准锻造，而萨恩格瑞姆·火眼以精湛的技艺闻名于部落。犹塞克让你去找他，好让你凭自己的本事赢得一把配得上日益增长的力量的武器。",al={"为什么要找萨恩格瑞姆","犹塞克让你找萨恩格瑞姆的动机","为什么要去见萨恩格瑞姆·火眼"}}},fp="18,344,23.514.0,24.488.0,46.169.0,36.117.0,47.206.0,43.140.0,44.162.0,30.111.0"}
P.entries["quest:1503"] = {n="锻造好的钢锭",s="兽人铁匠Thun'grim Firegaze需要帮助，从附近的野猪人营地找回被偷走的金属制品。作为找回他珍贵的锻造好的钢锭的回报，他愿意为一位初露锋芒的战士打造一件精良的武器。",h="兽人铁匠Thun'grim Firegaze需要帮助，从附近的野猪人营地找回被偷走的金属制品。作为找回他珍贵的锻造好的钢锭的回报，他愿意为一位初露锋芒的战士打造一件精良的武器。",kw={"贫瘠之地","firegaze","锻造好的钢锭","铁箱","野猪人","razormane","钢锭","thun'grim","战士武器"},ang={["class:Warrior"]="这项任务标志着早期一个重要的成人礼，教导战士们找回重要的军事补给，并在获得他们第一件定制武器之前证明自己的价值。",["faction:Horde"]="Razormane部族对整个贫瘠之地的补给线和独立营地构成了持续的困扰，因此反击袭击是保卫部落边疆的必要手段。",["profession:Blacksmithing"]="Thun'grim对高质量锻造好的钢锭的依赖，展现了部落在卡利姆多严酷且资源匮乏的边境地区对精炼冶金术的持续需求。"},sec={{t="利用盲点",b="Thun'grim Firegaze在贫瘠之地东部崎岖的山脊上安营扎寨，作为一名护甲商和铁匠，远离了奥格瑞玛繁忙的锻造工坊。尽管他精神矍铄，但长年累月盯着熔炉的火焰，使他的视力大受损伤。邻近的Razormane野猪人察觉到了这一弱点，趁着夜色潜入了他的营地。他们故意在一侧制造噪音并发出哼哼声，引开了他模糊的视线，随后一伙窃贼从另一侧溜了进去，偷走了一箱装满他准备好的锻造好的钢锭的铁箱。"},{t="无价的金属，无知的窃贼",b="虽然Thun'grim对这种盗窃行为感到愤怒，但他并不担心Razormane野猪人真能用好这些金属。野猪人的工艺通常依赖原始的石头、磨尖的獠牙和多刺的根茎，而非先进的冶金术。沉重的铁箱在他们营地里一辆破旧的马车旁完好无损，对野猪人来说毫无用处，但对于急需为部落的年轻战士锻造战备装备的兽人护甲商来说，却是无价之宝。"}},faq={{q="Thun'grim Firegaze是谁？",a="Thun'grim Firegaze是一位资深的兽人护甲商和武器匠，住在贫瘠之地东部的一个小营地里。尽管视力下降，他依然坚持从事锻造工艺，并帮助训练和武装有抱负的部落战士。",al={"thungrim firegaze","铁匠是谁","thungrim"}},{q="野猪人为什么要偷钢锭？",a="Razormane野猪人是机会主义的拾荒者，经常袭击贫瘠之地的旅行者和哨所。他们利用夜间的声东击西战术抢走了铁箱，仅仅是为了洗劫这位虚弱的铁匠，尽管他们缺乏锻造知识，无法加工里面的锻造好的钢锭。",al={"为什么要偷金属","野猪人为什么要偷东西","razormane想要什么"}},{q="锻造好的钢锭存放在哪里？",a="钢锭仍锁在“偷来的铁箱”里，被遗弃在Thun'grim营地西北方向Razormane野猪人领地内的一辆破马车旁。",al={"箱子在哪里","被偷的铁箱位置","钢锭在哪里"}},{q="Thun'grim会提供什么武器作为回报？",a="为了换回他储存的优质钢材，Thun'grim愿意为年轻的战士提供一些刚锻造好的武器，助他们在卡利姆多的试炼中一臂之力。",al={"武器奖励","我能得到什么","锻造好的钢锭奖励"}},{q="Razormane是如何骗过Thun'grim的？",a="野猪人利用了Thun'grim视力衰退的弱点。几名劫掠者在远处发出巨大的哼哼声来吸引他的注意力，让其他人得以潜入他的营地，在未被发现的情况下拖走了铁箱。",al={"他们是如何抢劫他的","thungrim是如何被抢的","分散thungrim的注意力"}},{q="为什么Thun'grim住在贫瘠之地而不是奥格瑞玛？",a="Thun'grim在俯瞰贸易路线的干旱丘陵中维持着一个孤立的哨所，作为护甲商和导师，为从杜隆塔尔前往贫瘠之地这一更广阔试炼之地的战士们提供服务。",al={"为什么thungrim在这里","为什么在贫瘠之地驻扎"}}},fx={["46a881ef"]={q="为什么萨恩格瑞姆·火眼要你找回钢锭？",a="萨恩格瑞姆是位大师级铁匠，像这些锻造好的钢锭这样的优质加工金属，对他的手艺至关重要。猪鼻子的窃贼竟敢在他眼皮底下偷走物资，伤了他的自尊；更糟的是，这还夺走了他锻造武器所需的材料。在失窃的存货归还之前，他不会交出自己锻造的武器。",al={"为什么要找回锻造好的钢锭","萨恩格瑞姆的动机","萨恩格瑞姆为什么想要回钢锭"}},["4f2d7c31"]={q="为什么萨恩格瑞姆要你去取回钢锭，而不是亲自前往？",a="萨恩格瑞姆年事已高，视力严重衰退；剃刀沼泽野猪人正是趁他看不清时抢劫了他。他看不清路，无法追踪野猪人进入荆棘丛生的巢穴，也难以与他们正面交战，所以只能依靠你这样的能干战士深入野猪人营地，取回被盗的箱子。",al={"萨恩格瑞姆为什么不能自己取回钢锭","为什么派我去找萨恩格瑞姆","萨恩格瑞姆为什么需要帮忙"}},["758f9f11"]={q="持有钢锭的剃刀沼泽野猪人是什么人？",a="这些窃贼属于贫瘠之地的剃刀沼泽野猪人部族，是凶残的猪形类人生物。他们好斗且领地意识极强，在平原各处布满尖刺的荆棘营地中聚居，还常常袭击旅人和偏僻营地，掠走能找到的物资；不过，他们通常并不懂得如何加工锻造好的钢材这类精制材料。",al={"剃刀沼泽野猪人是什么人","西北方的野猪人","谁偷了铁箱"}}},fp="12,227,22.589.0,33.492.0,26.217.0,37.296.0,37.157.0,43.160.0,49.222.0,64.208.0"}
P.entries["quest:1504"] = {n="誓缚",s="“束缚”是奥格瑞玛的部落年轻术士在寻求虚空行者指挥权时，所要经历的最后入门仪式。在甘鲁尔·血眼的指导下，学徒需要在Neeru Fireblade的召唤法阵中刻画出自维尔加石板的召唤铭文，以召唤、制服并永久奴役一只虚空生物。",h="“束缚”是奥格瑞玛的部落年轻术士在寻求虚空行者指挥权时，所要经历的最后入门仪式。在甘鲁尔·血眼的指导下，学徒需要在Neeru...",kw={"cleft of shadow","甘鲁尔·血眼","召唤铭文","neeru fireblade","奥格瑞玛","维尔加石板","束缚","虚空行者","术士"},ang={["class:Warlock"]="这项仪式标志着术士从摆弄琐碎的小鬼提升到指挥前线阴影恐怖，巩固了权力必须被征服和奴役的无情哲学。",["faction:Horde"]="虽然萨尔的部落官方背弃了过去的恶魔腐化，但在奥格瑞玛下方，术士魔法的实用必要性仍在监视下被容忍。",["race:Orc"]="兽人术士在Cleft of Shadow这样的隐秘角落里活动，远离大酋长萨尔和萨满教复兴的非议目光，练习着他们的黑暗艺术。"},sec={{t="虚空的征服",b="对于潜伏在Cleft of Shadow阴暗隧道中的术士学徒来说，召唤小鬼只不过是小儿科。制服虚空行者才是对意志力和奥术统治力的第一次真正考验。术士不会与这些来自异界的恐怖生物签订温和的契约或进行沟通；他们通过纯粹的力量将其从维度中强行拉出，并将其束缚在永恒的奴役之中。甘鲁尔·血眼要求学徒利用从维尔加石板上抄录的铭文，将怪物直接召唤到Neeru Fireblade的仪式法阵中，并通过单打独斗将其击败。"},{t="无尽的警惕",b="在物理和魔法战斗中战胜实体仅仅是战斗的一半。正如甘鲁尔·血眼所警告的那样，被束缚的虚空行者永远不会真正接受它的奴役。虽然它在战斗中能作为主人坚实、阴影般的盾牌，但它永远都在寻找主人精神松懈的时刻。术士必须始终保持对仆从坚定不移的精神控制，因为一旦纪律松懈，虚空行者就会乐于吞噬那个束缚它的人的灵魂。"}},faq={{q="召唤的是什么样的生物？",a="学徒召唤的是虚空行者，这是一种由纯粹的宇宙阴影和虚空能量锻造而成的庞大存在。不同于调皮的小鬼（恶魔），虚空行者是从扭曲虚空和虚空中强行撕裂而来的粗暴实体，术士主要利用它们来吸收毁灭性的物理攻击。",al={"召唤的是什么","是什么恶魔","虚空行者背景"}},{q="这个召唤仪式在哪里进行？",a="仪式在位于奥格瑞玛下方Cleft of Shadow内的Neeru Fireblade帐篷里进行。地面上绘制的特定召唤法阵聚焦了从扭曲虚空中撕裂虚空行者所需的维度能量。",al={"我在哪里召唤","召唤法阵位置","仪式地点"}},{q="维尔加石板有什么用？",a="维尔加石板记载着将虚空行者显现并从现实结构中撕裂所需的古老、特殊的铭文。学徒通过研究其铭文来制作建立召唤法阵所需的召唤铭文。",al={"维尔加石板","召唤铭文"}},{q="为什么术士必须击败虚空行者？",a="术士通过绝对的统治力来控制异位面生物。在虚空行者交出其本质并服从命令之前，召唤者必须通过物理和魔法手段将其击败并使其屈服，以证明自己的支配地位。",al={"为什么杀死虚空行者","为什么要与它战斗","束缚过程"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是部落的一位高级术士训练师，驻扎在奥格瑞玛Cleft of Shadow的阴暗洞穴中。他负责监督部落年轻从业者的黑暗教育，教导他们如何奴役更强大的恶魔实体。",al={"甘鲁尔是谁","甘鲁尔·血眼"}},{q="被束缚的虚空行者可以完全信任吗？",a="绝不能。正如甘鲁尔指出的，即使是一个已经服役多年且没有反抗的虚空行者，也只是在等待主人放松警惕。这种纽带需要时刻保持警惕，因为该生物对囚禁它的人怀有永恒的怨恨。",al={"虚空行者会背叛我吗","虚空行者忠诚吗","恶魔会反叛吗"}}},fx={["066e41c9"]={q="甘鲁尔·血眼为什么想让你完成这件事？",a="甘鲁尔·血眼是聚集在暗影裂口的有潜力术士们的教官。他通过督促你拓展黑暗魔法的技艺，考验并锤炼你的自律。若要为部落驾驭更强大的邪能，你就必须证明自己掌握了召唤并支配强韧虚空行者的本领。",al={"甘鲁尔·血眼的动机","甘鲁尔为什么要召唤虚空行者","甘鲁尔为什么要我束缚虚空行者"}},["3b87ecbf"]={q="为什么甘鲁尔·血眼让你亲自与虚空行者战斗？",a="召唤出的仆从只能靠驾驭它的术士以强大的意志和力量束缚。甘鲁尔·血眼和城卫军都无法让恶魔的意志屈服于你。你必须凭借自己的魔法与武力战胜它，证明你的心智和灵魂足够强大，能够将它奴役。",al={"为什么要独自对抗虚空行者","甘鲁尔为什么不能对付虚空行者","为什么让我去束缚虚空行者"}}},fp="11,326,23.564.0,17.457.0,40.290.0,44.249.0,37.244.0,43.227.0,24.242.0,45.244.0"}
P.entries["quest:1505"] = {n="老兵犹塞克",s="“老兵犹塞克”是一项部落任务，旨在引导有前途的年轻战士寻找经验丰富的战斗导师。犹塞克驻扎在杜隆塔尔与贫瘠之地交界处的前沿哨所以南，他教导新兵们真正的武道成就既需要刻苦的钻研，也需要强大的力量。",h="“老兵犹塞克”是一项部落任务，旨在引导有前途的年轻战士寻找经验丰富的战斗导师。犹塞克驻扎在杜隆塔尔与贫瘠之地交界处的前沿哨所以南，他教导新兵们真正的武道成就既需要刻苦的钻研，也需要强大的力量。",kw={"贫瘠之地","战斗指导","杜隆塔尔","前沿哨所","部落","犹塞克","老兵犹塞克","战士"},ang={["class:Warrior"]="年轻的战士被派往犹塞克那里是为了学习单靠蛮力是不够的，真正的力量源于成为一名专注的战斗学徒。",["faction:Horde"]="部落将武技视为最高荣誉，并依靠驻扎在边境哨所的经验丰富的战斗老兵来指导下一代。"},sec={{t="战士之道",b="在部落的文化中，武力是毋庸置疑并受到最高尊崇的。然而，仅靠蛮力并不能造就一名勇士。经验丰富的指挥官们都知道，最伟大的战士同时也是谦逊的学徒，他们愿意通过纪律和学习来磨练自己的本能。渴望超越基础训练的战士会被引导去寻找那些经历过战争洗礼的老兵。"},{t="边境的老兵",b="为了获得进阶的战斗指导，年轻的战士们会前往杜隆塔尔和贫瘠之地之间干旱的边境地带。犹塞克就驻扎在监视着东部边境的兽人据点——前沿哨所以南。作为身经百战的老兵，犹塞克现在将他的余年投入到对有前途的新兵进行战斗和战术生存要义的指导中。"}},faq={{q="老兵犹塞克是谁？",a="犹塞克是一位久经沙场的部落老兵，专门负责指导年轻战士的战斗技巧。在经历过无数次交战后，他现在在靠近杜隆塔尔和贫瘠之地边境的营地里传授他来之不易的武学智慧。",al={"犹塞克是谁","犹塞克背景故事","这位老兵是谁"}},{q="在哪里可以找到犹塞克？",a="犹塞克位于前沿哨所以南，该兽人据点位于杜隆塔尔和贫瘠之地的东部边界沿线。",al={"犹塞克在哪里","犹塞克位置","寻找犹塞克"}},{q="什么是前沿哨所？",a="前沿哨所是一座标志着贫瘠之地东部边界的兽人据点，守卫着从杜隆塔尔进入该地区的通道，并作为部落的防御阵地。",al={"什么是前沿哨所","前沿哨所用途"}},{q="为什么年轻战士会被派往犹塞克那里？",a="渴望进步的战士会去寻找犹塞克以寻求战斗指导。在部落中，虽然力量不容置疑，但真正伟大的战士必须同时掌握钻研精神和武技。",al={"为什么要拜访犹塞克","犹塞克传授什么","战士指导"}},{q="当你抵达时犹塞克会说什么？",a="当抵达他的营地时，犹塞克会热情地迎接这些年轻战士，准备开始评估他们的决心，并传授他们战争之道。",al={"与犹塞克对话会发生什么","犹塞克任务交付"}},{q="部落如何看待他们的战士？",a="部落因其战士不可磨灭的力量和对武道的奉献而尊崇他们，但文化传统强调，真正的掌握需要纪律以及向经验丰富的老兵学习。",al={"谁尊崇战士","部落战士文化"}}},fp="13,283,23.417.0,25.376.0,21.229.0,25.131.0,23.163.0,37.195.0,36.143.0,37.194.0"}
P.entries["quest:1506"] = {n="甘鲁尔的召唤",s="甘鲁尔的召唤是奥菲克在剃刀岭传达给年轻部落术士的一项紧急征召。资深术士甘鲁尔·血眼要求他们立即前往暗影裂口，以提升他们的训练水平。这标志着掌握召唤虚空行者这一黑暗艺术的第一步。",h="甘鲁尔的召唤是奥菲克在剃刀岭传达给年轻部落术士的一项紧急征召。资深术士甘鲁尔·血眼要求他们立即前往暗影裂口，以提升他们的训练水平。这标志着掌握召唤虚空行者这一黑暗艺术的第一步。",kw={"血眼","cleft of shadow","甘鲁尔","奥菲克","奥格瑞玛","召唤","虚空行者","术士任务"},ang={["class:Warlock"]="这次召唤标志着你跨过了基础小鬼召唤的阶段，开启了指挥强壮的虚空行者作为护卫的道路。",["faction:Horde"]="术士在萨尔领导的新部落中处境不安，他们因其实用力量而受到容忍，但被隔离在奥格瑞玛的地底深处。"},sec={{t="召唤暗影",b="在杜隆塔尔活动的初级术士很快就会引人注意。一旦修行者证明了他们对初始小鬼的驾驭能力，消息就会传到奥格瑞玛地下的深处。驻扎在杜隆塔尔的奥菲克充当了暗影施法者的信使，他会拦截那些术士，并要求他们放下手头的一切工作，立即向暗影裂口报到。"},{t="资深术士",b="甘鲁尔·血眼负责监管部落中兽人术士新手的训练。他在奥格瑞玛下方的隐蔽洞穴中工作，在磨练致命的邪能力量与防止这些危险艺术被大酋长不赞成的目光发现之间保持着微妙的平衡。当血眼召唤学徒到他的圈子里时，这就意味着简单的火焰法术和小鬼已不再足够；是时候从扭曲虚空束缚一只生物了。"}},faq={{q="奥菲克是谁？",a="奥菲克是驻扎在杜隆塔尔的术士们的同僚。他负责追踪不断成长的修行者，并传递像甘鲁尔·血眼这样的资深导师下达的命令。",al={"奥菲克","谁发布此任务","任务发布者"}},{q="甘鲁尔·血眼在哪里？",a="甘鲁尔·血眼居住在暗影裂口，那是隐藏在奥格瑞玛岩石高原之下的地下洞穴系统。",al={"甘鲁尔在哪里","甘鲁尔位置","寻找甘鲁尔·血眼"}},{q="甘鲁尔·血眼为什么要见我？",a="甘鲁尔认为你已经足够老练，可以继续你的术士研究，并开始召唤和束缚虚空行者所需的危险仪式了。",al={"为什么要召唤","甘鲁尔想要什么","任务缘由"}},{q="向甘鲁尔报到后会发生什么？",a="向甘鲁尔报到后将开始任务“虚空生物”，该任务会指引你获取将虚空实体拉入艾泽拉斯所必需的材料与知识。",al={"下一个任务","甘鲁尔的召唤之后是什么"}},{q="为什么术士们待在暗影裂口？",a="术士们修习不稳定的邪能魔法，萨尔和传统的萨满教派部落对此怀有深深的怀疑。暗影裂口让他们可以在公众视野之外进行仪式。",al={"为什么在暗影裂口","为什么术士要躲藏","奥格瑞玛术士洞穴"}},{q="任何职业都能接这个任务吗？",a="不能。此任务仅提供给已达到训练第十等级的部落术士。",al={"这是术士专属吗","谁能接到此任务"}}},fx={f5421555={q="奥菲克为什么派你去找甘鲁尔？",a="奥菲克只是甘鲁尔·血眼的跑腿和信使。大断崖的资深术士不会在奥格瑞玛四处寻找学徒，而是派手下去把需要的人带来。奥菲克知道不能耽搁甘鲁尔的召唤，因此提醒你，让术士大师久等通常不会有好下场。",al={"奥菲克为什么派我去","奥菲克的动机","奥菲克为什么传达召唤"}}},fp="17,290,24.399.0,18.455.0,13.157.0,34.132.0,41.147.0,40.163.0,48.182.0,30.108.0"}
P.entries["quest:1507"] = {n="噬魂者",s="“噬魂者”是一位有抱负的部落术士在召唤并驾驭魅魔的旅程中最初的任务。该任务由深藏在Cleft of Shadow中的甘鲁尔·血眼提供，他会指引修炼者穿过洞穴，向古老的术士卡祖尔请教如何诱捕并束缚这种狡诈的恶魔。",h="“噬魂者”是一位有抱负的部落术士在召唤并驾驭魅魔的旅程中最初的任务。该任务由深藏在Cleft of Shadow中的甘鲁尔·血眼提供，他会指引修炼者穿过洞穴，向古老的术士卡祖尔请教如何诱捕并束缚这种狡诈的恶魔。",kw={"束缚","卡祖尔","cleft of shadow","甘鲁尔·血眼","奥格瑞玛","魅魔","召唤","术士"},ang={["class:Warlock"]="该任务标志着你开始转而指挥那些擅长精神控制与诱惑的恶魔，这不仅需要强大的邪能，更需要坚定的意志。",["faction:Horde"]="与萨尔的部落中那些公开活动的萨满祭司和战士不同，术士必须在Cleft of Shadow潮湿而隐秘的缝隙中，隐秘地进行这些危险的仪式。"},sec={{t="步入魅影",b="已经掌握了小鬼和虚空行者等低阶恶魔的部落术士们，最终会发现单纯的蛮力已不再够用。甘鲁尔·血眼是奥格瑞玛地下黑暗艺术的监管者，他会判断术士何时已准备好从扭曲虚空之中召唤魅魔——这种生物以诱导意志薄弱者自相残杀而臭名昭著。束缚这种恶魔需要的是狡黠的手段，而非纯粹的力量。"},{t="卡祖尔的传说",b="由于魅魔以凡人的欲望为食，因此单凭原始的咒语是无法将其召唤出来的；必须使用一件注入了纯粹爱意与奉献之情的物品，将其引诱至我们的世界。甘鲁尔本人既不愿也无法提供这样的圣物，因此他指引召唤者去找Cleft of Shadow中潜伏的古老术士卡祖尔，他对于奥术和恶魔仪式的渊博知识将指引仪式的下一阶段。"}},faq={{q="这个任务的目的是什么？",a="“噬魂者”开启了学习召唤魅魔随从所需仪式的一系列部落任务。它会将你与Cleft of Shadow中的导师联系起来，他们会教导你这种恶魔的本质，以及如何将其从扭曲虚空中诱捕出来。",al={"为什么要完成噬魂者","魅魔任务起始","这个任务解锁什么"}},{q="我在哪里能找到卡祖尔？",a="卡祖尔位于Cleft of Shadow内，这是一个隐藏在奥格瑞玛地下的洞穴，城中的潜行者和术士训练师们在这里修炼他们禁忌的艺术，远离大酋长的视线。",al={"卡祖尔位置","卡祖尔在哪里","在奥格瑞玛寻找卡祖尔"}},{q="为什么术士需要用充满爱意的物品来召唤魅魔？",a="魅魔是能够操纵人心的恶魔，它们以凡人的情感、奉献和薄弱的意志为食。为了将它们从扭曲虚空的帷幕另一端引诱过来，召唤者必须先以一件饱含真挚奉献与爱意的强大护身符作为诱饵，然后再压制并束缚该生物。",al={"魅魔诱饵爱意","为什么召唤魅魔需要爱之信物","魅魔召唤传说"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是一位部落资深术士训练师，居住在奥格瑞玛的Cleft of Shadow中。他引导着不断成长的修炼者们，去完成那些危险的仪式，以束缚日益强大的恶魔仆从。",al={"谁提供噬魂者任务","甘鲁尔传说","甘鲁尔·血眼"}},{q="开始这个任务需要什么等级？",a="术士必须达到20级，甘鲁尔·血眼才会认为他们的魔法造诣和精神力量足以支撑他们完成仪式，并从与魅魔的交易中幸存下来。",al={"召唤魅魔所需等级","噬魂者等级要求","魅魔任务链等级要求"}},{q="与卡祖尔交谈后接下来要做什么？",a="与卡祖尔交谈会开启任务“盲目卡祖尔”，该任务会指引召唤者前往奥格瑞玛寻找赞卡沙，她的伴侣多格兰在十字路口执行任务时至今未归。寻找合适爱之信物的旅程就从她开始。",al={"噬魂者后的下一个任务","卡祖尔任务后是什么","魅魔任务流程"}}},fx={["0f1c8f0b"]={q="甘鲁尔·血眼为什么要你召唤魅魔？",a="作为部落大断崖的术士导师之一，甘鲁尔·血眼的职责是引导你掌握更深奥、更强大的黑暗魔法。他认为你具备足够的心智力量和狡诈，能够驯服魅魔，而不会被它的魅惑所迷。对他而言，每成功束缚一个仆从，你们共同施展的恶魔技艺便会扩大影响力，增强杀伤力。",al={"甘鲁尔为什么要这样做","甘鲁尔·血眼的动机","甘鲁尔为什么要召唤魅魔"}},cde5d57b={q="甘鲁尔为什么派你去，而不是自己寻找诱饵？",a="术士无法直接获得对恶魔的绝对掌控；这份束缚必须由你亲自历练，凭借自己的机敏建立。甘鲁尔要你找到所需的爱意信物，并独自迫使恶魔屈服，以此证明自己的价值、确立自身的支配力，而不是依赖他人的力量。",al={"甘鲁尔为什么选我","为什么派我去找魅魔","甘鲁尔为什么不能自己做"}}},fp="17,310,29.439.0,17.417.0,34.243.0,22.207.0,63.268.0,24.207.0,43.181.0,39.224.1"}
P.entries["quest:1508"] = {n="盲眼卡祖尔",s="“盲眼”卡祖尔是部落术士试炼中召唤魅魔的一个过渡步骤。在暗影裂口中听从了导师的指引后，新晋术士会去寻找盲眼术士卡祖尔，他会指出仪式所需的一种强烈情感的载体。",h="“盲眼”卡祖尔是部落术士试炼中召唤魅魔的一个过渡步骤。在暗影裂口中听从了导师的指引后，新晋术士会去寻找盲眼术士卡祖尔，他会指出仪式所需的一种强烈情感的载体。",kw={"盲眼卡祖尔","卡祖尔","cleft of shadow","多格兰","奥格瑞玛","魅魔","术士","赞卡沙"},ang={["class:Warlock"]="这项任务表明，恶魔召唤不仅依赖于邪能魔法，同样也依赖于心理共鸣，需要通过强烈的凡人情感载体来引诱魅魔。",["faction:Horde"]="在暗影裂口深处进行的黑暗艺术在部落首都的地表之下运作，悄无声息地触动着居住在上方平顶山上的普通公民的生活。"},sec={{t="诱惑的真谛",b="奴役一名恶魔仆从不仅仅需要纯粹的意志力；扭曲虚空的某些生物必须依靠其与生俱来的渴望才能穿过虚空的帷幕。众所周知的灵魂吞噬者——魅魔，对凡人的渴望、悲伤和未竟的欲望有着强烈的反应。卡祖尔对此心知肚明，他一眼就能看出这些渴望力量的召唤者为何来寻找他。"},{t="断崖上的双眼",b="尽管双目失明，但卡祖尔对奥格瑞玛红色城墙内上演的平静生活与悲剧仍有着敏锐的洞察力。他并没有直接派术士去战斗，而是指引他们去找住在双足飞龙管理员附近悬崖上的一位兽人女性，名叫赞卡沙。赞卡沙一直在焦急地等待她的伴侣多格兰归来，她心中怀揣的绝望正是恶魔无法抗拒的东西。"}},faq={{q="卡祖尔是谁？",a="卡祖尔是一位盲眼术士，他在奥格瑞玛中安静地生活着。他通过鉴别恶魔召唤所需的试剂和媒介，协助暗影裂口的术士们。",al={"盲眼卡祖尔","卡祖尔是谁"}},{q="为什么卡祖尔让你去找赞卡沙？",a="为了召唤并奴役一只魅魔，新晋术士需要一件浸透了强大凡人渴望或爱情的物品。赞卡沙正因她失踪的伴侣多格兰而痛苦不堪，这使得她与伴侣之间的私人联系成为获取情感诱饵的关键。",al={"为什么找赞卡沙","赞卡沙有什么"}},{q="赞卡沙在奥格瑞玛的什么地方？",a="赞卡沙居住在奥格瑞玛的高地上，位于双足飞龙管理员以西。你可以穿过飞行塔的桥，检查右侧附近的住所来找到她。",al={"赞卡沙位置","赞卡沙在哪里"}},{q="和赞卡沙谈话后会发生什么？",a="赞卡沙因为她的伴侣多格兰失踪而感到痛苦。与她交谈将引导术士前往贫瘠之地寻找他的下落，从而开启一段获取强力爱情信物的任务链。",al={"what comes next","卡祖尔之后的下一步"}},{q="这个任务让你准备召唤什么样的恶魔？",a="这项差事是召唤并奴役魅魔的入会仪式的一部分，魅魔是一种擅长诱惑和精神折磨的恶魔仆从。",al={"哪个宠物","恶魔奖励"}},{q="为什么术士必须利用个人的悲剧来完成他们的仪式？",a="像魅魔这样的下级恶魔会被强烈的凡人情感——尤其是激情、奉献和心碎所吸引。术士会刻意利用那些被悲伤或欲望所玷污的信物，作为召唤仪式上的灵魂诱饵。",al={"术士道德","为什么要利用多格兰"}}},fx={a1700788={q="卡祖尔为什么要你去找赞卡沙？",a="卡祖尔是大断崖阴影中的导师和长者。当甘鲁尔·血眼把一名有志成为术士的人送到他面前时，卡祖尔的职责便是指引你寻找束缚魅魔所需的材料。召唤这种恶魔需要一件承载着爱意与强烈渴望的物品。卡祖尔知道，赞卡沙因伴侣多格兰失踪而悲痛绝望，这份情感正可成为你引诱噬魂者归顺的凭依。",al={"卡祖尔的动机","卡祖尔为什么帮赞卡沙","卡祖尔为什么派我去找赞卡沙"}},fea16628={q="卡祖尔为什么派你去找赞卡沙，而不是亲自前往？",a="这项任务是你成为术士的启蒙仪式，并非普通的城中差事。卡祖尔是一位年迈失明的隐士，居住在奥格瑞玛幽暗的深处，悄然指引新人学习黑暗仪式。术士训练要求你亲自建立束缚，并收集恶魔所需的材料。此外，奥格瑞玛的卫兵不会有兴趣协助被禁止的恶魔仪式，因此追寻这段悲伤往事的重任只能落在你肩上。",al={"卡祖尔为什么选我","为什么派玩家去找赞卡沙","卡祖尔为什么需要我"}}},fp="11,268,22.367.0,18.414.0,13.171.0,35.236.0,40.194.0,39.193.0,57.136.0,63.238.0"}
P.entries["quest:1509"] = {n="多格兰的消息",s="这个任务派遣部落术士从奥格瑞玛的大断崖前往贫瘠之地那片干旱的旷野，寻找一名失踪的步兵，名叫Dogran。他的伴侣赞卡沙在数日的沉默后预感到了最坏的结果，于是派遣施法者前往十字路口询问Dogran的上级。查明Dogran的命运是术士召唤魅魔仪式中至关重要的一步。",h="这个任务派遣部落术士从奥格瑞玛的大断崖前往贫瘠之地那片干旱的旷野，寻找一名失踪的步兵，名叫Dogran。他的伴侣赞卡沙在数日的沉默后预感到了最坏的结果，于是派遣施法者前往十字路口询问Dogran的上级。查明Dogran的...",kw={"贫瘠之地","卡祖尔","十字路口","dogran","加兹罗格","dogran的消息","野猪人","魅魔","赞卡沙"},ang={["class:Warlock"]="这一段旅程将你的训练从奥格瑞玛的黑暗典籍转向了对凡人悲剧的现实利用，以获取一只魅魔。",["faction:Horde"]="这项任务阐述了那些试图保护卡利姆多危险十字路口免受敌对土著威胁的部落步兵所面临的持续危险。",["race:Orc"]="赞卡沙那无声的悲伤揭示了部落在杜隆塔尔和贫瘠之地扩张与防御背后的个人代价。"},sec={{t="伴侣的绝望",b="在奥格瑞玛的断崖上，赞卡沙静静地等待着，心中充满了恐惧。她的伴侣Dogran因获得光荣的晋升而被指派到十字路口，然而他预定的归期已过，却音信全无。她并不知道幕后操纵着复杂黑暗技艺的阴谋，只希望能寻求一名路过的同情者，向他的指挥官加兹罗格打听消息。"},{t="贫瘠之地的惨讯",b="抵达十字路口的中心哨站后，真相令人沮丧。Dogran不仅仅是因为任务而延误；他已经落入了盘踞在平原上的凶残野猪人手中。加兹罗格承认，虽然Dogran还活着，但他被俘的事实是一个残酷的现实，加兹罗格不愿将其传达给赞卡沙。"},{t="召唤的媒介",b="对于一位胸怀大志的术士来说，Dogran的悲剧不仅仅是一次救援任务。召唤并驾驭魅魔（一种被原始激情、绝望和折磨所束缚的生物）的道路，需要触动过真挚情感的圣物。Dogran的苦难以及他与赞卡沙之间的纽带，正是束缚仪式所必需的情感媒介。"}},faq={{q="Dogran是谁？",a="Dogran是一名驻扎在贫瘠之地的兽人步兵，最近被晋升到了十字路口。他也是居住在奥格瑞玛的兽人女性赞卡沙的伴侣。",al={"dogran背景故事","dogran是谁","步兵多格兰"}},{q="为什么术士会关心一名失踪的兽人卫兵？",a="暗影裂口的术士导师们策划了这次搜寻，因为魅魔的束缚仪式需要浸透了深刻凡人情感（如爱、奉献和苦难）的信物。",al={"为什么是术士任务","术士为什么要这么做","魅魔关联"}},{q="加兹罗格在哪里？",a="加兹罗格驻扎在贫瘠之地的十字路口，是负责管理防御当地威胁的部落主要长官之一。",al={"加兹罗格在哪里","加兹罗格位置","十字路口加兹罗格"}},{q="Dogran发生了什么事？",a="Dogran未能在预定时间回到赞卡沙身边。她请求你前往十字路口向加兹罗格打听消息。",al={"dogran死了吗","dogran在哪里","dogran的命运"}},{q="谁发布了这个任务？",a="该任务由奥格瑞玛断崖上的赞卡沙发布，在此之前，术士训练师卡祖尔会指引你去找她。",al={"任务发布者","如何开始dogran的消息"}},{q="这个任务线接下来是什么？",a="继续你在贫瘠之地的调查，了解Dogran的命运并将消息传达下去。",al={"接下来做什么","下一个任务","魅魔任务线后续"}}},fx={["7a20ce20"]={q="赞卡沙为什么要你打听多格兰的消息？",a="多格兰是赞卡沙的伴侣。他对最近的晋升和被派往十字路口的差事满怀自豪，但贫瘠之地远比奥格瑞玛城墙内安全的环境凶险得多。他如今已经逾期一周多仍未归来，而她也没有收到任何消息。她在恐惧与希望之间备受煎熬，再也无法忍受沉默，需要有人找到他的指挥官。",al={"赞卡沙为什么要这样做","赞卡沙的动机","为什么寻找多格兰"}}},fp="14,360,16.351.0,27.315.1,26.332.1,14.164.0,50.192.0,24.141.0,24.96.1,21.115.0,29.88.1"}
P.entries["quest:151"] = {n="老马布兰契",s="“可怜的老马布兰契”是弗娜·法布隆在西部荒野主路旁给予玩家的一个任务。在逃难途中，法布隆一家的马车抛锚了，导致他们年迈的役马筋疲力尽、饥肠辘辘。探险者们被请求去附近的废弃农场寻找散落的燕麦袋，以喂养这匹疲惫的牲口。",h="“可怜的老马布兰契”是弗娜·法布隆在西部荒野主路旁给予玩家的一个任务。在逃难途中，法布隆一家的马车抛锚了，导致他们年迈的役马筋疲力尽、饥肠辘辘。探险者们被请求去附近的废弃农场寻找散落的燕麦袋，以喂养这匹疲惫的牲口。",kw={"收割傀儡","马","燕麦","老马布兰契","可怜的老马布兰契","弗娜·法布隆","马车","西部荒野"},ang={["class:Hunter"]="照料一匹力竭的役畜，凸显了劳动人民与那些忠诚地为他们承担重负的牲口之间的深厚羁绊。",["faction:Alliance"]="受困的法布隆一家展现了乡村人类臣民所遭受的绝望忽视，而此时的首都却因政治僵局而陷入瘫痪。"},sec={{t="困顿的一家",b="当游客沿着西部荒野尘土飞扬的公路旅行时，会在路边遇到被困住的弗娜和农夫法布隆。和该地区许多劳动家庭一样，法布隆一家因猖獗的强盗和失控的机械收割傀儡而被迫流离失所。他们在试图将全部家当运往安全地带时，马车发生了严重的故障，使他们被困在荒郊野外。"},{t="安抚忠诚的役马",b="他们当前困境的核心是老马布兰契，这匹年迈的役马在漫长的岁月里一直陪伴着这家人耕作和运输。由于拉着超载的马车而精疲力竭，又因为行程延误而挨饿，这匹温顺的马儿正在迅速衰弱。弗娜恳求过路人潜入附近沦陷的农场去搜寻幸存的粮食袋，冒着危险去对抗敌对的收割机和豺狼人拾荒者，只为给这匹忠诚的动物一顿像样的饭。"}},faq={{q="老马布兰契是谁？",a="老马布兰契是法布隆一家心爱的老役马。多年来，她一直拉着他们的犁和马车在西部荒野奔波，如今因为马车车轴断裂，她变得筋疲力尽，被困在路边。",al={"布兰契是谁","老马布兰契是什么","布兰契背景故事"}},{q="为什么法布隆一家的马车会坏掉？",a="法布隆一家试图带着所有财物逃离农场，结果马车在超负荷运转下解体了。他们被困在公路上，暴露在强盗和徘徊的野兽面前。",al={"他们为什么被困住","法布隆的马车","坏掉的马车公路"}},{q="燕麦从哪里来？",a="在西部荒野被侵占的农场里，田间和附属建筑中仍散落着不少燕麦袋，这些是农场主在逃离失控的收割机器和强盗时留下的。",al={"燕麦在哪里","寻找燕麦","燕麦袋"}},{q="田里的粮食受到什么威胁的守护？",a="公路西南方向的农田里不仅有失控的机械收割傀儡出没，还有成群结队的河爪豺狼人在搜刮荒废的谷仓。",al={"农场里有什么攻击者","农场危险","收割傀儡燕麦"}},{q="为什么这一家子没有把老马布兰契转移到安全的地方？",a="老马布兰契已经完全力竭且饥肠辘辘，没有食物补充就无法拉车或长途行走，而法布隆一家也不愿丢下他们忠诚的马儿和家当。",al={"为什么不离开马车","马还能走吗","为什么不去哨兵岭"}},{q="暴风城会向法布隆这样的农民提供援助吗？",a="暴风城的皇室法庭几乎没有为西部荒野的农场主提供任何保护或援助。乡村居民大多只能自生自灭，或者依赖处境艰难的人民民兵组织。",al={"暴风城帮助西部荒野","卫兵在哪里","联盟援助西部荒野"}}},fp="16,257,20.284.0,27.366.0,19.210.0,38.185.0,28.167.0,43.141.0,50.158.0,54.178.0"}
P.entries["quest:1510"] = {n="多格兰的消息",s="这项任务指引部落冒险者深入石爪山脉的山脚，前往玛拉卡金联系暗矛巨魔肯兹格拉。一名来自陶拉祖营地的兽人步兵Dogran负伤倒地，而第一个被派去取回救命草药的信使至今未归。",h="这项任务指引部落冒险者深入石爪山脉的山脚，前往玛拉卡金联系暗矛巨魔肯兹格拉。一名来自陶拉祖营地的兽人步兵Dogran负伤倒地，而第一个被派去取回救命草药的信使至今未归。",kw={"陶拉祖营地","dogran","加兹罗格","肯兹格拉","玛拉卡金","野猪人","石爪山脉"},ang={["class:Warlock"]="这项看起来是标准的军事救援任务，实际上是卡祖尔和奥格瑞玛的术士们所设下的一场关键试炼，旨在引导你感受奴役魅魔所需的情感共鸣。",["faction:Horde"]="这段旅程展现了在野猪人和地精的敌意面前，连接陶拉祖营地这类偏远哨站与玛拉卡金这类孤立营地之间的补给线是多么的细微且脆弱。"},sec={{t="边境求援",b="Dogran是驻扎在南贫瘠之地陶拉祖营地的一名部落步兵，他在与固守的野猪人交战时受了重伤。与他同行的步兵们撤了回来并试图营救他，但他的伤口溃烂得太严重，他们不敢在进行初步处理前移动他。为了寻求强效良药，陶拉祖营地向北方的十字路口发出求援，希望能获得玛拉卡金的丛林巨魔所调制的传统疗伤药。"},{t="玛拉卡金的血案",b="当旅行者抵达玛拉卡金的岩壁时，他们发现救援任务几乎立刻就失败了。第一位被派去取药的信使在带回药物前就被地精杀害了。肯兹格拉手中仍有Dogran所需的药物，但要拿到它，就必须应付石爪山脉山口边缘那些不稳定的边境危险。"}},faq={{q="Dogran是谁，他为什么受伤？",a="Dogran是驻扎在陶拉祖营地的一名兽人步兵。在率领小队清理南贫瘠之地好战的野猪人营地时，他受了严重的溃烂创伤，如果不立即进行医疗处理，根本无法转移他。",al={"dogran是谁","dogran为什么受伤","dogran的故事"}},{q="玛拉卡金在哪里？",a="玛拉卡金是坐落在石爪山脉岩石基座上的一个小暗矛巨魔哨站，位于贫瘠之地西北边界之外。",al={"玛拉卡金的位置","玛拉卡金在哪里","寻找肯兹格拉"}},{q="第一个去取药的信使发生了什么事？",a="最初从十字路口被派去取肯兹格拉的伤药的信使，在玛拉卡金附近被地精杀害了，没能将药带回来。肯兹格拉只说地精干掉了他。",al={"第一位信使","信使遭遇了什么","牺牲的信使"}},{q="为什么术士训练师关心Dogran的命运？",a="术士学徒们以替盲眼卡祖尔和加兹罗格跑腿为幌子被指引去处理Dogran的困境，但这趟差事最终会将他们引向一件充满爱与心碎的遗物，这件遗物是召唤并奴役魅魔所必需的。",al={"术士任务关联","魅魔与dogran","术士的目的"}},{q="肯兹格拉是谁？",a="肯兹格拉是一位居住在石爪山脉玛拉卡金定居点的暗矛巨魔炼金师和草药师，擅长酿制强效的荒野药剂。",al={"肯兹格拉是谁","石爪山脉的肯兹格拉","肯兹格拉"}},{q="为什么不能直接把Dogran转移到城市里？",a="与野猪人战斗后，Dogran的伤口严重溃烂。他的战友们担心在颠簸的贫瘠之地道路上把他运送到大城市的治疗者那里，还没到地方他就会死掉。",al={"为什么无法转移dogran","dogran的伤势","陶拉祖营地为何留下他"}}},fx={["643120b9"]={q="加兹罗格为什么要你帮忙？",a="加兹罗格负责协调贫瘠之地的防务和部队。多格兰在陶拉祖营地附近与野猪人作战时受了伤，伤口已经恶化，若无人帮助，他根本无法移动。此前派往玛拉卡金的信使迟迟未归，加兹罗格需要你拿到巨魔的疗伤药剂，免得多格兰伤重不治。",al={"加兹罗格的动机","为什么加兹罗格要救多格兰","为什么派我去玛拉卡金"}},["79033db9"]={q="加兹罗格为什么派冒险者去，而不是派自己的步兵？",a="部落在贫瘠之地的兵力捉襟见肘，既要抵挡野猪人持续不断的袭击，又要确保哨站路线安全。加兹罗格已经派了一名信使前往石爪山麓，但对方没有回来。眼前就有一位能干的冒险者，他没有多余的士兵可以再冒险派去跑腿。",al={"为什么让我打听多格兰的消息","加兹罗格为什么不派卫兵","加兹罗格为什么需要我"}}},fp="14,283,26.469.0,23.378.1,33.256.0,28.150.0,58.209.0,49.233.1,17.160.0,49.213.0"}
P.entries["quest:1511"] = {n="肯兹格拉的伤药",s="肯兹格拉的伤药是部落术士召唤魅魔任务线中的一项紧急送信任务。术士需要携带一份来自石爪山脉玛拉卡金的强效药剂，赶往卡利姆多的陶拉祖营地，以拯救一名叫做多格兰的特工。",h="肯兹格拉的伤药是部落术士召唤魅魔任务线中的一项紧急送信任务。术士需要携带一份来自石爪山脉玛拉卡金的强效药剂，赶往卡利姆多的陶拉祖营地，以拯救一名叫做多格兰的特工。",kw={"贫瘠之地","多格兰","伤药","肯兹格拉","劳格玛","石爪山脉","魅魔","陶拉祖营地"},ang={["class:Warlock"]="旅途的这一段是对耐心和足智多谋的考验；想要驾驭这种充满原始欲望与诱惑的生物，你必须先治愈那个持有束缚信物的凡人。",["faction:Horde"]="展示了年轻的部落在卡利姆多中部后勤战线的延伸，石爪山脉和贫瘠之地的孤立哨所依靠旅行者来传递关键信息和医疗援助。"},sec={{t="救命药剂",b="在石爪山脉的峭壁中，巨魔药剂师肯兹格拉预感到了麻烦。他知道之前派去为失踪斥候多格兰获取药物的信使再也没有回来，于是肯兹格拉准备了第二剂强效恢复药水。这种药剂威力强大且性质不稳定：半剂就能让垂死的士兵恢复行动能力，且不会导致伤口出血；而剩下的部分则必须留到第二天服用，以完成康复。"},{t="在陶拉祖营地会合",b="术士带着药剂离开山脉，进入南贫瘠之地，被指引去寻找陶拉祖营地的步兵劳格玛。劳格玛掌握着多格兰下落的关键情报，但他的驻地因不断的搜寻任务而兵力空虚。由于多格兰被困在敌对区域且身负重伤，将药剂送达陶拉祖是进行营救行动前的最后准备工作。"}},faq={{q="肯兹格拉的伤药有什么用途？",a="这是肯兹格拉调制的一种强效药剂，旨在救治受伤的兽人特工多格兰。药剂分两次服用，第一剂能让受伤的战士有足够的力量行动而不至于崩裂致命伤口，第二剂则完成愈合过程。",al={"什么是伤药","肯兹格拉的伤药用途","为什么要制作伤药"}},{q="肯兹格拉是谁？",a="肯兹格拉是一位驻扎在石爪山脉的巨魔药剂师。他为在该地区活动的部落特工提供专业的炼金混合药剂。",al={"肯兹格拉背景故事","肯兹格拉是谁"}},{q="步兵劳格玛为什么在陶拉祖营地等待？",a="步兵劳格玛驻扎在南贫瘠之地的陶拉祖营地。他负责监视当地斥候的动向，并掌握着多格兰失踪前最后的已知情报，但他缺乏人手来独自发起营救。",al={"步兵劳格玛是谁","劳格玛与陶拉祖营地","步兵劳格玛的角色"}},{q="这个任务与召唤魅魔有什么联系？",a="为了召唤并束缚魅魔，奥格瑞玛的部落术士需要多格兰的坠饰，这是一件充满激情与奉献精神的宝物。要获得该坠饰，就需要找到多格兰并用肯兹格拉的伤药救回他的性命。",al={"为什么魅魔任务需要伤药","魅魔任务线与多格兰"}},{q="为什么第一位信使没能把药剂带到？",a="原本派往石爪山脉的信使未能完成任务，这促使肯兹格拉为下一位追踪多格兰的冒险者准备了备用的剂量。",al={"第一位信使发生了什么","前任信使"}},{q="在陶拉祖营地之后，线索指向哪里？",a="在收到药剂后，步兵劳格玛会指引术士前往南贫瘠之地寻找扣押多格兰的敌人，垂死的斥候正被囚禁在那里。",al={"多格兰在哪里","劳格玛之后的任务步骤"}}},fx={["0e638b4a"]={q="肯兹格拉为什么要你帮忙？",a="肯兹格拉早已备好恢复药剂，料到还会有人替多格兰前来求药。作为住在石爪山脉玛拉卡金的巨魔治疗者，配制强效药剂是他的本行；只要一剂药便能救活伤者，他就不愿眼看战士丧命。",al={"肯兹格拉的动机","为什么配制伤药","肯兹格拉为什么帮忙"}},ff24236d={q="肯兹格拉为什么要你送药剂？",a="肯兹格拉是驻扎在石爪山脉玛拉卡金的药剂师，那里离贫瘠之地很远。把药剂穿过群山送到陶拉祖营地，路途漫长又危险，他无法亲自前往，尤其是在多格兰命悬一线之际。",al={"为什么派我去","她为什么不自己送伤药","为什么必须由玩家送伤药"}}},fp="19,273,18.489.0,26.399.1,40.261.0,17.170.0,44.218.0,52.223.0,47.167.0,43.147.1"}
P.entries["quest:1512"] = {n="爱的礼物",s="“爱的礼物”是部落术士召唤并奴役魅魔任务链中倒数第二个任务。在贫瘠之地被找到并复苏后，垂死的步兵多格兰交出了一个珍贵的纪念品，为黑暗仪式提供了必要的诱饵。",h="“爱的礼物”是部落术士召唤并奴役魅魔任务链中倒数第二个任务。在贫瘠之地被找到并复苏后，垂死的步兵多格兰交出了一个珍贵的纪念品，为黑暗仪式提供了必要的诱饵。",kw={"dirt-caked pendant","甘鲁尔·血眼","步兵多格兰","爱的礼物","奥格瑞玛","魅魔","贫瘠之地","赞卡沙"},ang={["class:Warlock"]="奴役魅魔的经历教导术士们，恶魔不仅仅是通过奥术力量召唤出来的，还可以通过利用它们对原始凡人激情（如爱和悲伤）的渴望来诱捕。",["faction:Horde"]="步兵多格兰体现了部落严酷的尚武精神，宁愿死在战场上，也不愿作为一个残废成为亲人的负担。"},sec={{t="步兵的牺牲",b="步兵多格兰在贫瘠之地被刺鬃野猪人囚禁并折磨，后被肯兹格拉的伤药救醒。知道自己的身体已经无法恢复，多格兰决定在光荣的战斗中面对死亡，而不是作为一个残废回到他的伴侣赞卡沙身边。他交出了一个Dirt-Caked Pendant——一份源于纯洁爱情的礼物——只求她永远不要知道他放弃了什么。"},{t="恶魔的诱饵",b="要召唤并奴役魅魔，术士需要一件蕴含强烈、纯洁情感的护身符。魅魔以凡人的欲望为食，将真挚的感情扭曲为痛苦。多格兰的坠饰承载着真挚的奉献和悲剧性的离别。在奥格瑞玛的暗影裂口将其交还给甘鲁尔·血眼后，这件护身符被清洗打磨，其璀璨的情感共鸣足以诱使灵魂吞噬者穿越扭曲虚空。"}},faq={{q="为什么术士需要多格兰的坠饰？",a="魅魔是会被深刻的凡人激情所吸引的恶魔生物，她们会扭曲并吞噬这些激情。多格兰的坠饰代表着无私的爱和衷心的牺牲，这使其成为将魅魔引入召唤法阵的完美神秘诱饵。",al={"为什么需要坠饰","魅魔诱饵","为什么需要dirt-caked pendant"}},{q="谁是步兵多格兰？",a="多格兰是一名在南贫瘠之地被刺鬃野猪人俘虏并残忍折磨的部落战士。虽然他被救出并用炼金药剂复苏，但他受到的重伤使他无法再作为一名骄傲的战士生活下去。",al={"多格兰是谁","步兵多格兰的背景故事"}},{q="谁是赞卡沙？",a="赞卡沙是多格兰年轻的伴侣，她焦急地等待着他的消息。为了让她免受照顾一个破碎残躯的悲伤和负担，多格兰选择放弃她的信物，寻求战士的死亡。",al={"赞卡沙的背景故事","多格兰的伴侣"}},{q="为什么多格兰要求你向赞卡沙保守这个秘密？",a="多格兰拒绝让年轻的伴侣被一个垂死的残废所束缚。他交出她的坠饰时就知道它永远不会回到她身边，但他祈求让她免于得知他最终命运的愧疚。",al={"为什么不告诉赞卡沙","多格兰的秘密"}},{q="谁清洗了坠饰，为什么要清洗？",a="奥格瑞玛的术士训练师甘鲁尔·血眼拿走了坠饰。他洗去了上面的污垢，使其明亮、纯净的外观和情感共鸣对被召唤的恶魔产生无法抗拒的吸引力。",al={"甘鲁尔·血眼的作用","为什么要清洗坠饰"}},{q="完成这个任务后紧接着会发生什么？",a="甘鲁尔·血眼指示你带着净化后的坠饰前往奥格瑞玛下方的召唤法阵，施展奴役仪式并在单挑中击败魅魔。",al={"what comes next","“爱的礼物”之后的下一个任务"}}},fx={["528517eb"]={q="步兵多格兰为什么让你带着他的坠饰离开？",a="多格兰不愿沦为废人，终生受年轻伴侣赞卡沙照料。他不想残破地回家，让她承受悲伤或愧疚，因此打算去寻找一场荣耀的战士之死，而不是像空壳一样逐渐衰弱。交出坠饰并让你离开，能让他斩断这份牵绊，以自己的方式有尊严地迎接终局。",al={"多格兰为什么把坠饰交给你","多格兰对爱之礼物的动机","为什么送出沾满泥土的坠饰"}},["6232e4f3"]={q="多格兰为什么需要你送还坠饰？",a="多格兰刚遭受野猪人残酷的囚禁和折磨，身体状况根本无法亲自前往奥格瑞玛。此外，他明确打算在战场上以一名战士的身份结束生命，而不是回到文明社会。你是唯一抵达他身边、值得信任的外来者，因此只有你能把这件信物交给甘鲁尔，同时不让赞卡沙知道他的命运。",al={"爱之礼物为什么选我","多格兰为什么需要我","多格兰为什么不能亲自带走坠饰"}}},fp="11,255,19.408.1,16.446.0,41.239.0,20.229.0,15.206.1,57.188.1,31.210.0,53.171.1"}
P.entries["quest:1513"] = {n="誓缚",s="“束缚”是部落术士学徒在奥格瑞玛奴役魅魔任务中的最终试炼。通过利用多格兰的坠饰中所蕴含的忠诚，术士在尼尔鲁·火刃的召唤法阵前，将一个恶魔从扭曲虚空中强行拽出，并凭借武力和法术折服它的意志。",h="“束缚”是部落术士学徒在奥格瑞玛奴役魅魔任务中的最终试炼。通过利用多格兰的坠饰中所蕴含的忠诚，术士在尼尔鲁·火刃的召唤法阵前，将一个恶魔从扭曲虚空中强行拽出，并凭借武力和法术折服它的意志。",kw={"束缚","cleft of shadow","多格兰","甘鲁尔","尼尔鲁","奥格瑞玛","坠饰","魅魔","术士","赞卡沙"},ang={["class:Warlock"]="这一仪式标志着术士向指挥狡诈、混乱的恶魔迈进，证明了个人的意志力可以驾驭虚空中诱人的危险。",["faction:Horde"]="该仪式在大断崖内秘密进行，凸显了萨尔领导的部落对这些躲避城市中尊崇荣誉的平民的恶魔使用者所持有的不安容忍。",["race:Orc"]="对于兽人来说，与恶魔实体打交道承载着他们种族过去被腐化的苦涩回忆，这使得甘鲁尔所要求的纪律和控制力显得尤为重要。"},sec={{t="恶魔的锚点",b="为了跨越位面并迫使魅魔现身，召唤者需要一个锚点——一个与该生物本质相契合的媒介。被残疾的兽人多格兰所遗弃的坠饰正是为了这个黑暗目的而存在的。它是多格兰对自己爱人赞卡沙的寄托，在历经囚禁与折磨的过程中，这件饰品承载了连接扭曲虚空并抓住恶魔注意力的情感共鸣。"},{t="阴影中的法阵",b="在奥格瑞玛的大断崖之下，尼尔鲁·火刃的帐篷深处，放置着一个为这种危险工作而准备的召唤法阵。在甘鲁尔·血眼的指导下，术士激活了刻满符文的法阵，并与被召唤出的魅魔战斗。术士不能简单地召唤一个恶魔来服役；他们必须在单挑中将其击败，用强大的意志征服它的邪恶灵魂。"},{t="诡计与意志力",b="正如甘鲁尔所警告的那样，魅魔是危险的奴仆。虽然她们的存在会让人陶醉并诱惑感官，但她们会不断地吸取粗心主人的生命力和精神。甘鲁尔告诫术士要铭记多格兰和赞卡沙的悲剧，以此作为抵御恶魔诡计的防线，因为傲慢和过度自信已经击垮了许多前途无量的术士。真正的掌控力要求拥有绝不屈服于恶魔诱惑的坚定意志。"}},faq={{q="这个仪式过程中会发生什么？",a="术士将多格兰的坠饰带入位于大断崖中尼尔鲁·火刃帐篷内的召唤法阵。利用护身符中束缚的忠诚，召唤者从扭曲虚空中召唤出一只魅魔，并将其打至屈服，从而确立对该生物的绝对统治。",al={"仪式如何运作","束缚任务要做什么","魅魔仪式"}},{q="召唤在哪里进行？",a="召唤在奥格瑞玛的大断崖进行，具体是在尼尔鲁·火刃的帐篷内，那里地板上刻有一个永久性的仪式法阵。",al={"法阵在哪里","召唤法阵位置","在哪里召唤魅魔"}},{q="多格兰是谁，为什么需要他的坠饰？",a="多格兰是一名在贫瘠之地被野猪人俘虏并致残的部落步兵。他的坠饰是他与爱人赞卡沙之间联系的信物，作为引诱并锚定魅魔的关键焦点。",al={"多格兰是谁","为什么用多格兰的坠饰","多格兰的故事"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是一位居住在奥格瑞玛下方大断崖的高级术士训练师。他指导黑魔法的后起之秀，并引导他们完成危险的恶魔奴役仪式。",al={"谁发布任务","甘鲁尔是谁","甘鲁尔·血眼的角色"}},{q="术士完成这项试炼后能获得什么力量？",a="征服这个生物标志着术士训练的完成，他们将获得随时召唤魅魔作为仆从所需的秘密知识和符文掌控力。",al={"术士获得什么奖励","为什么要召唤魅魔","魅魔宠物技能"}},{q="为什么召唤魅魔被认为特别危险？",a="魅魔拥有强大的魅惑能力，并能操控凡人的欲望。过度自信的术士面临着灵魂被缓慢吸干的风险，最终屈服于恶魔的微妙诡计，而非驾驭它。",al={"魅魔的危险性","为什么魅魔有风险","魅魔背景知识"}}},fx={["9ef07cc1"]={q="甘鲁尔·血眼为什么要你帮忙？",a="作为部落新晋术士的导师，甘鲁尔·血眼必须在让你指挥危险的恶魔仆从之前，考验你的意志和魔法力量。他让你借助多格兰爱情的悲剧遗物召唤并降服魅魔，以此教你提防恶魔的诡计和傲慢。等你成功后，甘鲁尔还打算归还多格兰的坠饰，并把消息带给赞卡沙。",al={"甘鲁尔·血眼的动机","甘鲁尔为什么要召唤魅魔","为什么要做束缚仪式任务"}},["9690a59c"]={q="甘鲁尔·血眼为什么要你来施展召唤仪式，而不是亲自施展？",a="这场仪式是专为你准备的成年礼。术士必须亲自让召唤来的恶魔屈服；老师或城中卫兵都无法代你建立这种精神上的支配。若甘鲁尔亲自降服恶魔，你就无法获得束缚并指挥自己魅魔所需的纪律与权威。",al={"束缚任务为什么选我","甘鲁尔为什么不能召唤魅魔","为什么我必须召唤它"}},dee6d59e={q="仪式中你要对付谁？",a="仪式中，你将面对一只被召唤出来的魅魔。它穿越扭曲虚空，被召至尼鲁·火刃的帐篷内的召唤法阵。这些狡诈的恶魔魅魔最喜欢操纵凡人的欲望、吞噬灵魂。你用多格兰的坠饰——一件浸透凡人爱意与悲剧的物品——引诱恶魔，迫使它现身，再将其击败并驯服。",al={"束缚仪式的目标","束缚仪式中要打什么","召唤出来的魅魔"}}},fp="11,305,16.391.1,25.401.0,19.425.1,32.297.0,36.172.0,45.203.1,24.209.0,58.171.0,60.203.0"}
P.entries["quest:1515"] = {n="多格兰之囚",s="多格兰的俘虏是部落术士学徒训练中的一项重要试炼，要求修行者深入野猪人营地中心营救一名被俘的兽人战士。术士被委托携带一剂恢复药剂，必须找到饱受摧残的步兵多格兰，并为他提供逃离俘虏者魔掌所需的力量。",h="多格兰的俘虏是部落术士学徒训练中的一项重要试炼，要求修行者深入野猪人营地中心营救一名被俘的兽人战士。术士被委托携带一剂恢复药剂，必须找到饱受摧残的步兵多格兰，并为他提供逃离俘虏者魔掌所需的力量。",kw={"贫瘠之地","多格兰","伤药","肯兹格拉","劳格玛","野猪人","魅魔","陶拉祖","术士"},ang={["class:Warlock"]="这次救援是理解凡人激情与牺牲的重要基石，而这两者正是召唤魅魔的先决条件。",["faction:Horde"]="多格兰的困境说明了野猪人对整个贫瘠之地中部地区的部落巡逻队和哨所构成了持续的威胁。",["race:Orc"]="即使面对野猪人俘虏者的残害和折磨，多格兰的坚忍也展现了兽人步兵应有的顽强韧性。"},sec={{t="孤身救援",b="陶拉祖营地的步兵劳格玛拒绝冒着损失部落军事力量的风险，去对盘踞的野猪人发动代价高昂的突袭，因此他的战友多格兰的命运完全掌握在一位有进取心的术士手中。救援者仅携带肯兹格拉的伤药，必须冒险北上，穿过荆棘和敌对营地，找到多格兰被囚禁的地方。"},{t="血的代价",b="多格兰在陶拉祖北部的一处小屋中被发现，他遭到了残酷的殴打，并被敌对的野猪人包围。虽然那苦涩的药剂提供了足够让这名战士蹒跚逃往安全地带的活力，但这救援也付出了沉重的代价：多格兰的严重创伤使他落下永久性残疾，失去了一条胳膊和一条腿。"}},faq={{q="步兵多格兰被关在哪里？",a="步兵多格兰被囚禁在贫瘠之地陶拉祖营地正北方的一小簇野猪人小屋中。",al={"多格兰的位置","多格兰在哪里","在贫瘠之地寻找多格兰"}},{q="为什么步兵劳格玛不派士兵去帮忙？",a="步兵劳格玛无法从陶拉祖营地的防务中抽调任何兵力，他认为进入重兵把守的野猪人领地执行救援任务风险太大，不值得再搭上士兵的性命。",al={"为什么没有部落卫兵帮忙","劳格玛的士兵","陶拉祖的增援"}},{q="肯兹格拉的伤药是什么？",a="这是一种药效强劲、味道难闻的恢复药剂，是专门酿制用来让伤势严重的多格兰获得足够的体力，从而站起来逃离野猪人的囚禁。",al={"肯兹格拉药剂","什么是伤药","多格兰的药物"}},{q="多格兰被发现时状况如何？",a="多格兰处于濒死边缘，在野猪人的折磨下身受重伤，饱受摧残。即使喝下药剂后，他的手臂和腿也已经损坏到无法修复的地步。",al={"多格兰的伤势","多格兰还活着吗","多格兰的手臂和腿"}},{q="这次救援与召唤魅魔有什么关系？",a="多格兰持有一个与爱和凡人忠诚有关的信物——这正是术士用来召唤魅魔并将其束缚在自己意志之下的情感和概念。",al={"为什么术士要做这件事","魅魔任务关联","术士任务多格兰"}},{q="是谁俘虏了多格兰？",a="他是被居住在陶拉祖营地北部荆棘丛中的本土野猪人部落俘虏的。",al={"谁抓走了多格兰","多格兰的俘虏者","贫瘠之地的绑架者"}}},fx={b38341a7={q="步兵劳格玛为什么要你去寻找多格兰？",a="步兵多格兰是劳格玛的同伴，在贫瘠之地巡逻时被野猪人俘虏。劳格玛既无法抽调部落士兵，也不敢冒险发动军事袭击营救他，但他不愿彻底抛弃这位同伴。劳格玛见你已经决心追查到此，便准许你独自冒险前去施以援手，并带上肯兹格拉的伤药，让多格兰有机会活下来。",al={"为什么帮多格兰","步兵劳格玛的动机","为什么救多格兰"}}},fp="18,321,15.354.0,18.331.1,27.115.0,45.191.0,28.166.0,39.183.1,52.148.1,20.97.0"}
P.entries["quest:1516"] = {n="大地的召唤",s="Call of Earth是部落萨满祭司新人在试炼谷受训时的初始试炼。这项试炼由坎纳甘·地鸣主持，旨在通过要求萨满狩猎恶魔邪犬来准备一种仪式用萨普塔，从而考验萨满的耐力和耐心。",h="Call of Earth是部落萨满祭司新人在试炼谷受训时的初始试炼。这项试炼由坎纳甘·地鸣主持，旨在通过要求萨满狩猎恶魔邪犬来准备一种仪式用萨普塔，从而考验萨满的耐力和耐心。",kw={"火刃氏族","call of earth","坎纳甘·地鸣","大地图腾","邪犬","萨普塔","萨满试炼","试炼谷"},ang={["class:Shaman"]="这项仪式标志着你与元素的首次正式交流，为你获得大地图腾奠定了基础。",["race:Orc"]="在萨尔领导的部落中，回归萨满之道是在向恶魔腐化之前古老的氏族传统致敬。",["race:Troll"]="暗矛巨魔的巫医和灵术师拥抱大地之灵，以此支持他们与兽人共同建立的新家园。"},sec={{t="最初的羁绊",b="萨满在召唤元素之前，必须依次与每种元素建立持久的联系。在兽人和巨魔的文化中，这条精神之路始于大地——生命、耐力和耐心的基石。坎纳甘·地鸣作为试炼谷中新手的向导，教导萨满们大地在给予庇护之前，需要获得至高的尊重与坚定不移的信念。"},{t="净化狩猎",b="为了证明自己已做好与大地上顽固的灵魂交流的准备，萨满学徒被派往火刃氏族盘踞的北部峡谷。通过狩猎邪犬——一种由黑暗魔法召唤出来的、源自外位面的腐化猎犬——萨满证明了他们有能力保卫大地免受非自然腐化的侵害。坎纳甘将收获的蹄子作为炼制大地萨普塔的材料，这是一种能让凡人洞察元素位面的神圣药剂。"}},faq={{q="这项试炼的目的是什么？",a="这项试炼将萨满引入元素奥秘，向大地之灵证明他们的耐心与精神纪律，以便他们最终能直接与其交流并获得大地图腾。",al={"为什么进行call of earth","call of earth的奖励","任务目的"}},{q="坎纳甘·地鸣是谁？",a="坎纳甘·地鸣是一位居住在杜隆塔尔试炼谷的巨魔萨满训练师。他指导年轻的兽人、巨魔以及来访的牛头人萨满踏出通往元素掌控的第一步。",al={"坎纳甘是谁","坎纳甘·地鸣背景故事"}},{q="坎纳甘为什么需要邪犬的蹄子？",a="坎纳甘将这些蹄子作为调制大地萨普塔的关键原料，这是一种特殊的药剂，能让凡人萨满的感官能够感知并与元素之灵交流。",al={"为什么需要邪犬蹄子","蹄子的用途"}},{q="邪犬在哪里？",a="邪犬位于试炼谷训练场以北，出没于火刃集会所所属的洞穴及周围的悬崖上。",al={"邪犬位置","在哪里寻找邪犬"}},{q="其他部落种族可以进行这个版本的试炼吗？",a="可以。虽然该试炼主要针对在杜隆塔尔成年的兽人和巨魔萨满，但离开红云台地的牛头人萨满也可以在试炼谷进行坎纳甘的试炼。",al={"牛头人能做这个任务吗","这是兽人专属吗"}},{q="对萨满而言，大地代表什么美德？",a="根据萨满传统，大地代表了生命的基石，体现了强大的力量、耐力和永恒的耐心，尽管如果不加尊重，它也可能变得顽固而反复无常。",al={"大地代表的美德","萨满大地的含义"}}},fx={a9a10a24={q="坎纳甘·地鸣为什么要你帮忙？",a="坎纳甘是年轻萨满的引路人，帮助他们踏上灵性之路。他感应到冲突将至，也察觉你拥有与大地沟通所需的坚韧精神。在他准备圣水并分享大地的奥秘之前，必须考验你面对危险敌人时的决心、力量和耐心，确保你已准备好聆听元素的呼唤。",al={"坎纳甘·地鸣的动机","坎纳甘为什么考验你","坎纳甘·地鸣为什么这样做"}},["3057b25e"]={q="试炼谷里为什么会有魔能猎犬？",a="这些恶魔猎犬徘徊在山谷北部，由藏身于当地洞穴中的火刃集会所术士召唤并束缚。它们邪恶的存在玷污了周围的土地，既对年轻的入门者构成迫在眉睫的威胁，也为初出茅庐的萨满提供了考验勇气与战斗力的合适试炼。",al={"这里为什么有魔能猎犬","试炼谷魔能猎犬","魔能猎犬是什么"}},dddcc185={q="为什么必须由你对付魔能猎犬，而不是让山谷的卫兵出手？",a="这是个人的灵性试炼，并非例行的军事行动。萨满必须通过亲身试炼和展现力量，与元素建立自己的和谐。让战士或卫兵收集蹄子，无法证明什么；固执的大地之灵要求你直面危险，证明自己的耐心、毅力与能力，然后才会赐予你力量。",al={"为什么是我执行大地呼唤","为什么不派卫兵对付魔能猎犬","为什么必须猎杀魔能猎犬"}}},fp="13,260,14.398.0,16.449.0,34.202.0,26.202.0,39.178.0,34.160.0,58.189.0,50.188.0"}
P.entries["quest:1517"] = {n="大地的召唤",s="这一神圣的仪式标志着萨满学徒在杜隆塔尔首次与元素进行精神交流。在坎纳甘·地鸣的指引下，年轻的萨满在灵魂石地服下一剂强效大地之液，从而洞穿现实的帷幕，直接面对大地之魂。",h="这一神圣的仪式标志着萨满学徒在杜隆塔尔首次与元素进行精神交流。在坎纳甘·地鸣的指引下，年轻的萨满在灵魂石地服下一剂强效大地之液，从而洞穿现实的帷幕，直接面对大地之魂。",kw={"call of earth","坎纳甘·地鸣","大地之液","秘道","大地之魂","大地之液视觉","灵魂石地","试炼谷"},ang={["class:Shaman"]="这一仪式代表了你迈向元素调和之路的第一步，教会了你真正的掌握始于大地那静谧的耐心。",["race:Orc"]="对于在经历了几代邪能腐化后回归祖先道路的兽人来说，通过大地之液进行的交流是其族人与灵魂之间传统纽带的神圣重现。",["race:Troll"]="暗矛巨魔的巫医和通灵师们拥抱这些大地的仪式，将他们深厚的祖先纽带与杜隆塔尔严酷的、被烈日炙烤的土地相结合。"},sec={{t="大地之液的力量",b="大地之液是一种只有极少数萨满大师才知晓的神秘配方。这种药剂由元素魔法酿造而成，旨在沟通凡人的感知与灵界，让意志坚定者获得“大地之液视觉”。由于其力量直接将饮用者的灵魂与元素绑定，传统要求它只能在神圣的净土上服用。"},{t="灵魂石地的朝圣之旅",b="为了与大地沟通，学徒们离开试炼谷，沿着秘道登上杜隆塔尔南部的山脊。小径的尽头便是灵魂石地，这是一处俯瞰着崎岖荒野的高处圣地。在这里饮用大地之液，能让学徒感知到凡眼所不能见的事物：静候于岩石之中的元素存在。"},{t="大地的耐心",b="大地之魂并不要求流血或征服，它只要求祈求者谦卑地站在这世界之上。虽然其他的元素力量——火、水和风——拥有动荡、反复无常且常常混乱的精神，但大地赋予的是稳重。它通过提醒人们山脉带来持久、平原提供无限的耐心来欢迎祈求者。"}},faq={{q="什么是大地之液？",a="大地之液是由资深萨满酿造的一种特殊药剂，能暂时使饮用者的灵魂与大地元素相调和。饮用它能获得看见并与隐形元素之灵交流所需的内在视野。",al={"什么是大地之液","大地之液的含义","大地之液的作用"}},{q="灵魂石地在哪里？",a="灵魂石地坐落在试炼谷大兽穴西南方向的崎岖山脉中。学徒们可以沿着秘道向上，进入山谷底部南侧的丘陵来抵达那里。",al={"灵魂石地在哪里","灵魂石地位置","如何找到灵魂石地"}},{q="为什么必须在灵魂石地饮用大地之液？",a="萨满传统规定，大地之液只能在指定的圣地饮用。像灵魂石地这样的神圣场所是凡间与元素位面之间天然的薄弱点。",al={"为什么要在灵魂石地饮用","可以在任何地方饮用大地之液吗"}},{q="大地之魂是谁？",a="它是栖息在灵魂石地的一种大地元素之灵。只有通过大地之液增强的视野才能看见它，它会迎接年轻的萨满，考验他们的谦卑，并传授关于元素平衡的最初基础课程。",al={"大地之魂","大地之灵是谁"}},{q="任何部落萨满都能进行这项试炼吗？",a="虽然这主要是为在杜隆塔尔受训的年轻兽人和暗矛巨魔萨满准备的成人礼，但来到此处的牛头人萨满也可以完成它，尽管他们在红云台地有自己对应的仪式。",al={"牛头人可以完成这个任务吗","谁可以进行大地之唤仪式"}},{q="大地之灵对学徒有何反应？",a="与火或风的动荡表现不同，大地之灵是友好且被动的。它接纳怀着谦卑敬意前来的学徒，并赐予祝福，而不要求进行力量的角逐。",al={"大地之灵说了什么","大地之灵具有敌意吗"}}},fx={["1aaf4733"]={q="坎纳甘·地鸣为什么要你完成这件事？",a="坎纳甘·地鸣正在引导你踏上萨满的灵性之路。在你收集到所需的仪式材料，证明自己已经做好准备后，他要求你在灵魂石地饮下大地灵契。他希望借此缔结你与这片土地的元素之灵之间的联系，让你的视野穿透帷幕，直接与大地交流。",al={"坎纳甘的目的","为什么派我去灵魂石地","为什么要喝大地灵契"}},["99304602"]={q="坎纳甘·地鸣为什么派你去，而不亲自前往？",a="这段旅程是一项神圣的成年仪式，每位有志成为萨满的人都必须亲自经历。大地灵契会将饮用者自身的灵魂与元素相连，赐予的视野无法通过他人代为体验。坎纳甘早已能与大地交流；你必须亲自谦恭地站在大地面前，赢得它的祝福。",al={"为什么派我去找坎纳甘","为什么派玩家去灵魂石地","为什么必须喝灵契"}}},fp="13,260,22.371.0,25.352.0,21.400.0,23.225.0,29.179.0,46.196.0,40.238.0,42.217.0,48.212.0"}
P.entries["quest:1518"] = {n="大地的召唤",s="“大地的召唤”是杜隆塔尔年轻萨满试炼大地任务的终极仪式。在与大地之魂沟通后，学徒需要带着粗石英回到坎纳甘·地鸣那里，以获得他们的第一个元素图腾。",h="“大地的召唤”是杜隆塔尔年轻萨满试炼大地任务的终极仪式。在与大地之魂沟通后，学徒需要带着粗石英回到坎纳甘·地鸣那里，以获得他们的第一个元素图腾。",kw={"call of earth","坎纳甘·地鸣","杜隆塔尔","大地图腾","大地之魂","粗石英","萨满","试炼谷"},ang={["class:Shaman"]="这个仪式为你提供了第一个图腾，解锁了让你自己沉浸在元素之中，并呼唤大地给予援助的能力。",["faction:Horde"]="卡利姆多的元素狂野且不受驯服，这使得部落萨满所建立的羁绊对于他们新定居点的生存至关重要。",["race:Orc"]="这个试炼代表了兽人萨满教义在杜隆塔尔的持续复兴，在经历了数十年的恶魔腐化之后，重新回归元素平衡。",["race:Troll"]="暗矛巫医和灵行者在试炼谷与兽人们并肩学习，调整他们传统的沟通方式，以涵盖四大元素之道。"},sec={{t="石之心",b="为了与大地沟通，萨满新手必须超越蛮力。在向大地之魂展现了耐心与谦逊之后，学徒会获得一个谦卑的信物：一块粗石英。虽然外表平凡，但这块小小的石头是力量的种子，也是大地之灵接受请求者承诺的证明。"},{t="四条道路之首",b="Bringing the quartz back to Canaga Earthcaller in the Valley of Trials completes the trial. Canaga crafts the stone into an Earth Totem, the physical focus through which the shaman channels the ground's steadfast protection and strength. This rite marks the initiate's formal entrance into the first of the four elemental disciplines, laying the foundation for a lifetime of communion with the natural world."}},faq={{q="粗石英有什么用？",a="粗石英是由大地之魂赠予的，以此证明你已经与大地之灵完成了沟通。坎纳甘·地鸣会将这块鹅卵石嵌入你新雕刻的大地图腾中，作为你大地法术的核心与焦点。",al={"粗石英","粗石英的作用","粗石英的目的"}},{q="坎纳甘·地鸣是谁？",a="坎纳甘·地鸣是一位位于杜隆塔尔试炼谷的萨满训练师。他引导年轻的兽人和巨魔学徒完成最初的试炼，准备让他们与元素之灵沟通，并制作他们的第一个图腾。",al={"坎纳甘","坎纳甘·地鸣","坎纳甘是谁"}},{q="牛头人可以完成这个任务吗？",a="可以。虽然牛头人通常会在莫高雷红云台地的长者那里完成他们的大地试炼，但任何前往试炼谷的部落萨满都可以找坎纳甘·地鸣进行这个仪式。",al={"牛头人可以完成杜隆塔尔的大地召唤吗","杜隆塔尔的牛头人萨满","牛头人的大地召唤"}},{q="获得大地图腾意味着什么？",a="获得大地图腾意味着大地之灵已经认可了你。它既是你作为萨满地位的象征，也是施放大地祝福与结界所必需的物理法器。",al={"为什么要获得大地图腾","萨满大地图腾的意义"}},{q="大地对萨满有哪些美德要求？",a="大地之灵要求学徒保持耐心、坚强并寻求智慧。它教导我们，即使是最小的鹅卵石，只要能持之以恒，也能长存过高山，并以此劝诫萨满尊重大地，大地才会反过来支撑他们。",al={"大地之灵的教诲","大地要求什么"}},{q="萨满之路在这之后走向何方？",a="大地只是萨满必须掌握的四大元素中的第一个。随着你修行的继续，你最终会被召唤去寻求与火、水、风之灵的沟通。",al={"下一个图腾是什么","大地图腾之后","萨满的四条道路"}}},fx={["946f939a"]={q="大地之魂为什么要把粗石英交给你？",a="在考验了你的决心并认可了你与大地的交流后，这个灵体将粗石英赐予你，作为你们之间联系的实物凭证。它希望你把这块小石头带回给坎纳甘·地鸣，让它成为你第一个图腾的核心，将大地恒久的力量与耐心直接融入你的灵性修行。",al={"大地之魂的目的","为什么要粗石英","大地显灵体为什么派我去"}}},fp="13,246,18.371.0,23.408.0,34.245.0,26.235.0,25.210.0,44.216.0,49.228.0,41.184.0"}
P.entries["quest:1519"] = {n="大地的召唤",s="“Call of Earth”是一项神圣的萨满祭司成年礼，旨在考验受试者的耐心、毅力和对自然界的尊重。通过回应大地的召唤并接受元素萨普塔，寻求者将开启一场精神上的重生，直接与万物之基进行沟通。",h="“Call of Earth”是一项神圣的萨满祭司成年礼，旨在考验受试者的耐心、毅力和对自然界的尊重。通过回应大地的召唤并接受元素萨普塔，寻求者将开启一场精神上的重生，直接与万物之基进行沟通。",kw={"call of earth","大地之母","元素","耐心","重生","萨普塔","萨满祭司","耐力"},ang={["class:Shaman"]="这一仪式标志着萨满祭司训练中的一个关键转折点，与大地的沟通赋予了他们力量、耐力和深刻的精神洞察力。",["faction:Horde"]="团结部落的萨满祭司传统汲取了元素的力量，而这一切始于大地的稳固韧性。",["race:Tauren"]="对大地之母的崇敬是牛头人文化的核心，这使得这一试炼成为对基本祖先信仰的遵循。"},sec={{t="万物之基",b="“Call of Earth”是萨满祭司学习与世界原始力量沟通的奠基仪式。大地被视为所有元素中最顽固也最睿智的，它是存在的稳固基石。试炼强调自然是在腐蚀与重生的刻意循环中运行的，历经无数岁月将山脉化为沙漠，将河流切成峡谷。为了聆听大地的声音，受试者必须展现出同样坚定不移的耐心。"},{t="萨普塔与重生",b="回应这一召唤被视为一场精神上的重生，它使寻求者发生不可逆转的改变，无法再回到过去的蒙昧状态。在证明了自己的准备就绪并尊重大地之母的法则后，受试者将获得一种土之萨普塔。这种特制的药剂开启了一条全新的感知路径，使萨满祭司能够掌握力量、耐力和元素保护的基本奥秘。"}},faq={{q="什么是“Call of Earth”？",a="“Call of Earth”是志向成为萨满祭司者的神圣精神试炼。它考验寻求者的耐心和准备程度，以直接与大地元素沟通并聆听其永恒的智慧。",al={"什么是call of earth","萨满祭司大地任务","call of earth的目的"}},{q="大地元素在萨满传统中代表什么？",a="大地代表万物之基，体现了力量、耐力和耐心。它被认为是最顽固也最睿智的元素，教导人们万物皆随时间而腐蚀并重生。",al={"大地代表什么","大地元素背景","萨满祭司大地含义"}},{q="什么是萨普塔？",a="萨普塔是由萨满祭司导师准备的一种元素药剂。饮用或接受它会开启一条精神路径，调整寻求者的感官，使其能够感知元素之灵并与之互动。",al={"什么是萨普塔","大地萨普塔","萨普塔的作用"}},{q="试炼中提到的大地之母是谁？",a="大地之母是生命与平衡的基础源泉，尤其受到牛头人萨满祭司的崇敬。她保护那些遵守她法则的人，并赐予那些以尊重对待土地的寻求者以更大的智慧。",al={"大地之母是谁","大地之母背景","大地之母联系"}},{q="回应召唤后会发生什么？",a="完成这一阶段标志着寻求者已为他们的下一步“The Next Step”做好了准备。它代表了一种精神上的重生，自此以后萨满祭司再也无法回到无知的状态，因为大地的全新秘密已被揭开。",al={"完成后会发生什么","call of earth之后","call of earth重生"}},{q="为什么与大地沟通需要耐心？",a="大地在腐蚀与重生的循环中运作，山脉终将磨损成沙漠，河流终将刻蚀出峡谷。萨满祭司必须掌握耐心和耐力，才能与这种恒久的节奏相协调。",al={"为什么大地需要耐心","耐心与大地"}}},fp="13,291,28.468.0,21.416.0,26.183.0,60.205.0,16.187.0,47.209.0,37.219.0,51.200.0"}
P.entries["quest:152"] = {n="清理海岸",s="在西部荒野崎岖的西侧边缘，浅滩上遍布着沉船，鱼人部落则占领了海滩。位于西部荒野灯塔的幽灵葛瑞森船长招募有能力的冒险者去清理这些水生掠夺者，好让遭遇海难的水手有活命上岸的机会。",h="在西部荒野崎岖的西侧边缘，浅滩上遍布着沉船，鱼人部落则占领了海滩。位于西部荒野灯塔的幽灵葛瑞森船长招募有能力的冒险者去清理这些水生掠夺者，好让遭遇海难的水手有活命上岸的机会。",kw={"葛瑞森船长","海岸奔袭者","无尽之海","鱼人","神谕者","沉船","踏潮者","西部荒野灯塔"},ang={["faction:Alliance"]="由于暴风城军队不在西部荒野，人民民兵在保护内陆农场方面已经竭尽全力，海岸防御工作完全留给了像葛瑞森船长这样的孤立盟友。",["race:Human"]="人类商船和渔民长期以来一直航行在西部荒野外的水域；看到海岸变成了一个鱼人横行的死亡陷阱，这无不令人痛苦地回想起王国沦陷的边境。"},sec={{t="沉船之墓",b="无尽之海在西部荒野西界一带以凶险著称。多年来，暗礁、突如其来的暴风雨和锯齿般的岩石已经将无数船只撞成了碎片。在正常情况下，幸存者或许可以抓住残骸爬上沙滩等待救援。但对于任何遭遇海难的水手来说不幸的是，海岸线已完全落入了极具攻击性的鱼人部落的控制之下，它们对被冲上岸的落难者毫不留情。"},{t="幽灵哨兵",b="西部荒野灯塔耸立在大陆西南方的一处孤立岩岬上，由葛瑞森船长的灵魂守护着。尽管死亡将他束缚在这个岗位上，葛瑞森仍坚守着对过往船只和迷途水手安全的责任。他认识到，从北方的普通鱼人海岸奔袭者到南方的致命鱼人踏潮者、战士和神谕者，这些鱼人部落让海滩变得险象环生，因此他号召旅行者对海岸线进行系统性的清理。"}},faq={{q="谁是葛瑞森船长？",a="葛瑞森船长是一位在西部荒野灯塔徘徊的幽灵海长。尽管处于亡灵状态，但他对航行在海岸外危险水域的水手们仍有着挥之不去的责任感，并寻求保护海岸线，以让任何可能在海难中幸存的人免受伤害。",al={"葛瑞森船长","灯塔里的幽灵","西部荒野灯塔管理员"}},{q="为什么葛瑞森想要清理海岸上的鱼人？",a="西部荒野外的水域遍布沉船，幸存的水手经常被冲上岸。由于极具攻击性的鱼人部落从北向南蜂拥在海滩上，除非海岸线保持清净，否则任何登上陆地的海难幸存者都会很快遭到攻击并被杀害。",al={"为什么要在西部荒野杀鱼人","海岸不安全的原因","为什么要清理海岸"}},{q="这些不同的鱼人位于哪里？",a="鱼人海岸奔袭者通常居住在西部荒野海岸的北部地带。更强大的鱼人战士、神谕者和踏潮者则集中在南部海滩的定居点和营地中。",al={"西部荒野鱼人分布","海岸奔袭者在哪里","踏潮者在哪里"}},{q="葛瑞森船长对联盟或部落怀有敌意吗？",a="葛瑞森船长是一个中立人物。他受航海职责而非政治立场约束，会向任何愿意帮助使海岸更安全的有能力的冒险者提供任务和奖励。",al={"葛瑞森友好吗","葛瑞森阵营","部落可以做这个任务吗"}},{q="这个任务需要先重新点亮灯塔吗？",a="不需要。无论你是否曾协助他重新点亮西部荒野灯塔，葛瑞森船长都会委托你清理海岸。",al={"我需要先完成灯塔守护者吗","海岸不安全的前置任务"}},{q="鱼人是在为迪菲亚潜行者工作吗？",a="不是。鱼人是出于领地攻击性而独立行动的。虽然迪菲亚潜行者在附近的月溪镇地区和南部海湾活动，但沿海的鱼人部落会攻击任何侵入它们海岸狩猎场的人。",al={"迪菲亚和鱼人结盟了吗","迪菲亚与鱼人的联系"}}},fp="21,199,20.266.0,19.360.0,23.182.0,57.176.0,42.168.0,52.135.0,56.111.0,51.176.0"}
P.entries["quest:1520"] = {n="大地的召唤",s="这一神圣的仪式标志着牛头人萨满在精神上与大地元素达成共鸣。通过在纳拉其营地以东的一块神圣岩石处饮用大地图腾药剂，试炼者能够超越肉体感官，直接与大地之魂进行沟通。",h="这一神圣的仪式标志着牛头人萨满在精神上与大地元素达成共鸣。通过在纳拉其营地以东的一块神圣岩石处饮用大地图腾药剂，试炼者能够超越肉体感官，直接与大地之魂进行沟通。",kw={"call of earth","纳拉其营地","大地图腾药剂","科多石","化身","莫高雷","药剂","鸦羽先知"},ang={["class:Shaman"]="这一仪式构成了牛头人萨满与大地联结的精神核心，是获得大地共鸣并接受大地图腾的必要桥梁。",["race:Tauren"]="对大地母亲的深切敬畏使得药剂仪式成为红云台地上的牛头人精神修行者最受尊崇的成年试炼之一。"},sec={{t="药剂的用途",b="药剂是由萨满长者精心调制的仪式药水，旨在将试炼者的凡人之魂直接与原始元素相连。这种药剂蕴含着先祖的魔法，只有少数几位牛头人掌握着它的酿造秘方。在指定的圣地饮用后，药水会扩张饮用者的心智，刺破现实世界与精神位面之间的面纱，从而让萨满以原始形态亲眼目睹元素。"},{t="在科多石的交流",b="纳拉其营地东面矗立着科多石，这是一根高耸的石柱，作为一处神圣的避难所。在这里饮用药剂，能够显现出等待着朝圣者的大地之魂。与萨满修行道路上稍后会遇到的狂暴、炽热或愤怒的自然界力量不同，大地之魂只要求试炼者以安静且谦卑的态度接近它，并会赐予那些尊崇大地的人以山岳般持久的力量和平原般平静的耐心。"}},faq={{q="什么是大地图腾药剂？",a="大地图腾药剂是一种由萨满长者酿造的炼金和精神药水。它的魔法能够开启饮用者的感知，使试炼者能够看见并直接与大地元素之灵进行沟通。",al={"什么是药剂","大地图腾药剂的含义","药水有什么作用"}},{q="科多石在哪里？",a="科多石是一块宏伟的天然巨石，位于纳拉其营地穿过红云台地的正东方。",al={"寻找科多石","科多石位置","圣地在哪里"}},{q="是谁为这次仪式调配了大地图腾药剂？",a="这种药剂是由居住在纳拉其营地的鸦羽先知调制并赐予的，他是一位萨满长者，负责监督年轻精神向导的训练。",al={"谁提供药剂","鸦羽先知药剂"}},{q="为什么药剂必须在圣地饮用？",a="药剂本质上是神圣的，如果使用不当会非常危险。牛头人的传统要求只能在供奉的圣地内饮用，因为那里是元素之灵自然栖息的地方，可以安全地接待祈求者。",al={"为什么在科多石饮用","我可以随处饮用药剂吗"}},{q="在科多石饮用药剂后会发生什么？",a="药剂揭开了世俗的面纱，显现出大地之魂。与这个实体交谈可以完成萨满与大地元素之间的联结。",al={"会出现什么","大地之魂刷新"}},{q="大地之灵向试炼者传授了什么教诲？",a="大地之灵教导说，大地需要的是谦卑的耐心，而非战斗。虽然像火焰或空气这样的元素可能混乱而狂暴，但大地能为萨满的灵魂提供力量、耐力和宁静的基础。",al={"大地之灵的教诲","大地仪式的含义"}}},fx={["52e0a178"]={q="鸦羽先知为什么派你去科多石？",a="鸦羽先知正在引导你这个萨满学徒踏上修行之路。她准备的大地灵契蕴含着一种魔法，能够让你感知到世间的灵体。她指引你在科多石的神圣圣所饮下药剂，目的是将你的灵魂永久地与大地元素相连，让你能直接与大地显灵体交流，领悟其核心智慧。",al={"鸦羽先知的目的","为什么要喝大地灵契","鸦羽先知为什么要我执行大地呼唤"}}},fp="13,245,24.449.0,22.456.0,23.205.0,27.115.0,42.151.0,46.204.0,52.165.0,54.210.0"}
P.entries["quest:1521"] = {n="大地的召唤",s="这一仪式标志着一位年轻的牛头人萨满在莫高雷完成了与大地之灵的初次交流。在饮下大地之药，并亲自与大地之魂进行对话后，这位初学者会得到一块原始的石料作为信物带回。回到纳拉其营地，标志着这位初出茅庐的神秘主义者与四大元素中的第一位正式建立了羁绊。",h="这一仪式标志着一位年轻的牛头人萨满在莫高雷完成了与大地之灵的初次交流。在饮下大地之药，并亲自与大地之魂进行对话后，这位初学者会得到一块原始的石料作为信物带回。回到纳拉其营地，标志着这位初出茅庐的神秘主义者与四大元素中的第...",kw={"call of earth","纳拉其营地","大地图腾","大地之魂","莫高雷","红云台地","粗石英","鸦羽先知","牛头人萨满"},ang={["class:Shaman"]="此仪式标志着你获得了第一座图腾。随身携带它将能稳固你的精神特质，并解锁你施放基础的大地系结界的能力。",["faction:Horde"]="萨满是新部落中至关重要的精神支柱和顾问，他们架起了凡人种族与卡利姆多狂暴元素力量之间的桥梁。",["race:Tauren"]="牛头人文化对大地母亲怀有崇高的敬意。参与这项试炼，可以将初学者直接与他们祖先家园的岩石与土壤绑定在一起。"},sec={{t="来自群山的馈赠",b="在红云台地附近的峭壁之上，通过与大地之魂的交流，这位灵魂会赐予你一块简单的粗石英。虽然外表平凡，但这块石头代表了一份元素契约和大地本身的坚韧。灵魂提醒年轻的萨满，耐心和力量是大地所要求的核心美德，并承诺只要相互尊重，就能与这片大地达到和谐共处。"},{t="第一座图腾",b="回到纳拉其营地后，鸦羽先知会利用这块被赠予的石英来制作萨满的第一座大地图腾。这不仅仅是一个地位的象征，图腾更是一个永久的物质与精神锚点。通过这个雕刻出的核心，初学者可以引导大地本身的沉稳与守护魔法，从而迈出了通往四大元素之路上真正的一步。"}},faq={{q="粗石英有什么用？",a="这块石英是大地之魂亲自赐予的信物，以证明你们已经完成了交流。鸦羽先知会将其作为你新制作的大地图腾的精神核心。",al={"我为什么需要粗石英","石英有什么用","粗石英用途"}},{q="为什么大地图腾对萨满如此重要？",a="图腾是萨满引导元素力量的媒介。如果没有大地图腾作为核心，萨满就无法祈求大地之灵来展现他们的法术和守护结界。",al={"我为什么需要大地图腾","大地图腾有什么用","大地图腾背景"}},{q="鸦羽先知是谁？",a="鸦羽先知是驻扎在红云台地纳拉其营地的精神向导和萨满训练师。她负责监督年轻牛头人的元素试炼，引导他们进行初次的幻象体验，并为他们制作神圣的器具。",al={"谁是鸦羽先知","鸦羽先知背景","纳拉其营地先知"}},{q="鸦羽先知提到的四条道路是什么？",a="她指的是萨满必须掌握的四大原始元素：土、火、水和风。大地是基础，代表着坚韧与稳固，这也是初学者面临的首个试炼。",al={"四条道路","萨满四元素","这四条道路是什么"}},{q="这种交流在哪里进行？",a="大地之魂栖息在莫高雷红云台地边缘的崎岖峭壁上，只有在饮下特制的大地之药后才能到达。",al={"我在哪里能找到大地之灵","大地之魂位置","灵魂在哪里"}},{q="其他部落萨满也需要进行类似的仪式吗？",a="是的。杜隆塔尔的兽人和暗矛巨魔也会在试炼谷进行他们自己版本的“大地之唤”，寻求与当地的大地之魂进行交流，从而雕刻出他们的第一座图腾。",al={"兽人会进行大地之唤吗","巨魔的大地之唤","所有萨满都会获得大地图腾吗"}}},fx={["43ccddec"]={q="大地之魂为什么要你回去找鸦羽先知？",a="这个元素之灵考验了你的决心，认定你有资格踏上大地之道。它将自身的一部分——粗石英——赐予你，作为你与它交流、彼此尊重的实物凭证。它让你回去找鸦羽先知，好让这块石头成为你第一个图腾的核心；在你践行耐心、力量与智慧时，大地之灵也将与你结下联系。",al={"大地之魂的目的","为什么要交出粗石英","大地显灵体的目的"}}},fp="13,352,24.402.0,15.387.0,40.178.0,47.203.0,25.241.0,51.205.0,37.157.0,48.198.0"}
P.entries["quest:1524"] = {n="火焰的召唤",s="这次朝圣标志着萨满追求与火焰沟通的第二个试炼。受来自贫瘠之地的卡纳尔·菲斯指派，一位萨满学徒带着未点燃的眠炎火炬，前往杜隆塔尔怒水河上方高耸的隐秘山顶圣殿。",h="这次朝圣标志着萨满追求与火焰沟通的第二个试炼。受来自贫瘠之地的卡纳尔·菲斯指派，一位萨满学徒带着未点燃的眠炎火炬，前往杜隆塔尔怒水河上方高耸的隐秘山顶圣殿。",kw={"贫瘠之地","call of fire","杜隆塔尔","火焰图腾","卡纳尔·菲斯","眠炎圣殿","怒水河","泰尔夫·祖拉姆"},ang={["class:Shaman"]="通往火焰图腾的道路需要直接与卡利姆多的元素力量沟通，这就要求进行远程圣殿的朝圣，而不仅仅是简单的指导。",["faction:Horde"]="兽人、牛头人和巨魔之间共同的萨满教义统一了他们的精神传统，将弟子们从贫瘠之地的平原送往杜隆塔尔的神圣悬崖。"},sec={{t="准备就绪的考验",b="虽然学徒可能展示了原始的神秘力量，但火焰要求的远不止力量；它需要节制、专注和尊重。卡纳尔·菲斯将眠炎火炬托付给萨满。该物品既是仪式用具，也是凭证，向圣殿的守护者证明持有者已被正式判定为可以尝试此试炼。"},{t="隐秘山峰",b="目的地位于杜隆塔尔南部崎岖山脉中，怒水河的彼岸。只有一块刻有火符文的风化石头作为标记，一条晦暗的秘道通向该地区最高处之一。山顶上坐落着眠炎圣殿，由巨魔隐士泰尔夫·祖拉姆看守。泰尔夫经常会赶走好奇的旅行者和寻宝者，保护神圣的火盆免受世俗目光的打扰，直到真正的祈求者带着未点燃的火炬到来。"}},faq={{q="眠炎火炬的用途是什么？",a="未点燃的火炬是卡纳尔·菲斯提供的一种意图信物。它向圣殿的守护者泰尔夫·祖拉姆表明持有者是一位有资格的萨满学徒，否则他会拒绝一般的流浪者和寻宝者。",al={"为什么要携带火炬","眠炎火炬","火炬的含义"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位部落的萨满隐士，他在杜隆塔尔南部的山峰上守护着眠炎圣殿。他保护着火盆，防止那些不理解或不尊重灵魂本质的人接近。",al={"泰尔夫·祖拉姆","圣殿守护者","圣殿里的巨魔是谁"}},{q="秘道在哪里？",a="这条路径始于杜隆塔尔，在跨越怒水河的桥梁以南。沿着山脉与海岸线交汇处的河岸，一块刻有火焰符文的立石标记着通往高耸山脊的狭窄路径。",al={"秘道位置","如何找到眠炎圣殿","上山的路"}},{q="为什么火炬必须在未点燃的状态下带来？",a="火焰不能简单地获取；它必须通过适当的仪式来唤醒和掌握。携带未点燃的火炬象征着萨满在进行点燃它所需的沟通之前，火焰所处的休眠状态。",al={"为什么火炬未点燃","眠炎火炬仪式","为什么是眠炎"}},{q="到达泰尔夫·祖拉姆处后会发生什么？",a="一旦泰尔夫·祖拉姆确认了火炬，他会引导学徒进行更严酷、更危险的仪式，以点燃眠炎并证明对元素之火的掌控。",al={"call of fire的下一步","找到泰尔夫·祖拉姆之后做什么"}},{q="为什么这个圣殿对部落的其他成员保密？",a="元素力量在未经训练的人手中既不稳定又危险。萨满传统将神圣场所保留在远离日常定居点的地方，以免寻宝者和好奇者打扰安息的灵魂或招致灾祸。",al={"为什么要保密圣殿","圣殿是隐秘的吗"}}},fx={["10005cfa"]={q="卡纳尔·菲斯为什么派你去眠炎圣殿？",a="卡纳尔·菲斯明白，你的灵魂虽拥有驾驭火焰的原始力量，但仅有力量还不够。火焰危险、具有毁灭性且难以驯服；若过早将火焰图腾交给你，可能酿成灾难。作为导师，他有责任确保你经历神圣的准备与敬意试炼。他派你去找泰尔夫·祖拉姆，让你证明自己的自律，并在元素面前赢得持有火焰的资格。",al={"卡纳尔·菲斯为什么要我完成这件事","卡纳尔·菲斯的目的","卡纳尔为什么派你去"}},b8cc7d40={q="为什么必须由你踏上这段旅程，而不是让别人去？",a="这趟朝圣并非简单的差事，也不是军事防卫任务，而是一项极为个人的灵性成年仪式。眠炎圣殿对部落的普通成员和一般卫兵严格保密。只有追求与火元素交流的学徒，才能携带沉睡的火炬，寻求泰尔夫·祖拉姆的指引，并证明自己有资格驾驭元素的力量。",al={"为什么是我执行火焰召唤","为什么派我去眠炎圣殿","为什么卫兵不能去"}}},fp="12,269,19.369.0,15.481.0,54.221.0,19.227.0,33.234.0,36.219.0,40.173.0,58.227.0"}
P.entries["quest:1525"] = {n="火焰的召唤",s="这项试炼标志着萨满与火焰沟通的重要准备工作，要求受试者收集酿造火焰灵契所需的挥发性原料。泰尔夫·祖拉姆需要充满热量和魔法力量的组件：来自剃刀鬃毛地卜师的焦油，以及藏在杜隆塔尔的火刃氏族邪教徒手中的一袋黑暗试剂。",h="这项试炼标志着萨满与火焰沟通的重要准备工作，要求受试者收集酿造火焰灵契所需的挥发性原料。泰尔夫·祖拉姆需要充满热量和魔法力量的组件：来自剃刀鬃毛地卜师的焦油，以及藏在杜隆塔尔的火刃氏族邪教徒手中的一袋黑暗试剂。",kw={"火刃氏族","call of fire","尘风洞穴","火焰灵契","火焰焦油","剃刀鬃毛","试剂袋","泰尔夫·祖拉姆"},ang={["class:Shaman"]="这项仪式测试了年轻萨满平衡对立力量的能力，证明了火焰不仅仅是愤怒的燃料，当在智慧的指引下时，它也是活力与光明的工具。",["faction:Horde"]="这项试炼派遣部落的保卫者去打击边境上的两个紧迫威胁：贫瘠之地中不断侵蚀的剃刀鬃毛野猪人，以及潜伏在杜隆塔尔内部阴险的火刃氏族邪教徒。",["race:Orc"]="对于兽人来说，与火刃氏族打交道是让他们想起曾经腐蚀过他们族人的黑暗术士魔法的痛苦提醒，这使得将火焰重新确立为一种纯粹的自然元素成为了文化复兴的重要行为。"},sec={{t="酿造火焰灵契",b="为了感知并与火元素沟通，萨满不能仅依靠凡人的视觉。正如大地需要它自己的药剂一样，开启通往永恒之火的感官也需要一种专门的火焰灵契。这种药剂需要天生与热量和火焰相连的试剂。隐士泰尔夫·祖拉姆派遣受试者穿越杜隆塔尔并进入东部贫瘠之地，从那些掌握原始热量和腐蚀性巫术的人手中收集这些特定的元素。"},{t="敌人与元素",b="所收集的原料揭示了不同势力是如何利用火焰的。东部贫瘠之地的剃刀鬃毛野猪人施法者携带火焰焦油，这是一种在他们的大地仪式中产生的粘稠、易燃的副产品。相比之下，试剂袋必须从潜伏在尘风洞穴的火刃氏族邪教徒手中夺取，该洞穴坐落在剃刀岭东北部的峡谷中。虽然这些术士邪教徒将火焰用作毁灭和恶魔混乱的工具，但他们袋中的原始试剂仍然与元素本身保持着天然的共鸣。"},{t="火焰的本质",b="在酿造出灵契后，泰尔夫·祖拉姆传授了一个关于元素的重要真理：火焰不仅仅是毁灭和破坏。虽然它会燃烧和吞噬，但它也是温暖、光明和创造的核心。真正的平衡需要理解对立的力量赋予彼此意义，而睿智的萨满会协同使用对立的元素力量，而不是仅仅把火焰当作一种武器。"}},faq={{q="什么是火焰灵契？",a="灵契是由萨满使用与特定元素相关的原料制备的仪式药剂。饮用火焰灵契会暂时将萨满的精神和视野与火元素位面连接起来，使他们能够感知并与在普通感官下不可见的火元素之灵交谈。",al={"什么是火焰灵契","火焰灵契的含义","为什么要饮用灵契"}},{q="我在哪里可以找到火焰焦油？",a="火焰焦油由居住在贫瘠之地东部平原、杜隆塔尔怒水河对岸的剃刀鬃毛野猪人施法者携带。地卜师、先知、秘术师和荆棘织法者经常携带这种浓稠、易燃的混合物用于他们的部落仪式。",al={"火焰焦油的位置","谁掉落火焰焦油","火焰焦油野猪人"}},{q="在哪里可以找到试剂袋？",a="试剂袋由尘风洞穴中的火刃氏族邪教徒携带。该洞穴位于杜隆塔尔剃刀岭东北部的峡谷上方，不要将其与更北边靠近海岸的骷髅石混淆。",al={"试剂袋的位置","哪个洞穴有试剂袋","火刃氏族试剂袋"}},{q="为什么萨满要使用术士的物品？",a="灵契需要天生充满特定元素的原料。因为火刃氏族邪教徒不断召唤具有毁灭性的恶魔火焰，他们的法术包中塞满了与火焰直接相关的强效试剂，提供了泰尔夫·祖拉姆调制药剂所需的精确催化剂。",al={"为什么要使用火刃氏族的试剂","萨满使用的术士物品","术士之火"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位孤独的巨魔萨满，他在剃刀岭南部的杜隆塔尔岩崖之上安营扎寨。他负责监督部落受试者的严酷火焰试炼，引导他们掌握毁灭与创造之间危险的平衡。",al={"泰尔夫·祖拉姆背景故事","泰尔夫·祖拉姆是谁"}},{q="这个任务之后会发生什么？",a="一旦泰尔夫·祖拉姆用收集到的试剂调制好火焰灵契，他就会派你前往附近休眠山峰的火热高地。在那里，你必须喝下这种药剂以面对元素之灵并获得你的火焰图腾。",al={"call of fire后续任务","获得试剂后","如何使用火焰灵契"}}},fx={["8d79977d"]={q="泰尔夫·祖拉姆为什么派你执行这项任务？",a="泰尔夫·祖拉姆正在引导你入门，学习更深奥的元素之道。要驾驭火焰的力量并获得火焰图腾，你必须饮下一种特制的药剂，名为火焰灵契。它能暂时使你的灵性感官与火焰领域相连。泰尔夫无法凭空调制这种药剂；他需要你取回与火焰紧密相连的材料，才能配制药剂，指引你踏上永恒之火的道路。",al={"泰尔夫·祖拉姆为什么需要这个","泰尔夫·祖拉姆的目的","为什么要帮泰尔夫·祖拉姆"}},["08a6380d"]={q="火焰焦油有什么用？",a="火焰焦油是泰尔夫·祖拉姆调制火焰灵契所需的两种关键催化剂之一。剃刀沼泽部族的施法野猪人将它带在身上，出没于贫瘠之地东部。这种焦油天生具有与火焰魔法相契合的不稳定特性，能为药剂提供足够的效力，使你的感官与元素之灵相连。",al={"为什么需要火焰焦油","火焰焦油的用途","火焰焦油有什么用"}},["52c07fd8"]={q="试剂袋有什么用？",a="试剂袋里装着完成火焰灵契所需的不稳定材料。泰尔夫·祖拉姆让你从剃刀岭东北方潜伏的火刃教徒手中夺取它，因为这些术士经常收集与火焰密切相关的材料，用于自己的黑暗巫术。无需四处搜寻稀有而分散的催化剂，教徒的个人藏匿处里就有与你的灵魂建立火焰联系所需的确切材料。",al={"为什么需要试剂袋","试剂袋的用途","萨满怎么用试剂袋"}},["65d894ad"]={q="杜隆塔尔的火刃教徒是什么人？",a="这些教徒是火刃氏族的凡人爪牙。火刃氏族是古老恶魔教派残留下来的一个隐秘组织，曾经效忠于暗影议会。他们潜伏在剃刀岭东北方峡谷上方的隐蔽洞穴里，就在部落眼皮底下施展禁忌的邪能魔法，并借助混乱的火焰力量，因此他们的试剂袋是调制元素药剂的上佳来源。",al={"火刃氏族的目标","教徒是什么人","杜隆塔尔的火刃氏族"}},f71fa686={q="为什么必须由你亲自收集材料，而不是泰尔夫·祖拉姆去？",a="这段旅程本身就是你灵性试炼的一部分。萨满必须证明自己有能力面对危险、对抗腐化魔法，并展现决心，才能获得与火焰交流的资格。泰尔夫·祖拉姆在这座偏远山峰上担任导师和向导，但与元素的交流无法由他人代劳——你必须亲自夺取那些将你与火焰相连的材料。",al={"为什么泰尔夫不能去取","为什么由我执行火焰任务","萨满为什么要收集材料"}}},fp="12,343,22.442.0,20.527.0,19.406.1,21.302.0,29.275.0,33.219.0,42.311.0,19.245.0,30.223.1"}
P.entries["quest:1526"] = {n="火焰的召唤",s="这一试炼标志着萨满在杜隆塔尔山巅与火焰建立调和的关键时刻。在隐士泰尔夫·祖拉姆的指引下，试炼者必须喝下一瓶强效火焰灵契，以感知并直面微型火焰显灵。击败这种元素之灵后，会获得一枚余烬，用于点燃永恒火焰神龛的火盆，并点燃仪式火炬。",h="这一试炼标志着萨满在杜隆塔尔山巅与火焰建立调和的关键时刻。在隐士泰尔夫·祖拉姆的指引下，试炼者必须喝下一瓶强效火焰灵契，以感知并直面微型火焰显灵。击败这种元素之灵后，会获得一枚余烬，用于点燃永恒火焰神龛的火盆，并点燃仪式...",kw={"休眠之焰火盆","call of fire","杜隆塔尔","火焰灵契","火焰图腾","微型火焰显灵","萨满试炼","永恒火焰神龛","泰尔夫·祖拉姆"},ang={["class:Shaman"]="与坚实而不屈的土元素不同，火元素是反复无常且极具破坏性的。这项试炼教会我们，火焰会吞噬那些优柔寡断的召唤者，它需要坚定不移的专注和权威才能将其驾驭。",["faction:Horde"]="兽人和巨魔萨满踏上杜隆塔尔红色的岩脊，完成这场朝圣，以证明他们与大地上的烈焰之灵达成了调和。"},sec={{t="火焰之眼",b="对于未经过指引的人来说，火元素很少会显露真形。为了与它们沟通，萨满必须使用火焰灵契来改变自己的感知，这是一种由贫瘠之地和海岸各处采集的试剂调配而成的元素药剂。饮下此药剂后，感官便会向不可见的领域敞开，显露出在山峰岩石间舞动的微小元素和显灵。"},{t="直面显灵",b="火焰不会向被动的虔诚低头；它需要的是力量、果决和尊重。山顶上等待着一只微型火焰显灵。一旦萨满服下灵契，它就会察觉到萨满那锐利的目光，并等待挑战的开始。试炼者被教导要迅速出击，毫不迟疑，因为元素之火会通过延长的战斗汲取力量，战斗持续越久，它就越狂暴、越炽热。"},{t="休眠之焰火盆",b="随着显灵被击败，萨满可以以余烬的形式取回其残留的热量。回到山顶的神龛，将余烬放入休眠之焰火盆中。尽管杜隆塔尔的烈日和狂风不断侵蚀，但铭刻了符文的金属表面依然清凉如初，直到余烬落入盆中，瞬间迸发出有节奏的炽白烈焰，点燃仪式火炬。"}},faq={{q="这项试炼的目的是什么？",a="这项试炼旨在考验准萨满是否有资格驾驭元素之火。通过直面显灵并将其原始热量捕获在仪式火炬中，试炼者证明了自己的实力，并赢得了制作火焰图腾的权利。",al={"为何要进行call of fire","火焰图腾任务的含义","call of fire试炼"}},{q="为什么我需要喝下火焰灵契？",a="元素之灵通常存在于普通凡人视线之外。饮用火焰灵契可以削弱凡世的隔阂，让萨满能够感知并与聚集在山顶上的火元素进行物理层面的交互。",al={"火焰灵契有什么用","为什么需要灵契","无法看到火元素"}},{q="微型火焰显灵在哪里？",a="该显灵位于杜隆塔尔泰尔夫·祖拉姆驻足点上方山脊的最高峰，靠近永恒火焰神龛。",al={"显灵的位置","火元素在哪里","我该去哪里"}},{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位古怪的萨满隐士，居住在杜隆塔尔高处的岩石山脊上。他引导年轻的部落试炼者完成危险而又喜怒无常的火之仪式，以理解火焰的力量。",al={"泰尔夫·祖拉姆的作用","泰尔夫·祖拉姆的背景","那位隐士是谁"}},{q="为什么显灵在战斗中会变得更强？",a="火焰会随着时间的推移自然积聚、蔓延并汲取能量。萨满们被告诫要果断出击，因为长时间的犹豫会让元素之灵积蓄力量，并燃烧得愈发炽热。",al={"为什么火元素变得这么强","显灵的难度增长","迅速出击火焰"}},{q="点燃火盆后会发生什么？",a="点燃火盆后，仪式火炬也会随之点亮。试炼者携带这道圣火回到山下，以完成火焰图腾的制作。",al={"休眠之焰后要做什么","call of fire的后续任务","要把点燃的火炬带到哪里"}}},fx={e554f055={q="泰尔夫·祖拉姆为什么让你接受这场试炼？",a="泰尔夫·祖拉姆是你的元素之道导师，负责引导年轻萨满与火焰交流。火焰狂暴、具有毁灭性且变幻莫测；除非你证明自己有能力直面并驾驭它的本质，否则灵体不会赐予你力量或尊重。泰尔夫让你登上山峰，并非为了铲除威胁，而是要在战斗中锤炼你的灵魂，让你赢得持有火焰的资格。",al={"泰尔夫·祖拉姆的目的","泰尔夫·祖拉姆为什么需要这个","为什么要接受这场试炼"}},e534729d={q="余烬有什么用？",a="余烬是从被击败的次级火焰显灵体身上取得的纯净元素残留物。要完成仪式，你必须将这团火焰核心带到永恒之火圣殿，放入沉睡的火盆中。以元素鲜活的精华重新点燃冰冷的火盆，会燃起神圣的白炽火焰，继而点亮你的沉睡火炬，并确立你与火焰元素之间的联系。",al={"余烬的用途","为什么需要余烬","余烬的作用"}},["8a082e57"]={q="次级火焰显灵体是什么？它为什么会在这里？",a="次级火焰显灵体是一个徘徊在山顶、靠近永恒之火圣殿的元素之灵。只有饮下神圣的火焰灵契、开启感官的人才能看见它；它代表着火焰原始而好斗的本性。它永远守在峭壁之上，考验着有志成为萨满的人，挑战所有寻求掌控火焰者征服它炽烈的怒火。",al={"次级火焰显灵体的背景","这个显灵体是谁","火元素为什么在这里"}}},fp="12,363,17.359.0,29.427.0,32.403.1,34.232.0,38.217.0,47.140.0,19.189.0,58.193.0,38.158.0"}
P.entries["quest:1529"] = {n="水之召唤",s="“水之召唤”是一项入门仪式，指引着从雷霆崖高地崛起的部落萨满前往贫瘠之地的东海岸。为了与洁净的水元素沟通，初学者必须寻访避世的水之先知伊斯伦。这次会面标志着获取水之图腾这一精神旅程的第一步。",h="“水之召唤”是一项入门仪式，指引着从雷霆崖高地崛起的部落萨满前往贫瘠之地的东海岸。为了与洁净的水元素沟通，初学者必须寻访避世的水之先知伊斯伦。这次会面标志着获取水之图腾这一精神旅程的第一步。",kw={"贫瘠之地","call of water","水之先知伊斯伦","棘齿城","萨满","怒水河","雷霆崖","水之图腾","萨尼斯·织火"},ang={["class:Shaman"]="这项仪式标志着从早期的元素试炼向掌握洁净、复苏和潮汐的流动力量的转变。",["faction:Horde"]="萨满教依然是新部落的基石，将兽人、巨魔和牛头人精神追求者之间的古老传统联系在了一起。",["race:Tauren"]="这项任务始于雷霆崖，它将年轻的舒哈鲁萨满从莫高雷的庇护平原带向了更广阔的卡利姆多。"},sec={{t="来自雷霆崖的召唤",b="在掌握了坚不可摧的大地和狂野的火焰后，有志向的萨满最终会被认为有能力去探究元素更深层的奥秘。在雷霆崖，像萨尼斯·织火这样的训练师会识别出学生何时展现了足够的纪律性，从而去接触那流动的、洁净的水之灵。这段旅程需要离开莫高雷风吹草动的平顶山，向东穿过贫瘠之地被烈日灼烧的平原。"},{t="海岸边的隐士",b="这条路径通向水之先知伊斯伦，一位安静的神秘主义者，她远离喧嚣的定居点，居住在棘齿城南侧和怒水河河口以南的东海岸边一间简陋的渔屋里。站在浩瀚的大海边，伊斯伦通过元素在旅者周围萦绕的方式来解读他们是否做好了准备。看到求道者的精神中已经结合了稳固的大地、轻快的微风和温暖的火焰，她便会让他们为理解水的纯净而做好试炼的准备。"}},faq={{q="谁派我踏上这段旅程？",a="雷霆崖的萨满训练师，例如萨尼斯·织火，会在初学者在精神训练中取得了足够的进展，有能力去追求水之仪式时，发布这个任务。",al={"任务发布者","谁开启水之召唤","雷霆崖水之召唤任务在哪里接"}},{q="水之先知伊斯伦在哪里？",a="水之先知伊斯伦住在贫瘠之地东海岸的一间孤零零的渔屋里。她的住所位于棘齿城以南，怒水河入海口以南的海岸边。",al={"水之先知伊斯伦在哪里","伊斯伦位置","寻找伊斯伦"}},{q="“水之召唤”试炼的目的是什么？",a="这项试炼是每一位寻求与水沟通的萨满必经的成人礼。它考验初学者对元素纯净度的理解，并直接引向他们获取水之图腾的过程。",al={"为什么要完成水之召唤","水之召唤目的","萨满水之图腾任务"}},{q="其他部落种族会收到同样的指引吗？",a="虽然雷霆崖的入门召唤通常由牛头人接受，但在奥格瑞玛和杜隆塔尔的兽人和巨魔萨满也会收到类似的召唤，要求他们去贫瘠之地海岸寻找水之先知伊斯伦。",al={"这是牛头人专属吗","兽人水之召唤","巨魔水之召唤"}},{q="萨满在掌握水之前必须掌握哪些元素？",a="萨满在寻求水的流动本质之前，会先与稳固的大地以及具有破坏性却又能赋予生命的火焰沟通。正如伊斯伦在你到达时所指出的，大地、风和火必须先触动你的精神，水才会向你揭示它的纯净。",al={"先决条件","先获得哪些图腾","元素顺序"}},{q="找到水之先知伊斯伦后会发生什么？",a="与伊斯伦的交谈结束了从雷霆崖出发的初始旅程。她会立即给予你挑战，要求你在卡利姆多各地完成进一步的任务，以直接理解和净化水元素。",al={"接下来做什么","找到伊斯伦之后","水之召唤第二部分"}}},fx={["22e527b8"]={q="我为什么必须亲自踏上这段旅程？",a="萨满之道是一段极为个人的旅程。与元素沟通需要个人的精神修行和虔诚证明，不能交由守卫代劳，也不能由导师代你完成。正如水之先知伊斯伦所说，你必须亲自迈出每一步，向灵魂证明你拥有与水沟通所需的内在力量。",al={"为什么必须亲自去","为什么我得做水之召唤","能让别人去找伊斯伦吗"}},["6892158c"]={q="萨尼斯·织火为什么派我执行这项任务？",a="萨尼斯·织火是你萨满之路上的向导。他见证了你的耐心，以及你对初阶元素的掌握，因此认定你的灵魂已成长到足以面对水元素试炼的程度。他的职责不是每一步都带领你，而是判断你是否已准备就绪，并指引你去找水之先知伊斯伦，由他传授更深的智慧，考验你对水之纯净的理解。",al={"萨尼斯为什么派我去","萨尼斯·织火的目的","为什么要找水之先知伊斯伦"}}},fp="13,329,24.438.0,23.499.0,29.177.0,33.187.0,47.195.0,51.195.0,48.246.0,43.195.0"}
P.entries["quest:153"] = {n="红色皮质面罩",s="“红色皮质面罩”是西部荒野哨兵岭的哨兵加里安发布的一项悬赏任务。由于人民民兵在平原上艰难地追踪迪菲亚潜行者，加里安向任何愿意削减他们人数并带回这些歹徒所佩戴的独特红色布面罩的人提供赏金。",h="“红色皮质面罩”是西部荒野哨兵岭的哨兵加里安发布的一项悬赏任务。由于人民民兵在平原上艰难地追踪迪菲亚潜行者，加里安向任何愿意削减他们人数并带回这些歹徒所佩戴的独特红色布面罩的人提供赏金。",kw={"面罩","迪菲亚潜行者","人民民兵","红色皮质面罩","哨兵加里安","哨兵岭","西部荒野"},ang={["class:Rogue"]="迪菲亚强盗所佩戴的绯红色面罩严酷地提醒着人们，这些技艺高超的潜行者和扒手是如何在暴风城的家门口组织成一支军队的。",["faction:Alliance"]="当暴风城的皇家领导层未能提供援助时，接受人民民兵的悬赏直接支持了西部荒野的当地防御。"},sec={{t="效忠的标志",b="在整个西部荒野，红色面罩已成为迪菲亚潜行者无可混淆的标志。虽然该团伙雇佣了各行各业的普通扒手、劫掠者和叛徒，但他们以这面绯红色的旗帜将 ranks 团结在一起。对于哨兵岭的哨兵加里安和那支处境艰难的人民民兵来说，收集这些战利品有两个目的：确认消灭了强盗，并收集关于他们在乡村各处不断变换的前线的情报。"},{t="民兵的侦察工作",b="由于暴风城拒绝向西部荒野提供适当的军事增援，人民民兵严重依赖像哨兵加里安这样经验丰富的观察员来绘制迪菲亚的活动图。加里安整天在哨兵岭的安全地带监视强盗的巡逻，依靠路过的冒险者和民兵志愿者去做那些斩杀强盗的血腥工作，这些强盗已经将诚实的农民从他们的土地上赶走。"}},faq={{q="为什么迪菲亚要戴红色皮质面罩？",a="红色皮质面罩是迪菲亚潜行者的统一制服和效忠象征。它掩盖了前劳工、窃贼和歹徒的身份，同时给西部荒野剩余的农民带来了恐怖。",al={"迪菲亚红色面罩含义","为什么戴红色面罩","迪菲亚面罩背景"}},{q="谁是哨兵加里安？",a="哨兵加里安是驻扎在哨兵岭的人民民兵成员。他监视迪菲亚潜行者在整个西部荒野的动向和不断变化的前线，协调冒险者的悬赏任务以遏制强盗活动。",al={"哨兵加里安","谁发布红色皮质面罩任务","哨兵岭哨兵"}},{q="为什么民兵需要冒险者来收集这些面罩？",a="人民民兵的人手极其短缺，在没有皇家士兵或暴风城资金支持的情况下运作。通过为被杀死的强盗提供悬赏作为证据，像加里安这样的哨兵可以在不让哨兵岭防守人手不足的情况下削减迪菲亚的力量。",al={"为什么要收集面罩","为什么民兵要悬赏"}},{q="在哪里可以找到携带这些面罩的强盗？",a="迪菲亚强盗几乎遍布西部荒野的每一个角落，占据废弃的农场，在十字路口徘徊，在黄金海岸沿岸以及月溪镇山丘周围露营。",al={"哪里寻找迪菲亚面罩","西部荒野迪菲亚位置"}},{q="你上交面罩后它们会怎么样？",a="哨兵加里安将它们用作倒下强盗的证据，以追踪他们不断变化的前线，并衡量民兵的行动在多大程度上影响了该地区潜行者的人数。",al={"加里安如何处理面罩"}},{q="暴风城军队参与了这次悬赏吗？",a="不。暴风城军队基本上已经放弃了西部荒野，转而关注其他内部问题，将当地的防御完全留给了格里安·斯托曼和志愿人民民兵。",al={"暴风城卫兵西部荒野","暴风城是否帮助哨兵岭"}}},fp="20,225,20.390.0,30.354.0,44.189.0,21.194.0,64.216.0,52.170.0,52.188.0,46.166.0"}
P.entries["quest:1530"] = {n="水之召唤",s="Call of Water旅程的这一阶段旨在指引有抱负的部落萨满前往贫瘠之地那充满敌意的南部地区。受到水之先知伊斯伦的派遣，旅行者们必须找到一位名叫Brine的隐士，以加深对水之净化与修复本质的理解。",h="Call of Water旅程的这一阶段旨在指引有抱负的部落萨满前往贫瘠之地那充满敌意的南部地区。受到水之先知伊斯伦的派遣，旅行者们必须找到一位名叫Brine的隐士，以加深对水之净化与修复本质的理解。",kw={"贫瘠之地","brine","call of water","水之先知伊斯伦","野猪人","重生","萨满","water sapta"},ang={["class:Shaman"]="与水沟通是萨满成长过程中的一个关键里程碑，它将坚毅的大地和狂暴的火焰与治愈的恢复力量连接了起来。",["faction:Horde"]="部落的初学者穿越广袤的卡利姆多来掌握元素，以此向赋予大酋长的萨满们重要魔法的灵魂表达敬意。"},sec={{t="潮汐之课",b="在准许获取Water Sapta之前，水之先知伊斯伦会向初学者灌输一个基本真理：水象征着重生。它的水流可以切开岩石、洗净污秽、修复血肉，但其治愈力量完全取决于自身的纯净。受污染的水带来的只会是枯萎而非生命，每一位萨满在尝试与元素沟通之前，都必须领悟这种脆弱的平衡。"},{t="尘土中的隐士",b="为了继续前进，初学者必须深入贫瘠之地南部干旱的地带找到Brine。Brine选择在野猪人不断的袭击中过着与世隔绝的生活，她身边没有守卫，也毫无畏惧，掌握着塑造初学者与水之羁绊所需的特定知识和试炼。"}},faq={{q="水之先知伊斯伦是谁？",a="水之先知伊斯伦是一位萨满大师，居住在贫瘠之地商旅海岸以南的沿海地区。她指引部落萨满完成与水之灵魂沟通所必需的试炼。",al={"伊斯伦","水之先知","谁发布了这个任务"}},{q="为什么住在被野猪人包围的南贫瘠之地？",a="尽管受到野猪人的持续骚扰，Brine依然独自居住在南部荒原。虽然她也承认这种危险在外人看来很愚蠢，但她将自己的动机深藏于心，以此考验初学者是否有毅力找到她。",al={"为什么brine住在那里","brine 野猪人","brine的位置"}},{q="Water Sapta的目的是什么？",a="Sapta是一种仪式性混合剂，可以改变萨满的感知，使他们能够看见并与凡人肉眼无法察觉的元素之灵交流。",al={"sapta","water sapta的用途","为什么要获得water sapta"}},{q="水对萨满而言代表什么核心课程？",a="水体现了重生、净化和恢复活力。它拥有无与伦比的治愈潜力，但如果受到污染或停滞不前，它也可能导致毁灭性的腐朽与破坏。",al={"水的课程","元素含义 水","水 重生"}},{q="谁可以踏上这段旅程？",a="只有证明了自己的奉献精神，且已经与大地和火焰之灵调和的部落萨满，才会被指引去完成Call of Water的试炼。",al={"谁能获得call of water","call of water是部落独有的吗"}},{q="通往Brine的道路上潜伏着什么威胁？",a="南贫瘠之地险象环生，不仅有保卫荆棘巢穴的侵略性野猪人部落，还有游荡的野兽，它们会捕食远离十字路口或陶拉祖营地保护范围的粗心漫游者。",al={"南贫瘠之地的危险","通往brine的道路"}}},fx={c40eecf4={q="水之先知伊斯伦为什么派你去找 Brine？",a="水之先知伊斯伦希望引导你完成与水沟通的神圣试炼。她教导你，水象征着重生与治愈，若不洁净，也会带来毁灭性的腐化。为了准备好能够穿透帷幕、感知元素之灵所需的 Water Sapta，她指引你去找 Brine。Brine 掌握着你下一场成年礼所需的实用知识和材料。",al={"为什么派我去找 brine","水之先知伊斯伦的动机","为什么去找 brine"}},d6b5acd2={q="水之先知伊斯伦为什么让你独自踏上这段旅程？",a="与元素沟通是一段深刻而个人的精神旅程，每个立志成为萨满的人都必须亲自走过。守卫和长者都无法代你完成理解元素的试炼。你要穿越危机四伏的南贫瘠之地去寻找 Brine，以此证明自己的决心、自立能力，以及赢得水之灵青睐的虔诚。",al={"为什么我必须去找 brine","为什么我得做水之召唤","为什么让玩家独自前往"}}},fp="13,261,19.391.0,21.271.0,23.194.0,56.238.0,39.171.0,50.172.0,31.154.0,38.210.0"}
P.entries["quest:1531"] = {n="空气的召唤",s="“空气的召唤”是部落萨满祭司成长道路上必不可少的试炼，目的是掌握驾驭风之力的技巧。这项任务由Grommash Hold的希尔恩·火结发起，指引修行者远赴卡利姆多南部，去拜访那位隐居的普拉特·白云。在她的指点下，萨满祭司将获得元素修行的最后一根图腾：空气图腾。",h="“空气的召唤”是部落萨满祭司成长道路上必不可少的试炼，目的是掌握驾驭风之力的技巧。这项任务由Grommash...",kw={"空气图腾","空气的召唤","奥格瑞玛","普拉特·白云","希尔恩·火结","萨满任务","千针石林","valley of spirits"},ang={["class:Shaman"]="获得空气图腾是萨满修行初期的一个重要里程碑，它允许你与大地、火焰和水之灵一同呼唤风之灵。",["faction:Horde"]="萨满传统将部落的各个种族联系在一起，依靠散布在卡利姆多中部各地的长者和隐士来传承这些神圣的习俗。"},sec={{t="南方的气息",b="当萨满祭司已经获得了大地、火焰和水的认可，并完成了初步的修行，他们便做好了驾驭风这一微妙而多变元素的准备。在奥格瑞玛，巨魔训练师希尔恩·火结能看出门徒何时准备好迈出这关键的一步。他没有让修行者在杜隆塔尔的峡谷中进行测试，而是指引他们向南穿过贫瘠之地，进入千针石林的峡谷迷宫。"},{t="云行者的隐居处",b="等待着旅人的是普拉特·白云，一位居住在千针石林砂岩台地高处洞穴中的隐士。她与伴侣远离部落营地的喧嚣，静静地生活在这里。在传授风的秘密之前，普拉特要求修行者表现出应有的恭敬。当你带着足够的敬意拜访她时，她会传授你具象化空气图腾所需的知识与专注力，从而补全萨满祭司的元素循环。"}},faq={{q="谁发布这项任务？",a="希尔恩·火结，一位居住在奥格瑞玛Grommash Hold的巨魔萨满训练师，会在萨满祭司达到相应等级后向他们提供该任务。",al={"任务发布者","如何获取空气的召唤","希尔恩·火结"}},{q="我在哪里可以找到普拉特·白云？",a="普拉特·白云位于千针石林。从南贫瘠之地走下升降梯，向东穿过峡谷底部，即可找到她居住的洞穴。",al={"普拉特·白云位置","寻找普拉特","空气图腾npc"}},{q="空气图腾有什么用？",a="空气图腾是萨满祭司获得的第四个也是最后一个元素焦点。携带它允许萨满祭司调用空气元素的法术和图腾，从而获得速度、优雅和基于风的力量。",al={"空气图腾用途","为什么要做空气图腾任务","空气图腾有什么用"}},{q="为什么希尔恩·火结要让我去这么远的地方？",a="掌握元素之力需要向那些毕生致力于与特定灵魂沟通的导师求教。普拉特·白云对千针石林峡谷中变幻莫测的风有着深刻的见解，这使她成为学习驾驭空气之力的理想导师。",al={"为什么在千针石林","为什么是普拉特·白云"}},{q="我需要先完成其他元素图腾任务吗？",a="是的。萨满祭司的训练遵循严格的元素循序，从大地开始，接着是火和水，最后证明自己有能力驾驭空气。",al={"前置条件","图腾顺序","我可以先做空气图腾吗"}},{q="其他城市有该任务的其他版本吗？",a="是的。雷霆崖等部落主城的萨满训练师也会提供指引，将修行者派往千针石林寻找普拉特·白云。",al={"雷霆崖空气图腾","幽暗城空气图腾"}}},fx={["9e3dc8ab"]={q="希尔恩·火结为什么派你去找普拉特·白云？",a="希尔恩·火结认为，你的萨满修行已经进步到足以与空气之灵沟通的程度。他无法亲自赐予你空气图腾的沟通之力，因为这份智慧掌握在千针石林的普拉特·白云手中。作为导师，他有责任指引你前去，让深谙风之灵习性的普拉特教会你如何尊重这些反复无常的灵魂。",al={"希尔恩·火结的动机","希尔恩为什么要完成此事","为什么派我去找普拉特·白云"}},bc8bd922={q="希尔恩·火结为什么需要你去，而不亲自处理此事？",a="萨满之道是一段个人的精神旅程，无法由他人代行。希尔恩·火结已经能够驾驭元素，并在奥格瑞玛为部落训练新手。要赢得空气图腾，你必须亲自在普拉特·白云和她沟通的风之灵面前证明自己的谦逊、坚韧和尊重。",al={"为什么我得做空气的召唤","为什么我必须去找普拉特","希尔恩为什么不亲自去"}}},fp="11,342,23.463.0,25.425.0,22.163.0,33.182.0,31.196.0,47.272.0,57.171.0,60.169.0"}
P.entries["quest:1532"] = {n="空气的召唤",s="“空气的召唤”标志着部落萨满精神道路上的一个重要里程碑，指引他们寻求与不可预测的风元素沟通。此任务由雷霆崖的萨尼斯·织火提供，要求经验丰富的入门者南下前往千针石林，向普拉特·白云求教。掌握空气元素后，萨满就能获得引导大自然最迅捷力量所需的圣物图腾。",h="“空气的召唤”标志着部落萨满精神道路上的一个重要里程碑，指引他们寻求与不可预测的风元素沟通。此任务由雷霆崖的萨尼斯·织火提供，要求经验丰富的入门者南下前往千针石林，向普拉特·白云求教。掌握空气元素后，萨满就能获得引导大自...",kw={"空气图腾","空气的召唤","普拉特·白云","萨满","千针石林","雷霆崖","萨尼斯·织火"},ang={["class:Shaman"]="完成你的元素组合是一个深刻的转折点，让你得以使用空气图腾那迅捷的气流和缠绕闪电的力量。",["faction:Horde"]="通过将卡利姆多狂野的风束缚进神圣的图腾中，部落萨满巩固了他们初创联盟的精神支柱。",["race:Tauren"]="从莫高雷高耸的峭壁上俯瞰，舒哈鲁人将风尊为神圣的信使，它们将大地母亲的低语传遍整片平原。"},sec={{t="低语之风",b="在已经与大地的稳固、火焰的狂暴以及水的治愈深度达成共鸣之后，萨满迎来了最后的元素之柱：空气。萨尼斯·织火在雷霆崖的高处指引着修行者，他承认风比之前的元素更加变幻莫测，也更难以掌控。这次试炼要求修行者保持谦逊、专注，并对天空那狂暴的本质怀有与生俱来的敬畏。"},{t="南方的朝圣之旅",b="为了与风共鸣，萨满必须南下穿过广阔的贫瘠之地，进入千针石林那被风雕琢出的峡谷。在那里，在遥远的东部，住着隐士萨满普拉特·白云。她隐居在一个偏僻的悬崖洞穴中，那里终日回荡着峡谷的疾风。在授予空气图腾——这一召唤阵风、闪电和迅捷风灵的核心法器之前，她会先考验入门者的准备情况。"}},faq={{q="谁派我执行这项任务？",a="萨尼斯·织火是一位位于雷霆崖的萨满训练师，当入门者获得足够的经验来与空气元素产生共鸣时，他便会提供此任务。",al={"任务发布者","谁开启空气的召唤","萨尼斯·织火"}},{q="普拉特·白云在哪里？",a="普拉特·白云居住在千针石林风蚀峡谷内遥远东方的一个隐蔽洞穴中，位于贫瘠之地的南面。",al={"普拉特·白云位置","普拉特在哪里","寻找普拉特·白云"}},{q="为什么空气元素是最后才寻求的？",a="众所周知，空气是不可捉摸、突然且难以捉摸的。萨满教义要求入门者在尝试锚定狂野且无形的气流之前，必须先掌握大地的踏实稳固、火焰的动荡热量以及水的流动性。",al={"为什么空气是最后","萨满空气图腾背景故事","元素顺序"}},{q="找到普拉特·白云后我会得到什么？",a="普拉特·白云会赠予你空气图腾，这是你的精神媒介，能让你集中元素魔法并呼唤风灵来提供援助。",al={"空气图腾奖励","普拉特给予什么","空气的召唤任务奖励"}},{q="这个任务是牛头人专属的吗？",a="虽然任务始于牛头人的主城雷霆崖，但任何已经与前三种元素产生共鸣的部落萨满，都可以踏上这条通往千针石林的道路，以领取他们的空气图腾。",al={"兽人可以做这个吗","这是牛头人专属吗","部落萨满空气任务"}},{q="完成此任务后会发生什么？",a="普拉特·白云会在你到达时授予你空气图腾，使你能够立即召唤基于风的图腾，并提供进一步的训练和试炼，以磨练你与天空的联系。",al={"what comes next","空气的召唤之后","普拉特·白云任务"}}},fx={["52df4f2b"]={q="萨尼斯·织火为什么派我去做这个任务？",a="萨尼斯·织火认为，你的萨满修行已有所成，可以开始掌握最难以驾驭的元素：空气。作为你在雷霆崖的导师，他看出卡利姆多的疾风正在呼唤你。空气元素向来难以束缚和沟通，萨尼斯无法从高崖之上亲自传授你最后的领悟。因此，他指引你南下前往千针石林，由普拉特·白云引领你开始与空气之灵沟通。",al={"萨尼斯为什么派我去","萨尼斯·织火的动机","空气的召唤的目的"}}},fp="11,391,20.426.0,18.452.0,27.160.0,33.135.0,38.258.0,47.159.0,34.179.0,40.183.0"}
P.entries["quest:1534"] = {n="水之召唤",s="此任务代表了萨满祭司在追求Call of Water旅程中的最后一次收集试炼。在南贫瘠之地的隐士布莱恩（Brine）的指引下，初学者必须长途跋涉前往遥远北方的灰谷，在那幽暗的森林中寻找，并从星尘废墟内的古老喷泉中收集纯净之水。",h="此任务代表了萨满祭司在追求Call of...",kw={"灰谷","蓝色水囊","布莱恩","call of water","水之先知伊斯伦","密斯特拉湖","星尘废墟","萨满"},ang={["class:Shaman"]="此仪式考验萨满是否愿意跨越危险的边界以寻求平衡，收集绑定Water Totem所需的最后一种流体精华。",["faction:Horde"]="进入灰谷意味着要跋涉前往古老的卡多雷土地，在那里战歌氏族正在与敌对的暗夜精灵哨兵进行着持续不断的木材战争。",["race:Tauren"]="这场朝圣之旅连接了卡利姆多中心干旱的家园与那些存在于神话和古老歌谣中、挂满露水的圣洁森林。"},sec={{t="前往暮光之林",b="在收集了贫瘠之地她的小屋下的水坑样本，以及塔伦米尔的纯净之井的泉水后，萨满还需要寻找第三种、也是最后一种精华。布莱恩指引初学者穿过这片干燥平原的北部边界，进入被暗夜精灵视为圣地的茂密古老森林——灰谷。贫瘠之地的干旱与灰谷茂密的林冠形成了鲜明的对比，这突显了萨满若要真正与水元素和谐共处，就必须理解元素的多元性。"},{t="星尘废墟",b="星尘废墟隐匿在分隔灰谷与石爪山脉的山道附近，穿过密斯特拉湖波光粼粼的水面即可到达。这处僻静的精灵圣所环绕着宁静的水域和古老的石块，中间是一座纯净的喷泉。尽管废墟沉浸在原始的宁静之中，但这里受到野性元素和自然之灵的守卫，它们敌视任何入侵者，迫使萨满必须小心谨慎，才能取到那神圣的喷泉之水。"},{t="最纯净之水",b="带着装满水的蓝色水囊回到布莱恩身边，标志着这场跨越卡利姆多和东部王国的朝圣之旅圆满结束。将精灵喷泉的纯净样本与贫瘠之地水坑和塔伦米尔的样本混合，布莱恩调制出一瓶极度纯净的药剂。这种合剂将作为下一步试炼的催化剂：通过水之先知伊斯伦与水元素之灵进行沟通。"}},faq={{q="星尘废墟在哪里？",a="星尘废墟位于灰谷的西南部。从贫瘠之地向北出发后，沿路向西穿过密斯特拉湖，朝石爪山脉边界的山麓前进即可到达。",al={"星尘废墟位置","星尘废墟在哪里","如何前往星尘废墟"}},{q="为什么布莱恩需要来自精灵废墟的水？",a="为了与水之灵沟通，萨满必须收集代表该元素不同表现形式的水。星尘废墟中的喷泉拥有古老且充满魔法的纯净水，未受贫瘠之地干旱枯萎的影响，补齐了布莱恩仪式药剂所需的三种精华。",al={"为什么需要灰谷的水","为什么是星尘废墟","收集星尘之水的原因"}},{q="星尘废墟周围有什么威胁？",a="废墟及其周围的水域受到守护兽和自然之灵的保护，包括领地意识极强的水元素，以及攻击任何打扰森林之人的灰谷原生野兽。",al={"星尘废墟的敌人","星尘废墟是否危险","谁守护着喷泉"}},{q="布莱恩是谁，她为什么要帮忙？",a="布莱恩是一位苦行僧般的兽人萨满，居住在南贫瘠之地的一间孤屋中。她是协助水之先知伊斯伦的长者向导，通过考验萨满学徒的耐心、毅力和对水之百态的理解，以此来授予萨满该元素的祝福。",al={"谁是布莱恩","布莱恩背景故事","布莱恩的角色"}},{q="把水交给布莱恩之后会发生什么？",a="一旦布莱恩收到第三份样本，她就会将它们融合，调制出最纯净之水。然后，她会指引萨满回到东贫瘠之地海岸找水之先知伊斯伦，开启与元素的幻象沟通。",al={"call of water下一步","接下来要做什么","交给布莱恩后去哪"}},{q="灰谷对低等级的部落萨满来说安全吗？",a="灰谷是冲突不断的地区，暗夜精灵与部落在此激烈交锋。虽然穿过南部森林的路线可以避开阿斯特兰纳等主要的暗夜精灵定居点，但游荡的野生动物、好斗的元素生物以及联盟巡逻队对初学者来说仍是真正的威胁。",al={"灰谷是否危险","灰谷任务等级"}}},fx={d600fc8e={q="Brine为什么需要你完成这件事？",a="Brine 引导立志成为萨满的人完成水之试炼。你要从遥远而神圣之地采集纯净的水样，以此证明自己理解元素的决心。你从星尘废墟的古老喷泉取到水后，她便能将你收集的水样调制成至纯的饮剂，完成她在你的成年礼中所担负的部分，并让你做好返回水之先知伊斯伦身边的准备。",al={"brine为什么帮忙","brine对水之召唤的动机","为什么收集星尘废墟的水"}},bc32fa0f={q="装满水的蓝色水囊有什么用？",a="这个水囊装着从灰谷星尘废墟圣泉中汲取的纯净泉水。这是 Brine 调制无瑕之水所需的第三种、也是最后一种纯净水源。",al={"装满水的蓝色水囊有什么用","装满水的蓝色水囊用途","为什么要装满蓝色水囊"}},d1cea88a={q="Brine为什么派你去取水，而不亲自去？",a="这段旅程是你成为萨满的成年礼中不可或缺的一部分。寻找遥远的圣水考验你的耐力、对元素的尊重和虔诚。Brine 会留在她的池塘边准备仪式，但朝圣之路必须由你亲自走完。",al={"为什么我必须去取水","brine为什么不去灰谷","为什么派我去做水之召唤"}}},fp="13,306,31.489.0,21.457.0,27.423.1,40.204.0,45.299.0,48.209.0,36.268.0,48.224.1,46.268.0"}
P.entries["quest:1535"] = {n="水之召唤",s="这个任务标志着Brine在贫瘠之地为萨满祭司的水之调和所分配的第一次采集试炼。为了调制Water Sapta，Brine指引试炼者从她小屋下方被守卫的水坑中取样，并敦促他们思考沙漠中这种赋予生命的泉水其神圣且充满争夺的本质。",h="这个任务标志着Brine在贫瘠之地为萨满祭司的水之调和所分配的第一次采集试炼。为了调制Water...",kw={"贫瘠之地","brine","棕色水囊","call of water","quilboar","sapta","水坑"},ang={["class:Shaman"]="这次试炼教导萨满祭司，水元素不仅仅意味着治疗和恢复，它也是冲突和生命为了生存而进行绝望挣扎的催化剂。",["faction:Horde"]="控制和分享水源仍然是定居贫瘠之地的终极挑战，在这里，相互竞争的部落和野兽为了每一丝涓流不断地争斗。"},sec={{t="沙漠中的一课",b="在授予与灵魂沟通所需的Water Sapta之前，隐士Brine要求萨满试炼者研究世界上水的所有形态。在干旱的贫瘠之地，水是生存与饥饿的分界线。Brine要求萨满不仅要观察液体本身，还要观察周围的生态：森林如何在水的滋养下繁茂，沙漠如何在水的匮乏中干涸，以及生物会为了保护哪怕是最卑微的泉水而杀戮。"},{t="Quilboar的宝藏",b="Brine山丘下的水坑被当地的Quilboar严密守卫着。对他们来说，任何一潭水都是无价的宝藏，每当天空降雨，他们都会以宴席庆祝。虽然Brine对这种因囤积而产生的不可避免的暴力感到遗憾，但她指出，Quilboar狭隘的贪婪和分裂的氏族限制了他们的威胁，为在平原上努力生存的其他种族保留了一种不稳定的平衡。"}},faq={{q="为Brine收集水的目的是什么？",a="Brine需要来自世界各个角落的纯净水样本来调制一种仪式用的Water Sapta。这种药剂能开启试炼者的感知，使他们能够直接与水元素之灵沟通。",al={"为什么要取水","brine的水之任务","call of water任务3的目的"}},{q="为什么Brine下方那个水坑会有如此激烈的争夺？",a="在贫瘠之地干旱的气候中，水是最宝贵的资源。当地的Quilboar将任何水潭都视为神圣的宝藏，并会激烈反击任何试图取水的人。",al={"为什么quilboar要守卫水源","quilboar的水塘","贫瘠之地的水坑"}},{q="Brine是谁？",a="Brine是一位兽人萨满祭司兼隐士，居住在俯瞰南贫瘠之地的一间孤屋里。她拥有关于水和元素之灵的深厚智慧，指引着Horde的萨满祭司走上沟通之路。",al={"brine是谁","brine 贫瘠之地","brine npc"}},{q="把装满水的棕色水囊交还后会发生什么？",a="当你带着从水坑采集的样本回来后，Brine会扩展你的朝圣之旅，派遣你前往更远的地方，从截然不同的环境中汲取纯净之水，例如希尔斯布莱德丘陵中塔伦米尔的水井。",al={"call of water下一步","水坑任务之后","brine的下一步任务"}},{q="为什么Brine会提到Quilboar的分裂？",a="Brine指出，Quilboar激烈的领土意识和氏族竞争加剧了他们自身的苦难。如果他们团结起来，而不是为了孤立的泉水而战，他们会对贫瘠之地的其余部分构成更大的危险。",al={"brine对quilboar的评价","为什么quilboar互相争斗"}},{q="什么是Sapta？",a="Sapta是一种神秘的药剂，由萨满祭司使用采集到的试剂和元素水调制而成。饮用它可以扩展一个人的灵视，揭示通常对凡人肉眼隐藏的元素生物。",al={"什么是sapta","water sapta的含义"}}},fx={["6eca6e0d"]={q="装满水的棕色水囊有什么用？",a="装满水的棕色水囊里装着从 Brine 山丘下方那处争夺不断的池塘采集的水样。Brine 要你收集这种水，不只是为了调制 Water Sapta 的材料，也是为了让你从萨满试炼中获得教训。取水时，你会亲眼见到稀缺而维系生命的液体，如何引发当地野猪人的激烈争夺和流血冲突。",al={"装满水的棕色水囊的用途","为什么要装满水的棕色水囊","装满水的棕色水囊"}}},fp="13,326,22.466.0,20.449.0,50.215.0,58.187.0,13.210.0,56.227.1,49.248.0,16.208.0"}
P.entries["quest:1536"] = {n="水之召唤",s="这次朝圣任务要求一名有抱负的萨满祭司从干旱的Barrens出发，跨越海洋前往处于争夺中的希尔斯布莱德丘陵。在那里，在Forsaken控制的塔伦米尔小村庄里，有一口小井，尽管周围是一片腐朽，它却奇迹般地保持了纯净。收集井水可以让学员明白，纯洁与希望即使在最黑暗的环境中也能持久存在。",h="这次朝圣任务要求一名有抱负的萨满祭司从干旱的Barrens出发，跨越海洋前往处于争夺中的希尔斯布莱德丘陵。在那里，在Forsaken控制的塔伦米尔小村庄里，有一口小井，尽管周围是一片腐朽，它却奇迹般地保持了纯净。收集井水...",kw={"barrens","brine","call of water","希尔斯布莱德","sapta","萨满","塔伦米尔","thrall","水囊"},ang={["class:Shaman"]="从世界各地取水是一种对承诺的考验，教导你在身处东部王国的苦难之地时，也要学会寻求和谐与生命。",["faction:Horde"]="造访塔伦米尔让年轻的卡利姆多出生的Horde战士和萨满祭司们直面他们不安的新盟友Forsaken，以及对抗希尔斯布莱德人类防御者的前线战争。",["race:Orc"]="这次试炼提供了一个反思Thrall持久的生存与力量遗产的时刻，提醒Orc们他们为自由所付出的沉重代价。"},sec={{t="奇迹之泉",b="在为Water Sapta准备试剂时，隐士Brine指引学员跨越海洋前往希尔斯布莱德丘陵的塔伦米尔。在人类的抵抗和新结盟的Forsaken那被瘟疫污染的影响下，镇中心的一口小井却出奇地产生着纯净、未受污染的泉水。Brine将这口泉水视为一种神圣的遗迹——一个在污秽之海中幸存的纯净孤岛。"},{t="黑暗中的坚韧",b="对Brine来说，塔伦米尔的纯净水井不仅仅是一种配料；它更是一堂关于韧性的深刻课程。她将其生存与Warchief Thrall本人相提并论，Thrall在面对不可能的困境时，忍受了巨大的苦难、囚禁和悲伤，最终崛起并领导了Orc人民。正如Thrall是Horde重燃希望的灯塔一样，塔伦米尔的水井证明了生命与纯洁可以在悲剧和腐败中坚持下来。"}},faq={{q="水样是在哪里收集的？",a="样本直接取自塔伦米尔镇中心的一口水井，这是一座位于希尔斯布莱德丘陵的古老人类定居点，现在被Forsaken占据。",al={"塔伦米尔的水","水井在哪里","call of water水井位置"}},{q="为什么Brine要派你到那么远的地方去取水？",a="Brine需要独特的精华之水来调制Water Sapta，这是一种让萨满祭司能够感知元素之灵的药剂。她在早些时候前往希尔斯布莱德的旅途中发现了这口泉水，并认为它在Forsaken的腐朽中依然保持纯净，这在元素上具有强大的力量，在精神上具有指导意义。",al={"为什么是塔伦米尔","为什么是希尔斯布莱德的水","brine为什么需要这水"}},{q="什么是塔伦米尔？",a="塔伦米尔曾是希尔斯布莱德丘陵北部一个简朴的人类城镇。在Third War和Lordaeron陷落之后，它落入了Sylvanas Windrunner的Forsaken的控制之下，他们现在将其作为对抗该地区人类军队的坚固Horde前哨。",al={"塔伦米尔历史","谁拥有塔伦米尔"}},{q="这个任务与Thrall有什么联系？",a="Brine用这口未受污染的水井来类比Warchief Thrall。正如这口井在瘟疫和死亡的包围中依然保持着新鲜的纯净一样，Thrall在忍受奴役和深重苦难的同时，保持了引导新Horde所需的道德毅力和远见。",al={"brine thrall对话","thrall的关联"}},{q="交还装满的水囊后会发生什么？",a="Brine会收下装满水的红色水囊，并告诉你，在完成调制Water Sapta所需的试剂混合物之前，还需要采集最后一种独特的水样。",al={"call of water接下来做什么","塔伦米尔取水后"}},{q="为什么这口井的纯净被认为是不寻常的？",a="Lordaeron的大部分地区都遭受了Scourge亡灵瘟疫的灾难性污染，Forsaken的定居点很少与新鲜、鲜活的泉水联系在一起。塔伦米尔的中心水井至今仍能汲取原始的清水，这使它成为了一处罕见的、未被腐蚀的遗迹。",al={"为什么塔伦米尔的水是纯净的","forsaken污染的水井"}}},fx={["05ee6a54"]={q="装满水的红色水囊有什么用？",a="装满水的红色水囊里装着从希尔斯布莱德塔伦米尔水井汲取的纯净泉水。Brine 需要这份未受污染的水样与其他水样一同调制 Water Sapta 的特殊试剂。饮下这种饮剂后，你将获得与水之灵直接沟通所需的灵视。",al={"装满水的红色水囊用途","为什么要装满水的红色水囊","塔伦米尔的水样"}}},fp="13,377,19.416.0,21.435.0,36.167.0,46.297.0,20.265.0,38.277.0,50.173.0,44.269.0"}
P.entries["quest:154"] = {n="归还梳子",s="“归还梳子”是暮色森林中的一个联盟差事，结束了与盲眼玛丽这一灵体的闹鬼交易。在被要求用一把梳子收集她的一缕幽灵发丝后，这个饱受折磨的鬼魂因失去美貌而陷入绝望，并将梳子扔了出去。将缠着发丝的梳子带回给伊瓦夫人，这位神秘主义者就能纺织出虚幻的幽灵的发丝。",h="“归还梳子”是暮色森林中的一个联盟差事，结束了与盲眼玛丽这一灵体的闹鬼交易。在被要求用一把梳子收集她的一缕幽灵发丝后，这个饱受折磨的鬼魂因失去美貌而陷入绝望，并将梳子扔了出去。将缠着发丝的梳子带回给伊瓦夫人，这位神秘主义...",kw={"盲眼玛丽","夜色镇","暮色森林","幽灵的发丝","伊瓦夫人","归还梳子"},ang={["class:Priest"]="目睹盲眼玛丽痛苦的自厌，为那些因悲伤而非恶意而滞留在凡世的游荡灵魂的折磨提供了一个阴暗的视角。",["faction:Alliance"]="在夜色镇和玛丽荒凉的住所之间穿行阴暗的道路，让旅行者们暴露在笼罩着暮色森林中心的那种无处不在的腐朽之中。",["profession:Tailoring"]="纺织幽灵的发丝突显了暮色森林怪异的技艺，证明了灵体材料可以被收集并梳理成耐用的超自然纺织品。"},sec={{t="苦涩的倒影",b="盲眼玛丽徘徊在夜色镇以南的一间破败小屋里，永远地哀悼着她悲惨的死亡和改变了的状态。当带着伊瓦夫人的梳子走近她时，这种凡俗梳妆的提醒只会加深她的悲伤。当她意识到自己现在只不过是一个幽灵——一个被剥夺了凡人优雅、再也不会有人去爱的怪物时，她惊恐地退缩了，并将梳子和纠缠在梳齿上的幽灵发丝塞回了旅行者的手中。"},{t="编织超自然之物",b="伊瓦夫人在夜色镇等待梳子的归还，她很清楚这项任务的恐怖本质。既然弄到了幽灵发丝，这位占卜师就拥有了纺织一卷幽灵的发丝所必需的稀有灵媒。伊瓦将这些虚幻的纤维纺成线，并为在精细纺织过程中留下的任何多余发丝向旅行者支付报酬。"}},faq={{q="为什么盲眼玛丽对梳子有惊恐的反应？",a="梳子提醒了盲眼玛丽关于她凡人的生活和美貌。看到自己沦为枯萎的幽灵形态，这引发了她极度的悲痛，驱使她拒绝梳子并哀叹自己已变成了一个再也不会有人珍惜的怪物。",al={"玛丽为什么难过","盲眼玛丽为什么尖叫","玛丽对梳子的反应"}},{q="伊瓦夫人如何处理梳子上的头发？",a="伊瓦夫人将梳子上收集到的发丝编织成幽灵的发丝，这是一种有着万千用途的神秘线，从束缚邪恶灵魂到为无生命物体缝入生命力，无所不能。",al={"为什么需要幽灵发丝","伊瓦夫人怎么处理幽灵发丝","伊瓦夫人的线"}},{q="盲眼玛丽在哪里？",a="盲眼玛丽盘踞在夜色镇以南，暮色森林静谧花园墓场附近的一间废弃破败小屋里。",al={"盲眼玛丽在哪里","盲眼玛丽的位置"}},{q="谁是伊瓦夫人？",a="伊瓦夫人是一位居住在夜色镇的神秘人类神秘主义者和占卜师。她为那些在暮色森林险境中穿行的人提供算命、晦涩的指引，并制作魔法饰品和试剂。",al={"谁是伊瓦夫人","夜色镇的伊瓦夫人"}},{q="将梳子归还给伊瓦夫人后会发生什么？",a="一旦伊瓦夫人收下梳子并准备好一卷幽灵的发丝，她就会让你把做好的线送到住在乌鸦岭墓地附近的隐士亚伯克隆比那里。",al={"what comes next","归还梳子后的下一个任务"}},{q="为什么伊瓦夫人在任务完成后给你钱？",a="伊瓦指出梳子上收集到的幽灵发丝远超纺织所需，于是她用几枚钱币作为报酬，买下了多余的发丝供自己使用。",al={"为什么我会得到钱","多余发丝的报酬"}}},fp="15,389,19.452.0,24.362.0,50.248.0,50.180.0,28.126.0,18.209.0,52.182.1,51.189.0"}
P.entries["quest:155"] = {n="迪菲亚兄弟会",s="在这场调查的关键阶段，人民民兵在一名变节潜行者的帮助下取得了突破。为了换取保护，这名迪菲亚叛徒同意直接带领联盟勇士前往兄弟会的秘密行动基地。旅程将径直穿过被占领的鬼镇月溪镇，从而揭开艾德温·范克里夫的私人领地。",h="在这场调查的关键阶段，人民民兵在一名变节潜行者的帮助下取得了突破。为了换取保护，这名迪菲亚叛徒同意直接带领联盟勇士前往兄弟会的秘密行动基地。旅程将径直穿过被占领的鬼镇月溪镇，从而揭开艾德温·范克里夫的私人领地。",kw={"死亡矿井","迪菲亚叛徒","艾德温·范克里夫","护送","格里安·斯托曼","月溪镇","人民民兵","哨兵岭","西部荒野"},ang={["class:Rogue"]="与一名曾经的迪菲亚潜行者并肩作战，可以让人深刻地看到犯罪地下世界背叛的代价，在这里，违背誓言的下场就是匕首。",["faction:Alliance"]="揭开藏身处是陷入苦战的人民民兵的一项重大军事突破，提供了对西部荒野的犯罪暴动进行决定性打击的第一个真正机会。",["race:Human"]="对于暴风城的人类来说，看到月溪镇陷入无政府状态并被曾经的石匠工会成员占据，凸显了自第三次战争以来王国已经分崩离析到何种程度。"},sec={{t="变节者的交易",b="当一名被俘的强盗同意开口后，格里安·斯托曼针对迪菲亚兄弟会的行动迎来了一个转折点。面对被昔日兄弟处决或暗杀的命运，这名迪菲亚叛徒与人民民兵达成了一项协议：护送他安全穿过敌对领地，他就会揭露艾德温·范克里夫及其核心成员的藏身之处。由于深知盗贼网络会毫不留情地灭口任何告密者，这名叛徒要求全程有武装保护。"},{t="通往月溪镇之路",b="前往藏身处的路径从哨兵岭直接向西南延伸，进入完全被兄弟会占领的月溪镇。叛徒引导他的保护者径直经过废弃的城镇广场和喷泉，引来了巡逻在废墟中的每一名强盗、掠夺者和劫匪的愤怒。这名变节者带领众人直接抵达了位于月溪镇下方庞大的死亡矿井入口，证实了民兵最担心的事：范克里夫在西部荒野的眼皮底下加固了一个地下据点。"}},faq={{q="谁是迪菲亚叛徒？",a="他曾是迪菲亚兄弟会的一员，后转投格里安·斯托曼和人民民兵充当线人。由于害怕死在昔日同伙手中，他以出卖艾德温·范克里夫的地下堡垒所在地为筹码，换取了前往安全地带的护送。",al={"谁是叛徒","迪菲亚叛徒身份","迪菲亚告密者"}},{q="叛徒要把你带到哪里去？",a="他带领你从哨兵岭沿路走进月溪镇，径直穿过废弃的城镇广场，经过喷泉，最终抵达城镇下方死亡矿井隧道的入口。",al={"迪菲亚藏身处在哪里","叛徒行进路线","他去哪里"}},{q="为什么格里安·斯托曼需要这个情报？",a="尽管人民民兵已经在整个西部荒野与劫匪交战，但他们并不清楚艾德温·范克里夫是在哪里指挥行动的。发现他地下巢穴的入口让民兵拥有了一个打击叛乱核心的明确目标。",al={"为什么要护送叛徒","斯托曼的目的","为什么要寻找藏身处"}},{q="为什么月溪镇到处都是迪菲亚？",a="月溪镇曾经是一个繁荣的农业中心，但当暴风城王国陷入颓势、强盗涌入后，该镇就被居民遗弃了。迪菲亚兄弟会占领了这些空置的建筑，将其作为守护死亡矿井入口的地面防线。",al={"为什么月溪镇有迪菲亚","月溪镇被占领","谁拥有月溪镇"}},{q="发现藏身处之后会发生什么？",a="当叛徒揭示了死亡矿井的入口后，你会回到哨兵岭向格里安·斯托曼报告。掌握了范克里夫位置的确凿证据后，民兵准备对地下巢穴发动直接突袭。",al={"what comes next","护送迪菲亚之后","任务进度"}},{q="为什么兄弟会想要叛徒死？",a="迪菲亚依赖隐秘行动，在隐蔽的隧道中运作，并策划着针对暴风城各领地的行动。一名变节者揭露了他们中心行动的门户，这可能会彻底瓦解他们的整个阴谋。",al={"为什么要杀叛徒","迪菲亚攻击叛徒"}}},fp="22,242,20.448.0,26.404.1,26.261.0,32.155.0,49.224.0,38.270.0,44.197.1,47.210.0"}
P.entries["quest:156"] = {n="收集腐败之花",s="夜色镇的旅店老板斯密茨需要一些腐败之花来调配他那臭名昭著的“僵尸药水”。这种令人毛骨悚然的植物直接从潜伏在暮色森林不安宁墓地中的骸骨恐怖和恶魔的腐烂头骨中生长出来。",h="夜色镇的旅店老板斯密茨需要一些腐败之花来调配他那臭名昭著的“僵尸药水”。这种令人毛骨悚然的植物直接从潜伏在暮色森林不安宁墓地中的骸骨恐怖和恶魔的腐烂头骨中生长出来。",kw={"夜色镇","守夜人","乌鸦岭墓地","腐败之花","骸骨恶魔","骸骨恐怖","旅店老板斯密茨","静谧花园墓场","僵尸药水"},ang={["faction:Alliance"]="在暮色森林的墓地猎杀亡灵，为疲惫不堪的夜色镇守夜人提供了极大的缓解，他们每天都在为防止城镇沦陷而奋战。",["profession:Herbalism"]="与生长在肥沃土壤和阳光下的普通草药不同，腐败之花是完全扎根于死灵腐朽和受操纵骸骨中的黑暗植物异常体。"},sec={{t="一种怪异的配料",b="大多数旅店老板都以陈年麦芽酒和上等葡萄酒为傲，但绯红渡鸦旅店的旅店老板斯密茨偶尔会酿造一些更让人不安的饮品。他那“僵尸药水”的配方需要腐败之花——这是一种肮脏的死灵植物，会在受操纵的骷髅空洞的头骨中扎根。斯密茨本人很明智，从不靠近亡灵，而是将这令人毛骨悚然的收割工作留给路过的雇佣兵。"},{t="墓地害虫防治",b="采集这些花朵需要消灭在静谧花园墓场或乌鸦岭墓地那广袤的杂草丛生的墓区中游荡的骸骨恐怖和恶魔。暮色森林的当地民兵“守夜人”为了抵御森林中蔓延的恐怖生物，兵力一直捉襟见肘。斯密茨向那些闯入墓地的冒险者保证，他们清理不安宁的亡灵的功绩会被如实上报给指挥官阿尔泰娅·埃伯洛克。"}},faq={{q="什么是腐败之花？",a="腐败之花是一种肮脏的植物，生长在充斥着黑暗魔法和腐朽的环境中。在暮色森林，它们直接生长在受操纵的骸骨恐怖和恶魔的头颅腔内。",al={"腐败之花","什么是腐败之花","腐败之花从哪里来"}},{q="为什么旅店老板斯密茨需要腐败之花？",a="斯密茨将这些花朵作为酿造“僵尸药水”的关键成分，这是一种该地区某些顾客要求的强力饮料。",al={"斯密茨为什么需要花朵","僵尸药水配料","斯密茨的饮料"}},{q="哪里可以找到长有这些花朵的骷髅？",a="骸骨恐怖和骸骨恶魔聚集在暮色森林各处的墓地中，特别是靠近夜色镇的静谧花园墓场，以及西边广阔的乌鸦岭墓地。",al={"哪里有骸骨恐怖","腐败之花位置","静谧花园的骷髅"}},{q="这项任务有助于保卫夜色镇吗？",a="是的。夜色镇依靠守夜人来应对持续不断的亡灵袭击以求生存。斯密茨指出，为了获取花朵而猎杀骷髅，通过减少威胁城镇的怪物数量，从而在协助指挥官阿尔泰娅·埃伯洛克。",al={"守夜人的帮助","阿尔泰娅·埃伯洛克清理骷髅"}},{q="交付花朵之后接下来要做什么？",a="一旦斯密茨收到花朵并酿好僵尸药水，他会要求你把成品药剂送给亚伯克隆比，那是一位住在乌鸦岭墓地附近的古怪隐士。",al={"腐败之花之后的下一个任务","药水交付后续"}},{q="僵尸药水是夜色镇供应的普通饮料吗？",a="不是。绯红渡鸦旅店通常供应标准的地区性饮品。僵尸药水是一种怪异的特制酿造品，只有当斯密茨收到需要死灵配料的古怪订单时才会准备。",al={"僵尸药水是否普通","绯红渡鸦的饮品"}}},fx={["1d59b9b9"]={q="哪些骷髅携带腐烂花朵？",a="你要对付的是盘踞在暮色森林墓地的骷髅恐魔和骷髅恶鬼，尤其是静谧花园墓场和乌鸦岭一带。这些亡灵怪物从阴影笼罩的树林中被惊扰的墓穴里爬出，头骨内竟藏着奇异的坏死腐烂花朵。",al={"暮色森林的骷髅恐魔","静谧花园的骷髅恶鬼","哪些骷髅会掉落腐烂花朵"}},["1e6a32cf"]={q="旅店老板斯密茨为什么派你去，而不让夜色镇守夜人行动？",a="斯密茨经营着 Scarlet Raven Tavern，并承认自己从来不敢靠近活骷髅查看。与此同时，夜色镇守夜人为了抵御四面八方的恶魔，已经疲于奔命。让一位能干的冒险者在墓地附近狩猎，就能腾出当地守夜人来守卫城镇外围。",al={"夜色镇守夜人为什么不杀骷髅","斯密茨为什么派我去","旅店老板斯密茨为什么需要你"}}},fp="19,236,20.415.0,22.438.0,22.190.0,45.148.0,56.204.0,45.230.0,46.176.1,54.199.0"}
P.entries["quest:1560"] = {n="图加的任务",s="图加是一只迷路的乌龟，他被妻子托尔塔派出去寻找晚餐，结果在某个地方走错了路。图加请求你带他回到托尔塔身边，她正在热砂港以南等待着。",h="图加是一只迷路的乌龟，他被妻子托尔塔派出去寻找晚餐，结果在某个地方走错了路。图加请求你带他回到托尔塔身边，她正在热砂港以南等待着。",kw={"热砂港","塔纳利斯","灌木谷","图加","托尔塔","乌龟"},sec={{t="迷途的旅者",b="图加在灌木谷附近的一架坠毁的地精飞艇旁徘徊。托尔塔派图加出去寻找晚餐，但他在某个地方走错了路，这只可怜的乌龟现在完全迷失了方向。图加请求你为他带路。"},{t="穿越地区",b="托尔塔正在热砂港以南，也就是塔纳利斯的另一头等待，因此你需要带着他几乎走遍整个地区。"},{t="妻子的欢迎",b="对于图加没能独自找到回家的路，托尔塔一点也不感到惊讶。她让图加赶紧下海去带些食物回来。"}},faq={{q="图加是谁？",a="塔纳利斯的一只迷路乌龟，需要帮助才能找到回家的路去找他的妻子。",al={"图加是谁","图加 乌龟","塔纳利斯的乌龟是谁"}},{q="托尔塔是谁？",a="图加的妻子，正在热砂港以南等待。",al={"托尔塔是谁","托尔塔在哪里","托尔塔位置"}},{q="为什么图加会在沙漠里迷路？",a="托尔塔派图加去取晚餐，结果他走错了路，导致迷路了。",al={"为什么图加会迷路","图加发生了什么事","图加背景故事"}},{q="图加最初在哪里被发现？",a="在塔纳利斯灌木谷旁的一架坠毁的地精飞艇附近。",al={"图加起始位置","图加的任务在哪里开始","找到图加"}}},fp="13,186,15.213.0,15.144.0,16.132.1,13.73.0,13.56.0,32.65.0,32.65.0"}
P.entries["quest:157"] = {n="幽灵的发丝",s="“传送发丝”是暮色森林中的一项联盟差事，玩家需要将一轴“幽灵的发丝”从夜色镇的伊瓦夫人那里送到位于这片闹鬼森林另一头的亚伯克隆比手中。这位住在乌鸦岭墓地附近的古怪隐士声称他需要这根附魔发丝来保护他那摇摇欲坠的小屋，以抵御那些不安的灵魂。然而，伊瓦夫人对这根发丝所发表的阴暗言论暗示，它或许有着更加险恶的用途。",h="“传送发丝”是暮色森林中的一项联盟差事，玩家需要将一轴“幽灵的发丝”从夜色镇的伊瓦夫人那里送到位于这片闹鬼森林另一头的亚伯克隆比手中。这位住在乌鸦岭墓地附近的古怪隐士声称他需要这根附魔发丝来保护他那摇摇欲坠的小屋，以抵御...",kw={"亚伯克隆比","夜色镇","传送发丝","暮色森林","幽灵的发丝","伊瓦夫人","乌鸦岭","乌鸦岭墓地","僵尸药剂"},ang={["class:Priest"]="守卫家园以对抗不安的亡者，通常需要圣光的圣礼；而依靠死者遗留的织物，这说明亚伯克隆比走的显然是一条更加黑暗的道路。",["faction:Alliance"]="夜色镇脆弱的安全取决于警惕，将援助送往怪物横行的西部森林给一位隐居的怪人，这让守夜人的防线倍感压力。",["profession:Tailoring"]="将幽灵毛发纺成可用的线轴绝非普通的纺织；它融合了缝纫术与邪门的亡灵法术，造就了能够缝合物理领域之外物质的材料。"},sec={{t="黑暗中的穿越",b="当伊瓦夫人纺好从盲眼玛丽的鬼魂身上收集来的幽灵毛发后，她会将“幽灵的发丝”交给任何愿意将其带往西方的旅人。这趟旅程需要穿过阴森的暮色森林，在躲避潜伏的蜘蛛和游荡的亡灵后，抵达位于广袤墓地北侧、亚伯克隆比那间破败的小屋。"},{t="生与死的线索",b="亚伯克隆比坚持说他需要这根编织出的幽灵丝线来挂在窗户和门框上，以阻挡乌鸦岭那些哀嚎的亡者。然而，伊瓦夫人却无意中透露，幽灵发丝有着千种用途：不仅可以束缚邪恶的灵魂，还能将生命的表象缝合进死物和无生命的物质之中。这位隐士怀着巨大的喜悦迎接了这轴发丝，迫不及待地想要启动他那隐藏的邪恶计划。"}},faq={{q="什么是幽灵发丝？",a="这是一轴由夜色镇的伊瓦夫人利用从盲眼玛丽的鬼魂身上收集的毛发所纺出的附魔线轴。据伊瓦所说，它具有强大的神秘属性，能够束缚灵魂或将生命缝合进无生命的物体中。",al={"幽灵发丝","什么是发丝","幽灵线"}},{q="谁是亚伯克隆比？",a="亚伯克隆比是一位隐居的老人，住在一间离乌鸦岭墓地以北不远的孤零零的小屋里。他表现得像是一个无害、虚弱的隐士，终日对在他家附近徘徊的亡灵感到恐惧。",al={"隐士","亚伯克隆比是谁","小屋里的那个人"}},{q="为什么亚伯克隆比声称他需要这根发丝？",a="亚伯克隆比告诉访客，他打算把幽灵发丝串在窗户和门框上。他声称其灵魂属性将作为一道防护，阻挡那些在暮色森林中游荡的食尸鬼和灵魂进入。",al={"为什么要发丝","亚伯克隆比的借口","驱邪"}},{q="亚伯克隆比在哪里？",a="他住在一间孤立的木屋里，坐落在乌鸦岭墓地主场地以北，紧邻穿过暮色森林的西行之路。",al={"亚伯克隆比的位置","小屋在哪里","隐士小屋"}},{q="把发丝交给亚伯克隆比后会发生什么？",a="一旦亚伯克隆比收到发丝，他会奖励信使，并立即开始抱怨其他紧迫的需求，打发旅行者去跑腿寻找其他奇怪的炼金原料，例如僵尸药剂。",al={"后续任务","接下来发生什么","传送发丝之后"}},{q="伊瓦夫人知道亚伯克隆比在搞什么名堂吗？",a="伊瓦并没有直接指责亚伯克隆比有不轨行为，但她那意味深长的临别赠言提到，幽灵发丝可以用来将生命缝合进无生命的物体中。她似乎非常清楚这根发丝的亡灵法术潜力，即便她毫无怨言地完成了这份订单。",al={"伊瓦知道吗","伊瓦夫人是同谋吗","伊瓦的警告"}}},fx={["011e87a7"]={q="伊瓦夫人为什么要你把幽灵的发丝送给亚伯克隆比？",a="伊瓦夫人正在履行交易中的承诺。亚伯克隆比曾请求幽灵的发丝，用来抵御他隐居地附近躁动不安的亡灵；伊瓦夫人则答应，只要你带来盲眼玛丽的幽灵发丝，她就会将其纺成线。她认为亚伯克隆比不过是个虚弱古怪的隐士，想在乌鸦岭附近的恐怖威胁中求生，便托付你将纺好的线轴安全送到他的门口。",al={"伊瓦夫人为什么帮助亚伯克隆比","伊瓦夫人的动机","为什么要送幽灵的发丝"}}},fp="18,414,22.355.0,25.386.1,26.228.0,19.212.0,47.217.0,29.147.0,52.207.0,47.261.0"}
P.entries["quest:1578"] = {n="前线的补给",s="支援前线是铁炉堡的托姆斯·深炉委托给铁炉堡矮人铁匠的一项早期任务。该任务要求铁匠们锻造武器和护甲，以支援驻扎在洛克莫丹的登山者，抵御不断侵袭的穴居人。",h="支援前线是铁炉堡的托姆斯·深炉委托给铁炉堡矮人铁匠的一项早期任务。该任务要求铁匠们锻造武器和护甲，以支援驻扎在洛克莫丹的登山者，抵御不断侵袭的穴居人。",kw={"锻造","铜斧","铜链腰带","铁炉堡","洛克莫丹","支援前线","塞尔萨玛","索瓦尔德·深炉","托姆斯·深炉","穴居人"},ang={["faction:Alliance"]="卡兹莫丹的边境安全保卫着连接铁炉堡与暴风城以及联盟南部战线的山路。",["profession:Blacksmithing"]="这项任务是有抱负的金属工匠的早期试炼，测试他们生产可用于实战的可靠且统一的铜制武器和护甲的能力。",["race:Dwarf"]="洛克莫丹的防御直接依赖于矮人的工艺，证明了操作风箱的工匠对于王国生存的重要性，丝毫不亚于手持步枪的登山者。"},sec={{t="武装登山者",b="在铁炉堡的Great Forge中，铁匠大师托姆斯·深炉密切关注着卡兹莫丹王国的边境。保卫洛克莫丹山谷的登山者们正承受着来自那些从地底遗迹和洞穴中涌出的穴居人的突袭。为了维持他们的防线供给，需要不断更换新鲜的刀刃、腰带和装备，这促使当地的工匠们纷纷伸出援手。"},{t="深炉氏族的纽带",b="为了在不抽调城市熔炉中资深工匠的前提下维持防御物资供应，托姆斯派遣学徒前往东方的洛克莫丹。在那里，他的同事索瓦尔德·深炉在南部哨塔维护着一处战地军械库。通过将坚固的铜斧和铜链腰带直接交付给索瓦尔德，铁匠们可以证明自己的可靠性并获得更高级的锻造技术。"}},faq={{q="谁提供了这个任务？需要什么材料？",a="位于铁炉堡Great Forge的铁匠托姆斯·深炉会向锻造等级至少达到30级的学徒提供这项任务。你需要制作六把铜斧和六条铜链腰带。",al={"谁发布了支援前线任务","任务发起人","锻造任务要求"}},{q="索瓦尔德·深炉在哪里？",a="索瓦尔德·深炉驻扎在洛克莫丹的南部哨塔内。要找到他，请沿着塞尔萨玛经过的大路向南前往荒芜之地边界，塔楼就矗立在山口旁。",al={"索瓦尔德在哪里","索瓦尔德位置","洛克莫丹南部哨塔"}},{q="为什么登山者需要这么多铜制补给品？",a="驻扎在洛克莫丹的登山者们正与凶残的穴居人进行不断的交火。残酷的战斗导致他们的装备迅速崩裂、变钝和损坏，因此需要源源不断的基本武器和锁甲补给。",al={"为什么需要斧头","铜有什么用"}},{q="索瓦尔德和托姆斯是什么关系？",a="托姆斯称索瓦尔德为同事，且两人共享“深炉”氏族之名，他们是联系紧密的工匠，共同努力将铁炉堡的工业能力与前线防御连接起来。",al={"索瓦尔德和托姆斯有亲属关系吗","托姆斯的同事"}},{q="索瓦尔德提供什么样的奖励？",a="为了感谢你缓解了南部哨塔的补给压力，索瓦尔德会分享他的锻造知识，并提供新的护甲图纸。",al={"任务奖励","索瓦尔德教授什么"}},{q="为什么穴居人现在成了洛克莫丹的一个大问题？",a="最近的矮人挖掘工作在整个卡兹莫丹发现了地下的金库和空洞，意外地唤醒并挖掘出大群具有攻击性的穴居人，它们现在威胁着周围的定居点和哨塔。",al={"为什么穴居人在攻击","洛克莫丹的穴居人问题"}}},fx={f96d051f={q="托姆斯·深炉为何请冒险者帮忙为前线运送补给？",a="托瓦尔德忙着处理前线的维修事务，已经应接不暇，而托姆斯也不能丢下铁炉堡自己的铁砧不管。作为一名崭露头角的铁匠，锻造装备并穿过隧道将其送往东边，既能考验你的手艺，也能直接减轻山地卫兵的负担。",al={"为何让我为前线运送补给","托姆斯为何需要我","为何派冒险者去找托瓦尔德"}},["0062256f"]={q="托姆斯·深炉为什么还需要更多铜斧？",a="在洛克莫丹作战的铁炉堡山地步兵不断与穴居人交战。持续作战会让武器很快损坏，索瓦尔德·深炉急需新的武器，以确保防守者能够守住前线。",al={"铜斧有什么用","供应前线任务中的铜斧用途","为什么要铜斧"}},c19cb0c2={q="索瓦尔德为什么需要铜质链甲腰带？",a="穴居人的攻击凶狠而无休无止，让山地步兵的护具损耗得比他们修复的速度还快。索瓦尔德依靠源源不断运来的耐用护甲部件，例如铜质链甲腰带，来确保矮人哨兵在南部山口得到妥善保护。",al={"铜质链甲腰带有什么用","铜质链甲腰带用途","为什么要铜质链甲腰带"}}},fp="19,259,23.405.0,21.389.0,43.205.0,36.215.0,53.221.0,36.194.0,40.146.0,57.219.0"}
P.entries["quest:1579"] = {n="小齿轮",s="维兹班恩·曲针是一位在奥伯丁宿醉的侏儒发明家，他需要帮助找回一箱他掉进海里的重要零件。为了躲避铁炉堡的喧嚣，他来到了卡利姆多宁静的海岸，却在旅途中不慎将极其重要的小齿轮掉进了海里。任何拥有鱼竿和耐心的人，都能沿着海岸线打捞出这些丢失的组件。",h="维兹班恩·曲针是一位在奥伯丁宿醉的侏儒发明家，他需要帮助找回一箱他掉进海里的重要零件。为了躲避铁炉堡的喧嚣，他来到了卡利姆多宁静的海岸，却在旅途中不慎将极其重要的小齿轮掉进了海里。任何拥有鱼竿和耐心的人，都能沿着海岸线打...",kw={"奥伯丁","黑海岸","电动推进器","钓鱼","小齿轮","铁炉堡","钉齿","维兹班恩·曲针"},ang={["profession:Engineering"]="任何工程师都知道，缺少一个微小且非标准的机械零件来完成精密设备的校准，是一件多么令人痛苦的事情。",["race:Gnome"]="维兹班恩体现了侏儒工匠那不安分的古怪性格，尽管即使是其他侏儒，看到他将高精度组件与酗酒这种鲁莽行为结合在一起时，恐怕也会感到尴尬。",["race:NightElf"]="宁静而神圣的黑海岸森林，对于一个粗鲁且宿醉的侏儒发明家来说，是一个奇怪的去处，这也在考验着奥伯丁暗夜精灵哨兵们传说中的耐心。"},sec={{t="宁静避风港中的混乱思绪",b="为了远离铁炉堡Great Forge震耳欲聋的喧嚣，古怪的侏儒发明家维兹班恩·曲针漂洋过海，跨越无尽之海来到了黑海岸。不幸的是，维兹班恩在航行途中贪杯了。在酒精的麻痹下，他靠在栏杆上时，竟将整整一箱名为“小齿轮”的专用金属组件掉进了奥伯丁外海的海水中。"},{t="调试钉齿",b="对于普通路人来说，小齿轮看起来只是一些不起眼的金属碎片，但对维兹班恩来说，它们是必不可少的精密工具。他声称，如果没有这些零件，就完全无法正确校准他的钉齿，也无法进行任何精细的修理工作。这位侏儒自己不愿跳进寒冷的海水中，便只好请求当地的垂钓者沿着黑海岸的浪潮抛竿，把这些散落的零件钓上来。"}},faq={{q="什么是小齿轮？",a="小齿轮是侏儒的一种小型机械紧固件和组件。据维兹班恩·曲针所说，它们是专门用于在他的修理项目中调试钉齿的重要专用工具。",al={"什么是小齿轮","小齿轮的用途","小齿轮物品"}},{q="小齿轮是怎么掉进海里的？",a="维兹班恩·曲针在从东部王国前往卡利姆多的航行途中喝得太多了。在船上醉酒时，他意外地将自己的补给箱掉进了黑海岸附近的海岸线里。",al={"他是怎么弄丢的","为什么它们在水里","为什么要钓小齿轮"}},{q="为什么维兹班恩·曲针在奥伯丁而不是铁炉堡？",a="维兹班恩选择奥伯丁正是因为它宁静平和。他无法忍受铁炉堡不断传来的撞击声、铁砧敲击声和吵闹的车间，尤其是在他因酗酒而头痛欲裂的时候。",al={"维兹班恩为什么在奥伯丁","维兹班恩为什么要离开铁炉堡"}},{q="在哪里可以钓到丢失的小齿轮？",a="它们可以在奥伯丁附近黑海岸海岸线的开放盐水中钓到。垂钓者可以通过在沿海水域正常垂钓获得，而不需要寻找特定的鱼群。",al={"在哪里钓小齿轮","小齿轮位置"}},{q="找回小齿轮后会发生什么？",a="一旦维兹班恩找回了用来调试钉齿的小齿轮，他就会透露自己在黑海岸的河流和湖泊中还丢了另一套关键设备：他的电动推进器，也必须通过钓鱼找回来。",al={"小齿轮之后做什么","小齿轮后续任务"}},{q="为什么维兹班恩需要冒险者帮忙，而不是自己去取回？",a="由于剧烈的宿醉和缺乏海上垂钓装备，维兹班恩宁愿舒舒服服地待在奥伯丁码头上，把这种枯燥的打捞工作留给任何带着鱼竿路过的人。",al={"为什么维兹班恩不能自己去拿","为什么维兹班恩不钓鱼"}}},fx={bd1e627b={q="维兹班恩·曲针为何想找回那些灯芯千斤顶？",a="维兹班恩不远万里从铁炉堡来到黑海岸，只为寻觅一处清静之地研究他的发明。不幸的是，他在航行途中醉酒闯祸，笨手笨脚地把重要补给弄沉到了海底。没有那些灯芯千斤顶，他那些妙趣横生的发明研究就只能立刻停摆；没有它们，他甚至没法调校他的短钉。",al={"维兹班恩为何需要灯芯千斤顶","维兹班恩·曲针的动机","为何帮助维兹班恩·曲针"}}},fp="12,380,33.436.0,23.442.0,22.203.0,43.225.0,61.243.0,45.182.0,47.223.1,69.189.0"}
P.entries["quest:158"] = {n="僵尸",s="“僵尸果汁”是应亚伯克隆比之托完成的一项差事，这位古怪的隐士居住在闹鬼的暮色森林荒野中。他自称难以忍受午夜时分的严寒，因此派遣旅行者前往夜色镇的旅店，去取一种不同寻常的烈性药剂。",h="“僵尸果汁”是应亚伯克隆比之托完成的一项差事，这位古怪的隐士居住在闹鬼的暮色森林荒野中。他自称难以忍受午夜时分的严寒，因此派遣旅行者前往夜色镇的旅店，去取一种不同寻常的烈性药剂。",kw={"亚伯克隆比","夜色镇","暮色森林","烈酒","scarlet raven tavern","旅店老板斯密茨","僵尸果汁"},ang={["faction:Alliance"]="为了支援苦战中的夜色镇哨站，联盟的冒险者常常会发现自己充当了快递员，为沿着暮色森林危险道路居住的古怪隐士们跑腿。"},sec={{t="寒冷的请求",b="隐士亚伯克隆比独自居住在阴森树林的恐怖之中，他经常派遣富有同情心的旅行者去完成一些奇怪的差事。他声称蔓延的暮色夺走了他的温暖与活力，因此请求冒险者前往东边的夜色镇。他的目标是Scarlet Raven Tavern的旅店老板斯密茨，他想从那里得到一瓶名为“僵尸果汁”的烈性且名字不祥的酿造品，以此让他的血管重新沸腾起来。"},{t="在Scarlet Raven",b="夜色镇的旅店里总是坐满了疲惫的卫兵和惊恐的镇民，但即使是对旅店老板斯密茨来说，索要“僵尸果汁”的要求也很罕见。这种酒以烈性极强而闻名。虽然斯密茨认得这种酒，但考虑到暮色森林本身就深受The Restless Dead的困扰，亚伯克隆比对这种阴森药剂的渴望还是让旁人暗自侧目。"}},faq={{q="什么是“僵尸果汁”？",a="这是一种烈性极强、名字阴森的酒，由夜色镇Scarlet Raven Tavern的旅店老板斯密茨出售。普通的顾客很少会点这种酒。",al={"僵尸果汁饮品","什么是这种酒","僵尸果汁背景故事"}},{q="是谁派你去取“僵尸果汁”的？",a="隐士亚伯克隆比，他独自住在暮色森林西部的一间小屋里，他请求旅行者去取来这种酒，好让自己冰冷的骨头暖和起来。",al={"谁发布了僵尸果汁任务","亚伯克隆比任务饮品","隐士饮品请求"}},{q="你在哪里完成这个任务？",a="你需要与位于暮色森林东部、夜色镇中心旅店Scarlet Raven Tavern里的旅店老板斯密茨交谈。",al={"斯密茨在哪里","提交僵尸果汁","斯密茨位置"}},{q="亚伯克隆比为什么要这个？",a="亚伯克隆比声称暮色森林阴暗潮湿的夜晚让他瑟瑟发抖，他需要这种烈酒来温暖自己的血液。",al={"为什么亚伯克隆比需要果汁","亚伯克隆比寒冷","他为什么要喝僵尸果汁"}},{q="旅店老板斯密茨对这个订单感到惊讶吗？",a="是的。斯密茨指出“僵尸果汁”是一种烈性极强的饮品，并提到他平时的常客通常不会要求买这种酒。",al={"斯密茨的反应","斯密茨有僵尸果汁吗","斯密茨对话"}},{q="这个任务需要与任何怪物战斗吗？",a="不需要。这项差事本身只需要沿着从亚伯克隆比隐蔽的小屋到夜色镇的道路行进，并与旅店老板斯密茨交谈即可，不过暮色森林的道路上总是充斥着游荡的野兽和亡灵。",al={"僵尸果汁战斗","僵尸果汁危险吗","僵尸果汁怪物"}}},fx={aa8c42e6={q="亚伯克隆比为何需要你去弄到僵尸汁？",a="亚伯克隆比是个体弱多病、独自隐居的隐士，住在乌鸦岭附近阴森而闹鬼的树林深处。对一位年迈的隐士而言，穿越暮色森林里满是怪物的道路，一路前往夜色镇的 Scarlet Raven Tavern，实在太过危险，尤其是像你这样身手不凡的冒险者愿意替他跑腿。",al={"亚伯克隆比为何不能自己弄到","为何让我去拿僵尸汁","为何派我去拿僵尸汁"}}},fp="12,261,16.437.0,20.360.0,21.164.0,36.130.0,31.115.0,29.131.0,44.157.0,46.226.0"}
P.entries["quest:1580"] = {n="导电器",s="“电驱推进器”是奥伯丁的一位古怪侏儒技师维兹班恩·曲针委托的一项轻松跑腿任务。在一次制作爆炸鸭子诱饵的冒险失败后，维兹班恩把装有原型组件的袋子弄丢在了黑海岸的淡水溪流里，他请求过往的垂钓者帮忙把它们钓回来。",h="“电驱推进器”是奥伯丁的一位古怪侏儒技师维兹班恩·曲针委托的一项轻松跑腿任务。在一次制作爆炸鸭子诱饵的冒险失败后，维兹班恩把装有原型组件的袋子弄丢在了黑海岸的淡水溪流里，他请求过往的垂钓者帮忙把它们钓回来。",kw={"奥伯丁","壁泉河","黑海岸","鸭子诱饵","电驱推进器","钓鱼","急弯河","维兹班恩·曲针"},ang={["profession:Engineering"]="电驱推进器是侏儒微型动力装置的奇特例子，旨在驱动机械诱饵，然后再猛烈燃烧。",["race:Gnome"]="维兹班恩制造爆炸鸭子诱饵的混乱野心对于任何侏儒来说都是司空见惯的景象，即使把昂贵的零件丢在有精灵守卫的河里稍微有点尴尬。",["race:NightElf"]="当地的暗夜精灵对维兹班恩那些吵闹、冒烟的发明和弄脏河流的鲁莽行为持默许的反对态度，她们更希望黑海岸的溪流保持自然状态。"},sec={{t="微醺的发明",b="维兹班恩·曲针，一位驻扎在安静的暗夜精灵港口奥伯丁的侏儒技师，曾在一个晚上徘徊在黑海岸内陆寻找测试场地。他最近痴迷于一个项目：一种自带动力、会爆炸的鸭子诱饵。不幸的是，喝得有点多导致他不合时宜地断片了。几个小时后，维兹班恩在镇上醒来，头发被烧焦了，背包空空如也，他意外地把他珍贵的电驱推进器袋子掉进了一条沿海河流里。"},{t="疏浚水域",b="维兹班恩并没有亲自涉险去取回他散落的机械部件，而是号召当地渔民去黑海岸的淡水溪流中打捞。垂钓者在急弯河和壁泉河等水道上抛竿时，经常会连同当地的鱼一起钩到这些浮力良好的金属小玩意。找回这些组件后，这位健忘的侏儒又能继续他那危险且怪异的水禽实验了。"}},faq={{q="我在哪里可以找到电驱推进器？",a="它们必须从黑海岸的淡水河流和湖泊（如壁泉河或急弯河）中钓出来。它们不会出现在沿海的海洋水域中。",al={"电驱推进器在哪里","如何获得电驱推进器","电驱推进器位置"}},{q="维兹班恩·曲针是谁？",a="维兹班恩是居住在奥伯丁的一位古怪的侏儒工程师。他以奇特且具有爆炸性的发明而闻名，他依赖冒险的旅者为他的实验收集丢失的组件和奇怪的物品。",al={"谁给予电驱推进器任务","维兹班恩·曲针"}},{q="维兹班恩试图制造什么？",a="他正在研究一种自带动力、会爆炸的鸭子诱饵。由于他喝得有点多，不小心引爆了一个早期原型机，烧焦了自己的头发，并把装有零件的袋子掉进了水里，导致他的测试乱了套。",al={"爆炸鸭子诱饵","维兹班恩的项目"}},{q="可以在鱼群中找到电驱推进器吗？",a="不能，电驱推进器是直接从淡水中钓上来的。直接将鱼钩抛入特殊的鱼群（例如小型黑口鱼节点）中不会获得这些机械部件。",al={"电驱推进器鱼群","我能钓鱼群吗"}},{q="这个任务的前置是什么？",a="你必须先完成“加弗·杰克斯”，这是维兹班恩分配的一项更早的钓鱼任务，旨在测试你在当地水域的垂钓运气。",al={"电驱推进器前置","电驱推进器先决条件"}},{q="怪物会掉落电驱推进器吗？",a="不会。它们不能从敌人身上拾取，也不能在地面的容器中找到；必须使用鱼竿从河流中钓取。",al={"怪物掉落电驱推进器吗","谁掉落电驱推进器"}}},fx={["42aa198c"]={q="维兹班恩·曲针为何想让你找回电动螺旋桨？",a="维兹班恩醉酒闯祸，在黑海岸的水道边测试发明时，弄丢了整袋零件。他醒来时已经回到奥伯丁，头发被烧焦，背包也空空如也。缺少这些零件，他正在进行的自推进爆炸鸭子诱饵工程研究就完全停滞了。",al={"维兹班恩为何需要电动螺旋桨","维兹班恩的动机","为何找电动螺旋桨"}},c9029636={q="电动螺旋桨有什么用途？",a="电动螺旋桨是维兹班恩设计的专用机械推进部件。具体来说，它们是他那款自推进爆炸鸭子诱饵原型的驱动装置，能让机械诱饵在水面上转向并行进，直到其中的不稳定装药爆炸。",al={"什么是电动螺旋桨","电动螺旋桨的用途","电动螺旋桨的作用"}},d23bdc75={q="维兹班恩为何让你去钓电动螺旋桨，而不是自己动手？",a="此前你为维兹班恩捞起灯芯千斤顶时，他已经见识过你不可思议的好运和钓鱼本领。醉酒闯祸后，他头昏脑涨、头发烧焦地回到了奥伯丁，因此宁愿依靠一位有过成功经历的钓手，也不愿独自在黑海岸的荒野中四处搜寻。",al={"为何让我帮维兹班恩","维兹班恩为何不自己钓上来"}}},fp="14,289,17.479.0,19.429.0,35.178.0,27.202.0,33.229.0,44.184.0,29.124.0,39.130.0"}
P.entries["quest:1581"] = {n="刃叶的药剂",s="在多兰纳尔的枝叶间，塞拉尔·刃叶正在寻找一位炼金师来补充她家族日益兴旺的贸易库存。她的丈夫整日埋头于酿造药剂的坩埚旁，塞拉尔希望通过一批新鲜的药剂来减轻他的负担，并以此作为酬劳赠予贡献者一捆稀有草药。",h="在多兰纳尔的枝叶间，塞拉尔·刃叶正在寻找一位炼金师来补充她家族日益兴旺的贸易库存。她的丈夫整日埋头于酿造药剂的坩埚旁，塞拉尔希望通过一批新鲜的药剂来减轻他的负担，并以此作为酬劳赠予贡献者一捆稀有草药。",kw={"炼金术","多兰纳尔","地根草","狮王之力药剂","初级防御药剂","给刃叶家族的药剂","银叶草","塞拉尔·刃叶","泰达希尔"},ang={["faction:Alliance"]="确保多兰纳尔拥有充足的恢复和防御药水储备，能让守卫和旅行的盟友们为应对森林中的威胁做好准备。",["profession:Herbalism"]="泰达希尔肥沃的土壤盛产银叶草和地根草，这使得采集满足塞拉尔商店订单所需的原材料变得非常简单。",["race:NightElf"]="支持像刃叶家族这样的本地商人有助于维持多兰纳尔这个新兴聚居地在泰达希尔树冠下的发展。"},sec={{t="繁荣的重担",b="多兰纳尔聚居地是穿行于泰达希尔树冠间的旅行者、哨兵和德鲁伊们的重要十字路口。随着往来行人的增多，塞拉尔·刃叶和她丈夫经营的草药与炼金生意也随之蒸蒸日上。然而，高需求也带来了代价。她的丈夫几乎将所有时间都花在药瓶和坩埚上以维持货架供应，导致夫妻俩几乎没有相处的时间。"},{t="商人的交换",b="为了不让她的伴侣在繁重的订单中耗尽心力，塞拉尔向过往的草药师和酿造者求助。通过委托他们预先调配药水——特别是狮王之力药剂和初级防御药剂——她补充了商店的库存，并以新鲜采摘的稀有草药作为回报。对于一位在大树下磨炼技艺的初级炼金师来说，这是一个将常见的森林植物转化为珍贵的地区特产的绝佳机会。"}},faq={{q="为什么塞拉尔·刃叶需要这些药水？",a="他们在多兰纳尔经营的家庭草药和炼金商店生意非常繁忙。她的丈夫把所有时间都花在酿造药水以应对需求，让他们没有私人的共处时光。外包这些工作能让他得到急需的休息。",al={"为什么需要药剂","塞拉尔·刃叶的动机","刃叶商店的问题"}},{q="任务需要哪些药水？",a="塞拉尔需要六瓶狮王之力药剂和两瓶初级防御药剂。这两者都是泰达希尔的冒险者和当地哨兵经常购买的常备药水。",al={"哪些药剂","我需要什么来酿造","需要的药水"}},{q="酿造这些所需的药剂需要什么草药？",a="酿造所需的药剂需要银叶草和地根草，这两种草药在泰达希尔的森林地面上随处可见，此外还需要标准的清澈的瓶子。",al={"需要的原料","药剂材料","我该采摘什么草药"}},{q="谁可以承担这个请求？",a="只有在炼金术方面具备基本能力的从业者才会被提供这项任务。塞拉尔为她的商店寻求的是可靠、调配得当的药剂，而不是业余的作品。",al={"等级要求","专业要求","任何人都可以做这个任务吗"}},{q="塞拉尔用什么来交换这些药剂？",a="塞拉尔会用一捆新鲜采集、在泰达希尔林间小径上难以轻易找到的稀有草药作为回报，奖励那些提供帮助的炼金师。",al={"奖励背景","塞拉尔提供什么","刃叶贸易奖励"}},{q="塞拉尔·刃叶在哪里？",a="她可以在多兰纳尔北部建筑外找到，靠近穿过这座森林村庄的中央道路。",al={"塞拉尔在哪里","刃叶的位置","我在哪里提交任务"}}},fx={c3ad307f={q="狮王之力药剂有什么用？",a="狮王之力药剂是前线战士和炼金师常备的饮剂，饮用后能暂时增强体魄。塞拉尔·刃叶在多兰纳尔备有这种药剂，以满足猎人、哨兵和旅行者的持续需求；他们都在为面对泰达希尔危险的荒野做准备。",al={"狮王之力药剂的用途","为何要狮王之力药剂","狮王之力药剂的作用"}},["34301f2f"]={q="次级防御药剂有什么用？",a="次级防御药剂是一种炼金制品，能使皮肤变得坚韧，并强化天生的护甲，以抵御物理攻击。塞拉尔·刃叶在店里备有这种药剂，供巡守巨树枝桠、需要可靠基础防护的守卫和冒险者购买。",al={"次级防御药剂的用途","为何要次级防御药剂","次级防御药剂的作用"}}},fp="26,276,22.435.0,19.467.0,44.238.0,39.175.0,51.165.0,31.185.0,50.161.0,33.119.0"}
P.entries["quest:1582"] = {n="月光外衣",s="月光背心是达纳苏斯的暗夜精灵制皮训练师洛瑟里亚斯提供的一项贸易训练任务。由于前往卡利姆多荒野的年轻冒险者需求不断，她忙得不可开交，因此她愿意用一种特殊的暗夜精灵束腰外衣图纸作为交换，来换取大量的雕花皮制装备。",h="月光背心是达纳苏斯的暗夜精灵制皮训练师洛瑟里亚斯提供的一项贸易训练任务。由于前往卡利姆多荒野的年轻冒险者需求不断，她忙得不可开交，因此她愿意用一种特殊的暗夜精灵束腰外衣图纸作为交换，来换取大量的雕花皮制装备。",kw={"制造","达纳苏斯","雕花皮","卡多雷","制皮","洛瑟里亚斯","月光背心","泰达希尔"},ang={["faction:Alliance"]="为达纳苏斯的新兵配备装备，有助于在日益增长的野外和敌对威胁中维持联盟在卡利姆多北部的脆弱控制。",["race:NightElf"]="月光背心代表了泰达希尔工匠典型的优雅工艺，为森林树冠下的斥候和哨兵提供了灵活的防护。"},sec={{t="武装卡多雷",b="在达纳苏斯的庇护枝叶下，商人们正不知疲倦地工作，为日益壮大的哨兵和渴望成为荒野斥候的人们提供装备。随着年轻的暗夜精灵和联盟的流浪者们走出泰达希尔，前往动荡的卡利姆多，人们对可靠护甲的需求十分迫切。像洛瑟里亚斯这样的制皮大师肩负着为这些前线地区供应坚固皮革的重任。"},{t="掌握技艺",b="为了确保她的学徒们既具备耐力又拥有精湛的技术，洛瑟里亚斯要求他们通过多种配套服饰来证明自己的手艺：雕花皮手套、皮靴和披风。完成这些配额能赢得她的信任，从而促使她传授那种独特的暗夜精灵月光背心图纸——这种服装因在柔软的防护和敏捷的机动性之间取得了平衡而备受青睐。"}},faq={{q="洛瑟里亚斯是谁？",a="洛瑟里亚斯是一位常驻达纳苏斯的熟练暗夜精灵制皮训练师。她负责指导联盟工匠的技艺，并为那些证明了自己奉献精神的制皮师提供高级设计图纸。",al={"洛瑟里亚斯 达纳苏斯","谁提供月光背心"}},{q="为什么洛瑟里亚斯需要这么多皮革制品？",a="达纳苏斯挤满了准备踏上旅程的新手冒险者。工匠们正努力应付对野外装备的持续需求，这促使洛瑟里亚斯将标准的雕花皮制服装外包给有能力的学徒制作。",al={"为什么需要这么多皮靴","为什么要制作雕花皮"}},{q="月光背心是什么？",a="月光背心是一种高级的制作类皮甲。一旦你证明了自己能够批量生产高质量的雕花皮制品，洛瑟里亚斯就会将它的图纸作为奖励传授给你。",al={"月光背心图纸","我能得到什么"}},{q="完成这项任务需要什么材料？",a="你必须提供一副雕花皮手套、五双雕花皮靴和五件雕花皮披风。所有物品都必须亲手制作并直接交给洛瑟里亚斯。",al={"我需要什么","月光背心所需物品"}},{q="部落的制皮师可以在这里学习这个图纸吗？",a="不能。洛瑟里亚斯居住在达纳苏斯，只培训联盟的工匠。部落的工匠必须在卡利姆多和东部王国寻找各自的训练师来扩展他们的贸易技能。",al={"部落可以做这个吗","月光背心是联盟专属吗"}},{q="这个任务需要特定的商业技能等级吗？",a="是的，工匠必须达到至少70点的制皮等级，洛瑟里亚斯才会认为他们有足够的技术来承接订单并学习背心图纸。",al={"所需制皮等级","什么时候可以获得月光背心"}}},fx={["304f0e76"]={q="雕花皮手套有什么用？",a="洛瑟里亚斯和达纳苏斯的其他工匠忙得不可开交，正努力为大批涌入荒野的年轻冒险者置办装备。她请你制作一副雕花皮手套，以应付堆积如山的订单；这也能考验你处理精细工艺的本领，之后她才会传授你更高深的技巧。",al={"为何要雕花皮手套","雕花皮手套的用途","洛瑟里亚斯的手套"}},["3d684782"]={q="雕花皮靴有什么用？",a="洛瑟里亚斯需要五双雕花皮靴，为准备在卡利姆多各地展开危险远征的当地冒险者提供装备。批量制作结实可靠的鞋履，既能证明你作为制皮匠的稳定手艺，也能减轻达纳苏斯繁忙工坊的负担。",al={"为何要雕花皮靴","雕花皮靴的用途","洛瑟里亚斯的靴子"}},["83a79481"]={q="雕花皮披风有什么用？",a="这五件雕花皮披风是为那些在泰达希尔及更远之处冒险、迎战风雨的新手准备的。洛瑟里亚斯被各种补给需求压得喘不过气；制作这些耐用的披风，能证明你既有耐力，也具备接受高级制皮训练所需的技术能力。",al={"为何要雕花皮披风","雕花皮披风的用途","洛瑟里亚斯的披风"}}},fp="13,317,22.381.0,19.376.0,17.208.0,46.256.0,26.199.0,50.189.0,49.204.0,53.168.0"}
P.entries["quest:159"] = {n="僵尸酒",s="“果汁快递”是往返于夜色镇和暮色森林西侧边缘的一项跑腿任务。旅店老板斯密茨委托你将一种名为“僵尸果汁”的烈性混合酒送给隐居的隐士亚伯克隆比。虽然表面上是为了给这位瑟瑟发抖的老人取暖，但这种酒离奇的药力着实令人侧目。",h="“果汁快递”是往返于夜色镇和暮色森林西侧边缘的一项跑腿任务。旅店老板斯密茨委托你将一种名为“僵尸果汁”的烈性混合酒送给隐居的隐士亚伯克隆比。虽然表面上是为了给这位瑟瑟发抖的老人取暖，但这种酒离奇的药力着实令人侧目。",kw={"亚伯克隆比","夜色镇","暮色森林","果汁快递","scarlet raven tavern","旅店老板斯密茨","僵尸果汁"},ang={["faction:Alliance"]="夜色镇的居民依赖勇敢的联盟信使来穿越暮色森林危机四伏的道路，但信任林中的每一位隐士可能会导致意想不到的麻烦。",["profession:Cooking"]="旅店老板斯密茨的僵尸果汁配方严重依赖于刺激且非传统的配料，挑战着人们对酒馆饮料的认知极限。"},sec={{t="一种可疑的混合酒",b="夜色镇的旅店老板斯密茨酿造了一种被俗称为“僵尸果汁”的传奇酒水。当订单最终完成时，斯密茨递过瓶子并严厉警告要小心处理，声称这种混合酒烈到足以让死人复活。对于一个奔波在闹鬼森林中跑腿的疲惫冒险者来说，给一个古怪的独居者送这种高浓度的私酿酒感觉就像是例行的慈善工作。"},{t="隐士的口误",b="带着这瓶挥发性的酒向西走，经过嚎叫的狼人和不得安息的亡灵，直达暮色森林边缘的亚伯克隆比的小屋。在收到瓶子后，这位虚弱的隐士声称他需要这些酒仅仅是为了在暮色森林寒冷且充满浓雾的夜晚温暖他疼痛的骨头。然而在拿到酒后，他差点感谢旅行者的“愚蠢”，随后迅速改口称赞他们的“善良”——这短暂的失言暗示着这位隐士脑中所酝酿的阴谋远不止是一杯简单的晚间饮品那么简单。"}},faq={{q="什么是僵尸果汁？",a="僵尸果汁是由夜色镇Scarlet Raven Tavern的旅店老板斯密茨酿造的一种极烈酒水。虽然它被当作烈性酒精饮料，但斯密茨指出，这种酒烈到足以唤醒死者，使其比普通的烈酒更加危险。",al={"僵尸果汁背景故事","什么是斯密茨的果汁","亚伯克隆比的酒"}},{q="谁订购了僵尸果汁？",a="这次快递是由亚伯克隆比委托的，他是一位住在暮色森林西侧边界附近偏僻小屋里的古怪老隐士。",al={"谁想要果汁","果汁快递是给谁的"}},{q="亚伯克隆比为什么要这种酒？",a="亚伯克隆比声称他需要这种酒来在暮色森林寒冷潮湿的夜晚取暖。然而，他在收到瓶子时的口误暗示了他对这种混合酒有着更为邪恶的企图。",al={"亚伯克隆比为什么需要果汁","亚伯克隆比寒冷"}},{q="谁酿造了僵尸果汁？",a="旅店老板斯密茨，也就是夜色镇中心Scarlet Raven Tavern的酒保，在得到必要的刺激性配料后，亲自酿造了这种酒。",al={"谁制作僵尸果汁","斯密茨酒保"}},{q="亚伯克隆比的小屋在哪里？",a="亚伯克隆比的小屋位于暮色森林西部的荒凉之处，就在乌鸦岭墓地北面。",al={"亚伯克隆比位置","亚伯克隆比的小屋在哪里"}},{q="亚伯克隆比在收到果汁后接下来做了什么？",a="一旦他拿到了僵尸果汁，亚伯克隆比便继续利用容易受骗的旅行者，派遣他们进入乌鸦岭墓地收集食尸鬼的肋骨，并声称这能用来制作一个可以驱赶亡灵的恐怖雕像。",al={"果汁快递之后的下一个任务","接下来发生了什么"}}},fx={["9f2016f2"]={q="旅店老板斯密茨为何想让人送去果汁？",a="斯密茨经营着夜色镇的 Scarlet Raven Tavern，并已完成交易中属于自己的部分：酿好亚伯克隆比所要求的烈性饮品。饮料已经装瓶备妥，他只想让约定的订单顺利交付，尽快脱手；途中他还提醒你小心处理这种不稳定的饮品。",al={"斯密茨为何想让人完成这件事","旅店老板斯密茨的动机","为何要送僵尸汁"}},["6bab1f80"]={q="斯密茨为何让冒险者送果汁，而不是自己去？",a="旅店老板斯密茨得留在 Scarlet Raven Tavern 照看酒吧，而在暮色森林阴森的道路上徘徊，对普通酒保来说太过危险。亚伯克隆比的隐居处位于乌鸦岭附近阴暗的树林另一边，那里遍布亡灵和野兽，只有全副武装的旅人才能安全穿行。",al={"为何让我帮斯密茨","斯密茨为何不自己送果汁","酒保为何不亲自去"}}},fp="14,317,20.410.0,17.548.1,21.267.0,28.133.0,36.222.0,27.171.0,29.89.0,56.205.0"}
P.entries["quest:1598"] = {n="失窃的典籍",s="“失窃的法术书”是为在北郡山谷训练的人类术士新兵准备的一项入门任务。在训练师杜希拉·拉萨雷的指派下，受训者必须潜入附近的迪菲亚潜行者营地，寻回一本名为《虚空灵能》的禁忌之书。通过此举，术士新兵能够证明自己的能力，并获得束缚其第一个恶魔仆从所需的知识。",h="“失窃的法术书”是为在北郡山谷训练的人类术士新兵准备的一项入门任务。在训练师杜希拉·拉萨雷的指派下，受训者必须潜入附近的迪菲亚潜行者营地，寻回一本名为《虚空灵能》的禁忌之书。通过此举，术士新兵能够证明自己的能力，并获得束...",kw={"迪菲亚潜行者","杜希拉·拉萨雷","北郡修道院","学徒窃贼","虚空灵能","失窃书籍","农场","术士小鬼"},ang={["class:Warlock"]="这一成年仪式旨在考验术士新兵是否能在不退缩的情况下穿越危险区域。获得这本书就能让你掌握召唤第一个小鬼所需的秘密仪式。",["faction:Alliance"]="在北郡的圣骑士和牧师眼皮底下行事，联盟的术士必须小心谨慎，利用亡命之徒的失误来获取受限的神秘知识。",["race:Human"]="该任务揭示了迪菲亚潜行者的势力渗透北郡有多深，甚至诱使修道院中与世隔绝的学生偷窃神圣文献并加入叛乱。"},sec={{t="禁忌的机缘",b="术士在暴风城的领地内行事必须小心谨慎，他们在隐秘的角落里磨练自己那变幻莫测的技艺，并努力不让窥探的目光发现他们的研究。北郡修道院的档案库中收藏着古老的知识，包括被锁在严密封印下的禁忌魔典。杜希拉·拉萨雷，这位潜伏在修道院内的术士导师，一直觊觎着其中的一卷——《虚空灵能》，但她不敢冒险亲自闯入图书馆的保护区，以免引起修道院牧师和圣骑士的怀疑。"},{t="迪菲亚的机会主义",b="拉萨雷的机会在一名修道院学徒投靠迪菲亚潜行者时到来了。这名背叛的学者在逃往北郡农场加入强盗时，顺手偷走了几本珍贵的书籍。强盗们在北郡农场的迪菲亚营地附近躲藏起来，并将他们的战利品藏在了一个野外帐篷里，却完全没有意识到书中所蕴含的黑暗技艺有着多么巨大的危险。"},{t="首次束缚",b="对于一名立志成为术士的人来说，找回这本书既是对胆识的考验，也是通往更黑暗奥秘的捷径。勇闯强盗营地并带回书籍不仅满足了杜希拉的野心，也证明了学徒已经做好了准备。当魔典落入她手中后，她会传授给学生召唤并束缚小鬼的黑暗仪式，这也是学徒学会指挥的第一个恶魔。"}},faq={{q="什么是《虚空灵能》？",a="这是一本详细记载了黑暗魔法概念和位面控制的禁忌魔典。它原本被存放在北郡修道院图书馆内一个有重兵把守的保护区中，书中包含了诸如杜希拉·拉萨雷这样的术士导师梦寐以求的深奥见解，供她们进行个人研究和教学。",al={"虚空灵能法术书","这本书是什么","学徒偷了什么"}},{q="为什么杜希拉·拉萨雷不亲自去偷这本书？",a="杜希拉必须小心行事，以保住她在北郡修道院的地位。偷偷潜入图书馆的机密档案室会立即引起牧师们的警觉。当一名心怀不满的学徒偷走这本法术书并加入了迪菲亚潜行者后，这给了她一个通过学徒来干净利落地获得该书的绝佳机会。",al={"为什么杜希拉不亲自去偷","为什么要派我去"}},{q="失窃的法术书藏在哪里？",a="迪菲亚强盗将法术书藏在了北郡农场内搭建的一个营地帐篷里，那里就在修道院的东边，也是他们的侦察兵和变节者驻扎的地方。",al={"书在哪里","法术书位置","失窃法术书帐篷"}},{q="为什么一名北郡学徒会加入迪菲亚潜行者？",a="不满情绪和社会动荡已在王国蔓延，驱使劳工、农民，甚至修道院的学生转而支持迪菲亚潜行者。这名学徒放弃了誓言，从图书馆拿走了几本重要书籍作为战利品，并逃向了农场的强盗那里。",al={"为什么学徒加入迪菲亚","修道院迪菲亚叛徒","谁偷了书"}},{q="术士找回法术书能得到什么奖励？",a="归还书籍让杜希拉确信，该学生拥有修习黑暗技艺所需的胆识和韧性。她会传授召唤小鬼所需的基础教学，这也标志着学徒完成了第一次成功的恶魔契约。",al={"你学到了什么","术士任务奖励","为什么要完成此任务"}},{q="迪菲亚潜行者知道如何使用这本书吗？",a="强盗们主要将这些被盗书籍视为从修道院抢来的值钱赃物。尽管迪菲亚潜行者中也有变节的施法者，但那名学徒和他的同伙只是将这卷书塞进了帐篷的板条箱里，并没有去掌握其中的黑暗秘密。",al={"迪菲亚能使用法术书吗","迪菲亚怎么处理法术书"}}},fp="15,206,23.341.0,18.270.0,17.315.0,31.215.0,52.243.0,32.99.0,56.231.0,55.179.0,39.219.0"}
P.entries["quest:1599"] = {n="开端",s="“开端”是刚开始在丹莫罗进行冒险的新手联盟术士的成人礼。在阿拉玛尔·格里姆不情不愿的指导下，新手们被派去从附近的霜鬃巨魔新手身上收集魔法羽毛咒符，以在掌握召唤小鬼的艺术之前证明自己的能力。",h="“开端”是刚开始在丹莫罗进行冒险的新手联盟术士的成人礼。在阿拉玛尔·格里姆不情不愿的指导下，新手们被派去从附近的霜鬃巨魔新手身上收集魔法羽毛咒符，以在掌握召唤小鬼的艺术之前证明自己的能力。",kw={"阿拉玛尔·格里姆","安威玛尔","开端","寒脊山谷","丹莫罗","羽毛咒符","霜鬃新手","小鬼"},ang={["class:Warlock"]="这个任务标志着联盟术士在丹莫罗的旅程中决定性的第一步，解锁了召唤你的第一个恶魔仆从的能力。",["race:Gnome"]="在寒脊山谷学习技艺的侏儒术士必须通过智取当地的霜鬃巨魔来证明自己的智慧和魔法统治力。"},sec={{t="勉为其难的导师",b="在安威玛尔这处避风港内，黑暗魔法虽然不会被公开颂扬，但因必要性而受到容忍。已有所成的术士阿拉玛尔·格里姆通常会相对隐秘地进行他的奥术研究。当新的修行者展现出潜力时，阿拉玛尔·格里姆会受到那些对新兵感兴趣的无名氏的委托，不得不从研究中抽身，亲自评估这些新兵。"},{t="黑暗魔法的火花",b="在将奴役低等恶魔的秘密传授给新手之前，阿拉玛尔·格里姆要求他们证明自己具备足够的体能和魔法亲和力。在安威玛尔西南方的一个洞穴中聚集的霜鬃巨魔新手，携带着注入了原始魔法的原始羽毛咒符。收集这些咒符不仅能证明这位术士新秀有能力征服魔法敌人，还能为阿拉玛尔·格里姆正在进行的研究提供好奇的样本。"},{t="召唤小鬼",b="带着咒符回来让阿拉玛尔·格里姆确信新手拥有足够的生存意志。试炼的高潮是传授召唤小鬼的方法，这是术士最基础的仆从。在进行仪式时，阿拉玛尔·格里姆给出了严厉的警告：尽管小鬼体型矮小，但它们挥舞着混乱的魔火，很容易就能压倒一个缺乏管教的主人。"}},faq={{q="谁给予“开端”这个任务？",a="阿拉玛尔·格里姆给予了这个任务。他是一位术士训练师，位于丹莫罗寒脊山谷的安威玛尔内。",al={"谁开启开端任务","开端任务发放者","阿拉玛尔·格里姆位置"}},{q="羽毛咒符有什么用处？",a="羽毛咒符有两种用途：它们证明了一位术士新秀能够面对并击败精通魔法的敌人，同时也为阿拉玛尔·格里姆提供了供其在研究中检查的奇特附魔巨魔饰品。",al={"为什么要羽毛咒符","羽毛咒符用途","霜鬃咒符"}},{q="霜鬃巨魔新手在哪里？",a="它们栖息在寒脊山谷安威玛尔西南方的一个洞穴中，霜鬃巨魔在那里建立了一个据点。",al={"巨魔新手在哪里","霜鬃洞穴位置","霜鬃新手地点"}},{q="完成这项任务后，术士能获得什么奖励？",a="完成这项任务可以获得阿拉玛尔·格里姆的认可，并获得召唤小鬼（术士的第一个恶魔同伴）所需的知识。",al={"开端任务教什么","开端任务奖励","小鬼法术任务"}},{q="为什么阿拉玛尔·格里姆要教导新的术士？",a="阿拉玛尔·格里姆提到，有影响力的人对这位术士新秀产生了兴趣，这说服了他暂停自己的私人奥术研究，转而测试并指导这位新兵。",al={"为什么阿拉玛尔要训练我","谁让阿拉玛尔训练我"}},{q="对于术士新手来说，小鬼危险吗？",a="是的。阿拉玛尔·格里姆明确警告说，尽管小鬼体型很小，但其魔火和狡诈使其变得不稳定，缺乏经验的召唤者很容易被它反噬。",al={"小鬼危险性","小鬼能杀死你吗","小鬼警告"}}},fx={["5dfeed0e"]={q="阿拉玛尔·格里姆为何要你完成这件事？",a="有名望的赞助者看中了你的潜力，于是劝说阿拉玛尔·格里姆暂停自己的研究，转而训练你。在教你召唤第一个恶魔——小鬼之前，他要求你证明自己有足够的魔法韧性和体魄来承受考验。找回羽毛护符也能满足他的好奇心，让他研究这种奇特的巨魔魔法。",al={"阿拉玛尔·格里姆的动机","为何要找回羽毛护符","阿拉玛尔为何想要羽毛护符"}},f653bf22={q="你奉命对付的霜鬃新手是谁？",a="霜鬃新手是年轻的冰霜巨魔，他们在安威玛尔西南方的洞穴中练习基础魔法。原住民霜鬃部族与丹莫罗的铁炉堡矮人冲突不断，并利用附近的洞穴重新集结、训练尚未成熟的施法者。",al={"丹莫罗的霜鬃新手","霜鬃新手是谁","洞穴里的巨魔新手"}}},fp="10,299,18.383.0,23.446.0,17.354.0,31.110.0,37.212.0,40.127.0,58.138.0,42.170.0,42.178.0"}
P.entries["quest:16"] = {n="葛拉德的饮料",s="“给葛拉德送水”是葛拉德·提勒托付的一件简单琐事，这位农夫在艾尔文森林的马科伦农场辛勤劳作。为了在烈日下解渴，他愿意用农产品交换清凉的泉水。这对年轻的冒险者来说，是了解以物易物和支援当地劳动者的第一课。",h="“给葛拉德送水”是葛拉德·提勒托付的一件简单琐事，这位农夫在艾尔文森林的马科伦农场辛勤劳作。为了在烈日下解渴，他愿意用农产品交换清凉的泉水。这对年轻的冒险者来说，是了解以物易物和支援当地劳动者的第一课。",kw={"苹果","以物易物","艾尔文森林","葛拉德·提勒","马科伦农场","清凉的泉水"},ang={["faction:Alliance"]="支持像马科伦农场这样的艾尔文农户，有助于在王国防御的动荡时期让森林的宅基地和驻军获得补给。",["race:Human"]="对于在北郡开始旅程的人类来说，帮助像葛拉德·提勒这样的邻居，是维系艾尔文社区精神的早期体现。"},sec={{t="农田里的口渴工作",b="艾尔文森林的农场出产了暴风城城镇居民和卫兵所需的绝大部分谷物、水果和蔬菜。在露天环境下照料庄稼是件非常辛苦且炎热的工作。葛拉德·提勒整天待在马科伦农场的泥土里，不仅要驱赶害虫，还得管理收获。由于没时间来回跑去镇上的水井，他只能依靠路过的招募人员为他带来干净的泉水，以便继续工作。"},{t="以物易物的经济学",b="比起金钱交易，葛拉德更倾向于公平且简单的补给交换。携带多余清凉的泉水的旅行者可以直接用它换取刚从果园采摘的新鲜苹果。在一个为了维持秩序和供应军队而资源紧缺的王国中，小农户和招募人员之间进行直接的易货交易，仍然是乡村艾尔文地区维持生计的实用方式。"}},faq={{q="葛拉德·提勒是谁？",a="葛拉德·提勒是一位朴实的农夫，在艾尔文森林南部的马科伦农场耕作。他负责管理那些为当地居民提供补给的田地和果园。",al={"葛拉德·提勒","提勒是谁","葛拉德"}},{q="为什么葛拉德需要水？",a="整天在烈日下的田地里劳作非常消耗体力。葛拉德需要依靠路过的旅行者为他提供清凉的泉水，这样他才能在不放下农活的情况下补充水分。",al={"为什么要泉水","葛拉德口渴","为什么需要饮料"}},{q="在哪里可以找到清凉的泉水？",a="清凉的泉水通常由艾尔文森林各处的食物和饮料商人或旅店老板出售，包括位于北郡修道院内的丹尼尔修士。",al={"去哪里拿水","泉水来源","如何获得水"}},{q="这个交易可以重复吗？",a="是的。葛拉德一直在田里干活，只要你还有多余的水，他都很乐意用新鲜的果园苹果来交换。",al={"可重复任务","我可以再做一次吗","上交更多水"}},{q="葛拉德用什么回报饮水？",a="作为清凉的泉水的交换，葛拉德会给你一个新鲜的红苹果。",al={"葛拉德奖励","我能得到什么","交易奖励"}},{q="葛拉德在哪里？",a="他就在艾尔文森林南部马科伦农场的谷仓外面。",al={"葛拉德·提勒位置","葛拉德在哪","农场在哪"}}},fp="19,156,35.392.0,21.324.0,21.139.0,27.168.0,43.149.0,25.113.0,47.48.0,24.78.0"}
P.entries["quest:160"] = {n="给镇长的信",s="“致市长的信”是暮色森林中一项联盟任务，它将古怪的隐士亚伯克隆比与夜色镇的领导层联系在了一起。在帮助这位隐居的老人后，冒险者会被要求将一封私人信件亲手交给艾尔罗·埃伯洛克公爵市长。然而，这封信带来的并非温情，而是立刻引起了怀疑。",h="“致市长的信”是暮色森林中一项联盟任务，它将古怪的隐士亚伯克隆比与夜色镇的领导层联系在了一起。在帮助这位隐居的老人后，冒险者会被要求将一封私人信件亲手交给艾尔罗·埃伯洛克公爵市长。然而，这封信带来的并非温情，而是立刻引起...",kw={"亚伯克隆比","夜色镇","暮色森林","艾尔罗·埃伯洛克","信件","市长","致市长的信"},ang={["faction:Alliance"]="夜色镇的存亡取决于能否在奇怪的骚乱突破守夜人的防线之前将其化解，因此这封可疑的信件对联盟特工来说是一个迫在眉睫的安全问题。",["race:Human"]="服务于守夜人和埃伯洛克家族的人类信使很快意识到，暮色森林边缘那个古怪的老隐士欺骗了他们。"},sec={{t="一封友好的信？",b="在帮助亚伯克隆比从沃古尔食人魔山的食人魔手中找回他被偷走的箱子后，这位隐士打发你顺着迷雾笼罩的道路回到镇上。亚伯克隆比开心地大笑，声称他和艾尔罗·埃伯洛克公爵市长是老朋友。他坚持认为，当市长得知冒险者完成了这项任务后，会和他一样感到激动。"},{t="困惑的领导",b="当你到达夜色镇的Darkshire Town Hall时，现实却与亚伯克隆比的说法大相径庭。艾尔罗·埃伯洛克公爵根本不记得有个叫亚伯克隆比的人。打开那张羊皮纸只会让谜团更加深重：信上写的根本不是老朋友之间亲切的问候，而是某种古老且无法辨认的文字，这让夜色镇的市长感到十分困惑。"}},faq={{q="是谁发出了“致市长的信”？",a="亚伯克隆比是一位住在暮色森林西侧偏僻小屋里的古怪隐士，在你从当地食人魔那里找回他被偷的财物后，他将这封信交给了你。",al={"谁给了这封致市长的信","谁开启了致市长的信任务","亚伯克隆比写信人"}},{q="亚伯克隆比和埃伯洛克市长真的是朋友吗？",a="不是。虽然亚伯克隆比声称他们是老相识，但艾尔罗·埃伯洛克公爵市长从未听说过他，并对收到这封信表示极其困惑。",al={"他们认识吗","亚伯克隆比是市长的朋友吗","亚伯克隆比与艾尔罗·埃伯洛克的关系"}},{q="信上写了什么？",a="这封信是用一种古老而晦涩的语言写成的，无论是送信的还是埃伯洛克市长都无法解读，市长因此不得不寻求外部的翻译。",al={"亚伯克隆比的信上写了什么","艾尔罗能读懂这封信吗","这封信是什么语言"}},{q="艾尔罗·埃伯洛克公爵在哪里？",a="艾尔罗·埃伯洛克公爵市长位于夜色镇的Darkshire Town Hall内，在暮色森林镇上主路东侧。",al={"市长在哪里","艾尔罗·埃伯洛克位置","我在哪里交致市长的信任务"}},{q="埃伯洛克市长收到信后会发生什么？",a="因为埃伯洛克公爵无法阅读这神秘的文字，他请你寻找能够解读文本的人，从而引出了任务“翻译亚伯克隆比的信”。",al={"致市长的信之后是什么任务","致市长的信后续"}},{q="为什么亚伯克隆比给你信的时候在笑？",a="亚伯克隆比那幸灾乐祸的笑声暗示，他的意图绝非与老友重逢那么简单，这也预示着夜色镇即将面临险恶的麻烦。",al={"为什么亚伯克隆比要笑","亚伯克隆比是邪恶的吗","亚伯克隆比的笑与信"}}},fx={["7816d016"]={q="亚伯克隆比为何让你带信，而不是亲自送去？",a="亚伯克隆比是个体弱多病、独自隐居的隐士，住在夜色镇以西很远的闹鬼树林里。让一个刚刚帮过他的、毫无戒心的旅人替他送信，就能把他那不祥的惊喜直接送到镇议事厅，而他自己不必踏足夜色镇，接近多疑的夜色镇守夜人或镇议会。",al={"为何让我送信给镇长","亚伯克隆比为何不亲自送信","为何让玩家送信"}}},fp="17,319,19.373.0,18.368.1,32.178.0,53.164.0,28.159.0,37.126.0,55.168.0,57.165.1"}
P.entries["quest:161"] = {n="水坝危机",s="出于对巨石水坝可能遭受破坏的怀疑，主工程师辛德维尔七世派遣了一名信使前往北方的湿地，对一份怪味粉末样本进行鉴定。信使必须通过奥加兹大门，沿着险峻的公路前行，将样本送到丹莫德的爆破专家阿什兰·暗石手中。",h="出于对巨石水坝可能遭受破坏的怀疑，主工程师辛德维尔七世派遣了一名信使前往北方的湿地，对一份怪味粉末样本进行鉴定。信使必须通过奥加兹大门，沿着险峻的公路前行，将样本送到丹莫德的爆破专家阿什兰·暗石手中。",kw={"阿什兰·暗石","黑暗威胁临近","丹莫德","爆炸性粉末","辛德维尔","巨石水坝","萨多尔大桥","湿地"},ang={["faction:Alliance"]="穿过洛克莫丹和湿地的高速公路是铁炉堡与萨多尔大桥对面北方联盟据点之间至关重要的军事生命线。",["profession:Engineering"]="鉴定高等级爆炸残留物需要工兵敏锐的眼光，这证明即使是寻常的粉末也能揭示出敌方破坏者高超的技术水准。",["race:Dwarf"]="巨石水坝是铜须矮人工程学的巅峰之作。任何企图破坏其建筑的阴谋，都是对整个卡兹莫丹的荣耀与安全的沉重打击。"},sec={{t="恶意之粉",b="在巨石水坝周围出现动荡后，主工程师辛德维尔七世在水坝东侧坡道附近的一只可疑木桶中发现了一包怪味粉末，他曾在那附近看到过黑铁工兵。辛德维尔意识到这可能导致灾难性的破坏，他怀疑这种物质是专门用于粉碎矮人建筑的精致炸药。由于水坝现场缺乏专业的化学检测设备，他坚持要在下结论前咨询一名军用爆破专家。"},{t="北上之路",b="这项紧急分析需要穿过奥加兹大门，进入湿地那泥泞的低地。沼泽中潜伏着充满敌意的野生生物、凶猛的龙人和黑铁渗透者，沿途危机四伏。辛德维尔敦促旅行者必须紧贴碎石路前行，直到抵达丹莫德——这座位于萨多尔大桥南端、此前曾遭劫掠的矮人城镇，目前仍有一支铁炉堡军团驻守在那里。"},{t="丹莫德的爆破专家",b="阿什兰·暗石驻扎在卡兹莫丹北部的前线，是该军团的高能炸药大师。几十年的剧烈爆炸让他的听力受损，甚至有些半聋，但暗石敏锐的目光和嗅觉立刻证实了辛德维尔最担心的事：这种化合物确实是一种专门的爆破装药，表明这显然是一个针对矮人工程学核心的精心策划的阴谋。"}},faq={{q="什么是怪味粉末？",a="这是在巨石水坝附近收集的一种炼金爆炸装药。主工程师辛德维尔七世怀疑破坏者企图用它炸毁水坝墙体。",al={"什么是怪味粉末","辛德维尔与粉末","怪味粉末"}},{q="为什么要将粉末送到丹莫德？",a="丹莫德驻扎着负责保卫萨多尔大桥的铁炉堡军团，其中包括爆破专家阿什兰·暗石。作为一名资深的炸药专家，他拥有鉴定特殊爆破化合物所需的技术知识。",al={"为什么要前往丹莫德","为什么要找阿什兰·暗石","为什么要前往湿地"}},{q="阿什兰·暗石在哪里？",a="阿什兰·暗石驻扎在丹莫德的军营里，该营地位于湿地极北处，就在萨多尔大桥南端。",al={"阿什兰·暗石在哪","寻找阿什兰","阿什兰·暗石的位置"}},{q="为什么辛德维尔警告要紧贴道路行走？",a="从奥加兹大门穿过湿地的道路直通那些遍布敌对野兽、迅猛龙、豺狼人和黑铁破坏者的区域，对于信使来说，偏离大路极其危险。",al={"为什么必须走大路","湿地的危险","通往湿地的路"}},{q="是谁在破坏巨石水坝？",a="这些炸药属于黑铁矮人，他们试图破坏铜须氏族的基建设施，并炸塌巨石水坝以淹没下方的山谷。",al={"谁制造了粉末","水坝破坏者","黑暗威胁的元凶"}},{q="为什么阿什兰·暗石听力不好？",a="多年在前线担任军事工兵和炸药专家的经历，使阿什兰患上了慢性耳鸣，并因爆炸冲击导致听力严重受损。",al={"阿什兰·暗石耳聋的原因","阿什兰为什么听力受损"}}},fx={["4fa83212"]={q="主工程师辛德维尔七世为何要你完成这件事？",a="主工程师辛德维尔负责巨石水坝的稳固，这座水坝是卡兹莫丹最伟大的工程奇迹之一。他怀疑附近发现的奇怪粉末是一种意图破坏水坝的炸药，因此需要专家分析，以便在灾难发生前弄清水坝面临的确切威胁。",al={"辛德维尔为何需要这东西","辛德维尔的动机","为何要送粉末"}}},fp="19,321,22.504.0,14.451.0,28.390.1,36.162.0,44.236.0,35.149.0,46.223.0,39.158.1,41.171.0"}
P.entries["quest:1618"] = {n="赤脊山的补给",s="“武装赤脊山”是联盟的一项锻造专业任务，由铁炉堡的托姆斯·深炉发布。有志向的铁匠们需要锻造坚固的铜制装备，以支援湖畔镇被围困的守军，并帮助当地铁匠弗纳·奥斯古抵御该地区的敌对兽人和豺狼人。",h="“武装赤脊山”是联盟的一项锻造专业任务，由铁炉堡的托姆斯·深炉发布。有志向的铁匠们需要锻造坚固的铜制装备，以支援湖畔镇被围困的守军，并帮助当地铁匠弗纳·奥斯古抵御该地区的敌对兽人和豺狼人。",kw={"黑石兽人","锻造","豺狼人","重型铜锤","湖畔镇","赤脊山","符文铜腰带","石堡","托姆斯·深炉","弗纳·奥斯古"},ang={["faction:Alliance"]="这次交付展示了铁炉堡与南方苦难重重的人类城镇之间至关重要的相互援助，在暴风城分裂的领导层行动滞后时介入了进来。",["profession:Blacksmithing"]="这项任务是锻造学徒的成人礼，考验你为活跃战线按需大量生产耐用武器和防护护甲的能力。",["race:Dwarf"]="矮人工艺是联盟战争努力的基石，托姆斯确保铁炉堡的天才们能用他们的技艺去援助受困的盟友。",["race:Human"]="对于南方王国的人类来说，接收在Khaz Modan锻造的金属制品，能为他们对抗好战的黑石残党提供亟需的援助。"},sec={{t="跨越王国的请求",b="虽然铁炉堡的Great Forge从不沉睡，但矮人铁匠们意识到联盟的前线战事早已延伸到了丹莫罗之外。在赤脊山，人类定居点湖畔镇发现自己正陷入不断的苦战中，不仅遭受着从石堡要塞开出的黑石兽人的常规入侵，还有成群结队的豺狼人在北部山脊出没。由于来自暴风城的皇家增援迟迟未到，当地的补给正处于危险的匮乏状态。"},{t="湖畔镇的铁砧",b="湖畔镇的常驻铁匠弗纳·奥斯古几乎独自一人在他那露天的熔炉旁工作，试图修补破碎的护甲并更换破损的武器。托姆斯·深炉注意到了这位人类同行的压力，于是指引正在成长的铁匠们直接向湖畔镇运送四条符文铜腰带和四把重型铜锤。作为对加强民兵防御储备的回报，弗纳很乐意将更精湛的商业技巧传授给路过的工匠。"}},faq={{q="谁发布了“武装赤脊山”任务？",a="托姆斯·深炉，铁炉堡Great Forge的一名矮人铁匠，向锻造技术达到足够水平的联盟铁匠提供该任务。",al={"武装赤脊山任务发放者","谁提供武装赤脊山","托姆斯任务"}},{q="为什么湖畔镇需要来自铁炉堡的武器和护甲？",a="湖畔镇面临着占据石堡要塞的黑石兽人以及当地好斗的豺狼人的持续攻击。镇上唯一的铁匠弗纳·奥斯古忙于独自修理武器和为民兵打造护甲，早已分身乏术。",al={"为什么赤脊山需要装备","为什么湖畔镇需要武器","赤脊山补给短缺"}},{q="在赤脊山谁来接收货物？",a="货物将交付给弗纳·奥斯古，他是驻扎在湖畔镇湖边熔炉附近的当地铁匠。",al={"在哪里交武装赤脊山任务","弗纳·奥斯古位置","赤脊山铁匠交任务"}},{q="该任务需要锻造什么装备？",a="你必须提供四条符文铜腰带和四把重型铜锤。这些装备展示了防护板甲和重型打击武器的锻造工艺。",al={"武装赤脊山所需物品","武装赤脊山材料","为托姆斯制作什么"}},{q="目前有哪些威胁在困扰着赤脊山？",a="威胁湖畔镇的主要危险是盘踞在石堡要塞内的黑石兽人氏族，以及在北部丘陵地带游荡的凶残豺狼人群。",al={"赤脊山敌人","谁在攻击湖畔镇","赤脊山威胁"}},{q="弗纳·奥斯古会提供什么奖励？",a="从为每一名卫兵从头装备的繁重负担中解脱出来后，弗纳会抽出时间教你高级锻造技术。",al={"弗纳·奥斯古训练","武装赤脊山奖励","我能得到什么"}}},fx={ba6aca96={q="托姆斯·深炉为什么想让你完成这件事？",a="托姆斯·深炉明白，铁炉堡的人类盟友正承受着沉重压力，也在为自己的生存奋战。黑石氏族不断袭击湖畔镇，他希望通过提供关键的锻造援助，增强矮人与人类之间的联系，帮助这位已不堪重负的盟友。",al={"为什么要帮助redridge","托姆斯·深炉的动机","为什么要给redridge送补给"}},e26bdf46={q="符文铜腰带有什么用？",a="这些附魔腰带能为湖畔镇的守卫者提供至关重要的护甲加固。当地铁匠忙于修理损坏的装备，结实耐用的腰带可以保护镇卫和民兵，让他们在不断与黑石兽人和豺狼人交战时多一分保障。",al={"符文铜腰带的用途","为什么要用符文铜腰带","符文铜腰带的作用"}},["61555f3e"]={q="重型铜槌有什么用？",a="重型铜槌能为湖畔镇的前线守卫者提供耐用而凶猛的武器。Redridge 的守卫者不断与身披护甲的黑石兽人和强悍的 Redridge 豺狼人交战，因此沉重的钝器对他们的战事不可或缺。",al={"重型铜槌的用途","为什么要用重型铜槌","redridge的重型铜槌"}},["330fd0fb"]={q="托姆斯·深炉为什么需要你送货，而不是亲自送去？",a="托姆斯是位大师级铁匠，既要训练学徒，也要管理铁炉堡的 Great Forge。这个重要职位让他无法抽身前往人类的土地。把货物托付给一位有志成为铁匠的人，既能帮助盟友，也能让你向弗纳·奥斯古学习贸易技巧。",al={"为什么派我去redridge","托姆斯为什么不能亲自送货","为什么派我去整备redridge"}}},fp="16,277,22.481.0,23.464.0,38.157.0,57.240.0,38.124.0,43.144.0,49.188.0,47.146.0"}
P.entries["quest:162"] = {n="异种蝎的威胁",s="高级勘探员菲兹杜瑟催促你将那份关于昆虫威胁的报告交给格拉希娜·灵风，她是达纳苏斯的一位暗夜精灵学者兼历史学家。",h="高级勘探员菲兹杜瑟催促你将那份关于昆虫威胁的报告交给格拉希娜·灵风，她是达纳苏斯的一位暗夜精灵学者兼历史学家。",kw={"达纳苏斯","菲兹杜瑟","格拉希娜","昆虫分析","其虫","灵风","塔纳利斯","temple of the moon"},sec={{t="达纳苏斯的学者",b="菲兹杜瑟希望这份报告能交到对此类事物有研究的人手中。格拉希娜·灵风是一位暗夜精灵学者，她花费了大量时间研究艾泽拉斯生态中独特的生命形式，同时她也是一位历史学家。菲兹杜瑟希望她能帮忙弄清这种危险的本质，最重要的是，找出阻止它的方法。据菲兹杜瑟所言，她一直住在达纳苏斯的Temple of the Moon。"},{t="格拉希娜的回答",b="格拉希娜说，暗夜精灵知晓报告中所描述的恐怖，并认为菲兹杜瑟的选择很明智，既送来了报告，也派来了你。这些生物将迅速吞噬塔纳利斯沙漠，是任何人所面临的最大威胁之一。它们是其虫，是部落和联盟共同面临的最严重威胁之一的工具。格拉希娜惋惜地说，没有人在更早的时候意识到这一点。"}},faq={{q="格拉希娜·灵风是谁？",a="一位暗夜精灵学者兼历史学家，花费了大量时间研究艾泽拉斯生态中独特的生命形式。",al={"格拉希娜·灵风背景故事","格拉希娜是谁","temple of the moon的学者"}},{q="是谁派你去找格拉希娜的？",a="高级勘探员菲兹杜瑟给了你昆虫分析报告，并要求你把它交给她。",al={"报告来自哪里","昆虫分析报告来源"}},{q="在哪里可以找到格拉希娜·灵风？",a="根据菲兹杜瑟的说法，她在达纳苏斯的Temple of the Moon。",al={"格拉希娜在哪里","格拉希娜·灵风位置","找到格拉希娜·灵风"}},{q="这次前往达纳苏斯的旅程之前发生了什么？",a="它是“昆虫部分分析”的后续。",al={"前置任务","什么导致了其虫的崛起","找格拉希娜之前的任务"}}},fp="20,151,22.429.0,16.395.1,27.122.0,25.97.0,39.68.0,43.32.0"}
P.entries["quest:163"] = {n="乌鸦岭",s="关于废弃的乌鸦岭定居点中出现了移动的阴影和闪烁的窗灯的报告，让守夜人感到如坐针毡。在夜色镇的艾莱尼·卡尔文的派遣下，旅行者们前往西部的闹鬼森林，去直面那潜藏在废墟之中的邪恶存在。",h="关于废弃的乌鸦岭定居点中出现了移动的阴影和闪烁的窗灯的报告，让守夜人感到如坐针毡。在夜色镇的艾莱尼·卡尔文的派遣下，旅行者们前往西部的闹鬼森林，去直面那潜藏在废墟之中的邪恶存在。",kw={"卡洛尔","夜色镇","暮色森林","艾莱尼·卡尔文","基特斯","守夜人","乌鸦岭"},ang={["class:Paladin"]="受过训练去猎杀困扰着附近墓地的游荡亡灵的圣骑士，在调查险恶闹鬼报告时，可能会发现瑟瑟发抖、有血有肉的基特斯是一个意外的发现。",["faction:Alliance"]="暮色森林的守夜人几乎无法从暴风城的驻军那里得到任何援助，这迫使他们不得不依靠路过的联盟英雄来调查这片领土荒芜角落里的不祥威胁。"},sec={{t="西方的注视",b="对于守夜人的游侠们来说，暮色森林的最西端早已被死者和荒野占据。然而，彻底的荒废也比出现意料之外的活动要好。卡洛尔，一名巡逻在阴暗道路上的守望者，连续两晚注意到乌鸦岭寂静的房屋间有动静，还伴随着窗户中令人不安的灯火闪烁。在这个饱受食尸鬼、骷髅和野兽困扰的土地上，任何无法解释的生命迹象都必须立即进行调查。"},{t="惊恐的隐士",b="那些期待在乌鸦岭内与新出现的恶魔或亡灵军阀交战的人，会发现现实远比这可怜得多。在残垣断壁中瑟瑟发抖的正是基特斯，一个彻底精神失常的流浪汉，他对黑暗中的任何一丝响动都感到战栗。虽然他疯狂地辩解说除了“无害的基特斯”之外并没有什么威胁，但他狂乱的胡言乱语表明，对于正在吞噬暮色森林的梦魇，他所知道的远比他敢于说出来的要多。"}},faq={{q="是谁派你来调查乌鸦岭的？",a="艾莱尼·卡尔文，一位协助守夜人的夜色镇居民，她恳求那些关心暮色森林安全的旅行者们去核实一下西部传来的不安传闻。",al={"谁发布乌鸦岭的任务","乌鸦岭任务发布者","艾莱尼·卡尔文任务"}},{q="卡洛尔在乌鸦岭到底看见了什么？",a="卡洛尔报告说连续两晚看到废弃定居点里有移动的阴影，在那之前的一晚，还看到其中一间房屋的窗户里点着灯或蜡烛。",al={"卡洛尔看见了什么","卡洛尔乌鸦岭目击事件","乌鸦岭的阴影"}},{q="什么怪物在废墟中作祟？",a="这正是你被派去发现的内容。卡洛尔只是瞥见了移动的阴影和窗户里的灯光；无论什么潜伏在乌鸦岭那破败的建筑里，都必须亲自去寻找。",al={"谁在乌鸦岭作祟","乌鸦岭里有什么","乌鸦岭的怪物是真的吗"}},{q="基特斯是谁？",a="基特斯是一个神经过敏、充满被害妄想的流浪汉，生活在暮色森林西部恐惧的边缘。虽然他声称自己完全无害，但他极度的内疚和狂乱的呓语暗示他与这片地区更黑暗的秘密有着千丝万缕的联系。",al={"基特斯背景故事","暮色森林的基特斯是谁","为什么基特斯在躲藏"}},{q="乌鸦岭在哪里？",a="乌鸦岭位于暮色森林的最西部，就在那座以其命名的、被亡灵占据的巨大墓地南面。",al={"乌鸦岭位置","去哪里找乌鸦岭","乌鸦岭地图"}},{q="为什么守夜人对移动的阴影如此担忧？",a="夜色镇在应对骷髅暴动、野性狼人和潜伏的蜘蛛时已经疲于奔命。在废弃的西部，任何有组织的活动迹象或奇怪的居民都可能预示着即将对剩余的人类定居点发动袭击。",al={"为什么要关心乌鸦岭","守夜人乌鸦岭"}}},fx={["2c575d43"]={q="艾莱尼·卡尔文为什么想调查乌鸦岭？",a="艾莱尼·卡尔文一心守护暮色森林的安全。夜色镇守夜人已经疲于应付林间蔓延的恐怖，而乌鸦岭这座废弃聚落里出现的诡异灯光和移动阴影不容忽视。她需要有人查明，是否有新的威胁正在这片区域的西部边缘滋生。",al={"艾莱尼为什么派你去","艾莱尼·卡尔文的动机","为什么调查乌鸦岭"}},["2a1c77d7"]={q="艾莱尼·卡尔文为什么请冒险者帮忙，而不是派夜色镇守夜人？",a="夜色镇守夜人人手严重不足，光是守住夜色镇的外围、保护道路就已疲于奔命。所有能战斗的守卫都被牵制在抵御亡灵、蜘蛛和狼人上，艾莱尼只能依靠那些愿意深入乌鸦岭荒废遗迹的能干旅人。",al={"为什么派我去乌鸦岭","艾莱尼为什么不派守夜人","为什么找冒险者帮忙"}}},fp="10,297,16.493.0,16.438.1,40.178.0,42.178.0,35.190.1,15.230.1,28.138.0,57.237.0"}
P.entries["quest:1638"] = {n="战士的训练",s="“战士的训练”是一个介绍性的职业任务，指引有前途的年轻战士从闪金镇前往暴风城。在训练师里瑞亚·杜拉克的指派下，士兵们前往Old Town的Pig and Whistle Tavern，寻找老兵哈里·伯加德，以接受战场耐力方面的老练教导。",h="“战士的训练”是一个介绍性的职业任务，指引有前途的年轻战士从闪金镇前往暴风城。在训练师里瑞亚·杜拉克的指派下，士兵们前往Old Town的Pig and Whistle...",kw={"巴特莱比","闪金镇","哈里·伯加德","里瑞亚·杜拉克","old town","pig and whistle","暴风城","训练","战士"},ang={["class:Warrior"]="这次试炼标志着你从一名当地民兵新兵转变为一名正式受认可的联盟士兵，解锁了高级姿态和防御技巧。",["faction:Alliance"]="像哈里·伯加德这样经验丰富的老兵确保前往争议边境的新兵们掌握实用的打斗智慧，而不仅仅是书本上的战术。",["race:Human"]="这条道路将人类战士从艾尔文的田园防御中引向Old Town，这是暴风城充满尚武传统的工人阶级摇篮。"},sec={{t="从艾尔文到Old Town",b="一旦一名有抱负的战士证明了他们处理艾尔文森林各地威胁的可靠基础，他们的训练师就会意识到闪金镇的教官已经教不了更多东西了。里瑞亚·杜拉克将新兵送往暴风城的核心地带，确切地说是前往Old Town这个粗犷的区域。在那里，老练的战士们聚集在一起，远离皇家卫戍部队的刻板形式，交流战斗经验。"},{t="老兵的课程",b="Old Town的联络人是哈里·伯加德，一位上了年纪的战斗老兵，他住在Pig and Whistle Tavern。哈里并不是在阅兵场上进行操练，而是通过酒馆的磨练和实用的耐力来考验战士的勇气。在教授让士兵在危险的战役中活下来的防御动作之前，哈里希望新来的人能跟上他的酒量，并击败当地的斗殴者。"}},faq={{q="谁提供这个任务？",a="这个任务由里瑞亚·杜拉克提供，她是驻扎在闪金镇铁匠铺后面的战士训练师，一旦战士证明了他们早期的战斗熟练度，就可以接到任务。",al={"任务发布者","谁开启了战士的训练","里瑞亚·杜拉克任务"}},{q="在哪里可以找到哈里·伯加德？",a="哈里·伯加德位于Pig and Whistle Tavern内，坐落在暴风城的Old Town区。",al={"哈里·伯加德在哪里","哈里·伯加德位置","pig and whistle tavern"}},{q="哈里·伯加德教什么？",a="哈里是一位老兵，他指导战士掌握实用的动作和姿态，旨在让他们在战场上活得更久，并以一些有趣的耐力测试作为开始。",al={"你学到了什么","战士任务奖励10级","哈里·伯加德的课程"}},{q="为什么训练是在酒馆而不是在军营里进行？",a="Old Town是暴风城传统的、较粗犷的核心地带，退伍士兵和身经百战的老兵都聚集在这里。哈里更喜欢在麦芽酒和徒手格斗的规训中进行指导，而不是拘泥于古板的军事礼仪。",al={"为什么是pig and whistle","为什么在酒馆训练","暴风城军营"}},{q="和哈里交谈后会发生什么？",a="哈里会立即让新兵参与一项涉及当地斗殴者酒鬼巴特莱比的挑战，在完成他们的训练之前测试他们的身体恢复力。",al={"下一个任务是什么","战士的训练之后","下一步"}},{q="非战士职业可以接到这个任务吗？",a="不可以。这个任务是专门的战士训练路线的一部分，仅提供给战士职业的角色。",al={"这是战士专属吗","圣骑士能做这个吗","战士职业任务"}}},fp="20,234,23.356.0,22.374.0,21.139.0,35.103.0,32.121.0,57.209.0,35.166.1,36.91.0"}
P.entries["quest:1639"] = {n="醉鬼巴特莱比",s="“醉鬼”巴特莱比是暴风城中联盟战士训练的一个早期试炼。在Pig and Whistle Tavern中，哈里·伯加德指派有志向的战士去挑战一个固执的酒鬼，并夺取他珍视的酒杯。这是一个简单的勇气测试，旨在证明战士在学习真正的战斗技巧前，能够应对一场斗殴。",h="“醉鬼”巴特莱比是暴风城中联盟战士训练的一个早期试炼。在Pig and Whistle...",kw={"巴特莱比","醉鬼","哈里·伯加德","酒杯","old town","猪和哨声酒馆","暴风城","训练","战士"},ang={["class:Warrior"]="这次对峙标志着暴风城的训练师在教你防御战术和姿态掌握之前所要求的实战测试。",["faction:Alliance"]="这场酒馆斗殴展示了暴风城Old Town粗犷、不加修饰的一面，与暴风要塞的皇室宫廷相去甚远。"},sec={{t="酒馆里的考验",b="在哈里·伯加德于Old Town的酒馆教授更深奥的战斗技巧之前，他要求新兵证明自己有真正的骨气。哈里没有安排一场正规的Sparring Match，而是指着房间另一端正在吧台尽头喝闷酒的醉鬼巴特莱比。任务很简单：拿走那个人的酒杯。伯加德很清楚，巴特莱比宁愿打架也不愿交出麦芽酒，这使得这场对峙成为了战士决心的一次即时考验。"},{t="Old Town的礼仪",b="Pig and Whistle Tavern主要接待士兵、劳工和当地粗鲁的居民，因此这里的人没什么耐心去讲究礼仪。接近巴特莱比只会换来嘲讽，而不是交谈，因为这个醉鬼会立刻嘲笑任何新人，觉得他们太娇气，不适合在酒馆里打架。这种摩擦为地板上的一场斗殴奠定了基础，表明在暴风城的武术圈子里，进阶往往始于最基本的酒馆斗殴。"}},faq={{q="谁是巴特莱比？",a="巴特莱比是一个固执、酗酒的酒客，在暴风城Old Town区的Pig and Whistle Tavern里闲逛。",al={"谁是巴特莱比","巴特莱比npc","醉鬼巴特莱比"}},{q="哈里·伯加德为什么要让我去找巴特莱比？",a="哈里·伯加德想在决定教你高级战士技巧之前，看看你有几斤几两。夺取巴特莱比的酒杯必然会引发一场战斗，用以测试你是否敢于挨拳头并坚守阵地。",al={"为什么要和巴特莱比打架","哈里·伯加德的测试","为什么要拿酒杯"}},{q="这场遭遇发生在哪里？",a="这场遭遇发生在位于暴风城东侧Old Town的Pig and Whistle Tavern内。",al={"巴特莱比在哪里","pig and whistle tavern位置"}},{q="和巴特莱比交谈会发生什么？",a="巴特莱比会侮辱你，说你花哨又娇气，并警告你在Pig and Whistle Tavern这种粗犷的地方别弄断了指甲，这很快就会引发一场斗殴。",al={"巴特莱比说了什么","巴特莱比对话"}},{q="和巴特莱比谈话之后会怎样？",a="与巴特莱比对峙会直接导致一场酒馆斗殴，你必须在物理上击败他，才能拿走他的酒杯并交还给哈里·伯加德。",al={"巴特莱比之后的任务","醉鬼巴特莱比后续"}},{q="这个任务所有职业都能接吗？",a="不，这个任务是联盟战士达到10级后专属职业训练任务线的一部分。",al={"谁能做巴特莱比任务","仅限战士"}}},fp="18,193,18.347.0,18.330.0,16.113.0,45.195.0,37.111.0,40.133.0,37.122.0,37.76.0"}
P.entries["quest:164"] = {n="斯温的货物",s="“送往斯温处的补给”是艾莱尼·卡尔文在夜色镇发布的一项联盟任务，要求将必要的补给品运送到暮色森林西北边境的一处孤立营地。在那里，斯温·约根和他仅存的几名追随者正在与那片被腐化森林中的恐怖存在进行着绝望而孤独的战斗。这项差事将苦苦挣扎在阴影中的镇民与荒野边缘的一支孤军连接在了一起。",h="“送往斯温处的补给”是艾莱尼·卡尔文在夜色镇发布的一项联盟任务，要求将必要的补给品运送到暮色森林西北边境的一处孤立营地。在那里，斯温·约根和他仅存的几名追随者正在与那片被腐化森林中的恐怖存在进行着绝望而孤独的战斗。这项差...",kw={"卡尔文","夜色镇","暮色森林","艾莱尼·卡尔文","圣光","斯温的货物","斯温·约根"},ang={["class:Paladin"]="艾莱尼将斯温称为一名践行圣光真正使命的人，这使得这次补给任务成为了对处于被围困状态的兄弟的一种声援行动。",["faction:Alliance"]="像斯温这样的边境哨兵代表了联盟在暮色森林中勉力维持的触角，这里的生存不依赖于正规军的补给线，而是依靠自愿的信使。",["race:Human"]="卡尔文家族和斯温的追随者展现了暴风城农村居民顽强的毅力，尽管身处无尽的阴影之中，却始终不肯放弃暮色森林。"},sec={{t="通往荒野的生命线",b="尽管夜色镇勉强守住了防线，抵御着狼群、蜘蛛和The Restless Dead的侵袭，但仍有人不愿躲在栅栏后苟活。斯温·约根和屈指可数的同伴在暮色森林的西北边缘建立了一处孤立的营地。他们时刻面临着巨大的威胁，根本抽不出哪怕一个人手进行往返城镇的长途跋涉去获取补给。艾莱尼·卡尔文主动承担起协调援助的责任，依靠勇敢的旅者来确保这些边境战士不会挨饿。"},{t="卡尔文家族的联系",b="卡尔文家族对斯温怀有极高的敬意，认为他的顽强抵抗是对圣光的虔诚奉献。艾莱尼愿意组织并运送物资，凸显了那些让暮色森林不至于完全坠入阴影的隐秘生存网络。当斯温收到板条箱时，他领会到了卡尔文家族持久的支持，尽管他的心思依然被眼前的严酷战斗所占据。"}},faq={{q="斯温·约根是谁？",a="斯温·约根是一名边境守望者，在暮色森林的西北边缘驻守着一处武装营地。在艾莱尼·卡尔文这样的人眼中，他是一位执行圣光意志的正直战士。斯温和他的小队正在与肆虐于周边森林的无数恐怖威胁进行抗争。",al={"谁是斯温","斯温背景故事","斯温·约根信息"}},{q="为什么斯温需要别人送去补给？",a="斯温的队伍人数极少，且时刻都在戒备周边的威胁。他们甚至抽不出一个人手来完成前往夜色镇并返回的危险旅程，因此只能完全依赖富有同情心的镇民和路过的信使来获取维持生存的物资。",al={"为什么斯温无法获得补给","斯温补给品","为什么进行配送"}},{q="谁提供了补给品？",a="补给品由夜色镇的艾莱尼·卡尔文提供。她的家族与斯温保持着密切的关系，并对其奉献精神倍加推崇，经常安排援助以支持他的营地。",al={"谁发送补给","艾莱尼·卡尔文","卡尔文家族"}},{q="斯温的营地在哪里？",a="斯温的营地坐落在暮色森林西北部的群山之下，位于远离大路、荒废农田以北的地方，正处于荒野的交界地带。",al={"斯温在哪里","斯温位置","斯温营地"}},{q="在进一步帮助斯温之前，必须完成这个送货任务吗？",a="不需要。虽然艾莱尼·卡尔文提供这个任务是为了指引旅者前往斯温处，但那些独自探索并发现斯温营地的冒险者也可以直接帮助他，而无需携带艾莱尼的板条箱。",al={"送往斯温处的补给是必需的吗","我需要完成送往斯温处的补给吗","配送前置条件"}},{q="收到补给后斯温会做什么？",a="斯温对卡尔文家族的支持表示了诚挚的感谢，但他关心的焦点立刻转回了威胁其营地和家族历史的严峻危机上，他开始寻找有能力的战士来帮助他复仇。",al={"接下来会发生什么","送往斯温处的补给之后","斯温后续任务"}}},fx={cd88e308={q="艾莱尼·卡尔文为什么想给斯温送补给？",a="艾莱尼·卡尔文十分敬重斯温·约根，认为他在荒野中的征战是真正践行圣光之道。她的家族经常为他的事业提供必需品，但斯温的小队人手太少，无法抽人前往夜色镇安全地领取补给。",al={"艾莱尼为什么派人送补给","艾莱尼·卡尔文的动机","为什么艾莱尼要帮助斯温"}},d0ad7f5e={q="艾莱尼·卡尔文为什么找你帮忙，而不是夜色镇守夜人？",a="夜色镇守夜人已经被逼到极限，既要守卫夜色镇，又要巡逻主要道路，抵御暮色森林的亡灵和野兽。他们没有多余的人手，能去北部荒野深处那座偏僻营地运送补给。",al={"艾莱尼为什么需要我","为什么不派守夜人","为什么要我亲自送补给"}}},fp="18,417,28.505.0,22.404.0,19.277.0,43.268.0,26.196.0,29.173.0,55.189.0,47.207.0"}
P.entries["quest:1640"] = {n="击败巴特莱比",s="“打败巴特莱比”是对暴风城有抱负的联盟战士武艺的直接考验。为了完成入门任务，受训者必须与一个顽固的镇上酒鬼进行肉搏，这个酒鬼不打一架绝不肯交出他珍爱的酒杯。向他证明自己的力量，既能赢得他不情愿的尊重，也能获得战士训练师所需的器皿。",h="“打败巴特莱比”是对暴风城有抱负的联盟战士武艺的直接考验。为了完成入门任务，受训者必须与一个顽固的镇上酒鬼进行肉搏，这个酒鬼不打一架绝不肯交出他珍爱的酒杯。向他证明自己的力量，既能赢得他不情愿的尊重，也能获得战士训练师所...",kw={"巴特莱比","斗殴","醉鬼","酒杯","暴风城","训练","试炼","战士"},ang={["class:Warrior"]="这场酒馆斗殴构成了联盟战士早期的标志性试炼，灌输了一个严酷的教训：在外交失败时，意志力和沉重的拳头往往能解决争端。",["faction:Alliance"]="这场小规模冲突发生在暴风城的街道上，在庄严的石墙之外，让人一窥这座城市粗犷而混乱的底层生活。"},sec={{t="拳手的挑战",b="暴风城的战士导师们不接受借口，也不会教导学生战斗总是高尚而宏大的。作为新兵正式训练的一部分，年轻的战士们被派去从巴特莱比那里取回一个特定的酒杯，这是一个在城里游荡的臭名昭著的酒鬼。当被接近时，巴特莱比对任何礼貌的请求都嗤之以鼻，发誓说任何人想要得到他的珍贵酒杯，唯一的办法就是从他冰冷、死去的指尖中夺走它。对于刚出道的战士来说，言语很快就会让位于赤手空拳的暴力。"},{t="醉酒的一课",b="虽然巴特莱比口口声声说要战斗至死，但只要把他痛打一顿，就足以让他清醒过来。一旦被打服，他的虚张声势就会变成受挫后的钦佩。意识到对手比看起来要强得多，他会平静地屈服，让胜利者最终拿到酒杯，完成训练大厅的试炼。"}},faq={{q="谁是巴特莱比？",a="巴特莱比是一个经常出没于暴风城的蛮横酒鬼。他因紧紧抓住一个心爱的酒具而闻名，他充当了被派来证明自己体能的新手战士们的无意障碍和陪练对象。",al={"巴特莱比","谁是巴特莱比","巴特莱比npc"}},{q="我为什么要和巴特莱比打架？",a="联盟战士训练师派遣新兵去取回巴特莱比手中的特定酒杯。因为他顽固地拒绝在不打一架的情况下交出酒杯，受训者必须在近身格斗中击败他，才能让他松手。",al={"为什么要打巴特莱比","打败巴特莱比的原因","为什么要打败他"}},{q="我在这个任务中真的要杀死巴特莱比吗？",a="不会。尽管他吹嘘说你必须从他冰冷、死去的指尖中夺走酒杯，但巴特莱比在生命值耗尽后会投降，并痛快地承认你比他预想的要强得多。",al={"巴特莱比会死吗","杀死巴特莱比","巴特莱比死了吗"}},{q="这个任务发生在哪里？",a="对峙发生在暴风城内，巴特莱比可以在那里被发现，他正在喝酒和游荡。",al={"打败巴特莱比的地点","巴特莱比在哪里","巴特莱比的位置"}},{q="我击败他之后会发生什么？",a="一旦被打败，巴特莱比会屈服并友善地与你交谈。然后你就可以拿走他的酒杯并将其送回给战士训练师，从而完成你的入门。",al={"打败巴特莱比之后","打败巴特莱比之后要做什么"}},{q="这次试炼代表什么等级的训练？",a="这场打斗代表了刚出道的战士在积累了大约十个赛季经验后的一个早期里程碑，是对基本近战耐力的一次实战测试。",al={"巴特莱比任务等级","什么时候去打巴特莱比"}}},fp="13,171,21.424.0,16.316.0,16.167.0,32.181.0,42.149.0,33.78.0,32.142.0,49.139.0"}
P.entries["quest:1641"] = {n="圣洁之书",s="“神圣之书”是暴风城王国年轻圣骑士的重要通过仪式。在Cathedral of Light的达索瑞恩·拉尔的指导下，初学者将接受考验，以检验他们对美德、虔诚以及行使圣光的庄严职责的理解。",h="“神圣之书”是暴风城王国年轻圣骑士的重要通过仪式。在Cathedral of Light的达索瑞恩·拉尔的指导下，初学者将接受考验，以检验他们对美德、虔诚以及行使圣光的庄严职责的理解。",kw={"神圣之书","威尔海姆修士","cathedral of light","达索瑞恩·拉尔","圣光","圣骑士","暴风城","美德"},ang={["class:Paladin"]="这一仪式标志着从一名普通的武器学徒转变为圣光的真正仆人，确立了定义该教团的牺牲与仁慈的核心原则。",["faction:Alliance"]="训练坚定的圣骑士可以加强暴风城的核心力量，确保正义的守护者时刻准备着保护联盟免受不断升起的黑暗侵袭。",["race:Human"]="对于暴风城的人类来说，这一仪式旨在纪念洛丹伦陨落骑士的遗产，并在南方王国延续白银之手那令人自豪的传统。"},sec={{t="圣骑士的召唤",b="在Cathedral of Light宁静的大理石殿堂内，达索瑞恩·拉尔负责指导那些肩负圣骑士使命的人。虽然早期的训练侧重于武艺纪律和战斗仪式，但想要在教团内晋升，还需要更深层次的精神承诺。“神圣之书”相关的试炼要求初学者超越战斗本身，去理解在内外危机重重下的王国中，道德责任的分量。"},{t="美德之路",b="获得“神圣之书”意味着签订了一份服务与自我牺牲的契约。达索瑞恩要求有志成为勇士的人研读这本神圣文本，以领悟圣光对其守护者所提出的要求。书中所载的教诲使圣骑士能够抵御天灾军团不断蔓延的恐怖，保护平民百姓，并证明正义的力量必须始终受到真正美德与仁慈的约束。"}},faq={{q="“神圣之书”的目的是什么？",a="“神圣之书”是给予成长中的圣骑士的基础神圣文本和试炼。它旨在检验初学者对神圣原则的掌握程度，然后再授予他们更伟大的神圣能力，确保他们的力量植根于虔诚和美德，而非仅仅是武力。",al={"为什么需要神圣之书","什么是神圣之书","圣骑士之书任务"}},{q="谁是达索瑞恩·拉尔？",a="达索瑞恩·拉尔是驻扎在暴风城Cathedral of Light的一名高级圣骑士训练师。他负责指导新晋的圣骑士，向他们颁发“神圣之书”，并指导他们在王国各地的试炼。",al={"达索瑞恩·拉尔","暴风城圣骑士训练师","达索瑞恩是谁"}},{q="这项试炼在哪里进行？",a="任务始于暴风城的Cathedral Square，位于宏伟的Cathedral of Light内。初学者在完成闪金镇等外围城镇的初步任务后，直接向达索瑞恩·拉尔汇报。",al={"达索瑞恩在哪里","cathedral of light任务","神圣之书任务起始地点"}},{q="为什么暴风城的教义中会提到天灾军团？",a="尽管天灾军团摧毁了北方的洛丹伦，但亡灵仍然对所有凡人构成生存威胁。暴风城的圣骑士从一开始就接受训练，以识别并对抗艾泽拉斯任何地方出现的天灾军团邪恶腐化。",al={"暴风城面临的天灾威胁","为什么会有天灾军团","圣骑士对抗天灾军团"}},{q="阅读“神圣之书”之后要做什么？",a="研读文本只是第一步。达索瑞恩·拉尔会通过派遣初学者去帮助那些身处困境的人，来检验他们是否真正领悟了书中的教诲，以行动而非言语来证明他们的仁慈与韧性。",al={"神圣之书后续步骤","阅读书籍之后","达索瑞恩的下一步要求"}},{q="通常是谁引导候选人去找达索瑞恩·拉尔？",a="在艾尔文森林外围定居点服务的当地导师和神职人员，例如闪金镇的威尔海姆修士，会识别初学者何时准备好接受正式试炼，并将他们直接派往首都的达索瑞恩那里。",al={"谁派我去找达索瑞恩","神圣之书的前置任务","威尔海姆修士"}}},fp="20,220,19.405.0,18.313.0,44.220.0,22.179.0,33.184.0,54.218.0,46.214.0,50.222.0"}
P.entries["quest:1642"] = {n="圣洁之书",s="《神圣法典》是致力于圣光的圣骑士训练中的基石。它旨在引导暴风城的有志之士，其神圣教义强调真正的神性在于谦卑的美德、同情心和耐心，而非单纯的武力或对神格的追求。在达索瑞恩·拉尔的注视下，新兵必须通过为王国中贫困与弱势者服务来践行这些教训。",h="《神圣法典》是致力于圣光的圣骑士训练中的基石。它旨在引导暴风城的有志之士，其神圣教义强调真正的神性在于谦卑的美德、同情心和耐心，而非单纯的武力或对神格的追求。在达索瑞恩·拉尔的注视下，新兵必须通过为王国中贫困与弱势者服务...",kw={"cathedral of light","同情心","神性","达索瑞恩·拉尔","圣光","圣骑士","耐心","暴风城","神圣法典"},ang={["class:Paladin"]="《神圣法典》定义了圣骑士使命的道德核心，确立了同情心和耐心与战斗准备同样重要。",["faction:Alliance"]="暴风城的圣骑士构成了联盟的精神和武力中坚，将王国的防御扎根于道德正直和对普通公民的谦卑服务之中。",["race:Human"]="对于暴风城的人类来说，研读这部神圣法典是一项神圣的成人仪式，它加强了公民责任感和对圣光的奉献。"},sec={{t="神性的本质",b="对于走在圣骑士道路上的新兵来说，神性经常被误解。正如《神圣法典》中的神圣文本所解释的那样，努力追求神性并不意味着追求神格或对他人的统治权。相反，圣光呼唤它的勇士们通过纯粹的意图和每一项善行来反映它的恩典。虽然圣骑士无疑受过打击邪恶和在危险时期拿起武器的训练，但没有道德目标的武力是毫无意义的。经文提醒骑士们，真正的尊严来自于他们如何对待艾泽拉斯的普通民众，确保力量始终与正义和谦卑紧密相连。"},{t="同情与耐心的试炼",b="研究神圣经文仅仅是真正服务的序幕。一旦新兵深入研读《神圣法典》，暴风城的达索瑞恩·拉尔就会测试这些教训是否已在候选人的心中和脑海中扎根。圣光的呼唤不仅仅是杀戮野兽；它需要持久的耐心、坚定的勇气和真正的理解。在城市和周围的土地上，总有受苦的公民和那些无法带来荣耀或赞誉的任务。通过前去帮助不幸者并安慰绝望的人，圣骑士证明了他们拥有负责任地运用圣光祝福所需的理智和无私精神。"}},faq={{q="什么是《神圣法典》？",a="《神圣法典》是暴风城的圣骑士所学习的一部神圣指导文本。它教导我们，神性不是关于获得神格或追求个人荣耀，而是关于通过每一个行动中的道德善良、同情心和耐心来反映圣光。",al={"什么是神圣法典","神圣法典任务","圣骑士神圣法典"}},{q="谁是达索瑞恩·拉尔？",a="达索瑞恩·拉尔是位于暴风城内的一位受人尊敬的圣骑士领袖。他监督年轻圣骑士的精神和武力试炼，指导他们研读《神圣法典》，并通过造福王国及其人民的实际任务来考验他们的决心。",al={"谁是达索瑞恩·拉尔","达索瑞恩·拉尔位置","暴风城达索瑞恩·拉尔"}},{q="《神圣法典》强调哪些美德？",a="《神圣法典》教导说，对于神圣战士而言，同情心、耐心和勇气与战斗技巧一样重要。虽然圣骑士必须打击邪恶，但他们真正的崇高来自于无私地帮助弱势群体并反映圣光的仁慈。",al={"圣骑士美德神圣法典","法典教导什么","圣光美德"}},{q="为什么达索瑞恩·拉尔要测试有志成为圣骑士的人？",a="达索瑞恩·拉尔测试新兵是为了确保他们真正领会了《神圣法典》的教义。圣骑士必须证明自己头脑清醒，并有耐心去帮助不幸的人，以此表明他们的奉献植根于服务，而非傲慢。",al={"为什么达索瑞恩测试圣骑士","达索瑞恩·拉尔试炼","圣骑士试炼的目的"}},{q="《神圣法典》教导圣骑士追求神格吗？",a="不，经文明确反对追求神格。它指导圣骑士，努力追求神性意味着努力在所有行动中保持善良，利用圣光赋予的力量去保护和支持他人，而不是将自己凌驾于凡人之上。",al={"圣骑士是否追求神格","圣骑士追求神格","圣骑士神性的含义"}},{q="这个任务在哪里进行？",a="这个任务在人类王国暴风城进行。新兵学习神圣教义并直接向城内的达索瑞恩·拉尔汇报，准备在王国各处街道和周边土地上进行慈善、耐心和勇气的试炼。",al={"神圣法典任务在哪里","神圣法典暴风城位置","神圣法典任务交接处"}},{q="为什么耐心对于圣光圣骑士如此重要？",a="耐心证明了一位神圣战士是有纪律、谦卑且头脑清醒的。圣光的真正仆人必须经常为受压迫者执行谦卑、困难或不起眼的任务，这需要情感上的坚定和真正的共情，而不是仅仅依靠战斗中的侵略性武力。",al={"为什么圣骑士需要耐心","圣光耐心的重要性","圣骑士耐心测试"}}},fp="20,441,22.673.0,33.669.0,29.270.0,22.269.0,49.276.0,47.277.0,57.268.0,33.266.0,56.297.0"}
P.entries["quest:1643"] = {n="圣洁之书",s="The Tome of Divinity 是一项基础的神圣试炼，要求圣光教徒在暴风城寻找并帮助一位心地纯洁、动机高尚的公民。任务引导勇士前往 Trade District 寻找 Stephanie Turner，该任务强调了真正的服务始于对弱势群体的谦卑与慈善。",h="The Tome of Divinity 是一项基础的神圣试炼，要求圣光教徒在暴风城寻找并帮助一位心地纯洁、动机高尚的公民。任务引导勇士前往 Trade District 寻找 Stephanie...",kw={"圣光","铁炉堡","孤儿院","圣骑士","stephanie turner","暴风城","the tome of divinity","tome of divinity","trade district"},ang={["class:Paladin"]="对于学习侍奉圣光的圣骑士来说，这是一项具有决定意义的早期课程，证明了真正的奉献始于谦卑的慈善，而非尚武的光荣。",["faction:Alliance"]="这项任务凸显了暴风城内部的民生挣扎，以及在经济压力下市民们努力支持孤儿院与铁炉堡之间建立的紧密联系。"},sec={{t="谦卑与服务的课程",b="The Tome of Divinity 是圣光修道者的一项重要精神成人礼。在接受关于神圣职责的更深层指导之前，有抱负的侍奉者需要走遍暴风城的街道，寻找一位心存善意、动机纯洁且需要陌生人施以援手的人。这项测试将神圣的誓言根植于对弱势群体的谦卑与细致的服务中，而非仅仅通过光荣的战斗来体现。"},{t="在 Trade District 的援助",b="在暴风城熙熙攘攘的 Trade District，这项职责将受试者引向了 Stephanie Turner。Stephanie 和她的丈夫每天都致力于为居住在城市孤儿院的孩子们手工制作衣物。然而，近期当地商人的激增导致原材料布料和皮革的竞争变得异常激烈，使得这对夫妇难以筹集到捐赠物资。当她的丈夫前往铁炉堡的矮人大厅寻求支援时，Stephanie 留在了暴风城，继续她默默无闻、无私奉献的工作。"}},faq={{q="The Tome of Divinity 试炼的目的是什么？",a="The Tome of Divinity 是圣光圣骑士的一项基础试炼。它不要求战斗技巧或伟大的英雄壮举，而是引导受试者深入暴风城，寻找并帮助一位真正需要援助的善良人士。",al={"the tome of divinity 是什么","the tome of divinity 的目的","为什么要完成 the tome of divinity"}},{q="Stephanie Turner 是谁？",a="Stephanie Turner 是居住在暴风城 Trade District 的一位富有同情心的居民。她不知疲倦地为当地孤儿院的孩子们缝制衣服，依靠布料和皮革的捐赠来让孩子们获得温暖与关怀。",al={"stephanie turner 是谁","stephanie turner 暴风城","stephanie turner 在哪里"}},{q="为什么 Stephanie Turner 的丈夫去了铁炉堡？",a="她的丈夫与她并肩工作，以支持孤儿院的需求。当 Stephanie 在暴风城收集物资并缝制衣服时，她的丈夫前往了北方的铁炉堡，向那里的矮人和侏儒寻求捐赠与援助。",al={"stephanie turner 的丈夫","stephanie 的丈夫是谁","丈夫在铁炉堡"}},{q="Stephanie Turner 面临什么困难？",a="暴风城商人的涌入加剧了对布料和皮革等重要原材料的竞争。由于愿意无偿提供这些资源的人越来越少，Stephanie 发现筹集制作孤儿服装所需材料变得越来越困难。",al={"为什么 stephanie 陷入困境","暴风城布料短缺","孤儿院服装问题"}},{q="为什么这个试炼专门引导受试者去寻找 Stephanie Turner？",a="该试炼要求圣光受试者寻找一位怀有高尚意图、纯洁动机且真正需要指引的人。Stephanie Turner 体现了对他人的无私奉献，这使她成为了圣光侍奉者寻求帮助的理想人选。",al={"为什么要帮助 stephanie turner","为什么任务让你去找 stephanie"}},{q="这个试炼向圣光的侍奉者传授了什么课程？",a="该试炼教导人们，走上圣光之路需要同情心、无私奉献以及对弱势群体的服务。在战斗中挥舞圣光力量之前，圣光勇士必须首先理解对有需要的普通市民施以善意的责任。",al={"圣光在这里教导了什么","the tome of divinity 的课程"}}},fp="20,311,32.438.0,25.536.0,50.272.0,24.256.0,53.245.0,45.280.0,70.265.0,60.259.0"}
P.entries["quest:1644"] = {n="圣洁之书",s="《神圣之书》是暴风城中一个圣骑士任务，任务要求受训者为斯蒂芬妮·特纳（Stephanie Turner）提供亚麻布。斯蒂芬妮是一位照看天灾军团遗孤的看护人。通过在她的丈夫前往铁炉堡搜集补给期间协助她为孩子们缝制衣物，这个任务展示了圣骑士至关重要的美德：无私的慈善。",h="《神圣之书》是暴风城中一个圣骑士任务，任务要求受训者为斯蒂芬妮·特纳（Stephanie...",kw={"慈善","约翰·特纳","亚麻布","孤儿","圣骑士","天灾军团","斯蒂芬妮·特纳","暴风城","神圣之书"},ang={["class:Paladin"]="作为《神圣之书》相关试炼的一部分，在暴风城关怀弱势群体并提供无私的慈善，考验着圣骑士对仁慈和圣光的虔诚。",["faction:Alliance"]="暴风城战争孤儿的困境凸显了近期天灾军团袭击北方联盟领土所造成的人力代价。",["profession:Tailoring"]="斯蒂芬妮·特纳使用简单的亚麻布卷为她照顾的孤儿缝制必需的衬衫和裤子。"},sec={{t="战争孤儿",b="在暴风城熙熙攘攘的街道上，斯蒂芬妮·特纳照料着一群孩子。过去十年里，天灾军团在北方大地造成的毁灭让这些孩子失去了家人。在她的丈夫约翰外出搜集物资时，斯蒂芬妮独自承担着让孩子们吃饱、穿暖并有栖身之所的日常重担。甚至连清洁衣物这种基本需求，都需要耗费她极难抽出的时间和精力。"},{t="仁慈的试炼",b="想要掌握《神圣之书》课程的圣骑士候选人，被要求展现无私的慈善，而非武力。通过将亚麻布卷交给斯蒂芬妮，受训者卸下了她肩头的一份重担，让她能腾出手来为孩子们缝制衬衫和裤子，从而能继续专注于为他们提供住所和食物。通过这种谦卑的援助，圣光的守护者证明了他们守护弱小的奉献精神。"},{t="首都的重负",b="尽管斯蒂芬妮坚持应对日常的艰难困苦，但她提到今年日子过得格外艰难。由于她的丈夫被迫长途跋涉，远赴铁炉堡搜集补给，普通民众所承受的压力反映出整个王国更广泛的不安。即使身处首都高耸的石墙内，北方近期悲剧带来的阴影依然挥之不去。"}},faq={{q="斯蒂芬妮·特纳是谁？",a="斯蒂芬妮·特纳是一位住在暴风城的充满同情心的女性，她毕生致力于照顾被天灾军团遗弃的孤儿。她不辞辛劳地为孩子们提供食物、衣物和住所，并严重依赖社区的慈善捐助以及她丈夫约翰的努力。",al={"斯蒂芬妮·特纳是谁","斯蒂芬妮·特纳 暴风城","孤儿院看护人"}},{q="为什么斯蒂芬妮·特纳需要亚麻布？",a="斯蒂芬妮需要亚麻布来为孤儿们缝制衬衫和裤子。她忙于寻找食物和维持孩子们的住所，有人提供现成的布料可以让她免去亲自搜集材料的时间和压力。",al={"为什么需要亚麻布","亚麻布的用途","给斯蒂芬妮的布料"}},{q="约翰是谁，他去了哪里？",a="约翰是斯蒂芬妮·特纳的丈夫。他离开暴风城去收集必需的物资和材料，甚至远赴矮人城市铁炉堡，尽管他并不喜欢远离家人的时光。",al={"约翰是谁","约翰在哪里","斯蒂芬妮·特纳的丈夫"}},{q="为什么暴风城有这么多孤儿？",a="在斯蒂芬妮照顾的孩子中，大多数人的家人都在过去十年里天灾军团对北方王国发动的毁灭性袭击中丧生。流离失所的难民和幸存者将许多失去双亲的年轻人带到了南方的暴风城。",al={"为什么暴风城有孤儿","天灾军团孤儿 暴风城","孩子们父母的遭遇"}},{q="帮助斯蒂芬妮与《神圣之书》有什么联系？",a="《神圣之书》考验着圣骑士候选人的核心美德，其中最重要的是慈善与仁慈。帮助一位负担过重的看护人提供基本物资，证明了圣光的仆人既能像面对怪物一样战斗，也能同样乐于保护谦卑者。",al={"《神圣之书》的含义","为什么这是圣骑士任务","圣骑士慈善任务"}},{q="斯蒂芬妮提到的“空气中弥漫着异样”是什么意思？",a="斯蒂芬妮提到今年感觉比往年艰难得多，仿佛空气中有什么东西预示着巨大的变化，尽管她承认自己说不上来具体是什么。",al={"暴风城的艰难岁月","空气中弥漫着异样","暴风城的困境"}}},fp="20,327,18.448.0,21.462.0,22.412.0,24.262.0,43.231.0,34.216.0,53.243.0,58.259.0,54.160.0"}
P.entries["quest:1645"] = {n="圣洁之书*",s="神圣之书标志着矮人圣骑士在铁炉堡训练中的一个重要里程碑。这本神圣的经文由位于Hall of Mysteries的蒂萨·热炉赠予，开启了一段以试炼为基础的旅程，旨在考验初学者对圣光的虔诚，以及他们抵御诸如天灾军团等黑暗势力保卫艾泽拉斯的准备程度。",h="神圣之书标志着矮人圣骑士在铁炉堡训练中的一个重要里程碑。这本神圣的经文由位于Hall of...",kw={"神圣之书","hall of mysteries","圣光","铁炉堡","圣骑士","救赎","天灾军团","蒂萨·热炉"},ang={["class:Paladin"]="这个通过仪式将早期的武艺指导与圣光更深层的美德联系起来，引导初学者走上能够引导救赎和复活之力的道路。",["race:Dwarf"]="对于矮人勇士来说，接受神圣之书巩固了铜须王国与白银之手人类骑士之间建立的信仰联盟。"},sec={{t="美德的召唤",b="当初学者证明自己掌握了武艺和精神的基础后，东部王国的圣骑士导师们会指引他们前往铁炉堡的Hall of Mysteries。在蒂萨·热炉的注视下，年轻的矮人圣骑士们开始接触庄严的准则，这些准则将普通的战士与受命的圣光勇士区分开来。接受这项任务代表着对自己一生自我牺牲、责任和精神纪律的自觉誓约。"},{t="神圣之书",b="接受此项指引后，初学者便会获得一本神圣之书。该书概述了有效运用神圣能量对抗邪恶威胁所需的期望、美德和精神教义。研读其中的教诲仅仅是入门步骤；在初学者被派往卡兹莫丹及更远的地方，并通过实际的信仰行为来体现这些课程之前，这本经文起到了基础指南的作用。"}},faq={{q="神圣之书任务的目的是什么？",a="该任务是矮人勇士进阶圣骑士训练的门户。通过与蒂萨·热炉交谈，初学者将获得他们的神圣经文，并开始一系列旨在证明其美德并解锁复活已故盟友能力的试炼。",al={"神圣之书的作用","神圣之书的目标","为什么要完成这个任务"}},{q="谁是蒂萨·热炉？",a="蒂萨·热炉是一位杰出的圣骑士训练师，居住在铁炉堡的Hall of Mysteries。她的职责是引导矮人圣骑士走向更高的美德，考验他们对圣光的虔诚，并让他们做好准备去面对诸如天灾军团之类的威胁。",al={"蒂萨·热炉","铁炉堡的圣骑士训练师是谁","谁给予神圣之书"}},{q="为什么初学者必须研读神圣之书？",a="神圣之书中包含了圣光所要求的职责和美德的核心教义。研读它能确保初学者在运用神圣的神奇力量之前，理解所需的精神纪律。",al={"什么是神圣之书","为什么要阅读该书","神圣之书背景故事"}},{q="矮人圣骑士正在准备对抗哪些重大威胁？",a="正如蒂萨·热炉所概述的那样，圣骑士们致力于保卫艾泽拉斯，抵御遍布这片土地的危险灾难，并特别警惕不断逼近的天灾军团的亡灵威胁。",al={"圣骑士对抗谁","为什么要进行铁炉堡圣骑士训练","圣骑士的目标"}},{q="这项训练在何处进行？",a="入门仪式始于Hall of Mysteries，这是位于铁炉堡北部区域的一个安静的避难所，学者、牧师、法师和圣骑士们聚集于此祈祷和学习。",al={"蒂萨·热炉在哪里","铁炉堡圣骑士位置","hall of mysteries圣骑士"}},{q="拿到书之后接下来该做什么？",a="一旦初学者阅读并思考了神圣之书，蒂萨·热炉就会发布实践试炼，要求圣骑士在城市大门的安全范围之外展示慈悲、责任和牺牲精神。",al={"接下来会发生什么","神圣之书后续任务","拿到书后去哪里"}}},fx={b6d4c081={q="蒂萨·热炉为什么想让你研读《神圣之书》？",a="蒂萨·热炉负责铁炉堡圣骑士的训练。她认为引导新晋圣骑士走向真正的美德、虔诚信仰，是自己庄严的职责。天灾军团与其他威胁正逼近艾泽拉斯，她希望确保自己训练的每一位守护者都明白自身的精神职责，并做好准备，在保卫王国时运用更强大的圣光力量。",al={"蒂萨为什么想让你完成这件事","蒂萨·热炉的动机","为什么研读《神圣之书》"}},a71115f0={q="蒂萨·热炉为什么让你接受这场试炼，而不是亲自处理？",a="蒂萨无法代替你走上美德之路。作为圣光的导师，她的职责是引导和教诲，但真正的圣骑士所需的虔诚、理解与内在力量，必须由受训者自己具备。若想获得圣光的祝福与能力，你必须通过研习和服务，亲自证明自己的能力与奉献精神。",al={"为什么让我研读《神圣之书》","蒂萨为什么不亲自做","为什么我必须研读这本书"}}},fp="20,325,19.469.0,20.423.0,50.272.0,24.259.0,46.230.0,59.213.0,36.186.0,41.215.0"}
P.entries["quest:1646"] = {n="圣洁之书",s="《神圣之书》是一项基础的圣骑士任务，其核心在于指引圣光战士的精神美德。该任务由铁炉堡的导师（例如蒂萨·热炉）发布，它教导初学者：对圣光的真正虔诚，除了需要武力之外，还需要耐心、同情心以及对弱者谦卑的服务。",h="《神圣之书》是一项基础的圣骑士任务，其核心在于指引圣光战士的精神美德。该任务由铁炉堡的导师（例如蒂萨·热炉）发布，它教导初学者：对圣光的真正虔诚，除了需要武力之外，还需要耐心、同情心以及对弱者谦卑的服务。",kw={"同情心","圣光","铁炉堡","圣骑士","耐心","神圣之书","蒂萨·热炉"},ang={["class:Paladin"]="《神圣之书》向年轻的圣骑士介绍了他们职业的基础信条，强调同情心与服务与武艺同等重要。",["race:Dwarf"]="铁炉堡的矮人圣骑士通过像蒂萨·热炉这样的导师接受这些指导，以确保他们的力量能得到耐心与美德的引导。"},sec={{t="神圣的准则",b="《神圣之书》代表了圣骑士训练中的一个重要里程碑。通过铁炉堡的导师（例如蒂萨·热炉）传授，该文本为初学者奠定了他们武力背后的精神宗旨。书中教导说，真正的神圣在于追求道德上的善，并作为圣光坚定的工具，而不是美化统治权或神格。"},{t="服务与同情的考验",b="虽然圣光的战士经常被召唤去惩戒艾泽拉斯各地的邪恶，但该书强调仅靠武力并不能定义一名圣骑士。同情心、耐心和谦卑使他们区别于普通的战士。研读该文本后，初学者会被指引去完成遍布铁炉堡及其周边地区的考验，通过慈善与服务行为来证明他们健全的头脑和坚定不移的奉献精神。"}},faq={{q="什么是《神圣之书》？",a="《神圣之书》是提供给新手圣骑士的核心指导文本。它教导说，神圣并非追求神格，而是努力向善，帮助不幸者，并体现同情心、耐心与勇敢。",al={"什么是神圣之书","神圣之书圣骑士","这本书教导什么"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位位于铁炉堡的圣骑士导师，她引导新手完成最初的考验，确保他们理解公正的战斗与无私的服务之间的平衡。",al={"谁是蒂萨·热炉","蒂萨·热炉位置","蒂萨在哪里"}},{q="为什么圣骑士必须学习耐心与同情心？",a="圣骑士的力量源于对圣光的映射，这需要健全的品格与道德修养。若没有保护和提升他人所需的耐心与同情心，仅有战斗力是不够的。",al={"为什么阅读神圣之书","圣骑士美德","为什么需要耐心与同情心"}},{q="阅读这本书后会有什么测试？",a="阅读文本后，圣骑士必须通过实践测试来证明他们的美德。导师会指派他们去城市及周边地区完成任务，以帮助那些有需要的人并证明他们对圣光的奉献。",al={"阅读这本书后会发生什么","神圣之书考验","阅读后的下一个考验"}},{q="这项考验在哪里进行？",a="该任务指引圣骑士在研读完书中教义后，回到矮人主城铁炉堡向蒂萨·热炉复命。",al={"这个任务在哪里交","铁炉堡圣骑士任务"}},{q="追求神圣意味着什么？",a="根据文本，追求神圣并不意味着渴望成为神。相反，它意味着在所有行动中主动选择善良，并运用圣光来支持和保护艾泽拉斯的人民。",al={"追求神圣意味着什么","圣骑士神格"}}},fp="20,318,23.392.0,32.429.0,29.229.0,24.190.0,48.216.0,35.213.0,33.142.0,41.207.0"}
P.entries["quest:1647"] = {n="圣洁之书",s="《圣洁之书》是铁炉堡的圣光初学者所经历的一项早期神圣试炼。在城中神殿导师的指引下，受试者必须前往外环搜寻一位心地纯良且确实需要帮助的人。找到勤恳的劳工John Turner后，初学者们将明白无私奉献与同情心是践行圣光之道的核心。",h="《圣洁之书》是铁炉堡的圣光初学者所经历的一项早期神圣试炼。在城中神殿导师的指引下，受试者必须前往外环搜寻一位心地纯良且确实需要帮助的人。找到勤恳的劳工John...",kw={"铁炉堡","john turner","圣光","孤儿院","圣骑士","神殿","圣洁之书"},ang={["class:Paladin"]="该任务代表了践行圣光之道的一项必要试炼，教导圣骑士真正的奉献始于无私地帮助有需要的普通民众。",["faction:Alliance"]="该任务强调了维系联盟的美德——在像铁炉堡这样的城市中，对弱势群体的同情、慈善与关怀。",["race:Dwarf"]="这项试炼发生在矮人主城铁炉堡，旨在测试当地的矮人圣光门徒在他们家园大厅中的修行。"},sec={{t="同情心的一课",b="《圣洁之书》是驻扎在铁炉堡的圣光初学者的一项基础试炼。导师并未要求他们测试战斗技巧或对抗敌人，而是命令他们深入繁忙的矮人城市，寻找一个真正需要帮助的人。这项任务考验洞察力：受试者必须找到一位拥有纯洁心灵、高尚意图且真正依赖他人善意的人，以此证明谦卑的服务是他们神圣使命的基础。"},{t="John Turner的重担",b="搜寻过程将门徒们引向了铁炉堡的外环，那里有一位名叫John Turner的谦卑工人在从事他的工作。他在呼喊关于暴风城孤儿院的事宜时被访客吓了一跳，随后Turner道出了他日常生活中默默奉献的真相。因为无尽的劳作而与挚爱的妻子分离，他忍受着漫长的工作时间，只为确保孤儿们有衣穿、有饭吃。通过帮助Turner，初学者们在回到神殿继续他们的圣光之旅前，发现了仁慈的真正分量。"}},faq={{q="《圣洁之书》任务是什么？",a="《圣洁之书》是铁炉堡的圣光追随者们所进行的一项神圣试炼。它要求受试者在城市中寻找并帮助一位心地纯良、动机高尚的人，之后方能继续他们的精神教导。",al={"什么是圣洁之书","圣洁之书的目的","这是什么任务"}},{q="John Turner是谁？",a="John Turner是一位在铁炉堡外环辛勤工作的男人。他为了筹集资源，不辞辛劳地远离挚爱的妻子，努力为贫困的孤儿提供食物和衣物。",al={"john turner是谁","铁炉堡的john turner","john turner在哪里"}},{q="导师为什么要派你去寻找需要帮助的人？",a="该试炼旨在测试初学者对同情心与服务的理解。圣光的仆人无需对抗怪物，而是必须首先学会识别高尚的意图，施予善意，并指引那些为了他人的利益而默默劳作的人。",al={"为什么要寻找需要帮助的人","帮助john turner的目的","为什么要进行这项测试"}},{q="John Turner在铁炉堡的什么位置？",a="你可以在铁炉堡的外环找到John Turner，他正在那里为孤儿院进行繁重的日常工作。",al={"在哪里可以找到john turner","john turner的位置","如何找到john turner"}},{q="与John Turner交谈后会发生什么？",a="在找到John Turner并了解了他的处境后，你将回到神殿的导师身边，反思追随圣光之道真正的含义，并为你的使命的The Next Step做好准备。",al={"找到john turner后会发生什么","回到圣光神殿","圣洁之书的后续步骤"}},{q="John Turner为什么要大喊关于孤儿院的事？",a="刚被接近时，John Turner大声谈论着暴风城孤儿院，随后意识到失态并道歉。他的工作致力于支持那些依靠慈善来获取食物和衣物的孤儿。",al={"john turner喊的是哪家孤儿院","铁炉堡的暴风城孤儿院","john turner为什么要大喊"}}},fp="20,369,22.515.0,25.541.0,35.249.0,19.183.0,53.242.0,42.131.0,45.202.0,48.224.0"}
P.entries["quest:1648"] = {n="圣洁之书",s="《圣光的召唤》要求圣光的仆从们在铁炉堡行一善举，以彰显谦卑与慈悲。协助负责暴风城孤儿院的约翰·特纳，这位孤儿院收留着因天灾军团而流离失所的孩子。这对初学者而言，是考验其是否能将无私与仁爱置于武力荣耀之上的试炼。",h="《圣光的召唤》要求圣光的仆从们在铁炉堡行一善举，以彰显谦卑与慈悲。协助负责暴风城孤儿院的约翰·特纳，这位孤儿院收留着因天灾军团而流离失所的孩子。这对初学者而言，是考验其是否能将无私与仁爱置于武力荣耀之上的试炼。",kw={"圣光","铁炉堡","约翰·特纳","亚麻布","圣骑士","天灾孤儿","暴风城孤儿院","圣光的召唤"},ang={["class:Paladin"]="圣骑士进行这项试炼并非依靠钢铁与战斗技巧，而是通过向无辜者提供无私的援助，体现了圣光核心中慈悲的美德。",["faction:Alliance"]="这项差事揭示了天灾军团在人类社会留下的深刻创伤，也展现了暴风城与铁炉堡之间相互依赖的关系。"},sec={{t="大工匠之地的慈善",b="《圣光的召唤》不仅是一本圣典，它还向行走在圣光之道的初学者们呈现了一场试炼，一场无关武力，只关乎慈悲的试炼。在铁炉堡繁忙的大厅中，一位名为约翰·特纳的仁慈使者正在寻求帮助。特纳和他的妻子在暴风城王国经营着一家孤儿院，照料着在过去十年里因天灾军团的灾难性浩劫而失去双亲的孤儿。他前往矮人首都的旅程，反映了联盟普通民众所经历的共同苦难。"},{t="天灾军团的创伤",b="跨越边境搜集物资绝非易事。随着艾泽拉斯各地工匠的大量涌入，当地供应链承受了巨大压力，导致基础材料变得匮乏。特纳前往铁炉堡向民间团体和市民寻求帮助的行程在数周内进展缓慢，这使得他无法获得妻子为孩子们缝制衣物所需的亚麻布。通过在不求回报的情况下主动提供这些亚麻布，圣光的仆从们展现出了圣光信仰根基中那无私奉献的精神。"}},faq={{q="约翰·特纳是谁？",a="约翰·特纳是一位人类照料者，他和妻子在暴风城经营着一家孤儿院。他大约每月会前往一次铁炉堡，向矮人市民和商会寻求捐赠与物资，以支持那些因战争而失去父母的孤儿。",al={"约翰·特纳是谁","约翰·特纳背景故事","铁炉堡特纳"}},{q="约翰·特纳为什么需要亚麻布？",a="特纳需要亚麻布，以便他在暴风城的妻子能为孤儿们缝制保暖的衣物。由于工匠的涌入和艾泽拉斯各地贸易格局的改变，基础布料变得十分稀缺，难以获得。",al={"为何需要亚麻布","约翰·特纳为什么需要布料","孤儿院的亚麻布"}},{q="为什么暴风城有这么多孤儿？",a="特纳夫妇照顾的孩子们是在过去十年里，因亡灵天灾军团的毁灭性攻击而失去了父母。第三次战争使得人类王国中许多家庭破碎，导致许多青少年无家可归。",al={"暴风城孤儿院的孤儿","为什么会有孤儿","天灾孤儿"}},{q="约翰·特纳为什么要前往铁炉堡？",a="特纳翻山越岭来到铁炉堡，向矮人市民和各贸易团体恳求捐助和物资，这些物资在暴风城很难筹集到。",al={"约翰·特纳为什么在铁炉堡","为什么为暴风城孤儿院求助铁炉堡"}},{q="帮助孤儿院与圣光有何联系？",a="圣光要求无私、仁慈，并服务于那些绝望之人。协助一位精疲力竭的照料者抚养战争孤儿，对于圣骑士的准信徒而言，是对其谦卑与慈悲的考验，而非对其武力强弱的展示。",al={"这与圣光有何关系","圣骑士联系","为什么圣骑士要做这个任务"}},{q="为什么约翰·特纳的铁炉堡之行如此艰难？",a="特纳的此行极其缓慢且几乎毫无进展，因为当地物资紧缺，鲜有团体伸出援手，导致他在筹集到足够的一批物资前无法返回家中。",al={"约翰·特纳被困住了吗","为什么行程缓慢"}}},fp="20,282,26.481.0,24.530.0,19.240.0,38.230.0,43.236.0,40.183.0,55.239.0,58.218.0"}
P.entries["quest:1649"] = {n="勇气之书",s="勇气之书是圣光大教堂内圣骑士们晋升之路上一项神圣的过渡试炼。在圣典和资深导师的指引下，申请者们会前往暴风城寻找达索瑞恩·拉尔，以证明他们对教会美德拥有坚定不移的信仰、勇气和奉献精神。",h="勇气之书是圣光大教堂内圣骑士们晋升之路上一项神圣的过渡试炼。在圣典和资深导师的指引下，申请者们会前往暴风城寻找达索瑞恩·拉尔，以证明他们对教会美德拥有坚定不移的信仰、勇气和奉献精神。",kw={"cathedral of light","圣光教会","达索瑞恩·拉尔","信仰","圣骑士","暴风城","勇气之书","勇气"},ang={["class:Paladin"]="这项试炼是圣骑士成长道路上决定性的一步，证明了正直的武勇必须以严明的信仰和无私的服务为基础。",["faction:Alliance"]="在暴风城进行的试炼有助于在动荡时期维持联盟防御和精神力量的核心。"},sec={{t="磨砺精神",b="在圣光的传统中，勇气并非一种可以独自保持纯粹的天生特质。《勇气之书》这本神圣典籍将美德比作珍贵却未经提炼的矿石：被发现时固然宝贵，但仍需仔细冶炼和精炼才能经受住磨难。唯有通过艰苦的考验和真正的承诺，圣骑士才能将信仰、同情心和勇气熔炼为一种足以抵御威胁艾泽拉斯最黑暗邪恶的合金。"},{t="向教会请愿",b="在领悟了《勇气之书》中的智慧后，圣骑士会受命前往达索瑞恩·拉尔处，他是聚集在暴风城圣光大教堂中的圣骑士里备受尊崇的领袖。达索瑞恩担任那些申请接受勇气试炼之人的仲裁者。他告诫申请者，前方的考验绝非儿戏：保卫无辜者和维护教会尊严需要做好牺牲生命的准备，确保只有真正坚定不移的人才能获得教团的认可。"}},faq={{q="这个任务的目的是什么？",a="这项任务是连接新手对圣光教义的基础学习与实际、危险的试炼之间的桥梁。在研读《勇气之书》后，有志成为圣骑士的人会向圣光大教堂的达索瑞恩·拉尔展示自己，并请愿接受真正的信仰与勇气测试。",al={"什么是勇气之书任务","我为什么需要这个任务","勇气之书的目的"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是一位驻扎在暴风城圣光大教堂内的高阶圣骑士和导师。他负责监督有前途的保卫者的成长，并主持严格的试炼，以证明新手在教会面前的价值。",al={"谁是达索瑞恩·拉尔","达索瑞恩·拉尔背景故事","大教堂圣骑士训练师"}},{q="教会为什么要如此严厉地测试圣骑士？",a="圣光教会期望其圣骑士成为抵御绝望与暴力的坚固堡垒。意志薄弱或信仰不坚定可能会在战场上付出生命的代价，因此导师们会确保新手的精神在执行关键的神圣任务前得到充分的磨砺与考验。",al={"为什么圣骑士试炼很危险","为什么要测试勇气"}},{q="这项试炼在哪里进行？",a="新手会将他们的请愿书直接交给位于暴风城Cathedral Square中心的圣光大教堂内的达索瑞恩·拉尔。",al={"去哪里上交勇气之书","达索瑞恩·拉尔位置"}}},fp="17,168,20.325.0,22.354.0,34.197.0,22.196.0,50.230.0,33.120.0"}
P.entries["quest:165"] = {n="隐士",s="由于一位年迈的隐士长时间没有露面，夜色镇的艾莱尼·卡尔文委托路人去看看他。这位孤独的老人亚伯克隆比住在一间摇摇欲坠的小屋里，那地方就位于乌鸦岭墓地的边缘。",h="由于一位年迈的隐士长时间没有露面，夜色镇的艾莱尼·卡尔文委托路人去看看他。这位孤独的老人亚伯克隆比住在一间摇摇欲坠的小屋里，那地方就位于乌鸦岭墓地的边缘。",kw={"亚伯克隆比","夜色镇","暮色森林","艾莱尼·卡尔文","乌鸦岭墓地","小屋","隐士"},ang={["faction:Alliance"]="守夜人一直在努力保护夜色镇和乌鸦岭之间的道路，这使得像亚伯克隆比这样的偏远隐士完全与城镇的安全隔绝开来。",["race:Human"]="卡尔文家族体现了暮色森林中持久的邻里纽带，即使在他们的家园陷入阴影时，依然关照着社区里古怪的长者。"},sec={{t="邻里的问候",b="在像夜色镇这样饱受困扰的定居点，人们很容易忽略那些古怪的独居者，直到他们长时间没有露面引起了担忧。艾莱尼·卡尔文回忆起有位老人过去常来镇上采买补给，但最近却突然消失了踪影。考虑到暮色森林的道路上徘徊着无尽的危险，她指引过往的冒险者前往他那座俯瞰着闹鬼的乌鸦岭墓地的小屋，确认他是否遭遇了不幸。"},{t="乌鸦岭的隐士",b="到达那间偏僻的小屋后，你发现住在那里的老人——亚伯克隆比，依然还活着。听到提起卡尔文一家时，他轻声笑了笑，声称自己长时间没露面仅仅是因为年事已高，再加上森林里到处都是阴险的怪物。发现家门口来了一位有能力的旅行者，亚伯克隆比毫不耽搁，立刻询问他们是否愿意为他跑几趟腿，帮他做些杂事。"}},faq={{q="谁发起了这个差事？",a="位于暮色森林夜色镇的居民艾莱尼·卡尔文，因为担心过去常来镇上购买补给的一位老隐士，从而开启了这项任务。",al={"谁给隐士任务","从哪里开始隐士任务","艾莱尼·卡尔文任务"}},{q="隐士住在哪里？",a="亚伯克隆比住在一间破旧的木屋里，位于暮色森林西部的乌鸦岭墓地北侧边缘。",al={"亚伯克隆比在哪里","暮色森林隐士位置","乌鸦岭附近的小屋"}},{q="为什么艾莱尼·卡尔文会担心他？",a="亚伯克隆比过去常来夜色镇购买补给，但后来完全不再出现了。由于道路上徘徊着野兽和亡灵，她担心他可能已经遭遇了不测。",al={"为什么去检查亚伯克隆比","为什么艾莱尼会担心","老人发生了什么事"}},{q="当你找到亚伯克隆比时，他真的有危险吗？",a="没有。当你到达他的小屋时，亚伯克隆比活得好好的，而且对镇上居民的关心感到一丝好笑，解释说是因为危险的道路和他年迈的身体让他出行变得非常困难。",al={"亚伯克隆比还好吗","隐士快死了吗","隐士有没有受到攻击"}},{q="为什么有人会选择住在乌鸦岭墓地旁边？",a="亚伯克隆比声称自己更喜欢清静，尽管住在东部王国最受死灵法术腐蚀的墓地之一的阴影下，对许多旅行者来说是一件令人不安的事。",al={"为什么住在乌鸦岭旁边","亚伯克隆比墓地小屋","为什么隐士在墓地附近"}},{q="当你找到亚伯克隆比后，他提出了什么要求？",a="亚伯克隆比急于利用送上门来的一位身强力壮的冒险者，立即请求他们协助完成他在森林周围的各种跑腿和任务。",al={"亚伯克隆比想要什么","隐士后续任务","隐士之后还有什么"}}},fx={e8a34d53={q="艾莱尼·卡尔文为什么让冒险者去看看亚伯克隆比？",a="夜色镇当地的守夜人已经人手严重不足，正竭力守住外围，抵御凶残的野兽、狂暴的狼人和不安的亡者。镇卫无暇深入西部森林，前往乌鸦岭查看一位古怪隐士的情况，因此能干的旅人是他们唯一切实可行的选择。",al={"为什么派我去","艾莱尼为什么需要冒险者","为什么卫兵不去看看隐士"}}},fp="10,225,21.461.0,25.419.0,23.140.0,28.125.0,41.179.0,52.190.0,66.189.0,49.174.0"}
P.entries["quest:1650"] = {n="勇气之书",s="这个任务代表了圣骑士在追求勇气之书过程中的第二个试炼。达索瑞恩·拉尔派遣骑士前往遥远的西部荒野海岸，去保护达芙妮·斯迪威尔，她是一位隐居的宅基地主，很容易受到周围迪菲亚潜行者的伤害。",h="这个任务代表了圣骑士在追求勇气之书过程中的第二个试炼。达索瑞恩·拉尔派遣骑士前往遥远的西部荒野海岸，去保护达芙妮·斯迪威尔，她是一位隐居的宅基地主，很容易受到周围迪菲亚潜行者的伤害。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","达索瑞恩·拉尔","乔丹·斯迪威尔","长滩","暴风城","勇气之书","西部荒野"},ang={["class:Paladin"]="这项任务构成了年轻圣骑士的核心成年礼，要求他们离开暴风城大教堂的安全环境，通过守卫无助者来证明他们的勇气。",["faction:Alliance"]="斯迪威尔宅基地的困境突显了西部荒野已经偏离了暴风城的直接保护有多远，让农村公民只能独自抵御迪菲亚潜行者。"},sec={{t="召唤武装",b="在圣光大教堂内，达索瑞恩·拉尔不仅通过经文或独自祈祷来考验有抱负的圣骑士，更通过直接保卫王国人民来考验他们。一旦接受了勇气的重任，圣骑士们就会立即被要求在权威和法律崩溃的地方将理想付诸实践。"},{t="长滩的危险",b="目的地是西部荒野偏远的长滩，达芙妮·斯迪威尔和她的丈夫乔丹在那里维持着一个靠海的前哨站。由于乔丹前往铁炉堡咨询矮人铁匠，达芙妮在迪菲亚潜行者横行的情况下独自留了下来。达索瑞恩命令圣骑士向西骑行，并在窃贼淹没她那孤零零的宅基地之前充当她的盾牌。"}},faq={{q="为什么达芙妮·斯迪威尔独自在西部荒野？",a="她的丈夫乔丹·斯迪威尔是一位著名的铁匠，他前往矮人王国铁炉堡去咨询同行。他的离开导致达芙妮在日益增长的迪菲亚攻击中只能孤身一人保卫他们的沿海财产。",al={"达芙妮的丈夫在哪里","为什么乔丹·斯迪威尔离开了","达芙妮·斯迪威尔独自一人"}},{q="是谁将这个任务分配给圣骑士的？",a="达索瑞恩·拉尔，暴风城圣光大教堂内的一位首席圣骑士训练师和导师，一旦你证明自己准备好接受勇气的试炼，他就会下达这个命令。",al={"谁发布了勇气之书1650任务","勇气之书任务发布者","达索瑞恩·拉尔任务"}},{q="在哪里可以找到达芙妮·斯迪威尔？",a="她住在长滩最南端的一间小屋里，位于西部荒野的西南部海岸线上。",al={"达芙妮·斯迪威尔在哪里","达芙妮·斯迪威尔位置","找到达芙妮·斯迪威尔"}},{q="当你到达时，达芙妮完全无助吗？",a="一点也不。当圣骑士到达她的门廊时，达芙妮已经亲手用自己的武器解决了半打迪菲亚潜行者，同时守住了宅基地。",al={"达芙妮能战斗吗","达芙妮无助吗","达芙妮·斯迪威尔战斗中"}},{q="是什么威胁在困扰斯迪威尔的家？",a="迪菲亚潜行者已经占领了西部荒野的大部分地区，并不断骚扰这个偏远的沿海宅基地，试图夺取土地并掠夺剩余的物资。",al={"谁在攻击达芙妮","西部荒野的迪菲亚潜行者","斯迪威尔农场的敌人"}},{q="这个任务如何融入勇气之书系列？",a="圣骑士传统中的勇气是通过主动牺牲和保卫弱者来衡量的。站在达芙妮和掠夺成性的强盗之间，提供了正义在行动中的实际证明。",al={"为什么我要帮助达芙妮","勇气之书试炼目的","该任务的含义"}}},fp="17,148,14.221.0,22.280.0,41.169.0,37.145.0,35.104.0,46.141.0,42.200.0,52.149.0"}
P.entries["quest:1651"] = {n="勇气之书",s="这是一项针对圣骑士培养的关键试炼，要求防守达芙妮·斯迪威尔的家园，抵御一次有组织的迪菲亚潜行者突袭。在西部荒野开阔的田野上，面对众多的敌人，圣骑士必须坚守阵线，以体现勇气这一核心信条。",h="这是一项针对圣骑士培养的关键试炼，要求防守达芙妮·斯迪威尔的家园，抵御一次有组织的迪菲亚潜行者突袭。在西部荒野开阔的田野上，面对众多的敌人，圣骑士必须坚守阵线，以体现勇气这一核心信条。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","迪菲亚强盗","圣骑士试炼","勇气之书","西部荒野"},ang={["class:Paladin"]="这场战斗考验你作为不屈守护者的角色。站在达芙妮身边坚守阵线展示了勇气这一核心美德，表明圣光战士存在的首要意义就是保护无辜者免受伤害。",["faction:Alliance"]="由于暴风城的驻军兵力不足，无法保卫乡村家园，保卫西部荒野忠诚公民的任务就完全落在了各位英雄的肩上。"},sec={{t="尘土中的坚守",b="在追寻《勇气之书》中所记载的美德时，圣骑士会接到指引，前往西部荒野达芙妮·斯迪威尔那座饱受战火的家园。这座农场位于迪菲亚潜行者争夺的领土中心，他们曾多次试图占领这处房产并除掉达芙妮。由于早先的冲突，守卫者知道报复性打击迫在眉睫，因此必须坚守在她的屋旁，而不是撤退到更安全的地方。"},{t="勇气试炼",b="达芙妮和圣骑士仅依靠她个人的火枪以及圣光所能提供的祝福，面对一波又一波迪菲亚潜行者的突袭。不同于单打独斗，这次试炼考验的是守护者在重压之下保护弱小的能力。抵御住这次猛攻证明了真正的勇气不仅仅是追求个人荣耀，更是为了在无辜平民与残酷暴力之间挺身而出。"}},faq={{q="达芙妮·斯迪威尔是谁？",a="达芙妮·斯迪威尔是一位居住在西部荒野草原上的坚韧人类农夫。尽管迪菲亚潜行者不断侵扰，她仍拒绝放弃自己的土地，并积极反击强盗的突袭。",al={"达芙妮·斯迪威尔","达芙妮是谁","斯迪威尔西部荒野"}},{q="迪菲亚潜行者为什么要袭击这个特定的农场？",a="迪菲亚潜行者已经基本控制了西部荒野的乡村，驱逐或奴役了当地农夫。由于她的丈夫Jordan远在铁炉堡，达芙妮孤立无援，而迪菲亚潜行者想要夺取她的土地。",al={"为什么迪菲亚攻击","迪菲亚突袭达芙妮","为什么要攻击斯迪威尔"}},{q="《勇气之书》是什么？",a="《勇气之书》是圣光教会用来指导年轻圣骑士的神圣指导文本。受训骑士们在王国各地进行身体和精神上的试炼，以体现书中记载的美德。",al={"什么是勇气之书","勇气之书任务","圣骑士勇气之书"}},{q="如果达芙妮在战斗中倒下会怎样？",a="如果达芙妮·斯迪威尔在战斗中倒下，试炼即告失败。勇气试炼的核心要求是在抵御强盗袭击时，保护她的生命以及你自己的安全。",al={"达芙妮会死吗","达芙妮·斯迪威尔死亡"}},{q="这场袭击发生在什么地方？",a="战斗发生在达芙妮·斯迪威尔的农舍外，这是一座位于西部荒野南部、俯瞰长滩的匕首岭小农场。",al={"达芙妮·斯迪威尔位置","农场在哪里"}},{q="防守农场之后该做什么？",a="在证明了你的勇气并击退迪菲亚潜行者后，达芙妮会认可你的奉献精神，并指引你进行下一阶段的圣骑士试炼。",al={"勇气之书后续任务","防守达芙妮之后"}}},fp="17,163,19.375.0,18.346.0,23.194.0,48.225.0,26.191.0,47.132.0,34.140.0,36.158.0"}
P.entries["quest:1652"] = {n="勇气之书",s="这个任务标志着暴风城圣光教会所设下的勇气试炼已告一段落。在保护西部荒野中孤立无援的斯迪威尔农场免受强盗侵扰后，一位有志成为圣骑士的勇士回到达索瑞恩·拉尔身边，报告了达芙妮安然无恙的消息。这巩固了圣骑士作为无辜者无私盾牌的神圣职责。",h="这个任务标志着暴风城圣光教会所设下的勇气试炼已告一段落。在保护西部荒野中孤立无援的斯迪威尔农场免受强盗侵扰后，一位有志成为圣骑士的勇士回到达索瑞恩·拉尔身边，报告了达芙妮安然无恙的消息。这巩固了圣骑士作为无辜者无私盾牌的...",kw={"cathedral of light","达芙妮·斯迪威尔","达索瑞恩·拉尔","铁炉堡","乔丹·斯迪威尔","暴风城","勇气之书","西部荒野"},ang={["class:Paladin"]="回到达索瑞恩·拉尔身边汇报，便完成了你的勇气课程，这证明了你拥有作为联盟神圣守护者所需的无私奉献精神。",["faction:Alliance"]="斯迪威尔一家的困境将西部荒野的人类农田与铁炉堡的矮人工坊直接联系了起来，展现了联盟之间实际的相互依存关系。"},sec={{t="神圣之盾",b="圣骑士之道不仅仅由战斗技巧来定义，更在于挺身而出，站在危险与手无寸铁之人之间。当达芙妮·斯迪威尔发现自己身陷西部荒野的农场被围困时，圣光教会派遣了一名见习生前去坚守阵线。在回到暴风城的Cathedral of Light后，这名见习生带回了农场依然稳固的消息，证明了他们的勇气与信念相符。"},{t="王国间的纽带",b="达芙妮的丈夫，乔丹·斯迪威尔，此刻正身处铁炉堡，以其精湛的工艺协助联盟的事业。既然农场已得到守卫，达芙妮也安然无恙，达索瑞恩·拉尔准备修书一封，寄往这座矮人山城。让乔丹确信他的家人得到了保护，能使这位工匠专注于他的工作，这彰显了相互援助和圣骑士的奉献精神是如何将遥远土地上的联盟成员紧密联系在一起的。"}},faq={{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城Cathedral of Light的一位资深圣骑士训练师。他负责监督年轻圣骑士的精神和武艺试炼，引导他们研习圣典中记录的教义，以确保他们能够体现勇气、正义和谦逊的美德。",al={"达索瑞恩·拉尔","达索瑞恩是谁","暴风城圣骑士训练师"}},{q="为什么达芙妮·斯迪威尔会有危险？",a="达芙妮·斯迪威尔居住在西部荒野的一处偏僻农场。在迪菲亚强盗和无法无天的环境包围下，当她的丈夫乔丹远在铁炉堡工作时，农场成为了一个容易下手的目标。",al={"达芙妮·斯迪威尔","斯迪威尔农场","谁袭击了达芙妮"}},{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是一位技艺高超的铁匠和工匠，虔诚地效忠于圣光教会和联盟。他目前正在铁炉堡工作，为他们的事业贡献自己的专业技能，同时信赖教会能够在他不在家时保护他的妻子。",al={"乔丹·斯迪威尔","达芙妮的丈夫","乔丹在铁炉堡"}},{q="什么是勇气之书？",a="勇气之书既是一本教义圣书，也代表了由Cathedral of Light所主持的一系列实践试炼。通过这些试炼，圣骑士们证明了自己拥有面对黑暗的勇气，并能在承担巨大个人风险的情况下保护弱者。",al={"勇气之书的含义","什么是勇气之书"}},{q="完成这项试炼后接下来要做什么？",a="一旦达索瑞恩·拉尔认可了你在保卫达芙妮·斯迪威尔过程中的英勇表现，他便会引导你进行精神和武艺进阶的下一步，即正义试炼，继续你在该组织内的晋升。",al={"勇气之书后的下一个任务","接下来是什么"}},{q="为什么教会关心斯迪威尔农场？",a="达芙妮和乔丹·斯迪威尔长期以来一直通过忠诚的服务和精湛的工艺协助圣光教会。在乔丹不在期间保护达芙妮，是互惠的荣誉与慈善之举，履行了教会照顾其成员的承诺。",al={"教会为什么要帮助达芙妮","教会与斯迪威尔一家"}}},fp="17,316,15.335.0,21.361.0,22.185.0,34.134.0,23.171.0,26.211.0,39.171.0,54.217.0"}
P.entries["quest:1653"] = {n="正义试炼",s="“正义的试炼”标志着你从在西部荒野保护无辜者，转变为开始铸造圣骑士神圣武器的征程。在达索瑞恩·拉尔的委托下，这位新晋圣骑士将前往铁炉堡，给虔诚的铁匠乔丹·斯迪威尔带去好消息。",h="“正义的试炼”标志着你从在西部荒野保护无辜者，转变为开始铸造圣骑士神圣武器的征程。在达索瑞恩·拉尔的委托下，这位新晋圣骑士将前往铁炉堡，给虔诚的铁匠乔丹·斯迪威尔带去好消息。",kw={"达芙妮·斯迪威尔","迪菲亚潜行者","丹莫罗","达索瑞恩·拉尔","铁炉堡","乔丹·斯迪威尔","暴风城","正义的试炼"},ang={["class:Paladin"]="这段试炼代表着你从保护弱小，转变为铸造肃清联盟领地内邪恶势力所需的神圣工具。",["faction:Alliance"]="斯迪威尔一家的遭遇反映了西部荒野日益加剧的不稳定局势，平民们在对抗迪菲亚潜行者时苦苦挣扎，而暴风城的王室顾问们却在犹豫不决。",["profession:Blacksmithing"]="乔丹·斯迪威尔证明了，对铁砧的真诚投入，与在战场上挥舞圣剑一样，都是一种神圣的虔诚表达。"},sec={{t="传递好消息的使者",b="在达芙妮·斯迪威尔于西部荒野的家园遭遇惊心动魄的迪菲亚潜行者伏击时，一位圣骑士新晋者曾守护在她身边，如今他回到了Cathedral Square复命。达索瑞恩·拉尔意识到，必须让乔丹·斯迪威尔得知妻子的安危，因为乔丹离开前往铁炉堡时，一直担心着家人的安危。拉尔派遣这位年轻的骑士亲自去报信，这既是一种同袍情谊的体现，也是一段更深远使命的序曲。"},{t="丹莫罗的铁匠",b="乔丹·斯迪威尔本应加入圣骑士的圣殿，但他选择了继承父亲作为武器大师的手艺，同时从未背弃自己的信仰。他在铁炉堡大门外架起铁砧，在凛冽的山间空气中工作，依靠虔诚的信仰来引导他的锤子。当得知妻子在迪菲亚潜行者的袭击中幸存后，他深怀感激，决定帮助圣骑士锻造一把神圣的正义武器。"}},faq={{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是一位驻扎在铁炉堡巨大正门外的虔诚武器匠。尽管他最初曾与圣骑士们一起学习圣光之道，但他最终选择将一生奉献给继承父亲的打铁手艺。",al={"乔丹·斯迪威尔","乔丹是谁","铁炉堡的铁匠"}},{q="为什么乔丹的妻子会有危险？",a="达芙妮·斯迪威尔居住在西部荒野的一处农庄，那是一片充斥着迪菲亚潜行者暴徒的未开化之地。当乔丹动身前往矮人首都时，他一直担心会发生袭击。他的担忧最终变成了现实，暴徒袭击了农场，直到被圣骑士新晋者击退。",al={"达芙妮·斯迪威尔的危险","乔丹妻子的遭遇","迪菲亚为何袭击"}},{q="乔丹·斯迪威尔在哪里？",a="乔丹·斯迪威尔在铁炉堡正门外，丹莫罗的严寒冰雪中工作。相比城内Great Forge那令人窒息的高温，他更喜欢清新的山间空气。",al={"乔丹·斯迪威尔在哪里","斯迪威尔的位置","乔丹在铁炉堡的位置"}},{q="为什么达索瑞恩·拉尔要派玩家去铁炉堡？",a="达索瑞恩·拉尔希望乔丹能直接从救下他妻子的恩人那里听到她幸存的消息。这次旅程也让新晋者结识了一位武器大师，他能引导玩家完成圣骑士神圣武装的铸造。",al={"为何要去铁炉堡","达索瑞恩·拉尔的差事","送信的原因"}},{q="与乔丹交谈后会发生什么？",a="得知消息后，乔丹如释重负，他提出贡献自己的技艺，为新晋者铸造一把壮丽的神圣战锤，但这需要收集散落在遥远大陆的稀有材料和圣物。",al={"正义的试炼后续","乔丹想要什么","与乔丹交谈后"}},{q="乔丹对迪菲亚的威胁有何看法？",a="乔丹对暴风城议会的盲目漠视感到愤怒。他指出，迪菲亚潜行者长期以来一直困扰着西部荒野，但他希望这次针对诚实平民家园的袭击，能迫使年幼国王的摄政王们最终正视这场危机。",al={"乔丹对迪菲亚的看法","斯迪威尔对国王顾问的看法","西部荒野的迪菲亚"}}},fp="25,170,24.326.0,23.334.0,23.186.0,32.219.0,35.131.0,53.178.0,38.152.1,45.214.0"}
P.entries["quest:1654"] = {n="正义试炼",s="正义的试炼象征着圣骑士在寻求圣光所赐的圣洁武器时所经历的一场决定性考验。武器大师乔丹·斯迪威尔提出要打造一件非凡的神圣武器，他委托勇士前往遥远的土地搜寻稀有的锻造材料，其中包括他丢失的家族铁锤。",h="正义的试炼象征着圣骑士在寻求圣光所赐的圣洁武器时所经历的一场决定性考验。武器大师乔丹·斯迪威尔提出要打造一件非凡的神圣武器，他委托勇士前往遥远的土地搜寻稀有的锻造材料，其中包括他丢失的家族铁锤。",kw={"贝洛的矿石","丹莫罗","铁炉堡","乔丹·斯迪威尔","科尔宝石","圣骑士武器","正义的试炼","白石橡木"},ang={["class:Paladin"]="这项任务代表了一处传统的试炼场，用锻造出来引导圣光之力的武器来奖励奉献与牺牲。",["faction:Alliance"]="这项协作努力连接了人类的工艺与卡兹莫丹及其他地区的联盟领地，旨在武装保卫者以对抗日益增长的黑暗威胁。",["profession:Blacksmithing"]="乔丹·斯迪威尔代表了凡人锻造技艺的巅峰，他将收回的传家工具与经过净化后的奥术和矿物组件结合，打造出了神圣的圣物。"},sec={{t="神圣的使命",b="在铁炉堡大门外，乔丹·斯迪威尔正在寻找一位值得信赖的圣光追随者。在认可了一位初出茅庐的圣骑士的英勇事迹后，这位铁匠提出了一个神圣的约定：只要这位圣骑士能够完成艰巨的差事，搜集到大师级的材料，他就会为其锻造一件能够成为虔诚永恒象征的传奇武器。"},{t="圣化的组件",b="锻造一件足以引导圣光的武器需要来自东部王国乃至更遥远地区的材料。斯迪威尔的设计需要四种截然不同的物品：坚固的白石橡木、大师级勘探员提炼的矿石、蕴含原始力量且经过净化的科尔宝石，以及找回乔丹当年从影牙城堡逃离时遗失的铁锤。寻找这些材料的过程将迫使圣骑士磨练自己的意志，直面远方的威胁。"},{t="铁匠的遗产",b="对于乔丹·斯迪威尔而言，这项工作绝非简单的交易。所需材料中包括他父亲的铁锤，这是一件与他的技艺和血统紧密相连的传家宝。通过将这件找回的工具与稀有且经过净化的科尔宝石结合，乔丹终于有机会实现他多年来的夙愿，将家族的奉献转化为一件神圣的正义工具。"}},faq={{q="这项任务的目的是什么？",a="这项任务派遣圣骑士在各地奔波，搜集乔丹·斯迪威尔锻造强大的神圣武器所需的稀有材料，以此作为一种试炼。",al={"这项任务的作用","为何进行正义的试炼","正义的试炼目标"}},{q="乔丹·斯迪威尔是谁？",a="乔丹·斯迪威尔是一位技术精湛的人类武器锻造师，驻扎在丹莫罗的铁炉堡大门外。他长期以来一直计划打造一把神圣的圣骑士武器，并试图找回他父亲遗失的锻造铁锤。",al={"乔丹·斯迪威尔背景故事","铁炉堡外的铁匠是谁","斯迪威尔背景"}},{q="锻造这把武器需要什么材料？",a="乔丹需要四种特定的组件：乔丹的铁锤、白石橡木、贝洛的精炼矿石，以及净化过的科尔宝石。",al={"我需要什么物品","乔丹·斯迪威尔的材料","正义的试炼成分"}},{q="为什么乔丹的铁锤对他如此重要？",a="这把铁锤原本属于乔丹的父亲。找回它意味着一件不可替代的传家宝回到了他的锻炉中，让他能够发挥出自己最精湛的技艺。",al={"为何要父亲的铁锤","乔丹的铁锤背景","斯迪威尔铁锤历史"}},{q="什么是科尔宝石？",a="科尔宝石是一种极其稀有且强大的宝石。在净化掉腐蚀性的影响后，它可以作为引导圣光武器的神圣核心。",al={"科尔宝石背景","什么是科尔宝石","净化过的科尔宝石"}},{q="乔丹·斯迪威尔在哪里锻造这把武器？",a="乔丹·斯迪威尔就在丹莫罗山区积雪的铁炉堡大门外工作。",al={"乔丹·斯迪威尔位置","乔丹在哪里","我在哪里交任务"}}},fx={c050f299={q="乔丹·斯迪威尔为什么想让这件事办成？",al={"乔丹·斯迪威尔的动机","乔丹为什么想要这些物品","乔丹·斯迪威尔为什么这样做"}},["4a2d94b4"]={q="乔丹的铁锤有什么用？",a="乔丹的铁锤是乔丹·斯迪威尔从父亲那里继承的传家宝。在着手打造你的圣光武器之前，乔丹需要手握这件熟悉而可靠的工具，才能完成精细而艰巨的工作。",al={"乔丹的铁锤是什么","乔丹的铁锤有什么用","为什么需要乔丹的铁锤"}},deb75c2f={q="乔丹的精炼矿石有什么用？",a="这批精炼矿石能提供打造武器锤头所需的淬炼金属。普通铁无法承载圣骑士的神圣力量，因此必须使用高品质精炼矿石，才能让武器承受激烈战斗和圣光本身的力量。",al={"乔丹的精炼矿石有什么用","精炼矿石有什么用","给乔丹运送矿石"}},a71ac5b5={q="白石橡木有什么用？",a="白石橡木质地致密，坚韧非凡，是打造耐用长柄的上佳木材。乔丹需要这批木料来雕制坚固的握柄，使其能够支撑沉重的锻造锤头，不会在强大的神圣力量下碎裂。",al={"白石橡木有什么用","为什么要用白石橡木","白石木料有什么用"}},ab9031e0={q="净化过的科尔宝石有什么用？",a="科尔宝石天生适于引导魔法与灵性力量。宝石洗去黑暗污秽并得到净化后，便可作为神圣的力量焦点嵌入武器，让你能够通过攻击驾驭并释放圣光。",al={"净化过的科尔宝石有什么用","科尔宝石有什么用","为什么要找净化过的科尔宝石"}},c2f50c47={q="乔丹·斯迪威尔为什么需要你去收集材料？",a="乔丹是个朴实的铁匠，终日守着铁炉堡外的熔炉。他缺乏战斗训练，也没有时间自由前往艾泽拉斯各地的险境。所需物品散落在遥远而危险的地方，必须由一位身经险境、能够驾驭圣光的圣骑士前去寻回。",al={"为什么要我去找乔丹·斯迪威尔","乔丹为什么需要帮助","乔丹为什么不能自己去找矿石"}}},fp="25,315,19.349.0,26.449.0,20.376.1,34.167.0,23.209.0,46.145.0,43.178.0,18.163.0,45.104.0"}
P.entries["quest:1655"] = {n="白洛尔的矿石",s="“白洛尔的矿石补给”是圣骑士们为了寻求乔丹·斯迪威尔的神圣武器所需的精炼金属而进行的一项任务。这批合金补给在从湿地前往洛克莫丹的路上遭遇了莫格罗什食人魔的伏击并被洗劫。",h="“白洛尔的矿石补给”是圣骑士们为了寻求乔丹·斯迪威尔的神圣武器所需的精炼金属而进行的一项任务。这批合金补给在从湿地前往洛克莫丹的路上遭遇了莫格罗什食人魔的伏击并被洗劫。",kw={"白洛尔","乔丹·斯迪威尔","洛克莫丹","莫格罗什","食人魔","矿石","补给","石手","正义试炼"},ang={["class:Paladin"]="找回白洛尔的合金是正义试炼中必不可少的通过仪式，证明你有能力勇敢面对危险的野兽，为你的神圣战锤收集材料。",["faction:Alliance"]="洛克莫丹东北部的莫格罗什食人魔势力依然对通过湿地山口的补给线和商队构成了公开的威胁。",["profession:Blacksmithing"]="白洛尔特制的合金代表了乔丹·斯迪威尔在制造传奇武器时所坚持的严苛冶金要求。"},sec={{t="遇袭的商队",b="当乔丹·斯迪威尔需要一批由他的老友白洛尔·石手精炼的特殊矿石时，这批货物没能安全送达铁炉堡。在从湿地向南蜿蜒前往洛克莫丹的途中，补给商队遭到了莫格罗什食人魔的伏击和屠杀。最后一名幸存的卫兵挣扎着爬回营地，但不久后便因伤势过重而身亡，这批货物也因此遗失在食人魔的领地中。"},{t="收回合金",b="驻扎在洛克莫丹的白洛尔·石手，指引圣骑士们穿过洛克湖，前往东北方的山丘。在那里，在莫格罗什食人魔的营地中，被盗的合金板条箱作为战利品被遗弃着。找回这个板条箱证明了圣骑士敢于深入敌方领地的决心，也让白洛尔能够履行他与乔丹·斯迪威尔最初的约定。"}},faq={{q="谁是白洛尔·石手？",a="白洛尔·石手是一位在洛克莫丹活动的矮人工匠，也是乔丹·斯迪威尔的老友。他负责准备和供应乔丹打造武器所需的特殊合金。",al={"白洛尔·石手","白洛尔是谁","白洛尔"}},{q="是谁偷走了乔丹的矿石补给？",a="莫格罗什食人魔在补给商队从湿地前往洛克莫丹的途中发起了伏击，杀死了护卫并将货物拖回了他们的营地。",al={"谁偷了矿石","谁拿走了补给","矿石窃贼"}},{q="伏击发生在什么地方？",a="商队是在连接湿地和洛克莫丹的山路上遭遇伏击的，当时他们还没能到达当地定居点的安全地带。",al={"伏击地点","商队在哪里遇袭"}},{q="莫格罗什食人魔在哪里？",a="莫格罗什食人魔在洛克湖东北方的崎岖山丘中建有坚固的营地，位于西部定居点对面的水域另一侧。",al={"莫格罗什在哪里","食人魔营地位置","补给在哪里"}},{q="为什么需要这批补给？",a="这批补给中包含一种特殊的合金，是乔丹·斯迪威尔为完成正义试炼的圣骑士打造神圣武器所必需的。",al={"为什么需要矿石","补给的用途","矿石的目的"}},{q="商队卫兵发生了什么事？",a="几乎所有人都在第一时间被食人魔杀害了。唯一一名设法逃脱并寻求帮助的卫兵在几天后就死去了，治疗者没能救回他。",al={"商队卫兵","商队幸存者"}}},fx={f726d253={q="白洛尔·石手为什么想让这件事办成？",a="白洛尔曾答应老友乔丹·斯迪威尔，替他提供一批特殊的精炼合金。运送合金离开湿地的商队遭到伏击，白洛尔不仅失去了货物，唯一幸存的守卫也因伤势过重而死。白洛尔一向以信守承诺为荣，但如今运输队伍已全军覆没，食人魔又控制着合金，他需要有人找回被劫的货物，确保乔丹收到承诺过的东西。",al={"为什么要帮白洛尔","白洛尔的动机","白洛尔为什么想要矿石"}},["8c6c3897"]={q="莫格罗什食人魔是什么人？",a="莫格罗什是一个野蛮的食人魔氏族，他们侵入洛克莫丹东北部的高地，在那里建立了莫格罗什要塞。他们凶狠而贪婪，经常袭击连接洛克莫丹与湿地的山道和商路，杀害旅人，劫掠补给车队，夺取原材料、武器和食物。",al={"莫格罗什食人魔","是谁抢走了矿石","洛克莫丹的食人魔"}},["6bcba9e0"]={q="白洛尔为什么需要冒险者，而不是当地卫兵？",a="当地的矮人卫兵和山地巡逻队正疲于应对穴居人的暴动，并维持洛克湖各处的防线。负责护送白洛尔合金的商队卫兵在伏击中全军覆没，唯一的幸存者也在援兵赶到前死去。白洛尔既没有多余兵力，也没有独自攻打食人魔要塞的本领，因此只能求助于有能力的冒险者。",al={"白洛尔为什么不派卫兵","白洛尔为什么找我帮忙","为什么不派铁炉堡卫兵"}}},fp="21,229,19.444.0,20.375.0,24.196.0,32.163.0,32.142.0,37.129.0,28.143.0,36.155.0"}
P.entries["quest:1656"] = {n="未完的任务",s="“未竟的任务”是一个简单的运送任务，旨在强调年轻牛头人在红云台地进行成年礼时所承受的巨大压力。由于试炼的繁重要求加上还要完成父亲交代的家务琐事，一位精疲力竭的年轻人请求一位路过的旅人将一捆毛皮送到血蹄村的旅店老板考斯那里。",h="“未竟的任务”是一个简单的运送任务，旨在强调年轻牛头人在红云台地进行成年礼时所承受的巨大压力。由于试炼的繁重要求加上还要完成父亲交代的家务琐事，一位精疲力竭的年轻人请求一位路过的旅人将一捆毛皮送到血蹄村的旅店老板考斯那里...",kw={"未竟的任务","血蹄村","一捆毛皮","旅店老板考斯","莫高雷","红云台地","力量试炼","牛头人"},ang={["faction:Horde"]="血蹄村是莫高雷旅人的重要集会中心，为穿越平原的部落成员提供温馨的庇护所和温暖的壁炉。",["race:Tauren"]="年轻的牛头人在红云台地接受严苛的试炼以证明他们的成熟与力量，在此过程中，部落和家庭的义务往往像仪式挑战一样考验着他们的耐力。"},sec={{t="台地上的试炼",b="在红云台地的高处，年轻的牛头人必须通过严苛的成年礼，以证明他们已经准备好迎接更广阔的世界。在传统仪式与日常部落杂务之间奔波，足以让一个年轻人身心俱疲。面对尚未完成的力量试炼和父亲交代的紧急家务，一位年轻的牛头人寻求路过的旅人帮助，将一捆毛皮送到台地下方。"},{t="家园与庇护",b="毛皮的目的地是血蹄村，那是一处坐落在下方广阔平原上的温馨避风港。旅店老板考斯热情地接收了这份运送物品，打算把这捆毛皮制成温暖的毯子，提供给疲惫的旅人。这个差事既体现了平原牛头人的好客，也强调了休息的重要性，展示了社区的支持是如何成为每一次独自进行力量试炼的坚实后盾。"}},faq={{q="什么是“未竟的任务”任务？",a="“未竟的任务”是红云台地上的一位精疲力竭的年轻牛头人所委派的差事。由于沉浸在力量试炼的繁重压力中，这名年轻人请求一位路过的旅人代其将一捆毛皮送到血蹄村的旅店老板手中。",al={"什么是未竟的任务","未竟的任务任务信息","谁发布了未竟的任务"}},{q="旅店老板考斯是谁？",a="旅店老板考斯经营着莫高雷血蹄村的本地旅店。他为那些从高处台地穿越平原而来的疲惫旅人提供温馨的休憩之所、温暖的毯子以及热情的款待。",al={"旅店老板考斯是谁","考斯在哪里","血蹄村旅店老板"}},{q="为什么要将毛皮送到旅店？",a="这捆毛皮是年轻牛头人的父亲要求送给旅店老板考斯的。考斯使用这些结实的毛皮为在他血蹄村旅店寻求庇护和休息的客人制作温暖的毯子。",al={"为什么运送毛皮","毛皮的用途是什么","莫高雷毛皮捆"}},{q="为什么年轻的牛头人自己不能运送这些毛皮？",a="这位年轻的牛头人目前正在红云台地进行力量试炼。试炼对体能的极高要求使他精疲力竭，无法在不导致神圣试炼失败或因过度疲劳而倒下的情况下，独自前往血蹄村。",al={"为什么任务发布者不能运送毛皮","为什么年轻人需要帮助"}},{q="什么是力量试炼？",a="力量试炼是年轻牛头人在台地上进行的基础成年礼之一。它考验着他们的体力、韧性以及作为部落未来守护者的能力。",al={"什么是力量试炼","力量试炼牛头人试炼"}},{q="血蹄村位于哪里？",a="血蹄村是莫高雷草海平原上的一个主要定居点，位于红云台地庇护的高地之下。它设有包括开放式旅店、制作补给品和贸易前哨站等中心部落设施。",al={"血蹄村在哪里","血蹄村位置"}}},fp="17,319,18.404.0,18.390.0,36.262.0,23.212.0,44.207.0,58.254.0,29.195.0,36.233.0"}
P.entries["quest:166"] = {n="迪菲亚兄弟会",s="这次任务是格里安·斯托曼长期致力于从不法之徒手中收复西部荒野这一行动的高潮。联盟的勇士们受命进入死亡矿井，必须突入这个罪犯的藏身处，并亲自击毙首领艾德温·范克里夫。",h="这次任务是格里安·斯托曼长期致力于从不法之徒手中收复西部荒野这一行动的高潮。联盟的勇士们受命进入死亡矿井，必须突入这个罪犯的藏身处，并亲自击毙首领艾德温·范克里夫。",kw={"死亡矿井","首级","重装战舰","民兵","月溪镇","石匠","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="范克里夫是一位传奇的潜行者和大师级工匠；在他的内圣所与他交锋，是对任何潜行特工武艺训练的考验。",["faction:Alliance"]="这次任务标志着联盟早期的一次关键胜利，在暴风城王座无力分兵的情况下，保住了西部荒野这个粮仓。",["race:Human"]="对于王国的人类来说，击毙范克里夫是一场苦乐参半的悲剧，因为他们亲手斩杀了那位曾用双手将他们的首都从灰烬中重建起来的工匠。"},sec={{t="执行死刑",b="数月以来，格里安·斯托曼和陷入困境的人民民兵一直与迪菲亚兄弟会在西部荒野进行着绝望的阻击战。随着盗贼团伙位于月溪镇下方的真正据点被发现，斯托曼下达了他那残酷的最终判决：必须刺杀艾德温·范克里夫，以彻底瓦解这场叛乱。"},{t="深入迷宫",b="为了执行这次处决，战士们必须深入死亡矿井蜿蜒的坑道。越过那些变节的石匠、地精工程师以及沉重的铁质防爆门，便是中央干船坞，范克里夫正在那里监督他那艘大型战争舰船的最后建造工作。取下他的首级便能切断维系整个不法网络的指挥系统。"},{t="更大阴谋的阴影",b="虽然斯托曼认为范克里夫的死标志着兄弟会末日的开始，但这位倒下的工会领袖的尸体却隐藏着令人不安的秘密。在他的身上有一封未寄出的信，暗示着西部荒野的起义并非孤立的叛乱，而是延伸到暴风城贵族阶层内部的一个更广阔、更黑暗的阴谋网络的一部分。"}},faq={{q="这个任务的目标是什么？",a="你受格里安·斯托曼之命，前往月溪镇的死亡矿井副本，消灭艾德温·范克里夫，并将他的首级带回哨兵岭。",al={"任务目标","我该做什么","这是什么任务"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫曾是石匠工会的总工匠，在第一次战争中兽人夷平暴风城后，他领导了城市的重建工作。在与贵族议会就报酬问题发生激烈争执后，他创立了迪菲亚兄弟会，向王国复仇。",al={"范克里夫是谁","范克里夫的身份","艾德温·范克里夫背景故事"}},{q="为什么格里安·斯托曼下令进行刺杀？",a="人民民兵缺乏维持持久战争所需的来自暴风城的正规军支援。斯托曼认识到，斩首行动是西部荒野打破辛迪加对农田控制的唯一现实机会。",al={"为什么要杀范克里夫","斯托曼的动机","为什么判处死刑"}},{q="在哪里可以找到艾德温·范克里夫？",a="他隐藏在月溪镇下方死亡矿井的深处。格里安·斯托曼要求你进入该藏身处并找到他。",al={"范克里夫的位置","艾德温·范克里夫在哪里","死亡矿井首领位置"}},{q="杀死范克里夫能彻底摧毁迪菲亚吗？",a="斯托曼希望范克里夫的死能打破兄弟会对西部荒野的控制。结果以及任何进一步的发现，都要等待此次突袭之后才能知晓。",al={"迪菲亚被击败了吗","迪菲亚消失了吗","兄弟会的终结"}},{q="范克里夫被击败后身上会发现什么值得注意的物品？",a="斯托曼要求范克里夫的首级作为证明。藏身处内的其他发现将在任务中揭晓。",al={"范克里夫掉落物","未寄出的信","范克里夫掉落什么"}}},fx={e9d4d384={q="范克里夫的头颅有什么用？",a="格里安·斯托曼要求拿出确凿证据，证明艾德温·范克里夫确实已死。多年来，迪菲亚潜行者一直藏身暗处，恐吓西部荒野、散布谣言并躲避追捕。献上范克里夫被砍下的头颅，能为人民军带来确切的了结，也能让饱受折磨的农民知道，他们最大的仇敌终于倒下了。",al={"为什么要拿范克里夫的头颅","范克里夫的头颅有什么用","为什么我需要范克里夫的头颅"}},["48642626"]={q="格里安·斯托曼为什么派你去，而不是派人民军？",a="人民军已竭尽全力守卫哨兵岭和西部荒野各处分散的家园，应付每天的强盗袭击与豺狼人侵扰。暴风城拒绝派遣援军，使斯托曼无法组织训练有素、装备精良的突击队，攻入死亡矿井坚固的深处。他只能依靠你这样的老练能干的冒险者，直捣阴谋的核心。",al={"人民军为什么不进攻死亡矿井","为什么派我去对付范克里夫","斯托曼为什么不杀范克里夫"}}},fp="22,257,17.364.0,18.354.1,31.343.1,31.164.0,22.284.0,50.257.0,34.123.0,52.140.1,55.115.1"}
P.entries["quest:1665"] = {n="巴特莱比的酒杯",s="“巴特莱比的酒杯”是年轻的暴风城战士在最初的意志考验中的最终任务。在Pig and Whistle Tavern击败了好斗的巴特莱比之后，The Adventurer索取了他的酒杯，作为向他们的训练师哈里·伯加德证明胜利的凭证。",h="“巴特莱比的酒杯”是年轻的暴风城战士在最初的意志考验中的最终任务。在Pig and Whistle Tavern击败了好斗的巴特莱比之后，The...",kw={"巴特莱比","伯加德","酒杯","old town","pig and whistle","暴风城","战士"},ang={["class:Warrior"]="暴风城的训练师认为，实战斗殴所教授的课程是任何手册都无法比拟的；夺取巴特莱比的酒杯证明了你有能力直面并制服不守规矩的敌人。",["faction:Alliance"]="维持Old Town的治安通常意味着要处理那些扰乱秩序的顾客，这使得巴特莱比成了暴风城的武术教官们熟悉的一个当地麻烦。"},sec={{t="酒馆斗殴的战利品",b="暴风城的战士训练师不在乎空谈理论；他们想要看到的是纯粹的决心和站稳脚跟的能力。哈里·伯加德指派初出茅庐的战士去击倒巴特莱比，这家伙是个在Old Town的Pig and Whistle吧台前酗酒的顽固酒鬼。一旦被制服，巴特莱比就会不情愿地交出他珍爱的酒杯——当然，是在喝干最后一口酒之后。"},{t="通往大师之路的一步",b="将酒杯送回给哈里·伯加德标志着新手试炼的完成。在认可了这位战士通过武力进行劝说的天赋后，伯加德确认了战士已经准备好掌握防御技能，并指引他们前往艾尔文森林，接受进一步的战场指导，并寻找经验丰富的老兵Marshal Haggard。"}},faq={{q="为什么哈里·伯加德想要巴特莱比的酒杯？",a="酒杯是新手战士确实与巴特莱比交手并将其击败的铁证。巴特莱比非常珍视他的酒杯，所以交出他的私人酒杯证明他确实被彻底击败并屈服了。",al={"为什么需要巴特莱比的酒杯","伯加德需要酒杯的目的","击败巴特莱比的证明"}},{q="巴特莱比是谁？",a="巴特莱比是暴风城Old Town的Pig and Whistle吧台前的一个无赖酒客。他因酗酒和暴躁的脾气而闻名，当地的战士训练师将他作为初出茅庐的战士们非正式的成人礼。",al={"巴特莱比背景故事","巴特莱比是谁","old town巴特莱比"}},{q="这场战斗在哪里发生？",a="这场斗殴发生在位于暴风城Old Town的Pig and Whistle Tavern内。",al={"巴特莱比在哪里","巴特莱比位置","pig and whistle斗殴"}},{q="把酒杯还给伯加德后接下来要做什么？",a="一旦伯加德检查完酒杯并确认了你的胜利，他会传授你关于防御战斗姿态的高级训练，然后派遣你前往城门外，去寻找艾尔文森林的Marshal Haggard。",al={"交还酒杯后做什么","酒杯任务后续","哈格德任务"}},{q="巴特莱比在斗殴中会受到永久性伤害吗？",a="不会。这只是一场非致命的酒馆斗殴。一旦被击败，巴特莱比就会认输，喝干他的酒，交出酒杯，并继续留在酒馆里安抚他的伤痛和自尊心。",al={"巴特莱比死了吗","巴特莱比是否死亡","巴特莱比幸存"}},{q="任何联盟职业都能做这个任务吗？",a="这项任务严格限定为联盟战士，作为他们10级职业训练进程的一部分，旨在掌握战斗姿态和防御机动的艺术。",al={"酒杯任务是否仅限战士","谁能做巴特莱比任务","酒杯任务职业"}}},fp="14,183,24.276.0,21.290.0,45.196.0,16.191.0,33.80.0,48.192.0,48.143.0,37.128.0"}
P.entries["quest:1666"] = {n="治安官哈迦德",s="“哈格德元帅”是哈里·伯加德在暴风城发布的一项联盟任务，旨在为寻求更好武器的新手战士提供帮助。这位年轻的战士会被派遣离开首都，前往艾尔文森林东部的东谷伐木场，去见一位退役的军事元帅，他收藏着许多传奇的老兵武器。这是战士在城墙保护之外的武勇征程中迈出的早期一步。",h="“哈格德元帅”是哈里·伯加德在暴风城发布的一项联盟任务，旨在为寻求更好武器的新手战士提供帮助。这位年轻的战士会被派遣离开首都，前往艾尔文森林东部的东谷伐木场，去见一位退役的军事元帅，他收藏着许多传奇的老兵武器。这是战士在...",kw={"东谷","东谷伐木场","艾尔文森林","哈里·伯加德","哈格德元帅","暴风城","战士"},ang={["class:Warrior"]="这项任务是联盟战士早期的一个里程碑，让他们从正式的城市训练过渡到广阔的荒野，寻找武勇装备。",["faction:Alliance"]="这个任务反映了暴风城如何依靠退役老兵积累的专业知识和私人补给来培养下一代保卫者。"},sec={{t="老兵的军械库",b="在暴风城训练的新手战士很快就会明白，没有可靠的钢刃，单纯的技巧是远远不够的。哈里·伯加德指引那些有前途的战士去寻找哈格德元帅，这是一位隐居在艾尔文森林东部宁静地带的王国退役军官。在漫长的野外服役生涯中，哈格德积累了一座令人敬佩的个人军械库，这使得他的家园成为了急需真正装备的新晋战士们的自然目的地。"},{t="在东谷的退休生活",b="哈格德元帅居住在靠近东谷伐木场的一座僻静庄园里。多年的艰苦服役对这位年迈的指挥官造成了不小的影响：他的视力正在衰退，并且容易把靠近的旅行者错看成徘徊的河爪豺狼人。尽管年事已高且与世隔绝，但这位老元帅在暴风城的卫兵和训练师中仍然备受尊敬。"}},faq={{q="谁发布了这个任务？",a="哈里·伯加德，一名驻扎在暴风城的战士训练师，会在有抱负的战士证明了他们的基础技能后提供此任务。",al={"哪里接哈格德元帅任务","谁给予哈格德元帅任务","任务发布者哈格德元帅"}},{q="哈格德元帅在哪里？",a="哈格德元帅住在东谷伐木场以东的一座庄园里，位于艾尔文森林的最东端，靠近赤脊山的边界。",al={"哈格德元帅位置","哈格德在哪里","东谷伐木场庄园"}},{q="哈里·伯加德为什么要派你去找哈格德？",a="伯加德意识到，一名成长中的战士需要比标准制式的新手训练刃更好的装备。哈格德在他漫长的职业生涯中收集了大量的武器和护甲，并且据了解，他愿意为那些证明了自己实力的战士提供装备。",al={"为什么找哈格德元帅","战士为什么要去东谷","哈格德元帅任务目的"}},{q="为什么哈格德会把访客错认成豺狼人？",a="哈格德的视力在晚年严重衰退。由于豺狼人经常骚扰东部的木材作业区和艾尔文森林的边缘地带，这位谨慎的老兵对突然出现的访客一直保持警惕。",al={"哈格德视力","哈格德失明了吗","哈格德豺狼人对话"}},{q="完成这个任务后会发生什么？",a="在问候哈格德后，这位退役元帅会让你去完成任务“死牙杰克”来考验你的实力，之后才会考虑拿出他个人库存中的任何武器。",al={"哈格德元帅后续任务","哈格德元帅接下来的任务"}},{q="这个任务战士以外的职业可以接吗？",a="不可以。这个任务线是10级战士职业任务的一部分，旨在为年轻的战士装备好应对艾尔文森林之外挑战的能力。",al={"圣骑士能做哈格德元帅任务吗","战士专属任务哈格德"}}},fp="15,194,18.386.0,22.325.0,22.104.0,33.137.0,45.223.0,45.169.0,39.150.1,55.129.0"}
P.entries["quest:1667"] = {n="蛀牙杰克",s="哈加德治安官，一位住在东艾尔文森林的退役军官，被一名叫做“死牙”杰克的迪菲亚潜行者骗走并交出了他的官方徽章。杰克在夜色中身穿暴风城战袍，冒充治安官杜汉偷走了徽章。哈加德需要找回这枚徽章，以免迪菲亚潜行者利用它来冒充暴风城的官员。",h="哈加德治安官，一位住在东艾尔文森林的退役军官，被一名叫做“死牙”杰克的迪菲亚潜行者骗走并交出了他的官方徽章。杰克在夜色中身穿暴风城战袍，冒充治安官杜汉偷走了徽章。哈加德需要找回这枚徽章，以免迪菲亚潜行者利用它来冒充暴风城...",kw={"徽章","死牙杰克","迪菲亚","艾尔文森林","伯加德","冒充","治安官杜汉","哈加德治安官","保险箱"},ang={["class:Rogue"]="“死牙”杰克的骗局表明，迪菲亚潜行者不仅依靠粗暴的拦路抢劫，还依赖伪装、社会工程学和厚颜无耻的手段。",["class:Warrior"]="哈加德治安官曾是一名身经百战的前线战士，他用自己多年现役生涯中保存下来的闲置武器来奖励那些恢复他荣誉的人。",["race:Human"]="对于暴风城的人类来说，这次盗窃凸显了该王国农村边界在迪菲亚渗透者面前是多么脆弱，这些渗透者毫无顾忌地身穿王室的颜色来欺骗退役的老兵。"},sec={{t="黑暗中的骗局",b="即使是经验丰富的士兵，在暮年也可能放松警惕。住在艾尔文森林东部山脊一座孤立小屋里的哈加德治安官，有天晚上看到一个身穿暴风城战袍的身影走近时，以为那是治安官杜汉。那个陌生人声称有公事，要求查看哈加德以前的治安官徽章。哈加德以为是交给自己的一位同僚，便照做了——谁知那个冒牌货，也就是众所周知的迪菲亚窃贼“死牙”杰克，嘲笑着他的愚蠢，随后消失在树林里。"},{t="虚假权力的威胁",b="虽然哈加德已经退役，但他的旧徽章仍然带有暴风城王国的法律效力和权威。随着迪菲亚强盗在艾尔文森林、西部荒野和赤脊山潜行，一枚落入罪犯手中的正牌警官徽章会带来直接的危险。它可能允许潜行者穿过守卫检查站、重定向巡逻队或征用物资。杰克撤退到了南边的一个营地，把偷来的赃物锁进了一个保险箱里，这让哈加德迫切希望能找回它，以免造成严重的后果。"}},faq={{q="“死牙”杰克是谁？",a="“死牙”杰克是活跃在东艾尔文森林的迪菲亚潜行者成员。他以胆大妄为著称，曾在夜色的掩护下伪装成治安官杜汉，欺骗已退役的哈加德治安官交出了他的官方暴风城徽章。",al={"死牙杰克","死牙是谁","死牙杰克背景故事"}},{q="为什么哈加德治安官需要拿回他的徽章？",a="这枚徽章是暴风城权威的真实象征。哈加德担心如果迪菲亚潜行者留着它，他们会利用它来冒充官员、绕过军事巡逻队，并在整个王国制造混乱。",al={"为什么要找回徽章","哈加德的徽章","为什么徽章很重要"}},{q="杰克是如何成功欺骗哈加德治安官的？",a="杰克在晚上身穿暴风城战袍接近了哈加德的小屋。在昏暗的灯光下，哈加德误以为他是闪金镇的治安官杜汉，并在被索要时毫不犹豫地交出了徽章。",al={"他如何欺骗哈加德","哈加德被骗","哈加德为何交出徽章"}},{q="杰克把偷来的徽章藏在哪里？",a="杰克将徽章锁在哈加德治安官住所南部的强盗营地里的一个保险箱中。杰克随身携带着那个箱子的钥匙。",al={"徽章位置","徽章在哪里","死牙营地"}},{q="起初是谁派你去找哈加德治安官的？",a="哈里·伯加德，那位常去暴风城Pig and Whistle Tavern的老兵战士，会派冒险者去找哈加德，因为他知道这位老治安官有一些闲置的武器，或许愿意用它们来交换帮助。",al={"谁派你来这里的","伯加德","任务起始"}},{q="徽章归还后会发生什么？",a="哈加德对迪菲亚潜行者无法利用他的身份或军衔来对抗王国感到非常欣慰。为了表示感谢，他向你敬礼，并让你从他服役期间精心保养的军用武器中挑选一件。",al={"任务提交","哈加德的反应","徽章已归还"}}},fp="15,367,17.381.0,29.408.0,23.199.0,45.211.0,44.219.0,38.142.0,51.207.0,40.219.1"}
P.entries["quest:167"] = {n="我的兄弟……",s="“噢，兄弟……”是联盟的一项任务，由暴风城的维尔德·蓟草发布。由于在月溪镇地下深处的探险中遭遇塌方，维尔德心急如焚，他请求冒险者们去那错综复杂的矿井中寻找他失踪的兄弟——工头希斯耐特，或是带回他的探险者协会徽章。",h="“噢，兄弟……”是联盟的一项任务，由暴风城的维尔德·蓟草发布。由于在月溪镇地下深处的探险中遭遇塌方，维尔德心急如焚，他请求冒险者们去那错综复杂的矿井中寻找他失踪的兄弟——工头希斯耐特，或是带回他的探险者协会徽章。",kw={"徽章","死亡矿井","探险者协会","月溪镇","暴风城","希斯耐特","亡灵","西部荒野","维尔德"},ang={["faction:Alliance"]="死亡矿井是暴风城门口的毒瘤，这项任务展现了迪菲亚兄弟会和地底恐怖生物对无辜市民造成的深重伤害。",["race:Dwarf"]="对于任何重视兄弟情谊、石匠工艺以及探险者协会不懈努力的矮人来说，一位探险者协会工头在人类土地上遭遇的悲惨结局令人感同身受。"},sec={{t="被困的探险队",b="维尔德·蓟草和他的兄弟作为一家矿业公司的成员，进入了月溪镇下方的洞穴隧道。然而，当敌对的盗贼蜂拥而至，引发剧烈的塌方封锁了下层隧道时，情况变得极为糟糕。维尔德设法逃到了暴风城，但他的兄弟和其余船员却被困在了碎石之后。"},{t="工头希斯耐特的悲惨命运",b="任何深入死亡矿井隧道试图进行营救的人，最终都会发现悲惨的真相。工头希斯耐特没能在那场掩埋中幸存；相反，在这座废弃矿井中涌动的黑暗能量，将这位不幸的矮人复活成了一具亡灵躯壳。他在地底洞穴中与其他游荡的尸体一同徘徊，只保留着他引以为傲的探险者协会徽章，作为他曾经身份的见证。"}},faq={{q="我在哪里可以接到“噢，兄弟……”这个任务？",a="该任务由维尔德·蓟草提供，他位于暴风城的Dwarven District。",al={"噢，兄弟 任务发布者","谁发布噢兄弟任务","哪里接噢兄弟"}},{q="工头希斯耐特在哪里？",a="工头希斯耐特在死亡矿井外围的矿道中徘徊，该矿井位于西部荒野的月溪镇下方。他在通往副本入口的外部隧道中的某个位置。",al={"工头希斯耐特位置","希斯耐特在哪里","兄弟在哪里"}},{q="工头希斯耐特发生了什么事？",a="一场塌方将工头希斯耐特和他的采矿队困在洞穴中，此后就再也没有他们的消息。找到他，或者至少找到他的徽章，是维尔德了解他兄弟命运的唯一途径。",al={"希斯耐特还活着吗","兄弟发生了什么","希斯耐特背景故事"}},{q="我需要取回什么物品？",a="你需要取回工头希斯耐特的探险者协会徽章，那是他随身携带的物品；在死亡矿井深处的隧道中找到工头，徽章就在他身上。",al={"噢兄弟 任务物品","噢兄弟 掉落物品"}},{q="探险队在月溪镇做什么？",a="蓟草兄弟是某家矿业公司的成员，他们在遭到迪菲亚强盗伏击并因突然的隧道坍塌而失散之前，一直在月溪镇下方的大矿井中工作。",al={"为什么矮人在西部荒野","探险者协会 死亡矿井","为什么他们在月溪镇"}},{q="这个任务是在死亡矿井副本内完成吗？",a="不需要，你不需要进入地下城副本。工头希斯耐特是一个精英怪物，他游荡在通往副本入口的、处于争夺状态的矿道中。",al={"噢兄弟 在死亡矿井副本里吗","需要副本队伍吗"}}},fx={["7bf03114"]={q="维尔德·蓟草为什么想让这件事办成？",a="月溪镇地下深处的隧道坍塌时，维尔德侥幸逃过一劫。他的兄弟和其余矿工再也没有出来，全被黑暗和盘踞在通道里的盗贼吞没。回到暴风城后，他一直在煎熬的不确定中苦苦等待，渴望得到解脱。他想知道兄弟是否还活着，还是已经在地底遭遇了悲惨的结局。",al={"为什么维尔德想找到兄弟","维尔德·蓟草的动机","为什么要找到工头希斯耐特"}},ebc7a172={q="希斯耐特的徽章是什么？",a="工头希斯耐特随身携带着一枚探险者协会徽章，表明他在铁炉堡挖掘者与冒险者公会中的身份。如果你在深处找不到任何幸存的矮人，找回这件私人信物便能证明他的命运，让悲痛的兄弟得以彻底释怀。",al={"希斯耐特的徽章是什么","希斯耐特探险者协会徽章","为什么要拿徽章"}},["5e05fe78"]={q="维尔德·蓟草为什么让你去，而不是自己去？",a="灾难发生时，维尔德侥幸逃出生天。月溪镇地下错综复杂的迷宫里遍布歹徒和危险陷阱，远非一个逃出来的矿工能够独自应付。看到你是个身手不凡的冒险者，他便把希望寄托在你身上，希望你能完成他只能逃离的事。",al={"维尔德为什么不自己去","为什么派我去死亡矿井","维尔德为什么需要帮忙"}}},fp="15,316,20.372.0,38.411.1,45.105.0,39.200.0,39.215.1,32.173.1,43.182.0,62.168.0"}
P.entries["quest:1679"] = {n="穆伦·雷矛",s="Muren Stormpike是一个为初级联盟战士设计的入门任务，当新兵在丹莫罗证明了他们的基本实力后就会接到该任务。在卡拉诺斯听从格兰尼斯·快斧的指引后，年轻的战士会前往山中城市铁炉堡，寻求关于战斗纪律的正式指导。与Muren会面标志着对战术姿态和矮人军事传统进行更深层次训练的开始。",h="Muren...",kw={"防御姿态","格兰尼斯·快斧","hall of arms","铁炉堡","卡拉诺斯","military ward","muren stormpike","战士训练师"},ang={["class:Warrior"]="这次召唤标志着你从一个手忙脚乱的新兵转变为一名能够坚守阵线并保护盟友的训练有素的士兵的试炼。",["race:Dwarf"]="对于矮人战士来说，向Hall of Arms报到将使你直接与山中氏族的辉煌武术传承和战术纪律建立联系。",["race:Gnome"]="侏儒战士在诺莫瑞根陷落后撤离到了丹莫罗，他们依靠铁炉堡的Hall of Arms来掌握传统的前线重装战斗。"},sec={{t="铁炉堡的召唤",b="在丹莫罗的雪谷中经历过当地威胁的磨练后，新手战士们吸引了卡拉诺斯的格兰尼斯·快斧的注意。快斧意识到粗浅的战斗只能让一个格斗者走得这么远，于是将有前途的战士送往矮人武艺的核心之地：铁炉堡的Military Ward。在那里，在铁炉堡的回响大厅中，高级战士们监管着那些注定要奔赴战场之人的正规训练。"},{t="武器大师",b="到达Hall of Arms后，新兵们被介绍给Muren Stormpike，一位来自著名矮人氏族的经验丰富的老兵。Muren对酒馆里的吹嘘毫无兴趣，他要求新兵证明他们能够经受住真正的战斗。向他报到开启了掌握防御艺术、学习吸收和控制敌人仇恨的道路，并能获得适合真正前线任务的精良铁制装备。"}},faq={{q="谁派你去找Muren Stormpike的？",a="格兰尼斯·快斧，驻守在卡拉诺斯的战士训练师。一旦你在丹莫罗证明了你的基本武力，他就会给你这个任务。",al={"谁发布muren stormpike任务","在哪里领取muren stormpike任务","muren stormpike任务发布者"}},{q="Muren Stormpike在哪里？",a="Muren Stormpike位于铁炉堡东侧Military Ward内的Hall of Arms。",al={"muren stormpike在哪里","muren stormpike位置","如何找到muren"}},{q="为什么这个任务对战士很重要？",a="向Muren报到将开启进阶战士训练。这直接通向可以解锁防御姿态、学习嘲讽等重要防御技能的任务，并奖励一件可靠的早期职业武器。",al={"muren stormpike解锁什么","为什么要完成muren stormpike","muren stormpike奖励"}},{q="Muren Stormpike是谁？",a="Muren是铁炉堡的一名资深战斗教官，属于著名的Stormpike氏族，这是一个以强悍战士和探险工程师而闻名的有影响力的矮人家族。",al={"muren是谁","muren stormpike背景故事","muren属于哪个氏族"}},{q="任何职业都能接这个任务吗？",a="不能。这个任务严格限制为准备接受专业武艺指导的战士新手。",al={"非战士职业可以完成muren stormpike吗","muren stormpike是战士专属任务吗","muren stormpike职业限制"}},{q="向Muren报到后会发生什么？",a="到达并与Muren交谈后，他会立即通过让你进行一场战斗试炼来测试你的决心，从对抗Vejrek的任务开始。",al={"完成muren stormpike后的下一个任务","muren stormpike后续任务","vejrek任务"}}},fx={["61377fd6"]={q="格兰尼斯·快斧为什么派你去找穆伦·风暴之矛？",a="格兰尼斯·快斧看出了你在战斗方面大有潜力，但卡拉诺斯只能教你一些基础本领。为了提升你的武艺，了解真正的战士之道，他把你推荐给了驻扎在铁炉堡 Hall of Arms 的老兵穆伦·风暴之矛。",al={"格兰尼斯·快斧的动机","为什么派我去找穆伦","为什么要去见穆伦·风暴之矛"}}},fp="15,395,22.444.0,18.414.0,38.145.0,33.115.0,41.202.0,23.180.0,30.105.0,38.158.0"}
P.entries["quest:168"] = {n="收集记忆",s="“收集记忆”是一项庄严的任务，由暴风城的矮人矿工维尔德·蓟草委托。他请求勇闯月溪镇下方废弃矿井的冒险者们找回他已故工友的矿工工会卡。将这些信物带回，能让首都中痛失亲人的家庭在灾难性的塌方后得到慰藉。",h="“收集记忆”是一项庄严的任务，由暴风城的矮人矿工维尔德·蓟草委托。他请求勇闯月溪镇下方废弃矿井的冒险者们找回他已故工友的矿工工会卡。将这些信物带回，能让首都中痛失亲人的家庭在灾难性的塌方后得到慰藉。",kw={"收集记忆","死亡矿井","矿工工会卡","月溪镇","暴风城","亡灵矿工","维尔德·蓟草"},ang={["faction:Alliance"]="找回这些在西部荒野遇难的工人的信物，能直接支持那些在暴风城城墙内忍受艰难困苦、沉浸在悲痛中的工人阶级家庭。",["profession:Mining"]="每一位矿工都能理解对矿井塌方的挥之不去的恐惧，这使得找回丢失工会卡的任务对所有矿工来说，都具有一种深刻而忧郁的共鸣。",["race:Dwarf"]="矮人非常重视在地底铸就的情谊以及逝去同胞的神圣安宁，这使得维尔德·蓟草的恳求对他的石族同胞而言，是一件感同身受的事。"},sec={{t="一场悲剧性的塌方",b="在月溪镇完全陷入无序状态并被迪菲亚潜行者的阴影笼罩之前，西部荒野的矿井曾是许多工人阶级家庭的重要经济来源。维尔德·蓟草在一次摧毁了错综复杂隧道其中一部分的毁灭性塌方中幸存下来，但他许多朋友和同事却没那么幸运。由于救援受阻，那些工人们在地底深处遇难，在暴风城留下了悲痛的亲属，他们从未得到关于亲人命运的确切消息或慰藉。"},{t="不安的遗骸",b="地下主铁矿区外的隧道不再是静谧的墓地。在塌方中遇难的矿工灵魂如今化作不安的亡灵躯壳，徘徊在黑暗的通道中。为了找回矿工工会卡，旅行者必须探索这些闹鬼的矿井，面对维尔德曾经并肩工作的矿工们留下的活动遗骸。将这些卡片带回暴风城，能让他们的亲属最终得知真相，也让维尔德有机会缅怀他逝去的同僚。"}},faq={{q="维尔德·蓟草是谁？",a="维尔德·蓟草是一位居住在暴风城的矮人矿工。他曾从西部荒野下方的一场导致他亲密同事丧生的毁灭性隧道塌方中幸存，现在他希望能给遇难者的家属带去安宁和确切的消息。",al={"维尔德·蓟草","任务发布者","谁发布了收集记忆"}},{q="死亡矿井里的矿工们发生了什么事？",a="一场毁灭性的隧道塌方困住并杀害了月溪镇挖掘点一侧的全体矿工。由于无法获得救援和妥善安葬，他们的灵魂和躯体化作不安的亡灵，徘徊在废弃的通道中。",al={"为什么会有亡灵矿工","矿井塌方","死亡矿井塌方"}},{q="维尔德为什么要找回他们的矿工工会卡？",a="工会卡是死于塌方工人的正式身份证明。由于尸体从未被寻回，找回这些卡片能让维尔德正式通知他们在暴风城的家人，并给予他们慰藉。",al={"工会卡有什么用","矿工工会卡"}},{q="在哪里可以找到工会卡？",a="这些卡片位于月溪镇下方闹鬼的外围隧道中，就在进入死亡矿井正式守卫区域前的走廊里。",al={"在哪里能找到卡片","死亡矿井亡灵位置","遇难矿工在哪里"}},{q="是迪菲亚潜行者导致了塌方吗？",a="维尔德·蓟草只是将其回想为一场可怕的采矿事故和隧道塌方。虽然迪菲亚潜行者现在控制着死亡矿井深处的通道，但这场悲剧本身似乎是一起困住他同伴的灾难性工业事故。",al={"迪菲亚造成了塌方吗","是谁导致矿井坍塌"}},{q="这些矿工被认为是迪菲亚潜行者的一部分吗？",a="不。他们只是在塌方发生时在矿井工作的普通工会劳工。他们不安的亡灵残骸在矿洞外围游荡，与位于深处、由艾德温·范克里夫组织的迪菲亚势力毫无关联。",al={"遇难矿工是迪菲亚吗","亡灵矿工属于迪菲亚吗"}}},fx={e1328ead={q="矿业工会会员卡是什么？",a="灾难发生前，这些工会卡是月溪镇矿洞中劳工的正式身份证明。如今，它们是地下隧道坍塌时遇难者留下的唯一长久凭证。找回这些卡是确认哪些工人葬身深处的唯一办法，这样维尔德·蓟草才能通知他们在暴风城悲痛欲绝的家人，让他们得以释怀。",al={"矿业工会会员卡","工会卡是什么","工会卡"}},["22601dce"]={q="维尔德·蓟草为什么需要冒险者来做这件事？",a="维尔德·蓟草在可怕的坍塌事故中幸存下来，但月溪镇矿洞深处此后陷入了危险的混乱。旧塌方区域周围到处都是敌对势力和躁动的亡者，普通平民或前矿工根本无力应对。由于城里的卫兵并未被派往西部荒野险恶的废墟，维尔德只能依靠那些本就打算深入矿洞的能干冒险者，去废墟中寻找他失踪的朋友。",al={"为什么让我收集回忆","维尔德为什么需要帮忙","为什么派冒险者去"}}},fp="19,339,17.529.0,16.482.0,28.247.0,45.237.0,47.237.0,32.162.0,45.261.0,57.210.0"}
P.entries["quest:1680"] = {n="托姆斯·深炉",s="托姆斯·深炉是铁炉堡的一位武器锻造师，负责为穆拉丁·铜须（在游戏中通常为穆伦·风暴之矛）所选拔的、具有潜力的战士提供精良的武器。在打造任何定制武器之前，托姆斯都会要求冒险者完成一项艰巨的试炼，以证明自己的实力。",h="托姆斯·深炉是铁炉堡的一位武器锻造师，负责为穆拉丁·铜须（在游戏中通常为穆伦·风暴之矛）所选拔的、具有潜力的战士提供精良的武器。在打造任何定制武器之前，托姆斯都会要求冒险者完成一项艰巨的试炼，以证明自己的实力。",kw={"矮人铁匠","great forge","铁炉堡","穆伦·风暴之矛","托姆斯·深炉","战士任务","武器锻造师"},ang={["class:Warrior"]="穆伦·风暴之矛会指引正在成长的战士前往铁炉堡寻找托姆斯·深炉，以证明他们的胆识并获得适合其残酷使命的定制武器。",["faction:Alliance"]="铁炉堡的武器锻造大师们经常会用危险的任务来考验那些有潜力的联盟战士，之后才会为他们打造精良的装备。"},sec={{t="铁匠的铁砧",b="托姆斯·深炉是一位驻扎在铁炉堡的矮人武器锻造大师。当战士向穆伦·风暴之矛展现出日益增长的实力时，他们会被派往城内去咨询托姆斯。托姆斯以锻造坚固而强力的武器而闻名，他不会随随便便就把精良的刀剑和锤斧交给任何走到他铁砧前的人——他要求战士通过行动来赢得他的手艺。"},{t="一项危险的试炼",b="在托姆斯同意为冒险者锻造武器之前，他会要求对方帮一个忙。以典型的矮人作风，他会直言不讳地警告前方的危险，强调这项任务确实会危及生命。对托姆斯而言，充满凶险和死亡可能性的任务并不是一种劝退，而是考验一个战士胆识的最佳手段。"}},faq={{q="谁是托姆斯·深炉？",a="托姆斯·深炉是一位造诣深厚的矮人武器锻造师，驻扎在铁炉堡的大熔炉旁。他能为那些证明了自己有能力且有勇气面对危险挑战的战士打造出卓越的武器。",al={"托姆斯是谁","托姆斯·深炉 铁炉堡","托姆斯·深炉是谁"}},{q="是谁让你去和托姆斯·深炉交谈的？",a="铁炉堡的资深战士训练师穆伦·风暴之矛会将那些有潜力的战士派去寻找托姆斯·深炉，当他们准备好打造适合其日益精进的武艺的武器时。",al={"谁派我去找托姆斯","为什么要和托姆斯交谈","穆伦·风暴之矛推荐"}},{q="托姆斯·深炉要求什么作为打造武器的回报？",a="托姆斯同意锻造一把精良的武器，但首先要求对方帮一个忙。他坚持要进行一项可能导致死亡的危险任务，并声称这正是那些有抱负的战士所寻求的挑战。",al={"托姆斯的请求","托姆斯会制作什么武器","托姆斯想要什么"}},{q="为什么托姆斯要强调这份工作很危险？",a="托姆斯心中所想的任务伴随着巨大的危险。他认为死亡任务不仅不会吓退战士，反而是检验一个人是否有资格使用他所锻造的武器的唯一正确标准。",al={"托姆斯·深炉危险吗","托姆斯的任务是什么","铁炉堡战士任务 托姆斯"}},{q="在哪里可以找到托姆斯·深炉？",a="托姆斯·深炉在矮人首都铁炉堡的大熔炉附近工作，周围环绕着其他的铁匠、铁砧和轰鸣的熔炉。",al={"托姆斯在哪里","托姆斯·深炉位置"}},{q="托姆斯·深炉与哪些冒险者合作？",a="托姆斯专门与那些由训练师指派的战士打交道，寻找那些具有武者胆识和决心去承担危及生命任务的人。",al={"哪个职业会接到托姆斯的任务","托姆斯只为战士服务吗"}}},fp="16,248,22.399.0,16.353.0,24.242.0,45.192.0,61.197.0,52.189.0,36.139.0,50.160.0"}
P.entries["quest:1681"] = {n="铁环营地",s="铁炉堡的铁匠托姆斯·深炉正在为他的导师斯特吉·铁环寻求复仇。斯特吉在丹莫罗东部的偏远教学营地遭到了一场突然且血腥的袭击。在那场屠杀之前，营地刚收到了一批罕见的暗影矿石，这立即引来了黑铁矮人们凶残的注意。",h="铁炉堡的铁匠托姆斯·深炉正在为他的导师斯特吉·铁环寻求复仇。斯特吉在丹莫罗东部的偏远教学营地遭到了一场突然且血腥的袭击。在那场屠杀之前，营地刚收到了一批罕见的暗影矿石，这立即引来了黑铁矮人们凶残的注意。",kw={"锻造","黑铁","丹莫罗","盔枕湖","铁环营地","斯特吉·铁环","托姆斯·深炉","暗影矿石"},ang={["profession:Blacksmithing"]="斯特吉·铁环的悲惨命运是一个警示，告诉人们对奇异、未经测试矿石的追求会给锻造者招致致命的危险。",["race:Dwarf"]="对铁环哨站的突袭突显了铁炉堡铜须矮人与其黑铁同胞之间挥之不去的深仇大恨。"},sec={{t="大师的陨落",b="斯特吉·铁环在铁炉堡备受尊崇，被誉为锻造工艺方面无与伦比的导师。他在盔枕湖以南的一处隐秘营地中教学，让那些有前途的学徒远离Great Forge那拥挤的铁砧。那段平静的教学生活在一名学生带回一种名为暗影矿石的陌生矿物后戛然而止。出于对矿石特性的好奇，铁环决定实验这一样本，但他完全没有意识到，拥有这种矿石已经让他所在的学校招致了灭顶之灾。"},{t="黑铁袭击",b="暗影矿石运抵营地后不久，充满敌意的黑铁矮人就对哨站发动了冷酷的突袭。袭击者没有表现出任何怜悯，他们在占领营地之前屠杀了斯特吉·铁环以及他照料下的每一名学徒。托姆斯·深炉是铁环幸存的徒弟之一，如今身在首都。他不愿坐视这场屠杀，便派遣联盟的旅行者去为他的老师复仇，并收回那块给营地带来毁灭的诅咒矿石。"}},faq={{q="铁环营地在哪里？",a="铁环营地位于丹莫罗东部，坐落在盔枕湖以南的雪山丘陵中。",al={"铁环位置","营地在哪里","寻找铁环营地"}},{q="斯特吉·铁环是谁？",a="斯特吉·铁环是一位著名的矮人锻造大师。他在铁炉堡外经营着一个专门的教学营地，在那里培训学生掌握高级金属加工工艺，直到在一场黑铁矮人的袭击中遇害。",al={"铁环是谁","斯特吉·铁环背景故事","斯特吉是谁"}},{q="为什么黑铁矮人要袭击这个营地？",a="袭击是由铁环的一名学生带回的一批暗影矿石引起的。矿石到达后不久，黑铁矮人就突袭了营地，杀光了在场的所有人并控制了该地点。",al={"为何袭击","为何黑铁突袭","黑铁动机"}},{q="什么是暗影矿石？",a="暗影矿石是一种罕见且神秘的矿物。铁环大师急于对其进行锻造，但它的出现立刻引来了黑铁氏族致命的兴趣。",al={"暗影矿石背景故事","什么是暗影矿石","奇异矿石"}},{q="托姆斯·深炉是谁？",a="托姆斯·深炉是铁炉堡的一名铁匠，也是斯特吉·铁环的前学徒。由于痛失恩师，他派遣冒险者去惩罚黑铁入侵者并寻回矿石。",al={"谁发布了铁环营地的任务","托姆斯·深炉背景故事","深炉是谁"}},{q="托姆斯想要从营地回收什么？",a="托姆斯指派旅行者消灭黑铁袭击者以祭奠铁环，并确保找回那批导致灾难的暗影矿石。",al={"要取回什么","营地任务目标","任务交付"}}},fp="19,307,15.487.0,18.496.0,37.101.0,24.208.0,50.230.0,19.169.0,24.205.0,50.149.0"}
P.entries["quest:1683"] = {n="沃鲁斯·邪蹄",s="Vorlus Vilehoof是年轻的暗夜精灵战士在达纳苏斯进行训练时的试炼之一。在战士训练师艾兰娜瑞的指导下，候选者必须狩猎并消灭一个亵渎了班奈希尔兽穴附近隐蔽月井的邪恶萨特。",h="Vorlus Vilehoof是年轻的暗夜精灵战士在达纳苏斯进行训练时的试炼之一。在战士训练师艾兰娜瑞的指导下，候选者必须狩猎并消灭一个亵渎了班奈希尔兽穴附近隐蔽月井的邪恶萨特。",kw={"班奈希尔","达纳苏斯","艾兰娜瑞","vorlus的角","月井","萨特","泰达希尔","vorlus vilehoof","战士任务"},ang={["class:Warrior"]="狩猎Vorlus Vilehoof是通往高级武技训练的入门仪式，证明了你的利刃是为了守护卡多雷的领土和女神的神圣而挥动。",["faction:Alliance"]="从潜伏的恶魔残党手中保卫泰达希尔的腹地，确保了达纳苏斯在北卡利姆多始终是联盟坚固的堡垒。",["race:NightElf"]="月井象征着月神之光的纯净，也是卡多雷精神的生命之源；容忍一个萨特在其中沐浴，是对所有暗夜精灵不可接受的侮辱。"},sec={{t="决心的考验",b="在艾兰娜瑞传授年轻的暗夜精灵战士更高级的武艺之前，她需要他们证明自己的奉献精神和纪律性。在保卫卡利姆多的战斗中，言语毫无意义；真正的卫士必须勇于直面腐化，并将泰达希尔的神圣枝叶从污秽中净化。"},{t="亵渎圣水",b="这次试炼的目标是Vorlus Vilehoof，一个潜入班奈希尔兽穴东南方群山中隐蔽月井的萨特。萨特，这些被恶魔力量扭曲的古老背叛者，对卡多雷的神圣遗物怀有永恒的仇恨。Vorlus在月井中沐浴，用他的存在玷污了神圣的井水，并亵渎了月神之光。"},{t="获取利角",b="找到Vorlus需要追踪一条被充满敌意的Gnarlpine熊怪守卫的隐蔽山路。一旦在受污染的泉水边将其围堵，就必须在格斗中将其击杀。将Vorlus的角带回达纳苏斯的战士区可以证明这头野兽已死，从而恢复隐秘林地的神圣，并开启通往专业武技武器的大门。"}},faq={{q="Vorlus Vilehoof是谁？",a="Vorlus Vilehoof是一个居住在泰达希尔的堕落萨特。他发现了一个位于班奈希尔兽穴东南方的隐蔽月井，并开始在其中沐浴，蓄意亵渎其神圣的井水。",al={"vorlus vilehoof背景故事","谁是vorlus","萨特vorlus"}},{q="为什么艾兰娜瑞要派遣战士去追捕Vorlus？",a="艾兰娜瑞将这次狩猎作为对有前途的战士的考验。击败像Vorlus这样危险而堕落的魔物，可以展示出战士在学习高级武技或在锻造特殊武器获得指引前所必须具备的专注、勇气和决心。",al={"为什么杀掉vorlus","艾兰娜瑞任务动机","vorlus vilehoof任务目标"}},{q="隐蔽的月井在哪里？",a="月井隐蔽在班奈希尔兽穴东南方的山脊中。要到达那里，需要找到一条位于兽穴东面Gnarlpine熊怪营地后方、点缀着火把的隐秘山径。",al={"vorlus位置","如何找到vorlus","隐蔽月井路径"}},{q="什么是月井？为什么他的存在事关重大？",a="月井是充满神圣之水的盆地，它们引导着月神之光并维系着大自然的生命力。像Vorlus这样的恶魔萨特在其中污秽亵渎，被视为对卡多雷信仰的直接冒犯，也是泰达希尔腐化的危险源头。",al={"为何月井重要","月井亵渎","暗夜精灵月井"}},{q="击败Vorlus Vilehoof之后会发生什么？",a="带回Vorlus被切下的角，艾兰娜瑞会对战士的表现表示满意，确认战士已准备好接受进一步的挑战。她随后会指引战士去寻找传奇的Elunite武器，并从发掘Elura之影开始。",al={"vorlus之后的下一个任务","接下来发生什么","elura之影任务"}},{q="泰达希尔还有其他萨特吗？",a="是的。尽管泰达希尔相对年轻，但萨特仍然潜伏在地狱石等地方以及零星散布的腐化空地中，不断试图用恶魔的污秽感染世界之树。",al={"泰达希尔的萨特","泰达希尔萨特威胁"}}},fx={["2a0bd33d"]={q="艾兰娜瑞为什么要杀死沃鲁斯·邪蹄？",a="对艾兰娜瑞和暗夜精灵而言，月亮井是盛满圣水的神圣圣所。沃鲁斯·邪蹄发现了班奈希尔兽穴东南方一处隐秘的月亮井，还肆意玷污它，把萨特的腐化污秽泼洒在神圣的池水中。艾兰娜瑞不能容忍泰达希尔上发生这样的亵渎，消灭这头野兽便能立即铲除这棵伟大巨树所面临的腐化威胁。",al={"艾兰娜瑞的动机","为什么杀死沃鲁斯","艾兰娜瑞对付沃鲁斯的理由"}}},fp="15,245,17.315.0,26.388.0,17.363.1,23.199.0,45.261.0,37.222.0,53.271.0,43.217.1,37.178.0"}
P.entries["quest:1685"] = {n="加科因的召唤",s="这是一份由雷门·玛考特代表黑暗缚灵者加科因发给有前途的联盟术士的召唤信。它指引初出茅庐的修行者前往暴风城Mage Quarter中Slaughtered Lamb下方的地穴，开始他们下一阶段的黑暗奥术训练。",h="这是一份由雷门·玛考特代表黑暗缚灵者加科因发给有前途的联盟术士的召唤信。它指引初出茅庐的修行者前往暴风城Mage Quarter中Slaughtered Lamb下方的地穴，开始他们下一阶段的黑暗奥术训练。",kw={"恶魔学","黑暗缚灵者加科因","mage quarter","雷门·玛考特","slaughtered lamb","暴风城","虚空行者","术士"},ang={["class:Warlock"]="这份召唤标志着你超越了戏法和小鬼，开始了奴役虚空行者以在战斗中保护你的必要试炼。",["faction:Alliance"]="即便是在暴风城的心脏地带，联盟也容忍着一个地下的暗影编织者结社，他们的邪能专长在对抗敌人时提供了一种阴影优势。"},sec={{t="一份隐秘的信息",b="恶魔学在暴风城的文明区域内是被严格禁止的，然而黑暗技艺却在城市卫兵的眼皮底下持续存在着。当术士展现出对初始小鬼足够的掌控能力时，消息会悄悄传达给资深修行者。雷门·玛考特会非常谨慎地传递这份信息，敦促学徒对会面地点保密，并前往Mage Quarter下方阴暗的角落。"},{t="Slaughtered Lamb的地穴",b="在Slaughtered Lamb旅店朴素的外表下，隐藏着一个潮湿的地窖和秘密墓穴网络。在这里，黑暗缚灵者加科因避开了肯瑞托法师和Cathedral of Light审判官的窥探，指导着暴风城的术士们。这份召唤是掌握虚空行者的门户，这一仪式需要危险的偷窃试剂和凶险的召唤法阵。"}},faq={{q="为什么黑暗缚灵者加科因要召唤术士？",a="当初出茅庐的术士达到足够的经验水平时，加科因就会召唤他们。他认为未受过训练的术士是个容易送命的累赘，并旨在指导他们完成将虚空行者束缚为己用的复杂仪式。",al={"为什么加科因要召唤","加科因的召唤有什么用","虚空行者任务开始"}},{q="黑暗缚灵者加科因在哪里？",a="加科因隐藏在暴风城Mage Quarter的Slaughtered Lamb旅店下方深处的地下墓穴中。",al={"加科因在哪里","加科因的位置","slaughtered lamb地下室"}},{q="雷门·玛考特是谁？",a="雷门·玛考特是暴风城术士集会的成员，他待在闪金镇的Lion's Pride Inn地窖里，寻找有前途的候选人，并将他们悄悄指引至加科因的秘密据点。",al={"雷门·玛考特","谁开启加科因的召唤"}},{q="为什么必须对位置保密？",a="邪能魔法和恶魔召唤在暴风城王国是被禁止的。一旦被白银之手、Cathedral of Light或城市卫兵发现，将会导致监禁或处决。",al={"为什么要保密","暴风城术士的隐秘性"}},{q="回应加科因的召唤后会发生什么？",a="向加科因报到后，他会指派术士前往艾尔文森林的布莱克威尔南瓜田，从苏蕾娜·卡雷登手中夺回血石颈环，这是虚空行者束缚仪式中必不可少的组件。",al={"加科因召唤后的下一个任务","接下来发生什么"}},{q="非术士可以收到这份召唤吗？",a="不可以。这份召唤严格限制于已经掌握了基础小鬼随从并需要进阶奥术指导的术士。",al={"法师能接到吗","谁能完成加科因的召唤"}}},fx={["0d517c2f"]={q="雷门·玛考特为什么要你去见加科因？",a="雷门·玛考特完全是在奉黑暗缚灵者加科因大师之命行事。他整整一天都在城里四处寻找你，为此已经烦透了。他只想完成差事，好不再追着你跑，回去处理自己的事情；他还警告你尽快去报到，免得你的师父失去耐心。",al={"雷门为什么派你去找加科因","雷门·玛考特的动机","雷门为什么在找你"}}},fp="15,265,18.434.0,34.392.0,46.241.0,38.128.0,20.204.0,37.188.0,43.219.1,38.135.0"}
P.entries["quest:1686"] = {n="艾鲁拉的阴影",s="“艾露拉的阴影”是暗夜精灵年轻战士早期的一次成人礼，由达纳苏斯的战士训练师艾兰娜瑞指导。该任务要求战士潜入奥伯丁附近的水域，让一位受折磨的海上船长之魂安息，并打捞成箱的稀有艾露尼矿石。获取这些材料是打造定制化战术武器的基础。",h="“艾露拉的阴影”是暗夜精灵年轻战士早期的一次成人礼，由达纳苏斯的战士训练师艾兰娜瑞指导。该任务要求战士潜入奥伯丁附近的水域，让一位受折磨的海上船长之魂安息，并打捞成箱的稀有艾露尼矿石。获取这些材料是打造定制化战术武器的基...",kw={"奥伯丁","黑海岸","达纳苏斯","艾兰娜瑞","艾露尼矿石","艾露拉","艾露拉的阴影","铁匠马希尔","艾露尼武器"},ang={["class:Warrior"]="这项任务是暗夜精灵战士职业生涯中决定性的一步，考验着他们的水性与战术纪律，从而换取一把艾露尼锻造的武器。",["profession:Blacksmithing"]="对沉没艾露尼的打捞凸显了暗夜精灵独特的冶金传统，他们用受到祝福的材料打造强大的武器。",["race:NightElf"]="让艾露拉的阴影安息，是为了纪念一位卡多雷同胞，她那无限的责任感曾使她被困在波涛之下长达数代之久。"},sec={{t="船长的永恒守卫",b="很久以前，一艘载有稀有艾露尼矿石的船只在奥伯丁灯塔附近的崎岖海岸岩石上触礁沉没。出于对职责的绝望与坚定忠诚，这艘船的船长艾露拉对自己施下诅咒。她的阴影被束缚在波涛之下的残骸中，徘徊在海床上，抵御着任何胆敢打扰她失落货物的闯入者。"},{t="艾露尼武器",b="对于刚刚成长的暗夜精灵战士来说，获得他们第一件真正的精制武器不仅需要战术技巧，还需要对阵亡同胞的尊重。训练师艾兰娜瑞派遣有抱负的战士们前往黑海岸寒冷的海浪中，这不仅是为了打捞金属，也是为了击败艾露拉的阴影并寻回她的奖章。让艾露拉安息不仅能将这位受诅咒的船长从守望中解脱出来，还能收获铁匠马希尔的熔炉所需的原始矿石。"}},faq={{q="谁是艾露拉的阴影？",a="艾露拉曾是一艘精灵船的船长，这艘船在奥伯丁灯塔附近的暗礁浅滩上遇难。她没有放弃自己的职责，而是在生前或死后对自己施加诅咒，永远警惕地守卫着她那沉入海底的艾露尼矿石货物。",al={"艾露拉的阴影背景知识","艾露拉是谁","艾露拉船长"}},{q="为什么艾兰娜瑞要派遣战士去对付艾露拉？",a="艾兰娜瑞既是为了让艾露拉那受折磨的灵魂获得平静，也是为了收回沉没的艾露尼矿石。击败这位船长并夺取她的奖章，既是对年轻战士勇武的证明，也确保了锻造上等武器所需的原材料。",al={"为什么我们要击败艾露拉","艾兰娜瑞任务的目的"}},{q="海难发生在什么地方？",a="沉船位于黑海岸奥伯丁的海岸外，靠近灯塔，就在主要港口码头的南面，零星散落在海底。",al={"沉船在哪里","艾露拉的船只位置"}},{q="艾露尼矿石有什么用途？",a="艾露尼是一种暗夜精灵铁匠所珍视的稀有矿石。在这次试炼中，打捞上来的板条箱会被送到达纳苏斯的铁匠马希尔那里，为有前途的战士锻造一件个性化的战术武器。",al={"什么是艾露尼","艾露尼矿石的用途"}},{q="击败阴影会对艾露拉造成永久性的伤害吗？",a="击败她的阴影可以打破束缚她灵魂于海底的自加诅咒。正如艾兰娜瑞所言，在战斗中战胜她，能让这位船长在经历漫长、寒冷且幽灵般的守望后获得渴望已久的平静。",al={"艾露拉死了吗","艾露拉获救了吗"}},{q="收集到矿石后，由谁来制作武器？",a="一旦艾兰娜瑞收到矿石和奖章，她就会指引战士前往达纳苏斯战士区的铁匠马希尔那里，由他将金属锻造成一把卓越的武器。",al={"谁制作艾露尼武器","艾露拉之后的下一个任务"}}},fx={["522232db"]={q="艾兰娜瑞为什么派你去取矿石，而不是自己去？",a="作为你的战士训练师，艾兰娜瑞正在引导你完成通往真正武艺精通之路的成年仪式。取回艾露恩矿石不只是为达纳苏斯跑一趟腿；你必须勇闯奥伯丁外危险的深处，并让船长埃鲁拉的躁动灵魂安息，以此证明自己拥有挥舞战士专属锻造武器所需的勇气与本领。",al={"为什么让我处理埃鲁拉之影","艾兰娜瑞为什么派战士去","为什么不派卫兵处理埃鲁拉"}}},fp="18,370,25.362.0,18.423.0,26.254.0,44.248.0,27.157.0,29.206.0,48.206.0,48.173.0"}
P.entries["quest:1688"] = {n="苏伦娜·凯尔东",s="Surena Caledon 是由暴风城的 Slaughtered Lamb 下方隐藏地下室里的黑暗缚灵者加科因所发布的术士训练任务。加科因派遣一名术士学徒去追捕他曾经的学生，因为她背叛了他并投靠了迪菲亚潜行者，学徒的任务是取回一条珍贵的血石颈环。",h="Surena Caledon 是由暴风城的 Slaughtered Lamb...",kw={"血石颈环","布莱克威尔南瓜田","迪菲亚","erlan drudgemoor","黑暗缚灵者加科因","slaughtered lamb","surena caledon","虚空行者"},ang={["class:Warlock"]="猎杀 Surena Caledon 是联盟术士的试金石，证明背叛会招致致命的代价，而情感的依恋在黑暗艺术中毫无立足之地。",["race:Human"]="Surena 的叛逃凸显了迪菲亚潜行者对暴风城内不满的公民们持续的诱惑力。"},sec={{t="苦涩的导师",b="在 Mage Quarter 的 Slaughtered Lamb 酒馆下方，黑暗缚灵者加科因正在训练新手学习禁忌的邪能召唤术。然而，加科因的判断并非总是准确的。在招收新学徒之前，他曾教导过一名叫 Surena Caledon 的年轻女子，并对她潜藏的魔法天赋和美貌赞赏有加。然而，Surena 放弃了学业，辜负了加科因的青睐，逃离了城市，与她的爱人 Erlan Drudgemoor 一起加入了迪菲亚潜行者。"},{t="被窃的血石",b="在 Surena 离开后，加科因对她的死活并不关心，但他拒绝失去他在她受训期间送给她的那条珍贵的血石颈环。他派他最新的学徒前往东南方的艾尔文森林的布莱克威尔南瓜田，那里已被迪菲亚强盗占据，并明确指示无论用什么手段都要把这颗宝石从 Surena 身上拿回来。取回的血石是学徒进行下一次试炼所需的魔法催化剂：召唤并束缚一名虚空行者。"}},faq={{q="Surena Caledon 是谁？",a="Surena Caledon 曾是暴风城黑暗缚灵者加科因门下的一名术士学徒。她天资聪颖，在加科因放弃她的技艺并与一名叫 Erlan Drudgemoor 的迪菲亚强盗私奔之前，曾深受加科因的青睐并获得过他的馈赠。",al={"surena 传说","surena 是谁","surena caledon 背景故事"}},{q="为什么加科因想要回她的颈环？",a="这条颈环上镶嵌着一颗珍贵的血石，是加科因在 Surena 当学徒期间送给她的。除了对她的偷窃和背叛感到愤怒外，加科因还需要这块石头所蕴含的黑暗共鸣作为仪式试剂，来帮助他新的学徒束缚一名虚空行者。",al={"为什么要拿回颈环","血石颈环的重要性"}},{q="在哪里可以找到 Surena Caledon？",a="Surena 躲藏在艾尔文森林东南部的一处废弃农场——布莱克威尔南瓜田，与她的迪菲亚同伙在一起。",al={"surena 的位置","哪里可以找到 surena","布莱克威尔南瓜田在哪里"}},{q="取回颈环后会发生什么？",a="将血石颈环交还给加科因即可完成此项试炼，并开启下一个任务：进入 Slaughtered Lamb 下方地穴中的召唤法阵，从扭曲虚空束缚一名虚空行者。",al={"what comes next","surena 之后的下一个任务"}},{q="Erlan Drudgemoor 是谁？",a="Erlan Drudgemoor 是一名隶属于迪菲亚潜行者的潜行者，他诱惑了 Surena Caledon 并说服她放弃术士训练，逃离暴风城，去强盗中生活。",al={"erlan 传说","erlan drudgemoor 是谁"}},{q="加科因对 Surena 的命运有任何悔意吗？",a="完全没有。加科因公开宣称她的死活对他来说已经无关紧要，并冷酷地表示，虽然浪费了魔法天赋很可惜，但她的背叛使除掉她成为必要之举。",al={"加科因在乎吗","加科因对 surena 的反应"}}},fp="14,196,15.376.0,21.419.1,22.198.0,36.201.0,34.128.0,41.199.1,24.176.0,47.179.0"}
P.entries["quest:1689"] = {n="誓缚",s="“统御”是联盟术士早期训练中的最后一道试炼，需要在暴风城召唤并奴役一名虚空行者。在黑暗缚灵者加科因的指导下，这名初出茅庐的召唤师将利用找回的血石颈环，把一个深渊爪牙拉入隐藏的地下法阵，并将其打至屈服。",h="“统御”是联盟术士早期训练中的最后一道试炼，需要在暴风城召唤并奴役一名虚空行者。在黑暗缚灵者加科因的指导下，这名初出茅庐的召唤师将利用找回的血石颈环，把一个深渊爪牙拉入隐藏的地下法阵，并将其打至屈服。",kw={"统御","血石颈环","黑暗缚灵者加科因","mage quarter","slaughtered lamb","暴风城","召唤法阵","虚空行者"},ang={["class:Warlock"]="这场成年礼为术士提供了他们的主要防御爪牙，标志着他们从鲁莽的初学者转变为异维度力量的指挥者。",["faction:Alliance"]="尽管联盟推崇圣光与奥术秩序，但务实的领导者们对于在法师区下方运作的黑暗修行者采取了睁一只眼闭一只眼的态度，因为他们认识到在危难时期这些残酷艺术的必要性。",["race:Gnome"]="侏儒术士以冷静的好奇心对待黑暗召唤，在加科因的指导下，将奴役虚空实体视为一种精确的形而上学实验。",["race:Human"]="人类术士必须应对暴风城祭司阶层的严密审查，在阴影中掌握危险的实体，同时将他们的力量隐藏在城市上方之人的视线之外。"},sec={{t="地窖中的征服",b="在暴风城法师区的“屠宰场之羊”酒馆下方，蜿蜒着一座被遗忘的地下墓穴，远离了白银之手与肯瑞托法官们的监视。在这里，黑暗缚灵者加科因教导新手修行者：掌握黑暗艺术不仅仅是引导魔法流，更重要的是对来自异界的实体行使绝对的统治。在从Surena Caledon手中夺回加科因被盗的血石颈环后，术士必须将其召唤到酒馆下方的召唤法阵中，将其直接引出。"},{t="对虚空的意志压制",b="虚空行者无法通过谈判解决，必须将其打倒。利用血石颈环内潜藏的力量，召唤师可以撕开一道裂隙，将一个暗影生物拉入凡世。为了完成契约，术士必须在物理和魔法层面上痛击该实体，直到其意志粉碎，从而证明自己的权威。一旦被制服，虚空行者的精华便会与施法者绑定，为术士提供一名坚韧的暗影护卫，足以在未来的战斗中吸收残酷的伤害。"}},faq={{q="召唤法阵在哪里？",a="召唤法阵位于暴风城法师区“屠宰场之羊”下方的地下墓穴深处。从黑暗缚灵者加科因所在的位置出发，沿着楼梯向下进入地下通道，直到你抵达最底层的密室，那里有着散发紫色光芒的符文，刻在石地板上。",al={"召唤法阵位置","我在哪里召唤虚空行者","法阵在哪里"}},{q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一名术士训练师，他在暴风城“屠宰场之羊”酒馆下方秘密运作。他私下里教导那些有潜力的术士学徒（人类与侏儒）如何召唤、奴役以及控制恶魔和虚空生物，同时不引起城卫队或教会当局的注意。",al={"谁是加科因","黑暗缚灵者加科因背景","加科因"}},{q="血石颈环有什么用？",a="血石颈环是一件魔法护身符，之前被Surena Caledon偷走。它注入了集中的魔法力量，作为一种催化剂，允许初级术士撕开帷幕，并将一只桀骜不驯的虚空行者拉入指定的召唤法阵中。",al={"血石颈环用途","为什么需要颈环","颈环"}},{q="为什么术士必须与他们的恶魔战斗才能将其奴役？",a="像恶魔和虚空生物这样的异位面实体不会心甘情愿地服务于凡人主人。术士必须通过战斗在物理或魔法上击垮这些生物，以展示其卓越的力量和钢铁般的意志，然后再建立一种永久的从属契约。",al={"为什么要与虚空行者战斗","为什么要奴役恶魔","恶魔奴役"}},{q="仪式完成后会发生什么？",a="一旦生物被击败且颈环归还给加科因，术士就获得了召唤并指挥忠诚虚空行者所需的知识和仪式技巧，使其在旅途中保护自己。",al={"我能得到什么奖励","虚空行者法术","统御仪式之后"}},{q="为什么这个仪式要秘密地在酒馆下方进行？",a="恶魔学和虚空魔法属于严格禁忌，圣光教会和联盟的法师们对此持强烈的敌意。暴风城的术士们在隐藏的地下室和墓穴中运作，以便在远离当局监视的地方练习这些禁忌艺术。",al={"为什么隐藏在酒馆下","邪能魔法是否非法","屠宰场之羊地下室"}}},fp="11,184,25.450.0,28.374.0,38.275.0,28.258.0,39.183.0,56.150.0,41.170.0,56.215.0"}
P.entries["quest:169"] = {n="通缉：加塞尔佐格",s="“通缉：加塞尔佐格”是赤脊山发布的一项联盟悬赏任务，旨在针对石堡黑石氏族入侵背后的军阀。所罗门镇长为任何有胆量攻打这座被占领的要塞并带回指挥官首级的人提供了丰厚的奖励。",h="“通缉：加塞尔佐格”是赤脊山发布的一项联盟悬赏任务，旨在针对石堡黑石氏族入侵背后的军阀。所罗门镇长为任何有胆量攻打这座被占领的要塞并带回指挥官首级的人提供了丰厚的奖励。",kw={"黑石","悬赏","加塞尔佐格","湖畔镇","所罗门镇长","赤脊山","石堡","通缉令"},ang={["class:Warrior"]="想要突破石堡要塞的顶峰，意味着要面对久经沙场的精锐战士，以及黑暗部落前线指挥部那野蛮的力量。",["faction:Alliance"]="击杀加塞尔佐格消除了对王国东部边境最直接的军事威胁之一，为湖畔镇的居民争取到了至关重要的喘息机会。",["race:Human"]="对于暴风城的民众来说，石堡要塞曾是一座来之不易的堡垒；加塞尔佐格在攻陷此地时对无辜平民的屠杀，使这份悬赏带上了苦涩的复仇色彩。"},sec={{t="石堡的军阀",b="加塞尔佐格是负责指挥黑石氏族在赤脊山各地劫掠的残暴指挥官。在他的指挥下，兽人们突袭并占领了石堡要塞，将一座曾经的人类堡垒变成了攻击周边定居点的坚固中转站。从要塞的最高城墙上，他策划着对湖畔镇的进一步入侵，企图将赤脊山与王国其他地区切断。"},{t="被逼到绝境的城镇",b="由于暴风城的皇家军队未能向边境地区部署增援，所罗门镇长不得不亲自采取行动。湖畔镇缺乏足够的军事力量来武力收复石堡要塞。通过对加塞尔佐格发出公开悬赏，所罗门旨在铲除黑石氏族的领导层，并开启为王国收复这座要塞的第一步。"}},faq={{q="谁是加塞尔佐格？",a="加塞尔佐格是一名兽人军阀，领导着占领石堡的黑石氏族部队。他指挥了对这座要塞的征服，并对频繁发生的针对湖畔镇人类定居者的致命袭击负有责任。",al={"加塞尔佐格背景故事","谁是加塞尔佐格","赤脊山黑石领袖"}},{q="在哪里可以找到加塞尔佐格？",a="他盘踞在石堡要塞的最顶端，该要塞位于赤脊山的东部山脊。他身边有黑石冠军勇士和保镖严密守卫。",al={"加塞尔佐格位置","加塞尔佐格在哪里","石堡首领位置"}},{q="为什么所罗门镇长要发放悬赏而不是派遣士兵？",a="湖畔镇当地的城镇卫兵已捉襟见肘，而暴风城的王室也没有派遣必要的部队来支援该地区。所罗门镇长不得不依靠雇佣兵和独立冒险者来应对重大威胁。",al={"为什么发布悬赏","暴风城的士兵在哪里","湖畔镇卫兵支援"}},{q="加塞尔佐格被杀后会发生什么？",a="所罗门镇长认为这名军阀的死是清除兽人侵略并最终为暴风王国收复石堡要塞的关键第一步，尽管该地区的黑石氏族势力依然庞大。",al={"石堡收复了吗","加塞尔佐格之后"}},{q="黑石兽人为什么要入侵石堡要塞？",a="黑石氏族将石堡要塞用作一座坚固的前进基地。它坐落在赤脊山的高处，使他们能够从战略上控制通道，并成为袭击人类定居点的直接出发点。",al={"为什么黑石在赤脊山","为什么石堡被占"}},{q="加塞尔佐格死后，谁来领取悬赏？",a="悬赏必须直接交给湖畔镇市政厅的所罗门镇长，并附上加塞尔佐格的首级作为他被击败的确凿证据。",al={"向谁上交加塞尔佐格的首级","加塞尔佐格任务上交"}}},fx={["1d021e94"]={q="湖畔镇为什么要杀死加塞尔佐格？",al={"为什么杀死加塞尔佐格","为什么要加塞尔佐格的悬赏","所罗门为什么要加塞尔佐格死"}},["69773e29"]={q="加塞尔佐格的头颅有什么用？",a="这颗头颅能确凿无疑地证明黑石军阀确实已经倒下。在发放镇上的悬赏，并让惊慌失措的湖畔镇居民相信袭击的幕后主使已被解决之前，所罗门镇长需要加塞尔佐格死亡的确切证据。",al={"加塞尔佐格的头颅有什么用","为什么要收集加塞尔佐格的头颅","加塞尔佐格的头颅该怎么处理"}}},fp="19,281,25.414.0,26.396.0,19.208.0,31.173.0,72.237.0,41.240.0,50.228.0,47.154.0"}
P.entries["quest:1690"] = {n="废土的公正",s="来自加基森水业公司的首席工程师沙克斯·比格维兹称，荒漠流浪者游牧民现在控制了塔纳利斯沙漠中几乎所有的水井。你被派往加基森东部，去对荒漠强盗和荒漠窃贼执行正义。",h="来自加基森水业公司的首席工程师沙克斯·比格维兹称，荒漠流浪者游牧民现在控制了塔纳利斯沙漠中几乎所有的水井。你被派往加基森东部，去对荒漠强盗和荒漠窃贼执行正义。",kw={"强盗","沙克斯·比格维兹","加基森","塔纳利斯","窃贼","荒漠流浪者","水业公司","水井"},sec={{t="为水井讨回公道",b="在塔纳利斯沙漠中，荒漠流浪者游牧民现在控制了几乎所有的水井，如果无法使用这些水井，加基森的供水很快就会枯竭。首席工程师沙克斯·比格维兹，一个偏爱地精式正义的人，要求你在镇子东边消灭十个荒漠强盗和荒漠窃贼，然后立即回去报告。"},{t="远未结束",b="沙克斯·比格维兹对工作的进展速度感到满意。这些游牧民的数量已经减少到公司可以开始考虑夺回水井的程度，尽管与这些可恶的游牧民之间的斗争还远未结束，他还有更多的计划。"}},faq={{q="首席工程师沙克斯·比格维兹是谁？",a="加基森水业公司的首席工程师，位于加基森。",al={"沙克斯·比格维兹","谁发布了为水井讨回公道任务","加基森水业公司工程师"}},{q="为什么加基森水业公司要对付荒漠流浪者？",a="荒漠流浪者游牧民控制了沙漠中几乎所有的水井，如果无法使用它们，加基森的供水就会枯竭。",al={"为什么要杀死荒漠强盗","荒漠流浪者正义的原因","为什么要攻击塔纳利斯的游牧民"}},{q="荒漠强盗和荒漠窃贼位于何处？",a="在加基森东部的沙漠里。",al={"在哪里可以找到荒漠强盗","荒漠强盗位置","塔纳利斯的窃贼位置"}}},fp="19,230,21.320.0,13.223.1,35.62.0,64.131.0,54.44.0"}
P.entries["quest:1691"] = {n="废土的公正",s="位于加基森的首席工程师沙克斯·比格维兹现在将矛头指向了更难对付的废土游民：那些潜行者、刺客和暗影法师，它们盘踞在城镇的东部和东南部。留下的游民越少，夺回水井的工作就越容易。",h="位于加基森的首席工程师沙克斯·比格维兹现在将矛头指向了更难对付的废土游民：那些潜行者、刺客和暗影法师，它们盘踞在城镇的东部和东南部。留下的游民越少，夺回水井的工作就越容易。",kw={"刺客","比格维兹","加基森","暗影法师","塔纳利斯","废土游民","水业公司"},sec={{t="更强的敌手",b="在首席工程师沙克斯·比格维兹看来，你目前做得很好，但想要夺回水井，就必须尽可能减少游民的数量。现在的目标是那些盘踞在加基森东部和东南部的游民潜行者、刺客和暗影法师。首席工程师沙克斯·比格维兹承认这些家伙很难对付，但他坚持认为这些水井理应属于公司。"},{t="主动出击",b="游民的数量已经少到足以让公司主动出击了。首席工程师沙克斯·比格维兹建议你去找镇上的操作员鲁格伦克谈谈，他对你在对付游民时获得的任何废土游民水袋都提供赏金。"}},faq={{q="谁发出的请求？",a="位于加基森的加基森水业公司的首席工程师沙克斯·比格维兹。",al={"谁发布了更多废土游民的正义任务","任务发布者"}},{q="为什么加基森水业公司想要清除这些游民？",a="公司想要夺回水井，而清除的游民越多，夺回水井的任务就越轻松。",al={"为什么要杀废土游民","比格维兹的动机"}},{q="这些游民目标在哪里可以找到？",a="位于加基森的东部和东南部，也就是那些游民聚集的地方。",al={"废土游民潜行者在哪里","去哪里找暗影法师"}},{q="这一步之前是什么？",a="这任务紧接在“废土游民的正义”之后。",al={"先决条件","前置任务"}}},fp="24,242,18.322.0,24.255.1,18.73.0,63.101.0,39.66.0,28.31.0"}
P.entries["quest:1692"] = {n="铁匠玛希尔",s="“铁匠马斯希尔”是达纳苏斯的一项核心战士任务，标志着战士从初出茅庐到装备精良的转变。在奥伯丁附近的沉船处寻回神圣的月神之矿后，雄心勃勃的战士会将矿石交给铁匠大师马斯希尔。他同意将这种受过祝福的金属打造成足以捍卫卡多雷的武器。",h="“铁匠马斯希尔”是达纳苏斯的一项核心战士任务，标志着战士从初出茅庐到装备精良的转变。在奥伯丁附近的沉船处寻回神圣的月神之矿后，雄心勃勃的战士会将矿石交给铁匠大师马斯希尔。他同意将这种受过祝福的金属打造成足以捍卫卡多雷的武...",kw={"战士区","达纳苏斯","艾兰娜瑞","月神之矿","马斯希尔","铁匠","战士"},ang={["class:Warrior"]="对于年轻的卡多雷战士来说，将月神之矿带给马斯希尔是一种成人礼，意味着他们将用普通的训练用剑换取由月之女神祝福过的定制武器。",["profession:Blacksmithing"]="马斯希尔对月神之矿的崇敬，凸显了卡多雷铁匠如何将神圣祝福融入锻造工艺，而非仅仅依赖蛮力和高温。",["race:NightElf"]="加工月神之矿将暗夜精灵的精湛工艺与对艾露恩的虔诚信仰结合在一起，证明了武力与神圣信仰是相辅相成的。"},sec={{t="神圣的交付",b="在奥伯丁附近的闹鬼沉船处找回月神之矿，并在战士训练师艾兰娜瑞的帮助下将其妥善保管后，年轻的暗夜精灵战士会被指引穿过达纳苏斯的战士区。艾兰娜瑞会将矿石小心地装入坚固的盒中，并指示新手去寻找首都最顶尖的铁匠之一——马斯希尔，请他打造一件配得上他们战士身份的武器。"},{t="月神之矿的祝福",b="马斯希尔不仅将锻造视为体力劳动，更将其视为一种虔诚的技艺。月神之矿并非普通的矿石，它承载着月之女神艾露恩的神圣祝福。当收到装着矿石的盒子时，马斯希尔欣然接下了这个任务，他认为能将这种圣洁的金属锻造成捍卫泰达希尔幼苗的武器，是一种莫大的荣幸。"}},faq={{q="铁匠马斯希尔是谁？",a="马斯希尔是一位技艺精湛的暗夜精灵铁匠，驻守在达纳苏斯的战士区。他负责打造特种军械，并为达纳苏斯的保卫者们提供定制锻造服务。",al={"马斯希尔是谁","铁匠马斯希尔","马斯希尔在哪里"}},{q="月神之矿有什么特别之处？",a="月神之矿是一种稀有金属，因其受到艾露恩本人的祝福而受到暗夜精灵的尊崇。像马斯希尔这样的铁匠将其视为至高荣誉，利用其神圣的属性来打造强大的武器。",al={"什么是月神之矿","月神之矿有魔力吗","月神之矿背景知识"}},{q="是谁指引你去找马斯希尔的？",a="艾兰娜瑞，一位居住在达纳苏斯战士区的杰出战士训练师，她会将你找回的矿石打包，并指引你前往就在战士区对面的马斯希尔处。",al={"谁发布铁匠马斯希尔任务","铁匠马斯希尔任务发布者"}},{q="这个任务只有战士才能接吗？",a="是的。这是10级战士职业任务线的一部分，旨在为年轻的战士装备他们的第一件专业军用武器。",al={"战士限定","其他职业可以做铁匠马斯希尔任务吗"}},{q="在达纳苏斯的什么地方可以找到马斯希尔？",a="马斯希尔在达纳苏斯的战士区工作，位于艾兰娜瑞所在建筑的南侧对面。",al={"马斯希尔位置","寻找马斯希尔"}},{q="将矿石交给马斯希尔后会发生什么？",a="马斯希尔会开始将月神之矿锻造成型，并立即提供后续任务，让你选择最适合你战斗风格的月神之矿武器。",al={"铁匠马斯希尔之后是什么","铁匠马斯希尔的后续任务"}}},fx={["4e03f025"]={q="艾兰娜瑞为什么派你去找铁匠马希尔？",a="艾兰娜瑞是你在达纳苏斯的战士训练师，她的职责是监督你的训练，并为你装备好迎接未来的挑战。你从黑海岸收集到神圣的艾露恩矿石后，她将矿石妥善装箱，以便精通圣金工艺的工匠铁匠马希尔能把它锻造成一件适合精灵战士使用的武器。",al={"艾兰娜瑞的动机","为什么派我去找马希尔","艾兰娜瑞和马希尔的事"}}},fp="13,330,17.400.0,23.351.0,21.180.0,34.209.0,25.167.0,41.143.0,40.107.0,50.170.0"}
P.entries["quest:1693"] = {n="月神武器",s="“艾露尼之刃”是达纳苏斯暗夜精灵战士早期成人礼的终章。在找回受过艾露恩祝福的原始矿石后，战士会将材料带给技艺精湛的铁匠玛希尔，将其锻造成适合卡利姆多守护者的武器。",h="“艾露尼之刃”是达纳苏斯暗夜精灵战士早期成人礼的终章。在找回受过艾露恩祝福的原始矿石后，战士会将材料带给技艺精湛的铁匠玛希尔，将其锻造成适合卡利姆多守护者的武器。",kw={"达纳苏斯","艾露恩","艾露尼","卡多雷","玛希尔","泰达希尔","战士","武器匠"},ang={["class:Warrior"]="这项任务代表了年轻卡多雷战士军事服役早期必不可少的成人礼，以可靠的、受艾露恩祝福的武器来奖励他们的奉献精神。",["profession:Blacksmithing"]="铁匠玛希尔的技艺展示了传统金属工艺与处理艾露尼这种神圣材料之间的微妙平衡。",["race:NightElf"]="艾露尼矿石的锻造反映了暗夜精灵社会是如何将对月神的崇敬直接融入到战争与防御的实用技艺之中的。"},sec={{t="神圣的锻造",b="暗夜精灵战士肩负着保卫泰达希尔和卡多雷人民的神圣职责。对于那些展现出潜力的战士，他们不会仅仅依赖凡铁，而是被派去收集艾露尼矿石——这是一种注入了月神恩典的矿物。锻造这种武器需要一位既懂得金属工艺，又对艾露恩的馈赠心怀敬意的匠人。"},{t="玛希尔的技艺",b="铁匠玛希尔居住在首都达纳苏斯，他以将这种受祝福的矿石塑造成战争武器而深感自豪。对玛希尔来说，使用艾露尼矿石工作不仅仅是常规的冶金，更是一种殊荣。收到矿石后，他会根据战士的风格量身打造一系列工具，用受他们女神祝福的武器来奖赏战士的功绩。"}},faq={{q="这个任务的目的是什么？",a="这个任务标志着达纳苏斯早期战士试炼的完成。在获得稀有的艾露尼矿石后，战士将其交付给铁匠玛希尔，玛希尔会铸造出注入了艾露恩精魄的可靠武器，以助他们踏上卡利姆多的旅程。",al={"艾露尼之刃任务","为什么要做这个任务","10级战士达纳苏斯"}},{q="玛希尔是谁？",a="玛希尔是居住在达纳苏斯的一位技艺精湛的暗夜精灵盔甲匠和武器匠。他拥有将艾露尼矿石锻造成适合这座城市初露锋芒的守护者使用的精良平衡武器所需的专业知识。",al={"铁匠玛希尔","玛希尔是谁","达纳苏斯铁匠"}},{q="什么是艾露尼矿石？",a="艾露尼矿石是一种对暗夜精灵而言神圣的稀有矿物，据信注入了月神艾露恩的光辉与眷顾。由于其神圣的本质，工匠们将其塑造成武器被视为一种庄严的荣誉。",al={"什么是艾露尼矿石","艾露尼传说"}},{q="谁可以接受这个任务？",a="此任务仅限于在达纳苏斯周围训练，并且已经完成了寻找并收集艾露尼矿石给铁匠玛希尔的初步任务的联盟战士。",al={"谁获得艾露尼之刃","这是战士专属吗"}},{q="这个任务在哪里进行？",a="该任务直接在暗夜精灵首都达纳苏斯交付给铁匠玛希尔，达纳苏斯坐落于世界之树泰达希尔的高大枝干之上。",al={"艾露尼之刃地点","玛希尔在哪里"}},{q="为什么玛希尔要感谢冒险者？",a="玛希尔认为与艾露尼矿石共事既是一种神圣的荣誉，也是一种个人的乐趣。塑造与艾露恩相关联的矿石是极少数铁匠才能获得的殊荣，这使得战士的交付对这位匠人来说也是一种福祉。",al={"为什么玛希尔感到荣幸","玛希尔对话"}}},fx={cb47846f={q="马希尔为什么让你来做这件事，而不是找卫兵？",a="这项委托是对有潜力的年轻战士的成年考验，而非正式的公务。哨兵和神殿卫兵肩负保卫达纳苏斯与泰达希尔、抵御现实威胁的职责，没有闲暇替个人武器收集稀有锻造材料。亲自承担收集矿石的劳作，能证明你的投入与自律，让你赢得一件专为契合自身武艺之路而锻造的武器。",al={"为什么派我去","为什么让我去找马希尔","为什么要战士去"}}},fp="18,261,14.349.0,15.350.0,34.255.0,15.215.0,16.223.0,29.168.0,33.151.0,38.211.0"}
P.entries["quest:1698"] = {n="犹鲁斯·麦酒",s="约鲁斯·麦酒是联盟的一名战士召集人，他将经验丰富的战士从暴风城引向赤脊山的边境。该任务由联盟各主城的武器训练师发布，旨在派遣雄心勃勃的战士前往湖畔镇的Lakeshire Inn，迎接一位矮人设下的致命挑战。",h="约鲁斯·麦酒是联盟的一名战士召集人，他将经验丰富的战士从暴风城引向赤脊山的边境。该任务由联盟各主城的武器训练师发布，旨在派遣雄心勃勃的战士前往湖畔镇的Lakeshire Inn，迎接一位矮人设下的致命挑战。",kw={"kelv sternhammer","湖畔镇","lakeshire inn","赤脊山","雷斯班","暴风城","战士","wu shen","约鲁斯·麦酒"},ang={["class:Warrior"]="这项任务标志着联盟战士成长过程中的一个重要仪式，使他们从入门训练转向赤脊山边境的危险试炼。",["faction:Alliance"]="麦酒的挑战将有能力的武力新兵直接带到湖畔镇，这是一个目前正受到豺狼人和黑石兽人围困的脆弱定居点。"},sec={{t="强者的召唤",b="包括Kelv Sternhammer、Wu Shen和Darnath Bladesinger在内的联盟各主城武器训练师，一直在密切关注着那些已经掌握基础训练的战士。当学徒在二十岁左右证明了自己的实力后，这些大师就会向他们提到一位名叫约鲁斯·麦酒的矮人。麦酒并没有发布标准的军事指令，而是向任何有胆量接受挑战的联盟战士发出了一场公开的赌约和武力测试。"},{t="在湖畔镇等待",b="麦酒驻扎在湖畔镇的旅店里，这里正是赤脊山对抗不断侵袭的豺狼人和黑石兽人的前线。那些找到他的人会看到一个手里拿着烈酒的傲慢矮人，他随时准备评估任何声称拥有真正战斗精神的挑战者。对于那些渴望在暴风城安全但狭窄的街道之外证明自己的战士来说，他的试炼标志着他们踏入了更为残酷的边境战斗。"}},faq={{q="谁是约鲁斯·麦酒？",a="约鲁斯·麦酒是一位与著名的麦酒酿造家族有关的矮人，他向联盟战士发出了公开的武力挑战。他驻扎在Lakeshire Inn，旨在测试那些认为自己已经为残酷的赤脊山边境做好准备的战士。",al={"约鲁斯·麦酒","谁是麦酒","湖畔镇旅店的矮人"}},{q="为什么训练师要把战士派往赤脊山？",a="当战士在暴风城达到足够的技能水平后，当地的武器大师会推动他们进行实战，即高风险的战斗。约鲁斯·麦酒提供的试炼迫使受训者走出城墙，证明他们在面对真实的荒野威胁时的耐力。",al={"为什么要去湖畔镇","战士训练师赤脊山任务","为什么要去找约鲁斯"}},{q="我在哪里可以找到约鲁斯·麦酒？",a="他坐在位于赤脊山湖畔镇的Lakeshire Inn里，该镇位于艾尔文森林的东部。",al={"约鲁斯·麦酒位置","约鲁斯在哪里","寻找麦酒"}},{q="和约鲁斯谈话后会发生什么？",a="与约鲁斯交谈将开启他的武力试炼，挑战你完成雷斯班之战，这是一项针对潜伏在周围山丘中的凶猛野兽和豺狼人的危险测试。",al={"约鲁斯之后","麦酒的试炼","下一个任务"}},{q="是谁提供了寻找他的任务？",a="该任务由联盟各主城的各种战士训练师提供，包括Kelv Sternhammer、Wu Shen和Darnath Bladesinger，前提是战士已经证明了基本的能力。",al={"谁发布任务","任务起始","约鲁斯的训练师"}},{q="这项试炼是否向战士以外的职业开放？",a="不。该挑战是专门为战士量身定制的。约鲁斯·麦酒只向那些纯粹依靠身体耐力和武器的战斗人员发布试炼。",al={"圣骑士能做这个吗","这是战士专有的吗","职业限制"}}},fp="16,259,20.418.0,20.414.0,24.257.0,46.254.0,34.128.0,39.147.0,33.172.0,50.120.0"}
P.entries["quest:1699"] = {n="往返瑞斯班洞穴",s="瑞斯班竞赛是一项由矮人酿酒师尤罗斯·麦酒在湖畔镇发起的离奇耐力考验。挑战者必须喝下一大口他家族酿造的烈性酒——“麦酒烫喉酒”，然后一路狂奔向北，进入豺狼人出没的瑞斯班洞穴，并在一小时内赶回。",h="瑞斯班竞赛是一项由矮人酿酒师尤罗斯·麦酒在湖畔镇发起的离奇耐力考验。挑战者必须喝下一大口他家族酿造的烈性酒——“麦酒烫喉酒”，然后一路狂奔向北，进入豺狼人出没的瑞斯班洞穴，并在一小时内赶回。",kw={"麦酒烫喉酒","豺狼人","湖畔镇","赤脊山","瑞斯班洞穴","瑞斯班竞赛","限时赛跑","尤罗斯·麦酒"},ang={["faction:Alliance"]="虽然湖畔镇在豺狼人入侵的威胁下苦苦挣扎，但勇闯竞赛有助于消灭北部洞穴附近游荡的敌方巡逻队。",["race:Dwarf"]="矮人们会对尤罗斯那种喧闹的娱乐方式感到宾至如归：将烈性家族酿酒与危险的山地冲刺结合在一起。"},sec={{t="矮人的挑战",b="在湖畔镇的旅店里，大家谈论的话题通常都是豺狼人突袭和失踪的镇守卫，而矮人尤罗斯·麦酒在这里带来了一种独特的矮人式娱乐活动。他自创的挑战“瑞斯班竞赛”，同时考验着冒险者的勇气、速度和酒量。参赛者在动身前往北部山麓之前，必须先灌下一大口他家族的招牌秘方——麦酒烫喉酒。"},{t="荒野奔跑",b="这项考验远比一场简单的醉酒赛跑危险得多。湖畔镇和目的地之间是赤脊山豺狼人的领地，那里到处都是穷凶极恶的赤脊山豺狼人。为了成功完成竞赛，参赛者必须战斗或潜行穿过这些豺狼人群，抵达瑞斯班洞穴内第一个岔路口，然后在一小时内赶回尤罗斯身边——这一切还要在抵御矮人烈酒带来的那种令人天旋地转的强烈醉意的情况下完成。"}},faq={{q="谁发起了瑞斯班竞赛？",a="留在湖畔镇的矮人酿酒师尤罗斯·麦酒。他向旅行者发起这项挑战，以证明他们的坚韧，并以此测试他的酿酒成果。",al={"谁发布瑞斯班竞赛","尤罗斯·麦酒任务","谁开启竞赛"}},{q="这项挑战为何格外困难？",a="除了必须在严格的一小时时限内避开在赤脊山山麓游荡的豺狼人之外，参赛者还必须先喝下麦酒烫喉酒，这种烈性饮料会让他们处于严重的醉酒状态，难以保持平衡。",al={"为什么瑞斯班竞赛很难","麦酒烫喉酒效果"}},{q="瑞斯班洞穴位于何处？",a="洞穴位于赤脊山北部的山麓地带，在湖畔镇的西北方。路径向北延伸，经过当地的农庄，一直通往豺狼人盘踞的峭壁。",al={"瑞斯班洞穴位置","瑞斯班在哪里","如何前往瑞斯班洞穴"}},{q="参赛者必须深入洞穴多远？",a="挑战者不需要清理整个洞穴；他们只需要抵达洞穴内部的第一个岔路口，然后转身赶回湖畔镇即可。",al={"瑞斯班洞穴目标","瑞斯班要进多深"}},{q="沿途的山丘和洞穴里住着什么生物？",a="该路线周边地区和洞穴内部到处都是敌对的赤脊山豺狼人，因此潜行或快速战斗对于在旅途中生存至关重要。",al={"瑞斯班有什么敌人","瑞斯班洞穴里有什么"}},{q="这项挑战接下来会引向何处？",a="在竞赛中幸存下来向尤罗斯·麦酒证明了你的耐力，这也为你开启了该地区后续的任务，例如前往暴风城寻找盾牌匠人弗伦·长须。",al={"瑞斯班竞赛后续","瑞斯班竞赛之后有什么任务"}}},fx={["26a182c4"]={q="尤鲁斯·麦酒为什么要这么做？",a="尤鲁斯·麦酒并非想解决危机，也不是要靠这场试炼拯救湖畔镇。他设计了雷斯班试炼场，把它当作一场考验胆量、耐力和酒量的喧闹挑战。他让大胆的冒险者喝下家族酿造的烈性麦酒，然后深入豺狼人领地，纯粹是为了取乐，也想看看是否有人敢于征服赤脊山凶残的豺狼人和麦酒令人眩晕的劲头。",al={"为什么要闯试炼场","尤鲁斯·麦酒的动机","尤鲁斯为什么挑战你"}}},fp="20,281,14.462.0,22.443.0,32.132.0,49.252.0,38.174.0,40.151.0,51.157.0,36.178.0"}
P.entries["quest:170"] = {n="新的威胁",s="“新的威胁”是巴尔林·霜锤在寒脊山谷发布的一项早期作战任务。矮人登山者们对突然在丹莫罗全境爆发的石颚穴居人措手不及，这些穴居人正威胁着当地的定居点和营地。",h="“新的威胁”是巴尔林·霜锤在寒脊山谷发布的一项早期作战任务。矮人登山者们对突然在丹莫罗全境爆发的石颚穴居人措手不及，这些穴居人正威胁着当地的定居点和营地。",kw={"新的威胁","安威玛尔","巴尔林·霜锤","强壮的石颚","寒脊山谷","丹莫罗","石颚穴居人"},ang={["faction:Alliance"]="遏制寒脊山谷的地下威胁，能确保铁炉堡的训练场依然可用，并确保南部的山门对联盟新兵来说依然安全。",["race:Dwarf"]="对于从安威玛尔出发的年轻铜须矮人来说，击退穴居人的入侵是捍卫丹莫罗神圣土地和隧道的个人职责。"},sec={{t="突破寒脊山谷",b="长期以来，寒脊山谷一直被视为年轻的矮人战士和登山者在丹莫罗训练的避风港。当穴居的石颚穴居人开始以惊人的数量挖掘地表时，这份宁静被打破了。安威玛尔很快收到了报告，称穴居人正在冰湖和周边的山麓地带蜂拥而出，扰乱了日常巡逻，并切断了穿过山谷通道的重要补给路线。"},{t="沦陷的营地",b="当这些生物对西部的一个矮人营地发动协同攻击时，危机达到了顶峰，迫使登山者们撤退并放弃了据点。由于人手不足，且无法从铁炉堡调遣完整的作战部队，巴尔林·霜锤只能求助于新招募的冒险者，让他们在这些野兽直逼安威玛尔家门口之前，杀出一条血路并守住山丘。"}},faq={{q="谁是巴尔林·霜锤？",a="巴尔林·霜锤是一位经验丰富的矮人登山者，驻扎在寒脊山谷的安威玛尔外。他负责组织防御行动，对抗威胁当地新兵的野生猛兽和入侵的穴居人。",al={"巴尔林·霜锤","谁发布了新的威胁任务","霜锤 安威玛尔"}},{q="为什么穴居人会突然出现在寒脊山谷？",a="石颚穴居人开始从丹莫罗各地的地下裂隙中挖掘至地表。寒脊山谷是首批遭受这种突然且猛烈突破并导致营地被占领的定居山谷之一。",al={"穴居人从哪里来","为什么穴居人会攻击","穴居人入侵"}},{q="哪个营地被穴居人占领了？",a="位于寒脊山谷西部边缘的一个矮人登山者营地最近遭到了穴居人的伏击并被攻陷，幸存者被迫向安威玛尔方向撤退。",al={"被占领的营地","西部营地","穴居人在哪里发动了攻击"}},{q="是什么样的穴居人在威胁山谷？",a="这些攻击者属于石颚部族，主要由普通的石颚穴居人以及更大、更强壮的强壮的石颚穴居人组成，后者在冰湖和山麓周围的推进中担任先锋。",al={"石颚穴居人","哪种穴居人","强壮的石颚穴居人"}},{q="国王麦格尼知道穴居人的问题吗？",a="当地卫兵希望国王麦格尼·铜须和铁炉堡议会能准备更大规模的回应，但像寒脊山谷这样的边境哨所目前只能被迫独自处理局部的爆发。",al={"麦格尼知道吗","铁炉堡对穴居人的回应","铁炉堡议会 穴居人"}},{q="清理这些穴居人之后会发生什么？",a="消减穴居人的数量有助于稳定安威玛尔周边的局势，不过巴尔林和其他矮人军官会继续组织反攻，以收复丢失的西部营地，并将这些害虫赶回地下。",al={"后续任务","新的威胁之后","寒脊山谷穴居人任务线"}}},fx={["3d273126"]={q="巴尔林·霜锤为什么需要你的帮助，而不是当地守卫？",a="安威玛尔的守军人手严重不足，处境岌岌可危。最近，他们西部营地遭到突袭，部队四散，驻军只能勉强守住定居点外围。没有多余的士兵可以投入进攻反击，巴尔林只能招募任何前来且有能力战斗的冒险者。",al={"为什么是我，巴尔林","为什么不用守卫","巴尔林为什么需要我"}},["54af52f4"]={q="巴尔林·霜锤为什么要清剿穴居人？",a="寒脊山谷正遭受迫在眉睫的围攻。穴居人不仅侵入了南部丘陵和冰冻湖泊，就在几夜之前还猛烈袭击了西边的矮人营地。巴尔林必须削减它们的数量，以免这些野蛮生物继续深入山谷，彻底攻陷安威玛尔。",al={"为什么杀穴居人","巴尔林·霜锤的动机","巴尔林为什么要穴居人死"}}},fp="12,240,26.426.0,14.404.0,25.209.0,44.222.0,36.179.0,47.196.0,41.203.0,40.220.0"}
P.entries["quest:1700"] = {n="格瑞曼德·艾尔默",s="在打造出特制护甲后，矮人铁匠弗伦·长须将他的研究成果副本寄送给了Dwarven District的格里曼德·埃尔莫尔。这件看似简单的差事在两位居住在暴风城的顽固武器匠之间传递了技术笔记。",h="在打造出特制护甲后，矮人铁匠弗伦·长须将他的研究成果副本寄送给了Dwarven District的格里曼德·埃尔莫尔。这件看似简单的差事在两位居住在暴风城的顽固武器匠之间传递了技术笔记。",kw={"锻造","dwarven district","火石链甲","弗伦·长须","弗伦的笔记","格里曼德·埃尔莫尔","暴风城"},ang={["class:Warrior"]="这次交付架起了桥梁，连接起自我武装与寻求通过同类元素实验锻造出的战争武器之间的鸿沟。",["profession:Blacksmithing"]="弗伦与格里曼德之间的交流展现了金属工艺大师之间常见的激烈职业竞争与行业机密分享。",["race:Dwarf"]="格里曼德与弗伦之间那暴躁而傲慢的斗嘴，反映了卡兹莫丹锻造文化中既竞争又合作的深厚传统。"},sec={{t="区区之间的一封信",b="在锻造出特制的火石链甲后，弗伦·长须记录下了他在过程中发现的复杂热处理技术和元素原理。他并没有将这些知识据为己有，而是将其写在羊皮纸上，并委托一位冒险者直接送交给格里曼德·埃尔莫尔——一位在附近武器店经营的资深工匠。"},{t="职业自尊与好奇心",b="格里曼德·埃尔莫尔在收到手稿后的第一反应是自尊心受挫。格里曼德坚称他教会了这名年轻矮人所知的一切，因此对自己曾经的学生居然反过来指导他感到愤慨。尽管表面上十分恼火，但这位工匠还是忍不住研读了笔记，并很快在其中发现了一个令他着迷的点子，让他迫不及待地想要亲自尝试一番。"}},faq={{q="格里曼德·埃尔莫尔是谁？",a="格里曼德·埃尔莫尔是一位备受尊敬的武器匠，在暴风城的Dwarven District经营着一家店铺。他以极其强烈的职业自尊心，以及过去曾向包括弗伦·长须在内的当地铁匠传授锻造技巧而闻名。",al={"格里曼德·埃尔莫尔","格里曼德是谁","埃尔莫尔 暴风城"}},{q="为什么弗伦要给格里曼德发送笔记？",a="在锻造火石链甲时，弗伦发现了新的技术并记录下了自己的方法。他希望与格里曼德分享这些突破，尽管他也知道格里曼德火爆的脾气和固执的自尊心会让他对接受指导一事产生抵触。",al={"为什么要送笔记","弗伦的笔记","弗伦给格里曼德"}},{q="在哪里可以找到格里曼德·埃尔莫尔？",a="他就在暴风城Dwarven District的武器店里工作，距离弗伦·长须的熔炉仅几步之遥。",al={"格里曼德在哪里","格里曼德位置","格里曼德·埃尔莫尔的商店"}},{q="格里曼德对这些笔记有何反应？",a="格里曼德起初感到愤怒，声称他教会了弗伦那矮人所知道的一切。然而，当他在文中发现一种令他想要实验的巧妙技术时，身为大师级铁匠的好奇心很快便占据了上风。",al={"格里曼德的反应","格里曼德生气了吗"}},{q="格里曼德读完笔记后发生了什么？",a="受弗伦在金属火淬工艺上工作的启发，格里曼德决定投身于一项雄心勃勃的制作计划，这引出了后续收集具有元素热能的稀有材料的任务。",al={"格里曼德接下来做什么","格里曼德·埃尔莫尔任务之后"}},{q="为什么弗伦在递交笔记时提醒要“低头躲避”？",a="弗伦深知格里曼德火爆的脾气和过剩的自尊心。他预料到，一旦暗示学徒居然能教导大师新的技术，格里曼德可能会大发雷霆——甚至扔东西。",al={"为什么要躲避","弗伦的躲避警告"}}},fx={["7d98159c"]={q="弗伦为什么派你去找 Grimand，而不是亲自前往？",a="弗伦太了解 Grimand Elmore 那易怒的脾气了。Grimand 声称自己把毕生所学都教给了弗伦。要是这位昔日学生径直走进他的铺子，向他讲授新的锻造技艺，肯定会引发激烈争吵。让你代为递交笔记，弗伦就能避免正面冲突，也能让这位固执的导师私下咽下这口气。",al={"为什么派我去找 grimand elmore","弗伦为什么不亲自送笔记","弗伦为什么需要我"}}},fp="14,256,29.392.0,32.407.0,22.240.0,37.270.0,34.149.0,36.233.0,43.187.1,56.215.0"}
P.entries["quest:1701"] = {n="弗伦的铠甲",s="“火淬锁甲”是一项联盟战士任务，由暴风城的矮人护甲商弗伦·长须提供。基于他之前打造护甲的工作，弗伦承诺如果战士能找回散落在两块大陆上的稀有炼金材料和野兽战利品，他就会打造出一套极其耐用的锁甲。",h="“火淬锁甲”是一项联盟战士任务，由暴风城的矮人护甲商弗伦·长须提供。基于他之前打造护甲的工作，弗伦承诺如果战士能找回散落在两块大陆上的稀有炼金材料和野兽战利品，他就会打造出一套极其耐用的锁甲。",kw={"烧焦的奇美拉角","火淬锁甲","弗伦·长须","光滑的奇美拉角","燃素","剃刀沼泽","罗古格","烧焦的蜘蛛牙","石爪山脉","湿地"},ang={["class:Warrior"]="这项任务是联盟战士的一次重要的成人礼，迫使他们勇敢地闯入卡利姆多的荒野和深层地下城，以赢得一件杰作级的盔甲。",["faction:Alliance"]="完成弗伦的清单需要一名联盟士兵深入到贫瘠之地和石爪山脉，这些地区是部落激烈争夺的区域。",["race:Dwarf"]="弗伦的工艺反映了矮人持久的信念，即真正的盔甲需要从最严酷的自然掠食者身上直接获取坚韧的材料。"},sec={{t="大师级护甲商的抱负",b="在为立志成为战士的冒险者打造了一面卓越的圆盾后，弗伦·长须提出了一个更宏大的计划：打造一套能抵御最猛烈攻击的锁甲。这种矮人手艺需要的不仅仅是铁或钢；它需要注入元素之热和天然韧性的奇异材料。由于铁匠无法离开他在暴风城的熔炉，收集这些危险试剂的重任就完全落在了寻求盔甲的战士身上。"},{t="跨大陆的远征",b="弗伦的详细指示将战士送往遥远的荒野和险恶的深处。配方需要从湿地潮湿裂隙中爬行的毒蛛身上采集毒牙，以及从石爪山脉筑巢的凶猛奇美拉身上剥下的烧焦的奇美拉角和光滑的奇美拉角。为了将这些野兽的肢体结合并锻造成可穿戴的锁甲，这套盔甲还需要一瓶从贫瘠之地剃刀沼泽中布满荆棘的迷宫深处的地卜师罗古格那里夺来的挥发性燃素。"}},faq={{q="谁是弗伦·长须？",a="弗伦·长须是一位资深的矮人护甲商和盾匠，驻扎在暴风城的Dwarven District。他专门为愿意帮助他的有前途的战士量身打造防御装备。",al={"弗伦","谁提供火淬锁甲","铁匠是谁"}},{q="为什么弗伦需要这些奇怪的材料？",a="传统的熔炼只能产出普通的钢材，但弗伦的秘方需要经过天然毒液、山风和吐息武器洗礼的有机材料，并辅以不稳定的催化物质燃素，从而将金属淬炼到超越普通矮人工艺的程度。",al={"为什么需要蜘蛛毒牙","为什么需要角","什么是燃素"}},{q="奇美拉角来自哪里？",a="烧焦的奇美拉角和珍贵的光滑的奇美拉角来自栖息在卡利姆多石爪山脉的奇美拉，特别是那些年幼的野兽以及统领它们的强大的奇美拉主宰。",al={"在哪里寻找奇美拉角","烧焦的奇美拉角位置","光滑的奇美拉角"}},{q="在哪里可以找到燃素？",a="一瓶燃素由野猪人地卜师罗古格携带，他盘踞在位于卡利姆多贫瘠之地南端的剃刀沼泽中。",al={"燃素","谁掉落燃素","罗古格"}},{q="哪些蜘蛛带有烧焦的蛛牙？",a="这些毒牙是从东部王国湿地的巨型蜘蛛身上获得的，具体来说是潜伏在该地区沼泽和洞穴中的吸血捕猎者和洞穴捕猎者。",al={"烧焦的蛛牙","蜘蛛在哪里","湿地蜘蛛"}},{q="所有材料收集齐之后会发生什么？",a="在收到毒牙、奇美拉角和燃素后，弗伦会立即开始操作他的熔炉，将这些原始元素锻造成任务“弗伦的护甲”中给战士的定制胸甲。",al={"what comes next","火淬锁甲后续","奖励"}}},fp="18,193,27.377.0,30.431.0,23.168.0,48.225.0,38.178.0,30.139.0,42.154.0,50.160.0"}
P.entries["quest:1702"] = {n="铸盾师",s="在赤脊山经历了一场惊心动魄的考验后，尤鲁斯·麦酒派遣战士前往暴风城的Dwarven District领取他们应得的奖励。带着一桶烈性的麦酒烧灼剂，这些好战的旅人会去寻找护甲大师弗伦·长须，请他打造一面坚固的盾牌。",h="在赤脊山经历了一场惊心动魄的考验后，尤鲁斯·麦酒派遣战士前往暴风城的Dwarven District领取他们应得的奖励。带着一桶烈性的麦酒烧灼剂，这些好战的旅人会去寻找护甲大师弗伦·长须，请他打造一面坚固的盾牌。",kw={"麦酒烧灼剂","酒桶","dwarven district","弗伦·长须","雷斯班","盾牌匠","暴风城","战士","尤鲁斯·麦酒"},ang={["class:Warrior"]="这笔交付将赤脊山的艰苦磨砺与暴风城的大师技艺结合在了一起，证明了你有权持有一面由传奇矮人护甲师亲手锻造的盾牌。",["profession:Blacksmithing"]="拜访弗伦·长须让你结识了一位铁砧大师，他在防御护甲方面的专业造诣在整个联盟都备受推崇。",["race:Dwarf"]="用一桶上好的麦酒佳酿在暴风城Dwarven District的中心换取锻造的钢铁，这就是最典型的矮人式交易。"},sec={{t="信守承诺",b="在证明了自己的勇气，对抗了雷斯班小径的豺狼人和重重危险之后，战士们期待着尤鲁斯·麦酒的酬劳。虽然尤鲁斯信守了他的诺言，但真正的奖赏却无法在湖畔镇敲打出来。相反，他指引这些前途无量的战士回到暴风城，那里有一位矮人护甲师已经准备好偿还他的人情债。"},{t="麦酒家族的佳酿",b="尤鲁斯并没有提供一张信用书，而是提供了一种对口渴的铁炉堡工匠来说更具说服力的货币：一桶沉甸甸的麦酒烧灼剂。这桶酒被送到Dwarven District的喧嚣与烟尘之中，交到弗伦·长须手中，既是介绍信也是报酬，促使这位经验丰富的铁匠用他的手艺去帮助一位有志气的保卫者。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是一位矮人护甲大师和盾牌匠，常驻于暴风城的Dwarven District。他在联盟战士中享有盛名，擅长打造特制的防御装备，并与那些赢得他尊重的身经百战的老兵们密切合作。",al={"弗伦·长须","弗伦是谁","谁是盾牌匠"}},{q="为什么尤鲁斯要送你去暴风城？",a="虽然尤鲁斯·麦酒为清理雷斯班小径提供了奖励，但他本人缺乏打造那面承诺的战斗盾牌所需的专业锻造技能。他把你引荐给他的朋友弗伦·长须，后者欠他一个人情。",al={"为什么要去暴风城","为何是暴风城","尤鲁斯的奖励位置"}},{q="什么是麦酒烧灼剂？",a="麦酒烧灼剂是麦酒家族酿造的一种极具威力的矮人饮品。尤鲁斯送了一桶新鲜的烧灼剂给弗伦·长须，以满足这位铁匠的酒瘾，并润滑他们交易的齿轮。",al={"一桶热酒","麦酒烧灼剂","什么是烧灼剂"}},{q="在哪里可以找到弗伦·长须？",a="弗伦·长须就在暴风城Dwarven District中心地带的熔炉旁，周围满是矮人工匠的烟尘、铁砧和工坊。",al={"弗伦的位置","弗伦·长须在哪","寻找弗伦"}},{q="把酒桶交给弗伦后会发生什么？",a="收到烧灼剂就证明了你是尤鲁斯派来的。弗伦承认他欠的人情，并立即提出为久经沙场的战士制造防御性护甲，从而开启了一条打造烈焰淬火装备的道路。",al={"what comes next","弗伦的后续任务"}},{q="为什么这个差事对联盟战士很重要？",a="这个差事将联盟战士引荐给了王国中最能干的护甲师之一，为定制战斗装备和进一步学习防御战的艺术打开了大门。",al={"战士任务的重要性","为什么战士要在意"}}},fp="15,205,14.296.0,19.301.0,23.225.0,37.197.0,27.206.0,35.141.0,41.187.0,51.179.0"}
P.entries["quest:1703"] = {n="玛希尔",s="这个任务要求冒险者带着弗伦·长须的锻造笔记远渡重洋前往达纳苏斯。收件人是玛希尔，一位居住在战士区、渴望研究矮人锁甲锻造创新的工匠铁匠。这代表了铁炉堡与卡多雷之间重要的军事冶金交流。",h="这个任务要求冒险者带着弗伦·长须的锻造笔记远渡重洋前往达纳苏斯。收件人是玛希尔，一位居住在战士区、渴望研究矮人锁甲锻造创新的工匠铁匠。这代表了铁炉堡与卡多雷之间重要的军事冶金交流。",kw={"铁匠","达纳苏斯","火焰强化锁甲","弗伦·长须","弗伦的笔记","玛希尔","泰达希尔","战士区"},ang={["class:Warrior"]="携带这些笔记标志着你从东部王国的火热锻炉之旅走向达纳苏斯的试炼之地，并扩充了你个人的军械库。",["profession:Blacksmithing"]="这次交付展示了铁匠大师之间至关重要的合作，蓝图和热回火技术在遥远的铁砧之间传递。",["race:Dwarf"]="与暗夜精灵分享弗伦的金属加工突破，突显了矮人对其炉火纯青的锻造技艺的自豪。",["race:NightElf"]="玛希尔代表了卡多雷愿意学习矮人地下锻造技术并将其与传统暗夜精灵护甲制作工艺相融合的意愿。"},sec={{t="跨海的信使",b="在掌握了火焰强化护甲的艰难锻造工艺后，矮人老铁匠弗伦·长须决定与联盟的其他工匠分享他的突破。弗伦没有将他新发现的冶金术据为己有，而是抄录了详细的技术图纸，并派遣他信赖的冒险者横跨大陆，去寻找居住在泰达希尔高处的能工巧匠玛希尔。"},{t="卡多雷的钢铁与矮人的技艺",b="玛希尔在达纳苏斯树冠下的战士区经营着他的熔炉，为守卫暗夜精灵主城的哨兵和战士们提供装备。弗伦的笔记的送达标志着两种不同锻造传统之间的桥梁：卡兹莫丹矮人粗犷的地下冶炼工艺，与卡多雷优雅且契合自然的护甲制作工艺。"}},faq={{q="玛希尔是谁？",a="玛希尔是一位驻扎在达纳苏斯战士区的暗夜精灵铁匠。他为首都的保卫者制造装备，并与联盟各地的其他铁匠大师保持着同僚间的通信。",al={"玛希尔背景故事","达纳苏斯的玛希尔是谁"}},{q="为什么弗伦要派你去达纳苏斯？",a="弗伦·长须希望他关于火焰强化护甲锻造的研究能造福联盟的其他工匠。因为玛希尔是一位值得信赖的同事，能够理解并运用先进的冶金技术，所以弗伦委托你将他个人的锻造笔记带给对方。",al={"为什么要给玛希尔送笔记","弗伦笔记的原因"}},{q="我能在达纳苏斯哪里找到玛希尔？",a="玛希尔位于达纳苏斯东区的战士区熔炉旁，战士和哨兵们在那里进行训练，主大门附近即是。",al={"玛希尔位置","玛希尔在哪里"}},{q="把笔记交给玛希尔后会发生什么？",a="玛希尔对弗伦的发现印象深刻，他决定在矮人技术的基础上进一步研究，并派遣战士前往卡利姆多的荒野进行试炼，去收集诸如焦灼的壳之类的异域材料。",al={"玛希尔任务后的后续","玛希尔后续任务"}},{q="送递的是什么样的笔记？",a="笔记中包含了弗伦在实验过程中通过灼热的蜘蛛毒牙、奇美拉之角和燃素来生产强化锁甲时所学到的详细冶金观察记录和锻造技术。",al={"弗伦笔记的内容","弗伦的笔记是什么"}},{q="这个任务仅限战士吗？",a="是的，这个送信差事是联盟战士发展其军事才能和护甲制作工艺的专属试炼与进阶的一部分。",al={"战士任务玛希尔","其他职业能做玛希尔任务吗"}}},fx={c109af9e={q="弗伦·长须为什么信任你，让你把笔记送给 Mathiel？",a="你收集弗伦锻造耐火护甲所需的稀有材料时，已经证明了自己的决心和实力。亲眼见识过你的可靠后，他知道你完全有能力横渡大海，走过漫长的旅途，把他来之不易的技艺交到 Mathiel 手中。",al={"为什么派我去找 mathiel","为什么由我送弗伦的笔记","弗伦为什么需要我"}}},fp="7,320,24.388.0,32.353.0,15.217.0,37.283.0,38.158.0,44.205.1,39.197.0,37.142.0"}
P.entries["quest:1704"] = {n="科罗莫特·钢尺",s="这个任务指引一位冒险者从暴风城前往铁炉堡，将商业秘密递交给工匠区（Tinkertown）的克洛克摩特·扳手（Klockmort Spannerspan）。在掌握了火炼护甲的艺术后，矮人铁匠弗伦·长须（Furen Longbeard）迫不及待地与他的侏儒同事分享了他的冶金发现。这是有志于测试异域锻造方法的勇士旅程中至关重要的一环。",h="这个任务指引一位冒险者从暴风城前往铁炉堡，将商业秘密递交给工匠区（Tinkertown）的克洛克摩特·扳手（Klockmort Spannerspan）。在掌握了火炼护甲的艺术后，矮人铁匠弗伦·长须（Furen...",kw={"铁匠","火炼","弗伦","铁炉堡","克洛克摩特","长须","笔记","扳手","工匠区"},ang={["class:Warrior"]="你制作耐用战斗装备的旅程将你从矮人的炉火边直接引向了侏儒的创新，并让你赢得了工匠区最优秀工匠的关注。",["profession:Blacksmithing"]="弗伦的笔记代表了铁炉堡大师级工匠之间尖端锻造技术的协作交流。",["race:Gnome"]="克洛克摩特代表了铁炉堡工匠区内经典矮人冶金术与创造性侏儒实验之间的巧妙结合。"},sec={{t="工匠区的同事",b="在成功打造出一套火炼锁甲后，弗伦·长须整理了他详尽的研究发现，准备交给一位同行。弗伦并没有将他新发现的技艺藏私，而是信任你将他的弗伦的笔记（Furen's Notes）从暴风城带到铁炉堡，并送入喧闹且蒸汽弥漫的工匠区，侏儒铁匠克洛克摩特·扳手正是在那里从事他的工作。"},{t="侏儒的兴奋",b="与他们的矮人东道主相比，侏儒铁匠相对罕见，而克洛克摩特对突破传统金属工艺的界限充满热情。在查看了弗伦的笔记后，克洛克摩特对这一突破感到非常兴奋，急切地想要将这些火炼技术融入他自己的异域项目中。"}},faq={{q="克洛克摩特·扳手是谁？",a="克洛克摩特·扳手是一位侏儒铁匠，在铁炉堡地底城市的工匠区工作。他与像弗伦·长须这样的矮人铁匠密切合作，研究先进的金属加工技术。",al={"克洛克摩特·扳手","谁是克洛克摩特","铁炉堡侏儒铁匠"}},{q="为什么弗伦·长须要派你去找克洛克摩特？",a="弗伦记录的笔记详细说明了他在制作火炼锁甲时发现的突破性技术。因为了解克洛克摩特对创造性铁匠工作的热情，弗伦派你去递送这些研究结果，以便这位侏儒可以进行实验。",al={"为什么要递送笔记","弗伦的笔记","弗伦·长须与克洛克摩特"}},{q="我可以在哪里找到克洛克摩特·扳手？",a="克洛克摩特·扳手位于工匠区，这是铁炉堡东部区域以侏儒为主的街区，周围环绕着工作台和机器。",al={"克洛克摩特的位置","克洛克摩特在哪里","克洛克摩特 铁炉堡"}},{q="把笔记交给克洛克摩特后会发生什么？",a="克洛克摩特对弗伦的突破性进展着了迷，他立即开始规划自己的冶金项目，并引导你走上收集诸如铁珊瑚（iron coral）等稀有材料的道路。",al={"任务后续","克洛克摩特任务之后做什么","铁珊瑚任务"}},{q="这个任务只限战士吗？",a="是的。这次递送是专为在资深武器和护甲大师指导下训练的联盟战士提供的专属护甲制作任务链的一部分。",al={"仅限战士","任何人都可以做这个任务吗","职业要求"}},{q="为什么克洛克摩特说他分不清白天和黑夜？",a="铁炉堡是一座完全深埋在丹莫罗群山之中的地底城市。在石制拱顶和明亮灯光下的工匠区，工匠们看不到太阳或天空。",al={"克洛克摩特昼夜对话","地底对话"}}},fp="21,386,25.371.0,18.314.0,29.214.0,47.245.0,39.153.0,46.175.1,34.156.0,53.187.0"}
P.entries["quest:1705"] = {n="燃烧之血",s="暴风城的锻造大师格里曼德·艾尔莫尔委托一位The Adventurer前往暮色森林那阴影笼罩的树林中，去搜寻奇异的锻造材料。格里曼德对弗伦·长须首创的创新盔甲制作技术很感兴趣，他需要野性狼人手中的燃烧之血和一块炽热的余烬之石来亲自测试这一工艺。",h="暴风城的锻造大师格里曼德·艾尔莫尔委托一位The...",kw={"燃烧之血","燃烧之石","暮色森林","弗伦·长须","格里曼德·艾尔莫尔","gutspill","夜之魇狼人","罗兰之墓"},ang={["class:Warrior"]="对于游历王国的战士来说，为了格里曼德的实验而勇敢面对暮色森林中被诅咒的野兽，可以获得专为前线量身定制的独特淬火盔甲。",["faction:Alliance"]="从罗兰之墓回收试剂有助于遏制暮色森林中不断侵袭的狼人威胁，同时也为暴风城的军械库提供了强有力的新防御技术。",["profession:Blacksmithing"]="铁匠们会理解格里曼德和他曾经的学生弗伦之间的职业自豪感，这凸显了锻造大师们为了测试稀有冶金和淬火剂所愿意付出的努力。"},sec={{t="不情愿的实验",b="格里曼德·艾尔莫尔是联盟中最有成就的盔甲匠之一，他很少承认其他工匠的技艺能胜过自己。然而，在听说了弗伦·长须那非传统的锻造发现后，职业好奇心战胜了他那固执的自尊。格里曼德同意通过锻造一件定制盔甲来测试弗伦的方法。为了将金属淬火并回火到精确的规格，普通的水或常见的煤炭是远远不够的；他需要只有在南方阴暗区域才能找到的奇异且不稳定的组件。"},{t="罗兰之墓的恐怖",b="任务指引勇敢的锻造学徒和战士前往暮色森林，具体目标是那座被遗弃的矿洞——罗兰之墓。洞穴已被野蛮的夜之魇狼人占领，这些狼形野兽那被诅咒的血管中流淌着非自然的灼热体液。格里曼德需要这种燃烧之血的药瓶，以及由狼群凶残的首领Gutspill所持有的、一种被称为燃烧之石的稀有火热地质核心。杀死这些野兽并获得它们滚烫的遗骸，能让格里曼德用黑暗而炽热的力量点燃他的熔炉。"}},faq={{q="格里曼德·艾尔莫尔是谁？",a="格里曼德·艾尔莫尔是在暴风城Dwarven District工作的一位受人尊敬的盔甲大师。他与其他工匠并肩工作，为城市的保卫者装备护甲，并向有抱负的战士传授关于正规战甲的耐久度和重量知识。",al={"格里曼德","格里曼德·艾尔莫尔","暴风城盔甲匠"}},{q="格里曼德为什么需要燃烧之血和燃烧之石？",a="格里曼德想要测试由弗伦·长须开发的一种非传统盔甲制作技术。燃烧之血和燃烧之石拥有淬火和锻造特殊盔甲板所需的强烈超自然热量。",al={"为什么需要燃烧之血","燃烧之石有什么用","任务目的"}},{q="我在哪里可以找到携带这些材料的夜之魇狼人？",a="这些材料可以在暮色森林的罗兰之墓找到，这是一座位于暮色森林东南部、夜色镇西南方的废弃矿洞。矿道里挤满了携带灼热之血的敌对夜之魇狼人。",al={"狼人在哪里","罗兰之墓位置","哪里有燃烧之血"}},{q="谁持有燃烧之石？",a="燃烧之石由Gutspill携带，它是居住在罗兰之墓深处的夜之魇狼人群落中一位强大的首领。",al={"谁有燃烧之石","gutspill","gutspill的位置"}},{q="格里曼德·艾尔莫尔和弗伦·长须之间是什么关系？",a="弗伦·长须是格里曼德·艾尔莫尔的前学生。格里曼德通常对外界的想法持怀疑态度，但弗伦在盔甲制作方面的最新创新足以让格里曼德亲自对其进行测试。",al={"格里曼德与弗伦","弗伦·长须是谁"}},{q="交回血液和石头后会发生什么？",a="在收到这些火热的试剂后，格里曼德立即开始锻造盔甲以验证弗伦的技术，并承诺将成品交付给收集了材料的The Adventurer。",al={"下一个任务","奖励","格里曼德制造什么"}}},fp="13,176,22.471.0,28.390.0,22.221.0,55.196.0,62.189.0,27.109.0,68.186.0,48.168.0"}
P.entries["quest:1706"] = {n="格瑞曼德的铠甲",s="“Grimand's Armor”是战士在暴风城Dwarven District的Grimand Elmore指导下完成的训练任务线的终点。在证明了弗伦·长须的冶金技术切实可行之后，这位铁匠打造出了一件能够在战斗中承受重击的强力护甲。这标志着联盟战士迈向精通之路的一个重要里程碑。",h="“Grimand's Armor”是战士在暴风城Dwarven District的Grimand...",kw={"护甲","锁甲头盔","burning blood","dwarven district","弗伦·长须","grimand elmore","暴风城","战士任务"},ang={["class:Warrior"]="这个任务代表了联盟战士生涯中的一个决定性时刻，奖励他们一顶标志性的、坚韧的锁甲头盔，专为抵御前线战斗中的残酷冲击而锻造。",["faction:Alliance"]="Grimand Elmore对弗伦·长须设计的依赖，展示了暴风城Dwarven District的矮人铁匠们是如何汇集他们的发现来武装联盟战士的。",["profession:Blacksmithing"]="这次交流展示了暴风城Dwarven District的两位矮人铁匠之间的合作，他们利用不寻常的试剂来极大程度地对金属进行回火。"},sec={{t="大师创新的证明",b="Grimand Elmore在暴风城Dwarven District的锻造厂工作，起初对矮人大师级护甲匠弗伦·长须所开发的那种怪异且大胆的技术持有深深的怀疑。验证弗伦的方法需要前往敌对领土进行危险的探险，以收集稀有的元素和野兽材料。通过提供这些至关重要的材料，战士让Grimand能够将这位矮人的理论付诸实践，将原材料锻造成一个旨在承受毁灭性冲击的强化头盔。"},{t="锻造神盾",b="最终的产品证明了弗伦的冶金见解是完全正确的。Grimand成功地对金属进行了处理，使其能够承受足以让普通钢铁变形的巨大压力和物理创伤。在将打造好的锁甲头盔交给帮助过他的战士时，Grimand既认可了弗伦的工艺，也认可了The Adventurer的决心，使他们有能力坚守前线，抵御艾泽拉斯最严重的威胁。"}},faq={{q="这个任务的目的是什么？",a="这是主要战士职业任务线的最后一个交接任务。Grimand Elmore使用你获得的稀有材料完成了特制锁甲头盔的锻造，验证了弗伦·长须的实验性锻造方法。",al={"grimand's armor任务目的","为什么要完成grimand's armor任务","grimand给什么奖励"}},{q="Grimand Elmore是谁？",a="Grimand Elmore是一位居住在暴风城Dwarven District的熟练矮人武器匠。他与铁炉堡的同事们协同工作，协助初出茅庐的战士获得特制的护甲。",al={"grimand是谁","grimand elmore的角色","grimand在哪里"}},{q="弗伦·长须是谁，为什么提到他？",a="弗伦·长须是驻扎在暴风城Dwarven District的矮人大师级护甲匠，他发明了一种能增强护甲以抵御巨大压力的实验性技术。Grimand起初对弗伦的主张表示怀疑，直到你带回了测试该方法所需的材料。",al={"弗伦是谁","弗伦的工艺技术","弗伦·长须"}},{q="哪个任务直接引导至此任务？",a="此任务紧接在“Burning Blood”之后，战士需要将最后一种稀有试剂——取自暮色森林罗兰之墓的Nightbane狼人身上的Burning Blood——交给Grimand，以便他淬火和回火金属。",al={"grimand's armor的前置任务","burning blood任务","此任务的前置任务是什么"}},{q="任何职业都能完成这个任务吗？",a="不可以。这条任务线专为三十级左右的联盟战士量身定制，代表了他们获得耐用锁甲的成人礼。",al={"grimand's armor是战士专属吗","谁能完成grimand's armor任务"}},{q="这个任务在哪里交接？",a="该任务直接在暴风城Dwarven District的铁砧处交给Grimand Elmore。",al={"在哪里交grimand's armor任务","grimand在暴风城的位置"}}},fp="15,236,28.378.0,17.351.0,34.203.0,22.168.0,47.208.0,40.196.0,34.125.0,35.87.0"}
P.entries["quest:1707"] = {n="收集水袋",s="加基森的操作员鲁格伦克希望你能找回被那些游牧民偷走的荒漠流浪者水囊，无论你在沙漠中何处发现它们。加基森水务公司承诺每回收五个水囊，就提供一份正式的补给包裹。",h="加基森的操作员鲁格伦克希望你能找回被那些游牧民偷走的荒漠流浪者水囊，无论你在沙漠中何处发现它们。加基森水务公司承诺每回收五个水囊，就提供一份正式的补给包裹。",kw={"加基森","鲁格伦克","塔纳利斯","荒漠流浪者","水务公司","水囊"},sec={{t="属于加基森的水",b="鲁格伦克是一位经验丰富的操作员，他希望能得到你在沙漠中遇到的荒漠流浪者水囊。这些水最初就是加基森的，是那些游牧民偷走了它们。每带来五个水囊，加基森水务公司就会提供一份正式的补给包裹，你这也是在帮助加基森自助。"},{t="多多益善",b="每回收一个水囊鲁格伦克都会感到高兴，因为每一个水囊都能让大家远离灾难。鲁格伦克承诺，你每带来五个水囊，他都会给你相应的报酬。"}},faq={{q="谁是操作员鲁格伦克？",a="加基森的一位经验丰富的操作员，他正在征集荒漠流浪者水囊。",al={"谁是鲁格伦克","鲁格伦克的职责","操作员"}},{q="为什么鲁格伦克想要荒漠流浪者水囊？",a="因为这些水属于加基森，是那些游牧民偷走的。",al={"为什么要水囊","为什么要杀荒漠流浪者","荒漠流浪者水囊背景"}},{q="在哪里可以找到荒漠流浪者水囊？",a="在沙漠里，从那些偷走水囊的荒漠流浪者游牧民手中。",al={"哪里能找到水囊","荒漠流浪者水囊位置","谁掉落水囊"}},{q="加基森水务公司用什么来换取这些水囊？",a="每五个水囊换取一份正式的补给包裹。",al={"补给包裹","交水囊能得到什么"}}},fp="18,219,31.357.0,16.177.1,33.79.0,50.54.0,45.73.0,60.55.0"}
P.entries["quest:1708"] = {n="铁珊瑚",s="“灼热珊瑚”是联盟方的一个任务，由铁炉堡工匠区的侏儒铁匠克罗克莫特·斯帕纳斯班发布。克罗克莫特渴望用一套定制的盔甲来测试新近分享的锻造方法，因此派你去湿地海岸潜水，搜集稀有的灼热珊瑚。完成他的要求后，他就能将侏儒的独创性与矮人的精湛技艺融合在一起。",h="“灼热珊瑚”是联盟方的一个任务，由铁炉堡工匠区的侏儒铁匠克罗克莫特·斯帕纳斯班发布。克罗克莫特渴望用一套定制的盔甲来测试新近分享的锻造方法，因此派你去湿地海岸潜水，搜集稀有的灼热珊瑚。完成他的要求后，他就能将侏儒的独创性...",kw={"盔甲熔炼","弗伦·长须","灼热珊瑚","铁炉堡","克罗克莫特·斯帕纳斯班","米奈希尔港","tinker town","湿地"},ang={["profession:Blacksmithing"]="铁匠们会欣赏克罗克莫特尝试的这种非传统的熔炼技术，他将采集到的海洋沉积物变成了个人盔甲的硬化板材。",["profession:Engineering"]="该任务展示了测试野外材料属性以实现卓越防御效用的修理哲学。",["race:Dwarf"]="这项实验直接源于铁炉堡大师级铁匠弗伦·长须的冶金发现，展示了侏儒与矮人在工匠区之间的紧密合作。",["race:Gnome"]="克罗克莫特追求奇异的沿海矿物而非标准的铁矿，反映了典型的侏儒创造力，即始终致力于通过实验来改进传统的工艺。"},sec={{t="工艺的融合",b="在与矮人锻造大师弗伦·长须交流心得后，克罗克莫特·斯帕纳斯班灵感迸发。这位性格古怪的侏儒铁匠想要将弗伦的冶金术与他自己的修理技术结合起来，打造出一套异常坚韧的盔甲。为了完成这一大胆的冶金实验，普通的山脉矿石是远远不够的；克罗克莫特需要一种不寻常的、天然硬化的海洋元素，即“灼热珊瑚”。"},{t="潜入湿地海岸",b="灼热珊瑚是一种挥发性强、质地坚硬的海洋沉积物，只生长在一个特定的区域：湿地米奈希尔港以南的近海海域。要取回二十块珊瑚，意味着你必须涉水穿过险恶的沼泽水域，面对本地水生掠食者的威胁，并将湿漉漉的收获物搬回铁炉堡。然而对克罗克莫特来说，这些奖品完全值得这趟潮湿的旅程，因为他打算将珊瑚直接熔炼并锻打进他的实验性板甲中。"}},faq={{q="谁是克罗克莫特·斯帕纳斯班？",a="克罗克莫特·斯帕纳斯班是一位技术娴熟的侏儒铁匠，居住在铁炉堡山城的工匠区。他热衷于机械修理和尖端冶金术，经常与矮人工匠密切合作，发明新的盔甲锻造方法。",al={"克罗克莫特","谁发布灼热珊瑚任务","灼热珊瑚任务发布者"}},{q="什么是灼热珊瑚？",a="灼热珊瑚是一种稀有的海洋生长物，是从湿地米奈希尔港以南的海底采集的。它具有独特的化学和物理特性，足以让一位富有创造力的工匠将其熔炼并锻打成盔甲的加固材料。",al={"灼热珊瑚背景故事","灼热珊瑚用途"}},{q="我在哪里可以找到灼热珊瑚？",a="珊瑚床只生长在湿地米奈希尔港正南方的沿海海底。潜水者必须深入波浪之下，才能撬下那些富含矿物质的枝条。",al={"灼热珊瑚位置","灼热珊瑚任务在哪里","湿地珊瑚位置"}},{q="为什么克罗克莫特需要灼热珊瑚，而不是金属矿石？",a="克罗克莫特正试图在他从矮人弗伦·长须那里学到的锻造技术基础上进行创新。他希望灼热珊瑚的不寻常属性在熔炼后能产生一种更轻、更耐用的成品，而不是单纯依赖传统的铁炉堡矿石。",al={"为什么要用珊瑚做盔甲","珊瑚冶金"}},{q="弗伦·长须在这个任务中扮演什么角色？",a="弗伦·长须之前在你的帮助下开发了新的盔甲锻造技术。出于感激，弗伦与克罗克莫特分享了他的商业机密，激发了这位侏儒将这些技术应用到他自己的防护发明中。",al={"弗伦的关联","弗伦·长须与灼热珊瑚"}},{q="把珊瑚交给克罗克莫特后会发生什么？",a="一旦提供了二十份灼热珊瑚，克罗克莫特就会立即在他的工作台上进行熔炼和锻打，这也直接引出了任务“克罗克莫特的杰作”中对他实验性装备的展示。",al={"灼热珊瑚后续任务","灼热珊瑚的下一个任务"}}},fx={f5cb4716={q="Klockmort Spannerspan 为什么要收集灼热珊瑚？",a="Klockmort 是一位热衷实验的侏儒发明家。他从弗伦·长须那里学到了创新的锻造技艺，想把弗伦的方法与自己的工程学知识结合起来，打造一套极为坚韧的护甲。为此，他特地需要从湿地海岸采集的灼热珊瑚所具有的独特性质。",al={"klockmort 为什么要珊瑚","klockmort 灼热珊瑚的动机","为什么打造灼热珊瑚护甲"}}},fp="10,353,18.451.0,25.468.0,29.265.0,22.239.0,34.203.0,59.284.0,45.227.0,51.233.1"}
P.entries["quest:1709"] = {n="科罗莫特的成果",s="克洛克莫特的杰作标志着在铁炉堡的Tinker Town成功锻造出一套特制护甲。侏儒铁匠克洛克莫特·扳手跨利用弗伦·长须这位盔甲锻造大师构思的非传统工艺，将原材料塑造成了一件极其坚韧的装备。",h="克洛克莫特的杰作标志着在铁炉堡的Tinker Town成功锻造出一套特制护甲。侏儒铁匠克洛克莫特·扳手跨利用弗伦·长须这位盔甲锻造大师构思的非传统工艺，将原材料塑造成了一件极其坚韧的装备。",kw={"弗伦·长须","灼热珊瑚","铁炉堡","克洛克莫特","攻城器械","扳手跨","tinker town","战士护甲"},ang={["class:Warrior"]="委托制作这些护手是联盟战士的一个重要里程碑，它们提供了专门为抵御前线战斗中毁灭性打击而定制的强化护甲。",["profession:Blacksmithing"]="弗伦·长须配方的成功应用凸显了尝试非传统回火方法和稀有海洋材料的价值。",["race:Gnome"]="克洛克莫特的工作表明，即使在重型盔甲锻造领域，侏儒的独创性也发挥着至关重要的作用，展示了机械精度如何提升传统的矮人工艺。"},sec={{t="学科的融合",b="锻造重甲通常是在Great Forge的巨型铁砧上完成，但克洛克莫特·扳手跨是在Tinker Town进行作业。这件护甲的诞生代表了矮人冶金传统与侏儒机械创新之间的一次合作胜利。通过采用弗伦·长须的严谨方法，克洛克莫特完成了一双经过特殊设计的护手，其强度足以承受足以压碎普通钢铁的重击。"},{t="无与伦比的韧性",b="据克洛克莫特所言，成品护甲拥有极高的结构完整性，即使攻城器械直接碾过也不会造成永久性变形。其秘诀在于对稀有组件的独特处理，证明了将古老的矮人锻造技术与侏儒独创性相结合，能够锻造出足以抵御最残酷前线战斗的护甲。"}},faq={{q="谁是克洛克莫特·扳手跨？",a="克洛克莫特·扳手跨是一位技艺精湛的侏儒铁匠，居住在铁炉堡的Tinker Town。他协助处理复杂的机械任务，并与像弗伦·长须这样的矮人工匠合作，打造独特而耐用的装备。",al={"克洛克莫特","克洛克莫特是谁","tinker town的侏儒"}},{q="是谁设计了制造这种护甲的工艺？",a="锻造工艺是由弗伦·长须构思的，他是一位卓有成就的矮人盔甲锻造师。克洛克莫特遵循弗伦的精确方法来处理材料并最终完成护甲制作。",al={"谁发明了工艺","弗伦·长须护甲","弗伦方法"}},{q="为什么侏儒铁匠会制造这件护甲？",a="作为一名侏儒铁匠，克洛克莫特想尝试弗伦·长须的新技术来制作一件属于他自己的护甲。因为你曾帮助过弗伦，作为回报，他用你收集来的灼热珊瑚换取了这套成品护甲。",al={"为什么是侏儒","侏儒锻造","工程学护甲"}},{q="这种护甲与标准板甲相比有何特别之处？",a="克洛克莫特声称，成品护甲除了坚硬耐用外，还具备非凡的弹性和柔韧性。他夸口说，即使被沉重的攻城器械压扁，金属也能立刻恢复原状。",al={"强度如何","攻城器械护甲","护甲耐用度"}},{q="这套护甲在战士的训练之路上处于什么位置？",a="这件作品是那些寻求装备由铁炉堡最杰出的大师定制的坚韧护甲的联盟战士们，在完成一系列奉献任务后的最终成就。",al={"战士任务护甲","为什么要完成这个任务","战士奖励"}},{q="在哪里可以找到克洛克莫特？",a="克洛克莫特·扳手跨位于铁炉堡侏儒区的Tinker Town，那里到处都是车间、叮当作响的齿轮和蒸汽管道。",al={"克洛克莫特位置","扳手跨在哪里"}}},fx={fd9fc5fd={q="Klockmort Spannerspan 为什么要帮忙打造这套护甲？",a="Klockmort Spannerspan 接下这项工作，是为了检验弗伦·长须大胆的锻造理论。矮人锻造很少依赖精密的侏儒工程学，组装护手正好给了 Klockmort 一个机会，证明将弗伦的方法与侏儒机械结合，能打造出足以抵御攻城器械的护甲。",al={"klockmort 为什么帮忙","klockmort spannerspan 的动机","klockmort 为什么锻造这套护甲"}}},fp="20,309,23.429.0,20.378.0,29.238.0,44.190.0,43.227.0,57.241.0,62.195.0,25.138.0"}
P.entries["quest:1710"] = {n="晒焦的蛋壳",s="在达纳苏斯，护甲商马希尔与矮人铁匠弗伦·长须合作，改进了一种新的锁甲制造技术。他委托勇士前往千针石林，从风巢的高处收集坚固的双足飞龙蛋壳。",h="在达纳苏斯，护甲商马希尔与矮人铁匠弗伦·长须合作，改进了一种新的锁甲制造技术。他委托勇士前往千针石林，从风巢的高处收集坚固的双足飞龙蛋壳。",kw={"蛋壳","弗伦·长须","风巢","漆","锁甲","马希尔","千针石林","双足飞龙"},ang={["class:Warrior"]="马希尔的实验旨在锻造坚韧的锁甲，对于寻求升级战斗装备的联盟勇士来说，这是必经的试炼。",["faction:Alliance"]="这次合作突显了达纳苏斯的暗夜精灵工匠与暴风城的矮人护甲商之间的技术交流。",["profession:Blacksmithing"]="这个任务展示了一种不同寻常的锻造技术：将野兽的成分提炼成保护漆，以处理金属链环。"},sec={{t="跨阵营的锻造联盟",b="马希尔在达纳苏斯的战士区工作，但他的技艺远超传统的暗夜精灵工艺。他与暴风城的著名矮人护甲商弗伦·长须保持着书信往来。受到弗伦在冶金和护甲锻造方面发现的启发，马希尔试图锻造一套由天然材料加固、能够承受极端压力的锁甲。为了验证这一混合理论，他需要一些在泰达希尔附近无法找到的奇异材料。"},{t="风巢的危险",b="马希尔实验的关键在于跨越海洋的南方，即千针石林的峡谷深处。在那里，高耸于盐碱滩和红色石台之上，风巢的双足飞龙在卡利姆多烈日的炙烤下筑巢。它们的蛋壳因长期暴露在灼热的高温和高海拔环境中而变得坚硬。马希尔打算将这些晒焦的碎片粉碎并制成一种坚韧的漆，涂在锁甲的链环上，从而制造出既灵活又异常耐用的护甲。"}},faq={{q="马希尔是谁？",a="马希尔是一位居住在达纳苏斯战士区的暗夜精灵护甲商。他与弗伦·长须合作，密切运用矮人的锻造方法，为久经考验的勇士开发先进的锁甲。",al={"马希尔","谁提供晒焦的蛋壳","马希尔 达纳苏斯"}},{q="马希尔为什么需要双足飞龙蛋壳？",a="来自风巢的双足飞龙蛋壳在千针石林酷烈的阳光下被烘烤和硬化。马希尔将它们粉碎并提炼成一种特制的漆，用来涂抹在锁甲的链环上，使其具有优异的耐久度。",al={"为什么需要双足飞龙蛋壳","晒焦的蛋壳的用途","蛋壳是做什么用的"}},{q="风巢在哪里？",a="风巢是一座位于千针石林西部，靠近菲拉斯边界的陡峭台地。双足飞龙在悬崖和高原上筑巢。",al={"风巢位置","风巢在哪里","如何找到风巢"}},{q="弗伦·长须与这个任务有什么关系？",a="弗伦·长须是一位驻扎在暴风城的矮人护甲大师。马希尔将弗伦视为受人尊敬的同行，并利用弗伦的护甲锻造发现来激发他在达纳苏斯的工作灵感。",al={"弗伦·长须的联系","谁是弗伦"}},{q="为什么达纳苏斯的精灵会要求使用千针石林的材料？",a="马希尔所需的特定化学韧性是那些暴露在南方峡谷台地无情干热环境下的双足飞龙蛋所独有的，这种条件在泰达希尔那多雾的枝桠间是无法复制的。",al={"为什么是千针石林","从达纳苏斯到千针石林"}},{q="把蛋壳带给马希尔之后会发生什么？",a="一旦马希尔收到二十个晒焦的蛋壳，他就会立即开始提炼这种漆，并锻造一套定制的锁甲作为对你野外工作的奖励。",al={"接下来马希尔做什么","晒焦的蛋壳之后","马希尔后续任务"}}},fx={dd37f0b8={q="晒焦的蛋壳有什么用？",a="风巢双足飞龙产下的蛋壳十分坚韧，出乎意料。Mathiel 打算将它们打碎并熬制成防护漆，用来涂覆实验性锁甲的每一节链环，以提高锁甲的耐久度。",al={"晒焦的蛋壳用途","为什么要晒焦的蛋壳","这些蛋壳有什么用"}}},fp="18,244,33.501.0,23.484.0,15.204.0,36.215.0,27.148.0,46.195.0,70.202.0,50.169.0"}
P.entries["quest:1711"] = {n="玛希尔的铠甲",s="“Mathiel's Armor”标志着Mathiel在达纳苏斯的战士区所进行的锻造工作圆满完成。通过将他自己的暗夜精灵工艺与弗伦·长须发明的创新矮人金属加工方法相结合，Mathiel将奇异的材料重铸成了坚固的战斗装备。该任务体现了联盟种族在为战士们服务时卓有成效的传统融合。",h="“Mathiel's...",kw={"工匠区","达纳苏斯","弗伦·长须","mathiel","mathiel的护甲","sunscorched shells","战士护甲"},ang={["class:Warrior"]="对于联盟的战士们来说，这个任务链产出的坚固护腿是结合了暗夜精灵与矮人锻造师冶金智慧的结晶。",["faction:Alliance"]="Mathiel与弗伦的合作说明了联盟在军事上的实际益处，通过共享贸易和共同防御将遥远的种族团结在一起。",["profession:Blacksmithing"]="这个项目是阵营间锻造工艺的典范，证明了刚硬的矮人回火技术可以与优雅的暗夜精灵锻造工艺和谐共存。"},sec={{t="工艺的融合",b="暗夜精灵护甲锻造师传统上倾向于使用千锤百炼的方法，依靠与自然的和谐、柔软的皮革或精细加工的金属。然而，暗夜精灵与东部王国之间的交流促使像Mathiel这样的锻造大师开始尝试创新。通过采用来自矮人护甲锻造师弗伦·长须的新方法，Mathiel成功地将矮人冶金术与精灵艺术融为一体。"},{t="奇特的原材料",b="锻造这种坚韧的护甲需要收集来自千针石林风巢双足飞龙巢穴的日灼蛋壳。通过将这些经过阳光炙烤的硬壳制成漆料，并运用弗伦的加热处理配方，Mathiel成功打造出了一套足以抵御残酷前线战斗的坚韧护腿。"}},faq={{q="谁是Mathiel？",a="Mathiel是一位技艺精湛的暗夜精灵护甲锻造师，驻扎在达纳苏斯的战士区。他与联盟各地的同行紧密合作，测试由弗伦·长须等盟友开发的全新概念。",al={"mathiel","谁是mathiel","达纳苏斯护甲锻造师"}},{q="谁是弗伦·长须？",a="弗伦·长须是一位居住在暴风城的矮人护甲锻造大师。他因发明了用于回火和锻造特殊护甲板的创新技术而闻名，并经常与整个联盟的盟友锻造师分享说明和设计图。",al={"弗伦","弗伦·长须"}},{q="锻造护甲使用了什么材料？",a="这套护甲是使用从千针石林风巢双足飞龙巢穴下方收集的日灼蛋壳锻造而成的，Mathiel利用弗伦·长须的特定锻造工序对其进行了加固和定型。",al={"护甲材料","mathiel的护甲是由什么制成的"}},{q="为什么精灵会使用矮人的技术？",a="联盟的锻造师经常分享知识，以装备他们的战士来应对不断升级的威胁。虽然暗夜精灵的锻造工艺以精巧和耐用著称，但矮人的创新提供了卓越的淬火方法，Mathiel对此欣然采纳。",al={"为什么使用矮人锻造术","暗夜精灵与矮人的合作"}},{q="这个任务发生在哪里？",a="该任务在位于泰达希尔岛上、达纳苏斯战士区的锻造台处开始并完成。",al={"mathiel的位置","mathiel在哪里"}},{q="这个任务链的上一个任务是什么？",a="此任务紧随“Sunscorched Shells”之后，在该任务中，冒险者必须前往卡利姆多的远方，获取适合Mathiel工艺的坚硬蛋壳。",al={"前置任务","mathiels armor前置条件"}}},fx={["5fea36e4"]={q="Mathiel 为什么要为你打造这套护甲？",a="Mathiel 想要检验并证明弗伦·长须传授的技艺。他将矮人护甲锻造技艺与精灵传统结合起来，打造出极为坚韧的锁甲护腿，帮助为联盟而战的勇士增强防护。",al={"mathiel 为什么打造护甲","mathiel 的动机","为什么打造 mathiel 的护甲"}}},fp="15,404,17.422.0,17.323.0,15.220.0,23.251.0,44.200.0,39.251.0,33.118.0,41.174.0"}
P.entries["quest:1712"] = {n="塞克隆尼亚",s="塞克隆尼安是一位强大的风元素领主，人们寻找打败他的机会已经很久了。为了挑战他，勇士必须收集召唤该元素所需的组件，将其击败并夺取他的旋风之心。击败这位风领主，就能将那颗心脏的力量注入一件强大的武器之中。",h="塞克隆尼安是一位强大的风元素领主，人们寻找打败他的机会已经很久了。为了挑战他，勇士必须收集召唤该元素所需的组件，将其击败并夺取他的旋风之心。击败这位风领主，就能将那颗心脏的力量注入一件强大的武器之中。",kw={"勇士","塞克隆尼安","元素","召唤","旋风之心","风领主"},ang={["class:Warrior"]="击败风领主塞克隆尼安是一次定义实力的考验，通过夺取他的旋风之心并锻造强力武器来证明武艺的精湛。"},sec={{t="沉睡的风领主",b="塞克隆尼安是一位狂暴的风元素领主，他的存在让人心生敬畏与警惕。长久以来，一位专注的守望者一直在召唤地点保持警惕，等待着拥有足够纯粹武力、足以挑战并摧毁这个暴风雨实体的战斗者出现。"},{t="召唤风暴",b="召唤塞克隆尼安需要根据一张特殊羊皮纸上详细记载的稀有材料进行召唤仪式。一旦被召唤出来，就必须与这位风领主进行正面交锋，以此来考验挑战者究竟是一位真正的勇士，还是仅仅是他那呼啸狂风下的又一个牺牲品。"},{t="旋风之心",b="对抗风领主的终极目标是夺取他的旋风之心。一旦从被击败的元素身上取下，这颗心脏中狂暴的元素能量就可以被束缚并注入到一件适合资深勇士的武器中。"}},faq={{q="谁是塞克隆尼安？",a="塞克隆尼安是一位强大的风元素领主。他代表着一种严重的元素威胁，长久以来一直受到观察者的注视，他们都在等待一位足够强大的勇士去挑战并击败他。",al={"谁是塞克隆尼安","塞克隆尼安背景故事","什么是塞克隆尼安"}},{q="为什么要召唤塞克隆尼安？",a="召唤塞克隆尼安是为了让配得上这个资格的勇士对他进行挑战并将其击败。击败这位风领主可以让久经考验的战士夺取他的旋风之心，进而将其注入一件强大的武器中。",al={"为什么要召唤塞克隆尼安","塞克隆尼安的目的","为什么要战斗塞克隆尼安"}},{q="什么是旋风之心？",a="旋风之心是风领主塞克隆尼安的核心精华。当从被击败的元素身上撕裂下来后，其狂暴的能量可以直接锻造成一件拥有强大武力的武器。",al={"什么是旋风之心","塞克隆尼安之心","旋风之心的用途"}},{q="是谁在监视塞克隆尼安？",a="奥特兰克山脉的捕风者巴斯拉已经守候在此地多年，无止境地寻找着能够打倒这位元素领主并驾驭其狂暴之心的真正勇士。",al={"谁想让塞克隆尼安死","谁在监视塞克隆尼安"}},{q="如何召唤塞克隆尼安？",a="召唤塞克隆尼安需要收集记录在特殊羊皮纸上的特定稀有试剂，这些试剂的作用是将风领主引诱到这个世界上，以便对他发起挑战。",al={"如何召唤塞克隆尼安","塞克隆尼安的材料"}},{q="塞克隆尼安可以锻造什么武器？",a="收集了必要组件、成功召唤并击败塞克隆尼安的勇士，将获得一件注入了该元素旋风之心潜在怒火的武器。",al={"塞克隆尼安的奖励","塞克隆尼安的武器"}}},fp="9,298,24.270.0,21.268.0,19.234.1,17.190.0,31.198.0,28.192.0,32.209.0,31.171.0,37.161.0"}
P.entries["quest:1713"] = {n="召唤",s="“召唤”是神秘的巴斯拉·风语者发起的一项战士试炼，旨在召唤风领主塞克隆尼亚斯。战士通过召唤并击败这位狂暴的元素生物，即可获取“旋风之心”，从而将风暴之力灌注到武器之中。",h="“召唤”是神秘的巴斯拉·风语者发起的一项战士试炼，旨在召唤风领主塞克隆尼亚斯。战士通过召唤并击败这位狂暴的元素生物，即可获取“旋风之心”，从而将风暴之力灌注到武器之中。",kw={"巴斯拉·风语者","巴斯拉","塞克隆尼亚斯","元素生物","召唤","战士任务","旋风之心","风领主"},ang={["class:Warrior"]="面对塞克隆尼亚斯并夺取“旋风之心”是有抱负的战士们的一项决定性试炼，完成后可获得一把灌注了风暴原始力量的武器。",["race:Troll"]="巴斯拉·风语者引导着远离文明的古老原始技艺来驾驭风元素，这反映了巨魔萨满和巫医深奥的神秘传统。"},sec={{t="召唤风暴",b="“召唤”代表了巴斯拉·风语者筹备工作的顶峰。这位隐居的神秘者准备了一个古老的仪式，将风领主——可怕的元素生物塞克隆尼亚斯召唤到凡人位面。召唤者此举并非为了与风暴谈判，而是为了将其征服，并让一名有能力的勇士在它显形的一刻将其击倒。"},{t="风暴之心",b="这场对决的核心就是“旋风之心”，这是维持塞克隆尼亚斯实体形态的能量漩涡。一旦风领主落败，心脏被夺走，巴斯拉就会利用困在其中的狂风。这个不稳定的元素核心正是将风暴之力注入武器的催化剂。"}},faq={{q="塞克隆尼亚斯是谁？",a="塞克隆尼亚斯是一位强大的元素生物，被称为风领主。当巴斯拉·风语者通过仪式将其召唤出来时，他会化作一股狂暴的飓风，必须将其击败才能获得封印在其核心内的精华。",al={"塞克隆尼亚斯是谁","什么是塞克隆尼亚斯","塞克隆尼亚斯背景故事"}},{q="什么是旋风之心？",a="“旋风之心”是塞克隆尼亚斯的元素核心。巴斯拉·风语者需要用它来将风领主那狂乱且具破坏性的能量直接束缚到一件强大的武器中。",al={"什么是旋风之心","为什么需要旋风之心","旋风之心的用途"}},{q="巴斯拉·风语者是谁？",a="巴斯拉·风语者是一位居住在荒野中的巨魔神秘者，掌握着召唤塞克隆尼亚斯的知识。他指引战士完成仪式，并利用被击败的元素生物的心脏来锻造强大的武器。",al={"巴斯拉是谁","巴斯拉·风语者","召唤任务给予者"}},{q="为什么要召唤塞克隆尼亚斯？",a="召唤塞克隆尼亚的目的在于与风领主战斗，将其击杀并获取他的元素之心。这股精华随后被用于将飓风那永恒的怒火注入武器之中。",al={"为什么召唤塞克隆尼亚斯","召唤的目的","召唤的理由"}},{q="击败塞克隆尼亚斯后会发生什么？",a="一旦塞克隆尼亚斯被击败，并且他的“旋风之心”被交给巴斯拉，这位神秘者就能利用捕获的元素能量来强化武器，使之拥有塞克隆尼亚斯的风暴之力。",al={"击败塞克隆尼亚斯之后","塞克隆尼亚斯奖励背景","召唤仪式之后"}},{q="召唤仪式在哪里进行？",a="仪式在巴斯拉·风语者的营地进行，神秘者在那里汇聚必要的原始焦点，将塞克隆尼亚斯从元素位面牵引到物质世界。",al={"仪式在哪里进行","召唤地点"}}},fp="13,254,19.374.0,22.345.0,17.216.0,28.178.0,28.217.0,32.204.0,41.185.0,36.180.0"}
P.entries["quest:1714"] = {n="流放精华",s="“放逐之精”是一种神秘的转化仪式，核心是一个冒泡并喷出蒸汽的大熔炉。将护符投入其液态深处，旅行者会引发剧烈的反应，产生一块翻涌的熔岩团。它代表了挥发性试剂与元素力量的强大融合。",h="“放逐之精”是一种神秘的转化仪式，核心是一个冒泡并喷出蒸汽的大熔炉。将护符投入其液态深处，旅行者会引发剧烈的反应，产生一块翻涌的熔岩团。它代表了挥发性试剂与元素力量的强大融合。",kw={"气泡","大熔炉","护符","放逐之精","熔岩","转化","蒸汽"},ang={["class:Mage"]="炼金大熔炉和元素转化通常引导原始的挥发性魔法，将不同的精粹结合成固体形式。",["class:Shaman"]="利用元素精粹——即使是通过翻涌熔岩的大熔炉——也需要对所涉及的原始元素力量有所了解。"},sec={{t="一个诱人的大熔炉",b="“放逐之精”涉及一种围绕着神秘、冒泡的大熔炉进行的奇异转化。这个容器散发出诱人的蒸汽，引诱着旅行者前去探寻它那翻涌的深处。它作为一个元素容器，能够与特定的附魔护符发生剧烈的反应。"},{t="熔火坩埚",b="当所需的护符被沉入大熔炉中时，它们会缓慢地向底部下沉。随着混合物发生反应，一个巨大的气泡穿过粘稠的液体升起并破裂，露出了一块由混合材料锻造而成的翻涌熔岩团。"}},faq={{q="什么是“放逐之精”？",a="“放逐之精”是在大熔炉旁进行的神秘仪式。将护符投入容器那翻涌的深处，就会发生剧烈的转化，从而产生一块翻涌的熔岩团。",al={"什么是放逐之精","放逐之精任务"}},{q="将护符投入大熔炉会发生什么？",a="大熔炉里冒出的蒸汽吸引着旅行者靠近。当护符被投入其中，它们会缓慢下沉至底部，直到一个巨大的气泡冲破液面，留下一块熔岩。",al={"大熔炉发生了什么","大熔炉如何运作"}},{q="大熔炉会产生什么？",a="在护符沉入大熔炉的蒸汽液体中，并且一个巨大的气泡在表面破裂后，容器内会显现出一块翻涌的熔岩团。",al={"大熔炉产生什么","从放逐之精中得到什么"}},{q="这个仪式在哪里使用大熔炉？",a="该仪式直接在一个沸腾的大熔炉旁进行，其炽热的蒸汽吸引着任何靠近它的人，作为一个转化的祭坛发挥作用。",al={"大熔炉位置","我在哪里可以找到大熔炉"}},{q="为什么要把护符放进大熔炉里？",a="护符作为试剂在大熔炉的深处被消耗。将它们沉入加热的液体中可以催化熔岩的形成。",al={"护符有什么用","为什么要把护符放入大熔炉"}},{q="为什么大熔炉一直在冒泡？",a="翻涌的液体和诱人的蒸汽表明容器内正在进行活跃且强烈的化学或元素反应，随时准备转化任何进入其深处的物体。",al={"为什么它在冒泡","什么是蒸汽"}}},fp="20,311,20.290.0,19.255.0,33.213.0,52.203.0,31.166.0,43.142.0,40.146.0,40.173.0"}
P.entries["quest:1715"] = {n="已宰的羔羊",s="这项任务指引侏儒术士新手离开铁炉堡，前往人类领地寻求深造。由于国王麦格尼·铜须对矮人山脉中的黑暗修行者保持着严密的监视，导师们必须依靠暴风城的隐秘网络来完成学徒的训练。",h="这项任务指引侏儒术士新手离开铁炉堡，前往人类领地寻求深造。由于国王麦格尼·铜须对矮人山脉中的黑暗修行者保持着严密的监视，导师们必须依靠暴风城的隐秘网络来完成学徒的训练。",kw={"黑暗缚灵者加科因","诺莫瑞根","铁炉堡","拉戈·黑钳","mage quarter","slaughtered lamb","暴风城","术士"},ang={["class:Warlock"]="这段旅程标志着年轻联盟术士的重要通过仪式，将他们引荐给跨越种族界限、将修行者联系在一起的秘密地下网络。",["race:Dwarf"]="铁炉堡当局对恶魔实验毫无耐心，迫使城内的术士群体深入阴影之中，并迫使他们的学生另寻他处。",["race:Gnome"]="这个任务突显了侏儒在流亡中所面临的屈辱，在失去诺莫瑞根的学院后，他们被迫挤在铁炉堡狭窄的区域里，并不得不依赖人类的收留。"},sec={{t="流亡与审视",b="在诺莫瑞根陷落之前，卡兹莫丹的有志术士们曾在科技之城深处跟随他们自己的工程法师和恶魔学者学习。导致侏儒流亡的灾难摧毁了那些机构。幸存的修行者发现自己被挤在铁炉堡阴暗的地下洞穴中，在国王麦格尼·铜须和矮人守卫不信任的目光下活动。由于无法在如此狭窄的空间里公开练习恶魔技艺或进行危险的仪式，像拉戈·黑钳这样的资深导师别无选择，只能将他们的学生送走。"},{t="Mage Quarter的秘密地窖",b="这些流亡学生的目的地是Slaughtered Lamb，一家坐落在暴风城Mage Quarter不起眼的酒馆。在其酒吧下方，隐藏在蜿蜒的石廊和向下的台阶之后，是一处地下圣所，人类术士们在此聚集于阴影之中。在像黑暗缚灵者加科因这样经验丰富的召唤师的监督下，这个隐秘的据点提供了必要的空间和黑暗法器，用以教导新手如何召唤并束缚次级恶魔，而不会引来城市治安官的直接愤怒。"},{t="阴影中增长的压力",b="虽然暴风城的秘会欢迎有能力的新人，但难民新手们的涌入造成了摩擦。人类导师们已经在刀尖上行走，以避免被城市的圣骑士和当局发现。黑暗缚灵者加科因和他的同僚们发现，从卡兹莫丹南下而来的修行者使得他们的秘密圣所日益拥挤。持续不断的矮人山脉来客可能会让他们的秘密行动暴露，但双方都没有更容易的选择。"}},faq={{q="为什么侏儒术士不能在铁炉堡训练？",a="国王麦格尼·铜须对铁炉堡的修行者保持着严密监视。随着诺莫瑞根的失落，流离失所的术士们没有自己的私人学院，这使得在矮人山脉内部进行危险的召唤仪式变得过于危险。",al={"为什么要送往暴风城","铁炉堡术士训练","为什么诺莫瑞根术士要离开"}},{q="卡兹莫丹的术士以前在哪里受训？",a="在过去，整个卡兹莫丹的黑暗修行者都是在诺莫瑞根的术士大师庇护下受训的。穴居怪的入侵和辐射中毒摧毁了那些机构，迫使幸存者进入了铁炉堡。",al={"诺莫瑞根术士历史","卡兹莫丹过去的术士训练"}},{q="谁是黑暗缚灵者加科因？",a="黑暗缚灵者加科因是一位资深人类术士，常驻于暴风城Slaughtered Lamb下方的墓穴中。他教导学徒束缚和召唤恶魔，包括从卡兹莫丹南下而来的侏儒新手。",al={"谁是加科因","加科因的角色"}},{q="什么是Slaughtered Lamb？",a="Slaughtered Lamb是一家位于暴风城Mage Quarter的酒馆。虽然街面的建筑看起来很普通，但其下方的深层地窖隐藏着一个秘密的术士聚集地，在城市当局的视线之外运作。",al={"slaughtered lamb酒馆","slaughtered lamb在哪里"}},{q="为什么加科因对新来者感到不满？",a="加科因担心大量的侏儒难民涌入会为暴风城的秘密秘会引来不必要的关注。空间和教师有限，过多的术士活动有被城市当局发现的风险。",al={"加科因的抱怨","为什么加科因很生气"}},{q="谁是拉戈·黑钳？",a="拉戈·黑钳是一位居住在铁炉堡暗巷中的侏儒术士训练师。他对诺莫瑞根的失落和矮人的审视感到愤恨，他将有前途的新手派往暴风城以完成他们的基础契约。",al={"拉戈·黑钳","slaughtered lamb的任务发布者"}}},fx={["2a96a15b"]={q="拉戈·黑钳为什么派你去暴风城？",a="要想精进你的恶魔学识，拉戈·黑钳别无选择。诺莫瑞根沦陷、侏儒施法者逃往铁炉堡后，国王麦格尼·铜须一直警惕地监视着山中要塞里的黑暗魔法。在矮人的监视下，铁炉堡流亡的术士无法建立合适的训练圣所，只能放下身段，把有潜力的新手送往南方，交给人类大师指导。",al={"为什么派我去暴风城","黑钳的动机","为什么去被屠宰的羔羊酒馆"}}},fp="20,295,18.597.0,32.506.0,29.469.0,44.246.0,46.223.0,28.228.0,29.234.0,43.222.0,24.219.0"}
P.entries["quest:1716"] = {n="噬魂者",s="“噬魂者”是暴风城派遣的联盟术士为了学会召唤魅魔而必须完成的关键试炼。在黑暗缚灵者加科因的指引下，初学者必须穿越半个世界，前往贫瘠之地危险的荒野中，寻求先知塔卡尔的建议。",h="“噬魂者”是暴风城派遣的联盟术士为了学会召唤魅魔而必须完成的关键试炼。在黑暗缚灵者加科因的指引下，初学者必须穿越半个世界，前往贫瘠之地危险的荒野中，寻求先知塔卡尔的建议。",kw={"陶拉祖营地","黑暗缚灵者加科因","心木","slaughtered lamb","暴风城","魅魔","先知塔卡尔","贫瘠之地","术士任务"},ang={["class:Warlock"]="奴役魅魔象征着术士在操纵心灵和诱惑魔法方面迈向了精通，这要求施法者具备极大的身体胆识以获取稀有的仪式试剂。",["faction:Alliance"]="完成这项试炼会迫使联盟施法者深入充满争端的部落领地，这需要危险的海上旅行和横跨大陆的航行。"},sec={{t="危险的西部之旅",b="在暴风城Mage Quarter的Slaughtered Lamb地下，黑暗缚灵者加科因正在教导有潜力的术士进行下一次重要的召唤：魅魔。这种恶魔被描述为灵魂的吞噬者、心灵的摧毁者和意志的支配者，不能盲目地将其召唤到艾泽拉斯。这需要一种强力的诱饵，特别是与纯洁之爱相关联的物品，才能将它从扭曲虚空中引出，以便施法者能够击败并奴役它。获取这种信物需要暴风城的术士结社在当地无法提供的智慧。"},{t="敌对领土中的先知",b="为了追踪所需的催化剂，加科因将他的学徒送过了无尽之海，前往卡利姆多。在贫瘠之地干旱荒野的深处，靠近部落定居点陶拉祖营地，住着先知塔卡尔。对于联盟术士来说，找到塔卡尔意味着必须穿越充满敌对的半人马、野猪人和部落战士的荒野，这本身就是一场不言自明的生存考验，甚至在召唤者开始准备仪式之前就要面对。"}},faq={{q="这个任务的目的是什么？",a="这项任务将联盟术士从暴风城派往卡利姆多，以学习如何召唤并奴役一只完全听命于他们的魅魔仆从。",al={"为什么要完成噬魂者任务","魅魔任务目标","术士魅魔任务线"}},{q="为什么我必须大老远跑到贫瘠之地去？",a="黑暗缚灵者加科因深知，召唤魅魔需要一种情感催化剂——一种纯洁之爱的象征——来引诱恶魔跨越位面。居住在贫瘠之地的先知塔卡尔掌握着寻找这种神器所需的特殊奥术知识。",al={"为什么要前往卡利姆多","为什么要前往贫瘠之地","为什么任务要去这么远"}},{q="谁是黑暗缚灵者加科因？",a="加科因是一位隐藏在暴风城Slaughtered Lamb地下墓穴中的召唤大师。他在避开城防卫兵视线的地方，教导新手术士关于恶魔契约、奴役以及黑暗魔法的知识。",al={"黑暗缚灵者加科因背景故事","谁发布了噬魂者任务"}},{q="谁是先知塔卡尔？",a="先知塔卡尔是一位隐居在贫瘠之地中部的神秘人物，位于牛头人前哨站陶拉祖营地外。他通过指引术士去寻找将恶魔诱入艾泽拉斯所需的圣物，以此帮助他们。",al={"先知塔卡尔在哪里","先知塔卡尔背景故事"}},{q="为什么召唤魅魔需要爱的象征？",a="正如加科因所解释的那样，魅魔以腐化人心和支配意志为生。它天生会被吞噬纯真、纯洁的感情所吸引，这使得浪漫的遗物成为将其从扭曲虚空中拉出来的唯一有效诱饵。",al={"为什么召唤魅魔需要爱","魅魔诱饵传说","魅魔的诱饵"}},{q="贫瘠之地对联盟角色安全吗？",a="不。贫瘠之地是部落的领土，充斥着敌对的野兽、野猪人部落以及像陶拉祖营地这样的部落定居点。联盟的旅行者在寻找塔卡尔时必须保持低调，并避开守卫。",al={"贫瘠之地危险吗","在贫瘠之地会受到部落攻击吗"}}},fx={["25fde1fe"]={q="黑暗缚灵者加科因为什么想让你办成这件事？",a="黑暗缚灵者加科因正在训练你，让你学会驾驭更危险的恶魔实体。要想提升术士的技艺，他要求你召唤、击败并束缚一名魅魔——这种恶魔残忍地吞噬灵魂，操纵心智。由于没有强大的情感诱饵，就无法引诱这样的实体穿越扭曲虚空，加科因才让你踏上这段漫长旅程，准备仪式所需的诱饵，以便让那只生物屈服于你。",al={"加科因为什么派我去","加科因与灵魂吞噬者的动机","加科因为什么要召唤魅魔"}}},fp="17,292,24.541.0,29.431.0,34.141.0,47.259.0,28.213.0,22.215.0,55.223.0,46.216.0"}
P.entries["quest:1717"] = {n="加科因的召唤",s="这是发给铁炉堡有潜力的联盟术士的一份召唤令，指示他们南下前往暴风城。黑暗缚灵者加科因在城内的法师区地下等待着他们，以监督他们进阶掌握更强大的恶魔。",h="这是发给铁炉堡有潜力的联盟术士的一份召唤令，指示他们南下前往暴风城。黑暗缚灵者加科因在城内的法师区地下等待着他们，以监督他们进阶掌握更强大的恶魔。",kw={"加科因","加科因的召唤","铁炉堡","拉戈·黑钳","mage quarter","slaughtered lamb","魅魔","术士"},ang={["class:Warlock"]="这个引导任务指示铁炉堡的术士返回暴风城，以开始束缚魅魔仆从的多阶段仪式任务线。",["faction:Alliance"]="展示了隐秘的术士网络如何在联盟首都之间保持联络，尽管他们在平民视线之外秘密地进行恶魔学研究。",["race:Gnome"]="在铁炉堡拉戈·黑钳手下训练的侏儒术士被引导至暴风城的地下网络，以获取更深奥的恶魔学教义。"},sec={{t="来自地下的信息",b="在整个联盟境内，恶魔学知识完全是在阴影中进行的。在铁炉堡，拉戈·黑钳代表暴风城的兄弟会默默地关注着往来的修行者。当一名术士对其最初的仆从展现出足够的掌控力时，消息便会迅速传开。拉戈会传递这一指令：放下你在卡兹莫丹雪山中的所有事务，立即南下报道。"},{t="回到“屠宰场羔羊”酒馆",b="在暴风城法师区的鹅卵石街道深处，在名为“屠宰场羔羊”的酒馆之下，黑暗缚灵者加科因负责协调城内术士的培养工作。加科因将每一位有能力的学员视为一项宝贵但危险的投资。收到他的召唤令标志着恶魔契约迈向了新的阶段，由此开启了降伏扭曲虚空中的魅魔所需的试炼。"}},faq={{q="是谁给我发的这份召唤令？",a="拉戈·黑钳，一位位于铁炉堡的术士训练师，他代表在暴风城负责恶魔学指导的黑暗缚灵者加科因发出了这份召唤令。",al={"任务给予者","任务起始","拉戈·黑钳"}},{q="我在哪里能找到黑暗缚灵者加科因？",a="加科因隐藏在“屠宰场羔羊”酒馆下的黑暗蜿蜒地下墓穴中，该酒馆位于暴风城的法师区。",al={"加科因位置","加科因在哪里","屠宰场羔羊酒馆位置"}},{q="加科因为什么要召唤我？",a="你的技艺已经进阶到可以承担召唤并降伏魅魔所需的仪式，这将扩充你的恶魔军火库。",al={"任务目的","这有什么用","为何被召唤"}},{q="我和加科因谈过之后会发生什么？",a="加科因会指派你一项名为“噬魂者”的任务，派遣你前往危险的土地获取召唤和束缚魅魔所需的仪式材料。",al={"下一步","后续任务","任务链"}},{q="为什么铁炉堡的术士要听命于暴风城？",a="出于必要，联盟的术士以一种谨慎、隐秘的网络形式运作。铁炉堡和暴风城的修行者保持联系，并将有潜力的学徒引导至加科因处，因为他在“屠宰场羔羊”酒馆下拥有专门的仪式装备和知识。",al={"铁炉堡术士","暴风城的侏儒术士","术士组织"}},{q="如果我想留在卡兹莫丹，我可以无视这份召唤令吗？",a="虽然你可以推迟前往暴风城，但如果不完成加科因的试炼，你就无法学会召唤魅魔，因此对于任何有志向的术士来说，这次旅程是必不可少的。",al={"这是必须的吗","可以跳过吗","需要去暴风城吗"}}},fx={["27281f2a"]={q="拉戈·黑钳为什么派你去暴风城？",a="拉戈·黑钳接到了暴风城同道的明确指示，要留意途经铁炉堡的有潜力术士。这个秘密团体已经在你的黑暗技艺上投入了大量时间和资源，拉戈希望确保你不会误入歧途，也不会在跟随黑暗缚灵者加科因学习、精进技艺之前丧命。",al={"拉戈为什么要办成这件事","拉戈·黑钳的动机","拉戈为什么派我去暴风城"}}},fp="15,220,30.427.0,30.399.0,26.160.0,37.136.0,26.144.0,36.165.0,59.260.0,58.166.0"}
P.entries["quest:1718"] = {n="岛民",s="“勇士岛试炼”是艾泽拉斯各地的资深战士训练师向那些在战斗中证明了自己基本实力的勇士发出的邀请。它指引初露头角的战士前往商旅海岸外的勇士岛，在那里，一个孤立的战士兄弟会通过纯粹的肉搏战来考验同僚。会见首席战士克兰诺克·马克雷德，是迈向掌握高级战斗技巧的关键一步。",h="“勇士岛试炼”是艾泽拉斯各地的资深战士训练师向那些在战斗中证明了自己基本实力的勇士发出的邀请。它指引初露头角的战士前往商旅海岸外的勇士岛，在那里，一个孤立的战士兄弟会通过纯粹的肉搏战来考验同僚。会见首席战士克兰诺克·马克...",kw={"勇士岛","克兰诺克·马克雷德","商旅海岸","棘齿城","大乱斗","贫瘠之地","勇士岛试炼","战士"},ang={["class:Warrior"]="这种成人礼是战士专属的，标志着从学习基础招式到解锁资深姿态的全部凶猛力量和战术多样性的关键转变。",["faction:Alliance"]="联盟战士必须跨越海洋或穿越卡利姆多的荒野才能到达勇士岛，在远离人类和矮人要塞的崎岖边境展现对武道的虔诚。",["faction:Horde"]="从雷霆崖或奥格瑞玛出发，部落战士一路南下前往贫瘠之地，在酋长们视线之外证明自己的实力。"},sec={{t="利刃集结",b="联盟和部落各大主城的战士训练师都清楚学生何时已经超越了基础训练的水平。武艺的精进并不取决于正式军衔或政治忠诚，而是要求战士在真正的同僚面前衡量自己的实力。这段旅程将战士们从文明的训练场送往无尽之海中一座荒凉的孤岛。"},{t="勇士岛与商旅海岸",b="勇士岛位于商旅海岸以东，就在贫瘠之地地精港口棘齿城的南面。通过游过水下的浅滩沙洲即可抵达。在这块礁石上，政治纽带在战士情谊面前消融；战士们聚集在岛上的首席战士克兰诺克·马克雷德的注视下，等待着他认为必要的任何残酷考验。"}},faq={{q="什么是勇士岛？",a="勇士岛是一块位于贫瘠之地商旅海岸外、棘齿城南面的岩石露头。它是一个孤立的试炼场，艾泽拉斯各地的战士汇聚于此，远离世俗的权威，磨练技艺，进行切磋，并面对艰苦的战斗考验。",al={"勇士岛在哪里","勇士岛背景故事","勇士岛"}},{q="谁是克兰诺克·马克雷德？",a="克兰诺克·马克雷德是坐镇勇士岛的首席战士。他负责评估前往该岛的充满希望的竞争者，决定他们的精神和技巧是否值得在 The Warrior's Path 上获得进一步的指引。",al={"谁是克兰诺克","克兰诺克·马克雷德的角色","马克雷德战士"}},{q="为什么部落和联盟的训练师都要把战士送到这里？",a="真正的武艺精通超越了阵营的界限。奥格瑞玛、暴风城、雷霆崖和铁炉堡的大师级训练师们都认识到，纯粹的武艺必须在毫无保留的战斗中得到检验，而勇士岛正是作为一个无需明说的试炼场，为任何能够幸存下来的战士提供考验。",al={"为什么两个阵营都要去这里","勇士岛是中立的吗","部落与联盟勇士岛"}},{q="从大陆如何前往勇士岛？",a="沿着贫瘠之地棘齿城港口外的商旅海岸向南行进。从海岸线出发，穿过沙洲浅滩，向东游过开阔水域即可抵达该岛。",al={"如何前往勇士岛","勇士岛指引","寻找勇士岛"}},{q="见到克兰诺克·马克雷德后会发生什么？",a="一旦克兰诺克确认你已经完成了旅程并评估了你的决心，他就会邀请你参加“大乱斗”——这是一场旨在考验你在面对一波又一波挑战者时的战斗耐力的生死考验。",al={"勇士岛试炼之后是什么","克兰诺克·马克雷德后续任务"}}},fx={b7452d18={q="战士训练师为什么派你去勇士岛？",a="你在城市中的训练已经让你达到常规操练所能带来的极限。随着声望渐长，你的导师明白，真正的武艺无法从练习假人或友好切磋中学到。他们派你去找克兰诺克·马克雷德，让你与来自世界各地的真正对手较量，检验自己是否真正有资格继续踏上战士之路。",al={"为什么派我去勇士岛","岛民训练师的动机","训练师为什么要我去"}}},fp="12,393,21.364.0,34.375.0,20.263.0,23.232.0,64.296.0,47.188.0,43.199.1"}
P.entries["quest:1719"] = {n="格斗考验",s="勇士之争是在贫瘠之地海岸外的勇士岛上举行的一场残酷武术考验。这项竞技场混战由克兰诺克·马克雷德主持，它将雄心勃勃的战士们投入到一波又一波岛上挑战者及其冠军的围攻中，以证明他们具备了接受进阶训练所需的勇气与实力。",h="勇士之争是在贫瘠之地海岸外的勇士岛上举行的一场残酷武术考验。这项竞技场混战由克兰诺克·马克雷德主持，它将雄心勃勃的战士们投入到一波又一波岛上挑战者及其冠军的围攻中，以证明他们具备了接受进阶训练所需的勇气与实力。",kw={"勇士之争","贫瘠之地","大个子威尔","勇士岛","克兰诺克·马克雷德","特威吉·平头","战士考验"},ang={["class:Warrior"]="勇士之争是资深战士决定性的成人礼，它是一个熔炉，让他们在此证明自己的战斗姿态和战场耐力，从而解锁更深奥的技艺。"},sec={{t="无尽之海上的试炼场",b="勇士岛远离大陆的纷争，是强悍的格斗者、流亡者和战斗导师们的避难所。克兰诺克·马克雷德并不会随随便便教导任何一个走下船的流浪者。若想获得他的指点，有志向的战士必须参加勇士之争，这是一场旨在将真正的战士与虚张声势的伪善者区分开来的武术耐力与战场意识的公开考验。"},{t="铁与血的圆环",b="勇士之争的规则既简单又冷酷。当战士踏上围观人群中央的铁栅栏时，即是向擂台主持特威吉·平头发出开始比赛的信号。挑战者将接连不断地进入擂台，考验初学者的耐力。那些在前期战斗者中幸存下来的人，将面对该岛的重量级冠军——大个子威尔。击败他，是赢得克兰诺克尊重的唯一条件。"}},faq={{q="什么是勇士之争？",a="勇士之争是在勇士岛上举行的一种竞技场式的考验。它旨在测试有志向的战士是否具备接受克兰诺克·马克雷德高级战斗训练所需的原始耐力和技巧。",al={"勇士之争考验","什么是勇士之争","勇士岛竞技场"}},{q="勇士之争在哪里举行？",a="它在勇士岛举行，这是一座位于无尽之海、贫瘠之地东海岸外的崎岖岛屿。",al={"勇士之争在哪里","勇士之争位置"}},{q="谁负责组织这项考验？",a="战士导师克兰诺克·马克雷德负责管理岛上的战士并主持这项考验，而特威吉·平头则在坑边指挥比赛。",al={"谁举办勇士之争","勇士之争组织者"}},{q="擂台上的战斗是如何进行的？",a="战士踏上中央的铁栅栏以示准备就绪。随后，特威吉·平头会将一波又一波的勇士之争挑战者送入坑中，最后才会放出岛上强壮的冠军——大个子威尔。",al={"战斗如何进行","勇士之争波数","开始勇士之争"}},{q="大个子威尔是谁？",a="大个子威尔是勇士岛格斗者中公认的冠军。在擂台上击败他是通过勇士之争的最终要求。",al={"大个子威尔","大个子威尔是谁","勇士岛冠军"}},{q="为什么战士必须完成这项考验？",a="克兰诺克·马克雷德拒绝将他的武术技巧传授给那些未能在鲜血与战斗中对抗多名对手、证明自己坚韧程度的人。",al={"为什么要进行勇士之争","勇士之争目的"}}},fx={["0df51000"]={q="克兰诺克·马克雷德为什么不亲自考验你，而是要你去战斗？",a="克兰诺克·马克雷德不会把高阶战斗训练浪费在每个乘船来到勇士岛、只会夸夸其谈的莽汉身上。勇士竞技场专为崭露头角的战士设立，是一场耐力试炼。他把你投入竞技场，让你迎战一波又一波身经百战的挑战者和冠军 Big Will，自己则在远处观察，评判你在真正压力下的勇气、控场能力和耐力，再决定是否收你为徒。",al={"为什么是我，克兰诺克","克兰诺克为什么考验我","为什么要参加勇士竞技场"}}},fp="10,285,33.402.0,28.428.0,19.184.0,33.108.0,24.152.0,37.197.0,16.131.0,38.148.0"}
P.entries["quest:173"] = {n="森林里的狼人",s="卡洛尔，一位驻扎在夜色镇、对现状感到失望的前卫兵，委托冒险者去猎杀潜伏在暮色森林中那些邪恶的夜行影织者。通过前往阳光树林和烂果园进行狩猎，外来者可以向乔纳森·卡尔文大师的怪物猎人小队证明自己的实力。",h="卡洛尔，一位驻扎在夜色镇、对现状感到失望的前卫兵，委托冒险者去猎杀潜伏在暮色森林中那些邪恶的夜行影织者。通过前往阳光树林和烂果园进行狩猎，外来者可以向乔纳森·卡尔文大师的怪物猎人小队证明自己的实力。",kw={"阳光树林","卡洛尔","卡尔文","夜色镇","暮色森林","夜行生物","烂果园","影织者","狼人"},ang={["class:Hunter"]="猎杀夜行生物是对追踪术和野兽知识的极限考验，因为狼人既不是天然的野生动物，也不是普通的人类歹徒，而是会施展暗影法术的双足恐怖生物。",["faction:Alliance"]="夜色镇感觉已经被暴风城的High Seat完全抛弃，这使得镇民和像卡洛尔这样的义勇军不得不招募任何能抵挡怪物的游荡联盟冒险者。",["race:Human"]="对于来自艾尔文森林或西部荒野的人类来说，目睹暮色森林中如烂果园般的农场遭受的悲惨破坏，是对未受遏制的黑暗魔法能对王国粮仓造成何种影响的严峻警告。"},sec={{t="私人守卫",b="守夜人始终在与不断逼近夜色镇边界的亡灵、蜘蛛和歹徒进行斗争。对于像卡洛尔这样的人来说，官方卫队不仅行动迟缓，而且在净化土地方面表现得过于安于现状。卡洛尔离开了守夜人，转而投靠乔纳森·卡尔文大师，誓要将自己的利剑挥向异端与腐化，将它们彻底根除。但卡尔文大师并不会随意接纳任何人加入他的圈子；那些想要协助他们的人，必须首先证明自己能在森林中最凶猛的恐惧面前幸存下来。"},{t="夜行潜伏者",b="试炼之地位于阳光树林和遭受重创的烂果园，被称为狼人的野性犬科生物在此盘踞。其中，夜行影织者能够驾驭黑暗魔法，在将受害者撕碎之前，先使其致盲并束缚住他们。卡洛尔派遣有志向的猎人去击杀这些会使用法术的野兽，既是为了考验外来者的决心，也是为了削减这一威胁，而这些怪物的起源至今仍让夜色镇的保卫者们感到极度不安。"},{t="凭空出现的怪物",b="虽然狼人在暮色森林中已成为一场无法逃避的噩梦，但它们的存在令人费解。卡洛尔指出，狼人似乎是凭空出现的，在该地区并无自然血缘。与那些贪婪的野狼或从当地墓穴中爬出的尸体不同，这些双足捕食者掌握着离奇而陌生的巫术。猎杀影织者可以展现战斗技巧，但这只是触及了这种在森林中扎根的非自然灾难的表面。"}},faq={{q="卡洛尔是谁？",a="卡洛尔是一名猎人，也是夜色镇守夜人的前成员。由于对镇民兵谨慎的官僚作风感到沮丧，他加入了乔纳森·卡尔文大师的麾下，积极猎杀威胁着暮色森林的邪恶生物。",al={"卡洛尔","卡洛尔 夜色镇","谁发布了林中的狼人任务"}},{q="卡洛尔为什么要猎杀夜行影织者？",a="卡洛尔将夜行影织者作为对他人的技巧和勇气的试炼。任何想要协助卡尔文大师任务的人，都必须证明自己能够猎杀危险的施法狼人，而不是只会空谈保卫小镇。",al={"为什么要击杀影织者","林中的狼人任务目标"}},{q="在哪里可以找到夜行影织者？",a="它们潜伏在夜色镇西部和西南部的两个主要区域：阳光树林那些扭曲的树木之间，以及废弃且杂草丛生的烂果园。",al={"夜行影织者在哪里","影织者位置"}},{q="暮色森林的狼人是从哪里来的？",a="对于暮色森林的人民来说，它们的突然出现是一个谜。正如卡洛尔所观察到的，这些野兽仿佛凭空显现，将黑暗的暗影魔法和贪婪的狂暴带入了一片本已濒临崩溃的森林。",al={"暮色森林狼人起源","为什么暮色森林有狼人","狼人从哪来"}},{q="卡尔文大师是谁？",a="乔纳森·卡尔文大师是一位驻扎在夜色镇的独立怪物猎人。他和他的追随者在守夜人的管辖范围之外行动，专注于彻底根除整个地区的邪恶、亡灵和奇异的怪物。",al={"卡尔文","卡尔文大师","卡尔文大师是谁"}},{q="卡洛尔为什么要离开守夜人？",a="卡洛尔对守夜人的消极和自满感到失望。当黑暗不断逼近时，比起在周边的围栏上驻守，他更倾向于卡尔文那种猎杀邪恶的主动方式。",al={"为什么卡洛尔离开守夜人","卡洛尔 守夜人"}}},fx={e85e2f18={q="夜行暗影施法者是什么？",a="夜行暗影施法者是潜伏在阳光树林和烂果园等地的施法狼人。这些狼形野兽突然出现在暮色森林各处，施展黑暗魔法，威胁着夜色镇的边境。卡洛尔和 Carevin 大师认为，它们的突然出现正给林地带来祸患，必须彻底铲除。",al={"夜行暗影施法者是什么","夜行暗影施法者","狼人是什么"}},["5ce72e6e"]={q="卡洛尔为什么需要你来猎杀狼人，而不亲自出手？",a="卡洛尔已经脱离了守夜人，因为他对他们的自满和不作为感到失望。如今，他协助 Carevin 大师致力于铲除暮色森林的异端与邪恶，并要求所有想加入他们的新来者用行动证明自己，而不是空口承诺。",al={"为什么派我去","卡洛尔为什么需要我","为什么不是守夜人"}}},fp="19,294,15.526.0,21.451.0,21.485.1,13.230.0,52.237.0,45.160.0,43.222.0,22.228.0,36.213.0"}
P.entries["quest:1738"] = {n="同心树",s="Heartswood是一项联盟术士任务，它派遣修行者深入灰谷，以寻回一颗古老而悲情的树木的枝条。术士们受隐士先知塔卡尔之托，代表黑暗缚灵者加科因寻找这一浪漫遗物，将其作为诱饵，在暴风城引诱并奴役一只魅魔。",h="Heartswood是一项联盟术士任务，它派遣修行者深入灰谷，以寻回一颗古老而悲情的树木的枝条。术士们受隐士先知塔卡尔之托，代表黑暗缚灵者加科因寻找这一浪漫遗物，将其作为诱饵，在暴风城引诱并奴役一只魅魔。",kw={"anathera","灰谷","贫瘠之地","暗滩教派","黑暗缚灵者加科因","heartswood","latherion","奥迪拉兰","魅魔","先知塔卡尔"},ang={["class:Warlock"]="获得Heartswood的一块碎片对于初出茅庐的术士来说是一个关键的里程碑，使他们能够召唤并奴役一只魅魔，在战场上操纵敌人的思想。",["faction:Alliance"]="前往卡利姆多会让年轻的联盟施法者暴露在充满争议的荒野、敌对的部落前哨以及古老的暗夜精灵废墟之中。",["race:Human"]="暴风城中隐藏的术士往往依赖像先知塔卡尔这样遥远的侦察兵，来定位那些人类奥术师从未记录过的旧卡利姆多遗物。"},sec={{t="悲剧爱情的纪念碑",b="根据先知塔卡尔的说法，Heartswood树生长的地方，是两名暗夜精灵恋人Anathera和Latherion在万年前的上古之战中共同倒下的地方。在他们最后的呼吸和永恒的爱意滋养下，这棵树长成了纯洁不朽爱情的象征。对于凡人而言，它是一座神圣而悲伤的纪念碑，但对于黑暗艺术的修行者来说，集中的情感能量是强大的魔法燃料。"},{t="诱捕魅魔",b="魅魔以凡人的激情、欲望和情感折磨为食。塔卡尔意识到，与浸透了数千年纯粹、不朽爱意的神器相比，普通的诱惑显得苍白无力。Heartswood的一部分为黑暗缚灵者加科因提供了将这些狡猾的恶魔通过虚空，引诱到暴风城Mage Quarter的召唤仪式中所需的精确催化剂。"},{t="奥迪拉兰废墟",b="这棵树屹立在灰谷西北部的奥迪拉兰废墟中。然而，取回它不仅需要面对野生猛兽和敌对领土，还要应对占据了精灵废墟的暗滩教派邪教徒。一旦取回，就必须穿过海洋，带回暴风城的Slaughtered Lamb，以开启奴役仪式。"}},faq={{q="为什么术士需要Heartswood来召唤魅魔？",a="魅魔是被激情、欲望和强烈情感羁绊所吸引的恶魔。Heartswood发芽的地方是两名忠贞的暗夜精灵恋人在一万年前共同陨落之处。他们挥之不去的激情灌注到了木头中，创造了将魅魔通过虚空吸引过来的绝佳精神诱饵。",al={"为何需要heartswood","魅魔诱饵","为何用木头召唤魅魔"}},{q="Heartswood树生长在哪里？",a="它位于灰谷西北部森林中的奥迪拉兰废墟，在黑海岸以南不远的地方。该地区已经落入了邪恶教派的手中。",al={"heartswood位置","heartswood在哪里","如何找到heartswood"}},{q="Anathera和Latherion是谁？",a="他们是两名在上古之战中并肩作战的暗夜精灵。当他们在战场上共同倒下时，Heartswood树在他们弥留之际呼出最后一口气的地方发芽，作为他们坚贞爱情的纪念碑。",al={"anathera和latherion","那对恋人是谁","灰谷的恋人"}},{q="先知塔卡尔是谁？",a="塔卡尔是一位与暴风城术士结盟的天赋异禀的人类先知。他选择居住在南贫瘠之地陶拉祖营地附近的隐居处，利用他神秘的视力穿透时间的迷雾，为黑暗缚灵者加科因寻找被遗忘的遗物。",al={"塔卡尔是谁","先知塔卡尔","贫瘠之地的隐士"}},{q="联盟术士如何从贫瘠之地安全前往灰谷？",a="从贫瘠之地穿越的联盟旅行者必须避开莫尔杉壁垒中戒备森严的部落前哨。术士通常会滑过主门东侧栅栏上一处无人看守的缺口，走石爪山脉的高路，或者游过边界河流。",al={"如何前往灰谷","绕过莫尔杉","避开部落壁垒"}},{q="加科因收到Heartswood后会发生什么？",a="加科因利用这块木头在暴风城Slaughtered Lamb下方的地下墓穴中准备仪式。他画了一个召唤法阵，从扭曲虚空中拉出一只魅魔，并指派术士去击败并奴役她。",al={"获得heartswood后做什么","加科因用heartswood做什么"}}},fx={bf8a48f3={q="为什么先知塔卡尔派你去寻找同心木？",a="塔卡尔是杜安·卡汉及其暴风城同伴的远见盟友。他以神秘视力搜寻时间迷雾，找到了足以诱捕并引诱魅魔穿越位面而来的神器，为你的到来做好准备。在这个秘密兄弟会中，他负责协助有志成为术士的人通过试炼。",al={"塔卡尔为何要同心木","塔卡尔为什么帮忙","塔卡尔为什么让我找同心木"}}},fp="10,301,25.441.0,20.398.0,23.359.1,53.288.0,36.177.0,32.249.0,22.254.0,73.271.0,49.228.0"}
P.entries["quest:1739"] = {n="誓缚",s="“束缚”是联盟术士在暴风城寻求奴役魅魔的最终入会仪式。实践者使用从同心树获取的附魔之核，进入Slaughtered Lamb下方的召唤法阵，将恶魔拖出并用武力将其制服。一旦被击败，恶魔的意志就会被链条锁住，从而使其对召唤者服从。",h="“束缚”是联盟术士在暴风城寻求奴役魅魔的最终入会仪式。实践者使用从同心树获取的附魔之核，进入Slaughtered...",kw={"束缚","地穴","黑暗缚灵者","加科因","同心树","slaughtered lamb","暴风城","魅魔","召唤法阵"},ang={["class:Warlock"]="这个仪式标志着人类和侏儒术士的一个关键里程碑，使他们从处理毫无思想的小鬼和虚空行者，转变为能够指挥有智慧、善于算计的恶魔。",["faction:Alliance"]="这个在暴风城深处进行的仪式表明，尽管有教会的教条，但联盟在私下里还是默许了阴影魔法在秘密角落的存在。"},sec={{t="深入地穴",b="在暴风城Mage Quarter的Slaughtered Lamb地板下，隐藏着一个专门用于禁忌魔法的巨大地穴。这里远离城市守卫和Cathedral of Light的监视，城中的隐秘术士结社在此处进行最危险的仪式。刻在石头上的召唤法阵引导着来自扭曲虚空的原始力量，使雄心勃勃的初学者能够撕裂世界之间的帷幕。"},{t="征服魅魔",b="召唤魅魔不仅仅需要吟唱咒语。术士必须携带一种媒介——在本例中是准备好的同心树之核——并在法阵处施展破界仪式。魅魔以腐化、诱惑和压倒即使是意志坚定的心灵而闻名。为了确立绝对的统治地位，召唤者必须在单挑中击败这只野兽，将其物理形态放逐回扭曲虚空，同时确立其真正的束缚。"},{t="加科因的秘密",b="在击杀被召唤的生物后，胜利的初学者将耗尽的内核带回给黑暗缚灵者加科因。在证明了自己的心理韧性和战斗能力后，学徒将获得在需要时跨越虚空召唤魅魔所需的基本知识。该仪式标志着联盟术士已成长为能够驾驭多变且有智慧的恶魔的专家。"}},faq={{q="召唤在哪里进行？",a="仪式在Slaughtered Lamb深处的地下墓穴中进行，这是一家位于暴风城Mage Quarter不起眼的酒馆。术士们沿着螺旋楼梯穿过酒馆地窖，进入一个配备有奥术召唤法阵的地下圣所。",al={"我在哪里召唤","魅魔召唤位置","地穴位置"}},{q="同心树之核的目的是什么？",a="同心树之核充当了锚点和催化剂的作用。它取自同心树，这棵树生长在“上古之战”期间两位暗夜精灵恋人在灰谷倒下的地方。它提供了撕裂局部裂隙并将魅魔从扭曲虚空吸引过来所需的精确精神共鸣。",al={"为什么使用同心树之核","同心树之核的作用"}},{q="为什么术士必须杀死魅魔？",a="扭曲虚空的恶魔只屈服于更强大的意志和力量。魅魔擅长心理操纵和精神征服；允许它在没有立即被击败的情况下显形会招致毁灭。在战斗中杀死该生物确立了统治地位，在它于扭曲虚空中重新凝聚之前，强行将术士的权威烙印在它的灵魂上。",al={"为什么要与魅魔战斗","为什么要杀死恶魔来束缚它"}},{q="黑暗缚灵者加科因是谁？",a="黑暗缚灵者加科因是一位居住在Slaughtered Lamb的资深术士，负责监督联盟术士在暴风城的训练。他负责协调恶魔学文物的秘密采购，并评估侍从是否有意志力将恶魔实体置于他们的掌控之下。",al={"谁是加科因","黑暗缚灵者加科因背景"}},{q="加科因提到的Surena是谁？",a="Surena Caledon是加科因以前的学生，她跟随迪菲亚兄弟会逃跑了，而你之前找回了她的项圈。加科因苦笑着怀疑她是否是一个伪装成人类、旨在扭曲他心智的魅魔，但他随后认为自己太高看她了。",al={"surena参考","surena是谁"}},{q="魅魔可以在暴风城的街道上出现吗？",a="神圣光教会和王国当局严禁公开进行恶魔学研究。虽然游戏机制允许被束缚的恶魔跟随术士穿过城市，但在背景设定中，这种做法仅限于阴影处、地下室和Slaughtered Lamb地穴等隐蔽的圣所中。",al={"守卫能看到我的魅魔吗","恶魔召唤在暴风城合法吗"}}},fp="11,188,22.291.0,26.323.0,15.283.1,36.206.0,43.278.0,39.271.0,28.254.0,34.229.0,50.257.0"}
P.entries["quest:174"] = {n="仰望星空",s="“仰望星空”开启了维克托·安特拉斯探索暮色森林阴森树冠之外的尝试。维克托坚信，除了奥术迷信之外，还有某种科学解释能够说明这片森林的黑暗诅咒，因此他招募你来为他的一位侏儒伙伴所设计的望远镜收集部件。",h="“仰望星空”开启了维克托·安特拉斯探索暮色森林阴森树冠之外的尝试。维克托坚信，除了奥术迷信之外，还有某种科学解释能够说明这片森林的黑暗诅咒，因此他招募你来为他的一位侏儒伙伴所设计的望远镜收集部件。",kw={"青铜管","考格","夜色镇","暮色森林","仰望星空","望远镜","维克托·安特拉斯"},ang={["faction:Alliance"]="当夜色镇的守夜人巡逻队在道路上抵御恐怖威胁时，维克托的项目代表了小镇微小而顽固的希望，他们想要了解究竟是什么毒害了他们的家园。",["profession:Engineering"]="整个工程完全取决于侏儒的设计和精湛的金属工艺，这让修理匠们有机会直接参与并协助维克托的天文探索。",["race:Gnome"]="维克托依赖于他那位侏儒伙伴考格的独创性，这证明了侏儒的技艺是如何即使在王国最黑暗的角落也能带来秩序与理性的。"},sec={{t="探索天空",b="在笼罩着夜色镇的阴霾与恐惧之中，维克托·安特拉斯对暮色森林的厄运有着一种截然不同的看法。维克托并不认为这片土地的腐化完全归咎于黑魔法、诅咒或不安分的亡灵，他怀疑在树冠之上有着更伟大的真理。在侏儒伙伴考格所绘制的蓝图的帮助下，他着手制造一台能够窥探天穹的光学仪器。"},{t="工程学问题",b="为了开始组装这台观星装置，维克托需要一个坚固的框架。按照考格的规格说明，他请求旅者去获取一根机械青铜管。这一步直接依赖于凡人机械的独创性而非咒法，突显了维克托固执的坚持，即实用的工艺与观察也许能让那些神秘主义失效的地方重见光明。"}},faq={{q="维克托·安特拉斯是谁？",a="维克托·安特拉斯是夜色镇的一位学者。与许多被恐惧瘫痪或被迷信所吞噬的当地人不同，他试图通过研究星辰来为暮色森林所遭受的腐化寻找合理的解释。",al={"维克托","谁给予仰望星空任务","维克托·安特拉斯"}},{q="维克托为什么要制造望远镜？",a="维克托相信在魔法之外存在着某种有形的真理，可以解释暮色森林的奇异变化。他希望通过望远镜凝视天空，能够揭示当地传说和施法者们所忽略的见解。",al={"为什么要观测星辰","为什么暮色森林需要青铜管","夜色镇望远镜任务"}},{q="考格是谁？",a="考格是一位侏儒工程师，也是维克托的朋友。他绘制了建造这台观星装置所需的机械蓝图。",al={"侏儒考格","谁设计了望远镜"}},{q="在哪里可以获得青铜管？",a="青铜管通常由拥有中等经验的工程师制作。并非工程师的旅者通常可以通过交易、拍卖行，或者从偶尔携带存货的旅行工程学商贩那里获得。",al={"如何获得青铜管","青铜管位置","在哪里寻找青铜管"}},{q="这是长任务线的一部分吗？",a="是的。这项任务是在夜色镇组装和校准维克托观星装置的多阶段工作的第一步。",al={"仰望星空任务链","仰望星空有多少个任务"}},{q="为什么维克托要在暮色森林寻找自然层面的解释？",a="尽管森林中爬满了亡灵和黑暗魔法，但维克托相信某种基本的宇宙或自然法则可能仍在支配着这种转变，这驱使他在对星辰的研究中寻求答案。",al={"为什么在暮色森林寻找科学解释","暮色森林的魔法与科学"}}},fx={["45e6e811"]={q="青铜管有什么用？",a="青铜管是维克托·安特拉斯正在建造的望远镜的主体结构。按照他的侏儒搭档考格提供的蓝图，金属外壳将作为必需的镜筒，用于安装光学透镜并将仪器对准天空。",al={"青铜管有什么用","维克托为什么需要青铜管","维克托青铜管的用途"}}},fp="17,288,19.432.0,23.382.0,28.217.0,43.230.0,11.130.0,36.237.0,35.128.0,60.201.0"}
P.entries["quest:1740"] = {n="索兰鲁克宝珠",s="索兰鲁克宝珠是南贫瘠之地的隐士杜安·卡汉指派给术士的一项试炼。有抱负的修行者会追踪散落在艾泽拉斯各处的破碎恶魔遗物，以重组一个禁锢着被放逐恶魔精华的容器。",h="索兰鲁克宝珠是南贫瘠之地的隐士杜安·卡汉指派给术士的一项试炼。有抱负的修行者会追踪散落在艾泽拉斯各处的破碎恶魔遗物，以重组一个禁锢着被放逐恶魔精华的容器。",kw={"黑暗深渊","恶魔","杜安·卡汉","索兰鲁克宝珠","扎尔甘宝珠","影牙","索兰鲁克","术士"},ang={["class:Warlock"]="重组索兰鲁克宝珠是术士职业的一个重要里程碑，它教会了术士军团如何惩戒其同类，以及如何将受束缚的恶魔实体转化为可用的器具。",["faction:Horde"]="杜安·卡汉居住在贫瘠之地严酷的旷野中，这使得南部的平原成为寻求高深黑暗知识的旅行召唤师们的必经之地。"},sec={{t="被放逐者的容器",b="在燃烧军团的等级制度中，失败意味着永恒的惩罚。当低阶恶魔不再受其恶魔主宰的青睐时，它们的灵魂就会被束缚并囚禁在水晶宝珠之中。这些神器随后被分发给军团的凡人召唤师和术士，作为原始且被驯服的力量的导管。即使碎裂成片，其中禁锢的恶魔精华依然保留着强大的魔法力量。"},{t="散布于各大陆",b="索兰鲁克宝珠并没能保持完整。它破碎成片，残骸散落在两块主要大陆的阴暗角落里。其中一半进一步碎裂，被灰谷黑暗深渊中潮湿洞穴里的暮光之锤教徒所把持。另一半较完整的部分则跨越海洋来到了银松森林，被影牙城堡闹鬼废墟中的一名巫师所占据。杜安·卡汉是一位终身研究军团宝珠的学者，他曾组装过扎尔甘宝珠，现在他利用回收的碎片将索兰鲁克宝珠重组成一件实用的器具。"}},faq={{q="什么是索兰鲁克宝珠？",a="索兰鲁克是燃烧军团中一名失宠的恶魔。按照恶魔的习俗，它的灵魂被囚禁在一颗魔法宝珠中，并交给了凡人修行者。后来宝珠碎裂，但即使是碎片也依然保留着被囚禁恶魔的力量。",al={"索兰鲁克背景故事","什么是索兰鲁克","索兰鲁克是谁"}},{q="杜安·卡汉是谁？",a="杜安·卡汉是一位隐居在南贫瘠之地的术士，他毕生致力于研究和重组燃烧军团的宝珠。他花费多年时间组装了自己的神器——扎尔甘宝珠，并协助新晋术士拼凑索兰鲁克宝珠。",al={"杜安·卡汉是谁","杜安·卡汉背景故事"}},{q="为什么宝珠会碎裂并散落在两个不同的地下城中？",a="最初的宝珠被分成了两块主要部分。其中一部分被碎裂成更小的碎片，由黑暗深渊中的暮光之锤教徒使用，而较大的残骸则被影牙城堡阴影笼罩的围墙内的一名巫师所占据。",al={"为什么碎片在黑暗深渊和影牙城堡","索兰鲁克碎片在哪里"}},{q="谁能承担这项任务？",a="这个任务仅供那些寻求精进技艺并掌握由被囚禁恶魔灵魂锻造的神器的术士进行。",al={"谁能完成这个任务","索兰鲁克宝珠是术士专属吗"}},{q="杜安·卡汉如何处理回收的碎片？",a="杜安·卡汉研究这些碎片以推进他对军团遗物的研究，然后将碎片重组成一件根据术士选择而塑形的完全复原的魔法器具。",al={"收集碎片后会发生什么","重组索兰鲁克"}},{q="什么是扎尔甘宝珠？",a="扎尔甘宝珠是一颗恶魔囚禁宝珠，杜安·卡汉耗费多年时间追踪并重组了它以供自己使用，其中禁锢着另一名被放逐的军团恶魔。",al={"扎尔甘宝珠","扎尔甘背景故事"}}},fx={f1114029={q="为什么杜安·卡汉想要索兰鲁克宝珠的碎片？",a="杜安·卡汉毕生致力于研究燃烧军团铸造的恶魔宝珠，并精研仿制之术。找回散落的索兰鲁克宝珠碎片，可以让他亲自检查容纳着一名失宠恶魔灵魂的容器，将长期研究付诸实践。",al={"杜安·卡汉为什么要宝珠","杜安·卡汉的动机","为什么要收集碎片"}},["32900559"]={q="索兰鲁克宝珠的碎片是什么？",a="索兰鲁克宝珠的碎片是破碎的索兰鲁克宝珠留下的小碎片。宝珠是一个容器，束缚着一名失宠于燃烧军团的恶魔的灵魂。暮光之锤的教徒将这些碎片带入黑暗深渊，企图利用其中残存的恶魔力量。",al={"索兰鲁克宝珠碎片的用途","索兰鲁克宝珠的碎片是什么","黑暗深渊的碎片"}},["321416b0"]={q="索兰鲁克宝珠的大碎片是什么？",a="索兰鲁克宝珠的大碎片是宝珠现存的主要部分。它仍蕴含着足够浓缩的恶魔精华，因此影牙城堡闹鬼的大厅里有一名黑暗法师夺取了它，用来增强自己的法术。",al={"索兰鲁克宝珠的大碎片","影牙城堡的碎片","大碎片的用途"}},["120120b9"]={q="谁持有宝珠碎片？",a="这些碎片落入了两个企图获取恶魔力量的危险势力手中。较小的碎片落入了在黑暗深渊海底密谋的暮光之锤信徒手中，而较大的残片则被一名潜伏在影牙城堡中的狡猾法师夺走。",al={"谁持有这些碎片","索兰鲁克宝珠碎片在哪里","谁持有宝珠碎片"}}},fp="20,247,24.444.0,27.600.0,29.264.0,19.280.0,52.248.0,28.137.0,54.184.0,27.170.0"}
P.entries["quest:175"] = {n="仰望星空",s="根据修补匠Cog提供的蓝图，维克托·安特拉斯正在夜色镇组装他的天文望远镜，他现在需要一面反射镜。他指引旅行者前往暮色森林南部去寻找玛丽，一位当地居民，因为她随身携带一面手镜而广为人知。",h="根据修补匠Cog提供的蓝图，维克托·安特拉斯正在夜色镇组装他的天文望远镜，他现在需要一面反射镜。他指引旅行者前往暮色森林南部去寻找玛丽，一位当地居民，因为她随身携带一面手镜而广为人知。",kw={"盲眼玛丽","夜色镇","暮色森林","仰望星空","手镜","玛丽","望远镜","静谧花园","维克托·安特拉斯"},ang={["faction:Alliance"]="帮助维克托建造他的望远镜，为这个饱受恐惧和腐朽侵蚀的城镇带来了一丝难得的好奇心与进步。",["profession:Engineering"]="望远镜的组装依赖于精确的光学规格，借鉴了侏儒的蓝图来反射和放大微弱的星光。"},sec={{t="反射镜面",b="在为望远镜准备好铜管后，维克托·安特拉斯开始着手处理Cog蓝图中的下一项需求：一面可以引导和反射光线通过设备镜筒的可靠镜子。由于夜色镇物资匮乏，无法从头锻造精细的镀银玻璃，维克托回想起玛丽，一位在该地区以随身携带手镜而闻名的当地居民。"},{t="搜寻南部",b="玛丽曾经的住所位于暮色森林深处的南部，就在闹鬼的静谧花园墓场北边。想要找到她，冒险者必须穿过守夜人的安全巡逻区，进入布满饥饿狼群、野性蜘蛛和游荡亡灵的枯萎林地。"},{t="悲惨的居民",b="来到玛丽位于南部的简陋小屋，展现出的是暮色森林衰败后的凄凉现实。维克托记忆中的那位女性已经不再是活着的居民，而是盲眼玛丽——一个游荡的灵魂，徘徊在她旧居和附近的墓场周围，被她生前的记忆和财物所束缚。"}},faq={{q="维克托·安特拉斯在建造什么？",a="维克托正在夜色镇山上的小屋里建造一台天文望远镜，他是按照一位名叫Cog的修补匠绘制的设计图进行工作的。",al={"维克托 望远镜","仰望星空任务","维克托在做什么"}},{q="为什么维克托需要一面手镜？",a="Cog的光学蓝图中需要一面镜子来反射并聚焦通过望远镜镜筒的光线。维克托记得玛丽随身带着一面手镜，希望能获得它来进行组装。",al={"为什么需要镜子","反射镜面 望远镜"}},{q="在哪里可以找到玛丽？",a="玛丽住在暮色森林东南部的一处废墟中，位置就在静谧花园墓场的北侧。",al={"玛丽在哪里","玛丽位置 暮色森林","找到盲眼玛丽"}},{q="玛丽是谁？",a="玛丽在土地陷入诅咒黑暗之前曾是暮色森林的居民，在夜色镇一带以随身携带手镜而闻名。她究竟发生了什么事，你必须在她靠近静谧花园墓场的旧居亲自查明。",al={"盲眼玛丽是谁","盲眼玛丽背景故事"}},{q="玛丽还有她的手镜吗？",a="当你接近她时，玛丽承认她曾经拥有过一面手镜，但她现在已经没有了，只能为你指出它的去向。",al={"玛丽有镜子吗","盲眼玛丽 手镜"}},{q="玛丽的小屋周围有什么危险？",a="东南部林地和邻近的静谧花园墓场到处都是敌对的亡灵、凶猛的暮色蝙蝠、毒网蜘蛛和狂犬，它们会捕食冒险前往夜色镇南部的旅行者。",al={"玛丽附近的危险","静谧花园墓场威胁"}}},fx={["9372b916"]={q="维克托·安特拉斯为什么如此执着于完成望远镜？",a="维克托·安特拉斯一心想在夜色镇的小屋里完成一架天文望远镜。按照侏儒考格提供的蓝图，他需要特殊部件来反射和聚焦光线。他希望透过笼罩暮色森林的永恒阴霾窥探远方，而搜集每一件罕见零件，都是让这件宏伟装置面世的关键。",al={"维克托为什么要你完成这件事","维克托·安特拉斯的动机","为什么要造望远镜"}}},fp="17,265,20.388.0,19.282.0,17.298.1,38.138.0,38.189.0,24.109.0,12.246.1,39.144.1,37.199.0"}
P.entries["quest:1758"] = {n="阴谋之书",s="《秘教秘典》会将一位渴望力量的联盟术士从棘齿城上方的高地送回铁炉堡图书馆。为了召唤并奴役一只贪婪的地狱猎犬，召唤者必须找到一本传说中的手册，那是由第一批征服了这种野兽的术士所著。",h="《秘教秘典》会将一位渴望力量的联盟术士从棘齿城上方的高地送回铁炉堡图书馆。为了召唤并奴役一只贪婪的地狱猎犬，召唤者必须找到一本传说中的手册，那是由第一批征服了这种野兽的术士所著。",kw={"地狱猎犬","hall of explorers","铁炉堡","克罗姆·粗臂","棘齿城","斯坦哈德·法尔杉","秘教秘典","术士"},ang={["class:Warlock"]="获得《秘教秘典》是黑魔法修行者寻求掌握地狱猎犬的关键仪式，这标志着他们不再仅仅满足于次等仆从，而是迈向了真正的反魔法恶魔学。",["faction:Alliance"]="联盟的修行者必须从卡利姆多的前线返回，前往铁炉堡的Hall of Explorers，利用矮人的学术研究来获取违禁的黑暗典籍。",["race:Dwarf"]="克罗姆·粗臂证明了并不是每个埋头在Hall of Explorers里的矮人都在挖掘泰坦神器——有些人正在私下里编撰恶魔知识。"},sec={{t="以魔法为食的野兽",b="奴役小鬼、虚空行者或魅魔都需要仪式，但地狱猎犬却带来了完全不同的危险。地狱猎犬不仅仅效力于燃烧军团，它们还会主动猎杀并吞噬奥术能量。普通的召唤法阵在它们面前会崩溃，并在束缚生效前就耗尽召唤者的魔法。斯坦哈德·法尔杉在贫瘠之地的据点中注视着棘齿城，他深知绝不能让一个业余者在毫无准备的情况下尝试这种束缚。"},{t="首次束缚",b="为了安全地召唤并束缚一只地狱猎犬，学徒需要《秘教秘典》中汇编的奥术公式。这本手稿由最早成功在没有外界帮助的情况下驯服地狱猎犬的凡人术士团体所著，详细记录了抵御这种生物的饥饿感所必需的特定地卜术、材料和束缚符文。对斯坦哈德和他的圈子来说，不幸的是，他们那本杰作的副本很久以前就丢失了。"},{t="丹莫罗的收藏家",b="斯坦哈德自己无法提供这本典籍，于是派遣联盟术士跨越无尽之海，前往铁炉堡的Hall of Explorers。那里潜伏着克罗姆·粗臂，一位云游四方的矮人术士，他将晚年时光都花在查阅古代手稿和图书馆记录上。如果在这片东部王国中还留有那本失落的魔典的任何踪迹，那一定就埋藏在克罗姆那严谨的目录之中。"}},faq={{q="我为什么要找到《秘教秘典》？",a="《秘教秘典》中包含了由第一批在没有外界帮助的情况下召唤并征服了地狱猎犬的凡人术士所写的精确指导。普通的召唤仪式不足以困住一只主动以魔法能量为食的恶魔。",al={"什么是秘教秘典","为什么要找书","秘教秘典的用途"}},{q="克罗姆·粗臂是谁？",a="克罗姆·粗臂是一位云游的矮人术士，居住在铁炉堡的Hall of Explorers图书馆里。他整日躲在满是灰尘的典籍中，整理着古代的历史记录。",al={"克罗姆在哪里","克罗姆·粗臂是谁","铁炉堡的克罗姆"}},{q="斯坦哈德·法尔杉为什么在贫瘠之地？",a="斯坦哈德·法尔杉是一位卓有成就的人类术士，在棘齿城上方的悬崖上维持着一个安静、中立的据点。他避开了肯瑞托和暴风城当局的监视，为联盟和部落的修行者传授强大的恶魔学知识。",al={"斯坦哈德的位置","为什么在棘齿城","斯坦哈德是谁"}},{q="我和克罗姆·粗臂交谈后会发生什么？",a="克罗姆·粗臂从旧的编目登记册中回忆起了关于这本典籍的记载。他会要求你追踪其丢失的部分，并找回重建这本魔典所需的稀有试剂。",al={"下一个任务","找过克罗姆之后","秘教秘典后续"}},{q="部落术士可以做这个任务吗？",a="这次前往铁炉堡的特定旅程严格来说只针对联盟术士。斯坦哈德会给部落术士一个同等的任务，转而让他们在部落领地内寻找知情者。",al={"部落版本","这是否仅限联盟"}},{q="这个任务线解锁了什么恶魔？",a="完成整个《秘教秘典》任务链的最终仪式是与一只召唤出的地狱猎犬进行战斗，从而教会术士如何召唤并将其束缚为永久的随从。",al={"哪种恶魔","地狱猎犬任务","能获得什么宠物"}}},fx={["8ce24f0c"]={q="为什么斯坦哈德·法尔杉要我去寻找《秘法会宝典》？",a="斯坦哈德·法尔杉正在引导你成长为一名术士，为你驾驭虚空中最凶猛的掠食者之一——地狱猎犬做准备。召唤这种野兽需要精密而危险的仪式，远超普通魔法阵的范畴。遗失的《秘法会宝典》记载着最初那批成功独力束缚地狱猎犬的术士所创立的仪式。斯坦哈德和他的侍僧已准备好在棘齿城上方布置召唤法阵，但若没有宝典中保存的专门知识，仪式便无法安全开始。",al={"斯坦哈德为什么要宝典","斯坦哈德·法尔杉的动机","斯坦哈德要秘法会宝典的原因"}},["327d5815"]={q="为什么斯坦哈德派我去，而不是亲自找回宝典？",a="降服恶魔仆从是一场极为个人的试炼，考验你的应变能力与决心。斯坦哈德会提供专业知识、仪式圣所和侍僧来稳固魔法，但取得必要知识的重任完全落在你肩上。此外，斯坦哈德仍驻守在棘齿城上方，掌控危险的奥术力量；而你可以自由前往铁炉堡的探险者大厅，向克罗姆·粗臂这样的学者请教，并亲自找回散落的遗物。",al={"斯坦哈德为什么派我去","斯坦哈德为什么不能取回宝典","为什么派玩家去铁炉堡"}}},fp="17,266,27.470.0,17.439.0,25.399.0,44.244.0,21.197.0,37.269.0,44.198.1,33.203.0,38.180.0"}
P.entries["quest:176"] = {n="通缉：霍格",s="“通缉：霍格”是贴在闪金镇外的一份联盟悬赏令，目标是一个巨大而凶残的豺狼人首领。霍格在艾尔文森林的西南树林中潜行，并暴力挫败了当地治安部门所有将其缉拿归案的尝试。",h="“通缉：霍格”是贴在闪金镇外的一份联盟悬赏令，目标是一个巨大而凶残的豺狼人首领。霍格在艾尔文森林的西南树林中潜行，并暴力挫败了当地治安部门所有将其缉拿归案的尝试。",kw={"悬赏","杜汉","艾尔文","林边空地","豺狼人","闪金镇","霍格","通缉"},ang={["faction:Alliance"]="讨伐霍格被视为年轻的联盟英雄在保卫暴风城核心地带时检验自身实力的成人礼。",["race:Human"]="对于艾尔文森林的人类居民来说，击杀霍格能保障那些数月来一直受豺狼人伏击困扰的家园和贸易道路的安全。"},sec={{t="林中的威胁",b="尽管艾尔文森林一直饱受强盗和狗头人侵扰的困扰，但南部的豺狼人部落在霍格这个粗暴首领的带领下，变得更加大胆且更有组织。霍格的身躯比普通的河爪豺狼人还要高大，他在林边空地附近建立了营地，伏击过往旅人，并压制了当地派来试图制服他的民兵巡逻队。"},{t="闪金镇的绝望",b="由于暴风城军队兵力吃紧，无法抽出正规部队来维护首都周边的治安，治安官杜汉采取了非同寻常的措施，公开悬赏通缉这头野兽。讨伐霍格需要深入充满敌意的豺狼人领地，而他的凶残也让他成了艾尔文森林中新手冒险者所面临的最致命威胁。"}},faq={{q="霍格是谁？",a="霍格是一个异常高大且凶残的豺狼人首领，他让艾尔文森林西南部的居民陷入恐惧。他指挥着林边空地周围的豺狼人族群，并暴力击退了暴风城卫兵之前所有试图抓捕或击杀他的尝试。",al={"霍格是谁","霍格背景故事","霍格是什么"}},{q="在什么地方能找到霍格？",a="霍格在艾尔文森林西南部的豺狼人营地中徘徊，靠近被称为林边空地的南部边界，位于西部荒野和暮色森林的河流交界处以北。",al={"霍格位置","霍格在哪里","寻找霍格"}},{q="为什么要悬赏通缉霍格？",a="暴风城军队悬赏通缉霍格是因为他压制了当地的巡逻队，并对过往旅人构成了致命威胁。由于正规部队在王国各地兵力不足，治安官杜汉转而求助于独立的冒险者和赏金猎人来消除这一威胁。",al={"为什么击杀霍格","通缉令霍格","谁悬赏霍格"}},{q="谁来收集证明霍格死亡的凭证？",a="这头野兽死亡的证明——他那只巨大的豺狼人爪——必须直接交给指挥闪金镇当地驻军的治安官杜汉。",al={"提交霍格任务","哪里提交霍格任务","谁需要霍格之爪"}},{q="为什么霍格比其他豺狼人更危险？",a="与潜伏在艾尔文森林的普通豺狼人不同，霍格拥有巨大的体型和野蛮的力量。他的攻击力更强，也更能承受打击，往往能轻易击败那些低估他的独行战斗者。",al={"霍格强吗","为什么霍格是精英"}},{q="为什么暴风城卫兵不能亲自处理霍格？",a="王国的军事资源严重匮乏，大都牵制在防御主要边界或处理失踪的瓦里安·乌瑞恩国王的相关事务上。治安官杜汉在闪金镇的小分队人手不足，无法安全地追捕如此顽强的怪物。",al={"为什么杜汉不亲自杀霍格","暴风城军队在哪里"}}},fx={fccb34f1={q="巨大的豺狼人爪有什么用？",a="巨大的豺狼人爪是霍格已死的确凿证据。这个蛮兽击退了所有抓捕行动，因此治安官杜汉和暴风城军队要求看到无可辩驳的实物证据，才会发放公告中的悬赏。",al={"巨大的豺狼人爪","为什么需要霍格的爪子","霍格的爪子有什么用"}}},fp="16,253,21.347.0,23.369.0,14.234.0,26.184.0,32.274.0,41.151.0,52.226.0,56.251.0"}
P.entries["quest:177"] = {n="仰望星空",s="此任务要求冒险者为天文学家维克托·安特拉斯寻回被盲眼玛丽遗弃的眼镜。这面脆弱的镜子落入了一个疯狂食尸鬼的手中，它在暮色森林南部的静谧花园墓场中游荡。",h="此任务要求冒险者为天文学家维克托·安特拉斯寻回被盲眼玛丽遗弃的眼镜。这面脆弱的镜子落入了一个疯狂食尸鬼的手中，它在暮色森林南部的静谧花园墓场中游荡。",kw={"盲眼玛丽","cog","夜色镇","疯狂食尸鬼","注视星辰","玛丽的眼镜","望远镜","静谧花园墓场","维克托·安特拉斯"},ang={["class:Priest"]="在静谧花园墓场受污染的土地上行走的牧师们，见证了暮色森林死者遭受的可怕屈辱，沦落的村民们被沦为了疯狂的拾荒者。",["faction:Alliance"]="从饥肠辘辘的亡灵手中寻回失落的城镇遗物，凸显了暮色森林人民被遗弃在暴风城王国危险边缘的苦涩命运。",["profession:Engineering"]="工程师们会欣赏维克托即兴发挥的光学机械，将普通的手持抛光镜变成了天文仪器的反射组件。"},sec={{t="往日遗物",b="在潜伏的阴霾笼罩暮色森林并使她变成一个哭泣的幽灵之前，盲眼玛丽一直珍视着一面精致的眼镜。在夺走她视力和理智的可怕事件发生后，她将这件纪念品扔进了自家谷仓后的泥土里。这面反光镜正是维克托·安特拉斯在夜色镇建造他的大型望远镜所需要的部件，但在天文学家梦想着研究星空很久之前，它就已经被带入了阴影之中。"},{t="墓地拾荒者",b="这面镜子被一个在废弃农庄后徘徊的疯狂食尸鬼捡走了。由于无尽的饥饿驱使它向南移动，这个可怜的亡灵生物带着眼镜进入了静谧花园墓场，盘踞在杂草丛生的墓碑之间一座废弃的小教堂里。要找回这面精致的镜片，就意味着必须穿过潜伏在南部森林中的食人怪物，从腐烂的爪子中夺回玛丽失落的宝藏。"}},faq={{q="维克托为什么要玛丽的眼镜？",a="维克托·安特拉斯正在夜色镇山上的一间小屋里组装一台强大的望远镜。他需要高质量的反射透镜和镜子来汇聚微弱的星光，而玛丽传家宝的材质正好满足了他发明所需的精密光学要求。",al={"维克托 镜子","为何需要眼镜","镜子的用途"}},{q="偷走镜子的疯狂食尸鬼是谁？",a="疯狂食尸鬼是一个拾荒的亡灵恶魔，它从玛丽家附近的废弃农庄收集小玩意儿。它一路向南逃窜，并在静谧花园墓场内的一座破败教堂中安了家。",al={"疯狂食尸鬼位置","谁拿了眼镜","教堂食尸鬼"}},{q="盲眼玛丽为什么要扔掉她的眼镜？",a="在夺去她视力、撕裂她理智并使她成为一个不安的幽灵的“那场事故”之前，玛丽一直珍视着她的眼镜。那场灾难过后，她再也无法面对或触碰它，便绝望地将它扔在了谷仓后面。",al={"玛丽为何丢弃","盲眼玛丽 镜子","玛丽眼镜事故"}},{q="静谧花园墓场在哪里？",a="静谧花园墓场位于暮色森林的东南部，大路以南。这里曾经是暮色森林人民安详的安息地，如今却充满了狂暴的食尸鬼、骷髅和食腐兽。",al={"静谧花园位置","墓地在哪"}},{q="Cog是谁？",a="Cog是住在夜色镇的一名侏儒技师。维克托依靠Cog的工程学专业知识来评估并协助建造他观星机器的精密机械结构。",al={"cog是谁","维克托 cog"}},{q="将镜子归还给维克托后会发生什么？",a="拿到反光设备后，维克托对装置的进展感到非常激动。随后，他将进入组装望远镜的最后阶段，并索要最后一个关键部件来完成透镜系统。",al={"注视星辰后续任务","what comes next"}}},fx={["9a9407cc"]={q="为什么盲眼玛丽帮你寻找镜子？",a="玛丽并不想留着自己的镜子。它曾是她最珍爱的宝物之一，但在一场悲剧使她失明并毁了她之后，镜子便令她难以忍受。她绝望之中早已把它丢在谷仓后面，因此没有理由隐瞒它的下落，还主动指引你去找那个捡走它的人。",al={"盲眼玛丽为什么帮忙","盲眼玛丽寻找镜子的动机","玛丽为什么告诉你镜子在哪里"}},f9c44b13={q="为什么盲眼玛丽需要你取回镜子，而不是自己去？",a="盲眼玛丽是个无助的失明幽灵，孤独地徘徊在夜色镇外。即使生前，她也不可能对付凶猛的食尸鬼；死后，她更被束缚在闹鬼的小屋里。只有全副武装的冒险者能够冒险进入静谧花园墓场，把镜子取回来。",al={"玛丽为什么不能取回镜子","玛丽为什么需要我","玛丽为什么不取回镜子"}}},fp="17,249,22.463.0,23.420.0,43.261.0,46.206.0,48.237.0,39.231.0,11.184.0,51.228.1"}
P.entries["quest:1778"] = {n="圣洁之书",s="《神圣之书》是有志于学习圣光基本美德的圣骑士新手所面对的一项基础试炼。在帮助了需要援助的人之后，初学者会回到铁炉堡，向导师蒂萨·热炉汇报他们的无私服务。",h="《神圣之书》是有志于学习圣光基本美德的圣骑士新手所面对的一项基础试炼。在帮助了需要援助的人之后，初学者会回到铁炉堡，向导师蒂萨·热炉汇报他们的无私服务。",kw={"仁慈","圣光","铁炉堡","圣骑士试炼","斯蒂芬妮","暴风城","蒂萨·热炉","神圣之书"},ang={["class:Paladin"]="《神圣之书》的试炼教导有志成为圣骑士的人，运用圣光要求在追求武力荣耀之前，先要对普通平民具备无私、仁慈和持久的责任感。",["faction:Alliance"]="铁炉堡与暴风城王国之间的联系依然紧密，这一点反映在圣骑士导师和旅行者往返于各大联盟城市之间的往来上。",["race:Dwarf"]="在丹莫罗进行试炼的矮人圣骑士会向铁炉堡大厅内的蒂萨·热炉汇报，以交代他们在广阔世界中的所作所为。"},sec={{t="圣光的教诲",b="《神圣之书》构成了新手晋升为圣骑士的基础。这些教导并不要求展现战斗实力，而是强调谦逊、公民责任以及对苦难者的仁慈。圣光的真正仆人必须首先理解凡人的苦难，并准备好在不求回报、不求名利的情况下提供帮助。"},{t="铁炉堡的汇报",b="在铁炉堡完成一项援助任务后，有志成为圣骑士的初学者会回到蒂萨·热炉身边。初学者站在导师面前，讲述他们在外出期间的所作所为，以及他们帮助分担了谁的重担。在确信初学者确实秉持了真诚的仁慈与责任后，蒂萨会给予嘉奖，并肯定这种无私的牺牲正是追随圣光的真谛。"}},faq={{q="什么是《神圣之书》？",a="《神圣之书》代表了圣骑士新手所经历的核心神圣试炼。通过各项任务，初学者接受的考验并非仅仅是战场上的力量，而是诸如怜悯、仁慈和自我牺牲等美德。",al={"什么是神圣之书","神圣之书试炼","这个任务有什么用"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位驻扎在铁炉堡的矮人圣骑士导师。她负责监督初学者的精神和道德成长，评估他们的行为是否体现了圣光的真正教诲。",al={"蒂萨·热炉是谁","蒂萨·热炉在哪里","铁炉堡圣骑士训练师"}},{q="斯蒂芬妮是谁？",a="斯蒂芬妮·特纳是约翰·特纳在暴风城的妻子，他们在那里共同经营一家孤儿院。约翰希望能在他从铁炉堡收集完物资后回到她身边。",al={"斯蒂芬妮是谁","暴风城的斯蒂芬妮"}},{q="蒂萨·热炉会对回来的初学者提出什么要求？",a="蒂萨会考验圣骑士是否领悟了仁慈和服务他人的真正分量。在给予祝福之前，她会倾听初学者如何帮助了一项崇高的事业并援助了普通平民。",al={"蒂萨考验什么课程","蒂萨想要什么","圣骑士慈善考验"}},{q="为什么初学者必须向铁炉堡汇报？",a="初学者被要求回到铁炉堡向蒂萨·热炉汇报他们的事迹，以证明他们通过帮助城中的约翰·特纳，展现了对他人的同情与无私。",al={"为什么要在铁炉堡与蒂萨交谈","铁炉堡神圣之书"}},{q="为什么自我牺牲是这项试炼的核心？",a="根据圣骑士的教义，将他人的福祉置于自身之上是践行圣光之道的根本。蒂萨提醒学生们，这种无私的牺牲终将获得回报。",al={"圣光如何奖励牺牲","圣骑士的牺牲"}}},fp="20,243,25.386.0,27.395.0,29.228.0,24.205.0,17.157.0,54.203.0,39.177.0,44.213.0"}
P.entries["quest:1779"] = {n="圣洁之书",s="《神圣之书》是铁炉堡的圣骑士见习生所必须经历的一项神圣试炼，旨在证明他们对圣光之力和战斗奉献的掌握。在被授予生命符记后，一位满怀抱负的圣骑士将前往救助在与黑铁矮人的一次致命遭遇后身负重伤的战士穆瑞登·战炉。",h="《神圣之书》是铁炉堡的圣骑士见习生所必须经历的一项神圣试炼，旨在证明他们对圣光之力和战斗奉献的掌握。在被授予生命符记后，一位满怀抱负的圣骑士将前往救助在与黑铁矮人的一次致命遭遇后身负重伤的战士穆瑞登·战炉。",kw={"黑铁","圣光","铁炉堡","穆瑞登·战炉","纳姆","圣骑士","生命符记","神圣之书"},ang={["class:Paladin"]="这项试炼考验着年轻圣骑士的奉献精神，要求他们携带生命符记去安慰伤者，并为复活这一神圣职责做好准备。",["race:Dwarf"]="这场试炼以铁炉堡为中心，反映了矮人保卫者之间深厚的情谊，他们勇敢地面对黑铁氏族的伏击。"},sec={{t="信仰与力量的试炼",b="在铁炉堡这座山中王国，修行《神圣之书》是圣骑士训练中一个至关重要的里程碑。那些已经展现出谦逊、耐心和仁慈的见习生，会被要求证明他们对战斗技巧和圣光之力的掌握。见习生将带着被称为生命符记的神圣遗物，被派往城内的大厅，去救助那些正饱受城门外激烈冲突之苦的人们。"},{t="倒下的兄弟",b="接下来的直接任务是引导见习生前往穆瑞登·战炉处。他是一位在与敌对的黑铁矮人交战后身受重伤的矮人战士。当一位牧师正在照料穆瑞登的伤口时，这位饱受创伤的战士正准备讲述他的探险队和他同伴纳姆的遭遇，并向这位满怀抱负的圣骑士发出挑战，希望他能挺身而出，运用圣光重生的恩赐。"}},faq={{q="什么是《神圣之书》？",a="《神圣之书》是学习圣光之道的年轻圣骑士的成年礼。在试炼的这一阶段，一位已经证明自己仁慈和耐心的见习生将被授予一件名为生命符记的圣物，并被指派前往铁炉堡救助一名受伤的矮人。",al={"这个任务是什么","神圣之书的用途","这个任务的作用是什么"}},{q="什么是生命符记？",a="生命符记是圣骑士在试炼期间被授予的一枚神圣徽记。它体现了圣光治疗和恢复的力量，旨在帮助并复活那些为了保卫人民而倒下的人。",al={"什么是生命符记","生命符记物品"}},{q="谁是穆瑞登·战炉？",a="穆瑞登·战炉是一位刚刚在与黑铁矮人的残酷冲突中幸存下来的矮人战士。尽管他伤痕累累且因伤势而不断咳嗽，但他正在铁炉堡接受当地牧师的照料，他的妻子则派遣有前途的圣骑士去听取他的故事。",al={"谁是穆瑞登·战炉","受伤的矮人是谁"}},{q="谁给了你生命符记？",a="这个任务是由穆瑞登·战炉的妻子，一位铁炉堡的圣骑士导师给予的。在观察到你展现出仁慈和耐心后，她将生命符记交给你，以此来考验你的力量、战斗准备程度以及你协助她受伤丈夫的意愿。",al={"谁派你去找穆瑞登","谁给予了这个任务"}},{q="穆瑞登·战炉发生了什么事？",a="穆瑞登和他的同伴纳姆遭到了敌对的黑铁矮人的伏击。穆瑞登死里逃生，好不容易回到铁炉堡，但他身受重伤，需要精神上和身体上的修复。",al={"谁袭击了穆瑞登","穆瑞登发生了什么"}},{q="谁是纳姆？",a="纳姆是穆瑞登·战炉最好的朋友，也是一位陪同他上战场的圣骑士同伴。虽然穆瑞登在与黑铁矮人的冲突中成功逃脱，但纳姆却没那么幸运，这也让圣骑士有必要代表他介入此事。",al={"谁是纳姆","纳姆发生了什么"}}},fp="20,302,26.454.0,16.400.0,29.289.0,27.221.0,28.267.0,33.257.0,38.220.0,12.258.0"}
P.entries["quest:178"] = {n="塞欧克瑞图斯的坠饰",s="“塞欧克瑞图斯的搜寻”始于一位在赤脊山的冒险者发现当地豺狼人携带的一件魔法饰品，随后便听到了饰品中传出的遥远回响。说话者是阿祖拉之塔的高阶法师塞欧克瑞图斯，他成功截获了豺狼人的神秘网络，并急切地请求将该坠饰带给他进行研究。",h="“塞欧克瑞图斯的搜寻”始于一位在赤脊山的冒险者发现当地豺狼人携带的一件魔法饰品，随后便听到了饰品中传出的遥远回响。说话者是阿祖拉之塔的高阶法师塞欧克瑞图斯，他成功截获了豺狼人的神秘网络，并急切地请求将该坠饰带给他进行研究...",kw={"艾尔文","豺狼人","摩根斯","坠饰","赤脊山","暗皮","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="塞欧克瑞图斯的工作展示了防护系和预言系魔法的巧妙应用，即侵入另一位施法者的网络，以便在远距离投放反制法术。",["faction:Alliance"]="艾尔文森林的阿祖拉之塔与湖畔镇陷入困境的守军之间的协作，显示了在暴风城皇家军队兵力不足的情况下，当地法师是如何挺身而出的。"},sec={{t="石中之声",b="当在赤脊山各地与凶残的暗皮豺狼人作战时，旅行者有时会偶然发现一种被称为暗皮坠饰的附魔饰品。触摸该物体不会听到低沉的吠叫或咒骂，而是会触发一个平静、超然的声音，它属于住在艾尔文森林边界另一侧阿祖拉之塔的人类法师塞欧克瑞图斯。这段讯息是他长期以来艰苦研究的成果，旨在破译指挥豺狼人部族的黑暗魔法。"},{t="颠覆摩根斯的网络",b="暗皮豺狼人并非纯粹出于本能行事；它们听命于摩根斯，一个潜伏在山中的堕落黑暗施法者。摩根斯制作并分发这些附魔坠饰，直接向他的野兽爪牙下达指令。塞欧克瑞图斯花费了数月时间来破译摩根斯传讯法术的频率。当冒险者将褪色的坠饰送回阿祖拉之塔时，这位法师确认他的探知术已经触及了该护身符，为反向工程攻击并彻底瘫痪豺狼人打开了大门。"}},faq={{q="塞欧克瑞图斯是谁？",a="塞欧克瑞图斯是联盟的一位高阶法师，驻扎在艾尔文森林东部的阿祖拉之塔。他时刻关注着该地区的动荡，并将大部分魔法研究投入到遏制从赤脊山蔓延而来的黑暗魔法上。",al={"塞欧克瑞图斯背景故事","谁通过坠饰说话","阿祖拉之塔法师"}},{q="为什么暗皮豺狼人会携带魔法坠饰？",a="这些坠饰是叛逃法师摩根斯制作的魔法传导器。通过它们，他可以从远方发送精神指令并指挥暗皮氏族的行动。",al={"为什么豺狼人有坠饰","暗皮坠饰用途","豺狼人魔法物品"}},{q="为什么塞欧克瑞图斯发出的声音会有延迟？",a="塞欧克瑞图斯在冒险者找回这块石头之前的几周就施放了讯息，起初他以为自己的法术已经消散并失败了。穿透摩根斯的黑暗结界并在如此遥远的距离建立连接导致了巨大的魔法延迟。",al={"延迟的信息","为什么塞欧克瑞图斯花了数周时间","褪色坠饰的延迟"}},{q="塞欧克瑞图斯希望通过找回的坠饰达成什么目的？",a="通过破译将坠饰与摩根斯连接的特定魔法频率，塞欧克瑞图斯希望能反转魔法流。他的最终目标是通过该网络广播一种攻击性法术，瞬间瘫痪所有佩戴坠饰的豺狼人。",al={"塞欧克瑞图斯的计划","塞欧克瑞图斯要做什么","为什么要研究坠饰"}},{q="这个任务线接下来会走向何方？",a="交付坠饰即可完成此项跑腿任务。塞欧克瑞图斯与摩根斯的持续对抗将在“警惕之眼”中继续，该任务会将冒险者派往伊尔加拉之塔监视摩根斯的大本营。",al={"塞欧克瑞图斯的搜寻之后的任务","摩根斯任务链","接下来发生什么"}}},fx={["24fcac1f"]={q="为什么塞欧克瑞图斯需要冒险者送来吊坠？",a="塞欧克瑞图斯曾盲目地通过摩根斯用来与豺狼人交流的魔法频率发送讯息，完全不知道吊坠会在何时何地收到它。他被束缚在艾尔文森林的阿祖拉之塔圣所，无法亲自搜寻赤脊山的险恶荒野。他只能依靠发现这件遗物的能干旅人，将它安全带回文明之地。",al={"为什么派冒险者去","塞欧克瑞图斯为什么需要我","塞欧克瑞图斯为什么不能取回吊坠"}}},fp="21,342,20.490.0,29.538.1,18.244.0,57.178.0,50.252.0,64.257.0,38.216.1"}
P.entries["quest:1780"] = {n="圣洁之书",s="《神圣之书》是圣骑士为了证明他们对圣光的虔诚而进行的神圣试炼。在暴风城的Cathedral of Light中，在达索瑞恩·拉尔的指引下，初学者们必须展现出无私、仁爱，以及保护弱者的坚定承诺。",h="《神圣之书》是圣骑士为了证明他们对圣光的虔诚而进行的神圣试炼。在暴风城的Cathedral of Light中，在达索瑞恩·拉尔的指引下，初学者们必须展现出无私、仁爱，以及保护弱者的坚定承诺。",kw={"cathedral of light","慈善","达索瑞恩·拉尔","圣光","圣骑士试炼","暴风城","神圣之书"},ang={["class:Paladin"]="《神圣之书》考验着有抱负的圣骑士对无私服务的承诺，教导他们对圣光的虔诚需要通过为普通公民提供有形的慈善和保护来体现。",["faction:Alliance"]="这些试炼加强了暴风城的精神基础，提醒联盟的保卫者，真正的力量在于守护他们人民中的弱势群体。"},sec={{t="美德试炼",b="《神圣之书》代表了圣骑士侍奉圣光的一个决定性成年礼。达索瑞恩·拉尔驻守在暴风城的Cathedral of Light，负责监督这些试炼。他派遣初学者们去证明他们的奉献精神，不是通过武力荣耀，而是通过道德正直以及为王国公民所做的无私善举。"},{t="无私的美德",b="在救助弱势群体——为孩子们提供所需的救济并赢得他们真诚的感激——归来后，初学者们向达索瑞恩·拉尔汇报他们的行动。这位导师对那些将他人置于自身之上的行为印象深刻，并提醒他们，慈善、同情心以及对艾泽拉斯人民的责任，才是行走在圣光之路者真正的衡量标准。"}},faq={{q="《神圣之书》是什么？",a="《神圣之书》代表了有抱负的圣骑士所进行的一系列基础试炼。这项任务通过暴风城Cathedral of Light的导师们来执行，要求初学者们通过直接帮助王国中需要帮助的公民，来展现道德美德、慈善和责任感。",al={"什么是神圣之书","神圣之书任务","圣骑士试炼任务"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是驻守在暴风城Cathedral of Light的一名资深圣骑士训练师。他引导初出茅庐的圣骑士完成他们的精神教育和道德试炼，评估他们的行为是否真正体现了对圣光美德的遵循。",al={"达索瑞恩·拉尔是谁","暴风城圣骑士训练师","达索瑞恩·拉尔的作用"}},{q="这次试炼背后的课程是什么？",a="这次试炼灌输了圣骑士的基本精神，即运用圣光需要谦逊、无私牺牲和为他人服务。它强调的是对艾泽拉斯人民的同情、慈善和道德义务，而不是仅仅关注武力技巧。",al={"神圣之书的目的","为什么圣骑士要这样做","这个任务教导了什么"}},{q="这个任务在哪里进行？",a="该任务围绕着Cathedral of Light展开，这是位于暴风城Cathedral Square的宏伟精神圣地。初学者们出发去帮助平民，然后回到教堂向达索瑞恩·拉尔汇报他们的善举。",al={"这个任务在哪里进行","在哪里交还神圣之书","cathedral of light任务"}},{q="这个任务帮助了谁？",a="在试炼的这一阶段，援助被带给了那些急需帮助的人，包括年幼的孩子。受助者表达了深深的感激之情，并指出暴风城的圣骑士绝不能背弃无辜和贫困的人。",al={"这个任务帮助了谁","儿童慈善任务","谁接受了援助"}},{q="为什么达索瑞恩·拉尔强调慈善？",a="慈善和保卫无辜者是圣光的核心支柱。达索瑞恩·拉尔强调，个人牺牲和将他人的福祉置于自身之上，是圣骑士神圣使命的基石。",al={"慈善对圣骑士为何重要","圣骑士与贫困者","慈善与圣光"}}},fp="20,277,17.348.0,26.372.0,29.299.0,22.266.0,37.269.0,33.248.0,23.229.0,42.221.0"}
P.entries["quest:1781"] = {n="圣洁之书",s="“神圣之书”代表了暴风城圣光大教堂内圣骑士新兵的一项重要试炼，要求他们学会专注使用神圣的生命符记。在证明了自己的品德之后，有志之士会被指引去协助贾森·坦诺姆，他在艾尔文森林的英雄哨岗附近侥幸从一次致命的迪菲亚潜行者伏击中逃脱。",h="“神圣之书”代表了暴风城圣光大教堂内圣骑士新兵的一项重要试炼，要求他们学会专注使用神圣的生命符记。在证明了自己的品德之后，有志之士会被指引去协助贾森·坦诺姆，他在艾尔文森林的英雄哨岗附近侥幸从一次致命的迪菲亚潜行者伏击中...",kw={"cathedral of light","迪菲亚潜行者","达索瑞恩","达索瑞恩·拉尔","贾森·坦诺姆","亨泽","英雄哨岗","生命符记","神圣之书"},ang={["class:Paladin"]="这项任务是圣骑士在暴风城训练中的一个重要里程碑，用于测试新兵是否拥有驾驭生命符记的精神力量。",["faction:Alliance"]="英雄哨岗附近的迪菲亚活动对艾尔文森林内的旅行者和市民构成了持续威胁，需要教会的干预。"},sec={{t="奉献的考验",b="在圣光大教堂，展现出耐心与仁慈的圣骑士新兵会获得生命符记。这件圣物由达索瑞恩·拉尔托付，旨在测试一位有抱负的勇士是否具备足够的精神专注，来引导圣光最伟大的恩赐之一：复活堕落者的力量。"},{t="英雄哨岗的伏击",b="贾森·坦诺姆清楚地表明了对生命符记的迫切需求。他最近在艾尔文森林的英雄哨岗附近遭到迪菲亚暴徒的残忍袭击，之后挣扎着回到了暴风城。当大教堂祭坛的牧师们正在照料贾森的重伤时，他的同伴亨泽依然身处那些歹徒袭击时的险境之中。"}},faq={{q="谁是贾森·坦诺姆？",a="贾森·坦诺姆是达索瑞恩·拉尔的同伴，他在艾尔文森林的英雄哨岗附近侥幸从迪菲亚暴徒的伏击中逃脱。他在遭遇战中身受重伤，被送进了暴风城的圣光大教堂，接受当地牧师的救治。",al={"贾森·坦诺姆是谁","贾森 艾尔文 迪菲亚","受伤男子 暴风城 祭坛"}},{q="什么是生命符记？",a="生命符记是一件托付给被认为仁慈且有耐心的圣骑士新兵的圣物。它的作用是测试一位初露锋芒的勇士，是否具备引导圣光最伟大的恩赐——复活生命——所需的精神专注力和坚毅品质。",al={"生命符记的作用","生命符记 圣骑士","圣骑士复活神器"}},{q="英雄哨岗发生了什么？",a="英雄哨岗是艾尔文森林内的一个区域，贾森·坦诺姆和他的同伴亨泽在那里遭到了迪菲亚暴徒的伏击。虽然贾森带着重伤逃回了暴风城，但他朋友亨泽的命运亟待援助。",al={"英雄哨岗在哪里","英雄哨岗 艾尔文 迪菲亚","贾森伏击地点"}},{q="谁是亨泽？",a="亨泽是贾森·坦诺姆的同伴，当迪菲亚暴徒在艾尔文森林的英雄哨岗附近袭击他们时，他也在场。虽然贾森活着回到了暴风城，但亨泽却被留在了那里。",al={"亨泽是谁","亨兹·法奥克","贾森的朋友 迪菲亚"}},{q="是谁派你去和贾森·坦诺姆交谈的？",a="任务发布者是达索瑞恩·拉尔，他是暴风城圣光大教堂圣骑士们的领袖之一。在确认了一位新兵证明了自己的耐心和仁慈之后，他会指引他们去祭坛与贾森·坦诺姆交谈。",al={"谁派你去见贾森","达索瑞恩·拉尔 神圣之书","暴风城圣骑士训练师任务"}},{q="为什么迪菲亚暴徒要在英雄哨岗附近袭击旅行者？",a="迪菲亚潜行者在艾尔文森林各处部署了暴徒和强盗，甚至在距离首都咫尺之遥的地方伏击旅行者。贾森·坦诺姆那次惊心动魄的遭遇，充分展示了迪菲亚的行动已经变得多么猖獗和致命。",al={"迪菲亚威胁 艾尔文","为什么迪菲亚在英雄哨岗附近","迪菲亚潜行者 暴风城"}}},fp="20,318,18.338.0,23.310.0,20.257.0,27.264.0,31.227.0,13.201.0,41.227.0,62.245.0"}
P.entries["quest:1782"] = {n="弗伦的铠甲",s="“弗伦的护甲”标志着一名立志成为勇士的冒险者协助暴风城的锻造大师弗伦·长须的任务达到了顶点。通过收集蜘蛛毒牙、奇美拉之角和一瓶燃素，这位冒险者帮助长须锻造出了一件坚固的淬火锁甲。为了回报他们的帮助，长须将成品锁甲赠予了勇士，并承诺将他新掌握的冶金技术在联盟内部传授开来。",h="“弗伦的护甲”标志着一名立志成为勇士的冒险者协助暴风城的锻造大师弗伦·长须的任务达到了顶点。通过收集蜘蛛毒牙、奇美拉之角和一瓶燃素，这位冒险者帮助长须锻造出了一件坚固的淬火锁甲。为了回报他们的帮助，长须将成品锁甲赠予了勇...",kw={"联盟战士","锻造","淬火锁甲","弗伦·长须","弗伦的护甲","锁甲","暴风城"},ang={["class:Warrior"]="对于那些即将成年的联盟战士来说，获得弗伦定制的淬火护甲代表着一种成长的仪式，并为早期的前线战役提供了不可或缺的保护。",["faction:Alliance"]="强大的武装对于确保联盟的常备军在面对迪菲亚兄弟会、豺狼人和敌对元素生物的持续威胁时生存下来至关重要。",["profession:Blacksmithing"]="弗伦的成功实验凸显了联盟铁匠的协作传统，他们分享专业的冶金发现，从而提升了暴风城和铁炉堡的工艺标准。"},sec={{t="大师的突破",b="弗伦·长须是一位驻扎在暴风城的受人尊敬的矮人盔甲匠，他致力于突破联盟防御性冶金工艺的极限。通过委托一位坚定的冒险者去寻回稀有的毒牙、尖角和燃素，长须得以测试在淬火过程中抵抗灼热和重击的先进技术。最终的成品证明这是一次巨大的成功，巩固了长须作为联盟最顶尖盔甲匠之一的地位。"},{t="分享工艺",b="当把刚完成的淬火锁甲交给收集材料的冒险者时，弗伦表达了对这次合作的深切感谢。这些实验不仅仅打造出了一件耐用的盔甲，更扩展了他对防护性锻造的理解。秉承着铁炉堡和暴风城工匠的协作精神，长须决定将他的笔记和发现分发给其他的联盟铁匠，确保他的突破能够加强全联盟前线战士的装备。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是一位在暴风城内工作的矮人盔甲大师。他与联盟的军事组织有着广泛的合作，特别是与那些寻求专业高等级护甲的战士。",al={"弗伦是谁","弗伦·长须","暴风城铁匠弗伦"}},{q="弗伦制作的是什么样的护甲？",a="通过对稀有毒牙、尖角和燃素的大量实验，弗伦锻造出了一件淬火锁甲，这是一种锁甲胸甲。他将其设计为能够在战场上抵御猛烈的攻击和极端的高温。",al={"弗伦制作什么护甲","淬火锁甲","弗伦的奖励"}},{q="弗伦·长须将他的锻造发现发送到哪里？",a="弗伦承诺将他的技术发现和笔记发送给全联盟的铁匠同僚，将新测试的淬火方法所带来的益处推广到整个王国的军械库和铁匠铺。",al={"弗伦的笔记","谁能得到弗伦的设计","联盟铁匠"}},{q="为什么要让战士为弗伦收集试剂？",a="弗伦需要稀有且不稳定的成分来测试未经检验的锻造技术。由于无法离开他的铁匠铺去猎杀湿地的蜘蛛和石爪山的奇美拉，他只能依赖一位雄心勃勃的战士来获取这些材料。",al={"为什么要为弗伦收集试剂","淬火锁甲任务材料"}},{q="这件护甲是在哪里锻造并交付的？",a="交易直接在弗伦·长须位于暴风城的铁匠铺内进行，他会在那里完成这件锁甲的最后敲打和冷却工序。",al={"弗伦·长须在哪里","交付地点","弗伦位置"}},{q="这项工作是否让其他联盟战士受益？",a="是的。弗伦指出，从这些材料的处理中所学到的经验将与其他联盟盔甲匠分享，他希望这将鼓励其他铁匠为联盟士兵制造并提供精良的装备。",al={"联盟收益","弗伦的突破"}}},fp="13,288,23.282.0,17.283.0,23.161.0,36.162.0,57.159.0,55.207.0,41.96.0,47.152.0"}
P.entries["quest:1783"] = {n="圣洁之书",s="《神圣之书》指引一名圣骑士新兵前往丹莫罗盔枕湖以南的冰冷湖岸。圣骑士携带着生命符记，必须找到并复活纳姆·福克，这名勇敢的侦察兵在抵御一伙黑铁矮人时不幸阵亡。",h="《神圣之书》指引一名圣骑士新兵前往丹莫罗盔枕湖以南的冰冷湖岸。圣骑士携带着生命符记，必须找到并复活纳姆·福克，这名勇敢的侦察兵在抵御一伙黑铁矮人时不幸阵亡。",kw={"黑铁矮人","丹莫罗","盔枕湖","穆里登","纳姆·福克","圣骑士","复活","生命符记","神圣之书"},ang={["class:Paladin"]="这项试炼标志着圣骑士对死亡本身的掌控，展示了通过生命符记引导圣光来复活阵亡盟友的能力。",["faction:Alliance"]="营救矮人侦察兵并找回神圣文书，使联盟的关键知识和防卫者免受黑铁矮人阴谋的伤害。",["race:Dwarf"]="这项试炼直接应对了盘踞在丹莫罗盔枕湖以南的黑铁矮人所带来的威胁。"},sec={{t="湖畔伏击",b="在盔枕湖以南的一次例行侦察任务中，侦察兵穆里登和纳姆·福克发现敌对的黑铁矮人正在加固防御，局势顿时变得危急起来。在发现敌方指挥官下达命令后，侦察兵试图击杀几名敌人并获取一份文书，但黑铁矮人以出人意料的凶猛攻势压倒了他们。穆里登逃离去寻求增援，而纳姆则负责阻击敌人。"},{t="信仰的试炼",b="携带生命符记的圣骑士新兵前往丹莫罗的雪地寻找纳姆·福克。虽然纳姆在黑铁矮人的猛攻下倒下了，但通过引导这件圣物的力量，圣骑士成功地在圣光即将完全拥抱纳姆之时将其灵魂拉了回来。这一举动巩固了圣骑士初生的使命感，以及复活阵亡者的能力。"}},faq={{q="这个任务的目的是什么？",a="《神圣之书》代表了年轻圣骑士的一项决定性试炼。在这一阶段，新兵会收到生命符记，并被派去营救一名阵亡的侦察兵，通过祈求圣光复活死者来证明自己的价值与虔诚。",al={"什么是神圣之书","神圣之书的目的","圣骑士复活任务"}},{q="纳姆·福克是谁？",a="纳姆·福克是一名联盟侦察兵，他在盔枕湖以南遭到黑铁矮人的伏击。他为了让同伴穆里登逃脱而放弃了逃生的机会，在战斗中阵亡，随后被圣光所复活。",al={"纳姆·福克是谁","纳姆在哪里","阵亡矮人纳姆"}},{q="穆里登是谁？",a="穆里登是在纳姆·福克的催促下从黑铁矮人伏击中逃脱的侦察兵。他返回寻求增援，并指引圣骑士使用生命符记拯救他那阵亡的战友。",al={"穆里登是谁","任务给予者穆里登","谁给予任务"}},{q="什么是生命符记？",a="生命符记是一件神圣的圣物，由提扎和穆里登交给圣骑士。由圣光的合格侍从引导，它拥有复活死者的力量。",al={"什么是生命符记","复活物品","生命符记背景"}},{q="纳姆和穆里登在盔枕湖附近做什么？",a="穆里登和纳姆·福克当时正在监视那些在盔枕湖以南加固防御的黑铁矮人。在侦察任务中，他们目睹了敌军首领正在发号施令，并试图在被压倒前夺回神圣的文书。",al={"他们在盔枕湖以南做什么","为什么要监视黑铁矮人","黑铁矮人 盔枕湖"}},{q="提扎是谁？",a="提扎是参与调派救援并与穆里登一起为营救任务准备生命符记的导师或协调员之一。",al={"提扎是谁","提扎 圣骑士"}}},fp="20,257,18.417.0,15.377.1,34.259.0,18.222.0,16.185.0,27.204.0,55.255.0,12.147.0"}
P.entries["quest:1784"] = {n="圣洁之书",s="《圣光的感召》是一项关键的圣骑士试炼，核心任务是揭露潜入丹莫罗的黑铁矮人阴谋。胸怀大志的圣骑士们需要去帮助受伤的斥候纳姆·法克和缪雷登·战锤，夺回至关重要的敌军命令，从而向铁炉堡中怀疑此事的议会证明近在咫尺的威胁。",h="《圣光的感召》是一项关键的圣骑士试炼，核心任务是揭露潜入丹莫罗的黑铁矮人阴谋。胸怀大志的圣骑士们需要去帮助受伤的斥候纳姆·法克和缪雷登·战锤，夺回至关重要的敌军命令，从而向铁炉堡中怀疑此事的议会证明近在咫尺的威胁。",kw={"黑铁矮人","黑铁手稿","丹莫罗","盔枕湖","铁炉堡","缪雷登·战锤","纳姆·法克","圣光的感召"},ang={["class:Paladin"]="该任务是矮人圣骑士通过《圣光的感召》进行的早期试炼中的关键一步，旨在通过保卫王国和营救受难战友来传授对圣光的无私奉献精神。",["faction:Alliance"]="揭露铁炉堡周边的黑铁破坏活动，保卫了矮人首都，并加强了联盟北部防御以应对隐秘威胁。",["race:Dwarf"]="在铁炉堡家门口揭露黑铁渗透对于矮人防御至关重要，这向固执的议员们证明了世仇已经入侵了丹莫罗。"},sec={{t="侍奉之试炼",b="《圣光的感召》指引着年轻的矮人圣骑士走上他们的精神修行之路。在这场试炼中，当一场针对隐秘黑铁特工的远征在盔枕湖附近遇挫时，初出茅庐的勇士被卷入了丹莫罗的防御战。纳姆·法克和缪雷登·战锤试图伏击敌方斥候，但在冲突中纳姆身负重伤，而缪雷登则撤回铁炉堡进行休整。"},{t="给议会的证明",b="尽管传言甚嚣尘上，铁炉堡统治议会的几位成员仍拒绝承认黑铁渗透者已经潜入了丹莫罗。通过追踪盔枕湖附近的间谍并回收他们队长传递的“黑铁手稿”，圣骑士获得了敌军动向无可辩驳的证据，并揭开了他们就在首都大门外酝酿的阴谋。"},{t="保卫家园",b="将截获的命令带回铁炉堡交给缪雷登·战锤令人深感宽慰。随着纳姆获救，回收的文件也被交给缪雷登的妻子呈递给议会，圣骑士展现出了无私的勇敢与对圣光的虔诚，保护了矮人王国免受隐藏的背叛之苦。"}},faq={{q="谁发布《圣光的感召》任务？",a="该任务由纳姆·法克发布，他是一位在盔枕湖附近与黑铁间谍战斗时受伤的矮人。他派遣你去取回敌军手稿，并向他在铁炉堡的同伴缪雷登·战锤报告。",al={"谁发布此任务","圣光的感召任务发布者","纳姆是谁"}},{q="缪雷登·战锤是谁？",a="缪雷登·战锤是一位驻扎在铁炉堡的矮人。他曾与纳姆·法克一起在盔枕湖附近侦察黑铁间谍，随后回到城中休养伤势。",al={"缪雷登·战锤是谁","缪雷登在哪里","缪雷登·战锤位置"}},{q="什么是黑铁手稿？",a="黑铁手稿包含了黑铁间谍与其队长在盔枕湖附近传递的书面命令。它提供了敌方渗透的实质性证据，可以用来展示给持怀疑态度的铁炉堡议会。",al={"什么是黑铁手稿","为什么要获取黑铁手稿","黑铁手稿用途"}},{q="为什么铁炉堡的议会需要黑铁矮人的证据？",a="铁炉堡的一些议会成员仍然怀疑黑铁矮人是否成功渗透了丹莫罗。回收的手稿证明了他们的活跃动向，并揭露了他们的秘密计划。",al={"为什么议会否认黑铁矮人","铁炉堡议会黑铁证据"}},{q="黑铁间谍位于何处？",a="盔枕湖位于丹莫罗东部，卡拉诺斯以东。黑铁间谍在附近的一间小屋旁活动，试图传递隐秘的作战命令。",al={"盔枕湖在哪里","盔枕湖的黑铁矮人","丹莫罗的黑铁位置"}},{q="这个任务对圣骑士有什么作用？",a="《圣光的感召》系列考验着一位胸怀大志的圣骑士在侍奉、同情心和勇气方面的品质。通过帮助纳姆这样的落难战友并保卫丹莫罗免受阴险敌人的侵害，圣骑士证明了自己有资格驾驭圣光。",al={"圣光的感召教导什么","圣骑士圣光的感召背景"}}},fp="20,311,18.396.0,21.378.0,19.325.1,37.222.0,28.181.0,29.210.0,63.202.0,38.164.0,44.234.0"}
P.entries["quest:1785"] = {n="圣洁之书",s="《神圣之书》是圣职者在铁炉堡进行的一项关键试炼，最终将与蒂萨·热炉会面。完成这项试炼证明了你是否有资格使用生命符记，并能解锁复活阵亡盟友的神圣力量。",h="《神圣之书》是圣职者在铁炉堡进行的一项关键试炼，最终将与蒂萨·热炉会面。完成这项试炼证明了你是否有资格使用生命符记，并能解锁复活阵亡盟友的神圣力量。",kw={"铁炉堡","圣骑士","救赎","复活","生命符记","神圣之书","蒂萨·热炉"},ang={["class:Paladin"]="该任务标志着矮人圣骑士在铁炉堡进行的一项神圣成年礼，最终将获得圣光赋予的复活恩赐。",["faction:Alliance"]="受过圣光训练的勇士已做好准备，站在对抗天灾军团和黑铁矮人的最前线。",["race:Dwarf"]="试炼在铁炉堡内进行，并赢得了热炉家族代表矮人王国的感激。"},sec={{t="铁炉堡的神圣仪式",b="《神圣之书》是矮人圣职者训练过程中最关键的里程碑之一。在王国各地接受试炼后，勇士会被派往铁炉堡会见蒂萨·热炉，她是一位备受尊敬的神圣艺术导师。当你走向她时，她的丈夫怀着无比自豪的心情注视着你，渴望看到你的准备工作在矮人同胞和圣光面前得到认可。"},{t="复活的祝福",b="为了获得最终的祝福，勇士必须展示出驾驭生命符记所需的精神决心。正如蒂萨·热炉所解释的那样，这件圣物只会回应那些真正准备好引导圣光最深奥天赋的心灵。证明了这份资格，蒂萨便会赐予你一卷神圣卷轴，赋予你将阵亡战友从死亡边缘唤回的能力。这股力量被托付给勇士，以支撑铁炉堡对抗天灾军团和黑铁矮人的斗争。"}},faq={{q="什么是《神圣之书》？",a="《神圣之书》是铁炉堡的圣职者所进行的一项神圣试炼。完成这项试炼证明了你的精神成熟度，并赋予你引导圣光以复活阵亡同伴的能力。",al={"神圣之书是什么","神圣之书任务","这个任务有什么用"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位居住在铁炉堡的杰出矮人圣光导师。她会将最终的祝福颁发给证明自己有能力驾驭复活之力的勇士。",al={"蒂萨·热炉是谁","蒂萨·热炉在哪里","寻找蒂萨·热炉"}},{q="谁把你引荐给蒂萨·热炉的？",a="在完成之前的实地试炼后，你会受到她丈夫的指引前往蒂萨·热炉处。他此时身在铁炉堡，带着自豪与鼓励的话语将你引荐给他的妻子。",al={"谁发布这个任务","蒂萨的丈夫","谁引荐我去找蒂萨"}},{q="什么是生命符记？",a="生命符记是圣骑士试炼中使用的一件圣物。它只对那些因虔诚而有资格接受圣光最伟大奇迹之一（将阵亡盟友从死亡中唤回）的勇士起作用。",al={"什么是生命符记","生命符记圣骑士","复活如何运作"}},{q="完成这个任务能学到什么技能？",a="当你来到蒂萨·热炉面前时，她会赐予你一卷神圣卷轴，教给你救赎，即恢复阵亡盟友生命的力量。",al={"我能学到什么力量","复活法术任务","圣骑士复活任务"}},{q="为什么铁炉堡需要圣光勇士？",a="铁炉堡不断面临狡诈的黑铁矮人和天灾军团亡灵怪物的威胁，这使得强大的治疗者和神圣保卫者对于王国防御至关重要。",al={"铁炉堡的敌人是谁","为什么要对抗黑铁矮人和天灾军团","战场上的敌人"}}},fp="20,260,26.406.0,28.504.0,29.213.0,24.208.0,34.190.0,27.223.0,53.155.0,51.203.0"}
P.entries["quest:1786"] = {n="圣洁之书",s="《神圣之书》是艾尔文森林圣骑士的一项关于信仰与牺牲的神圣试炼。在一次迪菲亚法师的伏击导致侦察兵亨兹·法奥克在英雄哨岗阵亡后，一位有抱负的神圣战士必须挥舞生命符记来复活他，并挫败迪菲亚潜行者日益逼近的阴谋。",h="《神圣之书》是艾尔文森林圣骑士的一项关于信仰与牺牲的神圣试炼。在一次迪菲亚法师的伏击导致侦察兵亨兹·法奥克在英雄哨岗阵亡后，一位有抱负的神圣战士必须挥舞生命符记来复活他，并挫败迪菲亚潜行者日益逼近的阴谋。",kw={"迪菲亚","达索瑞恩","贾森","亨兹·法奥克","英雄哨岗","圣骑士","复活","石碑湖","生命符记","《神圣之书》"},ang={["class:Paladin"]="这项任务代表了年轻圣骑士的一个重要里程碑，通过挥舞生命符记来复活倒下的盟友，证明他们的信仰以及与圣光的联系。",["faction:Alliance"]="在艾尔文森林东北部活动的迪菲亚施法者威胁着暴风城腹地的安全，这使得在英雄哨岗收集情报对联盟至关重要。"},sec={{t="英雄哨岗的伏击",b="亨兹·法奥克和他的搭档贾森在听说迪菲亚潜行者特工渗透边境的报告后，前往了艾尔文森林东北部石碑湖中央的一座岛屿——英雄哨岗。为了寻找呈交给国王皇家顾问的确凿证据，两名侦察兵试图伏击一对正在审查计划的阴谋分子。然而，当迪菲亚施法者加入战斗时，他们很快就被压制了。亨兹坚守阵地对抗敌对法师，牺牲了自己，为贾森争取了足够的时间逃脱并保住了性命。"},{t="复活的恩赐",b="从伏击中恢复过来需要的不仅仅是普通的药物；这需要圣光的力量。装备着生命符记，一位有抱负的圣骑士被派往石碑湖，在岛上寻找亨兹的遗体。通过这件神圣的圣物引导个人信仰，使亨兹起死回生，这标志着神圣战士的精神纽带和为暴风城的防御服务、侍奉圣光的准备情况的一次关键考验。"}},faq={{q="谁是亨兹·法奥克？",a="亨兹·法奥克是一位勇敢的防御者，他与贾森一起冒险前往石碑湖上的英雄哨岗，以获取迪菲亚渗透的证据。他阻挡了迪菲亚法师，让他的同伴得以逃脱，最终死于他们的奥术攻击，之后通过生命符记复活。",al={"亨兹·法奥克是谁","亨兹·法奥克","亨兹在哪里"}},{q="英雄哨岗在哪里？",a="英雄哨岗是位于艾尔文森林东北部石碑湖中央的一座岛屿。迪菲亚法师和潜行者在那里建立了一个前哨站，正在仔细研读秘密计划。",al={"英雄哨岗在哪里","英雄哨岗位置","英雄哨岗岛屿"}},{q="什么是生命符记？",a="生命符记是一件用于引导圣骑士信仰并复活阵亡者的圣物。它需要真正的精神信念来赋予力量，因此在亨兹·法奥克身上成功使用它，是对圣骑士使命感的一次考验。",al={"什么是生命符记","如何复活亨兹","生命符记的用途"}},{q="谁指引了对亨兹·法奥克的营救？",a="贾森·坦诺姆在岛上从迪菲亚手中逃脱，现在躺在暴风城Cathedral of Light的祭坛旁受伤，他请求帮助。他是达索瑞恩·拉尔的朋友，达索瑞恩·拉尔是将这位新兵派往他那里的圣骑士领袖。",al={"谁派我去寻找亨兹","达索瑞恩还是贾森","《神圣之书》任务发布者"}},{q="迪菲亚在英雄哨岗做什么？",a="迪菲亚特工渗透进艾尔文森林东北部，并聚集在英雄哨岗，审查文件并协调他们的行动。亨兹和贾森试图找回这些文件，作为给国王顾问们的证据。",al={"迪菲亚为何在英雄哨岗","迪菲亚在石碑湖做什么","迪菲亚在艾尔文的计划"}},{q="亨兹和贾森为什么去石碑湖？",a="亨兹·法奥克和贾森在听说有迪菲亚渗透者的报告后，前往了石碑湖。他们的目标是伏击阴谋分子，并找回他们的计划书面证据，呈交给暴风城的安度因国王的顾问们。",al={"亨兹和贾森为何在那儿","亨兹和贾森的任务"}}},fp="20,298,23.564.0,24.427.1,19.287.0,23.188.0,27.215.0,38.219.0,43.216.0,47.231.0"}
P.entries["quest:1787"] = {n="圣洁之书",s="“神圣之书”是联盟圣骑士为了证明自己对圣光的虔诚而进行训练的关键任务。在艾尔文森林帮助一名叫亨兹的受伤斥候后，新兵必须面对迪菲亚潜行者（Defias Rogue Wizards），取回威胁王国安全的机密文件。",h="“神圣之书”是联盟圣骑士为了证明自己对圣光的虔诚而进行训练的关键任务。在艾尔文森林帮助一名叫亨兹的受伤斥候后，新兵必须面对迪菲亚潜行者（Defias Rogue Wizards），取回威胁王国安全的机密文件。",kw={"迪菲亚潜行者","迪菲亚手稿","艾尔文森林","贾森·坦诺姆","亨兹·法奥克","英雄哨岗","圣骑士任务","神圣之书"},ang={["class:Paladin"]="“神圣之书”是年轻圣骑士虔诚与勇气的核心试炼，考验他们保护无辜者并捍卫圣光以对抗迪菲亚兄弟会这类威胁的决心。",["faction:Alliance"]="揭露艾尔文森林内的迪菲亚动向与文件，能为暴风城的保卫者提供至关重要的情报。"},sec={{t="圣骑士的试炼",b="“神圣之书”是圣骑士受训期间至关重要的成人礼。在这项试炼中，新兵必须追踪亨兹，这名盟友在艾尔文森林的一座岛屿上监视非法活动时受了伤，新兵需要协助揭开当地迪菲亚渗透活动的规模。"},{t="艾尔文森林的渗透者",b="亨兹在岛上发现了正在审阅机密文件的迪菲亚潜行者，但他伤势过重，无法亲自战斗。他委托新兵击败这些潜行者法师并夺回他们的手稿，在将情报安全送达暴风城的贾森·坦诺姆手中之前，揭露他们的阴谋。"},{t="保卫王国",b="获得迪菲亚手稿证实了该兄弟会对英雄哨岗等周边地区构成了切实的威胁。将窃取的情报带回Cathedral of Light不仅证明了新兵对圣光的奉献，也证明了亨兹的生还。"}},faq={{q="这项任务涉及哪些人？",a="这一阶段的任务线始于找到在艾尔文森林某岛屿上受伤的亨兹·法奥克，并以向暴风城Cathedral of Light的贾森·坦诺姆报告结束。",al={"谁发布此任务","谁发布神圣之书","哪里接到神圣之书"}},{q="亨兹是谁？",a="亨兹是一位与圣骑士试炼相关的盟友，他在观察迪菲亚活动时受伤。虽然他本人已无法战斗，但他指引冒险者去获取该兄弟会渗透的证据。",al={"亨兹是谁","亨兹·法奥克背景故事","那个受伤的人是谁"}},{q="贾森·坦诺姆是谁？",a="贾森·坦诺姆是亨兹的朋友，也是达索瑞恩·拉尔的朋友，可以在暴风城Cathedral of Light的祭坛旁找到他。他从英雄哨岗的迪菲亚手中死里逃生，并希望得到亨兹平安的消息。",al={"贾森·坦诺姆是谁","贾森·坦诺姆在哪里","贾森 暴风城"}},{q="为什么迪菲亚潜行者会在岛上活动？",a="迪菲亚兄弟会在艾尔文森林各处建立了据点，利用潜行者法师研究计划并协调行动。他们携带的文件中包含了他们在该地区图谋的直接证据。",al={"为什么迪菲亚在艾尔文森林","迪菲亚潜行者","迪菲亚手稿"}},{q="英雄哨岗是什么？",a="英雄哨岗是艾尔文森林中受到迪菲亚行动威胁的一个地点。贾森·坦诺姆希望消灭附近的潜行者法师并获得他们的文件，从而保护该地点免受进一步的伤害。",al={"英雄哨岗是什么","英雄哨岗 艾尔文森林","英雄哨岗安全吗"}},{q="什么是迪菲亚手稿？",a="迪菲亚手稿是由迪菲亚潜行者携带的书面命令或通讯，证明了他们的渗透行为，并详述了他们在艾尔文森林内的近期图谋。",al={"什么是迪菲亚手稿","这些文件是什么","迪菲亚文件 艾尔文森林"}}},fp="20,291,17.276.0,22.313.1,21.248.1,30.203.0,13.207.0,20.199.0,53.217.0,22.204.0,26.182.0"}
P.entries["quest:1788"] = {n="圣洁之书",s="《神圣法典》是暴风城圣骑士的一项关键信仰与虔诚试炼。通过证明自己对神圣的“生命符记”的掌控能力并复活一名阵亡盟友，受试者将获得达索瑞恩·拉尔授予的庄严复活祝福。",h="《神圣法典》是暴风城圣骑士的一项关键信仰与虔诚试炼。通过证明自己对神圣的“生命符记”的掌控能力并复活一名阵亡盟友，受试者将获得达索瑞恩·拉尔授予的庄严复活祝福。",kw={"达索瑞恩","达索瑞恩·拉尔","亨泽","圣骑士","复活","暴风城","生命符记","神圣法典"},ang={["class:Paladin"]="这项试炼标志着圣骑士正式踏入对圣光的忠诚服务，并掌握了让阵亡伙伴重获新生的神圣力量。",["faction:Alliance"]="暴风城的圣骑士在圣光大教堂接受训练，通过保护联盟保卫者的生命来加强王国的防御。"},sec={{t="返回大教堂",b="在完成野外试炼并使用“生命符记”复活阵亡的亨泽后，一名见习圣骑士需要回到暴风城的圣光大教堂。从岛上回收的迪菲亚文件将通过贾森·坦诺姆呈交给国王的顾问们，但首先，达索瑞恩·拉尔还在等待受试者成功的消息。"},{t="复活的天赋",b="召唤圣光来起死回生并非轻而易举。在达索瑞恩·拉尔眼中，成功引导“生命符记”证明了受试者拥有圣骑士教团最伟大使命之一所必需的信仰与精神力量：复活之力。通过掌握这一仪式，圣骑士已准备好在未来王国的战场上守护盟友。"}},faq={{q="什么是《神圣法典》？",a="《神圣法典》代表了圣骑士学习运用圣光过程中的最终试炼。在这个阶段，见习圣骑士在证明自己有能力引导圣光复活亡者后，需向达索瑞恩·拉尔汇报。",al={"神圣法典","这是什么任务","神圣法典 圣骑士"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是一位驻扎在暴风城圣光大教堂的高阶圣骑士训练师，负责监督圣骑士受试者的成长，并评判他们是否有资格执行神圣仪式。",al={"谁是达索瑞恩","达索瑞恩·拉尔的职责","达索瑞恩在哪里"}},{q="什么是“生命符记”？",a="“生命符记”是一种神圣的媒介，用于召唤圣光来赋予亡者以生命。证明自己有能力引导其力量，意味着受试者已准备好掌握圣骑士的复活之力。",al={"生命符记的用途","生命符记做了什么"}},{q="亨泽是谁？",a="亨泽是一位在野外阵亡的盟友，在受试者的试炼过程中，他被使用“生命符记”复活，这证明了该圣骑士拥有逆转死亡所需的决心与信仰。",al={"谁是亨泽","亨泽背景故事","亨泽圣骑士任务"}},{q="圣骑士如何获得复活之力？",a="复活被认为是圣骑士最高荣誉之一。通过直接与圣光沟通并展现深厚的信仰，圣骑士学会了将阵亡的伙伴从死亡边缘唤回。",al={"圣骑士复活背景","圣骑士如何复活"}},{q="为什么这些文件要被交给国王的顾问？",a="这些文件是从岛上取得的迪菲亚文件。在达索瑞恩·拉尔审阅过后，贾森·坦诺姆会将它们交给国王的顾问，以此证明迪菲亚兄弟会已经渗透进了艾尔文森林。",al={"国王顾问的文件","什么文件送往暴风城"}}},fp="20,242,23.333.0,24.407.0,29.228.0,22.192.0,27.213.0,14.206.0,50.207.0,53.198.0"}
P.entries["quest:179"] = {n="矮人的交易",s="“矮人装备”是寒脊山谷的一项入门级生存任务，由斯登·粗臂提供。新兵们需要通过猎杀当地的狼群来获取硬狼肉作为冬季口粮，作为回报，他们将获得一副结实的手套，以抵御丹莫罗寒风的侵袭。",h="“矮人装备”是寒脊山谷的一项入门级生存任务，由斯登·粗臂提供。新兵们需要通过猎杀当地的狼群来获取硬狼肉作为冬季口粮，作为回报，他们将获得一副结实的手套，以抵御丹莫罗寒风的侵袭。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人装备","冻伤","手套","斯登·粗臂","硬狼肉"},ang={["race:Dwarf"]="对于初次踏入寒脊山谷的年轻铜须矮人来说，这项任务是学习边境自力更生的一堂早课：靠自己挣得生存所需，为营地提供补给，并敬畏山区的严寒。",["race:Gnome"]="在与丹莫罗的矮人亲族共同避难后，侏儒们很快就会发现，要在安威玛尔生存下去，不仅需要敏锐的头脑，还需要实用的山区装备。"},sec={{t="寒脊山谷的公平交易",b="寒脊山谷的山隘终年积雪，气候严酷，未做好准备的旅行者很快就会发现普通装备根本无法抵御大自然的威胁。斯登·粗臂驻守在安威玛尔外，向新兵们提供了一笔直截了当的边境交易：前往雪原猎杀那些出没的狼群，带回硬狼肉来补充哨站的物资。作为交换，他会提供合适的防寒手套，确保年轻的冒险者们不会冻伤手指。"},{t="在山谷中求生",b="对于在山谷中训练的矮人侦察兵和侏儒新兵来说，狼群既是一种时刻存在的威胁，也是一种重要的资源。它们的肉维持着安威玛尔驻军的生存，而且猎杀狼群也能让当地营地之间的道路变得更加安全。斯登·粗臂的这个安排具有双重意义——既测试了新兵应对当地野生生物的能力，又为即将到来的严寒夜晚储备了食物。"}},faq={{q="斯登·粗臂是谁？",a="斯登·粗臂是一名驻守在寒脊山谷安威玛尔外的矮人。他负责留意刚抵达的新兵，确保他们拥有足够的装备来在丹莫罗严寒的气候中生存，并以实用的装备作为交换，鼓励他们去猎杀当地的野兽。",al={"斯登·粗臂","谁发布矮人装备任务","安威玛尔装备商"}},{q="为什么斯登需要狼肉？",a="安威玛尔哨站依靠当地的狩猎活动来维持物资储备。对于生活在这个与世隔绝、冰天雪地的山谷中的士兵和训练员来说，狼肉提供了耐寒且可靠的营养。",al={"为什么需要狼肉","硬狼肉","狼肉的用途"}},{q="在哪里可以找到做这个任务的狼？",a="狼群游荡在整个寒脊山谷的雪原空地上，特别是在安威玛尔主庭院外以及通往外围营地的道路上。",al={"狼群位置","寒脊山谷的狼","在哪里获得狼肉"}},{q="斯登提供什么奖励？",a="斯登奖励新兵一副可靠的保暖手套，这副手套专为抵御冻伤而设计，能保护战士的手部免受丹莫罗凛冽寒风的侵袭。",al={"矮人装备任务奖励","奖励什么手套","任务奖励"}},{q="狼肉在矮人中算得上是好食物吗？",a="硬狼肉粗糙且耐嚼，但在丹莫罗恶劣的山地气候下，矮人们更看重能填饱肚子的充饥食物，而不是美食。用营火炖煮或烤制后，它对驻军来说是非常实用的口粮。",al={"狼肉好吃吗","矮人吃狼肉","食用狼肉"}},{q="侏儒也能做这个任务吗？",a="可以。在寒脊山谷与矮人盟友并肩训练的侏儒同样面临着凛冽的寒风，他们也迫切需要保暖的衣物。",al={"侏儒与矮人装备任务","侏儒可以获得手套吗","侏儒防寒"}}},fx={cf6e8786={q="寒脊山谷里的狼在做什么？",a="瘦弱的幼狼和瘦弱的森林狼在寒脊山谷冰封的山崖间游荡，是当地的掠食者。它们是丹莫罗严酷山地生态的一部分，但在安威玛尔外凶猛出没，成了新兵们经常面对的麻烦，也为哨站提供了方便的新鲜食物来源。",al={"这里为什么有狼","寒脊山谷的狼","丹莫罗的狼群威胁"}}},fp="18,283,25.471.0,21.438.0,21.262.0,29.195.0,43.175.0,30.166.0,48.221.0,29.145.0"}
P.entries["quest:1791"] = {n="捕风者",s="“捕风者”是一项指引任务，指示经验丰富的战士去北方极远处寻找一位隐居的巨魔萨满。在“乱斗”试炼中证明了自己的实力并掌握了狂暴姿态后，战士们被指引去寻找一把与他们日益增长的怒火相匹配的武器。",h="“捕风者”是一项指引任务，指示经验丰富的战士去北方极远处寻找一位隐居的巨魔萨满。在“乱斗”试炼中证明了自己的实力并掌握了狂暴姿态后，战士们被指引去寻找一把与他们日益增长的怒火相匹配的武器。",kw={"奥特兰克山脉","捕风者巴斯拉","狂暴姿态","塞克隆尼亚","勇士岛","克兰诺克·马克雷德","塔伦米尔","乱斗","捕风者"},ang={["class:Warrior"]="这场成年礼将你在勇士岛上掌握的狂暴姿态与通过元素力量锻造传奇武器的追求联系在了一起。",["race:Troll"]="寻找巴斯拉证明了即使是在洛丹伦破碎的废墟深处，巨魔萨满和武器制造者所掌握的神秘知识也受到各族战士的敬仰。"},sec={{t="狂战士的武器",b="在勇士岛上幸存并通过残酷的“乱斗”试炼后，战士们便从克兰诺克·马克雷德那里获得了狂暴姿态的凶猛纪律。然而，纯粹的武技纪律还需要与之相称的武器。克兰诺克意识到了这一点，于是他让这些前途无量的战士离开贫瘠之地的海岸，指引他们跨越大陆，去寻找一位能够打造非凡武器的隐居工匠。"},{t="河岸上的隐士",b="任务指引旅行者深入洛丹伦北部的纷争山谷，具体来说是奥特兰克山脉和被瘟疫侵蚀的西瘟疫之地之间那片迷雾笼罩的边境地带。巨魔隐士捕风者巴斯拉独自居住在流经塔伦米尔北部的河岸边的石质废墟中。巴斯拉并非普通的隐士：他既是一位天赋异禀的武器制造者，又是一位强大的元素萨满，他正在等待那些决心打造出真正非凡之物的战士。"}},faq={{q="是谁让你去找捕风者的？",a="当你征服了“乱斗”并学会了狂暴姿态后，位于贫瘠之地东海岸外勇士岛上的战斗试炼大师克兰诺克·马克雷德就会派你踏上这段旅程。",al={"任务发布者","谁发布了捕风者任务","克兰诺克·马克雷德任务"}},{q="捕风者巴斯拉是谁？",a="巴斯拉是一位神秘的巨魔隐士、武器锻造大师和强大的萨满，他隐居在奥特兰克山脉和西瘟疫之地之间的荒野中。",al={"巴斯拉是谁","捕风者巴斯拉背景故事","巴斯拉的身份"}},{q="巴斯拉具体在哪里？",a="巴斯拉在流经塔伦米尔北部的河流东岸安营扎寨，就在奥特兰克和西瘟疫之地交界处的古代废墟附近。",al={"巴斯拉在哪里","巴斯拉的位置","寻找巴斯拉"}},{q="为什么克兰诺克要派战士去找巴斯拉？",a="克兰诺克认为，掌握了凶猛狂暴姿态的战士需要一把出色的武器来引导那股怒火，而巴斯拉拥有打造这种武器所必需的罕见元素和锻造知识。",al={"为什么要去见巴斯拉","这个任务的目的是什么","捕风者的目的"}},{q="与巴斯拉交谈后会发生什么？",a="与巴斯拉交谈后，将立即开启对抗狂暴元素生物塞克隆尼亚的任务，并收集稀有材料来制造一把强力的武器。",al={"捕风者之后是什么","塞克隆尼亚后续任务","捕风者任务后续"}},{q="对于从贫瘠之地出发的旅行者来说，这趟旅程安全吗？",a="这相当危险。旅程将带旅行者穿过希尔斯布莱德丘陵，进入辛迪加巢穴附近的北部纷争领土，那里有凶猛的山地掠食者，还有致命的西瘟疫之地瘟疫。",al={"这很危险吗","塔伦米尔河流的危险"}}},fx={ff43a27e={q="为什么克兰诺克派你去找巴斯拉，而不自己去？",a="克兰诺克·马克雷德并非在为自己寻找传奇武器；他是在勇士岛的角斗场担任经验丰富的导师。看到你在搏击中幸存下来并掌握了狂暴姿态后，他相信你已配得上与你新获力量相称的武器。前往遥远的隐士巴斯拉那里进行漫长的朝圣之旅，是对战士自身决心与成长的考验。",al={"风语者任务为什么是我","为什么派战士去","克兰诺克为什么派玩家去"}}},fp="15,283,24.410.0,27.517.0,38.202.0,32.171.0,34.175.0,43.210.0,40.163.1,60.223.0"}
P.entries["quest:1792"] = {n="旋风武器",s="“Whirlwind Weapon”任务标志着战士通过从元素生物Cyclonian身上获得的旋风之心，完成了武器的最终强化。通过将这头野兽狂暴的核心束缚进一件选定的容器中，使用者便可掌握风暴的本质与狂怒。这是武艺精进过程中的一个标志性里程碑。",h="“Whirlwind...",kw={"cyclonian","元素","风暴","容器","战士武器","旋风之心","旋风武器"},ang={["class:Warrior"]="获得“Whirlwind Weapon”是战士们的传奇成人礼，能为他们提供一把灌注了Cyclonian风暴之力的武装。"},sec={{t="灌注风暴之力",b="“Whirlwind Weapon”任务标志着一项关于力量与掌控的严酷试炼的完成。在降服元素风暴Cyclonian并取回其不稳定的核心后，战士会准备一件物理容器来承载风暴的原始能量。工匠已做好准备，将这只生物原始而旋转的心脏融合进选定的武器中，将普通的锻造金属转变为元素之怒的传奇载体。"},{t="Cyclonian的力量",b="Cyclonian的心脏体现了呼啸的狂风与猛烈的飓风那未被驯服的狂暴。通过将这一核心锚定在锻造的武器中，使用者所掌控的不仅是自身的武学修为，还有风暴本身的生命力量。每一次挥击都回荡着这名被击败的元素生物的共鸣伟力，确保Cyclonian的风暴能在其征服者手中持续咆哮。"}},faq={{q="什么是“Whirlwind Weapon”任务？",a="“Whirlwind Weapon”代表了战士对抗元素力量的试炼的终章。通过从Cyclonian身上捕获旋风之心，战士可以选择一件武器，将这种被捕获的元素本质灌注其中，从而创造出一件拥有强大原始力量的武装。",al={"什么是旋风武器","旋风武器背景故事","这个任务是什么"}},{q="谁是Cyclonian？",a="Cyclonian是风与风暴的强大元素化身。击败这个狂暴的实体可以获得旋风之心，它作为魔法动力源，能将原始的风之能量直接束缚在物理武器中。",al={"cyclonian是谁","cyclonian背景故事","什么是cyclonian"}},{q="什么是旋风之心？",a="旋风之心是从被击败的元素生物Cyclonian身上获得的核心本质。它蕴含着风暴原始而狂野的怒火，随时准备被束缚进战士所选的锻造容器中。",al={"什么是旋风之心","cyclonian之心","cyclonian的心脏"}},{q="武器是如何强化的？",a="“Whirlwind Weapon”的制作方法是选取一件武器作为容器，并将旋风之心引导注入其中。这个过程将Cyclonian的元素之怒直接束缚进钢铁中，使每一次挥击都灌注着风之能量。",al={"旋风武器如何制作","武器选择","锻造旋风武器"}},{q="武器有哪些选择？",a="战士可以选择自己偏好的武学载体来承载Cyclonian的风暴本质，根据自己喜爱的战斗风格和武器偏好来定制这种元素强化。",al={"我可以选择哪种武器","旋风武器选择","提供哪些武器"}},{q="为什么要追寻Cyclonian的力量？",a="战士们追求这种强化，因为将Cyclonian的核心武器化可以掌控狂暴的生命飓风，将武学招式转化为毁灭性的元素破坏力。",al={"为什么战士想要旋风武器","旋风武器的重要性"}}},fp="16,314,18.433.0,22.393.0,35.268.0,17.231.0,28.202.0,28.220.0,40.178.0,38.190.0"}
P.entries["quest:1793"] = {n="勇气之书",s="《勇气之书》是联盟圣骑士成长过程中的一项基础试炼。在暴风城和铁炉堡圣骑士导师的指导下，受试者必须证明他们的勇气和保护无辜者的奉献精神与他们的武技同样出色。",h="《勇气之书》是联盟圣骑士成长过程中的一项基础试炼。在暴风城和铁炉堡圣骑士导师的指导下，受试者必须证明他们的勇气和保护无辜者的奉献精神与他们的武技同样出色。",kw={"cathedral of light","达索瑞恩·拉尔","圣光","铁炉堡","圣骑士试炼","白银之手","蒂萨·热炉","勇气之书"},ang={["class:Paladin"]="这项仪式标志着从一名仅仅是侍从的学徒向圣光受托保卫者的转变，挑战你将无私的职责置于个人安全之上。",["faction:Alliance"]="《勇气之书》中概述的试炼旨在帮助勇士们保卫联盟定居点，抵御从当地强盗到怪物入侵者等日益增长的威胁。",["race:Dwarf"]="铁炉堡的圣骑士在蒂萨·热炉等导师的带领下，将《勇气之书》视为矮人坚韧精神在圣光目标加持下得到强化的证明。",["race:Human"]="在圣光大教堂达索瑞恩·拉尔的注视下组织进行，这项试炼反映了暴风城对白银之手创始理想的持久奉献。"},sec={{t="圣骑士的衡量标准",b="在战斗中运用圣光不仅仅需要沉重的盔甲和严明的纪律。当年轻的圣骑士在修行中达到更高的境界时，圣光大教堂和Hall of Mysteries的导师们会要求他们证明内心的坚定。 《勇气之书》的课程旨在考验受试者面对恐怖邪恶——从巨龙到恶魔——时，是否做好了准备，并保证他们不会退缩，也不会抛弃那些无法自卫的人。"},{t="秩序的美德",b="面对致命威胁时的勇敢，被认为是对圣战者而言与武器和盾牌同样重要的品质。通过《勇气之书》中设定的试炼，圣骑士们了解到，如果没有保护弱者的坚定誓言，纯粹的力量也是空洞的。面对真正的危险可以确保当黑暗笼罩联盟时，它的保卫者能够屹立不倒，而不是崩溃。"}},faq={{q="《勇气之书》的目的是什么？",a="《勇气之书》代表了联盟圣骑士成长过程中的一个成人礼。它由圣光的导师们设计，旨在确保受试者在晋升等级之前，拥有真正的勇气和保护弱者的无私愿望。",al={"什么是勇气之书","勇气之书的目的","为什么要进行勇气之书试炼"}},{q="谁来指导圣骑士进行这项试炼？",a="受试者通常会接到联盟首都高级圣骑士的召唤来参加这项试炼，例如暴风城圣光大教堂的达索瑞恩·拉尔或铁炉堡Hall of Mysteries的蒂萨·热炉。",al={"谁发放勇气之书任务","勇气之书任务发布者","谁开启勇气之书试炼"}},{q="这项试炼通向何处？",a="最初的召唤是通往一系列特定任务的门户，这些任务考验着圣骑士的决心，驱使他们投身前线，为了保卫王国和无辜者而直面真正的危险。",al={"勇气之书之后是什么","勇气之书后续任务","勇气之书任务线"}},{q="为什么圣骑士如此强调勇敢？",a="圣光响应信仰与意志。当面对恶魔或巨龙等压倒性的恐怖力量时，恐惧会击碎战士的精神；而勇气能确保圣骑士即使在最严酷的情况下，依然是他人坚定的盾牌。",al={"为什么需要勇气","为什么勇气对圣骑士很重要"}},{q="矮人和人类圣骑士是否进行同样的测试？",a="虽然矮人圣骑士在铁炉堡进行训练，而人类圣骑士在暴风城的圣光大教堂进行训练，但这两个传统都遵循相同的核心美德，即在圣光之下保持勇气、职责和对弱者的保护。",al={"矮人的测试是否不同","铁炉堡勇气之书","暴风城勇气之书"}},{q="试炼中概述了哪些核心课程？",a="试炼的核心是三个基本责任：无论胜算如何，都要掌握坚不可摧的勇气；积极保护弱者免受伤害；以及在面对恐惧时保持信仰。",al={"勇气之书课程","勇气之书教导什么"}}},fx={["81822402"]={q="为什么圣骑士导师要你接受这场试炼？",a="艾泽拉斯各地的局势日益险恶，恶魔和巨龙等邪恶力量正步步逼近。你已经证明圣光会回应你的召唤，但达索瑞恩·拉尔和蒂萨·热炉明白，光有信仰还不够。在更大的危难降临故土之前，他们必须考验你内在的勇气，确认你拥有真正圣骑士所需的坚定无畏。",al={"为什么要接受试炼","达索瑞恩·拉尔的动机","蒂萨·热炉为何要试炼"}},f91e68e3={q="为什么必须由你接受试炼，而不是资深圣骑士或卫兵？",a="这趟旅程不是城卫或老练骑士能替你完成的防卫差事，而是你个人的成年礼。导师必须亲眼看看你在困境面前如何坚守本心，考验你保护弱者、坚守信仰并在恐惧面前毫不退缩的能力。",al={"为什么让我接受勇气之书的试炼","为什么派玩家接受勇气试炼","卫兵为什么不能完成这件事"}}},fp="17,264,24.434.0,20.366.0,41.255.0,35.201.0,27.195.0,50.234.0,52.205.0,44.197.0"}
P.entries["quest:1795"] = {n="誓缚",s="“契约”是术士寻求驾驭地狱犬所必须完成的终极仪式。该仪式由隐居在棘齿城上方的神秘召唤师斯坦哈德·法尔杉监督，利用修复后的《秘法会之书》从扭曲虚空中撕裂出一只凶猛的恶魔掠食者，并通过战斗试炼迫使其臣服。",h="“契约”是术士寻求驾驭地狱犬所必须完成的终极仪式。该仪式由隐居在棘齿城上方的神秘召唤师斯坦哈德·法尔杉监督，利用修复后的《秘法会之书》从扭曲虚空中撕裂出一只凶猛的恶魔掠食者，并通过战斗试炼迫使其臣服。",kw={"贫瘠之地","地狱犬","棘齿城","斯坦哈德·法尔杉","召唤","契约仪式","秘法会之书","术士"},ang={["class:Warlock"]="制服地狱犬是任何术士的重要里程碑，为他们提供了一种专门的抗魔法掠食者，使其能够吞噬法术并压制敌对施法者。",["faction:Alliance"]="联盟术士会从安全的暴风城出发，跨越海洋来到崎岖的中立避风港棘齿城，在斯坦哈德的注视下完成他们危险的召唤仪式。",["faction:Horde"]="部落的修炼者则会深入贫瘠之地的中心，去证明他们对虚空的掌控，并在中立的土地上站在斯坦哈德面前完成猎犬的契约。"},sec={{t="秘法会之圆",b="斯坦哈德·法尔杉栖身于俯瞰地精港口棘齿城的悬崖之上，在此进行着卡利姆多最危险的恶魔学试炼。当术士收集齐拼凑古老《秘法会之书》所需的各种残片和试剂后，斯坦哈德便会准备契约之地。他会布置一个内圈的约束符文，同时他的忠诚侍僧们会通过附魔之杖引导能量来完成外圈，确保任何从中浮现的恐怖存在都被隔离在下方的定居点之外。"},{t="征服猎犬",b="受训者诵读《秘法会之书》中记载的咒语，打开了一道通往扭曲虚空的桥梁。地狱犬是贪婪的恶魔猎犬，它们天生渴求奥术力量，并以魔法能量为食。被召唤出的野兽绝非靠好言相劝或温和束缚就能控制；它必须在战斗中被暴力制服并击溃，才会承认术士为它真正的主人。在冲突中幸存下来，证明了召唤师已经做好准备，可以驱使这条猎犬对抗敌方施法者。"}},faq={{q="这个仪式的目的是什么？",a="该仪式允许术士召唤并契约一只地狱犬为己所用。通过在斯坦哈德·法尔杉的召唤法阵内诵读完整的《秘法会之书》，术士会将这只恶魔掠食者从虚空中引出，并在战斗中击败它，从而赢得该恶魔永久的服侍。",al={"为什么要完成这个任务","地狱犬任务目标","契约的目的"}},{q="谁是斯坦哈德·法尔杉？",a="斯坦哈德·法尔杉是一位造诣极高的术士，在贫瘠之地棘齿城上方的一座塔楼中运作。由于他掌握着渊博的黑暗召唤学知识，来自联盟和部落的导师们都会悄悄地将他们最有前途的学徒送去接受他的教导，学习进阶的契约仪式。",al={"谁是斯坦哈德","斯坦哈德·法尔杉背景故事","任务发放人斯坦哈德"}},{q="为什么术士必须杀死恶魔而不是直接奴役它？",a="地狱犬是一种极具侵略性、以魔法为食的掠食者，它们只尊重绝对的统治力。仪式要求修炼者在物理和魔法战斗中击败恶魔，以挫其锐气并将权威烙印在它的灵魂深处，确保它能服从未来的召唤。",al={"为什么要杀死地狱犬","我能直接奴役地狱犬吗","地狱犬战斗"}},{q="部落和联盟的术士都能在这里进行这个仪式吗？",a="是的。虽然重建《秘法会之书》的前置任务会根据阵营有所不同，但联盟和部落的术士最终都会被指引到棘齿城上方的斯坦哈德·法尔杉处进行最后的召唤。",al={"这是部落专属吗","这是联盟专属吗","谁能接到这个任务"}},{q="如果地狱犬击败了召唤师会发生什么？",a="如果召唤师落败，恶魔会被放逐回扭曲虚空，仪式即告失败。不过，斯坦哈德允许在失败中幸存的术士重新获取一份新的《秘法会之书》，并在做好充分准备后再次尝试召唤。",al={"如果我死了怎么办","契约仪式失败","我可以重试仪式吗"}},{q="地狱犬与其他恶魔相比有什么独特之处？",a="地狱犬是靠感知魔法散逸来捕猎的恶魔猎犬。它们不仅依靠蛮力或暗影法术，更擅长嗅出魔法痕迹、吞噬激活的附魔并干扰敌方施法者，这使它们成为对抗敌对施法者时不可多得的宝贵同伴。",al={"地狱犬有什么能力","地狱犬背景故事","为什么需要地狱犬"}}},fx={b1095368={q="斯坦哈德·法尔杉为什么要你召唤地狱猎犬？",a="斯坦哈德·法尔杉并非让你跑腿，而是在训练你掌握更高深的恶魔法术。他认为每位术士都该有一只地狱猎犬听命，因为这种生物的扰乱能力远胜于束缚它的危险。在指导你收集材料和《黑暗教派法典》后，他希望借此考验你的潜力，看看你能否经受试炼，跻身当代最强大的术士之列。",al={"斯坦哈德为什么要这样做","斯坦哈德·法尔杉的动机","斯坦哈德为什么要召唤地狱猎犬"}},["44d888c5"]={q="为什么必须由你亲自面对地狱猎犬，而不是让斯坦哈德来对付它？",a="召唤出的恶魔不能由别人代你征服。要奴役来自扭曲虚空的爪牙，你必须证明自己的意志和对它的支配力；若由斯坦哈德或他的助手击败它，也无法与它建立对你效忠的契约。斯坦哈德和助手们会引导强大的召唤法阵来控制裂隙，但在战斗中击溃野兽的蛮力，是只有未来的主人才能承受的考验。",al={"斯坦哈德为什么不能对付它","为什么必须杀死地狱猎犬","为什么必须独自对抗恶魔"}},["6bf7b15d"]={q="召唤出的地狱猎犬是什么？它来自哪里？",a="你面对的是一只凶残的掠食恶魔，它通过《黑暗教派法典》中的咒语直接从扭曲虚空中被召来。地狱猎犬是可怕的野兽，嗜食奥术与魔法能量，会热切地追踪、吸取并扰乱这些能量。它生性贪婪，因此被召入法阵后，一现身便会立刻攻击你。你必须在它的灵魂被束缚为你效力之前，在战斗中将它制服。",al={"召唤出的地狱猎犬是什么","我要对付什么","地狱猎犬背景"}}},fp="11,301,18.506.0,22.507.0,35.285.0,22.302.0,66.283.0,62.227.0,51.257.0,54.293.0"}
P.entries["quest:1796"] = {n="魔化金线血袍",s="梅纳拉·沃伦德指派贫瘠之地的术士新秀去弄到一件奥法之袍，作为一件强大魔法装备的基础服饰。这是制作魔化金线血袍的第一步，为承受黑暗附魔打下基础。",h="梅纳拉·沃伦德指派贫瘠之地的术士新秀去弄到一件奥法之袍，作为一件强大魔法装备的基础服饰。这是制作魔化金线血袍的第一步，为承受黑暗附魔打下基础。",kw={"贫瘠之地","血袍","魔化金线血袍","梅纳拉·沃伦德","奥法之袍","裁缝","术士任务"},ang={["class:Warlock"]="制作魔化金线血袍是术士的重要成人礼，它教导人们强大的神器必须锻造在坚韧、精心准备的基础之上。",["profession:Tailoring"]="该任务依赖于一位精通奥法之袍图样的熟练裁缝的专业技术，需要使用蜘蛛丝和一卷又一卷的精良丝绸。",["race:Orc"]="对于在种族恶魔历史的阴影下工作的兽人术士来说，为这种低调的长袍收集材料，代表着一种在众目睽睽之外对邪能的更深层掌控。",["race:Undead"]="被遗忘者修行者经常长途跋涉来到被阳光暴晒的贫瘠之地，从梅纳拉那里获取技术，寻求加固他们脆弱的凡人躯壳以抵御自身不稳定的艺术。"},sec={{t="奥法之器",b="在将黑暗魔法束缚到布料上之前，这件服饰本身必须足以承载那样的力量。梅纳拉·沃伦德告诫那些寻求更强力量的术士去弄到一件奥法之袍。正如梅纳拉所解释的那样，任何魔法遗物的能力都取决于其基础材料中所蕴含的技巧、稀有度和心血。普通的破布会在深层附魔的压力下支离破碎，因此一件缝制精良、能够感应魔法的服饰是必不可少的。"},{t="工艺与抱负",b="虽然梅纳拉对能够亲手缝制这件衣服的修行者表示特别赞赏，但她认为冷酷的抱负比自尊心更为重要。无论术士是亲自缝制丝绸、委托天才的工匠，还是在市场上进行交易，结果都是一样的：一件已经完成的长袍，等待着被改造成一种专门的邪能掌握工具。"}},faq={{q="为什么梅纳拉·沃伦德特别需要奥法之袍？",a="高阶附魔需要一件以精湛技艺和稀有材料织成的服饰。梅纳拉使用奥法之袍作为一种纯净、易于感应的基础，以便容纳即将束缚其中的不稳定魔法力量。",al={"为什么需要奥法之袍","为什么是这件长袍","长袍的用途"}},{q="梅纳拉·沃伦德在哪里？",a="梅纳拉·沃伦德居住在贫瘠之地的地精港口棘齿城，她在那里指导那些寻求提升技艺并锻造专业装备的术士。",al={"梅纳拉·沃伦德位置","梅纳拉在哪里","梅纳拉·沃伦德在何处"}},{q="我必须自己裁缝奥法之袍吗？",a="不需要。虽然梅纳拉尊重亲自制作这件服饰的敬业精神，但她也接受通过交易获得或从其他工匠那里购买的长袍。对于术士来说，通过任何实际手段获得这个容器都是可以接受的。",al={"我需要裁缝技能吗","我可以购买长袍吗","是否需要裁缝"}},{q="奥法之袍的图样从哪里来？",a="该图样是一种稀有掉落，主要出现在教徒和黑暗施法者身上，例如奥萨拉克斯之塔的黑暗之潮虚空召唤者或在暮色森林活动的迪菲亚附魔师。",al={"奥法之袍图样","如何获得图样","裁缝配方位置"}},{q="上交奥法之袍后会发生什么？",a="梅纳拉会将长袍据为己有，作为后续灌注仪式所需的原材料。如果你在完成任务时正穿着它，她会立即将其剥下，直到后续步骤完成前，你将没有胸甲可穿。",al={"我会失去长袍吗","长袍不见了","长袍的下场"}},{q="什么是魔化金线血袍？",a="这是一件为中阶术士量身定做的特殊法衣。通过黑暗组件和防护附魔束缚在一起，它能增强施法者的韧性和黑暗能量储备。",al={"什么是血袍","血袍背景故事","魔化金线血袍"}}},fx={["44990969"]={q="梅纳拉·沃伦德为什么要你完成这件事？",a="梅纳拉·沃伦德是导师，负责引导野心勃勃的术士精进黑暗法术。她并非想为自己添置一件长袍，而是在考验你的决心和应变能力，同时教你如何制作强大的术士法衣。引导有前途的术士借助量身打造的媒介驾驭邪能，可以壮大他们这门隐秘技艺的力量。",al={"梅纳拉为什么帮我","梅纳拉·沃伦德的动机","为什么要制作长袍"}}},fp="43,292,18.443.0,18.366.0,61.234.0,35.159.0,47.225.0,53.191.0,58.255.0,37.182.0"}
P.entries["quest:1798"] = {n="寻找斯坦哈德",s="“寻找斯坦哈德”是一项联盟术士任务，它派遣从暴风城出发的黑暗艺术修行者跨越无尽之海，前往贫瘠之地。在那里，在棘齿城这座地精港口的注视之下，他们将寻求斯坦哈德·法尔杉的专业指导，以学习如何召唤地狱猎犬。这标志着术士正式踏入了更高阶、更危险的恶魔奴役领域。",h="“寻找斯坦哈德”是一项联盟术士任务，它派遣从暴风城出发的黑暗艺术修行者跨越无尽之海，前往贫瘠之地。在那里，在棘齿城这座地精港口的注视之下，他们将寻求斯坦哈德·法尔杉的专业指导，以学习如何召唤地狱猎犬。这标志着术士正式踏入...",kw={"地狱猎犬","黑暗缚灵者加科因","棘齿城","寻找斯坦哈德","暴风城","斯坦哈德·法尔杉","贫瘠之地","术士"},ang={["class:Warlock"]="这项任务标志着术士成长过程中的一个重要里程碑，从基础的虚空行者和魅魔，进阶到了狡诈、嗜魔的地狱猎犬。",["faction:Alliance"]="对于联盟的召唤者来说，这段旅程需要他们勇敢地跨越无尽之海，直接踏入崎岖且由部落主导的卡利姆多腹地。"},sec={{t="跨越海洋的召唤",b="在暴风城Slaughtered Lamb的地下巢穴中，黑暗缚灵者加科因负责指导初出茅庐的术士们。然而，想要驾驭那捕食性的地狱猎犬，需要的材料、圣物和仪式远非Mage Quarter这间简陋的地下室所能提供。鉴于他的学徒实力已有增长，加科因指引他们离开王国的庇护，前往卡利姆多，由此开启了一段跨越大陆连接人类恶魔学隐秘圈子的旅程。"},{t="棘齿城的隐士",b="目的地是俯瞰棘齿城地精港口的干旱山丘。斯坦哈德·法尔杉就居住在那里，他是一名人类术士，也是加科因秘密结社中的同僚。在这一中立领土上活动，让斯坦哈德能够相对自由地避开联盟治安官、教会审判官以及部落哨兵的窥探。他在贫瘠之地的存在，成为了那些渴望掌控法力吞噬者恶魔的雄心勃勃的召唤者们的锚点。"}},faq={{q="是谁派你去寻找斯坦哈德的？",a="黑暗缚灵者加科因，那位隐居在暴风城Mage Quarter的Slaughtered Lamb地下室中的术士训练师，会在你准备好学习如何召唤地狱猎犬时，派遣你踏上这段旅程。",al={"谁给予寻找斯坦哈德任务","任务给予者","加科因"}},{q="斯坦哈德·法尔杉位于何处？",a="斯坦哈德·法尔杉以贫瘠之地为家，驻扎在俯瞰地精港口城镇棘齿城的高地上。",al={"斯坦哈德位置","斯坦哈德在哪里","寻找斯坦哈德"}},{q="为什么联盟术士必须大老远跑到贫瘠之地去？",a="加科因在暴风城内缺乏进行地狱猎犬召唤仪式所需的特殊试剂和学识。斯坦哈德·法尔杉掌握着必要的知识和材料，并且他已在棘齿城这一中立地带站稳脚跟，避开了当地势力的盘查。",al={"为什么去贫瘠之地","为什么去卡利姆多","为什么去棘齿城"}},{q="这项任务会解锁什么能力？",a="这项任务是通往“秘法会之书”及其召唤地狱猎犬同伴所需的契约仪式这一系列任务的入门步骤。",al={"这是什么宠物的任务","我能得到什么","地狱猎犬任务"}},{q="斯坦哈德·法尔杉对部落怀有敌意吗？",a="不。斯坦哈德居住在地精的中立领土上，并为寻求召唤地狱猎犬秘诀的联盟和部落术士提供指导，他与多个结社保持着联系。",al={"斯坦哈德是联盟独有吗","部落的斯坦哈德"}},{q="与斯坦哈德交谈后会发生什么？",a="在你向他问候后，斯坦哈德会指派你收集契约仪式所需的必要组件，从而开启涉及“秘法会之书”的多阶段任务链。",al={"后续任务","寻找斯坦哈德之后做什么","秘法会之书"}}},fx={["034d02a4"]={q="黑暗缚灵者加科因为什么要你去找斯坦哈德？",a="加科因认为你的力量已足以驾驭地狱猎犬，但他缺少在暴风城附近指导你所需的奥术试剂和仪式材料。为了不让你的训练停滞，他派你去找斯坦哈德·法尔杉——这位可信赖的同道身处他们的核心圈子，掌握着所需的知识和材料，而这些都在海的另一边。",al={"为什么要去找斯坦哈德","黑暗缚灵者加科因的动机","加科因为什么派你去"}}},fp="15,369,24.480.0,21.455.0,30.202.0,32.115.0,71.262.0,47.147.0,39.195.0,40.170.0"}
P.entries["quest:18"] = {n="潜行者兄弟会",s="“盗贼兄弟会”是维里副队长在北郡修道院外指派的一项早期任务。它引导年轻的联盟新兵穿过东边的河流，去击退一群被称为迪菲亚潜行者的入侵强盗。收集这些盗贼标志性的红色粗麻面罩，能为暴风城当局提供该组织在山谷中存在的第一手确凿证据。",h="“盗贼兄弟会”是维里副队长在北郡修道院外指派的一项早期任务。它引导年轻的联盟新兵穿过东边的河流，去击退一群被称为迪菲亚潜行者的入侵强盗。收集这些盗贼标志性的红色粗麻面罩，能为暴风城当局提供该组织在山谷中存在的第一手确凿证...",kw={"面罩","盗贼兄弟会","迪菲亚","维里副队长","艾尔文","北郡","暴风城军队"},ang={["class:Rogue"]="遭遇迪菲亚让新手潜行者得以一窥有组织的犯罪网络是如何在人类中心地带的阴影中运作的。",["faction:Alliance"]="在王国正规军兵力吃紧的情况下，暴风城当局依靠刚抵达的联盟新兵来维持北郡的和平。",["race:Human"]="对于在北郡开始训练的人类来说，对抗迪菲亚是第一个严酷的提醒，那就是暴风王国的安全正从内部瓦解。"},sec={{t="山谷中的强盗",b="北郡山谷长期以来一直被视为艾尔文森林中的避风港，受到暴风城卫兵的保护，专门用于训练新兵和圣光教士。然而最近，外围的纪律有所松懈。流浪汉和盗贼穿过了东边的河流，在树林附近潜伏，并在修道院的眼皮底下建立了小型营地。维里副队长肩负着维护当地秩序的重任，他意识到，如果没有志愿者的协助，当地卫兵无法抽调出足够的人手来巡视山谷的每一个角落。"},{t="深红徽记",b="这些亡命之徒与普通强盗的不同之处在于他们的协调性和统一的装束。他们自称为迪菲亚潜行者，并以戴在脸上的独特红色粗麻面罩来表明效忠。通过命令新兵猎杀这些强盗并取回他们的面罩，维里副队长旨在遏制他们的嚣张气焰，同时清查迪菲亚势力到底渗透到了王国的中心地带有多深。"}},faq={{q="迪菲亚潜行者是谁？",a="迪菲亚潜行者是一个有组织的强盗和亡命徒派系，目前活跃在艾尔文森林和西部荒野。虽然北郡当局起初只把他们看作是胆大妄为的窃贼，但他们戴着统一的红色粗麻面罩，并遵循着协同一致的领导。",al={"谁是迪菲亚","什么是迪菲亚潜行者","迪菲亚背景知识"}},{q="为什么维里副队长要请求新兵的帮助，而不是动用暴风城军队？",a="暴风城军队和当地的城市卫兵在王国各地人手吃紧。随着邻近地区的动荡加剧，暴风城内的领导层也倍感压力，当地副队长必须依靠热心的志愿者和新手新兵来清除入侵的强盗。",al={"为什么维里副队长需要帮助","暴风城卫兵在哪里","为什么不动用军队"}},{q="这些窃贼从哪里来？",a="在北郡，窃贼们聚集在修道院东侧的河对岸，潜伏在当地农场和葡萄园附近的营地边缘。",al={"强盗在哪里","北郡的迪菲亚位置"}},{q="为什么窃贼要戴红色粗麻面罩？",a="红色粗麻面罩是迪菲亚潜行者的统一徽章，既掩盖了他们的身份，又向在人类领地活动的同伙表明了效忠。",al={"为什么戴红色面罩","红色面罩的含义","红色粗麻"}},{q="完成这个任务后会发生什么？",a="维里副队长和当地人很快意识到，强盗的威胁已经蔓延到北郡更深处，导致新兵不得不协助Milly Osworth处理她被毁的庄稼，并追踪一个名叫Garrick Padfoot的特定头目。",al={"what comes next","盗贼兄弟会之后"}},{q="维里副队长知道谁在领导迪菲亚吗？",a="目前，Willem还不了解该组织的全部规模。他只知道他们自称为迪菲亚潜行者，并怀疑他们在修道院附近的出现对暴风城来说是一个不祥之兆。",al={"willem知道vancleef吗","谁在北郡领导迪菲亚"}}},fp="22,214,21.447.0,17.338.0,31.242.0,82.245.0,36.142.0,44.179.0,41.204.0,45.205.0"}
P.entries["quest:180"] = {n="通缉：范高雷中尉",s="“通缉：范高雷中尉”是所罗门镇长在湖畔镇张贴的一份悬赏令。它号召冒险者前去猎杀范高雷中尉，这位残暴的暗皮豺狼人首领正不断蚕食赤脊山。除掉他将直接重创那些豺狼人所效忠的叛变法师摩根斯。",h="“通缉：范高雷中尉”是所罗门镇长在湖畔镇张贴的一份悬赏令。它号召冒险者前去猎杀范高雷中尉，这位残暴的暗皮豺狼人首领正不断蚕食赤脊山。除掉他将直接重创那些豺狼人所效忠的叛变法师摩根斯。",kw={"范高雷","豺狼人","湖畔镇","范高雷中尉","所罗门镇长","摩根斯","赤脊山","暗皮"},ang={["faction:Alliance"]="湖畔镇是联盟在赤脊山的重要堡垒；铲除范高雷可以防止该定居点陷入彻底的孤立状态。",["race:Human"]="赤脊山的人类守卫直接感受到了被暴风城忽视的苦果，这使得针对豺狼人首领的私人干预成为了事关家园存亡的问题。"},sec={{t="被围困的城镇",b="湖畔镇目前的处境十分绝望。由于暴风城的军队兵力捉襟见肘，而瓦里安·乌瑞恩国王又离奇失踪，伯瓦尔·弗塔根公爵只能让赤脊山这样的边境定居点自生自灭。暗皮氏族变得越来越猖狂，它们劫掠贸易路线，焚烧农场，并步步紧逼城镇的外围防线。所罗门镇长只能依靠发布悬赏令，招募那些正规军无法触及的雇佣兵来解决问题。"},{t="摩根斯的副官",b="范高雷中尉不仅仅是一头四处劫掠的野兽；他实际上是潜伏在赤脊山丘陵地带的邪恶法师摩根斯的打手。在范高雷的指挥下，暗皮豺狼人不再像散沙一样的拾荒者那样战斗，而是有组织地进行袭击，威胁着要彻底切断湖畔镇与艾尔文森林之间的联系。砍下范高雷的爪子将为所罗门镇长提供证据，证明摩根斯那支野蛮的先锋部队已经被瓦解了。"}},faq={{q="范高雷中尉是谁？",a="范高雷中尉是居住在赤脊山的暗皮豺狼人氏族中一位强大的首领。他负责协调豺狼人的劫掠小队，并执行摩根斯——那名威胁着湖畔镇的黑暗法师——的意志。",al={"范高雷中尉","范高雷是谁","范高雷背景故事"}},{q="是谁发布了对范高雷中尉的悬赏？",a="这份悬赏是由湖畔镇的镇长所罗门发布的，他正试图保卫赤脊山的外围防线，抵御那些敌对的豺狼人和黑暗施法者。",al={"谁发布了悬赏","谁想要范高雷死","所罗门镇长 范高雷"}},{q="为什么暴风城不派士兵来对付这些豺狼人？",a="由于瓦里安·乌瑞恩国王的突然失踪以及国内的动荡，暴风城已陷入瘫痪。伯瓦尔·弗塔根公爵和贵族议会拒绝向湖畔镇这样的外围城镇派遣正规军部队，迫使所罗门镇长只能雇佣冒险者。",al={"为什么没有暴风城卫兵","暴风城士兵在哪里","为什么军队不帮忙"}},{q="上交悬赏需要什么证据？",a="所罗门镇长要求上交范高雷中尉被砍下的爪子，以此作为这名暗皮战将已被击杀的实物证据。",al={"范高雷 证据","范高雷的爪子","上交什么物品"}},{q="摩根斯是谁，为什么范高雷会追随他？",a="摩根斯是一名叛变的人类施法者，他在赤脊山的一座塔楼里修炼黑魔法。他通过意志控制了暗皮豺狼人，并利用范高雷中尉作为打手，在这片乡间地带散布恐怖。",al={"摩根斯是谁","为什么豺狼人听命于摩根斯","范高雷 摩根斯"}},{q="什么是暗皮豺狼人？",a="暗皮氏族是一群凶残的豺狼人部落，居住在赤脊山的岩壁和森林中。它们以极具攻击性和残忍的伏击战术而闻名，多年来一直困扰着湖畔镇的定居者。",al={"暗皮氏族","赤脊山豺狼人","暗皮背景故事"}}},fp="26,333,18.465.0,21.441.0,26.209.0,45.174.0,57.282.0,43.127.0,48.222.0,31.219.0"}
P.entries["quest:1801"] = {n="阴谋之书",s="此任务要求部落术士踏上一段旅程，从贫瘠之地的斯坦哈德·法尔杉的营地前往幽暗城，以寻找古老的恶魔学知识。为了召唤并奴役地狱犬，新晋术士必须追踪并找回遗失的《卡巴尔之书》，首先要找到一位名叫约拉·安尼森的制图师。这是掌握更高级恶魔召唤术的关键一步。",h="此任务要求部落术士踏上一段旅程，从贫瘠之地的斯坦哈德·法尔杉的营地前往幽暗城，以寻找古老的恶魔学知识。为了召唤并奴役地狱犬，新晋术士必须追踪并找回遗失的《卡巴尔之书》，首先要找到一位名叫约拉·安尼森的制图师。这是掌握更高...",kw={"贫瘠之地","地狱犬","约拉·安尼森","棘齿城","斯坦哈德·法尔杉","卡巴尔之书","幽暗城","术士任务"},ang={["class:Warlock"]="这是寻求驯服地狱犬的部落术士必经的成人礼，要求在卡利姆多和东部王国之间旅行，以收集被遗忘的仪式组件。",["faction:Horde"]="该任务展示了卡利姆多的黑暗施法者与居住在洛丹伦废墟下方的被遗忘者神秘学者之间的合作。"},sec={{t="寻觅古代知识",b="召唤地狱犬绝非普通的邪能魔法戏法；这种掠食性野兽会吞噬魔法能量，并抵御标准的召唤法阵。斯坦哈德·法尔杉解释说，为了将其引出，新晋术士需要借助专门的法阵以及一本名为《卡巴尔之书》的古老法术书。该书由第一批在没有任何外界帮助下奴役地狱犬的术士组织所著，书中记载了奴役这种危险恶魔所需的精确仪式和印记。"},{t="幽暗城的制图师",b="由于《卡巴尔之书》的副本在卡利姆多的术士中早已遗失，斯坦哈德指引他的学生跨越海洋，前往幽暗城寻找约拉·安尼森。尽管安尼森名义上是绘制洛丹伦地图的皇家制图师，但他对古老而晦涩的文献拥有极深的造诣。正如安尼森自己所承认的那样，他鄙视简单的制图工作，反而更渴望研究稀有的历史、神秘传说以及黑暗魔法的论文。"}},faq={{q="什么是《卡巴尔之书》？",a="《卡巴尔之书》是一本稀有的神秘学法术书，由第一批在没有任何外界帮助下成功召唤并奴役地狱犬的术士所著。它包含了将这种吞噬魔法的野兽安全带入艾泽拉斯所需的精确指令、结界和仪式。",al={"卡巴尔之书背景","这是什么书","卡巴尔之书"}},{q="为什么斯坦哈德·法尔杉要派你去幽暗城？",a="斯坦哈德和他在贫瘠之地的侍僧们缺少《卡巴尔之书》的副本。他知道幽暗城的制图师约拉·安尼森是一位稀有和古籍专家，或许知道在哪里可以寻回这些遗失的书页或卷册。",al={"为什么要前往幽暗城","斯坦哈德·法尔杉 幽暗城","为什么要见约拉"}},{q="谁是约拉·安尼森？",a="约拉·安尼森是一位在幽暗城工作的被遗忘者学者。虽然他的官方职业是制图和绘图，但他真正的热情在于晦涩的文献、死灵法术论文和古代文学。",al={"谁是约拉","约拉·安尼森背景"}},{q="为什么召唤地狱犬需要特殊的书籍？",a="地狱犬天生以奥术和魔法能量为食，这使得它们难以通过普通的恶魔召唤法阵来引导，且极其危险。《卡巴尔之书》详细记载了在它们吞噬召唤者之前奴役它们所必需的特殊防护措施。",al={"为什么地狱犬需要书籍","为什么召唤地狱犬很难"}}},fx={["9f4798be"]={q="斯坦哈德·法尔杉为什么要你完成这件事？",a="斯坦哈德·法尔杉负责指导你成长为一名有望驾驭更强大恶魔力量的术士。召唤并奴役地狱猎犬是一场危险的成人礼，考验术士能否掌控这种专以原始魔法精华为食的生物。斯坦哈德愿意派出他的助手，并提供魔法阵协助束缚仪式，但你必须先取得召唤所需的古老知识。",al={"斯坦哈德·法尔杉的动机","斯坦哈德为什么帮忙","斯坦哈德的理由"}},["5aabed1a"]={q="斯坦哈德·法尔杉为什么派你去，而不是亲自前往？",a="这场试炼完全由你亲自证明自己。术士必须展现应变能力、坚韧和对黑暗法术的掌控，才能束缚地狱猎犬这样危险的野兽。斯坦哈德和他的助手还必须留在棘齿城上方的召唤法阵旁，准备好复杂的结界和仪式，等你带着找回的书卷回来。",al={"为什么派我去","斯坦哈德为什么不亲自去","为什么必须去幽暗城"}}},fp="17,352,28.467.0,29.487.0,30.273.0,50.237.0,21.209.0,51.254.0"}
P.entries["quest:1802"] = {n="阴谋之书",s="此任务要求联盟术士追踪并找回被称为“恶魔契约之书”的奇异法典的两半残页。从遥远的大陆寻回这些丢失的书页，对于破译束缚地狱猎犬所需的黑暗仪式至关重要。",h="此任务要求联盟术士追踪并找回被称为“恶魔契约之书”的奇异法典的两半残页。从遥远的大陆寻回这些丢失的书页，对于破译束缚地狱猎犬所需的黑暗仪式至关重要。",kw={"碧玉矿洞","地狱猎犬","铁炉堡","克罗姆·粗臂","发霉的书籍","裂蹄堡","斯坦哈德·法尔杉","破损的手稿","恶魔契约之书"},ang={["class:Warlock"]="找回这本法典被撕裂的两半标志着成人礼的开始，它将开启从虚空中引出地狱猎犬并将其奴役所需的关键召唤仪式。",["faction:Alliance"]="联盟的施法者们依靠像克罗姆·粗臂这样的铁炉堡联络人来追踪跨越大陆的稀有恶魔遗物，以免引起教会或王室的公开怀疑。"},sec={{t="分裂的法典",b="“恶魔契约之书”仅存世一本，其动荡的历史注定了它无法保持完整。它被撕裂并破坏，残页散落到了世界各处。其中一部分，即那份直接从装订处撕下的破损的手稿，不知何故跨越了海洋来到了卡利姆多的崎岖峡谷中，落入了半人马氏族的手中。剩余的部分原计划通过海路从洛丹伦海岸运往卡兹莫丹，但在抵达港口前船只便沉没了。"},{t="跨越海洋与峡谷",b="重组这本法典需要经历两重险境。遗失在海中的残页被冲上了南海镇以西的希尔斯布莱德海岸，在那儿，拾荒而来的残骸和浸水的遗物被碧玉矿洞附近的海岸鱼人所攫取。与此同时，寻回那半干枯的书页需要潜入千针石林的裂蹄堡，深入半人马洞穴从一个古老的宝箱中取回手稿。只有将这两部分残页合二为一，克罗姆·粗臂才能在将古书交还给斯坦哈德·法尔杉之前对其进行查验。"}},faq={{q="什么是“恶魔契约之书”？",a="这是一本极其罕见的恶魔学法典，其中记载了术士所必需的深奥知识。其内容包含了从扭曲虚空召唤并奴役地狱猎犬所需的复杂咒语与束缚仪式。",al={"恶魔契约之书背景","这本书是什么","恶魔契约之书"}},{q="克罗姆·粗臂是谁，他为什么要这本古书？",a="克罗姆·粗臂是一位沉迷于研究稀有和遗忘典籍的铁炉堡矮人。作为交换，他愿意告诉联盟术士这些被撕裂的残页散落在何处，他唯一的要求就是在找回后让他亲自研读这些内容。",al={"克罗姆·粗臂是谁","克罗姆为什么想要这本书","铁炉堡克罗姆·粗臂"}},{q="这本书的两部分最终在哪里？",a="发霉的书籍被冲上了南海镇以西靠近碧玉矿洞的希尔斯布莱德海岸，被沿海的鱼人捡走。破损的手稿则出现在卡利姆多，位于千针石林的裂蹄堡内，被藏在半人马洞穴深处的一个破旧宝箱里。",al={"书页在哪里","书籍位置","破损的手稿位置"}},{q="为什么这本书最初会被撕裂？",a="“恶魔契约之书”仅被誊抄过一本。在其晦暗过去的某个时刻，它遭到了蓄意破坏，其中很大一部分被直接从装订处撕下并运往了卡利姆多，而其余部分则在一场前往米奈希尔港的灾难性航行中在海上遗失了。",al={"书为什么被撕裂","谁破坏了这本书"}},{q="斯坦哈德·法尔杉是谁，他与这个任务有什么关系？",a="斯坦哈德·法尔杉是一位住在贫瘠之地棘齿城附近的资深术士。他指导有志向的召唤师找回这本书，以便他们能习得在他的教导下召唤并束缚地狱猎犬所需的仪式。",al={"斯坦哈德是谁","斯坦哈德·法尔杉","斯坦哈德的联系"}},{q="为什么发霉的书籍上覆盖着海垢？",a="这本书当时正随船从洛丹伦海岸运往米奈希尔港，但船只没能抵达目的地。沉船漂流到了希尔斯布莱德海岸附近，那里潮湿、发霉的书页被碧玉矿洞附近的沿海鱼人收集了去。",al={"为什么发霉的书籍是湿的","希尔斯布莱德鱼人书籍"}}},fx={["7c4e226c"]={q="发霉的书籍是什么？",a="发霉的书籍是《黑暗教派法典》主体部分被海水浸泡后的残本。一艘驶往米奈希尔港的运输船沉没后，这本书遗失在希尔斯布莱德丘陵海岸附近。找回它，就能重新取得这部邪恶典籍的核心内容。",al={"发霉的书籍","发霉的书籍是什么","为什么要找发霉的书籍"}},aa350fa4={q="破损的手稿是什么？",a="破损的手稿是《黑暗教派法典》原本中被撕下的一部分，书籍遗失前便已被带走。它漂洋过海，最终落入千针石林的加拉克半人马手中，里面记载着补全全文所需的失传仪式。",al={"破损的手稿","破损的手稿是什么","半人马手稿"}}},fp="17,262,18.560.0,21.545.0,30.227.0,51.262.0,44.274.0,47.281.0,66.214.0,43.247.0"}
P.entries["quest:1803"] = {n="阴谋之书",s="这个任务要求部落术士为幽暗城的约拉·安尼森寻回被撕裂的古老书籍——《法术典籍》。这本魔法书曾收藏于洛丹伦王国，后来被撕成两半并散落在世界各地，最终彻底失踪。要追踪它那潮湿而破损的残页，就必须勇闯东部王国的险恶水域，以及卡利姆多的半人马领地深处。",h="这个任务要求部落术士为幽暗城的约拉·安尼森寻回被撕裂的古老书籍——《法术典籍》。这本魔法书曾收藏于洛丹伦王国，后来被撕成两半并散落在世界各地，最终彻底失踪。要追踪它那潮湿而破损的残页，就必须勇闯东部王国的险恶水域，以及卡...",kw={"加拉克","约拉·安尼森","洛丹伦","发霉的书籍","南海镇","裂蹄堡","破损的手稿","千针石林","法术典籍","术士任务"},ang={["class:Warlock"]="找回《法术典籍》是中级术士的试炼仪式，通过收集失落的洛丹伦奥术知识来扩充你的召唤法术储备。",["faction:Horde"]="追踪手稿的任务会把你带到千针石林的峡谷中，那里的部落驻军在乱风岗与当地的半人马进行着不断的战争。",["race:Undead"]="该书在王国陷落前一直保存在洛丹伦，因此对其进行回收，也是从被遗忘者生前身为人类时的遗迹中夺回神秘遗产。"},sec={{t="分裂的遗产",b="《法术典籍》曾被保存在旧洛丹伦王国的图书馆内。不知在何时，这本邪恶的魔法书被人蓄意破坏，近一半的页面被拆除，全书也被撕成了两半。剩下那部分完整的文本原计划被送往铁炉堡的矮人大厅，但命运弄人：运输船在南海镇以西的岩石海岸失事，书页被遗弃在浅滩中，在鱼人的窥视下逐渐腐烂。"},{t="散落在各大陆",b="那本被破坏的另一半典籍流落得更远。它从洛丹伦被夺走，一路向南流落到卡利姆多，最终落入了千针石林裂蹄堡深处的加拉克半人马手中。若想找回完整的文本，术士必须在希尔斯布莱德潮湿的海岸线上搜寻发霉的书籍，并潜入半人马峡谷的尘土与野蛮之中寻回破损的手稿。当这两部分残卷都被带到约拉·安尼森面前时，这本传奇的黑暗典籍便会合二为一，成为一本可供阅读的完整卷册。"}},faq={{q="什么是《法术典籍》？",a="这是一本曾收藏于洛丹伦首都的奥术与恶魔魔法书。它记载了高阶术士的仪式，但在遗失于两块不同大陆之前，它曾被人损毁并一分为二。",al={"法术典籍背景故事","这本书是什么","法术典籍"}},{q="为什么书的一部分在南海镇附近？",a="在书籍被破坏后，幸存的那部分装订本原定要转移给铁炉堡的学者。然而，运送它的船只在南海镇以西的海岸失事，导致魔法书被困在当地的鱼人之中。",al={"为什么在南海镇","发霉的书籍来源","南海镇以西海岸"}},{q="书页是如何流落到千针石林的半人马手中的？",a="大约一半的页面在洛丹伦时就被人从原书中撕下并偷运出去。通过贸易、劫掠或辗转流传，那份破损的手稿最终落入了千针石林裂蹄堡的深处，被加拉克半人马锁在箱子里。",al={"为什么半人马会有书","千针石林的残页","裂蹄堡的书"}},{q="约拉·安尼森是谁？",a="约拉·安尼森是一名位于幽暗城法术区的被遗忘者术士。他指引新晋的部落术士寻回那些被遗忘的禁忌知识，以加深他们对恶魔力量的掌控。",al={"约拉·安尼森背景","约拉是谁"}},{q="最初是谁损毁了这本书？",a="罪魁祸首的真实身份至今不明。约拉·安尼森本人也对这种破坏行为深感痛惜，并质疑究竟是谁会对这样一本拥有强大神秘力量的典籍做出如此卑劣的行径。",al={"谁撕了书","谁偷了书页","典籍破坏者"}},{q="当你带回两部分书后，约拉会如何处理？",a="在收到发霉的书籍和破损的手稿后，约拉·安尼森会将碎片拼凑成一本完整的卷册并仔细研读，为你接下来的恶魔仪式做好准备。",al={"交任务后会发生什么","修复后的典籍"}}},fx={a3cceb5d={q="约拉·安尼森为什么想要《黑暗教派法典》？",a="约拉·安尼森是一位被遗忘者术士学者，致力于发掘曾藏于洛丹伦的失落邪能知识。找回残缺的《黑暗教派法典》，能让他亲自研究其中的秘术，同时指导有前途的术士掌握危险而高深的召唤术。",al={"约拉为什么想要它","约拉·安尼森的动机","为什么要收集《黑暗教派法典》"}},["968099ef"]={q="发霉的书籍是什么？",a="发霉的书籍是原本计划运往铁炉堡的典籍残本。它在南海镇附近海岸遭遇海难后被鱼人搜走，其中保存着黑暗教派仪式至关重要的一半内容。",al={"发霉的书籍是什么","发霉的书籍背景","发霉的书籍用途"}},["2b99c3ce"]={q="破损的手稿是什么？",a="破损的手稿是《黑暗教派法典》缺失的另一半。书籍在洛丹伦遭到破坏时，这部分被撕了下来。这些被盗的书页辗转落入不明之人手中，漂洋过海来到卡利姆多，最后被锁在千针石林加拉克半人马的一只箱子里。",al={"破损的手稿是什么","破损的手稿背景","破损的手稿用途"}}},fp="17,405,16.496.0,27.563.1,30.206.0,44.241.0,62.248.0,21.210.0,43.189.0,64.204.0"}
P.entries["quest:1804"] = {n="阴谋之书",s="此任务标志着术士寻求召唤地狱犬的最后准备工作。在拼凑起破碎的《阴谋之书》后，术士必须从湿地的龙喉兽人手中收集引导之杖，并返回位于棘齿城上方、斯坦哈德·法尔杉所在的塔楼。",h="此任务标志着术士寻求召唤地狱犬的最后准备工作。在拼凑起破碎的《阴谋之书》后，术士必须从湿地的龙喉兽人手中收集引导之杖，并返回位于棘齿城上方、斯坦哈德·法尔杉所在的塔楼。",kw={"贫瘠之地","龙喉氏族","地狱犬","克罗姆·粗臂","棘齿城","引导之杖","斯坦哈德·法尔杉","阴谋之书","湿地"},ang={["class:Warlock"]="降服地狱犬是一次决定性的成人礼，将术士从简单的小鬼和虚空行者契约提升到掌握专门吞噬奥术魔法的掠食性恶魔。",["faction:Alliance"]="这个任务会让联盟的召唤者在铁炉堡、雾气缭绕的湿地和卡利姆多的中立地精港口棘齿城之间奔波。",["race:Dwarf"]="即使是黑暗艺术也依赖于铁炉堡Hall of Explorers内细致的保存技术，克罗姆·粗臂在那里将毁坏的遗物重新拼凑起来。"},sec={{t="勉强的交接",b="在铁炉堡的Hall of Explorers，克罗姆·粗臂细心地将残破且腐朽的《阴谋之书》碎片重新装订在一起。这位矮人学者不情愿地交出了这份稀有的黑暗学术资料，并在交给玩家一封来自斯坦哈德·法尔杉的新信件之前，要求玩家许诺未来会给他一份副本。书中包含了打破虚空所需的仪式，但仅靠原始的羊皮纸无法传导必要的仪式能量。"},{t="龙喉氏族的被窃圣物",b="在斯坦哈德的侍从协助绑定像地狱犬这样贪婪的恶魔之前，他们需要聚焦工具来稳定召唤出的能量。克罗姆指引术士前往湿地，那里的龙喉氏族施法者持有引导之杖。从敌对的兽人手中夺取这些聚焦物，就能提供斯坦哈德的圈子控制裂隙所必需的导管。"},{t="回到贫瘠之地",b="将重构的法术书和引导之杖送到棘齿城上方斯坦哈德的塔楼，便完成了艰巨的收集工作。随着工具到位且文本经过翻译，斯坦哈德准备开始危险的绑定仪式，测试召唤者是否有意志力来驯服这只燃烧军团的猎犬。"}},faq={{q="为什么斯坦哈德需要引导之杖？",a="召唤并绑定地狱犬对孤身一人的术士来说过于动荡，需要一个锚点。斯坦哈德的侍从必须在仪式期间维持并集中召唤法阵，而这些权杖可以引导并稳定必要的能量，防止传送门崩溃或失控。",al={"为什么需要引导之杖","引导之杖的作用","权杖的用途"}},{q="在哪里可以找到引导之杖？",a="这些权杖由居住在湿地的龙喉氏族兽人施法者持有，特别是在他们占据的沼泽和废墟周围。",al={"引导之杖获取地点","谁掉落引导之杖","引导之杖位置"}},{q="为什么克罗姆·粗臂会参与术士仪式？",a="克罗姆·粗臂是铁炉堡的一位研究大师，具备翻译、保存并物理重构受损古代手稿的专业技能。他对稀有文物的痴迷使他修复了《阴谋之书》中受损的页面。",al={"为什么是克罗姆","为什么铁炉堡矮人帮助术士","克罗姆·粗臂 术士"}},{q="把书和权杖交给斯坦哈德后会发生什么？",a="斯坦哈德会立即使用收集到的工具，在他的塔顶开始绑定仪式，你必须亲自面对并降服被召唤出来的地狱犬。",al={"接下来会发生什么","阴谋之书3后续任务","斯坦哈德做什么"}},{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉是一位强大的术士，在贫瘠之地港口城镇棘齿城上方的悬崖上经营着一座孤塔。卡利姆多和东部王国的资深术士们都对他精通的恶魔学表示敬重。",al={"斯坦哈德·法尔杉背景","斯坦哈德是谁","棘齿城上方的人"}},{q="部落也使用《阴谋之书》吗？",a="部落术士也会进行他们自己版本的《阴谋之书》仪式，尽管他们的线索会将他们引向卡利姆多和幽暗城的不同联络人，而不是像联盟那样与铁炉堡的克罗姆·粗臂合作。",al={"部落阴谋之书","兽人做这个任务吗"}}},fx={["7a279078"]={q="为什么要在湿地猎杀龙喉氏族？",a="盘踞在湿地的龙喉氏族残部仍掌握着强大的黑暗魔法，这是他们昔日统治留下的遗产。克罗姆知道，他们的施法者持有召唤用的特殊导能节杖，可以稳固斯坦哈德的召唤法阵。要拿到这些媒介，你必须直接从敌对的兽人施法者手中夺取。",al={"为什么要对付龙喉兽人","湿地的龙喉术士","谁持有导能节杖"}}},fp="17,278,19.437.0,30.375.0,19.338.1,41.284.0,39.144.0,51.268.0,55.165.1,22.242.0,51.209.0"}
P.entries["quest:1805"] = {n="阴谋之书",s="这个任务标志着部落术士学习召唤并奴役地狱犬旅程中最后的准备阶段。在帮助约拉·安尼森修复古老的“秘法会之书”后，修习者必须前往敌对领土夺取三根通道法杖，然后将这些组件带给位于棘齿城的斯坦哈德·法尔杉。",h="这个任务标志着部落术士学习召唤并奴役地狱犬旅程中最后的准备阶段。在帮助约拉·安尼森修复古老的“秘法会之书”后，修习者必须前往敌对领土夺取三根通道法杖，然后将这些组件带给位于棘齿城的斯坦哈德·法尔杉。",kw={"怒牙营地","龙喉氏族","地狱犬","约拉·安尼森","棘齿城","导能魔棒","斯坦哈德·法尔杉","秘法会之书","湿地"},ang={["class:Warlock"]="这项试炼考验你从敌对土地获取危险仪式试剂的决心，证明你拥有知识和胆识，能将掠食性的地狱犬束缚并为你所用。",["faction:Horde"]="湿地中的龙喉叛军仍然是萨尔部落的死敌，因此暴力夺回他们的通道法杖对部落的利益来说是一次双重胜利。",["race:Orc"]="击溃湿地中龙喉氏族的流氓成员，是对部落极力想要摆脱的黑暗、不知悔改之路的一次严厉提醒。",["race:Undead"]="约拉·安尼森在幽暗城的学术工作反映了被遗忘者术士剖析禁忌奥术文献以获取实际奥术霸权的传统。"},sec={{t="翻修过的书籍的秘密",b="在幽暗城，被遗忘者学者约拉·安尼森仔细检查了寻回的“秘法会之书”残页，拼凑出其中晦涩的篇章。在对这笔罕见的知识财富感到满意的同时，约拉也传达了斯坦哈德·法尔杉发来的紧急指示。若要束缚地狱犬这种恶魔掠食者，仅有原始知识是不够的：术士必须拥有精确的能量仪器，能够将狂暴的恶魔能量汇聚到一个束缚法阵中。"},{t="冒险前往湿地",b="斯坦哈德需要三根通道法杖，这是由龙喉氏族的叛军兽人携带的特殊导管。这些龙喉兽人远离部落的核心领地，盘踞在湿地潮湿沼泽中的怒牙营地废墟里。猎杀他们需要进入被敌对氏族残党统治的争夺中领土，这些残党不仅痛恨现代部落，也像屠杀联盟探险家一样残忍。"},{t="返回棘齿城",b="拿着找回的法杖并确保“翻修过的书籍”安全，术士跨海返回棘齿城上方斯坦哈德·法尔杉的塔楼。斯坦哈德带着冷酷的满意迎接了归来的施法者。召唤仪式的组件已组装完毕，这为对抗扭曲虚空未驯服野兽的危险意志考验铺平了道路。"}},faq={{q="这个任务的目的是什么？",a="这是部落术士学习如何召唤地狱犬任务链的第三步。它要求将修复后的“秘法会之书”和三根通道法杖交给棘齿城上方的斯坦哈德·法尔杉。",al={"为什么做这个任务","任务目的","秘法会之书有什么用"}},{q="约拉·安尼森是谁？",a="约拉·安尼森是一位驻扎在幽暗城Magic Quarter的被遗忘者术士兼学者。他研究深奥的黑暗文献，通过拼凑像“秘法会之书”这样破碎的法术书来协助同行。",al={"约拉是谁","约拉·安尼森背景故事"}},{q="为什么需要通道法杖？",a="召唤并强迫地狱犬服从需要精确的形而上学控制。法杖作为聚焦导管，用于稳定和塑造召唤法阵，这样术士才能制服恶魔，而不是被它吞噬。",al={"为什么需要通道法杖","法杖用途"}},{q="这个任务中龙喉兽人在哪里？",a="龙喉氏族占据着湿地内的怒牙营地，这是一个位于卡兹莫丹、由联盟控制的领土。具体来说，他们的骸骨卫士携带了梦寐以求的通道法杖。",al={"去哪里找龙喉兽人","湿地龙喉位置","怒牙营地"}},{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉是一位与部落黑暗施法者结盟的有影响力的术士，他在贫瘠之地棘齿城地精港口上方悬崖的一座孤塔中进行研究。",al={"斯坦哈德是谁","斯坦哈德·法尔杉棘齿城"}},{q="完成这个任务后会发生什么？",a="完成这次交付直接进入“束缚”任务，斯坦哈德会指示术士绘制召唤法阵，并在魔法战斗中面对召唤出的地狱犬，从而驾驭这头野兽。",al={"what comes next","书籍任务后的下一个任务"}}},fx={["9475dbd0"]={q="约拉·安尼森为什么要帮你？",a="约拉·安尼森是幽暗城Magic Quarter的一名被遗忘者制图师。他早已读遍手头为数不多的地理书籍，正渴望获得奥术和秘法方面的读物。作为让他研究翻修过的《黑暗教派法典》的交换，他会转告斯坦哈德·法尔杉的指示，并告诉你到哪里去找训练所需的稀有导能节杖。",al={"约拉为什么帮忙","约拉·安尼森的动机","约拉想要什么"}},cff1ec65={q="龙喉兽人为什么持有导能节杖？",a="叛离的龙喉氏族在湿地各处设有据点，藏匿着施展邪恶魔法的施法者和护骨者。他们不属于如今的部落，却仍修习黑暗法术。他们使用强大的导能节杖来聚集并束缚原始魔法能量，因此其营地正是寻找斯坦哈德召唤仪式所需奥术媒介的最佳地点。",al={"湿地的龙喉兽人","谁持有导能节杖","为什么要对付龙喉兽人"}}},fp="17,320,33.453.0,25.411.0,17.365.1,34.199.0,21.231.0,34.222.0,52.199.0,22.192.0,41.191.1"}
P.entries["quest:1806"] = {n="正义试炼",s="“正义的试炼”在丹莫罗铁炉堡大门外的乔丹·斯迪威尔的熔炉处达到高潮。在从东部王国和卡利姆多各地收集到危险的组件后，圣骑士将等待铁匠打造出一把威力强大的战锤。这标志着一名学徒转变为受人认可的圣光勇士。",h="“正义的试炼”在丹莫罗铁炉堡大门外的乔丹·斯迪威尔的熔炉处达到高潮。在从东部王国和卡利姆多各地收集到危险的组件后，圣骑士将等待铁匠打造出一把威力强大的战锤。这标志着一名学徒转变为受人认可的圣光勇士。",kw={"博什·维里甘","丹莫罗","熔炉","战锤","铁炉堡","乔丹·斯迪威尔","圣骑士","正义的试炼","维里甘"},ang={["class:Paladin"]="这次试炼仪式以“维里甘之拳”作为奖励，来回馈你在遥远大地上经历的艰险旅程，这件标志性的武器致力于维护正义。",["profession:Blacksmithing"]="看着乔丹·斯迪威尔在铁砧前工作，展现了大师级的工艺是如何将神圣的使命注入原始钢铁和搜集来的材料之中的。",["race:Dwarf"]="在这里锻造出的战锤让博什·维里甘的记忆永垂不朽，他是一位受人尊敬的矮人圣骑士，体现了卡兹莫丹的坚韧。"},sec={{t="铁匠的致敬",b="铸造大师乔丹·斯迪威尔在铁炉堡大门外从事着他的手艺。虽然他承认自己对四处游历的圣骑士有一丝羡慕，但他通过自己的锤子和铁砧支持这项事业，并以此为荣。一旦收到从阴暗地穴、沉没遗迹和危险矿井中收集到的稀有材料，斯迪威尔便会履行他的承诺，锻造出一件足以匹配真正捍卫者的武器。"},{t="博什·维里甘的遗产",b="成品战锤被命名为“维里甘之拳”，以纪念博什·维里甘，他是一位受人尊敬的矮人圣骑士，也是乔丹·斯迪威尔的挚友。通过将这件神圣的武器交付到年轻勇士的手中，斯迪威尔代表他本人及他的妻子，确保了他亡友的记忆与勇气能够长存，去对抗威胁着艾泽拉斯的黑暗。"}},faq={{q="在任务的这一步会发生什么？",a="乔丹·斯迪威尔走到他的铁砧前，敲击着炽热的金属，将你在艰苦试炼中收集到的组件组装起来。在锻造工作完成后，他会回来将成品武器交给你。",al={"正义的试炼结局","乔丹锻造武器","维里甘过场动画"}},{q="博什·维里甘是谁？",a="博什·维里甘是一位受人敬仰的矮人圣骑士，也是乔丹·斯迪威尔的好友。乔丹将这把新锻造的双手法锤以他的名字命名，以纪念他对圣光的奉献。",al={"维里甘是谁","维里甘之拳命名由来","博什·维里甘"}},{q="锻造在哪里进行？",a="锻造在丹莫罗雪山中、铁炉堡雄伟的大门外进行，乔丹·斯迪威尔在那里维护着他的熔炉和铁砧。",al={"乔丹·斯迪威尔位置","熔炉在哪里","丹莫罗铁砧"}},{q="乔丹为什么需要从世界各地收集稀有材料？",a="乔丹设计了一种具有卓越平衡性和圣光共鸣的武器。为了锻造出能够承受圣骑士神圣之怒的武器，他需要稀有的矿石、木材和宝石，这些材料只能从世界各地的危险之地寻获。",al={"为什么要收集材料","正义的试炼任务组件"}},{q="乔丹·斯迪威尔会亲自上阵战斗吗？",a="乔丹·斯迪威尔是一位铁匠，而不是游荡的战士。虽然他承认有时会羡慕那些漫游于大地之上的冒险者，但他发现自己的真正目标和骄傲在于打造武器，为圣光的捍卫者们提供装备。",al={"乔丹是战士吗","乔丹·斯迪威尔战斗能力"}},{q="对圣骑士来说，获得这把战锤意味着什么？",a="获得这把战锤标志着圣骑士漫长试炼的圆满完成。它证明了持有者拥有在艾泽拉斯最危险的角落里捍卫圣光所必需的勇气、毅力和神圣信念。",al={"维里甘之拳的意义","圣骑士试炼"}}},fx={["49955bc3"]={q="乔丹·斯迪威尔为什么想要锻造这把锤子？",a="乔丹·斯迪威尔承认，看到艾泽拉斯的勇士们英勇冒险时，他心中难免有些羡慕，因为自己只是铁匠，并非冒险者。用你收集的稀有材料锻造维里甘之拳，他就能直接帮助一位圣光的守护者，以自己的重要方式为守护王国出一份力。",al={"乔丹·斯迪威尔的动机","为什么要锻造武器","乔丹为什么要锻造锤子"}}},fp="25,320,17.391.0,27.358.0,43.211.0,21.190.0,35.152.0,59.243.0,50.225.0,54.228.0"}
P.entries["quest:181"] = {n="仰望星空",s="此任务标志着维克托·安特拉斯在夜色镇组装观星设备的努力达到了最后阶段。随着望远镜主体结构搭建完毕，维克托派遣旅行者前往危险的沃古尔食人魔山，去取回他那装置急需的一枚大型镜片：一枚由食人魔扎尔克·沃所佩戴的单片眼镜。",h="此任务标志着维克托·安特拉斯在夜色镇组装观星设备的努力达到了最后阶段。随着望远镜主体结构搭建完毕，维克托派遣旅行者前往危险的沃古尔食人魔山，去取回他那装置急需的一枚大型镜片：一枚由食人魔扎尔克·沃所佩戴的单片眼镜。",kw={"考格","夜色镇","仰望星空","单片眼镜","望远镜","维克托·安特拉斯","沃古尔食人魔山","扎尔克·沃"},ang={["faction:Alliance"]="夜色镇在恐怖与野兽的威胁下艰难求生，使得维克托对天文学知识的追求成为了一种持之以恒、尽管有些古怪的平民毅力灯塔。",["profession:Engineering"]="法师和工匠们都很欣赏这种用巨大的食人魔单片眼镜来满足天文镜片焦距要求的奇思妙想。",["race:Gnome"]="该装置依赖于侏儒工艺绘制的蓝图，要求进行巧妙的现场临时改装，例如将蛮族的眼镜转化为精密的光学仪器。"},sec={{t="最后一片",b="在观星望远镜的整个建造过程中，维克托·安特拉斯一直依赖于侏儒工程师考格·格利兹斯宾纳起草的设计图。虽然铜管和坚固的支架可以搜集或利用当地材料组装，但该装置还需要一枚格外巨大的聚焦透镜。暴风城的商人们所售的普通放大镜和光学组件根本无法满足考格那宏伟设计所需的直径，这迫使维克托将目光投向了一个意想不到且危险的选择。"},{t="食人魔的目镜",b="在南部山丘的阴影下坐落着沃古尔食人魔山，那是一个挤满了敌对蛮族的营地。其中居住着扎尔克·沃，这只食人魔以佩戴着一枚大到足以用作天文台镜片的玻璃单片眼镜而闻名。深入山丘并从扎尔克·沃手中夺取这枚目镜便能满足考格的设计图纸，从而让维克托完成他的望远镜，去凝视暮色森林阴暗树冠之上的星空。"}},faq={{q="维克托·安特拉斯是谁？",a="维克托·安特拉斯是一位住在夜色镇山坡小屋里的天文学家和学者。尽管暮色森林笼罩在阴郁之中，他仍致力于完成他的天文望远镜以研究群星。",al={"维克托是谁","维克托·安特拉斯"}},{q="我在哪里可以找到扎尔克·沃？",a="扎尔克·沃居住在暮色森林南部的沃古尔食人魔山内。他在山丘的营地和洞穴网络中徘徊，需要搜寻者穿过重兵把守的食人魔领地才能找到他。",al={"扎尔克·沃的位置","食人魔在哪里","食人魔单片眼镜位置"}},{q="为什么食人魔会有一枚单片眼镜？",a="虽然食人魔并不以追求学术或精细光学仪器而闻名，但扎尔克·沃确实带着一枚超大号的单片眼镜。其不同寻常的比例使它成为该地区唯一一枚大到足以适配考格望远镜设计的镜片。",al={"为什么需要食人魔单片眼镜","食人魔单片眼镜背景"}},{q="设备完成后会发生什么？",a="拿到单片眼镜后，维克托便能将最后这枚镜片安装到位。随着望远镜完全组装完毕，维克托就可以恢复他的天文学研究，不再受下方阴沉森林地面的遮挡。",al={"望远镜已完成","任务总结"}},{q="谁设计了这个望远镜？",a="该设备的蓝图由一位名叫考格的工程师提供，他那复杂的设计需要特殊的零件、金属框架，以及一枚远比普通矮人或侏儒眼镜大得多的镜片。",al={"考格的蓝图","谁建造了望远镜"}},{q="沃古尔食人魔山独自进入安全吗？",a="不安全。沃古尔食人魔山密布着敌对的食人魔，它们经常成群结队地巡逻或守卫着狭窄的小路。深入山丘寻找扎尔克·沃对独行的旅行者来说存在巨大的危险。",al={"沃古尔难度","食人魔山安全吗"}}},fx={bbeac028={q="Zzarc'Vul是谁？",a="Zzarc'Vul是一个引人注目的食人魔，居住在暮色森林南部丘陵的沃古尔食人魔山，和同族生活在一起。与那些凶残的同伴不同，他带着一副巨大的单片眼镜，这引起了维克托·安特拉斯的注意，也使他成为这位学者完成望远镜前的最后一道障碍。",al={"zzarc'vul是谁","那个食人魔是谁","目标zzarc'vul"}},ac1c4dd0={q="维克托·安特拉斯为什么要你完成这件事？",a="维克托是一位古怪的学者，致力于根据考格的蓝图制作一套专用的观星仪器。他花了不少心血搜集精巧的零件，但设计仍缺少一块足够大的镜片，无法用来观测天穹。望远镜组装完成后，他终于能在夜色镇阴暗的环境中继续天文学研究。",al={"维克托为什么需要单片眼镜","维克托·安特拉斯的目标","仰望星空的动机"}},f331a2d2={q="食人魔的单片眼镜有什么用？",a="维克托的观星仪器蓝图需要一块尺寸异常大的光学镜片。维克托不愿在暮色森林阴暗的僻静处从头打磨镜片，于是发现食人魔扎尔克沃尔佩戴的那副超大单片眼镜，恰好有完成仪器所需的尺寸和聚焦镜片。",al={"食人魔单片眼镜的用途","为什么要找食人魔的单片眼镜","单片眼镜有什么用"}}},fp="17,312,15.508.0,19.438.1,28.210.0,27.220.0,35.226.0,42.197.0,27.202.0,42.212.0"}
P.entries["quest:1818"] = {n="迪林格尔",s="“与迪林格尔谈话”是布瑞尔发布的一项部落军事指令。恐惧之末旅店的战士训练师奥斯蒂尔·德·蒙会将身强力壮的战士派遣给村庄西端的亡灵卫兵迪林格尔，以执行一项效忠希尔瓦娜斯女士的危险战斗任务。",h="“与迪林格尔谈话”是布瑞尔发布的一项部落军事指令。恐惧之末旅店的战士训练师奥斯蒂尔·德·蒙会将身强力壮的战士派遣给村庄西端的亡灵卫兵迪林格尔，以执行一项效忠希尔瓦娜斯女士的危险战斗任务。",kw={"奥斯蒂尔·德·蒙","布瑞尔","亡灵卫兵迪林格尔","与迪林格尔谈话","提瑞斯法林地","斩杀者乌拉格","幽暗城"},ang={["class:Warrior"]="亡灵卫兵指挥官最看重纯粹的战斗毅力，因此这次派遣是对你在前线战斗能力的直接考验。",["faction:Horde"]="响应幽暗城的防御号召，巩固了卡利姆多的盟友与新融入的被遗忘者之间的跨阵营团结。",["race:Undead"]="对于新解放的被遗忘者来说，响应迪林格尔的号召是证明你对黑暗女王的奉献以及对提瑞斯法林地防御贡献的关键一步。"},sec={{t="前线的召唤",b="在布瑞尔的恐惧之末旅店中，战士训练师奥斯蒂尔·德·蒙一直在留意那些愿意为黑暗女王效力的有前途的战士。当亡灵卫兵需要人手时，德·蒙就会将那些未经过考验的冒险者从旅店中指派到前线。负责布瑞尔西侧防务的亡灵卫兵迪林格尔需要一名具备战斗能力的人来执行一项紧急任务。"},{t="忠诚的考验",b="布瑞尔正好位于提瑞斯法林地的前线，被遗忘者必须不断地证明他们的武力优势以对抗敌对威胁。迪林格尔在村庄墓地附近的哨位使他能够很好地应对当地的入侵者。对于年轻的战士来说，向迪林格尔报到不仅仅是一件简单的差事：这是对其实战能力以及对新建立的被遗忘者政权政治忠诚度的正式考验。"}},faq={{q="是谁派遣我执行这个任务的？",a="布瑞尔恐惧之末旅店的战士训练师奥斯蒂尔·德·蒙负责识别潜在的士兵，并派遣他们去协助亡灵卫兵迪林格尔。",al={"任务发布者","奥斯蒂尔·德·蒙","谁开启与迪林格尔谈话"}},{q="亡灵卫兵迪林格尔在哪里？",a="亡灵卫兵迪林格尔驻扎在提瑞斯法林地的布瑞尔西侧，靠近墓地入口处。",al={"迪林格尔位置","迪林格尔在哪里","寻找迪林格尔"}},{q="向迪林格尔报到的目的是什么？",a="迪林格尔需要一名身强力壮的勇士来执行一项战斗任务，以保卫布瑞尔并证明他们对被遗忘者事业的忠诚。",al={"为什么与迪林格尔谈话","迪林格尔目标"}},{q="迪林格尔准备了什么任务？",a="当你向亡灵卫兵迪林格尔报到后，他会指派你去追捕一个名为“斩杀者乌拉格”的危险威胁。",al={"迪林格尔想要什么","迪林格尔后续任务"}},{q="其他部落种族也能接到这个指令吗？",a="任何赢得了幽暗城官员信任的部落战士都可以接受这项任务，尽管它主要是为了评估防守提瑞斯法林地的招募人员。",al={"这是否仅限亡灵","兽人可以做这个吗"}},{q="为什么战士训练师要派我去找迪林格尔？",a="奥斯蒂尔·德·蒙在布瑞尔的恐惧之末旅店训练战士，将新晋的合格冒险者输送给需要即时战力的亡灵卫兵指挥官。",al={"为什么从幽暗城开始","奥斯蒂尔·德·蒙的角色"}}},fx={["277a5d32"]={q="奥斯蒂尔·德·蒙为什么让你去找迪林格尔？",a="奥斯蒂尔·德·蒙充当中间人，为那些寻求更高地位的新晋被遗忘者指明方向，让他们能为国度效力，施展自己的战斗才能。他把有能力的人从布瑞尔的恐惧之末旅店派往前线，交由亡灵卫兵迪林格尔指挥，确保前线定居点得到增援，同时考验你是否真正有价值，是否忠于希尔瓦娜斯女士的事业。",al={"奥斯蒂尔·德·蒙的动机","为什么派去找迪林格尔","奥斯蒂尔·德·蒙的理由"}}},fp="20,284,22.415.0,20.419.0,29.143.0,40.111.0,46.129.0,45.117.1,40.168.0,48.162.0"}
P.entries["quest:1819"] = {n="切割者奥拉格",s="“斩杀者”乌拉格是提瑞斯法林地年轻被遗忘者战士的一项成人礼。亡灵卫兵迪林格尔会指派你前去释放并处决一名被囚禁在北部陵墓中的亡灵天灾战士，以此考验你的战斗意志，并赢得亡灵卫兵的尊重。",h="“斩杀者”乌拉格是提瑞斯法林地年轻被遗忘者战士的一项成人礼。亡灵卫兵迪林格尔会指派你前去释放并处决一名被囚禁在北部陵墓中的亡灵天灾战士，以此考验你的战斗意志，并赢得亡灵卫兵的尊重。",kw={"布瑞尔","亡灵卫兵迪林格尔","迪林格尔","陵墓","天灾","颅骨石","乌拉格","斩杀者乌拉格"},ang={["class:Warrior"]="这项试炼是早期被遗忘者战士的试炼场，考验你在面对一位强大的、被精神控制的天灾勇士时的勇气。",["race:Undead"]="乌拉格的命运展现了天灾控制下恐怖的现实，揭示了那些获得自由的被遗忘者与那些思想仍受巫妖王奴役的亡灵之间悲剧性的区别。"},sec={{t="一个被束缚的天灾奴仆",b="当亡灵天灾席卷洛丹伦时，被遗忘者捕获了一名自称为“斩杀者”乌拉格的独特亡灵战士。虽然乌拉格拥有清醒且理智的头脑，但他的精神仍无法摆脱巫妖王的精神奴役。为了了解天灾军团是如何束缚自由意志的，被遗忘者将他封印在布瑞尔北部的一座陵墓下，希望能斩断他精神上的枷锁。"},{t="处刑者的试炼",b="所有试图将乌拉格从巫妖王的精神控制中解救出来的努力都以失败告终。认识到真正的自由只有通过毁灭才能实现后，亡灵卫兵迪林格尔将这名俘虏重新利用起来，作为新晋被遗忘者战士的一项战斗试炼。通过扰动墓穴外的颅骨石机关，战士可以打破保护结界，释放乌拉格，并用斧刃送他解脱。"}},faq={{q="谁是“斩杀者”乌拉格？",a="“斩杀者”乌拉格是在天灾军团入侵提瑞斯法林地期间被被遗忘者捕获的一名亡灵战士。他比较特殊，虽然保留了自由的意识和身份，但仍完全受控于巫妖王的精神命令。",al={"乌拉格背景故事","谁是乌拉格","斩杀者乌拉格的身份"}},{q="为什么乌拉格被囚禁在陵墓下？",a="被遗忘者的学者和士兵用魔法封印将他囚禁在下方，以研究巫妖王的精神控制是如何运作的。他们曾希望找到一种方法来斩断束缚他的精神链接，但实验最终失败了。",al={"为什么囚禁乌拉格","提瑞斯法陵墓囚犯"}},{q="为什么亡灵卫兵现在要处决乌拉格？",a="在承认无法打破巫妖王对乌拉格的控制后，被遗忘者认为死亡是唯一的慈悲。亡灵卫兵迪林格尔决定将这次处决作为对有抱负的战士进行战斗勇气和纪律测试的手段。",al={"为什么要杀死乌拉格","斩杀乌拉格的原因"}},{q="如何召唤乌拉格？",a="他被关押在布瑞尔正北部的一座陵墓下。与墓穴附近的颅骨石互动会解除束缚他的魔法封印，使他复苏并展开攻击。",al={"如何召唤乌拉格","乌拉格在哪里","乌拉格颅骨石"}},{q="谁指派了杀死乌拉格的任务？",a="驻守在提瑞斯法林地布瑞尔西侧道路上的亡灵卫兵迪林格尔，会专门将此任务指派给寻求进一步指导的被遗忘者战士。",al={"乌拉格任务发放者","谁派我去对付乌拉格"}},{q="打败乌拉格之后会发生什么？",a="在确认乌拉格被击败后，亡灵卫兵迪林格尔会认可你的英勇，并让你去找布瑞尔的库勒曼·法席恩，以继续你的训练。",al={"乌拉格之后","乌拉格任务后续"}}},fx={["6de55395"]={q="亡灵卫兵迪林格尔为什么让你去对付乌拉格，而不是亲自解决他？",a="亡灵卫兵迪林格尔在考验你的胆识。乌拉格并非天灾军团中无足轻重的爪牙。独自面对他，可以证明你是否具备效忠希尔瓦娜斯女士的真正战士所需的技巧、勇气和决心。迪林格尔负责守卫布瑞尔并监督你的训练；派你进入墓穴，就是让你经受战斗考验，证明你值得接受更高阶的指导。",al={"迪林格尔为什么找我","为什么不亲自杀乌拉格","为什么派玩家去对付乌拉格"}}},fp="16,280,22.455.0,23.417.0,24.233.0,44.246.0,44.236.0,21.178.0,33.174.0,36.156.0"}
P.entries["quest:182"] = {n="巨魔洞穴",s="这项任务由登山者格瑞林·白须指派，旨在派遣冒险者清除聚集在寒脊山谷南部洞穴中的霜鬃巨魔幼崽。由于铁炉堡议会正忙于应对不断升级的穴居怪危机，孤身侦察兵和志愿招募的新兵必须在巨魔建立永久据点之前处理好边境的冲突。",h="这项任务由登山者格瑞林·白须指派，旨在派遣冒险者清除聚集在寒脊山谷南部洞穴中的霜鬃巨魔幼崽。由于铁炉堡议会正忙于应对不断升级的穴居怪危机，孤身侦察兵和志愿招募的新兵必须在巨魔建立永久据点之前处理好边境的冲突。",kw={"寒脊山谷","丹莫罗","霜鬃","格瑞林·白须","穴居怪","巨魔","幼崽"},ang={["class:Hunter"]="南部洞穴周围的峭壁是年轻追踪者学习如何将敌对目标从高山峻岭中驱赶出来的严酷试炼场。",["race:Dwarf"]="对于踏入风雪的年轻铜须矮人来说，镇压霜鬃战团既是边境安全问题，也是一场古老的山脉世仇。",["race:Gnome"]="在诺莫瑞根陷落后，侏儒们在丹莫罗寻求庇护，并乐于贡献他们的智慧和武器，帮助他们的矮人东道主解除周围的威胁。"},sec={{t="寒风中的注视",b="当铁炉堡的正规军正忙于在雪原上击退石颚怪的入侵时，南方的通路也不能无人守卫。格瑞林·白须和他的兄弟塞尼尔受山脉当局委派，负责评估当地的冰霜巨魔是否对核心地带构成了直接威胁。格瑞林伫立在俯瞰冰封山谷的峭壁上，独自监视着他们的动向。"},{t="先发制人",b="格瑞林的侦察显示，当地的霜鬃氏族已开始在寒脊山谷南部的山脊沿线的一个深洞中定居。这位侦察兵认为，进行全面的军事动员会造成矮人人力资源的无谓浪费，因此他更倾向于雇佣有能力的当地志愿者来清除那些具有攻击性的幼崽。削减他们年轻的战斗人员有助于在霜鬃巨魔对附近的矮人定居点发动协同突袭之前，扰乱他们的营地。"}},faq={{q="为什么铁炉堡不派遣正规士兵来对付这些巨魔？",a="铁炉堡议会和矮人军队正忙于应对突如其来的、毁灭性的穴居怪对丹莫罗的入侵，兵力捉襟见肘。像小型巨魔战团这样的次要威胁只能由格瑞林·白须这样的侦察兵来处理，他们会雇佣独立的冒险者来解决问题。",al={"为什么没有矮人军队","卫兵在哪里","为什么雇佣冒险者"}},{q="霜鬃巨魔是什么人？",a="霜鬃氏族是丹莫罗寒冷峭壁上的本土冰霜巨魔部落。他们长期与铜须矮人敌对，并因猎场、领地和古老的山口与登山者不断发生冲突。",al={"霜鬃氏族","丹莫罗巨魔","霜鬃巨魔是谁"}},{q="巨魔洞穴在哪里？",a="洞穴位于寒脊山谷南部的山脊沿线，在格瑞林·白须的观察营地以南。",al={"巨魔洞穴位置","洞穴在哪里","幼崽在哪里"}},{q="格瑞林·白须是谁？",a="格瑞林·白须是一位驻扎在寒脊山谷的铁炉堡侦察兵。他和负责勘测丹莫罗其他区域的兄弟塞尼尔一起，追踪敌对巨魔的动向，并向矮人领袖汇报情况。",al={"格瑞林","任务发布者","白须"}},{q="为什么格瑞林专门针对霜鬃巨魔的幼崽？",a="寒脊山谷南部的营地是一个充满了年轻战士的新兴定居点。击杀他们正在成长的战斗人员，可以防止该部族变得过于强大，从而威胁到矮人的补给线。",al={"为什么要杀幼崽","为什么要针对年轻巨魔"}},{q="清除洞穴后会发生什么？",a="回来后，你会发现巨魔在夜间进行了报复，袭击了格瑞林的营地并偷走了他的个人野外日志，需要立即深入它们的巢穴进行追回。",al={"接下来发生什么","巨魔洞穴后续"}}},fx={["9e422164"]={q="格瑞林·白须为什么想要处理掉这些巨魔？",a="格瑞林和他的兄弟塞尼尔奉命前往丹莫罗各地，评估当地的霜鬃巨魔是否对王国构成严重威胁。铁炉堡的议会已经忙于应付其他地区的穴居人暴乱，格瑞林希望在事态升级成需要正规军出动的危机之前，将这股势头扼杀在萌芽之中。",al={"为什么杀巨魔","格瑞林·白须的动机","为什么清理巨魔洞穴"}}},fp="14,348,16.431.0,19.464.0,70.270.0,29.237.0,32.120.0,25.216.0,53.218.0,36.197.1"}
P.entries["quest:1820"] = {n="库勒曼",s="“与库勒曼交谈”是提瑞斯法林地的一个过渡任务，专门提供给那些证明了自己有能力对抗天灾军团的勇士。亡灵卫兵迪林格尔会指引有能力的战士从城镇广场前往当地酒馆，协助库勒曼·法席恩处理私人和阵营间的恩怨。",h="“与库勒曼交谈”是提瑞斯法林地的一个过渡任务，专门提供给那些证明了自己有能力对抗天灾军团的勇士。亡灵卫兵迪林格尔会指引有能力的战士从城镇广场前往当地酒馆，协助库勒曼·法席恩处理私人和阵营间的恩怨。",kw={"阿加曼德","布瑞尔","库勒曼·法席恩","亡灵卫兵迪林格尔","被遗忘者","丧钟镇酒馆","部落","提瑞斯法林地"},ang={["faction:Horde"]="对于那些帮助稳固洛丹伦的旅行者来说，与布瑞尔当地居民建立联系，能为他们在提瑞斯法林地的行动提供重要立足点。",["race:Undead"]="许多被遗忘者除了对黑暗女王的忠诚外，还怀有个人恩怨；库勒曼·法席恩的请求反映了个人得失与国家防卫如何在提瑞斯法交织在一起。"},sec={{t="卫兵的叮嘱",b="在协助控制了当地严重的威胁（例如安葬了像斩杀者乌拉格这样危险的天灾残余）之后，冒险者将赢得亡灵卫兵迪林格尔的个人信任。作为守卫布瑞尔道路的哨兵之一，迪林格尔会判断谁有能力处理超出常规巡逻范围的任务，并将有实力的战士引荐给那些需要专门服务的市民。"},{t="私人恩怨",b="提瑞斯法林地并非每一场冲突都是按照幽暗城的最高指挥指令进行的。在洛丹伦王国废墟上，幸存的亡灵怀着与他们所留下的土地、家庭和财富相关的深仇大恨。库勒曼·法席恩在丧钟镇酒馆中等待时机，寻找复仇的工具，以打击盘踞在阿加曼德磨坊等前定居点附近的威胁。"}},faq={{q="我在哪里可以找到库勒曼·法席恩？",a="库勒曼·法席恩在丧钟镇酒馆内等候，该酒馆位于提瑞斯法林地的布瑞尔镇东侧。",al={"库勒曼·法席恩位置","库勒曼·法席恩在哪里","寻找布瑞尔的farthing"}},{q="是谁指引你去找库勒曼的？",a="守卫布瑞尔入口道路的亡灵卫兵迪林格尔会在你证明了自己的武艺后，指引你去找库勒曼。",al={"谁给予与库勒曼交谈任务","迪林格尔任务"}},{q="库勒曼·法席恩有什么委托？",a="库勒曼正在寻找一名有能力的战斗者作为复仇工具，以对抗被遗忘者的敌人，具体事宜主要围绕旧阿加曼德的财产展开。",al={"库勒曼想要什么","库勒曼·法席恩任务"}},{q="接受此任务需要什么前提条件？",a="只有当你击败斩杀者乌拉格，向被遗忘者证明了你的忠诚和战斗技巧后，亡灵卫兵迪林格尔才会把你引荐给库勒曼。",al={"与库勒曼交谈的前置条件","乌拉格要求"}},{q="这个任务能直接提供丰厚的奖励吗？",a="这个任务只是让你在酒馆里与法席恩取得联系，开启他个人的任务线，本身并不提供大量的装备或金币。",al={"与库勒曼交谈奖励","值得做吗"}},{q="什么是丧钟镇酒馆？",a="丧钟镇酒馆是布瑞尔的中心旅店，既是聚会场所和休息点，也是当地亡灵处理私人契约的非正式中心。",al={"布瑞尔酒馆","丧钟镇酒馆"}}},fx={["75bd5c35"]={q="亡灵卫兵迪林格尔为什么要我去和库勒曼谈谈？",a="亡灵卫兵迪林格尔知道，你通过处理布瑞尔面临的威胁，证明了自己的实力，也展现了对黑暗女王的忠诚。库勒曼·法席恩有私人恩怨，需要一位能干的战士向被遗忘者的敌人复仇。迪林格尔把你介绍给他，既能确保有能力的勇士帮助同胞，也能维护整个国度的安全。",al={"为什么派去找库勒曼","迪林格尔让去找库勒曼的动机","为什么去见库勒曼·法席恩"}},["5d6ae549"]={q="亡灵卫兵迪林格尔为什么派我去，而不是亲自处理库勒曼的请求？",a="迪林格尔是一名亡灵卫兵，驻守在布瑞尔的城镇外围，负责抵御天灾军团之类的迫近威胁。他不能擅离职守，去处理当地居民的私人仇怨或私事。你已经展现出战斗能力和独立性，是直接协助库勒曼·法席恩的理想人选。",al={"为什么派我去找库勒曼","为什么不是迪林格尔去","迪林格尔为什么派你去"}}},fp="18,283,21.406.0,18.413.0,34.123.0,33.132.0,45.174.0,57.145.0,53.164.0,32.162.0"}
P.entries["quest:1821"] = {n="阿加曼德家传武器",s="库勒曼·法席恩委派冒险者去掠夺位于阿加曼德磨坊北端的阿加曼德家族墓穴。出于对他自身凡人死亡的强烈怨恨，他试图剥夺他昔日主人的传家武器，并抹去他们最后的一丝尊严。",h="库勒曼·法席恩委派冒险者去掠夺位于阿加曼德磨坊北端的阿加曼德家族墓穴。出于对他自身凡人死亡的强烈怨恨，他试图剥夺他昔日主人的传家武器，并抹去他们最后的一丝尊严。",kw={"阿加曼德家族墓穴","阿加曼德传家宝","阿加曼德磨坊","库勒曼·法席恩","传家宝武器","天灾军团","提瑞斯法林地"},ang={["class:Rogue"]="潜行越过潜伏的食尸鬼，从守卫森严的墓穴中窃取古代武器，对潜行者来说是家常便饭。",["faction:Horde"]="清理墓穴削弱了天灾军团对提瑞斯法林地北部根深蒂固的控制，使该地区对部落的旅行者来说更加安全。",["race:Undead"]="库勒曼·法席恩的苦涩任务体现了许多被遗忘者从凡人生活带入死后的挥之不去的积怨和未愈合的伤口。"},sec={{t="仆人的苦涩积怨",b="在第三次战争摧毁洛丹伦之前，库勒曼·法席恩在提瑞斯法林地的阿加曼德磨坊为富裕且有影响力的阿加曼德家族效力。无论在他们庄园陷落时发生了什么，法席恩都将自己的死亡完全归咎于他昔日的主人。如今他已作为被遗忘者被复生，他以一种怨毒的快感审视着阿加曼德家族的没落，并为这个曾经显赫的王朝沦为受巫妖王奴役的无脑走狗而感到欣喜。"},{t="亵渎墓穴",b="为了彻底根除该家族残留的威望，法席恩派遣冒险者进入坐落在磨坊北部悬崖下的阿加曼德家族墓穴。在闹鬼的石砌大厅里，躁动不安的死者与徘徊的天灾军团并肩游荡。法席恩要求夺取四件传说中的遗物——阿加曼德家传长剑、战斧、匕首和钉锤——确保他们的血脉传承被剥夺掉仅存的每一丝荣誉。"}},faq={{q="库勒曼·法席恩生前是谁？",a="在天灾军团入侵洛丹伦之前，库勒曼·法席恩是受雇于阿加曼德磨坊的一名富裕的阿加曼德家族的侍从。他在那场灾难中丧生，并将自己的死亡归咎于他的主人们，怀着一种延续到死后的强烈怨恨。",al={"谁是库勒曼·法席恩","库勒曼的背景故事","法席恩的历史"}},{q="库勒曼·法席恩为什么想要这些传家宝？",a="法席恩寻求对他昔日主人的彻底复仇。通过从家族陵墓中掠夺他们的家传长剑、战斧、匕首和钉锤，他旨在剥夺这个没落家族最后的荣誉和记忆痕迹。",al={"为什么要偷走传家宝","库勒曼的动机","为什么要拿走武器"}},{q="阿加曼德家族发生了什么事？",a="当天灾军团横扫提瑞斯法林地时，阿加曼德家族覆灭了。他们并未在死亡中得到安息，而是被复生为受巫妖王意志束缚的无脑亡灵奴仆，游荡在他们破败的磨坊和墓穴中。",al={"阿加曼德的命运","阿加曼德家族还活着吗","阿加曼德家族现在是什么"}},{q="阿加曼德家族墓穴位于何处？",a="该墓穴位于阿加曼德磨坊的北端，坐落在俯瞰提瑞斯法林地北部枯萎农田的岩石悬崖中。",al={"墓穴位置","墓穴在哪里","阿加曼德墓穴地图"}},{q="墓穴中保存着什么武器？",a="墓穴中存放着该血脉的四件独特的传家武器：阿加曼德家传长剑、阿加曼德家传战斧、阿加曼德家传匕首和阿加曼德家传钉锤。",al={"哪些传家宝","四件传家宝","阿加曼德武器"}},{q="如果阿加曼德家族和被遗忘者都是亡灵，为什么被遗忘者还要攻击他们？",a="被遗忘者拥有自由意志并为自身的生存而战，而亡灵化的阿加曼德家族成员依然是天灾军团的无脑奴隶，服务于被被遗忘者所憎恨的巫妖王。",al={"亡灵对战亡灵","为什么要和阿加曼德家族作战","被遗忘者与天灾军团的冲突"}}},fx={c3afbf3e={q="库勒曼·法席恩会如何处置阿加曼德家族的传家宝？",a="对库勒曼·法席恩而言，那四件武器——阿加曼德家传长剑、斧头、匕首和钉锤——象征着他昔日主人的骄傲与血脉留下的最后遗物。亵渎他们的墓穴并夺走这些武器，将彻底抹去阿加曼德家族诅咒之地残存的荣誉与记忆，也宣告这个家族已彻底不复存在。",al={"阿加曼德家族传家宝的用途","这些传家宝有什么用","阿加曼德家族武器的用途"}},c1f9d064={q="谁在守卫阿加曼德家族墓穴？",a="墓穴及其周围的磨坊里挤满了没有心智的天灾军团爪牙，其中包括阿加曼德家族被重新唤起的遗骸。这些亡灵受巫妖王意志驱使，不像有自主意识的被遗忘者；它们潜伏在祖先的黑暗墓穴中，凶狠地守护着家族遗物，不让任何入侵者靠近。",al={"阿加曼德墓穴里的敌人","谁在保护传家宝","阿加曼德家族墓穴里的怪物"}}},fp="17,272,25.468.0,21.443.0,33.266.0,45.219.0,36.230.0,42.144.0,39.181.0,63.180.0"}
P.entries["quest:1824"] = {n="巨人旷野的试炼",s="“巨人旷野的试炼”是鲁迦·狂暴图腾在陶拉祖营地发布的一项战士试炼任务。作为训练的一部分，武学渴求者会被派遣到南方的巨人旷野，去消灭蜂拥而至的外来虫群。候选者必须采集几根仍然在抽动的触须，并在这些生物学证据失去活性之前赶回去。",h="“巨人旷野的试炼”是鲁迦·狂暴图腾在陶拉祖营地发布的一项战士试炼任务。作为训练的一部分，武学渴求者会被派遣到南方的巨人旷野，去消灭蜂拥而至的外来虫群。候选者必须采集几根仍然在抽动的触须，并在这些生物学证据失去活性之前赶回...",kw={"贫瘠之地","陶拉祖营地","巨人旷野","鲁迦·狂暴图腾","其拉虫","颤抖的触角","战士试炼"},ang={["class:Warrior"]="这场试炼是二十级左右战士的重要成人礼，旨在考验战士在严格的时间限制下迅速清理蜂拥而至的敌人的能力，以及保持体力耐力的水平。",["faction:Horde"]="部落一直警惕着南贫瘠之地不断扩张的其拉虫威胁，并将个人的训练试炼视为针对这种蔓延威胁的前线侦察手段。",["race:Tauren"]="对于牛头人保卫者来说，净化被亵渎的巨人旷野有助于保护陶拉祖营地周边的猎场，使其免受这种非自然的入侵巢穴的侵害。"},sec={{t="速度与钢铁的试炼",b="部落的战士训练师很少仅仅因为武艺出众就认可他人，他们还需要考验战士的坚韧和紧迫感。鲁迦·狂暴图腾在陶拉祖营地向正在成长的战士发起挑战，要求他们面对陌生的敌人证明自己。候选者不仅要奉命击杀这些入侵的生物，还必须切下新鲜的触须，并在半小时内回到陶拉祖，赶在采集到的组织停止抽动之前，这就要求战士必须快速穿越南贫瘠之地。"},{t="不受欢迎的入侵者",b="试炼的目标是盘踞在巨人旷野、依偎在巨大的化石肋骨下的其拉虫群巢穴。这些爬行的甲壳类昆虫是最近才来到贫瘠之地的，搅扰了守护着稀树草原的牛头人猎手和萨满祭司。鲁迦忧虑地指出，它们的存在对卡利姆多来说是一个不祥之兆，因此这场灭绝试炼具有双重目的：既能证明年轻战士的战斗本能，也能收集关于这种潜在生态威胁的情报。"}},faq={{q="为什么触须有时限？",a="鲁迦·狂暴图腾要求触须带回陶拉祖营地时仍然在抽动，因此战士只有三十分钟来完成狩猎并赶回。这种生物学上的新鲜度确保了候选者是通过直接战斗迅速击杀了其拉虫，而不是从尸体上搜刮来的。",al={"为什么有时限","抽动触须计时器","多少时间"}},{q="巨人旷野住着什么生物？",a="巨人旷野被其拉虫占据了，这是一种古怪且极具攻击性的穴居昆虫。它们在古老的化石下挖掘了巨大的土丘和巢穴，干扰了当地的生态系统，令部落感到不安。",al={"这些虫子是什么","巨人旷野怪物","什么是其拉虫"}},{q="鲁迦·狂暴图腾是谁？",a="鲁迦·狂暴图腾是一位驻扎在南贫瘠之地陶拉祖营地的牛头人战士训练师。他负责监督那些旨在考验部落战士技巧、坚韧和速度的试炼，以帮助他们提升地位。",al={"鲁迦","谁发布任务","鲁迦·狂暴图腾背景故事"}},{q="巨人旷野在哪里？",a="巨人旷野位于陶拉祖营地正南方，在通往千针石林的南方山口之前的道路两侧。那里耸立着巨大的骨架肋骨和其拉虫土丘，非常容易辨认。",al={"巨人旷野在哪","巨人旷野位置","在哪找到这些虫子"}},{q="这个训练任务链接下来通向哪里？",a="在按时带回抽动的触须后，鲁迦会指引战士去寻找瑟恩格瑞姆·火眼，一位住在十字路口东面山丘上的兽人老铁匠，他将为通过试炼的战士打造一套盔甲。",al={"下一个任务","接下来做什么","战士任务链后续"}},{q="为什么牛头人对这些昆虫感到担忧？",a="其拉虫对于贫瘠之地来说是不自然的入侵者。鲁迦称它们的到来预示着这片土地将有大难，他怀疑它们激进的挖掘和扩张预示着沙地之下正酝酿着更大的危机。",al={"为什么牛头人关心这个","昆虫预兆","其拉虫威胁"}}},fx={["5312a899"]={q="鲁迦·狂暴图腾为什么要你完成这件事？",a="鲁迦·狂暴图腾借此考验你的战斗本领，作为战士训练的一部分，同时也密切留意一个新出现的威胁。最近，巨人旷野出现了奇怪的虫形生物，令当地的牛头人感到不安。鲁迦派你迅速清除它们，并在它们停止抽搐之前带回新鲜的战利品，以此考验你在野外的战斗能力、速度和耐力。",al={"鲁迦·狂暴图腾的动机","为什么要在巨人旷野接受考验","鲁迦为什么派你去"}},["2d3c0cc0"]={q="鲁迦·狂暴图腾为什么需要你，而不是营地守卫？",a="这项任务是专为鲁迦指导下的战士学徒安排的个人成年礼。营地守卫要负责保卫陶拉祖营地并巡查附近边境；而独自经受严酷考验、对抗危险的掠食者，才能证明你已准备好踏上更广阔的战士之路。",al={"为什么让我接受巨人旷野的考验","鲁迦为什么派冒险者去"}}},fp="28,361,25.458.0,19.485.0,42.297.0,43.221.0,22.208.0,37.205.0,41.226.0,47.220.0"}
P.entries["quest:1825"] = {n="和索恩格瑞姆交谈",s="这个任务引导日益强大的部落战士去寻找索恩格里姆·火眼，一位居住在贫瘠之地的著名兽人铁匠。在通过了苛刻的体能考验后，战士们将受邀锻造专属护甲，以表彰他们的英勇。该任务是连接普通战士测试与打造残酷护甲的关键桥梁。",h="这个任务引导日益强大的部落战士去寻找索恩格里姆·火眼，一位居住在贫瘠之地的著名兽人铁匠。在通过了苛刻的体能考验后，战士们将受邀锻造专属护甲，以表彰他们的英勇。该任务是连接普通战士测试与打造残酷护甲的关键桥梁。",kw={"贫瘠之地","残酷护甲","十字路口","火眼","狂暴图腾","鲁迦","索恩格里姆","战士"},ang={["class:Warrior"]="这个任务标志着一个重要的成人礼，将你从一名新手战士提升为值得拥有定制锻造护甲的公认勇士。",["faction:Horde"]="部落的护甲匠以武装他们最凶猛的防御者为荣，确保那些在边境作战的战士所穿的装备能够匹配他们的战场功勋。",["profession:Blacksmithing"]="索恩格里姆·火眼代表了传统的兽人锻造理念，即大师级的护甲必须通过武力试炼而非仅仅通过金钱来获得。"},sec={{t="铁匠的召唤",b="在巨人旷野的试炼中证明了自己对抗其拉虫人的实力后，部落战士从鲁迦·狂暴图腾那里获得的不仅仅是简单的赞扬。他们坚韧与武艺的消息很快传到了索恩格里姆·火眼耳中，这是一位居住在十字路口以东山脊营地里的著名兽人铁匠。索恩格里姆认定他们是值得自己出手打造装备的战士，于是传话表示他希望能为他们打造一套非凡的战斗锁甲。"},{t="大师的标准",b="索恩格里姆·火眼不会为普通士兵锻造装备。对于他这种名望的护甲匠来说，钢铁必须与带它上战场的灵魂相匹配。到达他的营地标志着战士已经超越了简单的民兵训练，并准备好承担在卡利姆多各地收集稀有锻造材料的艰巨、专业任务。"}},faq={{q="索恩格里姆·火眼是谁？",a="索恩格里姆·火眼是一位受人尊敬的兽人铁匠，他在贫瘠之地十字路口以东的一处岩石山脊上扎营。他为通过了危险试炼并证明了自己勇气的部落战士锻造量身定制、坚不可摧的护甲。",al={"索恩格里姆是谁","索恩格里姆背景故事","索恩格里姆·火眼"}},{q="为什么鲁迦·狂暴图腾要让我去找他？",a="鲁迦·狂暴图腾认可你在南贫瘠之地的其拉虫人战斗中幸存下来后，已经超越了基础试炼。他指引你去找索恩格里姆，以便这位铁匠大师能通过为你锻造一套专业护甲来奖励你为部落所做的贡献。",al={"为什么要找索恩格里姆","鲁迦派我来的原因"}},{q="我在哪里可以找到索恩格里姆的营地？",a="索恩格里姆在贫瘠之地十字路口以东的高地悬崖上扎营，俯瞰着干燥的草原。",al={"索恩格里姆在哪里","索恩格里姆位置","找到索恩格里姆·火眼"}},{q="与索恩格里姆交谈后会发生什么？",a="会见索恩格里姆将开启残酷护甲任务线，派遣战士前往遥远的土地收集坚硬的材料（如烟熏铁锭和铁锭），以制作一套定制的锁甲。",al={"索恩格里姆之后的任务","索恩格里姆想要什么"}},{q="这个任务所有职业都能接吗？",a="不。此任务及其相关的护甲链严格属于部落战士的军事训练计划。",al={"非战士职业可以做吗","这是战士专属任务吗"}},{q="这次会面前需要通过什么试炼？",a="在此任务之前，战士们必须前往南贫瘠之地完成巨人旷野的试炼，收集抽搐的其拉虫人触角以证明他们的战斗耐力。",al={"前提任务","在此之前我做了什么"}}},fx={["2df90612"]={q="鲁迦·狂暴图腾为什么派你去，而不是亲自前往？",a="鲁迦·狂暴图腾在陶拉祖营地负责训练和考验部落中崭露头角的战士。Thun'grim Firegaze听闻你在贫瘠之地的英勇事迹和历练后，特地托人来找你。鲁迦只是转达这份召唤，让你领取一套按你的身形打造的护甲。",al={"鲁迦为什么派我去","鲁迦·狂暴图腾为什么找我","鲁迦为什么需要我"}}},fp="20,365,21.455.0,19.360.0,26.226.0,39.239.0,34.116.0,43.192.0,39.124.0,44.189.0"}
P.entries["quest:183"] = {n="猎杀野猪",s="“猎野猪”是寒脊山谷的矮人猎人塔林·锐眼发布的一项早期任务。当地岩鬃野猪数量的激增使得森林变得格外危险，年轻的新兵们受命清理这些极具攻击性的野兽，以便经验丰富的猎人们可以安心追踪猎物。",h="“猎野猪”是寒脊山谷的矮人猎人塔林·锐眼发布的一项早期任务。当地岩鬃野猪数量的激增使得森林变得格外危险，年轻的新兵们受命清理这些极具攻击性的野兽，以便经验丰富的猎人们可以安心追踪猎物。",kw={"安威玛尔","猎野猪","寒脊山谷","岩鬃野猪","丹莫罗","狩猎","塔林·锐眼"},ang={["class:Hunter"]="塔林·锐眼体现了矮人对追踪这一行直截了当的态度：保持准星精准，尊重野兽，并在猎物变得过于凶猛时清理灌木丛。",["race:Dwarf"]="生活在山里意味着要与凶猛的野生动物共享这片土地。清理安威玛尔周围好斗的岩鬃野猪，是每一个走出铁炉堡的年轻矮人的成人礼。",["race:Gnome"]="对于刚从诺莫瑞根逃难而来的侏儒难民来说，面对丹莫罗凶猛的野猪是了解崎岖矮人国度生活的一种严酷且务实的入门课。"},sec={{t="拥挤的山谷",b="寒脊山谷通常是为铁炉堡年轻的山地探险者和学者们提供的一片安静、受保护的训练场。然而，在严酷的冬季气候下，野生动物常常变得躁动不安且数量过多。驻扎在安威玛尔外围的资深猎人塔林·锐眼注意到，这些好斗的小型岩鬃野猪繁殖速度过快，对任何漫步在冰雪覆盖的小径上的人都构成了真正的威胁。"},{t="守望冰雪",b="狩猎是矮人生活的基石，它不仅能提供肉食和兽皮，也是必不可少的野外生存练习。然而，当猎物变成了一种一见到人就会主动攻击的麻烦时，就必须进行清理以恢复生态平衡。通过削减山谷坡地上的岩鬃野猪数量，年轻的冒险者们不仅证明了自己的战斗准备情况，也让当地的猎人们能够在不被野兽骚扰的情况下继续进行他们的狩猎活动。"}},faq={{q="塔林·锐眼是谁？",a="塔林·锐眼是一位驻扎在寒脊山谷安威玛尔附近的矮人猎人。他整日在大雪中追踪猎物，并帮助训练新手冒险者，让他们了解清理敌对野兽的实际意义。",al={"塔林·锐眼","猎野猪任务发布者","猎野猪npc"}},{q="为什么岩鬃野猪是个大麻烦？",a="寒脊山谷中的小型岩鬃野猪数量异常庞大，且见到人就会主动发起攻击。由于数量太多，对于当地人来说，正常的出行和狩猎都变得非常危险。",al={"为什么要杀野猪","寒脊山谷野猪问题","为什么野猪很危险"}},{q="在哪里可以找到岩鬃野猪？",a="小型岩鬃野猪在寒脊山谷中，遍布安威玛尔周边的开阔雪原和稀疏的林地。",al={"野猪在哪里","岩鬃野猪位置","小型岩鬃野猪地图"}},{q="这个任务和山谷中更大的威胁有关吗？",a="没有。这与那些骚扰矮人哨所的穴居人威胁不同，这项任务仅仅是为了保持小径安全并让塔林能安心狩猎而进行的当地野生动物管理。",al={"是否有后续任务","猎野猪任务链","野猪背后的故事"}},{q="为什么岩鬃野猪适应丹莫罗的环境？",a="岩鬃野猪是体格强壮、皮糙肉厚的猪类，它们天生就能忍受丹莫罗的严寒。它们好斗的性格和锋利的獠牙使它们能够在冰冻的土地上觅食，并抵御山中的掠食者。",al={"岩鬃野猪背景知识","矮人地区的野猪","丹莫罗野生动物"}},{q="为什么塔林·锐眼不亲自猎杀这些野猪？",a="塔林指出，由于好斗的野猪数量实在太多，他原本悠闲的狩猎活动已经变得非常危险且令人不快。他招募路过安威玛尔、渴望冒险的新人们来减少猪群数量，以便他能恢复正常的追踪工作。",al={"为什么塔林需要帮助","塔林懒惰吗","为什么塔林不能自己去猎杀它们"}}},fx={aa61ef91={q="塔林·锐眼为什么想要减少小型山猪的数量？",a="塔林·锐眼认为猎杀野猪是很好的消遣，但小型山猪在寒脊山谷泛滥成灾，彻底毁了他的乐趣。它们性情凶猛、数量暴增，使他的日常活动变得危险重重，而非悠闲惬意。杀掉十几只野猪，就能让山谷恢复一些安全，让他可以安心打猎，不必总是被野猪群围攻。",al={"为什么杀野猪","塔林·锐眼的动机","塔林为什么要杀掉野猪"}},cf0c4f7e={q="什么是小型山猪？它们为什么会出现在寒脊山谷？",al={"什么是山猪","野猪为什么在这里","小型山猪的背景"}}},fp="15,279,16.412.0,17.384.0,21.214.0,38.203.0,34.120.0,57.168.0,43.215.0,49.224.0"}
P.entries["quest:1838"] = {n="野蛮护甲",s="“残暴护甲”是部落战士的成年礼，由居住在贫瘠之地北部的近乎失明的铁匠图恩格姆·火眼监制。为了打造出配得上冉冉升起的勇士的护甲，图恩格姆会派遣经验丰富的战士前往遥远的国度，搜集珍稀的试剂和奇异的熔炼材料。完成他给出的卷轴，就开启了打造整套残暴战甲的征程。",h="“残暴护甲”是部落战士的成年礼，由居住在贫瘠之地北部的近乎失明的铁匠图恩格姆·火眼监制。为了打造出配得上冉冉升起的勇士的护甲，图恩格姆会派遣经验丰富的战士前往遥远的国度，搜集珍稀的试剂和奇异的熔炼材料。完成他给出的卷轴，...",kw={"贫瘠之地","残暴护甲","残暴胸甲","燃素","蓝铜粉","烟雾铁锭","图恩格姆·火眼","战士任务"},ang={["class:Warrior"]="该任务代表了部落战士的一个决定性里程碑，证明了他们跨越多个大陆的英勇与耐力，从而获得定制的战斗护甲。",["faction:Horde"]="残暴护甲套装是部落团结的证明，它将兽人、牛头人、巨魔和被遗忘者铁匠独特的锻造传统融为了一套战斗装备。",["profession:Blacksmithing"]="图恩格姆的卷轴展示了先进的冶金炼金术，将烟铁、蓝铜粉和燃素混合在一起，提升了普通铁器的冶炼工艺。"},sec={{t="大师的召唤",b="在贫瘠之地北部崎岖的山丘上，老兽人铁匠图恩格姆·火眼正仔细聆听着战争的风声。虽然他的视力已经衰退且模糊，但他在锻造方面的声望依然无人能及。在听闻有一位战士的力量与英勇远超普通士兵的传言后，图恩格姆决定打造一套坚固耐用的锁甲，使其足以抵御卡利姆多和东部王国最残酷的冲突。"},{t="跨越大陆的搜寻",b="锻造这种等级的护甲需要的不仅仅是普通的矿石。图恩格姆在昏暗的烛光下忍受着视力模糊的痛苦，写下了一份详尽的卷轴，详细说明了锻造核心胸甲所需的组件。这项任务需要普通的精炼铁，以及潜地狗头人携带的稀有烟铁锭、远销海外的矿工开采的蓝铜粉，还有一瓶不稳定的燃素。只有愿意忍受万里远征考验的战士，才有希望看到这套护甲重获新生。"},{t="铁锤的第一击",b="交付这些稀有的补给品仅仅是图恩格姆宏大愿景的开始。在收到材料并点燃熔炉锻造残暴胸甲时，这位老铁匠意识到单凭一位工匠是无法完成如此雄心勃勃的装备制造的。打造整套护甲需要部落其他种族的专家工匠通力协作——包括牛头人头盔塑造师、巨魔护手制造师，以及跨越大陆的亡灵护腿铁匠。"}},faq={{q="图恩格姆·火眼是谁？",a="图恩格姆·火眼是一位受人尊敬的兽人铁匠老兵，居住在贫瘠之地北部的一座山丘上。尽管他的视力在衰退，但他在铁砧前的直觉依然敏锐，他为那些通过英勇事迹赢得声望的部落战士打造强力且定制的战斗锁甲。",al={"图恩格姆是谁","图恩格姆·火眼背景故事","图恩格姆的身世"}},{q="什么是“残暴护甲”？",a="“残暴护甲”是一套专为经验丰富的部落战士设计的、久负盛名的战锻锁甲。每件护甲都需要通过部落铁匠的集体专业技能来打造，并要求勇士经历危险的旅程去获取稀有的炼金试剂、提纯矿石和古老的工艺技术。",al={"什么是残暴护甲","残暴护甲套装背景","战士护甲任务线"}},{q="为什么图恩格姆需要这些不同寻常的材料？",a="普通的铁太脆，无法承受前线勇士所遭受的重击。像蓝铜粉、烟铁锭和不稳定的燃素这样的奇异试剂被用作助焊剂和回火剂，让图恩格姆能够将巨大的韧性和力量注入金属之中。",al={"为什么需要蓝铜粉","为什么需要燃素","试剂的作用是什么"}},{q="图恩格姆是独自锻造整套护甲吗？",a="不。图恩格姆自己负责打造核心的胸甲，但他会指引战士前往部落各地的同行铁匠那里——包括奥姆·石蹄、尤拉莱克和维罗拉·奈特雷——去打造配套的头盔、护手和护腿。",al={"图恩格姆是否包揽了所有制作","谁制作了残暴护甲的组件"}},{q="这个任务线接下来会通往何处？",a="完成这项试炼会直接导向残暴胸甲的锻造，同时开启前往雷霆崖、森金村和幽暗城向当地铁匠咨询，以组装其余残暴战甲的途径。",al={"残暴护甲之后是什么","残暴护甲后续"}},{q="为什么战士必须为了这些材料跋涉如此之远？",a="这场试炼既是对武力坚韧程度的考验，也是一门关于机智应变的课程。要证明自己配得上大师级的锻造护甲，战士必须穿越敌对领土、深入危险矿坑，并搜集超出普通人触及范围的组件。",al={"为什么要前往东部王国","为什么材料需求这么多"}}},fx={["31952f55"]={q="Thun'grim Firegaze为什么想要打造这套护甲？",a="Thun'grim听说了你在部落中日益增长的声望，想为你打造一套配得上你实力的护甲。对于这位年迈且几近失明的铁匠来说，为一位冉冉升起的战士打造传奇护甲，伴他踏上征途，是一种荣誉，也能证明自己的技艺。",al={"thun'grim为什么帮我","thun'grim firegaze的动机","为什么打造野蛮护甲"}},["8131a754"]={q="Thun'grim为什么要你收集材料？",a="Thun'grim是一位年迈的兽人，视力几乎完全丧失；光是写下给你的指示，他就费了好几个晚上。从遥远的矿坑和野兽身上收集危险的材料远超他的体力所及，因此需要一位身经百战的战士踏上旅程。",al={"为什么要我收集材料","为什么让我打造野蛮护甲","thun'grim为什么需要我的帮助"}}},fp="12,365,18.438.0,26.474.0,30.423.1,26.283.0,21.277.0,49.286.0,44.234.1,38.220.1,61.236.0"}
P.entries["quest:1839"] = {n="尤拉莱克和野蛮护手",s="这个任务指引着逐渐崛起的部落勇士从贫瘠之地的高处回到杜隆塔尔的海岸。受铁匠Thun'grim Firegaze的指派，你必须前往森金村寻找暗矛部族的工匠尤拉莱克，为你锻造残暴护手。",h="这个任务指引着逐渐崛起的部落勇士从贫瘠之地的高处回到杜隆塔尔的海岸。受铁匠Thun'grim Firegaze的指派，你必须前往森金村寻找暗矛部族的工匠尤拉莱克，为你锻造残暴护手。",kw={"残暴护手","暗矛部族","杜隆塔尔","森金村","贫瘠之地","thun'grim firegaze","尤拉莱克","战士"},ang={["class:Warrior"]="残暴护甲任务线代表了部落战士通往成熟的关键仪式，标志着他们向身经百战的前线勇士的蜕变。",["faction:Horde"]="贫瘠之地的兽人锻造大师与杜隆塔尔的巨魔铁匠之间的通力合作，展现了萨尔所建立的年轻联盟之间的团结协作。",["race:Troll"]="拜访尤拉莱克突显了暗矛部族通过精湛的锻造技术和灵魂调和为部落战争所作出的贡献。"},sec={{t="前往海岸的旅程",b="在贫瘠之地证明了自己的勇气并接下收集残暴护甲套装的任务后，战士们会受到Thun'grim Firegaze的指引向东进发。这位老练的兽人铁匠并没有在自己位于山顶的铁匠铺里锻造每一件装备，而是依靠散布在部落领地各处的熟练工匠。为了锻造出适合一位进阶勇士的重甲护手，他将战士们派遣到了杜隆塔尔那多岩的南岸。"},{t="洛阿之眼",b="在森金村，巨魔护甲匠尤拉莱克正在他的暗矛族人中工作。尤拉莱克并非毫无准备，他透露Thun'grim早已传信告知了你的事迹——更重要的是，洛阿神灵们亲自见证了你在战斗中的胜利。对于一位正在部落精英中争取一席之地的战士而言，精湛的工艺与灵魂的认可缺一不可。"}},faq={{q="谁发布了“尤拉莱克和残暴护手”这个任务？",a="该任务由Thun'grim Firegaze发布，他是一位受人尊敬的兽人护甲匠，位于贫瘠之地的山顶上。",al={"任务发布者","谁开启尤拉莱克和残暴护手","thun'grim firegaze任务"}},{q="我在哪里可以找到尤拉莱克？",a="尤拉莱克驻扎在森金村，该村庄位于杜隆塔尔的南海岸。",al={"尤拉莱克位置","哪里找尤拉莱克","尤拉莱克森金"}},{q="什么是残暴护甲套装？",a="残暴护甲是一套定制的锁甲，专为三十级左右、经验丰富的部落战士设计，由散布在卡利姆多各处的盟友铁匠锻造而成。",al={"残暴护甲","什么是残暴护手","战士职业护甲30级"}},{q="找到尤拉莱克后会发生什么？",a="在迎接你并认可你在战斗中的事迹后，尤拉莱克会要求你收集锻造残暴护手所需的奇异材料，首先是萨特蹄子。",al={"后续任务","与尤拉莱克交谈后","萨特蹄子任务"}},{q="为什么Thun'grim会把你送到一位巨魔护甲匠那里？",a="Thun'grim将残暴护甲套装的锻造工作分配给了部落最优秀的专业铁匠，并信任像尤拉莱克这样的暗矛工匠来制作护手。",al={"为什么找尤拉莱克","为什么去森金村","巨魔铁匠残暴护甲"}},{q="联盟玩家有与此对应的任务吗？",a="联盟战士也会进行类似的武力试炼来锻造他们自己的职业专属护甲，但残暴护甲任务线和尤拉莱克的工艺是部落独有的。",al={"联盟残暴护手","联盟对应任务"}}},fx={a664db53={q="Thun'grim Firegaze为什么要你前往森金村？",a="Thun'grim Firegaze正在引导你成长为一名崭露头角的部落战士。在他监督你的训练时，锻造野蛮护甲这门古老技艺还需要部落各地其他工匠的专长。森金村的尤拉莱克是一位技艺精湛、通晓灵魂之力的暗矛护甲匠，适合打造这副护手。Thun'grim派你亲自前往，不只是为了委托打造护甲，也是为了证明你的投入，并亲自赢得这位护甲匠的信任。",al={"为什么让我去找尤拉莱克","thun'grim为什么不能打造护手","为什么派战士去杜隆塔尔"}}},fp="33,247,22.422.0,19.383.0,54.108.0,26.87.0,29.169.0,37.185.0,50.160.0,53.176.0"}
P.entries["quest:184"] = {n="法布隆的地契",s="法布隆的地契是艾尔文森林里的迪菲亚潜行者劫走的一份土地所有权证明。将这份文件归还给西部荒野边界附近的流离失所的农夫法布隆，是这对正在逃难的夫妇有朝一日能够收回被窃家园的唯一希望。",h="法布隆的地契是艾尔文森林里的迪菲亚潜行者劫走的一份土地所有权证明。将这份文件归还给西部荒野边界附近的流离失所的农夫法布隆，是这对正在逃难的夫妇有朝一日能够收回被窃家园的唯一希望。",kw={"迪菲亚","艾尔文","法布隆","西奥多·法布隆","弗娜·法布隆","西部荒野","西部荒野地契"},ang={["class:Paladin"]="将不慎遗失的地契归还给穷困潦倒的难民，体现了保护弱小、为无法无天的边境地区带来正义的神圣誓言。",["faction:Alliance"]="法布隆一家的困境凸显了暴风城王室未能保护首都坚固城墙之外的纳税公民。"},sec={{t="被窃文件上的线索",b="在艾尔文森林与迪菲亚强盗交战时，旅行者经常能找回一张由西奥多·法布隆和弗娜·法布隆签署的皱巴巴的土地契据。在羊皮纸的背面，潦草的字迹揭露了强盗们的阴谋：他们强行将这位年迈的农夫从他的土地上赶走，并将这份文件偷运过河进入艾尔文，用作伪造其他被抢占土地地契的模板。这些涂鸦还记录道，有人看到法布隆夫妇被困在边界那边的路边，因为马车坏了而动弹不得。"},{t="西部荒野农民的困境",b="法布隆一家的损失是笼罩西部荒野的悲剧的缩影。随着暴风城军队的缺席和王国资源的匮乏，迪菲亚潜行者已经驱逐了数十个家庭离开他们祖祖辈辈耕耘的土地，利用武力和法律手段巩固了他们对这个王国粮仓的控制。虽然西奥多和弗娜为了自身安全不得不放弃农场，但保留这张合法的地契，让他们在西部荒野恢复秩序后，拥有了对抗那些不法之徒、收回土地的唯一凭证。"}},faq={{q="我可以在哪里找到这份地契？",a="这份地契会从潜伏在艾尔文森林南部和西部各处的迪菲亚潜行者成员身上掉落，例如杰罗德码头附近或藏身于当地营地中的那些敌人。",al={"地契掉落","如何获取法布隆的地契","地契在哪里掉落"}},{q="农夫法布隆在哪里？",a="农夫法布隆和他的妻子弗娜被困在刚跨过艾尔文森林西侧桥梁，进入西部荒野后的大路旁，他们的马车坏在那里。",al={"法布隆的位置","去哪里交还法布隆的地契","农夫在哪里"}},{q="迪菲亚潜行者当初为什么想要这份地契？",a="背面的一张字条显示，强盗们打算利用法布隆这份合法的地契作为模板，在该地区伪造其他房产的所有权证明，通过伪造的文件来巩固他们对被抢农场的控制。",al={"强盗为什么要偷地契","迪菲亚为什么想要地契"}},{q="法布隆夫妇会回到他们的农场吗？",a="短时间内不会。由于无法无天的局势和强盗的袭击，这对夫妇正在逃离该地区。然而，手里拿着地契能确保如果西部荒野日后恢复和平，他们可以合法地收回自己的土地。",al={"法布隆夫妇会回家吗","法布隆的农场会怎样"}},{q="为什么暴风城不保护这些农场？",a="暴风城因瓦里安·乌瑞恩国王的突然失踪和国内的政治紧张局势而陷入瘫痪。随着王室资源集中在首都，西部荒野这样的外围领土只能靠自己来抵御日益猖獗的迪菲亚潜行者。",al={"为什么西部荒野没有卫兵","为什么暴风城无视西部荒野"}},{q="这个任务中艾尔文森林和西部荒野有什么联系？",a="该任务起到了引导作用，将冒险者从艾尔文森林引向河对岸的西部荒野，展示了迪菲亚的势力网已经渗透到了王国的核心区域。",al={"为什么地契会在艾尔文森林","区域间的联系"}}},fp="15,214,22.371.0,32.368.0,26.131.0,25.172.0,52.176.0,42.168.0,43.239.0,65.148.0"}
P.entries["quest:1840"] = {n="奥姆·石蹄和野蛮头盔",s="这个任务引导刚崭露头角的部落战士前往雷霆崖，向武器铸造大师奥姆·石蹄咨询。在森·怒火的推荐下，奥姆掌握了锻造野蛮头盔所需的专业技艺。",h="这个任务引导刚崭露头角的部落战士前往雷霆崖，向武器铸造大师奥姆·石蹄咨询。在森·怒火的推荐下，奥姆掌握了锻造野蛮头盔所需的专业技艺。",kw={"护甲任务","野蛮头盔","奥姆·石蹄","森·怒火","雷霆崖","战士"},ang={["class:Warrior"]="此任务标志着向重型头部防护装备的过渡，将战士引荐给了部落最顶尖的大师级铁匠之一。",["faction:Horde"]="该任务展示了贫瘠之地的兽人武器大师与雷霆崖之巅的牛头人工匠之间的精诚合作。"},sec={{t="钢铁推荐信",b="在证明了自己的勇气并收集了贫瘠之地野蛮护甲的组件后，战士们被指引前往更高处的台地城市雷霆崖。森·怒火本人也是一位卓有成就的护甲匠，他自知能力有限，便将自己的勇士推荐给了奥姆·石蹄。奥姆的技艺在卡利姆多久负盛名，尤其是他能将稀有而凶猛的战利品铸造成坚韧战场头盔的能力。"},{t="池畔的匠人",b="奥姆在莫高雷的高耸台地上安家立业，就在城市中央高耸的图腾下，静谧的水池旁。当战士带着森·怒火的消息抵达时，奥姆会放下手中的常规工作，商讨铸造真正配得上部落前线勇士的头盔所必需的繁琐材料。"}},faq={{q="谁是奥姆·石蹄？",a="奥姆·石蹄是一位居住在雷霆崖的牛头人护甲匠。他以精湛的技艺闻名，专门协助那些由森·怒火派遣来的战士锻造特制的战斗头盔。",al={"奥姆·石蹄","谁是奥姆"}},{q="在哪里可以找到奥姆·石蹄？",a="他位于雷霆崖的中心地带，站在城市巨大的中央图腾附近的水池边。",al={"奥姆在哪里","奥姆·石蹄位置","寻找奥姆"}},{q="为什么森·怒火会让你前往雷霆崖？",a="虽然森·怒火能够锻造野蛮套装的胸甲和其他部件，但他承认奥姆·石蹄拥有铸造野蛮头盔所需的精准专业知识。",al={"为什么去雷霆崖","为什么找奥姆"}},{q="什么是野蛮头盔？",a="野蛮头盔是一件标志性的头部装备，是为达到老兵级别的部落战士所锻造的。它需要从卡利姆多各地的野兽身上搜集危险的材料。",al={"野蛮头盔任务","什么是野蛮头盔"}},{q="奥姆接下来要求什么？",a="一旦你与奥姆交谈，他会指引你收集制作头盔所需的野兽战利品，首先就是去野外猎杀奇美拉以获取奇美拉角。",al={"后续任务","奥姆·石蹄之后","奇美拉角任务"}},{q="任何职业都可以接这个任务吗？",a="不可以。这条任务线仅限于那些在武艺训练中取得了长足进步，并完成了森·怒火最初护甲任务的战士。",al={"这是战士专属吗","谁能做这个任务"}}},fx={["528c5ae8"]={q="Thun'grim Firegaze为什么要你去见奥姆·石蹄？",a="Thun'grim Firegaze一直在引导你进行战士训练，但打造一顶野蛮头盔需要技艺远胜普通锻造的工匠大师。Thun'grim知道奥姆·石蹄的金属与骨料加工技艺无人能及，于是派你去雷霆崖找这位牛头人工匠，让你获得一件配得上日渐增长的实力和对部落贡献的护甲。",al={"thun'grim firegaze的动机","为什么派去找奥姆·石蹄","thun'grim打造野蛮头盔的理由"}}},fp="33,213,24.405.0,23.328.0,21.185.0,33.119.0,54.180.0,24.168.0,27.164.1,30.146.0"}
P.entries["quest:1841"] = {n="维罗拉·奈特雷和野蛮腿甲",s="这个任务指引经验丰富的部落勇士从贫瘠之地跨越海洋，前往洛丹伦的幽暗城。在那里，被遗忘者护甲商维罗拉·奈特雷利用她生前保留的精湛手艺，打造特制的野蛮腿甲。这对于为部落的前线勇士们拼凑出一套耐用的护甲来说，是至关重要的一步。",h="这个任务指引经验丰富的部落勇士从贫瘠之地跨越海洋，前往洛丹伦的幽暗城。在那里，被遗忘者护甲商维罗拉·奈特雷利用她生前保留的精湛手艺，打造特制的野蛮腿甲。这对于为部落的前线勇士们拼凑出一套耐用的护甲来说，是至关重要的一步。",kw={"野蛮护甲","野蛮腿甲","洛丹伦","瑟格林·火眼","trade quarter","幽暗城","维罗拉·奈特雷","战士任务"},ang={["class:Warrior"]="对于等级30左右的部落战士来说，这个任务是一个重要的里程碑，它将他们的旅程从卡利姆多扩展开来，以获取职业特有的护甲。",["faction:Horde"]="野蛮护甲的任务线将年轻的部落团结在一起，迫使身处卡利姆多的兽人、巨魔和牛头人直接与东部王国的被遗忘者工匠进行协作。",["race:Undead"]="维罗拉·奈特雷展现了被遗忘者依然保留着已覆灭的洛丹伦王国那精致的文化技艺和艺术遗产。"},sec={{t="跨海之旅",b="在贫瘠之地的岗哨向老练的铁匠瑟格林·火眼证明了自己的实力后，勇士们将接到收集传说中的野蛮护甲的任务。瑟格林无法独自打造全套装备，于是指引雄心勃勃的勇士们去寻求部落中其他能工巧匠的帮助。对于护胫，他会要求勇士们向东跨越无尽之海，前往被遗忘者的地下王国，寻找一位在北方人类王国覆灭前就已声名远扬的工匠。"},{t="维罗拉·奈特雷的技艺",b="在北方天灾军团的蹂躏中丧生之前，维罗拉·奈特雷曾是洛丹伦王国最杰出的护甲商之一。尽管失去了凡人的生命，家园也遭到了腐蚀，但这并没有减损她在冶金方面的造诣。如今，她在幽暗城的贸易区从事着自己的行当，将古老的人类技艺用于协助部落的勇士，并且还会用一种冷漠而阴森的幽默感来调侃自己亡灵的身份。"}},faq={{q="维罗拉·奈特雷是谁？",a="维罗拉·奈特雷曾是洛丹伦王国最优秀的护甲商之一。在第三次战争之后，她作为被遗忘者复生，随后搬到了幽暗城的贸易区，在那里继续为部落打造装备。",al={"维罗拉·奈特雷背景故事","维罗拉是谁","被遗忘者铁匠维罗拉"}},{q="为什么瑟格林要让我去幽暗城？",a="虽然瑟格林·火眼在贫瘠之地监督你的训练，但制作整套野蛮护甲需要部落各地的专业工匠协助。他深知维罗拉在护甲制作方面无与伦比的声望，因此派遣你前往洛丹伦直接订制腿甲。",al={"为什么去幽暗城","瑟格林幽暗城任务","从贫瘠之地前往幽暗城的战士"}},{q="在幽暗城哪里可以找到维罗拉·奈特雷？",a="维罗拉·奈特雷就在幽暗城贸易区的熔炉旁工作，周围是其他为希尔瓦娜斯·风行者效力的工匠和铁匠。",al={"维罗拉·奈特雷位置","维罗拉·奈特雷在哪","找到维罗拉·奈特雷"}},{q="和维罗拉·奈特雷对话后该做什么？",a="维罗拉会要求你从湿地的龙喉氏族兽人身上收集胫骨，以便她能用这些材料为你打造野蛮腿甲。",al={"维罗拉之后的任务","龙喉胫骨任务","维罗拉需要什么"}},{q="维罗拉有关于亡灵身份的台词吗？",a="有的。在你完成旅程见到她后，她会冷冷地开个玩笑，说不知道究竟是她在为你打造护甲还是反过来，并提到她在失去嗅觉和呼吸的同时也失去了幽默感。",al={"维罗拉的玩笑","亡灵铁匠对话","维罗拉的幽默感"}},{q="野蛮护甲是战士专用的吗？",a="是的，野蛮护甲的试炼——包括寻找维罗拉·奈特雷制作腿甲——是专门为达到一定等级的部落战士所设计的进阶武技仪式。",al={"其他职业能获得野蛮护甲吗","战士专属野蛮护甲任务"}}},fx={["7eb107f7"]={q="Thun'grim Firegaze为什么要你完成这件事？",a="Thun'grim Firegaze正在帮助你打造一整套野蛮护甲，这是部落有前途的战士晋升过程中必须经历的仪式。Thun'grim自己能打造其中几件，但护腿所需的特殊工艺超出了他个人的锻造技法，因此他指引你去找维罗拉·奈特雷。她被誉为洛丹伦最优秀的护甲匠之一。",al={"thun'grim firegaze的动机","为什么打造野蛮腿甲","为什么派去找维罗拉·奈特雷"}}},fp="38,330,24.463.0,29.458.0,21.266.0,40.270.0,48.168.0,43.124.1,49.242.0,34.197.0"}
P.entries["quest:1842"] = {n="萨特之蹄",s="萨特蹄足是一项由森金村的巨魔工匠尤拉莱克发布的任务。为了打造一副强力的残酷护手，战士们必须北上前往灰谷，猎杀萨特并采集它们那因魔法而肿胀、不再分叉的蹄足。",h="萨特蹄足是一项由森金村的巨魔工匠尤拉莱克发布的任务。为了打造一副强力的残酷护手，战士们必须北上前往灰谷，猎杀萨特并采集它们那因魔法而肿胀、不再分叉的蹄足。",kw={"灰谷","残酷护手","杜隆塔尔","蹄足","萨特","森金村","尤拉莱克","未分叉"},ang={["class:Warrior"]="这项任务是战士进阶仪式的一部分，旨在考验他们在面对狡诈的恶魔伏击者时的武力韧性，以换取定制的护甲。",["faction:Horde"]="执行这次狩猎将迫使部落战士离开杜隆塔尔的干旱平原，深入到灰谷充满争议的暗夜精灵领地。",["race:Troll"]="尤拉莱克的方法展现了暗矛工艺务实的一面，通过从倒下的魔法敌人身上抽取原始精华，而非仅仅依赖传统的锻造技术。"},sec={{t="汲取腐化精华",b="为了打造出足以抗衡卡利姆多最野蛮力量的护甲，暗矛部族的工匠尤拉莱克将目光投向了寻常的铁块和皮革之外。他指引雄心勃勃的战士们北上，前往灰谷的古老森林，那里 lingering 的恶魔腐化正在当地的萨特聚集点中不断蔓延。"},{t="灰谷魔法的肿胀",b="据尤拉莱克所说，灰谷东北部的萨特通过汲取森林中潜藏的纯净能量并将其扭曲为邪恶的力量来维持自身。那些在这些借来的生命力中沉溺最深的恶魔，它们的蹄足会产生异常的肿胀，并失去原本分叉的形态。尤拉莱克打算抽取这种集中的魔法能量，并将其直接编织进他所打造的护手中。"}},faq={{q="尤拉莱克为什么需要萨特蹄足？",a="尤拉莱克需要这些蹄足来增强他正在打造的残酷护手。他打算抽取萨特从森林中吸取并腐化进它们肿胀足部里的浓缩魔法。",al={"为什么需要萨特蹄足","蹄足的用途","蹄足有什么用"}},{q="萨特在哪里？",a="它们栖息在灰谷的东北部，在那里它们盘踞在受腐化的古代遗迹之中，并靠汲取深林中的残留魔法能量为生。",al={"萨特在哪里","萨特位置","在哪里寻找萨特蹄足"}},{q="为什么未分叉的蹄足很特别？",a="蹄足不再分叉意味着这只萨特已经吞噬了过量的灰谷纯净魔法，导致它的肢体因窃取的力量而肿胀。",al={"未分叉蹄足的背景知识","为什么没有分叉","肿胀的蹄足"}},{q="尤拉莱克是谁？",a="尤拉莱克是一位居住在杜隆塔尔南部森金村的熟练暗矛巨魔护甲匠，以协助战士制造试炼装备而闻名。",al={"尤拉莱克是谁","任务发布者","森金村的巨魔"}},{q="尤拉莱克在打造什么护甲？",a="他正准备打造一副残酷护手，这是一种为崛起的部落战士准备的重型防护手部装备，灌注了窃取的魔法效力。",al={"什么是残酷护手","护手任务","奖励护甲"}},{q="这里的萨特效忠于燃烧军团吗？",a="是的。萨特是因恶魔契约而发生转化的上古暗夜精灵，卡利姆多林地中残存的聚集点仍在为恶魔力量效劳，进行着邪能腐化。",al={"萨特的效忠对象","萨特属于军团吗"}}},fx={["749a1d7b"]={q="为什么东北部灰谷会有萨特？",a="萨特盘踞在东北部灰谷，贪婪地吞噬这片古老森林的纯净之力。它们通过吸取并腐化潜藏其中的魔法，为邪恶仪式注入力量，也扭曲自己的身体。那些吞噬灰谷自然魔力最多的萨特会长出畸形、肿胀且没有分趾的蹄子，成为浓缩奥术力量的活体容器。",al={"为什么灰谷有萨特","萨特蹄子的目标背景","为了蹄子要猎杀谁"}}},fp="12,253,28.286.0,30.413.0,36.195.0,27.145.0,36.161.0,16.157.0,31.140.0,44.180.0"}
P.entries["quest:1843"] = {n="野蛮护手",s="残暴护手是老练的部落勇士所能获得的精湛工艺结晶。在从遥远的土地收集稀有材料后，工匠尤拉莱克打造了一副强大的护手，旨在为制造者和佩戴者带来荣誉。",h="残暴护手是老练的部落勇士所能获得的精湛工艺结晶。在从遥远的土地收集稀有材料后，工匠尤拉莱克打造了一副强大的护手，旨在为制造者和佩戴者带来荣誉。",kw={"护甲锻造","残暴护手","杜隆塔尔","部落","萨特蹄子","尤拉莱克","战士护甲"},ang={["class:Warrior"]="这些护手代表了一名战士向纪律严明的军事领导者的转变，是专为激烈的近战而锻造的可靠防护装备。",["faction:Horde"]="部落的工艺依赖于持久的传统和尚武的骄傲，确保勇士们将工匠的精神分量和荣誉带入战场。"},sec={{t="工匠的杰作",b="为老练的前线战士锻造盔甲不仅仅是简单的金属加工——对于部落工匠来说，这是一种精神上的事业。居住在杜隆塔尔的工匠尤拉莱克将他的血统与技艺倾注在塑造这些残暴护手之中。通过使用从危险对手身上收获的坚硬战利品，他制造出的盔甲既能抵御凶猛的打击，又能增强佩戴者的进攻能力。"},{t="先祖的荣誉",b="在兽人和巨魔的传统中，精良的武器和护甲将锻造的威望和制造者的精神带入战场。当尤拉莱克将成品护手交给战士时，他将先祖的遗产托付给了他们。戴上这些护手投入战斗的勇士，理应展现出与这精湛工艺相匹配的勇气、武艺准则和力量。"}},faq={{q="尤拉莱克是谁？",a="尤拉莱克是一位定居在杜隆塔尔的工匠，他协助部落战士获得定制的高级护甲。他要求提供稀有的材料，以确保他的锻造技艺既能光耀他的行业，又能传承他的祖先传统。",al={"尤拉莱克","谁提供残暴护手","任务发布者"}},{q="为什么要用萨特蹄子来制作这些护手？",a="萨特那肿胀的未分趾蹄中蕴含着它们从灰谷的魔法中汲取的力量。尤拉莱克将这些蹄子中的力量抽取出来并融入到他的工艺中，因此这些护手蕴含着强大的魔法。",al={"为什么需要萨特蹄子","萨特部件","所用材料"}},{q="对尤拉莱克而言，佩戴这些护手意味着什么？",a="对尤拉莱克来说，制作这些护手代表了他的巅峰之作。将它们托付给一位值得的战士，能为他的工艺和先祖带来极大的荣誉，并将他的心血直接与部落的军事胜利联系在一起。",al={"荣耀先祖","尤拉莱克的荣誉"}},{q="这项任务是在哪里进行的？",a="锻造工作在杜隆塔尔完成，这里是兽人和暗矛巨魔干旱的心脏地带，尤拉莱克会在那里检查收集到的材料并交付成品护甲。",al={"地点","在哪里交付残暴护手"}},{q="这个试炼是针对所有冒险者的吗？",a="这条道路专为那些已经证明了自己的耐力和军事奉献精神的前线战士而开辟，标志着他们向部落内更老练的战斗角色迈进。",al={"这是否仅限战士","职业要求"}},{q="收到护手之后会发生什么？",a="护手的交付标志着这项特定锻造试炼的完成，战士将装备齐全，去面对艾泽拉斯饱经战火的战场上更大的威胁。",al={"下一个任务","残暴护手后续"}}},fp="16,262,25.416.0,15.367.0,16.212.0,49.203.0,52.214.0,32.168.0,43.180.0,41.182.0"}
P.entries["quest:1844"] = {n="奇美拉之角",s="作为打造残酷之盔的勇士仪式的一部分，奥姆·石蹄指派一名有抱负的勇士前往荒芜的焦炭谷。在那里，勇士必须狩猎一只陷入疯狂的奇美拉族母，获取她那枚光滑的奇美拉角，这既是出于怜悯，也是实力的证明。",h="作为打造残酷之盔的勇士仪式的一部分，奥姆·石蹄指派一名有抱负的勇士前往荒芜的焦炭谷。在那里，勇士必须狩猎一只陷入疯狂的奇美拉族母，获取她那枚光滑的奇美拉角，这既是出于怜悯，也是实力的证明。",kw={"残酷之盔","焦炭谷","奇美拉族母","奇美拉角","光滑的奇美拉角","奥姆·石蹄","石爪山脉","雷霆崖","战士任务"},ang={["class:Warrior"]="这次试炼考验了战士在残酷环境中猎杀独行顶级野兽的能力，以赢取佩戴残酷之盔的权利。",["faction:Horde"]="以烈日石居为基地的部落战士深入石爪山脉的争夺领地，为卡利姆多的防御锻造所需的武器。",["race:Tauren"]="奥姆·石蹄以牛头人特有的敬畏之心对待战争，提醒战士们即使在暴力中，让饱受折磨的野兽摆脱苦难也是对大地母亲的致敬。"},sec={{t="决心的试炼",b="奥姆·石蹄愿意为部落的战士铸造传奇的残酷之盔，但武道传统要求穿戴者必须先证明自己的勇气。奥姆不仅需要生金属或金钱；他要求的是勇士武艺的证明，以及直面毁灭性冲突所留下的残酷创伤的意志。"},{t="焦炭谷的创伤",b="这项任务将勇士们引向石爪山脉的西南地带，进入那片被称为焦炭谷的灰烬荒原。这片山谷曾经郁郁葱葱，但如今已被焚毁，变成了一片烟雾缭绕的不毛之地。徘徊在满是煤灰的弹坑中的幸存野兽因痛苦和愤怒而扭曲，尤其是那些在枯木和炽热蒸汽喷口间筑巢的强大奇美拉。"},{t="战斗中的怜悯",b="在牛头人铁匠眼中，击杀奇美拉族母有两个目的。这不仅能获取锻造头盔所需坚硬的“光滑的奇美拉角”，还能终结这头生物的折磨。通过击倒族母，勇士既是执行者，也是仁慈的化身，为一头因家园被毁而疯狂的野兽解脱。"}},faq={{q="奥姆·石蹄是谁？",a="奥姆·石蹄是雷霆崖的一位技艺精湛的牛头人铁匠，他协助部落的老兵战士打造标志性的职业护甲，包括残酷之盔。",al={"奥姆·石蹄背景故事","谁是奥姆·石蹄","雷霆崖铁匠奥姆"}},{q="奥姆为什么要光滑的奇美拉角？",a="光滑的奇美拉角既是残酷之盔耐用的物理组件，也是勇士拥有在危险地形中追踪并击败危险顶级掠食者的勇气的实际证明。",al={"光滑的奇美拉角用途","为什么获取光滑的奇美拉角","残酷之盔的角"}},{q="石爪山脉的奇美拉是什么？",a="奇美拉是卡利姆多野外原生的巨型双头带翼野兽。幸存在焦炭谷中的奇美拉因其筑巢地的火灾与破坏而陷入了暴怒与疯狂。",al={"石爪山脉的奇美拉","奇美拉背景故事","什么是奇美拉"}},{q="这个任务如何融入战士的训练？",a="在三十级左右时，部落的战士会被指引去寻找像奥姆·石蹄这样的专家，以接受危险的考验。完成这些挑战后，他们就有资格穿戴为战场冠军设计的重型带刺的残酷护甲套装。",al={"战士残酷之盔任务链","30级战士雷霆崖任务","残酷护甲任务线"}},{q="为什么奥姆将这次狩猎描述为一种怜悯行为？",a="牛头人文化强调与大地及其生灵和谐共处。由于焦炭谷的居民因土地的荒废而处于无尽的痛苦之中，击杀族母被视为一种仁慈，让一头受苦的野兽脱离永恒的苦难，而非盲目的屠杀。",al={"为什么对族母怜悯","解脱她的痛苦"}}},fx={["3a1b9e89"]={q="光滑的奇美拉角有什么用？",a="对奥姆·石蹄来说，光滑的奇美拉角有双重用途。从实用角度看，它能提供锻造野蛮头盔所需的坚硬角质材料。从仪式角度看，它是你勇闯焦炭谷灰烬荒原、对抗发狂的奇美拉首领，并展现出战斗实力与给予她解脱的仁慈的实证。",al={"光滑的奇美拉角用途","为什么需要光滑的奇美拉角","光滑的奇美拉角与野蛮头盔"}},["241e9666"]={q="你要去焦炭谷猎杀谁？",a="你要去猎杀一头栖息在焦炭谷废墟中的奇美拉首领。这里曾是一片繁茂的高地山谷，却被烈焰彻底摧毁，幸存的野兽也因痛苦和绝望而陷入疯狂。首领曾是这片土地上威严的掠食者之一，如今却在受污染的灰烬中无尽受苦，直到你赐予她一个体面的结局。",al={"奇美拉首领目标","在焦炭谷要杀谁","奇美拉角目标"}},c3120874={q="奥姆为什么派你去，而不亲自前往？",a="奥姆·石蹄是在考验你的意志，并非让你跑一趟寻常差事。野蛮头盔是传统而强力的护甲，只有证明了决心、战斗技艺和体面地施予仁慈的能力的战士才有资格佩戴。你亲自在焦炭谷险恶的荒原上猎杀那头野兽，便能向奥姆证明自己配得上他的作品。",al={"奥姆为什么派我去","奥姆为什么不去猎杀首领","奥姆为什么需要冒险者"}}},fp="14,275,17.316.0,29.393.0,15.348.0,21.180.0,38.210.0,33.205.0,46.244.0,47.285.0"}
P.entries["quest:1845"] = {n="野蛮头盔",s="“凶蛮头盔”标志着由雷霆崖上的奥姆·石蹄所监督的一场艰苦战士试炼的终章。在收集了卡利姆多各地的稀有野兽战利品后，一位立志成为勇士的人将获得一顶令人生畏的角盔，以证明其实力。",h="“凶蛮头盔”标志着由雷霆崖上的奥姆·石蹄所监督的一场艰苦战士试炼的终章。在收集了卡利姆多各地的稀有野兽战利品后，一位立志成为勇士的人将获得一顶令人生畏的角盔，以证明其实力。",kw={"凶蛮头盔","奇美拉之角","大地母亲","猎人高地","奥姆·石蹄","雷霆崖","战士"},ang={["class:Warrior"]="这项仪式是部落战士的一个关键里程碑，标志着他们换装由凶猛野兽锻造、并经由老练教官祝福的重甲。",["faction:Horde"]="凶蛮护甲试炼确保了在部落旗帜下作战的勇士拥有其领袖所要求的原始体能和狩猎技巧。",["race:Tauren"]="这顶头盔在雷霆崖颁发，反映了牛头人将狩猎战利品在大地母亲的恩泽下打造为防御装备的传统。"},sec={{t="战士的试炼",b="奥姆·石蹄是雷霆崖的一位严厉铁匠，引导部落战士完成艰苦的成人礼。这些试炼要求战士展现出武力，深入危险的领地狩猎凶猛的生物并获得稀有战利品。只有达到奥姆严格标准的人，才能获准完成他们的盔甲。"},{t="大地母亲的馈赠",b="通过将稀有的奇美拉之角带给奥姆·石蹄，战士证明了自己在荒野中的决心。为了表彰这一点，奥姆赠予了“凶蛮头盔”——这是一件沉重而凶狠的锁甲，旨在向野兽致敬，并增强穿戴者在前线战斗中的实力。在授予头盔时，奥姆祈求大地母亲的祝福，并期待着战士未来在艾泽拉斯各地做出更伟大的事迹。"}},faq={{q="谁提供凶蛮头盔？",a="雷霆崖受人尊敬的牛头人铁匠奥姆·石蹄，会向完成他试炼的部落战士赠予凶蛮头盔。",al={"谁给予凶蛮头盔","凶蛮头盔npc","奥姆·石蹄任务"}},{q="获得该头盔前必须完成什么任务？",a="你必须完成名为“奇美拉之角”的试炼，这需要你在荒野中狩猎凶猛的野兽，并将它们的角交给雷霆崖的奥姆·石蹄。",al={"凶蛮头盔前置条件","奇美拉之角任务"}},{q="奥姆·石蹄在哪里？",a="奥姆·石蹄位于雷霆崖高耸平顶城市中央大图腾旁的水池边。",al={"奥姆·石蹄位置","奥姆·石蹄在哪里"}},{q="为什么奥姆·石蹄要祈求大地母亲？",a="作为一名牛头人，奥姆尊奉大地母亲为世界的创造者和精神守护者。他在战士完成的头盔上献上她的祝福，反映了牛头人传统的信仰，即战斗中的力量必须与精神上的敬畏保持平衡。",al={"为什么提到大地母亲","大地母亲背景知识"}},{q="这项试炼对任何冒险者开放吗？",a="不。该试炼及其奖励的凶蛮护甲是部落战士专属的，他们必须通过专门的职业任务来证明自己的实力。",al={"任何人都能获得凶蛮头盔吗","凶蛮头盔职业"}},{q="凶蛮护甲套装有何意义？",a="凶蛮护甲部件代表了一名战士从新手士兵到部落精英勇士的成长历程，它们是使用从卡利姆多最凶猛的捕食者身上收集的材料所打造的。",al={"凶蛮护甲背景知识","为什么叫凶蛮头盔"}}},fx={["3a1185bd"]={q="奥姆·石蹄为什么要把野蛮头盔奖给你？",a="奥姆·石蹄赐予你头盔，并非因为迫切需要或突发危机，而是为了表彰你在战斗技艺上的成长。你从卡利姆多各地收集稀有材料，并通过战士试炼证明了自己的实力，表明你已准备好承担身经百战的勇士所肩负的重任。奥姆赞许你的坚毅，并祈求大地母亲赐福，让这件护甲在你迎接更艰巨的战斗时保护你。",al={"奥姆为什么把头盔给你","奥姆·石蹄赠予野蛮头盔的原因","为什么要野蛮头盔"}}},fp="11,259,16.365.0,27.411.0,27.130.0,53.168.0,31.105.0,46.254.0,37.127.0,49.188.0"}
P.entries["quest:1846"] = {n="龙喉胫骨",s="“龙喉胫骨”是部落战士的一个任务，由幽暗城的护甲商维罗拉·奈特雷发布。为了打造耐用的野蛮腿甲，战士们被派往湿地南部，从敌对的龙喉兽人身上收集异常粗壮的胫骨。",h="“龙喉胫骨”是部落战士的一个任务，由幽暗城的护甲商维罗拉·奈特雷发布。为了打造耐用的野蛮腿甲，战士们被派往湿地南部，从敌对的龙喉兽人身上收集异常粗壮的胫骨。",kw={"怒牙营地","野蛮腿甲","龙喉氏族","胫骨","萨多尔大桥","幽暗城","维罗拉·奈特雷","湿地"},ang={["class:Warrior"]="这项试炼不仅考验了战士在野外的身体耐力，也考验了他们为了打造高级盔甲而收集阴森材料的意愿。",["faction:Horde"]="击溃卡兹莫丹的龙喉叛军氏族，既削弱了一个危险的旧部落残党，又增强了萨尔新联盟的勇士们的实力。",["race:Orc"]="对于效忠奥格瑞玛的兽人来说，肃清顽固不化的龙喉氏族是对他们族人邪能过去以及救赎所付出的惨痛代价的深刻提醒。",["race:Undead"]="维罗拉·奈特雷务实地利用人型生物残骸的做法，体现了被遗忘者将一切可用资源武器化的心态，无论这些资源有多么骇人。"},sec={{t="恐怖的骨架",b="锻造适合前线身经百战的战士的盔甲需要非同寻常的材料。当要求打造野蛮腿甲时，被遗忘者护甲商维罗拉·奈特雷指定需要一种由坚硬、有弹性的骨骼构成的结构支撑。她没有利用普通的野兽，而是将这些有志向的战士指向了湿地的龙喉兽人，因为他们致密的骨骼结构能提供在战斗中抵御重击所需的韧性。"},{t="测试骨髓",b="从龙喉兽人身上采集骨头只是艰巨任务的一半。维罗拉指示战士们手动测试在野外采集的每一根骨头；任何脆弱到徒手就能折断的样本对锻造来说都是毫无用处的。战士们必须搜寻湿地峭壁沿线的这些叛军营地，折断脆弱的骨头，直到有八根真正坚固的样本通过力量测试。"}},faq={{q="为什么维罗拉·奈特雷特别需要兽人胫骨？",a="维罗拉需要致密、粗壮的材料来作为野蛮腿甲的支撑框架。她认为湿地的龙喉兽人尤其合适，因为他们沉重、强壮的骨骼结构比普通的猎物或残骸能提供更强的结构刚性。",al={"为什么需要兽人胫骨","为什么需要龙喉氏族的骨头","维罗拉的骨头盔甲"}},{q="为什么龙喉兽人是部落战士可以随意猎杀的目标？",a="盘踞在湿地的龙喉氏族残党是敌对的叛军，他们固守着第二次战争的黑暗遗产。他们并不效忠于萨尔领导下的现代部落，因此他们是国家的敌人，也是部落冒险者可以随意讨伐的对象。",al={"龙喉兽人属于部落吗","为什么要攻击龙喉兽人","龙喉氏族在部落的立场"}},{q="为了完成这个任务，在哪里可以找到龙喉兽人？",a="他们居住在湿地，穿过萨多尔大桥，位于阿拉希高地以南。战士们通常会在怒牙营地周围的山崖边搜寻他们，该营地位于北部主干道的西南方。",al={"龙喉氏族的位置","哪里寻找龙喉胫骨","怒牙营地位置"}},{q="为什么任务过程中会有这么多骨头折断？",a="维罗拉只要求最致密的骨髓框架用于锻造盔甲。作为她指示的一部分，战士们需要手工测试每一根骨头；任何在原始物理力量下折断的骨头都会被丢弃，因为它们太脆弱，无法在战斗中保护战士的双腿。",al={"断裂的胫骨","为什么胫骨会折断","坚固骨骼测试"}},{q="维罗拉·奈特雷是谁？",a="维罗拉·奈特雷是一位在幽暗城工作的被遗忘者护甲商。她性格粗暴、冷漠刻薄，而且喜欢讲些阴沉的冷笑话。她协助部落战士制造适合久经沙场的老兵使用的专业武备。",al={"维罗拉·奈特雷背景故事","维罗拉是谁","幽暗城护甲商"}},{q="用这些骨头锻造的是什么护甲部件？",a="这些收集来的骨头构成了野蛮腿甲的内部框架，这是一套为中等级别部落战士制作的耐用锁甲腿铠。",al={"胫骨任务奖励","胫骨的用途","野蛮腿甲锻造"}}},fx={["0579d748"]={q="维罗拉·奈特雷为什么想让你完成这件事？",a="维罗拉·奈特雷需要湿地龙喉兽人的胫骨来制作你的野蛮腿甲。这些坚固的骨头可以用作她答应为你打造的护甲材料。",al={"维罗拉·奈特雷的动机","维罗拉为什么要胫骨","维罗拉·奈特雷为什么"}}},fp="19,266,19.437.0,18.377.0,55.285.0,56.245.0,44.222.0,51.239.0,21.229.0,44.141.0"}
P.entries["quest:1848"] = {n="野蛮锁甲",s="凶暴链甲标志着部落战士在贫瘠之地完成艰苦试炼的顶点。在收集了稀有材料并证明了自己在面对各地危险敌人时的勇气后，战士们将战利品呈献给隐居的铁匠索恩格林·火眼。作为回报，他会打造出一套能够经受住最残酷战斗考验的坚固锁甲。",h="凶暴链甲标志着部落战士在贫瘠之地完成艰苦试炼的顶点。在收集了稀有材料并证明了自己在面对各地危险敌人时的勇气后，战士们将战利品呈献给隐居的铁匠索恩格林·火眼。作为回报，他会打造出一套能够经受住最残酷战斗考验的坚固锁甲。",kw={"凶暴护甲","凶暴链甲","十字路口","兽人锻造术","贫瘠之地","索恩格林·火眼","战士锁甲"},ang={["class:Warrior"]="凶暴链甲是年轻部落战士的一个里程碑成就，标志着他们从一名生涩的新兵蜕变为一名身着定制链甲、久经沙场的战士。",["faction:Horde"]="这件链甲由从卡利姆多的荒野中以鲜血换取的战利品制成，反映了部落崇尚武力自强和坚韧的核心美德。",["profession:Blacksmithing"]="观看索恩格林的锻造过程可以学到传统的兽人锻造术，在那里，战斗精神和坚韧意志被直接锤进了钢铁之中。"},sec={{t="铁匠的杰作",b="索恩格林·火眼栖身于贫瘠之地北部的崎岖山峦间，他不会为随便什么人打造盔甲。这位隐居的兽人要求想要获取盔甲的战士跋山涉水，去收集坚硬的野兽部件、稀有金属和炼金试剂，才会点燃他的风箱。这件成品链甲不仅是一件防护装备，更是被整个部落的老兵所认可的、代表着坚韧与勇气的持久勋章。"},{t="在苦难中锻造",b="索恩格林的试炼是刻意设计的磨砺。真正的部落武器和盔甲从诞生之初就注定要沾染其主人的汗水与鲜血。在交出成品凶暴链甲时，这位铁匠不会给予任何花哨的赞美——他只期待这套盔甲能在残酷的战斗中得到验证，并在归来时带着鲜血与荣耀的故事。"}},faq={{q="什么是凶暴链甲？",a="凶暴链甲是一件由兽人铁匠索恩格林·火眼定制的坚固胸甲。它是部落战士证明自己战斗实力，并跨越数片危险土地收集稀有材料后所获得的最高奖励。",al={"什么是凶暴链甲","凶暴链甲任务","谁制作凶暴链甲"}},{q="索恩格林·火眼是谁？",a="索恩格林·火眼是一位隐居的资深铁匠，他居住在贫瘠之地北部的一处山脊上，就在十字路口和奥格瑞玛之间的道路以东。他会考验初出茅庐的战士，并在他们证明自己的价值后，为他们打造特制的盔甲。",al={"索恩格林是谁","索恩格林·火眼","索恩格林在哪里"}},{q="为什么索恩格林在打造盔甲前要求这么多努力？",a="部落的战士传统不仅重视武艺，也同样重视磨难。索恩格林认为，如果一个人没有流过血，也没有辛苦地去获取锻造所需稀有组件，那么高质量的锁甲给他也是浪费。",al={"为什么要收集这么多材料","凶暴护甲要求","索恩格林的试炼"}},{q="这个任务链接下来会导向何处？",a="该任务代表了“凶暴的护甲”试炼的最后一步。一旦索恩格林将成品链甲交给你，他为你所做的工作就完成了，剩下的路就是穿着这套盔甲去往卡利姆多和东部王国参加战斗。",al={"凶暴链甲之后有什么","凶暴链甲后续任务","是否有后续"}},{q="联盟可以接取凶暴链甲任务吗？",a="不。凶暴链甲是部落专属的试炼。联盟战士会经历另一套独特的武艺仪式，涉及铁炉堡的铁匠和周边的矮人领地，以锻造他们自己的标志性盔甲。",al={"联盟能获得凶暴链甲吗","联盟对应任务","这是部落专属吗"}},{q="在贫瘠之地的什么地方可以找到索恩格林？",a="索恩格林居住在贫瘠之地北部的一处高耸山脊上，位于荆棘岭正南方，十字路口以东。",al={"索恩格林位置","贫瘠之地哪里有索恩格林","如何找到索恩格林"}}},fx={a5674fab={q="Thun'grim Firegaze为什么要为你锻造这件胸甲？",a="Thun'grim Firegaze不会为随便什么人锻造他的野蛮护甲。作为一位受尊敬的大师级护甲匠，他要考验有潜力的部落战士；在挥锤之前，他要求你证明自己的耐力、力量和坚韧。你收集必要的材料并替他直面险境，证明了自己有资格穿戴他的精湛作品上阵作战。",al={"为什么让我做野蛮胸甲","thun'grim为什么制作护甲","为什么赠予野蛮胸甲"}}},fp="14,363,21.433.0,18.356.0,27.241.0,26.255.0,68.223.0,38.233.0,54.212.0,44.110.0"}
P.entries["quest:185"] = {n="猎虎",s="在荆棘谷北部的狩猎营地，猎人艾耶克·罗欧克提出要传授冒险者追踪大型猫科动物的技巧。她会让新手去对抗营地附近潜行的幼虎，以此来测试他们基本的狩猎和追踪能力。",h="在荆棘谷北部的狩猎营地，猎人艾耶克·罗欧克提出要传授冒险者追踪大型猫科动物的技巧。她会让新手去对抗营地附近潜行的幼虎，以此来测试他们基本的狩猎和追踪能力。",kw={"艾耶克·罗欧克","狩猎","奈辛瓦里","荆棘谷","猎虎大师","年幼的荆棘谷猛虎"},sec={{t="丛林里的第一课",b="艾耶克·罗欧克在儿时就从她父亲那里学会了猎虎的艺术，现在她将这项技艺分享给那些在完成“丛林欢迎仪式”后来到奈辛瓦里远征队营地的旅人们。她坚持认为，追踪并猎杀最年幼的猫科动物是任何猎人进阶去挑战更高级猎物前必须具备的基础。"},{t="猎杀潜行者",b="年幼的荆棘谷猛虎通常出没在靠近远征队营地的丛林中。罗欧克要求必须猎杀十只这样的野兽，以证明其实力足以胜任，她才会提供进一步的训练。"}},faq={{q="谁会教你如何猎虎？",a="驻扎在荆棘谷北部奈辛瓦里远征队营地的资深猎人艾耶克·罗欧克提供此项训练。",al={"谁提供猎虎大师训练","艾耶克·罗欧克任务","猎虎任务发布者"}},{q="为什么艾耶克·罗欧克首先选择幼虎作为目标？",a="罗欧克认为这些年幼的猫科动物更容易追踪和猎杀，因此它们是检验猎人追踪技能的理想入门试炼，在尝试更危险的猎物之前必须先通过这一关。",al={"为什么是幼虎","为什么猎虎大师训练要从简单的开始"}},{q="在哪里可以找到幼虎？",a="年幼的荆棘谷猛虎通常潜伏在远征队营地附近的丛林地带。",al={"年幼的荆棘谷猛虎在哪里","幼虎位置"}},{q="这项狩猎之前有什么前置任务？",a="这项狩猎试炼紧随前置任务“丛林欢迎仪式”之后，该任务旨在引导旅人前往狩猎营地。",al={"猎虎大师训练前置要求","猎虎大师之前是什么任务"}}},fp="13,256,27.325.0,20.218.0,41.121.0,48.177.0,33.110.0,28.114.0"}
P.entries["quest:1858"] = {n="碎手氏族",s="这场潜行者试炼是加入奥格瑞玛碎手氏族的最终入门考核。瑟佐克要求想要加入的潜行者从一名毫不知情的同伙身上偷走钥匙，从而打开一个找回来的背包。",h="这场潜行者试炼是加入奥格瑞玛碎手氏族的最终入门考核。瑟佐克要求想要加入的潜行者从一名毫不知情的同伙身上偷走钥匙，从而打开一个找回来的背包。",kw={"cleft of shadow","加摩尔","奥格瑞玛","偷窃","潜行者","碎手氏族","塔赞","瑟佐克"},ang={["class:Rogue"]="这场成人礼传授了潜行者技艺的核心原则：在拥挤的地方追踪毫无察觉的目标，神不知鬼不觉地摸走钥匙，并获得至关重要情报。",["faction:Horde"]="在萨尔新部落的尚武荣誉之下，隐藏着隐秘侦察的必要性，而这正是由潜伏在奥格瑞玛深处的碎手氏族悄悄管理的。"},sec={{t="潜行者的考验",b="在拿到了塔赞的背包后，渴望加入的潜行者们发现没有钥匙，这个战利品就毫无用处。碎手氏族坚持要求进行真正的技艺展示，而不是强行破坏复杂的锁。瑟佐克指引他的新成员去找加摩尔，一个容易分心的牛头人醉汉，他经常出没于奥格瑞玛的旅店，而且曾经协助过塔赞，这使他成为秘密盗窃的完美目标。"},{t="欢迎来到暗影",b="在不惊动整个旅店的情况下从加摩尔身上偷走钥匙，让入门者可以打开背包并获得塔赞的日志。将这些失窃的内容带回给大断崖的瑟佐克，就能满足公会严格的标准。随着任务顺利完成，候选人将正式被接纳为碎手氏族公认的特工。"}},faq={{q="谁是加摩尔，为什么他有钥匙？",a="加摩尔曾是塔赞的助手，而塔赞正是瑟佐克正在调查其背包的那个特工。虽然塔赞带着背包，但他把钥匙留给了加摩尔，一个毫无戒心的醉汉，每天都在奥格瑞玛的中心旅店喝酒。",al={"为什么是加摩尔","谁有钥匙","加摩尔钥匙"}},{q="塔赞的背包里有什么？",a="锁住的背包里放着塔赞的日志。其中的内容详细记录了瑟佐克和碎手氏族感兴趣的情报，证明了该入门者在隐秘环境下获取重要信息的能力。",al={"塔赞的日志","背包内容","背包里有什么"}},{q="奥格瑞玛的碎手氏族是什么？",a="碎手氏族最初是一个来自德拉诺、以自我伤害和冷酷无情而闻名的臭名昭著的兽人氏族，在奥格瑞玛，它已经演变成了部落顶尖的刺客、间谍和潜行者公会，在大断崖的地下洞穴中运作。",al={"什么是碎手氏族","碎手氏族潜行者","奥格瑞玛潜行者"}},{q="瑟佐克在哪里运作？",a="瑟佐克在大断崖运作，这是一个隐藏在奥格瑞玛岩石山脊下的昏暗洞穴网络，术士、潜行者和暗影技艺的修行者们在这里远离日光，茁壮成长。",al={"瑟佐克在哪里","瑟佐克位置","大断崖潜行者训练师"}},{q="为什么瑟佐克不直接撬开背包？",a="背包上安装了复杂的锁具，但更重要的是，这是一场对潜行者纪律的考验。碎手氏族更看重外科手术般的盗窃技巧和细腻手法，而不是吵闹的破坏。",al={"为什么要偷窃","为什么需要钥匙"}},{q="这个任务之后会发生什么？",a="此任务标志着入门任务链的结束。通过上交塔赞的日志，你将被正式宣布为碎手氏族的一名公认成员，并获得有助于你未来隐秘行动的工具作为奖励。",al={"碎手氏族奖励","任务链结束"}}},fx={["74a53139"]={q="Therzok为什么想打开塔赞的背包？",a="Therzok和破碎之手在奥格瑞玛的暗处活动，为部落处理机密和隐秘防务。塔赞掌握着对他们行动至关重要的情报，但那些重要物品被锁在一个复杂的背包里。Therzok想在不损坏物品的情况下取得其中的情报，并借此作为实际考验，看看你是否具备加入他们组织所需的机敏、潜行本领和技巧。",al={"therzok的动机","为什么打开背包","therzok想要什么"}},a30dee79={q="塔赞的日志是什么？",a="塔赞的日志记录了塔赞的活动和秘密交易。这个行动人员的所作所为引起了破碎之手的注意。日志被锁在他的背包里，里面有Therzok所需的重要情报。毫发无损地交出日志，既能证明你会扒窃、能破解棘手的锁，也能将宝贵情报直接送到奥格瑞玛的间谍头目手中。",al={"塔赞的日志","日志里有什么","塔赞的日志背景"}},["1b7f194d"]={q="Therzok为什么不派奥格瑞玛的卫兵去抓Gamon？",a="破碎之手行事谨慎隐秘，与城市卫兵公开而光明正大的做法截然不同。若派奥格瑞玛的步兵抓捕像Gamon这样的醉酒酒馆客人，只会引发不必要的公开骚动，还可能惊动塔赞的同伙。把这次盗窃交给一名有志成为盗贼的人，既能让行动悄无声息，也能暗中考察你的身手。",al={"为什么选我","为什么派盗贼","为什么不派城市卫兵"}}},fp="18,216,18.386.0,22.353.0,42.243.0,31.216.0,40.250.0,27.179.0,48.194.0,30.223.1"}
P.entries["quest:1859"] = {n="瑟祖克",s="Therzok是一个发给在试炼谷和森金村附近活动的有前途的Horde潜行者的传唤。潜行者训练师卡普拉克发现了你对于暴力和潜行的天赋，悄悄指引你前往洞穴般的Cleft of Shadow去会见Shattered Hand的一名特工。",h="Therzok是一个发给在试炼谷和森金村附近活动的有前途的Horde潜行者的传唤。潜行者训练师卡普拉克发现了你对于暴力和潜行的天赋，悄悄指引你前往洞穴般的Cleft of Shadow去会见Shattered...",kw={"刺客","cleft of shadow","杜隆塔尔","卡普拉克","奥格瑞玛","潜行者","shattered hand","therzok"},ang={["class:Rogue"]="这次传唤标志着你正式加入Shattered Hand，将你在杜隆塔尔的单打独斗与遍布Horde的组织严密的间谍网络联系起来。",["faction:Horde"]="虽然Thrall宣扬荣耀和战士精神，但Therzok及其网络的存在证明了Horde理解隐藏之刃和秘密情报收集者的实际必要性。"},sec={{t="低语的传唤",b="并非所有新Horde的仆从都在Thrall荣耀的旗帜下光明正大地战斗。当年轻的潜行者开始在杜隆塔尔崭露头角时，卡普拉克会将他们拉到一边低语。一名既有致命杀伤力，又愿意游走于公开战争规则边缘的特工的消息，很快就传到了奥格瑞玛地下公会的耳中。"},{t="进入Cleft of Shadow",b="卡普拉克将初学者派往奥格瑞玛红石悬崖下的深处，进入Cleft of Shadow。远离城市卫兵的监视，Therzok在阴影中等待。这次会面作为一种引导，将独行的窃贼和伏击者带入结构严密的Shattered Hand，这个隐秘的网络作为Horde在黑暗中的匕首发挥作用。"}},faq={{q="Therzok是谁？",a="Therzok是位于奥格瑞玛地下Cleft of Shadow的一名Shattered Hand特工。他负责考察从杜隆塔尔训练场前来的有前途的年轻潜行者，并将他们引入公会效力。",al={"therzok是谁","therzok背景","npc therzok"}},{q="卡普拉克为什么要派我去找他？",a="卡普拉克认可你拥有战斗技巧以及潜行和诡计的天赋。他知道Shattered Hand一直在寻找有能力的恶棍来加强他们的队伍，因此他传达了Therzok招募你的请求。",al={"为什么派我去找therzok","卡普拉克任务","为什么要去奥格瑞玛"}},{q="奥格瑞玛的Shattered Hand是什么？",a="虽然这个名字可以追溯到古老的Draenor氏族，但在现代的奥格瑞玛，Shattered Hand作为效忠于Horde的刺客、间谍和盗贼的秘密公会运作。他们执行Thrall的荣耀战士无法公开执行的必要且道德模糊的任务。",al={"什么是shattered hand","shattered hand奥格瑞玛","horde潜行者公会"}},{q="Cleft of Shadow位于何处？",a="Cleft of Shadow是一个隐藏在奥格瑞玛中心下方的巨大洞穴，可以通过从Valley of Strength和the Drag向下延伸的黑暗通道进入。这里让城里的术士和潜行者远离公众视线。",al={"cleft of shadow在哪里","如何找到therzok","cleft of shadow位置"}},{q="见到Therzok之后要做什么？",a="在问候Therzok后，他会立即向你介绍为Shattered Hand工作的职责，并分配任务来证明你的能力、潜行技巧以及对该网络的忠诚。",al={"下一个任务","therzok想要什么","therzok之后"}},{q="非潜行者能接到这个任务吗？",a="不能。这个任务只提供给达到一定经验等级的潜行者，标志着他们从当地的散兵游勇转变为Horde情报网络的正式特工。",al={"其他职业可以做吗","这是潜行者专属吗","潜行者任务"}}},fx={["89f659b0"]={q="Kaplak为什么选你参加这次会面？",a="Kaplak接到明确命令，要寻找符合你特征的人。公会听说你擅长战斗，必要时也不介意使用潜行、欺骗或不那么光彩的手段。Therzok有件事要办，需要的正是你这样本领多变的人。",al={"kaplak为什么选我","为什么派我去找therzok","kaplak为什么挑中我"}}},fp="7,282,19.368.0,24.369.0,15.228.0,31.243.0,40.284.0,37.226.0,33.190.0,33.200.0"}
P.entries["quest:186"] = {n="猎虎",s="在北荆棘谷的奈辛瓦里远征队营地，艾耶克·罗欧克升级了他的狩猎试炼。在见识过你对幼年潜行者展现出的潜力后，他现在派你深入丛林，去猎杀成年荆棘谷猛虎。",h="在北荆棘谷的奈辛瓦里远征队营地，艾耶克·罗欧克升级了他的狩猎试炼。在见识过你对幼年潜行者展现出的潜力后，他现在派你深入丛林，去猎杀成年荆棘谷猛虎。",kw={"艾耶克·罗欧克","奈辛瓦里远征队营地","荆棘谷猛虎","荆棘谷","猛虎大师"},sec={{t="猎杀成年猫科动物",b="继你在对付年幼掠食者时初试身手并取得成功后，艾耶克·罗欧克希望考验你日益精进的狩猎技巧，让你去对付更老练的野兽。他指引你重返荆棘谷的荒野，在追求更艰巨的挑战之前，先猎杀十只成年荆棘谷猛虎。"}},faq={{q="谁发布了这个狩猎任务？",a="艾耶克·罗欧克，一位驻扎在北荆棘谷奈辛瓦里远征队营地的猎人，发布了这项试炼。",al={"谁发布了猛虎大师","艾耶克·罗欧克位置","谁发布了这个任务"}},{q="你需要猎杀什么野兽？",a="你需要追踪并击杀徘徊在周围丛林中的十只成年荆棘谷猛虎。",al={"我需要杀什么老虎","哪些猫科动物","猛虎大师目标"}},{q="这项试炼在狩猎任务链中处于什么位置？",a="这项试炼紧随最初的猛虎大师狩猎任务之后，并直接引向艾耶克·罗欧克指引下的第三阶段。",al={"猛虎大师2之前是什么","接下来是什么","猛虎大师系列任务"}}},fp="13,223,23.288.0,22.109.0,40.100.0,38.118.0"}
P.entries["quest:1860"] = {n="和詹妮亚交谈",s="“与詹妮亚交谈”是一项引导性的召唤任务，旨在引导那些在艾尔文森林完成了基础训练的新晋联盟法师。在闪金镇的训练师扎尔迪玛·维夫希尔特的派遣下，学徒们被指引前往暴风城，向密室中的詹妮亚·坎农报到。",h="“与詹妮亚交谈”是一项引导性的召唤任务，旨在引导那些在艾尔文森林完成了基础训练的新晋联盟法师。在闪金镇的训练师扎尔迪玛·维夫希尔特的派遣下，学徒们被指引前往暴风城，向密室中的詹妮亚·坎农报到。",kw={"艾尔文森林","闪金镇","詹妮亚·坎农","mage quarter","与詹妮亚交谈","暴风城","密室","扎尔迪玛·维夫希尔特"},ang={["class:Mage"]="这项任务标志着你从闪金镇的乡村施法训练毕业，正式参与到在暴风城密室运作的高阶法师们的事务中。",["faction:Alliance"]="艾尔文森林和暴风城的安全不仅仅依靠步兵，还依靠从首都魔法学院直接监控的奥术警戒。"},sec={{t="召唤前往密室",b="当学徒法师在闪金镇展现出对初级法术的足够掌握时，扎尔迪玛·维夫希尔特意识到在当地导师指导下的实地训练已经结束了。为了不让他们继续在艾尔文森林的村庄里徘徊，这些前途无量的施法者被指引前往暴风城。在法师区中心矗立着密室，那是一座庞大的奥术研究与教学圣殿，王国的高阶法师们在那里统筹整个王国的各类魔法事务。"},{t="王国安全事务",b="扎尔迪玛强调，向暴风城报到不仅仅是一次例行的学业晋升；有一项直接影响到艾尔文森林和暴风城安全的特殊任务已经出现。抵达后，学徒将向詹妮亚·坎农报到，这位资深法师负责监管当地的重要任务。尽管詹妮亚在向刚抵达的学徒透露重大机密时依然保持审慎和克制，但向她报到标志着正式开始为法师组织效力。"}},faq={{q="谁派发这个任务给我？",a="扎尔迪玛·维夫希尔特是驻扎在闪金镇Lion's Pride Inn内的人类法师训练师，当你达到足够的奥术造诣后，他会为你开启这项任务。",al={"任务发布者","谁发布任务","扎尔迪玛"}},{q="我在哪里可以找到詹妮亚·坎农？",a="詹妮亚·坎农住在暴风城法师区中心的密室里。她就在密室那充满神秘感的厅堂中研习法术。",al={"詹妮亚·坎农位置","詹妮亚在哪里","找到詹妮亚"}},{q="什么是密室？",a="密室是暴风城法师区内显眼的魔法尖塔。它是王国法师和奥术学者们主要的学院、图书馆及行动基地。",al={"什么是密室","暴风城法师塔"}},{q="为什么扎尔迪玛派我去找詹妮亚，而不是由他自己处理？",a="扎尔迪玛在闪金镇训练年轻法师掌握基础知识，但涉及王国整体的区域性威胁和专业任务则由来自首都的詹妮亚·坎农等高阶学者统管。",al={"为什么要前往暴风城","为什么是詹妮亚"}},{q="向詹妮亚·坎农报到后会发生什么？",a="当你向詹妮亚报到后，她会指派你去调查艾尔文森林明镜湖周围出现的神秘魔法异常现象。",al={"下一步做什么","后续任务","后续步骤"}},{q="任何职业都能接这个任务吗？",a="不能。这个任务仅限法师，它作为职业成人礼，标志着学徒从乡村训练毕业，正式进入暴风城奥术协会的行列。",al={"非法师能做这个吗","仅限法师","职业要求"}}},fp="17,210,30.347.0,27.321.0,27.129.0,31.89.0,29.173.0,67.196.0,46.97.1,37.98.0"}
P.entries["quest:1861"] = {n="明镜湖",s="明镜湖是为在暴风城的Mage Quarter学习的新手法师准备的入门调查任务。在詹妮亚·坎农的委托下，学徒们需要前往城门西南方，采集明镜湖瀑布的水样，以检测是否存在残留的魔法污染。",h="明镜湖是为在暴风城的Mage Quarter学习的新手法师准备的入门调查任务。在詹妮亚·坎农的委托下，学徒们需要前往城门西南方，采集明镜湖瀑布的水样，以检测是否存在残留的魔法污染。",kw={"奥术污染","艾尔文森林","詹妮亚·坎农","魔网","明镜湖","水样","密室"},ang={["class:Mage"]="这项任务标志着学徒从在密室阅读尘封的典籍转向调查现实世界的奥术现象，并将奖励他们的第一根专属法杖或副手法球。",["faction:Alliance"]="确保艾尔文森林自然资源的安全，是密室的法师们守护王国核心的诸多悄无声息的方式之一。",["race:Human"]="明镜湖滋养着艾尔文森林周边的农田和水道，其纯净度对于暴风城公民的日常健康至关重要。"},sec={{t="魔网与流动的变迁",b="在过去的几十年里，艾泽拉斯饱受灾难性的神秘冲突蹂躏，从黑暗之门开启到第三次战争，再到海加尔山之战。这些剧烈的震荡撕裂了古老的奥术流向，使其偏离了原本稳定的通道。在暴风城的密室中，像詹妮亚·坎农这样的法师密切监测着这些变化，他们担心偏移的奥术能量流可能会渗入周边的荒野并腐蚀当地的生态系统。"},{t="测试水质",b="明镜湖坐落在暴风城大门西南方的悬崖下，是主要的天然水库，由山间瀑布汇聚而成。由于周边地区依赖这些水源，詹妮亚派遣携带玻璃瓶的新手法师直接前往瀑布底部。收集新鲜的水雾样本可以让密室进行精细的占卜和试剂测试，以确定野生魔法是否已开始渗入公共供水系统。"}},faq={{q="为什么詹妮亚·坎农需要明镜湖的水样？",a="遍布艾泽拉斯的大规模神秘战争破坏了天然的魔网流向。詹妮亚·坎农担心不稳定的奥术能量正在渗入暴风城周围的地下水位，这可能会对饮用湖水的人产生不利影响。",al={"为什么需要明镜湖水","詹妮亚的水样","这个任务是为了什么"}},{q="明镜湖具体在哪里？",a="明镜湖位于艾尔文森林西北部，紧靠暴风城主门西南方的峭壁。所需的样本需在瀑布脚下的水潭处采集。",al={"明镜湖在哪里","明镜湖位置","寻找明镜湖"}},{q="如果水被污染了会怎样？",a="詹妮亚担心长期饮用受魔法污染的水可能会伤害那些依赖该湖泊的人。具体的影响尚不清楚。",al={"水有毒吗","如果水里有魔法怎么办","奥术污染的影响"}},{q="谁可以执行这项任务？",a="这项任务专门分配给在联盟中训练的新手法师，这是他们代表密室执行的最早期的实地任务之一。",al={"谁能接明镜湖任务","明镜湖任务只有法师能接吗"}},{q="这个任务会有后续调查吗？",a="它结束了詹妮亚·坎农召唤开始的直接初步任务，奖励学徒他们的第一件正式法师装备，并确立了他们监测整个王国魔法扰动的职责。",al={"明镜湖之后有什么","明镜湖任务线"}},{q="是什么导致了魔法流动的最初不稳定？",a="詹妮亚将流动的变化归因于世界范围内巨大的神秘斗争，并未具体指明某场战斗或事件。",al={"为什么魔网会受损","神秘斗争的含义","什么破坏了魔法"}}},fp="11,198,31.381.0,18.399.0,60.200.0,29.169.0,37.139.0,31.124.0,47.206.0,67.112.0"}
P.entries["quest:187"] = {n="猎虎",s="在奈辛瓦里远征队营地的丛林深处，艾耶克·罗欧克提高了狩猎试炼的难度。他要求你杀死十只年长的荆棘谷幼虎，以在最终测试前证明你的实力。",h="在奈辛瓦里远征队营地的丛林深处，艾耶克·罗欧克提高了狩猎试炼的难度。他要求你杀死十只年长的荆棘谷幼虎，以在最终测试前证明你的实力。",kw={"艾耶克·罗欧克","大型狩猎","年长的荆棘谷幼虎","奈辛瓦里","荆棘谷","虎类狩猎大师"},sec={{t="技能测试",b="在之前的狩猎之后，艾耶克·罗欧克要求你在荒野中追踪十只年长的荆棘谷幼虎。他认为这些野兽既最难追踪，也是最凶猛的对手。击杀十只这样的野兽是最终试炼的前奏，完成之后，他承诺会在奈辛瓦里大师面前宣布你是一位虎类狩猎大师。"}},faq={{q="谁负责布置这项试炼？",a="艾耶克·罗欧克在荆棘谷北部的奈辛瓦里远征队营地提供这项试炼。",al={"谁发布虎类狩猎大师","艾耶克·罗欧克任务","任务发布者"}},{q="你需要追踪什么猎物？",a="你必须猎杀十只年长的荆棘谷幼虎。",al={"我需要杀什么","哪种老虎","虎类狩猎大师目标"}},{q="为什么要特别挑选年长的荆棘谷幼虎？",a="艾耶克·罗欧克指出，年长的荆棘谷幼虎是当地猫科动物中最难找到且最凶猛的。",al={"为什么是年长的老虎","年长老虎的难度"}},{q="这项狩猎之前的内容是什么？",a="这项试炼紧随艾耶克·罗欧克的虎类狩猎大师系列任务的第二阶段之后。",al={"前置任务","先决条件"}}},fp="13,200,15.349.0,23.103.0,29.50.0,47.129.0,28.84.0"}
P.entries["quest:1878"] = {n="收集水袋",s="操作员鲁格伦克再次向你致意，希望你能再带五个荒芜游荡者水袋来，并为你准备好了一份补给包。",h="操作员鲁格伦克再次向你致意，希望你能再带五个荒芜游荡者水袋来，并为你准备好了一份补给包。",kw={"补给包","操作员鲁格伦克","塔纳利斯","荒芜游荡者水袋","水袋赏金"},sec={{t="再次光临",b="在“水袋赏金”任务之后，鲁格伦克欢迎你的回归，并询问你的背包里是否还有五个荒芜游荡者水袋。如果是，一份写着你名字的补给包已经为你留好了。"},{t="多多益善",b="鲁格伦克对回收的水袋感到满意，因为每一个水袋都能让大家远离灾难。鲁格伦克承诺，你每上交五个水袋，都会得到应有的回报。"}},faq={{q="谁在提供这项赏金任务？",a="加基森的操作员鲁格伦克。",al={"谁提供水袋赏金任务","鲁格伦克任务","谁回收水袋"}},{q="需要多少个水袋？",a="五个荒芜游荡者水袋，和之前一样。",al={"多少个水袋","水袋数量","每次上交的水袋数"}},{q="鲁格伦克准备了什么？",a="一份补给包，专门为你预留的。",al={"什么是补给包","我能得到什么"}},{q="这一步之前是什么？",a="它是之前“水袋赏金”任务的后续，在那项任务中，你首次将水袋带给了鲁格伦克。",al={"前置任务","我首先要做什么"}}},fp="18,131,10.189.0,16.182.1,28.44.0,34.51.0,31.37.0,28.91.0"}
P.entries["quest:1879"] = {n="和彬克交谈",s="“与彬克谈话”是一项联盟征召任务，旨在引导新手法师从丹莫罗前往主城铁炉堡。这项任务由玛济斯·石衣发布，旨在派遣有前途的施法者去协助在Hall of Mysteries工作的奥术研究员彬克。",h="“与彬克谈话”是一项联盟征召任务，旨在引导新手法师从丹莫罗前往主城铁炉堡。这项任务由玛济斯·石衣发布，旨在派遣有前途的施法者去协助在Hall of Mysteries工作的奥术研究员彬克。",kw={"彬克","丹莫罗","hall of mysteries","铁炉堡","法师","玛济斯·石衣","mystic ward"},ang={["class:Mage"]="这次征召标志着你从入门级的山谷训练中毕业，开始参与铁炉堡学院派奥术师们的更广泛事务。",["faction:Alliance"]="在联盟旗帜下，Hall of Mysteries内的共同研究展示了侏儒的智慧与矮人的好客之间的紧密结合。",["race:Gnome"]="在诺莫瑞根陷落后，彬克和玛济斯·石衣代表了侏儒奥术传统在铁炉堡好客大厅中的延续。"},sec={{t="同僚的征召",b="在丹莫罗冰冷的山峦中训练的新手法师最终引起了玛济斯·石衣的注意。当石衣意识到学徒已经超越了卡拉诺斯周边的基础练习后，他便传达了他同僚彬克的消息。这个请求非常具体且不容置疑：彬克需要一位奥术专家，并且拒绝将此事托付给任何不会施法的人。"},{t="Hall of Mysteries",b="这项任务将年轻的法师带入铁炉堡的Mystic Ward，学者、牧师和奥术师们汇聚在Hall of Mysteries高耸的石拱顶之下。彬克在这里进行她的研究，并用敏锐的目光评估着前来报到的学徒。在她看来，原始的潜力仅仅是个开始；一个缺乏纪律的施法者在奥术领域很快就会成为隐患，而非助力。"}},faq={{q="谁发布这个任务？",a="玛济斯·石衣会向那些已经在丹莫罗完成早期训练的新手联盟法师提供此任务。",al={"任务发布者","任务起始位置","谁发布与彬克谈话"}},{q="我在哪里可以找到彬克？",a="彬克居住在Hall of Mysteries，它位于铁炉堡北区的Mystic Ward内。",al={"彬克位置","彬克在哪里","寻找彬克"}},{q="为什么彬克只想要法师？",a="彬克正在进行的研究直接涉及奥术能量和敏感的监测设备。她认为非施法者无法处理其中涉及的魔法细微差别和危险。",al={"为什么仅限法师","法师职业要求","彬克只想要法师"}},{q="见到彬克后会发生什么？",a="在问候你并评估你的能力后，彬克会请求你协助她的研究，后续任务为“法师级的奥术监测器”。",al={"下一个任务","彬克后续任务","与彬克谈话后的任务"}},{q="其他职业可以接这个任务吗？",a="不可以。此任务专门为法师量身定做，作为从当地新手训练到主城专业任务的过渡。",al={"其他职业可以接吗","这是法师专属吗","法师专属"}},{q="什么是Hall of Mysteries？",a="Hall of Mysteries是铁炉堡的奥术和圣光研究中心，汇集了代表矮人和侏儒魔法艺术的训练师、学者和研究员。",al={"铁炉堡 hall of mysteries","什么是 hall of mysteries"}}},fx={["96ce9827"]={q="Magis Sparkmantle为什么派你去找彬克？",a="Magis Sparkmantle是一名驻扎在卡拉诺斯的侏儒法师训练师，也是新晋施法者的导师。他在铁炉堡的同僚彬克特意传话，请求派一位熟练的法师去执行一项重要任务。Magis看出你对奥术的掌握日益精进，便让你前往矮人之都响应她的召唤，继续磨练你的魔法技艺。",al={"magis为什么派你去","magis sparkmantle的动机","为什么要和彬克谈话"}}},fp="15,259,21.388.0,21.404.0,21.113.0,22.108.0,31.192.0,32.141.0,52.134.0,30.172.0"}
P.entries["quest:188"] = {n="猎虎",s="艾耶克·罗欧克在北荆棘谷的一系列狩猎任务中提供了终极挑战。在追踪一只难以捉摸的野兽数周后，他向你发出挑战，要求你找到老虎辛达尔并带回她的爪子。",h="艾耶克·罗欧克在北荆棘谷的一系列狩猎任务中提供了终极挑战。在追踪一只难以捉摸的野兽数周后，他向你发出挑战，要求你找到老虎辛达尔并带回她的爪子。",kw={"艾耶克·罗欧克","猛虎狩猎大师","奈辛瓦里远征队营地","辛达尔的爪子","辛达尔","荆棘谷","猛虎狩猎"},sec={{t="最后的猛虎",b="在完成了之前针对荆棘谷猛虎的试炼后，奈辛瓦里远征队营地的艾耶克·罗欧克为你提供了最后一个挑战。狩猎营地已经在丛林中追踪了一只异常难以捉摸的猛虎，名为辛达尔，时间长达数周。艾耶克向你发出挑战，要求你追踪并击倒这头野兽，夺取她的爪子作为无可辩驳的证据。"},{t="猛虎狩猎大师",b="带着辛达尔的爪子回到奈辛瓦里营地，证明了你无可置疑的追踪技术。艾耶克·罗欧克认可了你的成就，宣布你为真正的猛虎狩猎大师。"}},faq={{q="谁提供了这次狩猎任务？",a="艾耶克·罗欧克，一位驻扎在北荆棘谷奈辛瓦里远征队营地的资深猎人，发布了这次最终的猛虎挑战。",al={"任务发布者","谁发布猛虎狩猎","艾耶克·罗欧克位置"}},{q="辛达尔是什么？",a="辛达尔是一只难以捉摸的猛虎，奈辛瓦里远征队的猎人们已经在荆棘谷的丛林中追踪了她数周。",al={"辛达尔是什么","辛达尔背景故事","辛达尔是谁"}},{q="艾耶克·罗欧克需要什么证据？",a="艾耶克·罗欧克要求你带回辛达尔的爪子，以证明这头野兽确实已被击败。",al={"我需要带回什么","猛虎狩猎证明","辛达尔的爪子"}},{q="这次狩猎之前有什么任务？",a="这次狩猎是艾耶克·罗欧克系列任务的第四步，也是最后一步，紧接在北荆棘谷的第三次猛虎狩猎试炼之后。",al={"前置条件","猛虎狩猎任务线","前序任务"}}},fp="13,216,15.352.0,19.190.1,21.140.0,17.143.0,37.102.0,24.142.0"}
P.entries["quest:1881"] = {n="安娜斯塔西娅",s="“与安娜斯塔西娅谈话”是一项引导性的征召任务，指引有前途的被遗忘者法师前往幽暗城的安娜斯塔西娅·哈特威尔处。法师训练师凯恩·火歌会派遣年轻的施法者前往魔法区，为被遗忘者的法师们执行关键任务。这次简短的征召为深入提瑞斯法林地的枯萎之地进行调查奠定了基础。",h="“与安娜斯塔西娅谈话”是一项引导性的征召任务，指引有前途的被遗忘者法师前往幽暗城的安娜斯塔西娅·哈特威尔处。法师训练师凯恩·火歌会派遣年轻的施法者前往魔法区，为被遗忘者的法师们执行关键任务。这次简短的征召为深入提瑞斯法林...",kw={"安娜斯塔西娅·哈特威尔","巴尼尔农场","凯恩·火歌","法师任务","magic quarter","幽暗城"},ang={["class:Mage"]="这个任务标志着你从基础的奥术训练转向为幽暗城法师提供主动服务。",["race:Undead"]="对于被遗忘者奥术师来说，响应哈特威尔的召唤代表着一个机会，可以利用洛丹伦的知识储备来应对当前的危险。"},sec={{t="召唤前往魔法区",b="当新晋施法者在布瑞尔凯恩·火歌的指导下磨练初期才华时，他们很快就会被指引前往首都。被遗忘者的法师们在幽暗城的魔法区内维持着一个专门的领地，负责组织奥术学术研究，并统筹整个洛丹伦的防御战略。凯恩·火歌担任评估员，筛选掉新手，并将那些展现出真正天赋的人直接送往需要人手的资深法师处。"},{t="安娜斯塔西娅·哈特威尔的野心",b="安娜斯塔西娅·哈特威尔是幽暗城中杰出的法师导师之一。她并没有让有前途的学生在安全的环境中钻研琐碎的咒语，而是毫不浪费时间，迫使他们为被遗忘者的领土和现实利益服务。响应她的召唤不仅是奥术修行者的一场成人礼，也是对天灾军团战后定义的阴暗、务实魔法追求的入门。"}},faq={{q="是谁让你去和安娜斯塔西娅·哈特威尔谈话的？",a="被遗忘者法师训练师凯恩·火歌在认可你的奥术天赋足以协助处理首都内更艰巨的事项后，将你派往她那里。",al={"谁给予与安娜斯塔西娅谈话任务","与安娜斯塔西娅谈话任务发布者","凯恩·火歌召唤"}},{q="在哪里可以找到安娜斯塔西娅·哈特威尔？",a="安娜斯塔西娅·哈特威尔居住在幽暗城的魔法区，她在那里协调并指导被遗忘者的奥术修行者。",al={"安娜斯塔西娅·哈特威尔在哪里","安娜斯塔西娅·哈特威尔位置","找到安娜斯塔西娅"}},{q="这次征召的目的是什么？",a="安娜斯塔西娅正在寻找一位有能力的施法者来执行城墙之外的实际任务，首先是提瑞斯法林地的实地任务，例如调查巴尼尔农场。",al={"她为什么需要我","与安娜斯塔西娅谈话目的","安娜斯塔西娅需要什么"}},{q="“与安娜斯塔西娅谈话”之后是什么任务？",a="直接向安娜斯塔西娅报到后将接到“巴尼尔农场”任务，你会前往提瑞斯法林地东部，从农场的花园中收集金鱼草。",al={"接下来是什么任务","与安娜斯塔西娅谈话后的后续任务","与安娜斯塔西娅谈话后续"}},{q="这个任务有职业限制吗？",a="是的，此任务专为被遗忘者法师设计，作为他们达到十级左右初期水平时职业进阶的基石。",al={"这是法师专属任务吗","谁可以完成与安娜斯塔西娅谈话","职业要求"}},{q="为什么被遗忘者法师要在幽暗城保留他们自己的区域？",a="魔法区为被遗忘者的奥术师、术士和研究人员提供了一个专门的庇护所，让他们可以在远离物理区域的地方进行学习和施法，在洛丹伦的腹地延续他们第三次战争前的传统。",al={"为什么是魔法区","被遗忘者法师幽暗城"}}},fx={["34129032"]={q="凯恩·火歌为什么让你去找安娜斯塔西娅·哈特威尔？",a="凯恩·火歌在布瑞尔负责指导初学魔法的被遗忘者。你展现出足够的奥术技艺后，他就有责任将有前途的施法者引荐给幽暗城Magic Quarter的安娜斯塔西娅·哈特威尔。哈特威尔负责协调被遗忘者魔法组织更重要的事务，而凯恩则确保组织不断吸纳有能力、随时可以效力的成员。",al={"凯恩为什么派你去","凯恩·火歌的动机","为什么拜访安娜斯塔西娅·哈特威尔"}}},fp="20,370,27.496.0,29.442.0,47.178.0,38.152.0,36.183.0,40.160.0,41.163.0,67.227.0"}
P.entries["quest:1882"] = {n="巴尼尔农场",s="“巴尼尔农场”是年轻被遗忘者法师早期的一项试炼，由幽暗城法师区的安娜斯塔西娅·哈特威尔指导。新兵们被派往提瑞斯法林地东部，从一座离瘟疫之地边界极其危险的废弃农场中收集金鱼草。这些花卉样本可作为晴雨表，用于检测从天灾军团肆虐的东方蔓延而来的魔法腐蚀。",h="“巴尼尔农场”是年轻被遗忘者法师早期的一项试炼，由幽暗城法师区的安娜斯塔西娅·哈特威尔指导。新兵们被派往提瑞斯法林地东部，从一座离瘟疫之地边界极其危险的废弃农场中收集金鱼草。这些花卉样本可作为晴雨表，用于检测从天灾军团肆...",kw={"安娜斯塔西娅","巴尼尔","农场","哈特威尔","法师","瘟疫之地","金鱼草","提瑞斯法","幽暗城"},ang={["class:Mage"]="这次早期的试炼教会了新手法师，他们对奥术的研究对于监测和防御外来的魔法腐蚀至关重要。",["profession:Herbalism"]="巴尼尔金鱼草提供了一个例子，说明植物样本如何能够成为魔法污染的直接蓄积池和指示器。",["race:Undead"]="对于被遗忘者来说，保护提瑞斯法林地的边界免受天灾军团的侵害，事关他们的生存和主权。"},sec={{t="一种魔法晴雨表",b="尽管皇家药剂师学会经常研究死灵术和腐朽的影响，但被遗忘者的法师们也一直密切注视着边境地区。安娜斯塔西娅·哈特威尔指派新手施法者前往提瑞斯法林地东部的巴尼尔农场。农场花园中土生土长的金鱼草天生对变动的魔法流非常敏感，会从土壤和大气中吸收环境能量。通过检查这些花朵，幽暗城的奥术学者们就能测量巫妖王领地的腐蚀性传染是否已经穿过亡灵壁垒渗透到了提瑞斯法。"},{t="东部边界",b="巴尼尔农场坐落在林地边缘，离西瘟疫之地那片被枯萎病蹂躏的荒野近得令人不安。被遗忘者深知巫妖王的瘟疫是一种无法控制且具有破坏性的力量，会主动腐蚀土地本身。虽然被遗忘者也利用自己的黑暗技艺，但不受控制的天灾军团腐蚀威胁着他们的领土边界和安全。安娜斯塔西娅打算将收集到的金鱼草交给药剂师，将奥术观察与炼金调查结合起来，以保卫洛丹伦收复的核心领土。"}},faq={{q="为什么安娜斯塔西娅·哈特威尔特别需要金鱼草？",a="巴尼尔金鱼草对周围的魔法力量具有独特的天然敏感性。因为它们直接从大地和空气中吸收能量，研究它们可以让被遗忘者法师确定附近的瘟疫之地产生的奥术和死灵枯萎是否正在污染提瑞斯法林地。",al={"为什么选择金鱼草","巴尼尔金鱼草的用途","金鱼草有什么用"}},{q="巴尼尔农场在哪里？",a="该农场位于提瑞斯法林地东部，靠近林地与西瘟疫之地枯萎前线接壤的边界。金鱼草生长在破旧农舍周围杂草丛生的地块和花园里。",al={"巴尼尔农场位置","巴尼尔农场在哪里","寻找巴尼尔农场"}},{q="安娜斯塔西娅·哈特威尔是谁？",a="安娜斯塔西娅·哈特威尔是一位著名的被遗忘者法师和训练师，居住在幽暗城的法师区。她指导新生的亡灵施法者，教导他们纪律、奥术平衡以及针对敌对势力的实际边境防御。",al={"安娜斯塔西娅·哈特威尔背景故事","安娜斯塔西娅是谁"}},{q="为什么被遗忘者法师关心阻止瘟疫？",a="虽然被遗忘者也在试验他们自己的瘟疫和枯萎病，但巫妖王那种具有传染性的天灾魔法被视为一种不受控制的变异。如果不加遏制，天灾军团的腐蚀将吞噬整个提瑞斯法林地，并损害被遗忘者的独立性。",al={"为什么阻止瘟疫","被遗忘者是否憎恨瘟疫"}},{q="收集花朵后会怎样？",a="在收到金鱼草后，安娜斯塔西娅准备将其交给幽暗城的药剂师。炼金术士和法师们会一起解剖这些样本，以评估土壤和植物群受到天灾军团腐蚀的程度。",al={"安娜斯塔西娅如何处理这些花","谁来接收金鱼草"}},{q="这个任务只限法师吗？",a="是的。这项任务是专门为年轻的被遗忘者法师提供的职业任务，他们已经完成了丧钟镇的初步课程，并到达了首都以证明他们对奥术理论的掌握。",al={"巴尼尔农场任务是法师专属吗","法师职业任务"}}},fp="20,416,19.614.0,18.566.0,58.297.0,38.248.0,26.261.0,53.269.0,51.231.0,34.219.0"}
P.entries["quest:1885"] = {n="米奈特·卡加德",s="Mennet Carkad是幽暗城的一个潜行者入门任务，旨在将有前途的特工引入死亡猎手组织。在Marion Call的指引下，渴望成为刺客的新人被召集前往幽暗城Rogues' Quarter深处，直接向Mennet Carkad汇报。",h="Mennet Carkad是幽暗城的一个潜行者入门任务，旨在将有前途的特工引入死亡猎手组织。在Marion Call的指引下，渴望成为刺客的新人被召集前往幽暗城Rogues' Quarter深处，直接向Mennet...",kw={"刺客","死亡猎手","亡灵潜行者","马里恩·考尔","mennet carkad","rogues' quarter","幽暗城"},ang={["class:Rogue"]="这次召唤标志着你从一个未经考验的扒手转变为死亡猎手（亡灵精英暗影网络）公认的一员。",["race:Undead"]="死亡猎手对亡灵的生存至关重要，他们猎杀血色十字军狂热分子和天灾军团残余，同时保护希尔瓦娜斯女王免受隐藏威胁的侵害。"},sec={{t="来自阴影的召唤",b="在幽暗城黑暗的走廊里，亡灵的秘密特工之间静静地流传着消息。当某个侦察兵或刺客引起了高层领导的注意时，就会发出邀请。Marion Call传下话来，称潜行者训练师中的重要人物Mennet Carkad已经亲自注意到了你。考虑到亡灵情报机构那致命的名声，无视这样的指令绝非明智之举。"},{t="加入死亡猎手",b="Mennet Carkad守在Rogues' Quarter阴暗的壁龛中，观察着新兵并评估他们的准备情况。那些听从他召唤的人不仅仅是加入了一个普通的盗贼工会；他们正在接受测试，以进入死亡猎手，即亡灵那令人闻风丧胆的间谍与刺杀组织。对于任何寻求从阴影中效忠黑暗女王的人来说，迅速服从仅仅是第一项基础测试。"}},faq={{q="Mennet Carkad是谁？",a="Mennet Carkad是幽暗城Rogues' Quarter内的一名潜行者训练师和死亡猎手负责人。他负责监管有前途的秘密特工，并代表亡灵领导层分配关键任务。",al={"mennet carkad背景故事","carkad是谁"}},{q="如果有人无视Mennet Carkad的召唤会怎样？",a="Marion Call警告说，你不会想知道那些无视Carkad召唤的人遭遇了什么。她并没有解释他们的确切下场。",al={"无视carkad","无视召唤的后果"}},{q="什么是死亡猎手？",a="死亡猎手是效忠于亡灵的精英潜行者、间谍和刺客组织。他们在幽暗城的阴影中行动，清除高价值目标，收集情报，并从血色十字军和天灾军团等敌人手中保卫洛丹伦。",al={"死亡猎手背景故事","死亡猎手是什么"}},{q="我在哪里可以找到Mennet Carkad？",a="Mennet Carkad位于幽暗城的Rogues' Quarter，周围通常有其他秘密特工、训练师和暗影工艺补给品。",al={"carkad位置","mennet carkad在哪里"}},{q="是谁发布了寻找Mennet Carkad的任务？",a="该任务由布瑞尔恐惧之末旅店的Marion Call指派，她注意到了你正在增长的技能，并警告你Carkad要求迅速服从。",al={"谁发布了这个任务","marion call任务"}},{q="向Mennet Carkad汇报后会发生什么？",a="向Mennet Carkad汇报后，你将直接开始为死亡猎手服务，任务将从证明你的狡诈和对亡灵事业的忠诚开始。",al={"carkad之后的下一个任务","carkad想要什么"}}},fx={f971228d={q="马里恩·考尔为什么让你去找Mennet Carkad？",a="马里恩·考尔说，Mennet Carkad已经注意到你，并希望与你会面。她催促你听从他的召唤，还阴沉地警告你那些拒绝召唤的人，却没有说明他们的下场。",al={"马里恩·考尔为什么要你完成这件事","为什么去找mennet carkad","马里恩·考尔的动机"}}},fp="13,256,26.446.0,25.425.0,21.216.0,56.140.0,26.268.0,31.150.0,46.154.0,44.173.0"}
P.entries["quest:1886"] = {n="亡灵哨兵",s="此项任务标志着那些试图加入死亡猎手（Deathstalkers）的新兵所面临的试炼。死亡猎手是幽暗城直接效忠于瓦里玛萨斯（Varimathras）的隐秘而致命的组织。这项任务由位于潜行者区（Rogues' Quarter）的梅内特·卡卡德指派，需要执行者展现冷酷无情的作风，去拦截一名过路的信使。完成此任务将开启通往被遗忘者势力内部更深层秘密计划的大门。",h="此项任务标志着那些试图加入死亡猎手（Deathstalkers）的新兵所面临的试炼。死亡猎手是幽暗城直接效忠于瓦里玛萨斯（Varimathras）的隐秘而致命的组织。这项任务由位于潜行者区（Rogues'...",kw={"阿斯托·哈德伦","死亡猎手","梅内特·卡卡德","rogues' quarter","银松森林（silverpine forest）","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="对于被遗忘者的潜行者来说，加入死亡猎手代表了国家公职的最高层级，将街头混混转化为效忠于瓦里玛萨斯（Varimathras）和黑暗女王的工具。",["faction:Horde"]="死亡猎手在深沉的秘密中行动，确保被遗忘者维持着至关重要的情报网络，同时让部落的南方盟友对他们更为阴暗的内部事务知之甚少。",["race:Undead"]="死亡猎手代表了洛丹伦内部安全的铁腕，对外部敌人和被遗忘者内部潜在的叛徒保持着警惕和多疑的监视。"},sec={{t="阴影中的考验",b="死亡猎手绝不会随意招募成员。这个秘密组织直接在恐惧魔王瓦里玛萨斯（Varimathras）的指挥下行动，既是被遗忘者的秘密警察，也是其精锐刺客军团。为了获得他们的青睐，怀揣抱负的特工必须展现出狡诈、审慎以及毫不犹豫铲除目标的决心。在潜行者区（Rogues' Quarter）幽暗的角落里，教官梅内特·卡卡德设定了一项旨在剔除弱者或滥好人的入门试炼。"},{t="拦截行动",b="新兵的目标是阿斯托·哈德伦，一名往返于幽暗城与银松森林（Silverpine Forest）之间的信使。卡卡德并未提供战术指导，将如何获取哈德伦的引荐信的方法完全交由执行者自己决定。任务的关键在于拦截阿斯托，夺取他的证件，并确保死亡猎手能让新兵伪装成预期的特使，去接触一名叫安德隆的接头人。"}},faq={{q="死亡猎手是什么组织？",a="死亡猎手是被遗忘者旗下的精锐潜行与暗杀分支。他们以幽暗城的潜行者区（Rogues' Quarter）为总部，负责间谍活动、秘密处决和情报收集，直接向瓦里玛萨斯（Varimathras）领主汇报。",al={"死亡猎手背景故事","死亡猎手是什么","亡灵潜行者"}},{q="梅内特·卡卡德是谁？",a="梅内特·卡卡德是一位在幽暗城潜行者区（Rogues' Quarter）活动的死亡猎手教官。他负责监督早期的选拔，并测试那些渴望加入他们隐秘行列的招募者。",al={"梅内特·卡卡德的角色","任务提供者"}},{q="梅内特为什么要得到阿斯托·哈德伦的信件？",a="阿斯托·哈德伦是一名往返于银松森林（Silverpine Forest）与幽暗城之间的信使。夺取他的引荐信，能让死亡猎手以新特工替换哈德伦，从而欺骗一位名叫安德隆的同伙。",al={"阿斯托·哈德伦的信","为什么要拦截信使","阿斯托的引荐信"}},{q="阿斯托·哈德伦往返于哪里？",a="阿斯托·哈德伦沿着连接幽暗城与银松森林（Silverpine Forest）的小路行进，代表他的联络人传递地区间的信件。",al={"阿斯托·哈德伦的路线","阿斯托·哈德伦的位置","阿斯托在哪里"}},{q="瓦里玛萨斯（Varimathras）领主是谁？",a="瓦里玛萨斯是一位与希尔瓦娜斯·风行者（Sylvanas Windrunner）女王结盟以求自保的纳斯雷兹姆恐惧魔王。他从皇家区（Royal Quarter）负责监督幽暗城的安全、防务和潜行者行动。",al={"瓦里玛萨斯（varimathras）的角色","幽暗城的恐惧魔王"}},{q="这项试炼之后会发生什么？",a="通过试炼证明了执行者的能力，随后便会进入一项秘密伪装任务，即递交阿斯托的文书并渗透进安德隆的交易中。",al={"what comes next","死亡猎手任务线后续"}}},fx={["1398690a"]={q="Mennet Carkad为什么要你完成这件事？",a="Mennet Carkad正在执行一项渗透行动，关键是截获一封原本要交给名叫Andron的联络人的信件。只要偷走Astor Hadren的信，Mennet就能获得所需的凭据，让一名行动人员悄无声息地取得Andron的信任。",al={"mennet为什么需要这件事","mennet carkad的动机","为什么偷信"}},["763d70d5"]={q="Astor Hadren是谁？",a="Astor Hadren是一名往返于银松森林和幽暗城之间的信使。他带着一封写给名叫Andron的联络人的介绍信，却不知道死亡猎手正盯上他的信件，打算将其用于自己的秘密计划。",al={"hadren是谁","astor hadren","astor hadren的目标"}},f8c6b26b={q="Mennet Carkad为什么派你去，而不派一名资深特工？",a="你正努力证明自己有资格加入死亡猎手——这支为Lord Varimathras效力的精锐盗贼队伍。Mennet有意让有志加入的新人参加危险且可牺牲的实地考验，借此判断他们是否具备加入组织所需的机敏与致命手段。",al={"为什么选我加入死亡猎手","为什么派我去找mennet","为什么不用现有的死亡猎手成员"}}},fp="17,363,21.480.0,16.414.1,26.240.0,21.173.0,43.231.0,31.151.0,24.201.0,30.158.1"}
P.entries["quest:189"] = {n="血顶巨魔的耳朵",s="藏宝海湾的科博克因为与血顶巨魔在丛林中的冲突，损失了许多守卫和特工。由于开支不断攀升，他担心无法向大财主里维加兹交代，因此愿意出钱聘请冒险者去猎杀巨魔并带回战利品作为凭证。",h="藏宝海湾的科博克因为与血顶巨魔在丛林中的冲突，损失了许多守卫和特工。由于开支不断攀升，他担心无法向大财主里维加兹交代，因此愿意出钱聘请冒险者去猎杀巨魔并带回战利品作为凭证。",kw={"血顶","藏宝海湾","耳朵","科博克","里维加兹","荆棘谷","巨魔"},sec={{t="不断增长的开支",b="在繁忙的藏宝海湾港口，科博克正面临着严峻的经营困境。荆棘谷当地的巨魔一直在丛林中杀害他的特工，在与他们的冲突中，他失去了许多最精锐的守卫。随着伤亡人数的增加，开支也随之水涨船高，这让他对如何向大财主里维加兹解释这些费用感到焦头烂额。"},{t="限额悬赏",b="为了防止损失进一步扩大，科博克转而寻求外援。他向那些愿意深入丛林、猎杀血顶巨魔，并带回十五只巨魔断耳作为确凿击杀证明的旅行者提供金钱奖励。"}},faq={{q="科博克是谁？",a="科博克是藏宝海湾的一名地精，他在丛林中派驻了特工和守卫，且必须向大财主里维加兹汇报相关的开支。",al={"科博克","科博克是谁","谁发放血顶巨魔耳朵的任务"}},{q="为什么科博克需要血顶巨魔的耳朵？",a="血顶巨魔一直在丛林中杀害他的特工，并且他在与巨魔的冲突中损失了许多最精锐的守卫。开支正在不断增加，而他却无法向大财主里维加兹做出合理解释。",al={"为什么要耳朵","为什么要血顶巨魔的耳朵","为什么要收集耳朵"}},{q="需要多少只耳朵？",a="科博克要求你上交十五只血顶巨魔的耳朵，才会支付你的报酬。",al={"需要多少耳朵","耳朵数量"}},{q="这个悬赏后续会引向哪里？",a="当科博克为你上交的血顶巨魔耳朵支付报酬后，他会将注意力转向当地的另一个威胁：裂颅者獠牙。",al={"what comes next","血顶巨魔耳朵后续","下一个任务"}}},fp="15,256,14.341.0,16.271.0,13.134.0,36.197.0,27.77.0,33.123.1"}
P.entries["quest:1898"] = {n="亡灵哨兵",s="这项秘密任务会将一名卧底特工送入幽暗城的阴暗腹地，去审问一名毫无防备的同谋者。在瓦里玛萨斯领主的命令下，你将伪装成一名预期的信使，以揭露被遗忘者首都内部的叛乱。",h="这项秘密任务会将一名卧底特工送入幽暗城的阴暗腹地，去审问一名毫无防备的同谋者。在瓦里玛萨斯领主的命令下，你将伪装成一名预期的信使，以揭露被遗忘者首都内部的叛乱。",kw={"安德隆·甘特","apothecarium","阿斯托·哈德伦","死亡猎手","间谍活动","被遗忘者","梅内特·卡卡德","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="使用死者的身份渗透间谍网来诱捕大意的阴谋者，这是死亡猎手教科书式的谍报手段。",["faction:Horde"]="在幽暗城的表象之下潜藏着政治阴谋的巢穴，证明了即使在部落的边境之内，信任也是一种稀缺的商品。",["race:Undead"]="对于被遗忘者来说，警惕就是生存。任何被发现协助外部势力的公民都有可能面临黑暗女王秘密警察的立即清洗。"},sec={{t="欺诈之网",b="死亡猎手不仅仅是消除被遗忘者的外部威胁；他们还对自己的公民进行无情的监视。根据瓦里玛萨斯领主所持有的怀疑，死亡猎手梅内特·卡卡德制定了一项渗透计划。你带着伪造或获取的属于阿斯托·哈德伦的介绍信，任务是避开当地商人安德隆·甘特的怀疑。"},{t="Apothecarium 附近的商店",b="安德隆·甘特在 Apothecarium 散发着恶臭的烟雾和沸腾的大锅旁经营着一家商店。梅内特认为这个店主愚蠢且迟钝——根本没有眼力看穿伪装者。出示这封信能确立你作为信使的伪装，促使甘特急切地放松警惕，并主动透露关于他与一个身份不明的第三方交易的细节。"}},faq={{q="安德隆·甘特是谁？",a="安德隆·甘特是幽暗城 Apothecarium 附近的一名店主。由于涉嫌向一个未知的外部势力输送情报和提供援助，他已经引起了死亡猎手和瓦里玛萨斯领主的严密监视。",al={"安德隆·甘特","甘特是谁","安德隆·甘特在哪里"}},{q="为什么瓦里玛萨斯领主对这个商人感兴趣？",a="瓦里玛萨斯怀疑甘特在与被遗忘者之外的组织勾结。为了保卫城市并根除潜在的颠覆活动，这位恐惧魔王要求得到关于甘特联系人和意图的具体证据。",al={"为什么瓦里玛萨斯关心","瓦里玛萨斯 安德隆·甘特","为什么监视安德隆"}},{q="玩家如何欺骗安德隆·甘特？",a="梅内特·卡卡德给了你阿斯托的介绍信。因为甘特一直在等待一名信使，且被死亡猎手认为不够精明，所以向他出示这些证件足以获得他的信任。",al={"阿斯托的信","如何欺骗安德隆·甘特","伪装信使"}},{q="死亡猎手是什么组织？",a="死亡猎手是被遗忘者的精英潜行者组织和秘密情报机构。他们在希尔瓦娜斯女王和瓦里玛萨斯领主的指挥下，潜伏于阴影之中，负责根除煽动叛乱者、破坏敌方行动并消除内部威胁。",al={"死亡猎手背景知识","死亡猎手是什么","幽暗城潜行者"}},{q="在哪里可以找到安德隆·甘特？",a="他住在幽暗城 Apothecarium 区入口附近的一家商店里，在皇家药剂师学会和死亡猎手的严密监视下经营生意。",al={"安德隆·甘特位置","甘特的商店在哪里"}},{q="甘特接受这封信后会发生什么？",a="甘特毫不怀疑地接受了这封信，认为你只不过是一个无足轻重的信使。他立即暗示了与共同熟人之间的持续合作，为获取他背叛的进一步证据铺平了道路。",al={"甘特在做什么","甘特的反应"}}},fx={["6d39edb7"]={q="Mennet Carkad为什么要调查Andron Gant？",a="Mennet Carkad是直接奉Lord Varimathras之命行事。这位恐惧魔王怀疑Andron Gant在幽暗城内部暗中向一个身份不明的敌对势力输送援助和情报。为保护被遗忘者的领导层免遭内部颠覆，Mennet需要确凿证据证明Gant叛变，并查明他效力的神秘组织身份。",al={"为什么调查andron gant","mennet carkad的动机","mennet为什么派我去找gant"}},["3bf738ba"]={q="Mennet Carkad为什么派你去，而不亲自前往？",a="Mennet Carkad已经亲自见过Andron Gant，因此他本人出面会立刻暴露任务。Gant会马上认出这名已知的死亡猎手成员。你手里有Astor Hadren的介绍信，Gant便没有理由怀疑你不是他原定要见的信使。",al={"mennet为什么需要我","mennet为什么不能和gant谈","为什么使用冒险者"}}},fp="17,276,15.416.0,30.377.1,19.228.0,52.214.0,40.225.0,33.235.0,31.189.0,43.228.1"}
P.entries["quest:1899"] = {n="亡灵哨兵",s="这项任务延续了死亡猎手在幽暗城对线人安德隆·甘特的欺骗。由于甘特仍然认为你是他所期待的信使，他交出了一本本应交给其秘密联系人的账本，而执行者却将其送到了位于Rogues' Quarter的Mennet Carkad手中。这次交易标志着任务从简单的询问转变为代表被遗忘者势力的更深层、更隐秘的行动。",h="这项任务延续了死亡猎手在幽暗城对线人安德隆·甘特的欺骗。由于甘特仍然认为你是他所期待的信使，他交出了一本本应交给其秘密联系人的账本，而执行者却将其送到了位于Rogues' Quarter的Mennet...",kw={"安德隆·甘特","刺客","死亡猎手","间谍活动","账本","mennet carkad","rogues' quarter","幽暗城"},ang={["class:Rogue"]="对于幽暗城中一名有抱负的潜行者来说，为Mennet Carkad处理敏感的信使任务是一项基本的谨慎测试，这证明了执行者能够在不引起不必要注意的情况下管理秘密资产。",["race:Undead"]="幽暗城的内部安全关乎绝对的生存；协助死亡猎手能够直接加强黑暗女王对首都的控制，以抵御活着的渗透者和敌对的亡灵。"},sec={{t="阴影中的信使",b="死亡猎手并不单纯依赖蛮力或暗影魔法；他们的行动在很大程度上依赖于平凡的账本、记录的名单以及细致的监视。在幽暗城活动的安德隆·甘特交出了一本塞满情报的个人账本，认为它会交到他秘密效忠的神秘雇主手中。由于被执行者的伪装所蒙蔽，甘特甚至要求将来仍由同一名信使负责，他从未怀疑过这本账本正直接流向死亡猎手。"},{t="Rogues' Quarter的情报",b="当账本被送到Rogues' Quarter的Mennet Carkad手中时，它所揭露的信息远超死亡猎手的预期。甘特的记录并非草草写就的笔记，而是提供了切实可行的线索，使Carkad能够扩大他们的调查范围。在像被遗忘者领域这样多疑且分裂的环境中，拥有经过验证的书面证据对于清除内部颠覆分子，并在外部威胁袭击首都之前对其进行监控至关重要。"}},faq={{q="安德隆的账本里有什么？",a="这本账本包含了安德隆·甘特收集的敏感信息和记录。虽然具体内容没有被宣读，但Mennet Carkad指出，它所包含的细节和有价值的情报远比死亡猎手最初预期他能提供的要多。",al={"安德隆的账本内容","账本上写了什么","死亡猎手账本"}},{q="谁是死亡猎手？",a="死亡猎手是被遗忘者首屈一指的秘密组织和刺客公会。他们以幽暗城的Rogues' Quarter为总部，充当Sylvanas Windrunner的耳目和暗刃，负责整个洛丹伦的间谍活动、情报搜集和定点清除任务。",al={"死亡猎手背景故事","谁是死亡猎手","幽暗城潜行者"}},{q="为什么甘特希望将来继续使用同一名信使？",a="在幽暗城昏暗、充满不信任的氛围中，找到一名能够在不窃取或篡改敏感文件的情况下进行运送的执行者实属难得。甘特明确要求未来的业务由同一名跑腿者处理，以最大限度地降低风险并维持他既定的工作安排。",al={"为什么甘特信任你","安德隆·甘特的信任","甘特的信使"}},{q="Mennet Carkad是谁？",a="Mennet Carkad是驻扎在Rogues' Quarter的一名资深死亡猎手。他负责协调当地特工，从像安德隆·甘特这样的线人那里收集现场情报，并指挥首都及周边地区的秘密任务。",al={"mennet carkad背景故事","carkad是谁"}},{q="Rogues' Quarter位于何处？",a="Rogues' Quarter是幽暗城的南部区域。它是被遗忘者潜行者、盗贼和刺客的主要基地，为他们提供训练场地和远离上层废墟公共广场的黑暗角落。",al={"rogues' quarter位置","rogues' quarter在哪里","幽暗城rogues' quarter"}},{q="为什么被遗忘者需要一个内部情报机构？",a="被天灾军团、血色十字军和警惕的联盟残部四面环绕，年轻的被遗忘者国家面临着不断的渗透和叛乱威胁。死亡猎手铲除洛丹伦境内的一切颠覆活动，以确保这个新生的政权能够存续下去。",al={"为什么存在死亡猎手","被遗忘者间谍","幽暗城情报"}}},fx={["63e535f7"]={q="安德隆·甘特为什么想让你交付账册？",a="安德隆·甘特认定你是他一直向其提供情报的秘密联系人派来的信使。他把账册交给你转交，并请你告诉对方，如果他们想继续这项安排，就再派人来。他丝毫没有察觉，账册会直接落入亡灵哨兵手中。",al={"为什么要交付账册","安德隆·甘特的动机","安德隆为什么配合"}}},fp="17,411,24.506.0,35.465.1,27.270.0,26.299.0,55.305.0,21.265.0,37.248.0,57.274.0"}
P.entries["quest:19"] = {n="萨瑞尔祖恩",s="治安官马瑞斯为Tharil'zun悬赏，此人是潜伏在石堡要塞附近道路上骚扰过往行人的黑石氏族先遣队的狡诈首领。击杀他是在打破黑石氏族对赤脊山北部控制过程中的关键一步。将他的人头带回湖畔镇，对这座腹背受敌的城镇守卫来说是一场来之不易的胜利。",h="治安官马瑞斯为Tharil'zun悬赏，此人是潜伏在石堡要塞附近道路上骚扰过往行人的黑石氏族先遣队的狡诈首领。击杀他是在打破黑石氏族对赤脊山北部控制过程中的关键一步。将他的人头带回湖畔镇，对这座腹背受敌的城镇守卫来说是一...",kw={"黑石氏族","湖畔镇","治安官马瑞斯","先遣队","赤脊山","石堡","石堡要塞","tharil'zun"},ang={["faction:Alliance"]="在没有暴风城直接增援的情况下，湖畔镇基本上处于孤立状态，因此针对Tharil'zun的悬赏是一项至关重要的本地措施，旨在防止城镇被围困。",["race:Human"]="黑石氏族在赤脊山的存在是第一次和第二次战争带来的痛苦回忆，击杀Tharil'zun收复了被该氏族窃取的土地。",["race:Orc"]="Tharil'zun属于黑石旗帜下旧部落的黑暗残余势力，效忠于那些拒绝接受萨尔在海对岸建立的新秩序的主人。"},sec={{t="通往石堡之路",b="湖畔镇与石堡要塞之间蜿蜒的山口已经成为了伏击频发的险地。黑石氏族先遣队和叛军在岩石嶙峋的山脊上徘徊，切断了侦察兵的联系，并威胁着任何试图向要塞推进的援军。治安官马瑞斯认定Tharil'zun就是策划这些协同打击的指挥官，并宣称必须消灭他，以防止湖畔镇陷入彻底的包围。"},{t="斩首先遣队",b="Tharil'zun代表了一种危险的战场指挥官类型：凶残、狡诈，并且有能力将那些散乱的兽人劫掠者整合成一支有效的突袭部队。想要在石堡要塞的阴影下取他首级，就必须杀穿黑石氏族巩固的据点。他的死打破了先遣队巡逻的组织性，为联盟清理出了一条通往要塞内部并对抗守军的道路。"}},faq={{q="Tharil'zun是谁？",a="Tharil'zun是一位强大的黑石氏族兽人指挥官，负责领导在湖畔镇与石堡要塞之间的小径上进行伏击的先遣队和叛军。",al={"tharil'zun是谁","tharil'zun背景故事","tharil'zun首领"}},{q="在什么地方可以找到Tharil'zun？",a="Tharil'zun驻扎在赤脊山东北部的石堡要塞附近，指挥着巡逻周边山口和据点的先遣队。",al={"tharil'zun在哪里","tharil'zun位置","找到tharil'zun"}},{q="为什么治安官马瑞斯想要他的人头？",a="马瑞斯认出Tharil'zun是策划骚扰赤脊山伏击行动的狡猾战术家。索要他的人头可以确保先遣队的指挥系统被彻底摧毁，并为消除这一威胁提供无可辩驳的证据。",al={"为什么要杀tharil'zun","tharil'zun悬赏原因"}},{q="击败Tharil'zun之后会发生什么？",a="消灭Tharil'zun会削弱先遣队的协同能力，让湖畔镇的守军和冒险者能够更深入地挺进石堡要塞，对抗那里的黑石氏族主力守军。",al={"tharil'zun之后的任务","tharil'zun之后会有什么"}},{q="为什么黑石氏族兽人会出现在赤脊山？",a="黑石氏族的残部从燃烧平原向南推进进入了赤脊山，巩固了像石堡要塞这样的人类旧据点，在暴风城的军事力量捉襟见肘时威胁着整个东部王国。",al={"为什么黑石兽人在赤脊山","石堡兽人背景"}},{q="在狩猎Tharil'zun之前必须完成什么前置条件？",a="治安官马瑞斯要求冒险者先在“黑石氏族的威胁”任务中削减入侵势力的力量以证明自己的实力，然后才会派他们去对付Tharil'zun本人。",al={"tharil'zun前置任务","如何解锁tharil'zun任务"}}},fx={["3b83e264"]={q="治安官马瑞斯为什么需要萨瑞尔祖恩的头颅？",a="治安官马瑞斯要求拿到萨瑞尔祖恩的头颅，以确凿证明这名军阀已死。萨瑞尔祖恩狡诈而残暴，正指挥部下伏击湖畔镇的守军。整个地区的安危岌岌可危，马瑞斯无法依赖传言或错误的报告。",al={"萨瑞尔祖恩的头颅有什么用","萨瑞尔祖恩头颅的用途","为什么要取萨瑞尔祖恩的头颅"}},["66abe4be"]={q="治安官马瑞斯为什么派你去，而不是派镇上的卫兵？",a="湖畔镇的驻军已经不堪重负。暴风城扣下了援军，兽人的伏击又逼近城镇，治安官马瑞斯抽不出人手深入石堡境内。他只能依靠经验丰富、独立行动的冒险者，除掉敌方的重要指挥官。",al={"为什么派冒险者去","为什么不派赤脊山卫兵","马瑞斯为什么需要我"}}},fp="10,342,22.432.0,27.419.0,18.176.0,30.144.0,38.216.0,42.185.0,45.218.0,62.173.0"}
P.entries["quest:190"] = {n="猎豹",s="奈辛瓦里远征队营地的埃尔加丁爵士为那些想要证明自己是荆棘谷大型狩猎追踪者的冒险者们提供了一项试炼。为了加入赫米特的狩猎团，冒险者们必须先猎杀十只幼年黑豹，以此证明他们最基本的追踪能力。",h="奈辛瓦里远征队营地的埃尔加丁爵士为那些想要证明自己是荆棘谷大型狩猎追踪者的冒险者们提供了一项试炼。为了加入赫米特的狩猎团，冒险者们必须先猎杀十只幼年黑豹，以此证明他们最基本的追踪能力。",kw={"赫米特","奈辛瓦里","黑豹的掌控","埃尔加丁爵士","荆棘谷","幼年黑豹"},sec={{t="精英猎手小队",b="在荆棘谷北部广袤的荒野中，赫米特·奈辛瓦里集结了一群经验丰富的大型猎物猎人。任何想要参与狩猎的人，埃尔加丁爵士都会告诉他们：必须先证明自己是一名合格的黑豹猎手。"},{t="追踪潜行者",b="在埃尔加丁把更重要的猎物交给任何人之前，他会发布一个入门测试：找到并杀死十只幼年黑豹。仅仅找到这些野兽只是挑战的一半。"}},faq={{q="谁发布了这个狩猎挑战？",a="埃尔加丁爵士在荆棘谷北部的奈辛瓦里远征队营地发布了这个挑战，旨在测试想要加入赫米特狩猎队的后来者。",al={"黑豹的掌控任务发布者","谁开启黑豹的掌控","埃尔加丁任务"}},{q="需要猎杀什么猎物？",a="埃尔加丁爵士要求猎人们追踪并杀死潜伏在周围丛林灌木丛中的十只幼年黑豹。",al={"黑豹的掌控杀什么","黑豹的掌控目标","幼年黑豹"}},{q="为什么埃尔加丁爵士要布置这个测试？",a="赫米特·奈辛瓦里聚集了一支经验丰富的狩猎队，而埃尔加丁希望新人在加入狩猎之前证明自己是合格的黑豹猎手。",al={"为什么要杀幼年黑豹","黑豹的掌控目的"}},{q="完成这次狩猎后接下来要做什么？",a="完成这个入门试炼后直接开启“黑豹的掌控（2）”，届时埃尔加丁爵士会提高猎物的难度。",al={"黑豹的掌控后续任务","黑豹的掌控之后是什么"}}},fp="15,276,24.247.0,21.169.0,33.170.0,27.114.0,45.151.0,43.133.0"}
P.entries["quest:191"] = {n="猎豹",s="埃尔加丁爵士要求你证明自己有资格加入奈辛瓦里远征队营地的大型狩猎者行列。在你初步捕杀了年轻的野兽之后，他向你发出挑战，要求你在荆棘谷的荒野中追踪并击杀十只成年黑豹。",h="埃尔加丁爵士要求你证明自己有资格加入奈辛瓦里远征队营地的大型狩猎者行列。在你初步捕杀了年轻的野兽之后，他向你发出挑战，要求你在荆棘谷的荒野中追踪并击杀十只成年黑豹。",kw={"大型狩猎","埃尔加丁","狩猎","猎杀","奈辛瓦里","黑豹","荆棘谷"},sec={{t="更高的标准",b="在处理完丛林周围的幼年黑豹后，埃尔加丁爵士要求你提高目标。为了证明你有资格与经验丰富的大型狩猎者为伍，你被派去猎杀十只成年黑豹，它们比幼崽要强壮且危险得多。"}},faq={{q="谁提供了这次试炼？",a="埃尔加丁爵士，一位驻扎在荆棘谷北部奈辛瓦里远征队营地的猎人，负责监督狩猎的这一阶段。",al={"谁发布了黑豹的猎杀","埃尔加丁任务","任务发布者"}},{q="你需要猎杀什么样的猎物？",a="你被要求追踪并击败丛林周围的十只成年黑豹，它们比之前作为目标的幼年个体更为强壮。",al={"要杀什么黑豹","哪些野兽","黑豹的猎杀目标"}},{q="这项挑战之前是什么？",a="这紧随一项早期的试炼（同样名为“黑豹的猎杀”），在该试炼中，埃尔加丁考验了你对抗丛林幼年黑豹的勇气。",al={"前置任务","前一步骤","黑豹的猎杀前提条件"}},{q="猎杀这些黑豹的目的是什么？",a="埃尔加丁爵士需要你证明自己有技巧和毅力，可以与远征队中经验丰富的大型狩猎者进行交流并并肩狩猎。",al={"为什么要杀黑豹","埃尔加丁的动机","奈辛瓦里的目的"}}},fp="15,258,17.289.0,22.130.0,34.151.0,33.129.0,46.154.0"}
P.entries["quest:1918"] = {n="被污染的水元素",s="在击杀密斯特拉湖周围狂躁的水元素后，冒险者们发现了一个散发着污秽光芒的被污染的水球。为了弄清是什么毒害了湖泊及其元素之灵，他们将样本带回了碎木岗哨，交给了马斯托克·维尔西斯。",h="在击杀密斯特拉湖周围狂躁的水元素后，冒险者们发现了一个散发着污秽光芒的被污染的水球。为了弄清是什么毒害了湖泊及其元素之灵，他们将样本带回了碎木岗哨，交给了马斯托克·维尔西斯。",kw={"灰谷","被污染的水球","被腐蚀的元素","大地之环","马斯托克·维尔西斯","密斯特拉湖","碎木岗哨"},ang={["class:Shaman"]="密斯特拉湖元素扭曲的状态是萨满们严重关切的问题，他们能听到元素的痛苦，并认识到大地之环干预的必要性。",["faction:Horde"]="碎木岗哨无法容忍一个混乱的元素威胁在后院滋生，同时联盟哨兵和熊怪还在威胁着部落的补给线。",["race:Tauren"]="牛头人旅行者有一种深层的文化责任感，要去治愈这片土地上被污染的水域，这使得修复密斯特拉湖成为了一项紧迫的精神任务。"},sec={{t="密斯特拉湖的污染之水",b="位于灰谷中南部的密斯特拉湖陷入了严重的危机。栖息在浅水区的水元素变得异常暴躁且明显受到了腐蚀。当被击倒时，它们的残骸留下的不是纯净的元素精华，而是奇怪的、散发着强烈光芒的恶臭液体。无论是什么样的腐蚀物盘踞在湖泊中，都集中在这些水球里，这表明这场骚乱绝非自然界的领地争端那么简单。"},{t="寻求碎木岗哨的建议",b="由于对这种邪恶魔法的本质一无所知，部落侦察兵只能求助于碎木岗哨的驻军。作为前哨站的指挥官之一，马斯托克·维尔西斯最初对送来的这个卑劣样本感到厌恶。他是一名军人而非学者，马斯托克很快意识到凡人的钢铁无法治愈病态的水源，于是他指引冒险者去寻找大地之环的元素专家。"}},faq={{q="被污染的水球里有什么？",a="这个球体中装着目前正在毒害密斯特拉湖的腐蚀物的恶心浓缩样本。它是由被杀死的元素的残骸形成的，证明了它们受到的精神腐蚀是物质且强效的。",al={"被污染的水球内容物","水球里有什么","密斯特拉湖水球"}},{q="这个任务从哪里开始？",a="该任务始于在灰谷中南部密斯特拉湖战斗时，从被激怒或被污染的水元素身上掉落的物品。",al={"去哪里找水球","如何开始被污染的元素任务","任务开始"}},{q="为什么马斯托克·维尔西斯不想处理它？",a="马斯托克·维尔西斯是一名专注于碎木岗哨军事生存和后勤的部落军官。他对于诊断病态的魔法水域毫无兴趣，这就是为什么他建议去寻找大地之环的原因。",al={"谁是马斯托克","为什么要和马斯托克谈话","马斯托克·维尔西斯的职责"}},{q="大地之环为什么会对这个感兴趣？",a="大地之环是一个致力于研究、安抚并恢复元素和谐的萨满组织。像密斯特拉湖这样的受腐蚀元素直接处于他们的精神管辖范围之内。",al={"为什么要找大地之环","大地之环的关联","谁是大地之环"}},{q="调查接下来会引向何处？",a="马斯托克指引你去找耶努萨克雷，他是大地之环的一位萨满，驻扎在灰谷西海岸的佐拉姆加前哨站，他可以妥善检查这件被污染的圣物。",al={"what comes next","被污染的元素后续任务","接下来要去哪里"}}},fp="20,271,30.470.0,30.429.1,40.219.0,28.140.0,53.222.0,44.208.0,39.175.1"}
P.entries["quest:192"] = {n="猎豹",s="奈辛瓦里远征队营地的埃尔加丁爵士向大型猎物猎人们发起挑战，要求他们追踪并猎杀荆棘谷中最致命的豹子。继你之前的试炼之后，你现在必须寻找并杀死十只影牙豹。",h="奈辛瓦里远征队营地的埃尔加丁爵士向大型猎物猎人们发起挑战，要求他们追踪并猎杀荆棘谷中最致命的豹子。继你之前的试炼之后，你现在必须寻找并杀死十只影牙豹。",kw={"大型猎物","奈辛瓦里","豹子大师","影牙豹","埃尔加丁爵士","荆棘谷"},ang={["class:Hunter"]="埃尔加丁直接向你作为大型猎物猎人的声望发起挑战，期待你精通这种丛林中最凶猛掠食者的追踪与猎杀。"},sec={{t="最致命的猎物",b="埃尔加丁爵士认为影牙豹是徘徊在荆棘谷丛林中最危险的猫科动物。要证明你作为一名真正追踪者的实力，你需要穿过茂密的灌木丛，追踪并猎杀十只这种难以捉摸的野兽，它们凶猛的习性使得猎杀它们比找到它们要困难得多。"}},faq={{q="谁提供了这次狩猎？",a="埃尔加丁爵士在北荆棘谷的奈辛瓦里远征队营地提供了这项挑战。",al={"谁给予豹子大师任务","豹子大师任务给予者","谁给予此任务"}},{q="你要猎杀什么野兽？",a="你需要猎杀十只影牙豹，埃尔加丁称它们为整个荆棘谷中最致命的豹子。",al={"我要杀什么","豹子大师的目标","哪种豹子"}},{q="这在狩猎试炼中处于什么位置？",a="这是豹子狩猎系列试炼中的第三个任务，紧接在第二个豹子大师试炼之后，在第四个试炼之前。",al={"在此任务之前的任务是什么","豹子大师任务链","前置任务"}}},fp="15,229,20.303.0,21.108.0,28.113.0,42.138.0"}
P.entries["quest:193"] = {n="猎豹",s="埃尔加丁爵士已经在荆棘谷北部为你设定了豹类狩猎的最终考验。既然你已经证明了自己对抗该地区豹类的实力，那么现在你要去寻找巴尔瑟拉，这是一种至今仍未被远征队捕捉到的狡猾掠食者。带回这头野兽的巴尔瑟拉的牙齿，将确立你作为真正狩猎大师的地位。",h="埃尔加丁爵士已经在荆棘谷北部为你设定了豹类狩猎的最终考验。既然你已经证明了自己对抗该地区豹类的实力，那么现在你要去寻找巴尔瑟拉，这是一种至今仍未被远征队捕捉到的狡猾掠食者。带回这头野兽的巴尔瑟拉的牙齿，将确立你作为真正狩...",kw={"巴尔瑟拉","巴尔瑟拉的牙齿","奈辛瓦里远征队营地","豹类大师赛","埃尔加丁爵士","荆棘谷"},sec={{t="难以捉摸的潜行者",b="在奈辛瓦里远征队营地，埃尔加丁爵士认为你的考验已接近完成。还需要最后一个目标来证明你对抗丛林掠食者的价值：一头名叫巴尔瑟拉的豹子。当这头野兽在荆棘谷的荒野中潜行时，它至今仍躲避着远征队成员的追捕。埃尔加丁要求你追踪这头伟大的潜行者，并获取巴尔瑟拉的牙齿作为你实力的证明。"}},faq={{q="谁提供了这个狩猎任务？",a="埃尔加丁爵士在荆棘谷北部的奈辛瓦里远征队营地发布了这个挑战。",al={"任务发布者","谁发布了豹类大师赛","埃尔加丁任务"}},{q="你要猎杀什么野兽？",a="目标是巴尔瑟拉，这头在丛林中潜行、至今仍未被远征队捕捉到的巨大豹子。",al={"目标是什么","巴尔瑟拉是谁","豹子目标"}},{q="需要什么战利品？",a="埃尔加丁爵士需要巴尔瑟拉的牙齿作为击败这头野兽的证据。",al={"什么证明","什么物品","巴尔瑟拉的战利品"}},{q="这次狩猎之前发生了什么？",a="这项挑战紧随豹类大师赛系列的第三项试炼之后，是在早期豹类狩猎基础上的延续。",al={"前序任务","豹类大师赛的前置条件"}}},fp="15,361,19.403.0,21.98.0,27.110.0,24.85.0,27.106.0"}
P.entries["quest:1938"] = {n="乌尔的暗影魔法研究论文",s="“乌尔的暗影魔法研究论文”是一个由暴风城Mage Quarter的高阶法师安多玛斯发布的任务。他派遣冒险者从叛逃法师摩根斯手中夺回一本被魔法封印的禁忌典籍，摩根斯带着它逃到了赤脊山的伊尔加拉之塔。",h="“乌尔的暗影魔法研究论文”是一个由暴风城Mage Quarter的高阶法师安多玛斯发布的任务。他派遣冒险者从叛逃法师摩根斯手中夺回一本被魔法封印的禁忌典籍，摩根斯带着它逃到了赤脊山的伊尔加拉之塔。",kw={"安多玛斯","伊尔加拉","摩根斯","暗影魔法","暴风城","论文","乌尔","法师圣殿"},ang={["class:Mage"]="暴风城的法师们非常重视内部纪律问题，他们委托受信任的施法者清理一名堕落至禁忌暗影魔法的同僚所造成的危险后果。",["class:Warlock"]="虽然肯瑞托和暴风城的法师们对乌尔关于暗影的研究感到恐惧，但术士们却经常觊觎书中封印的跨位面召唤和黑暗施法的力量。",["faction:Alliance"]="找回被盗的典籍既能保障赤脊山的边境免受摩根斯日益增长的魔法威胁，又能保护暴风城王国免受流亡奥术的侵害。"},sec={{t="塔中的分裂",b="很久以前，三位前途无量的法师曾在暴风城的法师区共同学习。随着时间推移，其中一人，摩根斯，屈服于黑暗艺术和暗影魔法的诱惑。尽管他的同伴们苦苦规劝他远离这种腐蚀性的力量，但他拒绝放弃自己的执念。他被正式逐出了城市的魔法组织，但他并没有空手而归——他偷走了一部由乌尔撰写的危险著作，乌尔是一位臭名昭著的大法师，他的研究超出了正统奥术的范畴。"},{t="堕落法师的巢穴",b="摩根斯在远离暴风城监视的地方建立了一个新的据点，占据了赤脊山高处的伊尔加拉之塔。高阶法师安多玛斯绝不能允许这种危险的知识留在一个修炼禁忌魔法的叛徒手中。安多玛斯委托联盟冒险者突破塔楼的防御，旨在封印被破解之前找回这本典籍。"},{t="完好的封印",b="在从伊尔加拉的图书馆找回论文并将其带回法师圣殿后，安多玛斯深感宽慰。他曾担心摩根斯已经解开了书中的保护性附魔，或者将其藏到了无法触及的地方。幸运的是，施加在“乌尔的暗影魔法研究论文”上的魔法封印依然稳固，阻止了这位流亡法师释放书中蕴含的灾难性秘密。"}},faq={{q="这篇论文是谁写的？",a="这篇论文由乌尔撰写，他是一位传奇的达拉然法师，以其对跨位面实体和暗影魔法的深奥研究而闻名。",al={"谁是乌尔","论文作者","乌尔的暗影魔法研究论文作者"}},{q="是谁偷走了“乌尔的暗影魔法研究论文”？",a="摩根斯，一位暴风城的前法师，他在堕落于黑暗魔法并被逐出法师圣殿时偷走了这本书。",al={"谁偷了这本书","谁拿走了论文","摩根斯的书"}},{q="这本书存放在哪里？",a="这本书存放在伊尔加拉之塔内的图书馆里，塔楼高耸在赤脊山，摩根斯在那里建立了他的新避难所。",al={"论文在哪里","伊尔加拉之塔的书籍位置","乌尔的论文在哪里找到"}},{q="摩根斯读过这本书吗？",a="没有。当论文被归还给高阶法师安多玛斯时，他确认施加在书上的保护封印依然稳固，这意味着摩根斯从未成功打开过它。",al={"摩根斯打开书了吗","论文被打开了吗","封印破了吗"}},{q="为什么暴风城的法师要收回这本书？",a="这本典籍包含了暗影魔法的深奥秘密，可能会给未经训练的人带来毁灭。暴风城的法师们认为，让它留在像摩根斯这样的叛徒手中实在太危险了。",al={"为什么要回收这本书","为什么论文很危险","安多玛斯的目标"}},{q="谁发布了这个任务？",a="该任务由高阶法师安多玛斯提供，他位于暴风城Mage Quarter的法师圣殿内。",al={"任务发布者","在哪里接乌尔的论文任务","安多玛斯的任务"}}},fp="29,140,21.361.0,22.319.0,12.356.1,23.129.0,40.136.0,23.129.0,37.130.1,49.193.0,21.88.0"}
P.entries["quest:1939"] = {n="高阶巫师安多玛斯",s="高等法师安多玛斯是一个简短的召唤，旨在引导联盟法师前往暴风城法师区的高塔顶端。高等法师安多玛斯是除了在废墟中的达拉然以外，王国中最杰出的大法师之一。",h="高等法师安多玛斯是一个简短的召唤，旨在引导联盟法师前往暴风城法师区的高塔顶端。高等法师安多玛斯是除了在废墟中的达拉然以外，王国中最杰出的大法师之一。",kw={"安多玛斯","奥术","达拉然","詹妮亚·坎农","mage quarter","暴风城","法师区高塔"},ang={["class:Mage"]="这次召唤标志着从詹妮亚·坎农指导下的常规法术练习，过渡到与暴风城最顶尖的大法师之一共同研究危险、专业的知识。",["faction:Alliance"]="随着达拉然的幸存法师们全神贯注于重建他们被毁的城市，联盟在很大程度上依赖暴风城自己的法师区来培养法师并对抗超自然的威胁。"},sec={{t="前往高塔的召唤",b="在暴风城的法师区内，学徒协调员詹妮亚·坎农会将有前途的施法者指引至法师区高塔的顶端。高等法师安多玛斯是南部王国中依然活跃的最资深的奥术施法者之一，他特别要求与那些准备好承担更重责任的初露锋芒的法师进行面谈。"},{t="达拉然之外的大师",b="随着北方魔法王国达拉然在第三次战争中沦为废墟，幸存的巫师们全都忙于重建工作，像安多玛斯这样的施法者就具有了至关重要的战略意义。由于无法轻易接触到紫罗兰城堡的图书馆，联盟只能直接依靠驻扎在暴风城内的资深大法师来研究古代威胁，并指导对阴暗、禁忌艺术的研究。"}},faq={{q="高等法师安多玛斯是谁？",a="高等法师安多玛斯是一位受人尊敬的资深法师，居住在暴风城法师区的高塔顶端。他的同僚公认他是达拉然之外，世界上最强大、知识最渊博的活跃施法者之一。",al={"安多玛斯是谁","安多玛斯背景故事","暴风城高等法师"}},{q="我在哪里可以找到高等法师安多玛斯？",a="他位于暴风城法师区螺旋高塔的顶端。",al={"安多玛斯位置","安多玛斯在哪里","找到高等法师安多玛斯"}},{q="詹妮亚·坎农为什么要让我去找他？",a="詹妮亚·坎农会发掘那些已经超越了基础指导水平、有前途的施法者，并将他们送往安多玛斯那里，以获得更高级的建议和进行专门的危险研究任务。",al={"为什么要找安多玛斯谈话","詹妮亚·坎农的引荐"}},{q="安多玛斯需要什么帮助？",a="安多玛斯招募有能力的法师来调查黑暗的奥术秘密，具体来说是派遣他们去取回一本危险的历史文献：《乌尔的暗影魔法研究论文》。",al={"安多玛斯任务线","安多玛斯想要什么"}},{q="为什么说达拉然“与世隔绝”？",a="詹妮亚的话反映了肯瑞托自第三次战争以来一直处于隐居状态。在天灾军团和燃烧军团摧毁了他们的城市后，达拉然的幸存巫师们转而专注于重建工作，很少有人参与外界事务。",al={"为什么达拉然与世隔绝","达拉然现状","达拉然发生了什么"}},{q="这个任务是法师专属的吗？",a="是的。这个召唤是联盟法师在进阶职业道路上专属训练和任务的一部分。",al={"非职业法师能做这个吗","法师专属任务"}}},fp="23,174,20.290.0,24.287.0,31.184.0,41.100.0,42.142.0,35.152.1,42.227.0,33.87.0"}
P.entries["quest:194"] = {n="猎龙",s="在荆棘谷北部的探险营地中，赫米特·奈辛瓦里向过往的旅行者发出挑战，要求他们证明自己在荒野中的实力。这位著名的猎人要求击杀十只荆棘谷迅猛龙，以测试你是否具备真正的狩猎天赋。",h="在荆棘谷北部的探险营地中，赫米特·奈辛瓦里向过往的旅行者发出挑战，要求他们证明自己在荒野中的实力。这位著名的猎人要求击杀十只荆棘谷迅猛龙，以测试你是否具备真正的狩猎天赋。",kw={"大型猎物猎人","赫米特·奈辛瓦里","迅猛龙狩猎","荆棘谷迅猛龙","荆棘谷"},ang={["class:Hunter"]="对于那些走在猎人道路上的人来说，赫米特·奈辛瓦里在荒野中的试炼是检验追踪和射击技巧的经典试金石。"},sec={{t="技能测试",b="在完成“欢迎来到丛林”任务并抵达丛林后，赫米特·奈辛瓦里会提出测试你的追踪和狩猎能力。他没有提供地图或方向指引，而是坚持认为亲自找到荆棘谷迅猛龙也是考验的一部分，并挑战你深入灌木丛，猎杀十只凶猛的野兽。"}},faq={{q="谁发布了这个狩猎挑战？",a="驻扎在荆棘谷北部探险营地的著名大型猎物猎人赫米特·奈辛瓦里发布了这项挑战。",al={"谁发布了迅猛龙狩猎","迅猛龙狩猎任务发布者","赫米特·奈辛瓦里迅猛龙"}},{q="你需要追踪哪些野兽？",a="你需要追踪并击杀散布在丛林荒野中的十只荆棘谷迅猛龙。",al={"哪种迅猛龙","迅猛龙狩猎要杀什么","迅猛龙狩猎的目标"}},{q="为什么赫米特拒绝告诉你迅猛龙的栖息地？",a="赫米特认为，追踪并定位猎物是成为一名真正的大型猎物猎人必经的考验，因此他让你完全依靠自己去寻找。",al={"迅猛龙在哪里","为什么不给迅猛龙的位置","迅猛龙位置"}},{q="这项考验之前有什么任务？",a="这项狩猎考验是在荒野中的初步问候任务“欢迎来到丛林”之后进行的。",al={"迅猛龙狩猎的前置条件","迅猛龙狩猎的前置任务","迅猛龙狩猎任务线起点"}}},fp="14,243,15.345.0,33.134.0,40.101.0,57.151.0,34.89.0"}
P.entries["quest:1940"] = {n="新鲜的蜘蛛丝",s="“新鲜的蜘蛛丝”是暴风城高阶法师安多玛斯委托给联盟新晋法师的一项试炼任务。为了获得与精通者身份相符的服装，施法者会被派遣至阴暗的暮色森林，从腐食隐居者身上采集优质的蛛丝。收集到的丝线需送往Mage Quarter的裁缝维恩·拉尔森处，以制作附魔长袍。",h="“新鲜的蜘蛛丝”是暴风城高阶法师安多玛斯委托给联盟新晋法师的一项试炼任务。为了获得与精通者身份相符的服装，施法者会被派遣至阴暗的暮色森林，从腐食隐居者身上采集优质的蛛丝。收集到的丝线需送往Mage...",kw={"安多玛斯","腐食隐居者","暮色森林","拉尔森裁缝店","法师长袍","新鲜的蜘蛛丝","巫师圣殿","维恩·拉尔森"},ang={["class:Mage"]="这项通过仪式连接了学徒生涯与真正的精通者阶段，确保每位暴风城法师所穿的长袍，都是由他们亲手克服的危险所化。",["faction:Alliance"]="暮色森林对于暴风城的子民来说仍然是一片危险的边境，要求法师必须走出首都的庇护，去获取稀有的区域资源。",["profession:Tailoring"]="维恩·拉尔森的方法展示了如何将高级野生怪物纤维转化为具有魔法亲和力的织物，其品质远超普通的羊毛或亚麻。"},sec={{t="精通者法衣",b="在巫师圣殿内，认可的标准不仅在于对奥术的掌握，还在于从业者所穿的礼服。高阶法师安多玛斯在学生脱离了学徒工作后，会指引他们去定制与精通者身份相符的法衣。法师不能简单地购买成品，必须亲自从危险的野兽身上采集新鲜、无瑕的蛛丝，以证明其实地能力和辨别力。"},{t="暮色森林的织布机",b="所需材料无法在普通的商人货摊上找到。它必须从潜伏在暮色森林闹鬼阴影中的剧毒腐食隐居者蜘蛛身上小心提取。收集齐八份优质样本后，将其带往城内Mage Quarter的拉尔森裁缝店，裁缝维恩·拉尔森已做好准备，将这些精致的丝线纺织成具有奥术意义的长袍。"}},faq={{q="谁会派遣法师执行这项任务？",a="暴风城巫师圣殿的负责人高阶法师安多玛斯，会将此任务交给那些证明了自己的奉献精神的施法者。",al={"谁给予新鲜的蜘蛛丝任务","新鲜的蜘蛛丝任务发布者","安多玛斯任务"}},{q="这种蛛丝是在哪里采集的？",a="蛛丝是从出没在暮色森林闹鬼森林和布满蛛网的空地中的腐食隐居者蜘蛛身上采集的。",al={"在哪里获取新鲜的蛛丝","蜘蛛位置","腐食隐居者位置"}},{q="谁用这种蛛丝制作长袍？",a="维恩·拉尔森，一位在暴风城Mage Quarter的拉尔森裁缝店工作的专业裁缝，负责编织和裁剪工作。",al={"谁编织蛛丝","维恩·拉尔森","拉尔森裁缝店"}},{q="为什么法师要用蜘蛛丝制作服装？",a="新鲜的蜘蛛丝具有天然的韧性和极细的织纹，能创造出轻便的布料，既能承载微妙的附魔，又不会增加施法者的负担。",al={"为什么使用蜘蛛丝","蜘蛛丝魔法长袍"}},{q="交付蛛丝后会发生什么？",a="在维恩检查过蛛丝并进行织造后，她会将制作完成的星结长袍交给法师。",al={"新鲜的蜘蛛丝后续任务","接下来发生什么"}},{q="暮色森林里的任何蜘蛛丝都可以吗？",a="不行。拉尔森裁缝店所编织的精妙附魔，需要专门从腐食隐居者身上小心提取的新鲜样本，那些更粗糙的蛛网是无法使用的。",al={"能使用普通蜘蛛丝吗","新鲜与普通蛛丝对比"}}},fp="20,202,22.336.0,20.304.0,35.135.0,28.102.0,34.102.0,42.158.0,37.113.0,44.141.0"}
P.entries["quest:1941"] = {n="法纹长袍",s="魔纹长袍标志着暴风城中心一位裁缝宏大的制作委托圆满完成。维恩·拉尔森展示了一件由精良材料编织而成的成品附魔长袍，这成为了她家族店铺引以为傲的展示品。对于初出茅庐的施法者来说，它是奥术造诣与人类精湛工艺的早期象征。",h="魔纹长袍标志着暴风城中心一位裁缝宏大的制作委托圆满完成。维恩·拉尔森展示了一件由精良材料编织而成的成品附魔长袍，这成为了她家族店铺引以为傲的展示品。对于初出茅庐的施法者来说，它是奥术造诣与人类精湛工艺的早期象征。",kw={"学徒长袍","裁缝","拉尔森裁缝店","mage quarter","魔纹长袍","暴风城","维恩·拉尔森"},ang={["class:Mage"]="对于在暴风城高塔中学习的法师学徒来说，穿上一件定制的魔纹长袍标志着正式步入严肃的实地研究和独立的法术施展阶段。",["faction:Alliance"]="从首都当地店铺为有前途的勇士配备装备，有助于在动荡的领土上展示暴风城的威望和自给自足能力。",["profession:Tailoring"]="维恩·拉尔森的作品展示了人类裁缝工艺的高标准，体现了世俗材料如何被编织以驾驭和调和不稳定的奥术力量。"},sec={{t="拉尔森裁缝店",b="在暴风城熙熙攘攘的Mage Quarter，拉尔森裁缝店迎合了那些需要适合引导狂暴能量的服饰的奥术修行者。制作精良的魔法长袍需要稀有的材料、一丝不苟的针法，以及对那种在神秘共鸣下不会脱线的织线工艺的敏锐眼光。维恩·拉尔森对出自她店铺的每一件服饰都感到自豪，并将每一件在野外穿着的长袍都视为拉尔森家族名号的活招牌。"},{t="编织奥术",b="魔纹长袍旨在辅助法师学徒，提供舒适度、灵活性，以及在受争议的土地上漫游时所需的实际耐用性。在交付了必要的组件后，维恩亲自缝合了最后一针，将这件成品长袍不仅仅作为一笔交易，而是作为一件旨在吸引眼球并向整个王国宣传拉尔森裁缝工艺质量的杰作呈现出来。"}},faq={{q="谁制作了魔纹长袍？",a="维恩·拉尔森在位于暴风城Mage Quarter的拉尔森裁缝店制作这件服饰。",al={"谁制作了魔纹长袍","维恩·拉尔森长袍","拉尔森裁缝店"}},{q="为什么维恩·拉尔森希望你引以为傲地穿着这件长袍？",a="维恩认为这件长袍是她目前最精美的作品之一。她要求冒险者在其他人赞美其工艺时宣传拉尔森裁缝店，将其视为她店铺的活体广告。",al={"为什么要向人们介绍拉尔森","拉尔森广告","维恩对话"}},{q="拉尔森裁缝店位于何处？",a="该店铺位于暴风城的Mage Quarter，靠近联盟施法者聚集的学院和圣所。",al={"拉尔森店铺位置","维恩·拉尔森在哪里","法师区裁缝店"}},{q="魔纹长袍是什么样的服饰？",a="这是一件为魔法修行者设计的附魔布甲长袍，专为引导神秘能量而量身定制，同时在危险的旅途中提供实用的穿着体验。",al={"魔纹长袍背景故事","什么是魔纹长袍","长袍有什么用"}},{q="这是更长任务线的一部分吗？",a="是的。它结束了由詹妮亚·坎农开启的法师任务链：在调查了蓝色隐士旅店的法力裂隙后，你收集了亚麻布和充能裂隙宝石，以便维恩·拉尔森为你制作长袍。",al={"魔纹任务链","长袍任务线","任务线结尾"}},{q="哪个阵营可以执行此任务？",a="此任务严格仅限联盟成员，因为维恩·拉尔森完全是在暴风城首府内进行经营。",al={"联盟还是部落长袍","部落能获得魔纹长袍吗","阵营要求"}}},fp="14,194,16.354.0,13.339.0,30.94.0,59.203.0,34.127.0,41.156.0,35.182.0,38.114.0"}
P.entries["quest:1942"] = {n="星结之衣",s="星界结束腰是暴风城中一项专注的裁缝工艺的结晶。在冒险者深入野外收集到珍贵的新鲜的蜘蛛丝后，将其交给技艺精湛的裁缝维恩·拉尔森，最终打造出的成品是一件既适合险象环生的旅途，又适于高雅社交场合的精美魔法织物。",h="星界结束腰是暴风城中一项专注的裁缝工艺的结晶。在冒险者深入野外收集到珍贵的新鲜的蜘蛛丝后，将其交给技艺精湛的裁缝维恩·拉尔森，最终打造出的成品是一件既适合险象环生的旅途，又适于高雅社交场合的精美魔法织物。",kw={"星界结束腰","布甲","mage quarter","新鲜的蜘蛛丝","丝绸长袍","暴风城","裁缝","维恩·拉尔森"},ang={["class:Mage"]="星界结束腰将暴风城法师区的奥术尊严与在王国坚固城墙之外旅行时所需的实用附魔结合在了一起。",["faction:Alliance"]="暴风城的工匠们以能为联盟勇士提供既适用于皇家大厅，也适用于危险前线的装备而引以为傲。",["profession:Tailoring"]="维恩·拉尔森的作品代表了处理新鲜的蜘蛛丝的巅峰水平，展示了原始的怪物材料是如何被提炼成顶级时尚的。"},sec={{t="织造者的智慧",b="在熙熙攘攘的暴风城法师区，裁缝和绣娘们不仅服务于奥术精英，也为到访的贵族制作服饰。维恩·拉尔森就是这样一位工匠，她以将新鲜的蜘蛛丝编织成耐用且附魔的法袍而闻名。她素来以风趣幽默著称，在交付她那精巧的手工制品前，总会开玩笑说自己留了一些珍贵的丝绸碎料来装点自己的衣橱。"},{t="多功能优雅",b="星界结束腰受到那些对服装既有韧性要求、又追求精致感的布甲施法者的青睐。这件服饰由从危险蜘蛛身上采集的娇嫩而坚韧的丝线编织而成，既能抵御战斗的严酷考验，又能保持在暴风城要塞宴会上应有的光鲜亮丽。"}},faq={{q="什么是星界结束腰？",a="这是由维恩·拉尔森在暴风城手工缝制的一件精美服饰。它由新鲜的蜘蛛丝打造而成，专为布甲职业设计，既适用于冒险战斗，也适用于正式的社交场合。",al={"什么是星界结束腰","星界结长袍","星界结法袍"}},{q="谁制作星界结束腰？",a="维恩·拉尔森，暴风城法师区的一位裁缝，在获得所需的异域材料后可以制作这件装备。",al={"谁制作星界结","维恩·拉尔森任务","星界结裁缝"}},{q="完成这件服饰需要什么材料？",a="该服饰需要从世界各地荒野地区的致命蜘蛛身上采集的新鲜的蜘蛛丝，并通过能保留丝绸天然强度和附魔特性的裁缝技术将其编织在一起。",al={"星界结所需材料","需要蜘蛛丝","它是如何制作的"}},{q="为什么维恩·拉尔森会开玩笑说要留下多余的丝绸？",a="新鲜的蜘蛛丝在裁缝中非常稀有且珍贵。维恩总是开玩笑说她把衣服做得短一些，这样就能私藏一些边角料给自己，不过她最终还是会交付完整的成品。",al={"她偷了我的丝绸吗","维恩·拉尔森的笑话","短袍"}},{q="在暴风城的什么地方进行这种裁缝工作？",a="维恩·拉尔森位于暴风城的法师区，该区域是学者、奥术师和了解附魔纺织品的专业裁缝们的聚集地。",al={"维恩·拉尔森在哪里","星界结位置","在哪里上交星界结"}},{q="谁通常会穿戴星界结束腰？",a="联盟的法师们因其轻便、具备防护性的织造工艺以及庄重的外观，非常青睐并乐于获取这件服饰。",al={"谁使用星界结","这是什么职业用的","谁穿戴它"}}},fp="19,221,14.308.0,18.249.0,32.180.0,35.110.0,53.172.0,56.144.0,50.134.0,44.102.0"}
P.entries["quest:1943"] = {n="巨魔法师迪诺",s="“与迪诺交谈”是一项召唤任务，旨在指引有前途的部落法师前往奥格瑞玛寻找一位技术精湛的施法者。迪诺是一位在精神谷活动的巨魔法师，她需要一名高手代她执行至关重要的法术工作。回应她的召唤，将开启深入钻研奥术之路，并承担起遍布卡利姆多的艰巨任务。",h="“与迪诺交谈”是一项召唤任务，旨在指引有前途的部落法师前往奥格瑞玛寻找一位技术精湛的施法者。迪诺是一位在精神谷活动的巨魔法师，她需要一名高手代她执行至关重要的法术工作。回应她的召唤，将开启深入钻研奥术之路，并承担起遍布卡...",kw={"安娜斯塔西娅·哈特威尔","黑暗荆棘旅店","迪诺","法师任务","奥格瑞玛","quithas","valley of spirits","萨维亚之水"},ang={["class:Mage"]="此任务是你正统奥术训练中的关键一步，它将你与奥格瑞玛的高级施法者联系了起来。",["faction:Horde"]="这次召唤将洛丹伦和杜隆塔尔的地区训练师，与聚集在奥格瑞玛的奥术核心领导层连接在了一起。",["race:Troll"]="迪诺代表了暗矛部族中少数人所修习的、专注的奥术准则。"},sec={{t="前往奥格瑞玛的召唤",b="随着部落的奥术修行者们不断磨练自己的能力，导师们也会敏锐地察觉到学生何时准备好迎接更具挑战性的冒险。像幽暗城的安娜斯塔西娅·哈特威尔这样的导师，会将成长中的法师指引至奥格瑞玛。在那里，在那个巨魔聚居的区域深处，有着更专业的知识和危险的任务在等待着他们。"},{t="精神谷与黑暗荆棘旅店",b="迪诺居住在奥格瑞玛精神谷的黑暗荆棘旅店中。在暗矛巨魔中，专门从事奥术研究的修行者比起巫医和祭司相对较少，这使得迪诺成为了都城中一位显赫的权威。她不仅为当地事务奔走，更为了部落奥术修行者的长远利益，寻找那些愿意挑战遥远险境的有志法师。"}},faq={{q="是谁让你去与迪诺交谈的？",a="当法师达到足够的技能水平时，幽暗城魔法区（Magic Quarter）的法师训练师（例如安娜斯塔西娅·哈特威尔）会将他们派遣至奥格瑞玛。",al={"任务发布者","谁开启此任务","在哪里接到与迪诺交谈任务"}},{q="我在哪里可以找到迪诺？",a="迪诺位于奥格瑞玛西侧精神谷中的黑暗荆棘旅店里。",al={"迪诺位置","迪诺在哪里","黑暗荆棘旅店位置"}},{q="为什么迪诺需要帮助？",a="迪诺负责监督部落法师群体中至关重要的研究与任务。她征召有能力的施法者前往危险之地，以获取珍贵的奥术资源。",al={"迪诺为何需要帮助","迪诺想要什么"}},{q="向迪诺报到后会发生什么？",a="一旦你向迪诺报到，她会向你简要说明任务目标，并派遣你执行下一个任务，首先就是去收集萨维亚之水。",al={"下一个任务","之后是什么","后续任务"}},{q="这个任务所有职业都能接吗？",a="不能。此任务仅提供给部落的法师，作为他们职业进阶与训练的一部分。",al={"这是法师专属任务吗","术士能做吗","职业限制"}},{q="巨魔法师在部落中常见吗？",a="对于暗矛巨魔来说，奥术魔法并不像精神萨满教义、巫毒或洛阿祭司那样常见。然而，像迪诺这样的人物表明，一些巨魔已经彻底掌握了对奥术力量的正统研究。",al={"巨魔使用奥术","暗矛法师背景知识"}}},fx={["2e9f17ef"]={q="法师训练师为什么派你去找迪诺？",a="随着你对奥术的掌握日益深入，各大主城的导师意识到，常规训练之外还有更深奥的奥秘等待探索。奥格瑞玛的巨魔法师迪诺负责处理对部落法师群体至关重要的进阶事务。幽暗城的安娜斯塔西娅·哈特威尔等训练师会把有潜力的学徒引荐给她，让你为共同的技艺贡献力量。",al={"为什么派我去找迪诺","哈特威尔的任务动机","安娜斯塔西娅·哈特威尔为什么派我去"}}},fp="16,334,22.343.0,41.411.0,34.141.0,23.111.0,31.186.0,38.141.0,39.118.0,36.217.0"}
P.entries["quest:1944"] = {n="克萨维亚之水",s="“萨维亚之水”是一个部落法师任务，由奥格瑞玛的迪诺发布。为了探寻古老的精灵秘密，她指派学徒前往灰谷的萨维亚废墟，从那里最高的瀑布处取回样本。",h="“萨维亚之水”是一个部落法师任务，由奥格瑞玛的迪诺发布。为了探寻古老的精灵秘密，她指派学徒前往灰谷的萨维亚废墟，从那里最高的瀑布处取回样本。",kw={"灰谷","迪诺","瓶子","法师任务","奥格瑞玛","萨特","碎木岗哨","萨维亚之水","萨维亚"},ang={["class:Mage"]="此任务是部落法师专属的学习仪式，旨在测试他们冒险进入敌对荒野提取未受驯服的奥术试剂的能力。",["faction:Horde"]="碎木岗哨是部落在东灰谷最近的补给站，方便法师在萨维亚周围那片被萨特占据的荒野中穿行。"},sec={{t="法师的好奇心",b="在精神谷昏暗的裂隙中，巨魔法师迪诺一直在搜寻卡利姆多各地残留的原始奥术能量池。她的目光投向了萨维亚，这是一座隐藏在灰谷东部林冠深处的古老暗夜精灵城市。学者间的传说低语道，这座城市在天崩地裂前就沉浸于魔法知识之中，据说那里的水保留着强大的奥术特性，令现代施法者渴望解析。"},{t="萨维亚废墟",b="到达这些水源的源头绝非易事。萨维亚不再属于宁静的精灵贤者；它已沦为废墟，现在被野蛮、堕落的萨特占据，它们凶猛地守护着领地，抵御外来者。想一探究竟的法师必须穿过萨提纳尔，踏过危险的水道，在避开徘徊的野兽和恶魔哨兵的同时，在城市高耸的瀑布底部装满迪诺的瓶子。"}},faq={{q="谁是迪诺？",a="迪诺是一位巨魔法师训练师和学者，位于奥格瑞玛的精神谷。她负责指导部落法师，并调查古卡利姆多魔法的遗物。",al={"谁发布萨维亚之水任务","迪诺 奥格瑞玛"}},{q="萨维亚在哪里？",a="萨维亚是一座古老的废墟城市，位于灰谷东北部，碎木岗哨以北，萨特据点萨提纳尔的西北方。",al={"萨维亚位置","萨维亚在哪里","寻找萨维亚"}},{q="迪诺为什么要这种水？",a="学术记录声称萨维亚曾拥有广博的魔法知识，人们相信那里的水蕴含着残留的奥术力量。迪诺想要一份来自瀑布源头的新鲜样本来分析其特性。",al={"为什么获取萨维亚之水","萨维亚之水的用途"}},{q="萨维亚废墟由什么守卫？",a="废墟中到处都是萨特——那些厌恶入侵者并激烈捍卫领地以抵御窥探法师的恶魔化堕落生物。",al={"萨维亚的敌人","谁控制了萨维亚"}},{q="水样具体在哪里收集？",a="必须在萨维亚废墟内最高瀑布底部的池塘中，将水舀入迪诺的瓶子。",al={"瀑布位置","在哪里装满瓶子","萨维亚瀑布"}},{q="把样本还给迪诺后接下来要做什么？",a="迪诺对水样感到满意，随后派遣法师进行下一步的研究，涉及灰谷的树妖，任务名为“欢笑的姐妹”。",al={"萨维亚之水后续","萨维亚之水后的下一个任务"}}},fx={["6a4223ea"]={q="克萨维亚水样有什么用途？",a="古城萨维亚以失落的知识闻名于学者之间，据说那里的水蕴含着强大的魔力。迪诺需要一份未受污染的水样，必须直接从城中最高瀑布的底部取水，这样她才能回到奥格瑞玛研究其中潜藏的奥术特性。",al={"萨维亚的水有什么作用","为什么要收集萨维亚的水","萨维亚水样的用途"}}},fp="16,230,18.440.0,19.426.0,13.165.0,24.152.0,31.207.0,39.147.0,44.129.0,52.147.1"}
P.entries["quest:1945"] = {n="欢笑的姐妹",s="“欢笑姐妹”是一个部落任务，旨在派遣法师深入灰谷的腹地，从野生的树妖身上收集附魔的毛发。这些材料将交给十字路口的资深巨魔裁缝基尔哈拉，用来纺织成一件强化法袍。猎杀塞纳留斯的女儿们，凸显了部落施法者与古老林地原生守护者之间永无止境的摩擦。",h="“欢笑姐妹”是一个部落任务，旨在派遣法师深入灰谷的腹地，从野生的树妖身上收集附魔的毛发。这些材料将交给十字路口的资深巨魔裁缝基尔哈拉，用来纺织成一件强化法袍。猎杀塞纳留斯的女儿们，凸显了部落施法者与古老林地原生守护者之间...",kw={"灰谷","十字路口","迪诺","树妖","毛发","基尔哈拉","欢笑姐妹","林中树居","术士长袍"},ang={["class:Mage"]="这一成人礼教会了初出茅庐的法师，即使是灰谷神圣的林地灵魂也可以被收割，作为奥术工艺的材料。",["faction:Horde"]="击杀灰谷的树妖加剧了部落扩张势力与响应暗夜精灵号召的神圣森林守护者之间的冲突。",["profession:Tailoring"]="该任务强调了将鲜活的魔法纤维注入布甲的罕见艺术，展示了基尔哈拉在十字路口所采用的高等级技术。"},sec={{t="奥术编织",b="在努力确保萨维亚的水源后，那些初露头角的法师会受到奥格瑞玛的迪诺指引，去协助制作属于他们自己的附魔长袍。这种性质的奥术裁缝需要注入原始魔法精粹的材料。树妖的毛发天然就浸润着森林原始的生命力，具备了编织复杂魔法服饰所需的特质，从而能够保护并增强施法者的力量。"},{t="潜行于林中树居",b="为了收集这些毛发，法师必须向南前往灰谷的林中树居。欢笑姐妹——那些与暗夜精灵结盟的敏捷、林地树妖——会激烈地守护着这些树林，抵御伐木工和外来者的入侵。由于这些林地妖精绝不会心甘情愿地将毛发交给部落施法者，因此收集过程不可避免地会在古树的树冠下付出鲜血的代价。"},{t="裁缝的特权",b="毛发收集完成后，会被带往南方，穿过边界，送到贫瘠之地尘土飞扬的十字路口定居点。在那里，巨魔裁缝基尔哈拉毫无悔意地接收了这些贡品。虽然在承认失去林地生物时带有一丝讽刺意味，但基尔哈拉没有浪费时间，将这些附魔发丝投入到实际用途中，他深知部落的力量往往需要坚定不移的决心。"}},faq={{q="谁发布了猎杀“欢笑姐妹”的任务？",a="奥格瑞玛暗棘小屋的巨魔法师迪诺发布了这项任务，作为奖励和制作职业长袍的准备工作。",al={"谁发布欢笑姐妹任务","欢笑姐妹任务发布者","迪诺任务"}},{q="什么是欢笑姐妹？",a="欢笑姐妹是树妖，也就是半神塞纳留斯的女儿。她们拥有暗夜精灵女性的上身和小鹿的下身，保护着灰谷的林地和神圣的林中空地。",al={"什么是欢笑姐妹","欢笑姐妹树妖","欢笑姐妹是树妖吗"}},{q="在哪里可以找到欢笑姐妹？",a="她们游荡在灰谷中部的林中树居和欢笑姐妹林地附近的森林区域，距离贸易道路不远。",al={"欢笑姐妹位置","欢笑姐妹在哪里","去哪里找欢笑姐妹"}},{q="为什么基尔哈拉需要树妖的毛发？",a="树妖的毛发浸透了天然的附魔，是基尔哈拉编织专门用于奥术艺术的、具有魔法共鸣的长袍的理想线材。",al={"为什么需要树妖毛发","为什么要欢笑姐妹的毛发","毛发有什么用"}},{q="收集完毛发后，我该去哪里交付？",a="将毛发交给位于贫瘠之地繁华哨站十字路口的工艺裁缝基尔哈拉。",al={"基尔哈拉在哪里","欢笑姐妹任务交还","十字路口术士裁缝"}},{q="基尔哈拉拿到毛发后会发生什么？",a="在收到毛发后，基尔哈拉会花点时间处理这些材料，然后提供后续任务“虚空编织长袍”，以完成长袍的制作。",al={"欢笑姐妹后的下一个任务","欢笑姐妹之后","虚空编织长袍后续"}}},fx={["6db1d5c5"]={q="迪诺为什么派你去猎杀欢笑姐妹？",a="迪诺要奖励你一直以来为部落法师效力，于是安排为你制作专用法袍。她不会直接把法袍送给你，而是要求你亲自收集奇异的魔法试剂，派你深入灰谷，从森林的守卫者身上夺取树妖的头发。",al={"迪诺为什么要欢笑姐妹的头发","迪诺的动机：欢笑姐妹","为什么要收集欢笑姐妹的头发"}}},fp="16,400,18.431.0,18.412.0,24.410.0,51.141.0,30.199.0,40.135.0,34.164.0,49.117.0,43.160.0"}
P.entries["quest:1946"] = {n="虚灵长袍",s="虚空蕾丝法衣标志着裁缝基尔哈拉在贫瘠之地的专业制作工作告一段落。通过将收集到的树妖毛发编织成精美的布料，这位裁缝制作出了适合施法者的附魔服饰。",h="虚空蕾丝法衣标志着裁缝基尔哈拉在贫瘠之地的专业制作工作告一段落。通过将收集到的树妖毛发编织成精美的布料，这位裁缝制作出了适合施法者的附魔服饰。",kw={"灰谷","贫瘠之地","十字路口","迪诺","基尔哈拉","欢笑姐妹","法师","虚空蕾丝"},ang={["class:Mage"]="虚空蕾丝法衣是施法者进阶的一个重要里程碑，它连接了灰谷的荒野试炼与迪诺指导下基尔哈拉的精湛工艺。",["faction:Horde"]="从卡利姆多的圣林中获取组件来装备部落施法者，展示了部落与灰谷的林地守护者之间持续的对抗。",["profession:Tailoring"]="基尔哈拉的工艺展示了如何将诸如树妖毛发之类的奇异试剂纺织成带有先天魔法防护的织物。"},sec={{t="编织虚空蕾丝",b="基尔哈拉在贫瘠之地的十字路口工作，负责虚空蕾丝的精细制作工艺。这需要稀有且具有魔法共鸣的组件——特别是从灰谷中被称为欢笑姐妹的树妖身上采集到的发束——裁缝将天然的林地附魔直接融入舒适耐用的布料中。"},{t="奥格瑞玛的恩惠",b="除了单纯经营生意，基尔哈拉在确保服装质量方面还有个人的动机。他特别渴望讨好迪诺，一位居住在奥格瑞玛Valley of Spirits的受人尊敬的巨魔法师。通过为有抱负的施法者制作精良的服装，基尔哈拉希望获得并维持迪诺的好感。"}},faq={{q="什么是虚空蕾丝？",a="虚空蕾丝是由基尔哈拉制作的一种附魔织物。它由魔法材料编织而成，特别是使用了欢笑姐妹的发束，使其既坚韧又天然地充满了奥术共鸣。",al={"虚空蕾丝布料","什么是虚空蕾丝法衣"}},{q="谁制作虚空蕾丝法衣？",a="基尔哈拉，一位驻扎在贫瘠之地十字路口的熟练部落裁缝，在获得必要的灰谷树妖毛发后会制作这种服饰。",al={"谁制作虚空蕾丝","基尔哈拉 虚空蕾丝"}},{q="为什么基尔哈拉会提到迪诺？",a="迪诺是一位有影响力的巨魔法师训练师，居住在奥格瑞玛的Valley of Spirits。基尔哈拉渴望博得她的好感，并希望你对他裁缝手艺的满意能为他带来好评。",al={"谁是迪诺","为什么提到迪诺"}},{q="服饰的材料来自哪里？",a="核心材料是采集自欢笑姐妹的毛发，这是一群出没于灰谷森林中难以捉摸的树妖。",al={"虚空蕾丝材料","树妖毛发织物"}},{q="这件服饰是为谁制作的？",a="它主要是为施法者，特别是需要能够传导奥术能量且不影响行动的长袍的见习法师而制作的。",al={"谁使用虚空蕾丝法衣","虚空蕾丝职业"}},{q="基尔哈拉在哪里？",a="基尔哈拉居住在十字路口，这是一个位于贫瘠之地中心的中央枢纽定居点。",al={"基尔哈拉位置","基尔哈拉在哪里"}}},fp="19,223,23.343.0,20.351.0,20.207.0,35.155.0,32.208.0,50.126.0,29.151.0,26.107.0"}
P.entries["quest:195"] = {n="猎龙",s="在荆棘谷的丛林深处，赫米特·奈辛瓦里向猎人们发起挑战，要求他们去对付更危险的猎物。在完成早先的一次迅猛龙狩猎后，他指派冒险者们去追踪并击杀十只鞭尾迅猛龙。",h="在荆棘谷的丛林深处，赫米特·奈辛瓦里向猎人们发起挑战，要求他们去对付更危险的猎物。在完成早先的一次迅猛龙狩猎后，他指派冒险者们去追踪并击杀十只鞭尾迅猛龙。",kw={"格罗姆高营地","赫米特·奈辛瓦里","狩猎","鞭尾迅猛龙","迅猛龙狩猎","荆棘谷"},ang={["class:Hunter"]="对于追踪者和野兽猎手来说，赫米特·奈辛瓦里的挑战旨在考验他们面对荆棘谷中出没的致命捕食者时的基本狩猎素养。"},sec={{t="更严峻的挑战",b="在展示了初步的狩猎本领后，赫米特·奈辛瓦里希望大家不仅仅是围在营地的篝火旁虚度光阴。为了证明真正的专注与技巧，猎人们被派往格罗姆高营地以北茂密的丛林灌木丛中，去追踪并击杀十只凶猛的鞭尾迅猛龙。"},{t="炉边的战利品",b="从丛林中凯旋归来，将会赢得奈辛瓦里的热烈赞许。这位经验丰富的猎人认为这些危险的捕食者是很有价值的猎物，非常适合作为挂在炉火上方的战利品，他也正准备为冒险者提供更艰巨的挑战。"}},faq={{q="谁提供了这项狩猎挑战？",a="著名的大型猎物猎人赫米特·奈辛瓦里在荆棘谷北部的探险营地发出了这项挑战。",al={"谁开启了迅猛龙狩猎2","迅猛龙狩猎任务发布者","哪里领取迅猛龙狩猎"}},{q="你的狩猎目标是什么？",a="你接受的挑战是深入丛林，击杀十只鞭尾迅猛龙。",al={"要击杀什么迅猛龙","哪一个迅猛龙任务","鞭尾迅猛龙目标"}},{q="在哪里可以找到鞭尾迅猛龙？",a="鞭尾迅猛龙潜伏在荆棘谷北部荒野的丛林中，尤其是在格罗姆高营地的北面。",al={"鞭尾迅猛龙在哪里","鞭尾迅猛龙位置","到哪里寻找鞭尾迅猛龙"}},{q="这次狩猎在奈辛瓦里的考验中处于什么位置？",a="这是迅猛龙系列任务中的第二项考验，接在入门级的“迅猛龙狩猎”之后，并通向挑战的第三部分。",al={"这个迅猛龙狩猎之前有什么任务","迅猛龙狩猎任务进度","迅猛龙任务链"}}},fp="14,234,19.292.0,23.251.1,34.120.0,40.74.0,37.113.0,50.141.0"}
P.entries["quest:1950"] = {n="解封咒语",s="大法师提尔斯将一本至关重要的法术书锁在了他那施加了魔法封印的强效保险箱中，但他却记不起打开它的激活短语了。为了取回这本典籍，你必须在闪光平原赛道附近找到他失踪的学徒，并从他口中撬出那些被遗忘的咒语。",h="大法师提尔斯将一本至关重要的法术书锁在了他那施加了魔法封印的强效保险箱中，但他却记不起打开它的激活短语了。为了取回这本典籍，你必须在闪光平原赛道附近找到他失踪的学徒，并从他口中撬出那些被遗忘的咒语。",kw={"抢得先机","约翰逊","大法师提尔斯","沙漠赛道","闪光平原","保险箱","千针石林","魔杖任务"},ang={["class:Mage"]="与提尔斯打交道，既幽默又令人警醒，让人窥见了变形术的危险，以及强大的学者们可能会患上的健忘症。"},sec={{t="大法师与他的记忆",b="大法师提尔斯是一位古怪的施法者，居住在千针石林的闪光平原那干裂的盐碱地上。虽然他拥有进阶法师们梦寐以求的深奥知识和典籍，但与他打交道需要极大的耐心。提尔斯非常依赖助手来处理琐碎的细节，包括守护他奥术仓库的口头密码。当接到取回一本力量之书的任务时，前来拜访的修行者很快就会发现，提尔斯将那本书锁在了一个连他自己都已经完全忘记了开启咒语的保险箱里。"},{t="家禽的恶作剧",b="追踪提尔斯的学徒约翰逊并不是在沙漠赛道的围场里随便溜达那么简单。在询问了经营赛道的地精和侏儒之后，人们会发现约翰逊遭遇了服务一位反复无常的法师所带来的典型职业危害：变形。他被主人诅咒变成了一只普通的鸡，在盐滩上游荡，无法说话，直到有路过的旅行者靠近，打破了笼罩在他身上的魔法迷雾，他才能咯咯叫出那个丢失的密码。"}},faq={{q="谁是大法师提尔斯？",a="大法师提尔斯是一位隐居的人类法师，驻扎在千针石林的闪光平原，靠近沙漠赛道。他拥有先进的奥术学识，是那些希望磨练技艺的法师们寻找的目标。",al={"提尔斯背景故事","谁是大法师提尔斯","提尔斯闪光平原"}},{q="为什么提尔斯需要自己保险箱的密码？",a="提尔斯用一句咒语魔法封印了他的保险箱，本指望他的助手能记住这类琐碎的细节。但出于他那健忘的本性，当他的学徒失踪后，他立刻就忘记了那句咒语。",al={"为什么提尔斯忘记了","提尔斯保险箱密码"}},{q="学徒去哪了？",a="约翰逊没有跑远。他就在提尔斯营地东边的赛道附近徘徊，不过因为提尔斯把他变成了一只鸡，所以找到他变得有些复杂。",al={"寻找提尔斯的助手","学徒约翰逊在哪里","约翰逊位置"}},{q="为什么学徒被变成了鸡？",a="提尔斯在忘记自己做过这件事之前，对约翰逊施加了诅咒。在得知助手的遭遇后，提尔斯模糊地认为这学徒是因为不知感恩才落得如此下场。",al={"为什么约翰逊变成了鸡","提尔斯变形术学徒"}},{q="提尔斯的保险箱里有什么？",a="这个带有魔法封印的箱子里装着一本书，书中记载了法师继续进修和制作魔法道具所必需的仪式和说明。",al={"提尔斯保险箱内容","箱子里是什么书"}},{q="谁能执行这个任务？",a="此项差事是专门为那些寻求指导和材料以制作强力魔杖的法师所设计的试炼的一部分。",al={"非法师能做抢得先机吗","这是法师专属任务吗"}}},fx={["25c94f6f"]={q="大法师提尔斯为什么派你去，而不亲自寻找学徒？",a="既然是你求大法师提尔斯传授知识，他自然不会亲自去闪光平原搜寻。你前来求取他珍藏的魔法典籍，而他失去了助手，自己又想不起打开魔法封印宝箱的咒语，于是便以帮他找人为条件，换取他的帮助。",al={"为什么派我去","提尔斯为什么不去找约翰逊","为什么我必须去找学徒"}}},fp="13,283,22.549.0,9.526.1,19.201.0,48.218.0,28.167.1,45.186.1,33.143.0,28.138.0"}
P.entries["quest:1959"] = {n="向安娜斯塔西娅报告",s="“向安娜斯塔西娅报到”是一道发给卡利姆多和东部王国各地成长中的部落法师的征召令。幽暗城法师区的知名奥术师安娜斯塔西娅·哈特威尔在城内检测到了一股未知的魔法扰动，需要有能力的施法者前往调查。",h="“向安娜斯塔西娅报到”是一道发给卡利姆多和东部王国各地成长中的部落法师的征召令。幽暗城法师区的知名奥术师安娜斯塔西娅·哈特威尔在城内检测到了一股未知的魔法扰动，需要有能力的施法者前往调查。",kw={"安娜斯塔西娅·哈特威尔","凯恩·火歌","调查炼金房","法师","magic quarter","向安娜斯塔西娅报到","瑟斯顿·赞恩","安图瓦","幽暗城","尤塞尔奈"},ang={["class:Mage"]="这项任务是部落法师成长道路上的一个重要里程碑，它将修行者从地区的训练哨所中引出，带他们去接触洛丹伦废墟下酝酿的更深奥的奥术谜团——以及危险。",["faction:Horde"]="这次征召展现了被遗忘者与整个部落之间的协作交流，利用各个成员种族的魔法天赋来保护他们的共同利益。",["race:Undead"]="被遗忘者法师们被召回幽暗城的法师区，以帮助保护他们年轻的王国免受城墙内未知的奥术威胁。"},sec={{t="奥术的召唤",b="这个消息在部落施法者群体中迅速传开。无论是在雷霆崖的峭壁上、杜隆塔尔的燥热沙尘中，还是在洛丹伦废墟里，有足够天赋的法师们都会收到这道明确的指令。幽暗城的奥术修行者们感觉到有一股无法解释的扰动在他们的领地内回荡，他们需要地面的协助。"},{t="幽暗城的法师",b="安娜斯塔西娅·哈特威尔在幽暗城的法师区监管着奥术事务。当你抵达后，她证实了那个令人不安的消息：这座地下大都市内记录到了异常能量。由于这种魔法的性质完全未知——既未被证实是良性的，也不确定是否具有敌意——她需要一位专家悄悄调查其源头，并从城内的药剂区开始着手。"}},faq={{q="安娜斯塔西娅·哈特威尔是谁？",a="安娜斯塔西娅·哈特威尔是一位被遗忘者法师，也是驻扎在幽暗城法师区的奥术导师。她负责引导新手修行者，并时刻关注着被遗忘者首都内发生的奥术异常现象。",al={"安娜斯塔西娅·哈特威尔背景故事","安娜斯塔西娅是谁","哈特威尔幽暗城"}},{q="安娜斯塔西娅·哈特威尔在哪里？",a="她居住在幽暗城的法师区，位于这座地下城市北侧的圆环区域。你可以在其他施法者训练师和奥术研究员附近找到她。",al={"安娜斯塔西娅在哪里","哈特威尔位置","安娜斯塔西娅幽暗城地图"}},{q="为什么来自雷霆崖或贫瘠之地的法师会被征召到幽暗城？",a="尽管被遗忘者培养了自己的奥术专家，但异常的魔法异象威胁着整个部落在洛丹伦的存在。卡利姆多的导师们将他们有前途的学生派往幽暗城，以提供援助并获取处理复杂魔法现象的实战经验。",al={"为什么要去幽暗城","为什么要向安娜斯塔西娅报到","雷霆崖法师任务"}},{q="安娜斯塔西娅正在调查什么样的扰动？",a="法师们在城内探测到了无法解释的魔法波动。在发出这次征召时，安娜斯塔西娅·哈特威尔还无法确定这种能量是有敌意的、偶然产生的还是良性的，因此她发起了一次谨慎的调查。",al={"什么扰动","幽暗城魔法扰动","幽暗城出了什么问题"}},{q="谁会发布这个任务？",a="当施法者获得足够的经验后，各地的部落法师训练师都可以发布这道征召令，包括奥格瑞玛的尤塞尔奈、雷霆崖的瑟斯顿·赞恩、布瑞尔的凯恩·火歌以及森金村的安图瓦。",al={"谁发布向安娜斯塔西娅报到","向安娜斯塔西娅报到任务发布者"}},{q="向安娜斯塔西娅报到后会发生什么？",a="当你与安娜斯塔西娅交谈并听取简报后，她会立即指示你更深入地调查这一扰动，首先是通过任务“调查炼金房”来对城内的药剂区进行询问。",al={"向安娜斯塔西娅报到后续任务","向安娜斯塔西娅报到后续"}}},fx={["22ef3f4a"]={q="法师训练师为什么派你去找安娜斯塔西娅·哈特威尔，而不亲自处理？",a="训练师们需要教导初出茅庐的施法者，并在卡利姆多各处定居点维持魔法事务的监管。听闻被遗忘者法师需要协助，调查幽暗城内的奥术异象后，训练师们便找来有能力、前途可期且能够执行外勤任务的学徒，而不必离开教学岗位。",al={"为什么派我去找安娜斯塔西娅","训练师为什么不能去幽暗城","为什么让我向安娜斯塔西娅报告"}}},fp="19,292,20.385.0,25.418.0,26.229.0,36.183.0,80.273.0,52.238.0,21.220.0,42.221.0"}
P.entries["quest:196"] = {n="猎龙",s="赫米特·奈辛瓦里要求你猎杀一种难以捉摸的迅猛龙：丛林潜行者，以此提升他狩猎远征的难度。在荆棘谷成功追踪并猎杀十只这种狡猾的迅猛龙，将证明你作为一名真正的野兽追踪者所具备的实力。",h="赫米特·奈辛瓦里要求你猎杀一种难以捉摸的迅猛龙：丛林潜行者，以此提升他狩猎远征的难度。在荆棘谷成功追踪并猎杀十只这种狡猾的迅猛龙，将证明你作为一名真正的野兽追踪者所具备的实力。",kw={"大型狩猎专家","古拉巴什竞技场","赫米特·奈辛瓦里","丛林潜行者","迅猛龙大师","荆棘谷"},ang={["class:Hunter"]="在赫米特·奈辛瓦里的注视下，追踪像丛林潜行者这样机警的猎物，是展示追踪能力和荒野射击技巧的最佳方式。"},sec={{t="狡猾的猎物",b="在测试过你对付低等级迅猛龙的瞄准能力后，赫米特·奈辛瓦里提出了一个更具挑战性的猎物。丛林潜行者异常狡猾，比之前猎杀的品种更难追踪和击杀。赫米特希望你深入丛林，猎杀十只这种机警的掠食者，然后回到营地，以获得参与他最棒狩猎活动的资格。"}},faq={{q="谁提供了这次狩猎任务？",a="驻扎在荆棘谷北部的著名大型狩猎专家赫米特·奈辛瓦里发布了这项挑战。",al={"任务发布者","谁开启迅猛龙大师3","赫米特·奈辛瓦里狩猎"}},{q="你需要追踪哪种野兽？",a="你的任务是找到并击杀十只丛林潜行者，这是一种特别狡猾且难以捉摸的迅猛龙。",al={"什么迅猛龙","目标迅猛龙","要击杀哪种迅猛龙"}},{q="丛林潜行者在哪里出没？",a="丛林潜行者在荆棘谷游荡，特别是在古拉巴什竞技场以北和以西的区域。",al={"丛林潜行者位置","丛林潜行者在哪里游荡","寻找丛林潜行者"}},{q="这项挑战之前是什么任务？",a="这次狩猎紧随“迅猛龙大师”挑战的第二阶段，是赫米特·奈辛瓦里对当地迅猛龙品种狩猎进度的延续。",al={"前置任务","之前的迅猛龙大师","之前的任务是什么"}}},fp="14,245,14.349.0,21.110.0,39.112.0,32.116.0,33.148.0"}
P.entries["quest:1960"] = {n="调查炼金店",s="“调查炼金商店”是幽暗城的一个部落法师任务，要求解决Apothecarium内的一起奥术异常事件。在安娜斯塔西娅·哈特威尔的指导下，修行者们追踪并捕捉在Algernon的商店里四处游荡、由纯粹魔法能量构成的隐形生物。",h="“调查炼金商店”是幽暗城的一个部落法师任务，要求解决Apothecarium内的一起奥术异常事件。在安娜斯塔西娅·哈特威尔的指导下，修行者们追踪并捕捉在Algernon的商店里四处游荡、由纯粹魔法能量构成的隐形生物。",kw={"algernon","安娜斯塔西娅·哈特威尔","apothecarium","显形卷轴","收容箱","magic quarter","裂隙之源","幽暗城"},ang={["class:Mage"]="这项任务考验学徒对纯粹奥术力量的掌控力，要求使用专门的显形卷轴和收容容器，而不是单纯的破坏性力量。",["race:Undead"]="虽然被遗忘者的药剂师们专注于炼金术和瘟疫学，但这项任务凸显了幽暗城的奥术学者在保护城市免受魔法渗透方面的警惕性。"},sec={{t="Apothecarium的骚动",b="幽暗城对非自然现象并不陌生，但Apothecarium最近出现了一个纯粹源于奥术的问题。人们探测到看不见的魔法实体在Algernon的炼金商店中游荡，在冒泡的坩埚和有毒的试剂间无声穿行。幽暗城的法师导师安娜斯塔西娅·哈特威尔察觉到了魔法流中非自然的缺口，便指派有潜力的奥术新星前去调查并在灾难性后果发生前控制住这些实体。"},{t="显形与收容",b="由于这些实体是隐形的，且完全由原始奥术力量构成，普通的追踪方法毫无用处。安娜斯塔西娅为学生们配备了专门的“显形卷轴”来消除实体的隐形效果，并配发了坚固的收容箱。一旦现形，必须将这些不稳定的裂隙之源击倒，并将其安全封印在收容箱内，以免它们进一步失控或伤害正在工作的炼金术士。"},{t="事故还是奥术攻击？",b="在获取标本后，安娜斯塔西娅的担忧转向了它们的来源。环境魔法流中自发的裂隙已经足够令人烦恼，但如果是蓄意的缺口，则意味着有人正对被遗忘者的首都发动积极、协调的魔法攻击。捕获的生物被转交去进行研究，以确定Apothecarium究竟只是遭遇了一起奥术事故，还是正处于有针对性的威胁前线。"}},faq={{q="谁提供这个任务，我在哪里能找到他们？",a="该任务由安娜斯塔西娅·哈特威尔提供，她是驻扎在幽暗城Magic Quarter的法师训练师。",al={"任务发布者","任务起始地点","安娜斯塔西娅位置"}},{q="骚动发生在哪里？",a="骚动集中在Algernon的炼金商店周围，该商店位于幽暗城的Apothecarium区内。",al={"我该去哪里","炼金商店位置","algernon在哪里"}},{q="在商店里游荡的生物是什么？",a="它们是裂隙之源，是完全由浓缩魔法能量构成的隐形生物，通过当地魔法流中的异常现象显现出来。",al={"怪物是什么","隐形生物","裂隙之源"}},{q="你如何捕捉这些生物？",a="你必须在商店内吟唱“显形卷轴”以使裂隙之源现形，用咒语削弱它们，然后使用收容箱将它们困在里面。",al={"如何捕捉","使用收容箱","如何完成"}},{q="为什么安娜斯塔西娅想活捉这些生物？",a="安娜斯塔西娅和幽暗城的学者们需要活体标本，以确定魔法裂口是自然的随机裂隙，还是外部魔法势力对该城市的蓄意攻击。",al={"为什么要捕捉","收容箱用途","为什么要研究它们"}},{q="其他职业可以做这个任务吗？",a="不可以，此任务是专门针对部落法师的早期训练系列任务的一部分。",al={"法师专有","谁能接这个任务"}}},fx={["20993eae"]={q="显形卷轴有什么用途？",a="显形卷轴上刻有咒语，由安娜斯塔西娅·哈特威尔交给你，用来揭示不可见之物。阿尔杰农商店里的那些实体由纯粹的魔法能量构成，肉眼自然无法看见。在店内诵读卷轴上的咒语，会揭开它们的隐匿外衣，迫使它们显现实体，这样你就能与它们战斗并将其制服。",al={"显形卷轴的用途","为什么要使用显形卷轴","显形卷轴有什么作用"}},["355e23e2"]={q="封灵箱有什么用途？",a="一盒封灵箱中装有特制的结界容器，可用来束缚纯粹的魔法实体。药剂区出现的裂隙生物无法直接用手搬运，因此你必须等它们在战斗中变弱后，使用这些奥术容器将其封住，确保它们不会消散，方便运送。",al={"一盒封灵箱","什么是封灵箱","封灵箱的用途"}},["01d568c5"]={q="装满的封灵箱有什么用途？",a="每个装满的封灵箱都封存着一个从阿尔杰农商店捕获的活体裂隙生物。安娜斯塔西娅·哈特威尔需要你完好无损地带回三个封存的实体，好让幽暗城最杰出的奥术学者进行研究，查明它们突然显形究竟是魔法织网意外撕裂所致，还是有人蓄意发动袭击。",al={"装满的封灵箱有什么用","为什么要带回装满的封灵箱","装满的封灵箱的用途"}}},fp="30,277,33.479.0,29.435.0,27.417.1,46.109.0,33.123.0,42.144.0,33.168.0,55.195.0,43.101.0"}
P.entries["quest:1961"] = {n="收集原料",s="“收集材料”是幽暗城部落法师学徒的一项入职仪式。这项任务由安娜斯塔西娅·哈特威尔指派，要求学徒前往银松森林，从达拉然法师手中夺取奥术宝石，以此集齐制作第一件真正法师长袍所需的材料。",h="“收集材料”是幽暗城部落法师学徒的一项入职仪式。这项任务由安娜斯塔西娅·哈特威尔指派，要求学徒前往银松森林，从达拉然法师手中夺取奥术宝石，以此集齐制作第一件真正法师长袍所需的材料。",kw={"安伯米尔","安娜斯塔西娅·哈特威尔","达拉然法力宝石","收集材料","乔瑟夫·格里高利","亚麻布","magic quarter","法术火长袍","幽暗城"},ang={["class:Mage"]="这个任务是部落法师的一个关键里程碑，标志着他们告别了简单的学徒装束，穿上了编织着奥术力量的定制长袍。",["profession:Tailoring"]="这一过程彰显了如何将普通的亚麻布与强力的法力宝石结合，创造出持久的附魔服饰。",["race:Undead"]="这项使命展示了被遗忘者冷酷的世界观：如果达拉然的巫师们过于软弱而无法守住银松森林，那么曾经的同族情谊也换不来任何怜悯。"},sec={{t="奥术地位的试炼",b="在魔法区的奥术回廊中，法师学徒必须证明自己不仅能施展基础咒语，更具备真正的实力。为了获得他们的第一件法师长袍——一件标志着其地位和个人价值的正式礼服，学徒们会接到安娜斯塔西娅·哈特威尔的指派，去采集制作附魔织物所需的原材料：一卷普通的亚麻布和一套强力的达拉然法力宝石。"},{t="被遗忘者的实用主义",b="法力宝石无法通过购买或凭空变出，它们必须从驻扎在银松森林（尤其是安伯米尔附近）的达拉然法师身上强行夺取。安娜斯塔西娅·哈特威尔冷漠地指出，虽然达拉然的奥术哲学与他们不谋而合，但在幽暗城中，感性的犹豫毫无立足之地。在被遗忘者眼中，如果那些活着的法师没有实力守住他们的遗物，那么他们不仅会失去财宝，还会丢掉性命。"},{t="魔法区的裁缝",b="材料收集完毕后，布料和宝石将被送往魔法区的裁缝乔瑟夫·格里高利处。尽管格里高利坦言自己缺乏那种能鉴定达拉然附魔宝石纯度的魔法天赋，但他拥有将宝石原始力量直接编织进长袍布料中所需的罕见匠艺。"}},faq={{q="“收集材料”的目的是什么？",a="这个任务是部落法师的入职仪式。通过完成该任务，可以为裁缝乔瑟夫·格里高利提供所需的亚麻布和法力宝石，进而制作学徒的第一件正式附魔长袍。",al={"为什么要收集材料","收集材料任务目的","幽暗城法师长袍任务"}},{q="为什么安娜斯塔西娅·哈特威尔会派你去对付达拉然法师？",a="驻扎在银松森林的达拉然法师身上携带着能够传导强大魔法流的精炼法力宝石。哈特威尔以务实的态度看待这些活着的法师：尽管双方有着共同的知识根源，但如果他们在战场上表现出软弱，那么他们的生命和资源就注定要被被遗忘者夺走。",al={"为什么要杀达拉然法师","达拉然法力宝石背景","为什么要在银松森林找法师"}},{q="达拉然法师位于何处？",a="他们可以在银松森林中被发现，主要占据着瑟伯切尔东南部的哨所和营地，并以安伯米尔定居点为中心。",al={"哪里寻找达拉然法力宝石","银松森林法师位置","安伯米尔法师"}},{q="乔瑟夫·格里高利是谁？",a="乔瑟夫·格里高利是幽暗城魔法区的一名亡灵裁缝。虽然他是一位工匠而非奥术施法者，但他专精于缝制法术火长袍之类的附魔服饰。",al={"幽暗城的乔瑟夫·格里高利","谁是魔法区的裁缝","裁缝格里高利"}},{q="用这些材料制作的是什么长袍？",a="乔瑟夫·格里高利利用亚麻布和达拉然法力宝石缝制法术火长袍，这是一款标志着学徒转变为正式法师的经典服饰。",al={"能获得什么长袍","法术火长袍奖励","收集材料奖励长袍"}},{q="为什么安娜斯塔西娅对杀死达拉然法师感到有些反感？",a="正如哈特威尔所承认的，达拉然法师的信仰与被遗忘者法师有着许多共同的知识和魔法理念。尽管有着这种亲缘关系，但生存和需求高于情感。",al={"哈特威尔对达拉然的看法","被遗忘者法师与达拉然","安娜斯塔西娅·哈特威尔背景"}}},fx={e61c0dee={q="亚麻布有什么用途？",a="亚麻布是制作你的炎法长袍所用的普通基底材料。幽暗城魔法区的裁缝乔瑟夫·格里高利会先将布料织成精美服饰，再把魔法试剂编入丝线，为其注入力量。",al={"亚麻布的用途","为什么要亚麻布","亚麻布有什么用"}},["8f9ef647"]={q="达拉然法力宝石有什么用途？",a="达拉然法力宝石中储存着肯瑞托法师汇聚的纯粹奥术能量。乔瑟夫·格里高利会把宝石直接缝进你的长袍，为布料注入魔力，打造真正的炎法服饰。",al={"达拉然法力宝石的用途","为什么要达拉然法力宝石","法力宝石有什么用"}},["608132d5"]={q="银松森林里的达拉然法师是谁？",a="他们是效忠达拉然的人类法师，驻扎在银松森林东部的安伯米尔周围。他们的奥术训练方式与被遗忘者法师相似，但他们的存在直接威胁着幽暗城对该地区的统治，因此成了野心勃勃的学徒们优先袭击的目标。",al={"银松森林的达拉然法师","达拉然法师是谁","银松森林的达拉然人类"}},["1cfe23fe"]={q="安娜斯塔西娅·哈特威尔为什么派学徒去，而不亲自处理？",a="赢得第一件法师长袍是法师成长的必经仪式。安娜斯塔西娅·哈特威尔希望你通过亲自凭意志与力量从敌对施法者手中夺取试剂，证明自己的价值与奥术地位。",al={"为什么让我收集材料","为什么派学徒去","安娜斯塔西娅为什么不自己拿宝石"}}},fp="19,297,25.384.0,26.464.0,31.334.0,43.208.0,57.284.0,38.149.0,23.214.0,44.158.0,67.221.0"}
P.entries["quest:1962"] = {n="魔焰长袍",s="法术火长袍是幽暗城年轻部落法师训练过程中的终极仪式，由裁缝乔瑟夫·格里高利负责完成。在收集了来自各地的稀有材料后，学徒将获得量身定制的附魔长袍，这标志着他们对奥术的掌控力日益增强。",h="法术火长袍是幽暗城年轻部落法师训练过程中的终极仪式，由裁缝乔瑟夫·格里高利负责完成。在收集了来自各地的稀有材料后，学徒将获得量身定制的附魔长袍，这标志着他们对奥术的掌控力日益增强。",kw={"奥术长袍","收集材料","乔瑟夫·格里高利","法师任务","magic quarter","法术火长袍","幽暗城"},ang={["class:Mage"]="获得这些长袍是部落修行者早期的一项成年仪式，能提供足以应付不稳定火焰和奥术能量的定制服装。",["profession:Tailoring"]="该任务展示了凡俗布料如何通过异域试剂来增强，从而承受并提升强大的魔法流。",["race:Undead"]="幽暗城的被遗忘者施法者保留了达拉然风格的奥术纪律，将古老的魔法传统与他们在洛丹伦废墟中的新生活结合在了一起。"},sec={{t="法师的法衣",b="对于在洛丹伦钻研奥术的学徒来说，普通的披风和衣物无法引导或抵御原始的魔力。幽暗城魔法区的一名裁缝乔瑟夫·格里高利，正利用部落施法者们收集来的特殊材料编织真正的魔法服饰。法术火长袍的最后缝制，标志着学徒从最初的咒语学习转变为一名成熟的奥术与火焰艺术修行者。"},{t="编织的力量",b="制作能够安全汇聚高强度魔法的服饰是一项极其严苛的任务。制作这样的长袍不仅需要裁缝技艺，还需要通过危险的考验来获取特定的炼金和奥术材料。一旦这些补给被收集并送到格里高利的圣所，裁缝会当场将它们编织在一起，为有抱负的法师赋予一种实质性的地位象征和保护。"}},faq={{q="法术火长袍任务的目的是什么？",a="这是部落法师早期职业仪式中的最后一步，在他们为裁缝乔瑟夫·格里高利收集完裁缝材料后，奖励他们特别附魔的长袍。",al={"法术火长袍目的","法术火长袍的作用","为什么要完成此任务"}},{q="谁是乔瑟夫·格里高利？",a="乔瑟夫·格里高利是幽暗城魔法区裁缝店的一名被遗忘者裁缝。他负责为安娜斯塔西娅·哈特威尔指引而来的新手法师缝制第一件正式的职业服饰。",al={"乔瑟夫是谁","谁制作长袍","乔瑟夫·格里高利 幽暗城"}},{q="这个任务在哪里进行？",a="整个交互过程都在幽暗城的魔法区内完成，就在乔瑟夫·格里高利的裁缝店里。",al={"法术火长袍位置","法术火长袍在哪里交"}},{q="为什么不需要离开去执行其他任务就能完成此任务？",a="所有的劳作已在上一个任务“收集材料”中完成。一旦你将那些试剂交给乔瑟夫，他只需片刻时间即可织好衣服，并立即交付成品长袍。",al={"为什么它是瞬间完成","如何完成法术火长袍","长袍自动完成"}},{q="法师以外的职业可以获得这些长袍吗？",a="不能。整个任务链和由此获得的附魔长袍仅限于效忠部落的法师。",al={"这是法师专属吗","术士可以获得吗","谁可以完成法术火长袍"}},{q="制作这些长袍需要什么材料？",a="这件长袍由前一个任务中收集的稀有补给制成，包括亚麻布以及从银松森林的肯瑞托法师手中夺取的达拉然法力宝石。",al={"长袍的材料","长袍配方","收集材料交任务"}}},fx={c778cc7d={q="为什么乔瑟夫·格里高利要为你缝制火法长袍？",a="乔瑟夫·格里高利在 Magic Quarter 担任导师，指导正在崛起的被遗忘者与部落法师。他将收集来的试剂编织进合适的附魔法衣，确保你装备齐全，能够驾驭并承受日益精进的技艺所需的奥术力量。",al={"约瑟夫为什么制作长袍","约瑟夫·格里高利的动机","约瑟夫为什么帮你"}}},fp="15,301,17.487.0,11.426.0,49.191.0,23.199.0,33.120.0,62.209.0,48.110.0,49.183.0"}
P.entries["quest:1963"] = {n="碎手氏族",s="这项由暗影裂口中的瑟佐格发布的潜行者试炼，旨在考验那些渴望加入隐秘的破碎之手氏族的学徒。为了证明他们致命的效率，渴望成为潜行者的候选人必须受命去追杀巨魔走私犯塔赞，并夺取他那只上了锁的背包。",h="这项由暗影裂口中的瑟佐格发布的潜行者试炼，旨在考验那些渴望加入隐秘的破碎之手氏族的学徒。为了证明他们致命的效率，渴望成为潜行者的候选人必须受命去追杀巨魔走私犯塔赞，并夺取他那只上了锁的背包。",kw={"cleft of shadow","奥格瑞玛","棘齿城","潜行者","背包","破碎之手","塔赞","瑟佐格"},ang={["class:Rogue"]="这项成年礼将年轻的部落潜行者引入了破碎之手的阵营，强调冷酷的效率、暗杀与功能性，而非正面战斗。",["faction:Horde"]="破碎之手代表了奥格瑞玛内部的思想分歧，隐秘派系在此默默挑战着萨尔对于年轻部落的谨慎愿景。"},sec={{t="裂口之影",b="在奥格瑞玛繁华的街道之下，隐藏着暗影裂口那阴暗的地下空间。破碎之手氏族就活动于此，这是一个植根于古老兽人传统的刺客与盗贼秘密组织。当萨尔大酋长在治理新生部落时宣扬荣誉、外交与谨慎时，破碎之手的领导层却认为这种犹豫削弱了他们的人民。他们试图通过秘密暴力手段重拾军事优势，在战场冲锋可能失败的地方，他们会动用匕首与毒药。"},{t="走私犯的命运",b="为了剔除笨拙与软弱之徒，负责人瑟佐格布置了一项直接的任务：除掉塔赞——一个在贫瘠之地棘齿城附近活动的流浪巨魔。塔赞一直与沿海海盗进行交易，并掌握着该组织垂涎的机密情报。找回他那只上了锁的背包可以证明潜行者在城墙之外追踪猎物的能力，尽管想要取出里面的东西还需要更进一步的技巧。"}},faq={{q="奥格瑞玛的破碎之手是什么组织？",a="破碎之手是部落旗下的隐秘组织，由活跃于奥格瑞玛暗影裂口的潜行者、斥候与刺客组成。虽然在历史上，他们曾是一个以残酷自残行为而闻名的古老兽人氏族，但在现代部落中，他们充当着一个阴影情报与暗杀网络，比起萨尔谨慎的外交手段，他们更推崇冷酷的实用主义。",al={"破碎之手是什么人","破碎之手潜行者","破碎之手宗旨"}},{q="瑟佐格是谁？",a="瑟佐格是驻扎在暗影裂口的一名破碎之手负责人。他通过考验未来的潜行者，以确保他们具备效力于该组织所需的狡诈与致命手段，并且他公开对萨尔的克制态度表示怀疑。",al={"瑟佐格的角色","任务发布者是谁","奥格瑞玛的瑟佐格"}},{q="瑟佐格为什么要除掉塔赞？",a="塔赞是一名巨魔走私犯，在棘齿城港口附近与南海海盗进行非法交易。除了他所贩运的违禁品外，塔赞还随身携带一只装有重要情报的背包，而破碎之手想将其据为己有，用于他们自己的秘密行动。",al={"为什么要杀塔赞","塔赞的背景故事","塔赞做了什么"}},{q="塔赞在什么位置？",a="塔赞在贫瘠之地活动，潜伏在棘齿城南部的海岸与海盗据点附近。",al={"塔赞的位置","塔赞在哪里","找到塔赞"}},{q="找回塔赞的背包后会发生什么？",a="当背包被带回交给瑟佐格时，发现它是锁着的。瑟佐格对塔赞的死感到满意，但同时也需要里面的情报，于是他利用这种情况，作为对该潜行者开锁能力的后续测试。",al={"后续任务","上了锁的背包","背包怎么处理"}},{q="萨尔知道破碎之手的方法吗？",a="虽然名义上破碎之手效忠于部落，但其成员大多在阴影中行事，并对萨尔谨慎的领导风格怀有轻蔑。他们默默地追寻着自己的情报网络，以便在大酋长的外交手段拖慢行动之前，先行消除被视为威胁的目标。",al={"萨尔与破碎之手","大酋长是否赞同","萨尔的潜行者"}}},fx={["6c6760e5"]={q="塔赞的背包里有什么？",a="Therzok 想要这个背包，因为里面装着有价值的情报。塔赞与在棘齿城附近活动的南海海盗直接往来，他携带的信件或记录可能让 Shattered Hand 掌握海盗沿岸行动的把柄。可惜，这个背包锁得严严实实，在你找到打开它的办法之前毫无用处。",al={"塔赞的背包","塔赞的背包里有什么","塔赞背包的用途"}},fc6df596={q="塔赞是谁？",a="塔赞是个鬼鬼祟祟的巨魔，与驻扎在棘齿城以南的海盗进行非法交易。他在贫瘠之地活动，远离奥格瑞玛律法的管辖，贩卖秘密和违禁品，因此引起了 Shattered Hand 的注意。他与亡命之徒的勾当让他成了理想的清除目标。",al={"塔赞是谁","塔赞的目标","为什么杀塔赞"}},beb36990={q="为什么 Therzok 派你去处理塔赞，而不亲自出手？",a="Shattered Hand 藏身于暗影裂口深处，行事极为隐秘，将其残酷手段掩藏在酋长萨尔的警觉目光之外。Therzok 不能派遣部落正规卫兵，也不能让资深公会成员暴露在这种琐碎的外勤任务中。因此，他把这项委托当作入门试炼，考验你是否具备加入他们地下兄弟会所需的致命狡黠。",al={"为什么派我去","therzok 为什么要你去","为什么不亲自杀塔赞"}}},fp="18,266,20.505.0,17.421.1,40.345.0,15.226.0,33.250.0,23.97.0,46.211.1,52.286.0"}
P.entries["quest:197"] = {n="猎龙",s="在荆棘谷深处，赫米特·奈辛瓦里向经验丰富的追踪者发起了挑战，要求他们去捕杀一只连他自己都未曾捕获的狡猾猛兽。在证明了你对抗弱小野兽的实力后，你被委以重任，去追踪那只被称为特希斯的狡猾迅猛龙，并取回它的利爪。",h="在荆棘谷深处，赫米特·奈辛瓦里向经验丰富的追踪者发起了挑战，要求他们去捕杀一只连他自己都未曾捕获的狡猾猛兽。在证明了你对抗弱小野兽的实力后，你被委以重任，去追踪那只被称为特希斯的狡猾迅猛龙，并取回它的利爪。",kw={"艾耶克·罗欧克","古拉巴什竞技场","赫米特·奈辛瓦里","迅猛龙大师","荆棘谷","特希斯的利爪","特希斯"},sec={{t="谷地的狡猾掠食者",b="在完成了丛林中的初步试炼后，赫米特·奈辛瓦里向你揭示了一只特别凶残的迅猛龙，名为特希斯。虽然许多低级的猎人曾在丛林中追逐过猎物，但这只特希斯却从未被捕捉到，甚至连远征队领队本人都拿它没办法。艾耶克·罗欧克给这只野兽取了这个名字，并将其视为荆棘谷所有鳞甲怪物中的终极战利品。"},{t="夺取利爪",b="为了获得顶级大型狩猎者的认可，你需要前往古拉巴什竞技场北部的区域进行搜寻，那是特希斯经常出没的地方。带回这只恐怖生物的利爪，你就能获得迅猛龙猎杀大师的称号，这是其他大型狩猎者都未能完成的壮举。"}},faq={{q="是谁指派你去猎杀特希斯的？",a="在你证明了自己对抗普通丛林迅猛龙的追踪能力后，赫米特·奈辛瓦里会从他位于荆棘谷北部的奈辛瓦里远征队营地指派你去进行狩猎。",al={"谁给予迅猛龙大师任务","迅猛龙大师任务发布者","谁想要特希斯死"}},{q="特希斯在哪里可以找到？",a="这只凶猛的野兽潜伏在古拉巴什竞技场周围的丛林荒野中，人们经常在竞技场北部的灌木丛中发现它的踪迹。",al={"特希斯位置","特希斯在哪里","在哪里可以找到特希斯"}},{q="赫米特需要什么样的凭证来证明击杀？",a="赫米特需要特希斯的利爪作为无可辩驳的证据，以证明这只狡猾的生物终于被除掉了。",al={"我该给赫米特带回什么","特希斯的证明","迅猛龙大师任务提交物品"}},{q="是谁最初将这只迅猛龙命名为特希斯的？",a="奈辛瓦里远征队营地的猎人之一，艾耶克·罗欧克，为这只难以捉摸的掠食者取名为特希斯。",al={"谁给特希斯命名的","特希斯名字的由来"}}},fp="14,271,29.389.0,18.290.0,29.171.0,26.154.0,42.111.0,39.117.0"}
P.entries["quest:1978"] = {n="亡灵哨兵",s="此项差事标志着一名能干的特工正式加入死亡追踪者——这个被遗忘者的刺客与间谍组织。信使的任务是将安德隆的账本直接递交给恐惧魔王瓦里玛萨斯，从而将辛迪加进行秘密活动的证据呈送给幽暗城最高层的领导者。",h="此项差事标志着一名能干的特工正式加入死亡追踪者——这个被遗忘者的刺客与间谍组织。信使的任务是将安德隆的账本直接递交给恐惧魔王瓦里玛萨斯，从而将辛迪加进行秘密活动的证据呈送给幽暗城最高层的领导者。",kw={"奥特兰克","安德隆的账本","死亡追踪者","黑暗女王之殿","曼内特·卡卡德","辛迪加","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="此次入职代表着正式进入被遗忘者专业的潜行者队伍，将普通的扒手提升为国家资助的情报特工。",["faction:Horde"]="虽然这是被遗忘者内部的安全事务，但监视奥特兰克的人类残部可以保护北部部落领土免受颠覆性的破坏。",["race:Undead"]="对于被遗忘者而言，加入死亡追踪者就是一项直接的誓言：保护洛丹伦脆弱的主权，抵御人类幸存者和潜伏的叛徒。"},sec={{t="踏入阴影",b="在从安德隆·甘特手中发掘出确凿的罪证后，曼内特·卡卡德正式欢迎这位特工加入死亡追踪者。该组织是希尔瓦娜斯女王在洛丹伦各地的耳目与利刃，依靠情报网络、残酷的效率和隐秘行动在威胁显露之前将其消灭。对于幽暗城中任何有志于成为潜行者或斥候的人来说，获得该组织的正式认可是一个重要的里程碑。"},{t="辛迪加的勾结",b="这项秘密调查的战利品就是安德隆的账本，它揭露了当地特工与辛迪加之间的非法勾结。辛迪加曾是已陨落的人类王国奥特兰克的贵族，但在第二次战争王国覆灭后，他们转而从事强盗行径和颠覆活动。卡卡德对这些奥特兰克陨落贵族的堕落程度感到惊讶与鄙夷，他们竟沦落到靠琐碎的阴谋来夺回权力的地步。"},{t="觐见恐惧魔王",b="由于这份情报极其敏感，账本被直接送到了幽暗城皇家区的瓦里玛萨斯手中。这位纳斯雷兹姆指挥官在希尔瓦娜斯·风行者的麾下监管着被遗忘者的战术情报工作。瓦里玛萨斯对死亡追踪者的主动出击感到满意，欢迎这位特工展示出的能力，并指出他的情报部门总是需要像这样能交付成果的人。"}},faq={{q="什么是死亡追踪者？",a="死亡追踪者是被遗忘者首屈一指的间谍、侦察和暗杀组织。他们的总部位于幽暗城的盗贼区，在整个洛丹伦展开行动，以清除政治对手、渗透敌对派系，并保护被遗忘者的疆域免受外部和内部的颠覆。",al={"谁是死亡追踪者","死亡追踪者背景","被遗忘者刺客"}},{q="为什么辛迪加会卷入其中？",a="缴获的账本揭示了与辛迪加的秘密往来，这些流离失所的奥特兰克贵族已经沦为有组织犯罪的强盗。被遗忘者时刻监视着在他们领土内活动的奥特兰克残部，因为辛迪加特工一直在寻找机会夺回失地并掠夺整个北洛丹伦的资源。",al={"为什么是辛迪加","奥特兰克关联","辛迪加账本"}},{q="为什么要直接向瓦里玛萨斯汇报？",a="瓦里玛萨斯担任希尔瓦娜斯女王的战术顾问，负责监督幽暗城的安全和情报行动。涉及外国阴谋的重大发现（例如辛迪加的秘密行动）需要最高行政级别的审查，以便协调更广泛的军事和外交应对措施。",al={"为什么是瓦里玛萨斯","瓦里玛萨斯是谁","恐惧魔王职责"}},{q="曼内特·卡卡德是谁？",a="曼内特·卡卡德是死亡追踪者在幽暗城的一名资深联络员和负责人。他负责监管外勤特工，评估新兵，并在将关键发现上报指挥链之前筛选搜集到的情报。",al={"曼内特·卡卡德职责","任务发布者卡卡德"}},{q="觐见在什么地方举行？",a="觐见在位于幽暗城深处皇家区的黑暗女王之殿举行。瓦里玛萨斯站在希尔瓦娜斯·风行者女王身边，位于被遗忘者权力中心的核心地带。",al={"瓦里玛萨斯在哪里","黑暗女王之殿位置"}},{q="加入死亡追踪者后会发生什么？",a="随着你的资历得到认可，且你对曼内特·卡卡德和瓦里玛萨斯的可靠性也已得到证明，你被视为被遗忘者值得信赖的外勤特工，这也为你未来在洛丹伦纷争不断的土地上执行侦察和清除任务铺平了道路。",al={"死亡追踪者后续任务","接下来做什么"}}},fx={["123798f3"]={q="为什么 Mennet Carkad 要把安德隆的账本送给瓦里玛萨斯？",a="这本账本揭露了辛迪加——一群没落的奥特兰克贵族——正在密谋反对被遗忘者。揭穿他们的背叛，是 Deathstalkers 在情报方面的一次重大胜利。Mennet 知道，涉及洛丹伦安全的紧急消息必须直接交到瓦里玛萨斯勋爵手中，由他统管组织的行动。",al={"为什么要递送账本","mennet carkad 的动机","为什么要向瓦里玛萨斯报告辛迪加"}},b0e675df={q="为什么 Mennet 不亲自向瓦里玛萨斯报告？",a="是你亲自在外执行任务时追查到了密谋者，并拿到了安德隆的账本。Mennet 认为理应由你亲自呈上这份情报，让你在瓦里玛萨斯勋爵面前获得嘉奖，并正式加入 Deathstalkers。",al={"为什么选我加入 deathstalkers","为什么 mennet 派我去","为什么要亲自递送账本"}}},fp="17,326,26.441.0,24.431.1,27.427.0,27.311.0,30.341.0,35.327.0,22.243.0,36.206.0,45.277.0"}
P.entries["quest:198"] = {n="列兵索尔森的补给物资",s="藏宝海湾的克拉兹克雇佣了一名信使，将一批地精杂货运往北部的多伦上尉营地。当地巨魔的侵略行径导致常规运输中断，必须借助外力来确保货物能送达北部边界附近的列兵索尔森手中。",h="藏宝海湾的克拉兹克雇佣了一名信使，将一批地精杂货运往北部的多伦上尉营地。当地巨魔的侵略行径导致常规运输中断，必须借助外力来确保货物能送达北部边界附近的列兵索尔森手中。",kw={"藏宝海湾","暮色森林","地精补给","克拉兹克","库尔森","多伦上尉","列兵索尔森","荆棘谷"},ang={["faction:Alliance"]="多伦上尉的士兵们守卫着从暮色森林进入荆棘谷的北部入口，他们依赖地精提供的补给来维持阵地。"},sec={{t="中断的路线",b="多伦上尉和他的部队驻扎在荆棘谷与暮色森林的交界处附近，他们依赖通过克拉兹克安排的定期补给。当地巨魔持续不断的袭击使得常规运输变得危险重重，促使这位地精商人聘请了一名独立信使。包裹必须沿丛林大道一路北上，并由列兵索尔森负责接收，他可能在路西北侧的营地，也可能在南侧的巡逻路线上。"},{t="货物的真实内容",b="虽然清单上仅注明是地精杂货，但货物中却包含地雷。列兵索尔森透露，这些爆炸物旨在帮助他们守卫哨所，抵御库尔森上校及其手下的进攻。"}},faq={{q="谁在发送这些补给？",a="克拉兹克，一位在藏宝海湾经商的地精商人，负责安排发货并提供补给。",al={"谁给索尔森补给","克拉兹克送货","谁开启列兵索尔森的补给任务"}},{q="为什么补给会延迟？",a="荆棘谷当地巨魔的侵略行径扰乱了常规运输，导致多伦上尉的手下一直在等待原本计划送达的物资。",al={"为什么延迟","巨魔袭击运输","为什么没有送达"}},{q="在哪里可以找到列兵索尔森？",a="他可以在多伦上尉的营地找到，该营地位于暮色森林通往荆棘谷入口附近的主路西北侧，或者他也在营地南侧的道路上巡逻。",al={"索尔森在哪里","索尔森位置","寻找列兵索尔森"}},{q="如果补给丢失了会怎样？",a="克拉兹克警告说，任何未能完成货物交付的人都必须承担经济责任，并向他赔偿损失。",al={"如果我弄丢了补给怎么办","克拉兹克赔偿","让克拉兹克失望"}}},fp="27,254,17.475.0,28.206.1,30.108.0,35.155.0,35.188.0,38.120.0"}
P.entries["quest:199"] = {n="水坝危机",s="这个任务标志着针对巨石水坝破坏活动的调查发现了不法行为的实体证据。在发现隐藏在这座宏伟矮人建筑附近的一个可疑木桶后，冒险者取回了一份怪味粉末样本，并带去给主工程师辛德维尔七世。",h="这个任务标志着针对巨石水坝破坏活动的调查发现了不法行为的实体证据。在发现隐藏在这座宏伟矮人建筑附近的一个可疑木桶后，冒险者取回了一份怪味粉末样本，并带去给主工程师辛德维尔七世。",kw={"黑暗的威胁笼罩","辛德维尔","洛克莫丹","破坏","巨石水坝","怪味粉末","可疑木桶"},ang={["profession:Engineering"]="当一名工程师检查被故意放置在大型大坝结构应力点上的易挥发粉末时，他会立刻察觉到危险。",["race:Dwarf"]="巨石水坝是铁炉堡矮人最伟大的建筑成就之一。任何对其完整性的威胁，都直接冲击着卡兹莫丹的安全与荣耀。",["race:Gnome"]="侏儒的头脑能够欣赏矮人土木工程背后的精密之处，因此这种粗糙破坏行为所涉及的化学性质尤其令人担忧。"},sec={{t="可疑的发现",b="巨石水坝是矮人工程学的丰碑，它阻挡着洛克湖的浩瀚湖水。然而，有关破坏活动的传言引起了人们对周围湖岸的关注。在水边隐蔽处，一个突兀的木桶里装有一种不祥的物质——一种明显的怪味粉末，它显然不属于常规的大坝维护物资。"},{t="大坝警报",b="取走一份未知粉末样本并呈交给主工程师辛德维尔七世，证实了洛克莫丹当局最担心的噩梦。这位工程师立刻意识到有外部势力正在策划针对大坝的阴谋，从而将调查从单纯的怀疑升级为紧迫的区域防御事务。"}},faq={{q="怪味粉末是什么？",a="在木桶中发现的怪味粉末是一种被安放在巨石水坝底部的爆炸物或炼金试剂。这是敌人正在策划摧毁或破坏这座伟大屏障的直接证据。",al={"怪味粉末","木桶里有什么","可疑木桶粉末"}},{q="谁是主工程师辛德维尔七世？",a="主工程师辛德维尔七世是一位矮人总工程师，负责监督洛克莫丹巨石水坝的维护、结构完整性和安全性。",al={"辛德维尔是谁","主工程师辛德维尔","大坝工程师"}},{q="在哪里发现了可疑木桶？",a="这个可疑木桶隐藏在洛克莫丹北部的巨石水坝地基附近的湖岸边。",al={"木桶位置","木桶在哪里","洛克莫丹木桶"}},{q="为什么巨石水坝会成为目标？",a="巨石水坝阻挡着洛克莫丹巨大的蓄水池。如果水坝决堤，灾难性的洪水将冲毁下方的湿地，切断联盟的贸易路线，并摧毁整个卡兹莫丹的矮人领地。",al={"为什么要摧毁大坝","大坝破坏","对洛克莫丹的威胁"}},{q="谁把可疑木桶放在了这里？",a="这个木桶是由意图破坏矮人领地稳定的特工放置的，这促使主工程师辛德维尔对幕后黑手展开了更广泛的调查。",al={"谁放置了木桶","破坏者","谁放了粉末"}},{q="收集粉末后我该做什么？",a="直接将样本带给位于巨石水坝上方的主工程师辛德维尔七世，以便他检查这种物质并做出应对准备。",al={"接下来做什么","上交粉末","找谁谈话"}}},fp="19,308,22.377.0,16.319.1,36.233.0,37.149.0,37.124.0,43.226.0,36.168.0,45.139.0"}
P.entries["quest:1998"] = {n="芬维克·萨托斯",s="幽暗城的梅内特·卡卡德受瓦里玛萨斯领主直接指派，委派有前途的潜行者去猎杀芬威克·萨特罗斯。萨特罗斯涉嫌在银松森林沿岸组织独立的亡灵势力。消灭他能向死亡猎手证明特工的实力，从而开启更高级的职业训练。",h="幽暗城的梅内特·卡卡德受瓦里玛萨斯领主直接指派，委派有前途的潜行者去猎杀芬威克·萨特罗斯。萨特罗斯涉嫌在银松森林沿岸组织独立的亡灵势力。消灭他能向死亡猎手证明特工的实力，从而开启更高级的职业训练。",kw={"死亡猎手","芬威克·萨特罗斯","洛丹米尔湖","梅内特·卡卡德","rogues' quarter","银松森林","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="这份契约是被遗忘者潜行者的试炼场，旨在确认他们的潜行与致命能力，然后才会允许他们接触死亡猎手职业中更深层的工具。",["race:Undead"]="被遗忘者无法容忍敌对亡灵派系在靠近首都的地方宣示主权，这使得萨特罗斯的头颅成为了一项政治必需品。"},sec={{t="来自恐惧魔王的命令",b="在Rogues' Quarter那昏暗的走廊里，梅内特·卡卡德负责处理死亡猎手（被遗忘者秘密的情报分支）的内部契约与训练。当瓦里玛萨斯领主下达优先目标时，这绝非随手交给新手新兵的任务。芬威克·萨特罗斯通过在银松森林的流亡亡灵中建立据点，引起了恐惧魔王的注意。如果不加遏制，这些独立的亡灵领导层可能会危及被遗忘者在洛丹伦旧领土上的巩固统治。"},{t="洛丹米尔湖畔的破旧码头",b="根据死亡猎手的侦察，萨特罗斯并未躲藏在深处的要塞或墓穴中。相反，斥候发现他在银松森林洛丹米尔湖水域附近的一座破旧码头。在那里击杀他，需要穿越由野兽、腐皮豺狼人和天灾军团残党所占据的争夺中的荒野。带回他的头颅能提供瓦里玛萨斯所要求的切实的证据，从而让特工获准参与更深层次的秘密行动。"}},faq={{q="芬威克·萨特罗斯是谁？",a="芬威克·萨特罗斯是一名在银松森林洛丹米尔湖沿岸活动的亡灵领袖。与效忠希尔瓦娜斯女士的被遗忘者不同，萨特罗斯统领着一些并未归顺或敌视幽暗城的亡灵，这导致瓦里玛萨斯领主将其选为处决目标。",al={"芬威克背景故事","萨特罗斯是谁","芬威克·萨特罗斯背景"}},{q="为什么瓦里玛萨斯想要芬威克·萨特罗斯死？",a="瓦里玛萨斯认为萨特罗斯是一个新兴威胁，可能会集结银松森林中四散的亡灵来对抗被遗忘者。为了保卫幽暗城周边的边界，任何威胁到希尔瓦娜斯对该地区绝对控制权的敌对领袖都必须被迅速清除。",al={"瓦里玛萨斯 萨特罗斯","为什么要杀芬威克"}},{q="谁是死亡猎手？",a="死亡猎手是被遗忘者首屈一指的间谍、暗杀与侦察机构。他们以幽暗城的Rogues' Quarter为基地，在整个洛丹伦行动，以消除内部威胁、监视敌对派系，并为黑暗女王巩固领土。",al={"死亡猎手背景故事","什么是死亡猎手","亡灵潜行者派系"}},{q="芬威克·萨特罗斯在哪里？",a="死亡猎手的报告显示，萨特罗斯位于银松森林东北部洛丹米尔湖岸边的一座废弃、破旧的码头附近。",al={"芬威克在哪里","芬威克码头位置","萨特罗斯 洛丹米尔湖"}},{q="完成此任务能从死亡猎手那里获得什么？",a="处决萨特罗斯证明了特工对梅内特·卡卡德和死亡猎手的能力与忠诚。在证明了你的可靠性后，卡卡德会通过专门的职业指导为你提供更高级的暗影技艺训练。",al={"芬威克奖励背景","完成芬威克后会怎样"}},{q="梅内特·卡卡德是谁？",a="梅内特·卡卡德是一位位于幽暗城Rogues' Quarter的潜行者训练师兼死亡猎手联络员。他负责监管外勤特工，并指派与被遗忘者领土安全直接相关的任务。",al={"梅内特·卡卡德","谁发布了芬威克任务"}}},fx={eac48585={q="为什么 Mennet Carkad 需要芬维克的头颅？",a="Fenwick Thatros 是个盘踞在银松森林边境附近的有组织威胁。Mennet Carkad 要求你带回他的首级，以确凿证明这名叛变的亡灵指挥官已被铲除。在 Deathstalkers 和瓦里玛萨斯勋爵的秘密行动中，刺客的一面之词远远不够，必须有实体战利品证明任务完成。",al={"芬维克的头颅有什么用","为什么要带回芬维克的头颅","芬维克头颅的用途"}},bc8ca6fa={q="为什么 Mennet Carkad 选你执行这项任务？",a="Mennet Carkad 在 Rogues' Quarter 担任 Deathstalkers 的联络人和训练者。瓦里玛萨斯勋爵下令实施精确暗杀时，普通城卫并不适合在野外秘密侦察。Mennet 特意选中你，因为你在暗影技艺方面展现了潜力；他要借这项重要委托考察你是否已准备好接受更高级的训练，成为被遗忘者的精锐行动人员。",al={"为什么派我去","mennet 为什么选我","为什么不派 deathstalkers 卫兵"}}},fp="15,348,28.525.0,30.480.0,23.290.0,47.256.0,26.279.0,33.129.0,62.236.0,21.206.0"}
P.entries["quest:1999"] = {n="交易工具",s="《贸易工具》是幽暗城的门内特·卡卡德向部落潜行者发布的一项入门任务。在瓦里玛萨斯领主的命令下，特工们必须获得开锁工具，并潜入安伯米尔，找回详细记录达拉然当前状况的敏感肯瑞托报告。",h="《贸易工具》是幽暗城的门内特·卡卡德向部落潜行者发布的一项入门任务。在瓦里玛萨斯领主的命令下，特工们必须获得开锁工具，并潜入安伯米尔，找回详细记录达拉然当前状况的敏感肯瑞托报告。",kw={"安伯米尔","达拉然","死亡猎手","艾斯特蕾·根德瑞","肯瑞托","开锁","门内特·卡卡德","rogues' quarter","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="这项任务是部落潜行者的一次成人礼，要求你获取正式的开锁工具，并运用潜行和技巧而非蛮力来完成任务。",["faction:Horde"]="在银松森林获取人类的情报，巩固了部落在洛丹伦北部对抗联盟残余势力的立足点。",["race:Undead"]="潜入安伯米尔使被遗忘者能够智胜那些试图从坟墓中夺回洛丹伦的肯瑞托法师。"},sec={{t="密切关注安伯米尔",b="在审讯了一名囚犯后，死亡猎手得知有关达拉然废墟的重要情报隐藏在安伯米尔。银松森林依然是一条危险的前线，守卫该村庄的人类法师严密地守护着他们的通讯。在瓦里玛萨斯领主的命令下，死亡猎手导师门内特·卡卡德指引有潜力的特工绕过肯瑞托哨兵，夺取《达拉然形势报告》。"},{t="破入的艺术",b="与直接的暗杀不同，这项任务是对潜入和开锁能力的实战检验。特工在进入敌对的肯瑞托领地之前，会从艾斯特蕾·根德瑞那里配发专业的盗贼工具。撬开安伯米尔的保险箱证明了一名特工已经超越了粗暴的街头斗殴，成为了被遗忘者不可或缺的间谍资产。"}},faq={{q="谁下达了这项任务？",a="驻扎在幽暗城Rogues' Quarter的死亡猎手大师门内特·卡卡德负责指派这项任务。总体指令直接来自瓦里玛萨斯领主，他负责监督被遗忘者的情报搜集工作。",al={"谁发布了贸易工具任务","任务发布者","门内特·卡卡德任务"}},{q="《达拉然形势报告》是什么？",a="这是一份密封的肯瑞托公文，详细记录了达拉然内部的情况。死亡猎手审讯官从一名囚犯口中逼问出了这份公文的下落，从而让幽暗城意识到他们南方邻居的关键情报正处于脆弱状态。",al={"这些文件是什么","肯瑞托文件","形势报告"}},{q="这份报告存放在哪里？",a="该报告被锁在位于银松森林南部的肯瑞托前哨站安伯米尔内的一个保险箱里。",al={"我在哪里可以找到文件","安伯米尔宝箱位置","形势报告在哪里"}},{q="谁提供开锁工具？",a="幽暗城Rogues' Quarter的装备商艾斯特蕾·根德瑞提供了打开肯瑞托保险箱所需的盗贼工具。",al={"我去哪里获取工具","艾斯特蕾·根德瑞的作用","装备商工具"}},{q="为什么达拉然目前对被遗忘者很重要？",a="达拉然幸存的法师们正在洛丹米尔湖对岸的银松森林重建他们的城市。被遗忘者监视着肯瑞托，以保护他们在洛丹伦的领地。",al={"为什么关注达拉然","被遗忘者与达拉然","肯瑞托威胁"}},{q="接取此任务前必须完成什么前置条件？",a="特工必须先完成刺杀芬威克·萨特罗斯的合同，在银松森林猎杀目标，门内特·卡卡德才会信任他们去执行这项精密的潜入工作。",al={"前置任务","之前需要做什么任务","芬威克·萨特罗斯任务"}}},fx={["77cf7ea8"]={q="为什么 Mennet Carkad 想要完成这件事？",a="瓦里玛萨斯勋爵命令 Deathstalkers 从一名囚犯口中套出报告的下落后将其取回。作为 Rogues' Quarter 的一名行动人员，Mennet Carkad 执行恐惧魔王的指令，同时考验你日渐成熟的潜入与间谍技巧。",al={"mennet carkad 为什么要这个","mennet carkad 的动机","为什么要找回达拉然形势报告"}},["9b719de0"]={q="你要在安伯米尔对付谁？",a="你的目标是驻扎在银松森林安伯米尔的肯瑞托成员。这些人类法师在达拉然重建城附近维持着一处据点，防止被遗忘者获知这座破碎之城现状的机密情报。",al={"谁拿着这份报告","工具之战的目标","你的目标是谁"}},["6507a470"]={q="为什么 Mennet Carkad 需要你执行这项任务？",a="这项任务是你的成人礼。在你通过铲除 Fenwick Thatros 展现基本能力后，Mennet 选中你，证明你能够胜任 Deathstalkers 更精细的技艺——依靠潜行、开锁和潜入，而非蛮力。",al={"为什么派我去","mennet carkad 为什么选我","为什么 deathstalkers 不能拿到报告"}}},fp="18,265,17.460.0,21.418.0,24.235.0,34.244.0,25.125.0,35.145.0,51.178.0,63.183.0"}
P.entries["quest:2"] = {n="沙普塔隆的爪子",s="利爪尖牙是一项战利品任务，代表着在灰谷击败了凶猛的角鹰兽尖爪。将这头生物被切下的爪子带回碎木岗哨交给塞娜尼·雷心，可以证明你的技艺，并保护部落穿越这片古老森林的补给线。",h="利爪尖牙是一项战利品任务，代表着在灰谷击败了凶猛的角鹰兽尖爪。将这头生物被切下的爪子带回碎木岗哨交给塞娜尼·雷心，可以证明你的技艺，并保护部落穿越这片古老森林的补给线。",kw={"灰谷","灰谷狩猎","角鹰兽","苦工","塞娜尼·雷心","尖爪","碎木岗哨","战歌"},ang={["class:Hunter"]="击败像尖爪这样的传奇空中掠食者，是在灰谷茂密的树冠下进行追踪和射击技巧的终极考验。",["faction:Horde"]="击败尖爪保障了战歌伐木行动的重要路径，并保护了往返于前哨站和碎木岗哨之间的脆弱苦工。",["race:Orc"]="清除森林中的空中恐怖生物，减轻了战歌氏族艰苦的伐木活动的负担。",["race:Tauren"]="遵循塞娜尼·雷心的狩猎仪式，展现了牛头人通过面对自然界最凶猛的野兽来测试自我的一贯传统。"},sec={{t="森林小径的祸害",b="当部落试图在灰谷开辟资源时，当地的动物群也和暗夜精灵哨兵一样危险。尖爪是一只以极具攻击性而闻名的角鹰兽，它盘踞在通往碎木岗哨的树冠和路径上。这头野兽捕食往返于前线伐木场和哨所之间的脆弱苦工和信使，严重阻碍了部落在该地区的行动。"},{t="狩猎的证明",b="在牛头人女猎手塞娜尼·雷心的指导下，部落猎手被指派去清理潜伏在灰谷树冠下的致命掠食者。从尖爪身上砍下巨大的爪子，是这只空中恐怖生物已被击杀的无可辩驳的证据。将这一战利品送到碎木岗哨，能赢得哨所守卫的尊重，也能让那些必须行走在林间的恐惧劳工们感到一丝宽慰。"}},faq={{q="尖爪是什么？",a="尖爪是一只栖息在灰谷的有名号的掠食性角鹰兽。它以凶猛著称，不断伏击穿行于这片古老林地的旅行者。",al={"尖爪是谁","尖爪怪物","尖爪是什么野兽"}},{q="为什么塞娜尼·雷心想要这只爪子？",a="塞娜尼·雷心在碎木岗哨协调灰谷的狩猎行动。这只爪子是主要的掠食者已被清除、不再威胁部落工人和补给路线的实物证明。",al={"为什么交还爪子","塞娜尼·雷心战利品","利爪尖牙的目的"}},{q="我在哪里交还利爪尖牙？",a="你需要将爪子交给位于灰谷东部碎木岗哨的牛头人塞娜尼·雷心。",al={"在哪里交任务","谁收取爪子","交爪子地点"}},{q="击杀尖爪对部落有什么帮助？",a="尖爪经常攻击往返于偏远伐木场和碎木岗哨之间的苦工。击杀这头野兽能确保补给、木材和信使的运输更加安全。",al={"为什么击杀尖爪背景故事","部落对尖爪的关注"}},{q="这个任务是大型任务链的一部分吗？",a="是的。它是“灰谷狩猎”系列任务的一部分，这是一系列由塞娜尼·雷心提供的野兽追踪试炼，最终将完成“狩猎完成”的任务。",al={"灰谷狩猎任务链","尖爪任务链"}},{q="谁是塞娜尼·雷心？",a="塞娜尼·雷心是一位驻扎在碎木岗哨的牛头人女猎手，她观察森林的平衡，并测试部落猎手面对灰谷最危险生物时的勇气。",al={"塞娜尼背景故事","塞娜尼是谁"}}},fp="17,275,30.407.0,17.424.0,19.162.0,43.195.0,37.104.0,43.178.0,37.146.0,27.194.0"}
P.entries["quest:20"] = {n="黑石氏族的威胁",s="湖畔镇的治安官马瑞斯委派冒险者们去削减那些侵入赤脊山的黑石兽人的数量。通过缴获他们的破斧，镇上的守军希望能打破此时正笼罩着这片定居点的围困。",h="湖畔镇的治安官马瑞斯委派冒险者们去削减那些侵入赤脊山的黑石兽人的数量。通过缴获他们的破斧，镇上的守军希望能打破此时正笼罩着这片定居点的围困。",kw={"战斧","黑石","燃烧平原","湖畔镇","马瑞斯","兽人","赤脊山","石堡","萨瑞尔祖恩"},ang={["class:Warrior"]="与经验丰富的黑石掠夺者盾牌对盾牌的交锋，是对战斗纪律和前线坚韧度的一次残酷考验。",["faction:Alliance"]="保卫湖畔镇对于守住暴风王国南部边界、抵御旧世敌人的进犯至关重要。",["race:Human"]="黑石氏族在第一次战争中摧毁了最初的暴风王国；如今在赤脊山再次面对他们，让人回想起痛苦的历史创伤。"},sec={{t="被围困的城镇",b="湖畔镇发现自己四面受敌，但没有任何威胁能比得上从烈焰燃烧平原蜂拥而至的黑石兽人那样可怕。这些经验丰富的突袭者南下进入了赤脊山，夺取了据点，并徘徊在崎岖的山道上。他们的存在使得镇民实际上被困在了定居点内，切断了贸易、觅食以及通往北部道路的往来。"},{t="痛击先锋",b="治安官马瑞斯，这位焦头烂额的湖畔镇卫队指挥官，无法抽出分遣队去直接攻击他们的阵地。相反，他招募四处游历的冒险者去消耗入侵者的前哨斥候和步兵。马瑞斯要求他们提供粗陋的破斧作为死亡证明，以此削减盘踞在北方石堡周围以及赤脊山东南部崎岖地带的入侵者的数量。"}},faq={{q="这些黑石兽人是从哪来的？",a="他们穿过燃烧平原通往外部的崎岖山道一路向南进军，那里是他们位于黑石山周围的祖居要塞。",al={"兽人来自哪里","赤脊山的黑石入侵","为什么赤脊山有兽人"}},{q="谁发布了这个任务？",a="治安官马瑞斯，负责保卫湖畔镇并在城镇日益严峻的包围圈中维持秩序的高级军官。",al={"黑石之患任务发布者","治安官马瑞斯任务"}},{q="在哪里可以找到这些黑石入侵者？",a="他们占据了石堡要塞周围的北部高地，并在赤脊山的东南部地带也建立了立足点。",al={"黑石兽人在哪里","破斧掉落地点","赤脊山兽人营地"}},{q="治安官马瑞斯为什么要收集破斧？",a="破斧是冒险者曾与威胁山谷的黑石掠夺者进行交战并将其击杀的无可辩驳的实物证明。",al={"为什么收集战斧","死亡证明","破斧的用途"}},{q="这些斥候被击败后会发生什么？",a="在削弱了先锋部队后，治安官马瑞斯会下令对盘踞在山中的当地黑石首领萨瑞尔祖恩发动突袭。",al={"黑石之患后续任务","谁领导这些兽人"}},{q="这些兽人隶属于萨尔的部落吗？",a="不。在这里活动的黑石氏族由旧部落的残党组成，他们对联盟依然抱有极大的敌意，并且独立于萨尔在卡利姆多的新部落运作。",al={"这些是部落兽人吗","黑石氏族属于萨尔的部落吗","赤脊山有友方兽人吗"}}},fx={ded9bd4b={q="为什么治安官马瑞斯要杀死黑石兽人？",a="黑石氏族从燃烧平原向北推进，占领了石堡要塞，并在湖畔镇以北的土地上肆虐。他们不断袭击，实际上已将镇民困在边境之内，如同牲畜般被圈禁。治安官马瑞斯想打破这场令人窒息的围困，守住该地区北部边境，并消灭侦察战团，以免湖畔镇彻底沦陷。",al={"马瑞斯的动机","为什么杀黑石兽人","为什么要对付黑石威胁"}},["29f2a399"]={q="威胁湖畔镇的黑石入侵者是谁？",a="你奉命对付的是黑石兽人，他们是旧部落的残余势力，从燃烧平原一路南下。他们占据了北面的石堡要塞，在荒野中肆虐，并开始在赤脊山东南部的隐蔽地带建立据点，企图扼杀湖畔镇，并将领土控制范围扩张至群山各处。",al={"黑石兽人是谁","目标是谁","石堡兽人"}},e27bf976={q="为什么治安官马瑞斯需要冒险者，而不是湖畔镇卫兵？",a="湖畔镇的驻军已被逼到极限。暴风城的军队不在此地，也迟迟没有派来援军；马瑞斯和所剩无几的卫兵无法冒险出城进入荒野，否则镇子就会毫无防备。为了击退步步逼近的入侵者，他只能依靠有本事的独立佣兵和冒险者。",al={"卫兵为什么不作战","马瑞斯为什么选我","为什么需要冒险者"}}},fp="16,228,18.405.0,21.413.0,41.142.0,21.135.0,42.147.0,48.154.0,45.136.1,44.183.0"}
P.entries["quest:200"] = {n="书呆子赫罗德",s="在库尔森发现了索森的秘密后，多伦上尉担心他的人中混入了间谍。为了查明秘密是如何泄露的，调查者必须潜入库尔森的营地，并找回库尔森的后勤军官所保存的记录。",h="在库尔森发现了索森的秘密后，多伦上尉担心他的人中混入了间谍。为了查明秘密是如何泄露的，调查者必须潜入库尔森的营地，并找回库尔森的后勤军官所保存的记录。",kw={"赫洛德","库尔森上校","库尔森的营地","多伦上尉","荆棘谷","索森"},ang={["faction:Alliance"]="多伦上尉和他的手下曾与库尔森上校站在同一阵线，后来脱离了队伍，现在他们正在自己的队伍中搜寻间谍。"},sec={{t="队伍中的内鬼",b="在索森的秘密被发现后，多伦上尉怀疑他们之中出了叛徒。这次情报泄露威胁到了他们的行动，找出叛徒已成了当务之急。索森通过赫洛德——这位上校的后勤军官，与库尔森的营地保持着直接的通讯联系。由于赫洛德熟悉库尔森的营地日常运作方式，多伦认为这位军官的书面记录中藏着这次行动是如何暴露的真相。"},{t="后勤办公室",b="想要拿到赫洛德的文件，就必须冒险进入库尔森的营地。在多伦曾效力于库尔森的那段时间里，赫洛德将他的办公室设在营地唯一一栋两层建筑的顶楼。在那里，在物资征用单和库尔森上校亲笔书写的公文之间，存放着能追查到秘密是如何被出卖的文件。"}},faq={{q="赫洛德是谁？",a="赫洛德是库尔森上校手下的后勤军官。他负责监管库尔森的营地物资和日常运作，并且此前一直是索森的内线联系人。",al={"赫洛德的职责","赫洛德是谁","赫洛德背景故事"}},{q="为什么多伦上尉想要赫洛德的记录？",a="多伦上尉认为有间谍出卖了他们的营地，因为库尔森上校知道了索森的秘密。多伦希望通过赫洛德的后勤日志和信件，查明情报是如何泄露的。",al={"为什么要获取赫洛德的记录","多伦的间谍","索森是如何被抓的"}},{q="赫洛德的记录在哪里？",a="赫洛德的办公室位于库尔森的营地内唯一一栋两层建筑的顶楼，多伦认为他的记录很可能还保存在那里。",al={"记录在哪里","赫洛德办公室位置","库尔森的两层建筑"}},{q="在这次调查之前发生了什么？",a="这次调查紧接着“丛林秘密”任务，在那个任务中，多伦上尉断定必然有人将索森的秘密出卖给了库尔森的手下。",al={"前置任务","赫洛德的前置条件"}}},fp="12,237,19.511.0,20.336.0,20.192.0,47.207.0,41.148.0,37.150.0"}
P.entries["quest:201"] = {n="调查营地",s="“调查营地”是一项源自藏宝海湾的探险任务，旨在侦察荆棘谷新建立的一个猎人营地。受克拉兹克委派，这项任务要求旅行者证实有关传奇矮人神枪手赫米特·奈辛瓦里已经抵达纳菲瑞提湖附近的传言。",h="“调查营地”是一项源自藏宝海湾的探险任务，旨在侦察荆棘谷新建立的一个猎人营地。受克拉兹克委派，这项任务要求旅行者证实有关传奇矮人神枪手赫米特·奈辛瓦里已经抵达纳菲瑞提湖附近的传言。",kw={"藏宝海湾","赫米特·奈辛瓦里","猎人营地","调查营地","克拉兹克","纳菲瑞提湖","荆棘谷","荆棘谷地精"},ang={["class:Hunter"]="一支由著名猎人赫米特·奈辛瓦里带领的大型猎物猎人团队的传闻聚会，自然吸引了许多希望在丛林中磨练技术的追踪和射击爱好者。",["race:Dwarf"]="赫米特·奈辛瓦里是最著名的矮人神枪手和冒险家之一，他的出现让荆棘谷遥远的南方荒野增添了一份自豪与好奇。"},sec={{t="丛林中的报告",b="在藏宝海湾的码头流传着一份报告，称有一群大型猎物的猎人探险队在荆棘谷的北部丛林中扎营。克拉兹克收到消息，营地位于纳菲瑞提湖附近荆棘谷地精繁忙的采矿点上游的河边。在一个充满危险和利益冲突的无法律地带，不明身份的武装营地总是需要警惕的目光。"},{t="一位著名的神枪手",b="这次探险之所以引人注目，是因为有传言称赫米特·奈辛瓦里本人也在其中。这位著名的矮人神枪手在各地都被视为拥有强大关系网的精英探险家。克拉兹克不希望对这些在边远地区活动的有影响力的人物掉以轻心，于是派遣侦察兵沿河而上，以确认这位传奇猎人是否真的已经到来。"}},faq={{q="谁发布了调查营地的任务？",a="克拉兹克，驻扎在藏宝海湾的中立地精港口的一名特工，委派旅行者前往寻找该营地并汇报其确切位置。",al={"谁想要调查营地","谁发布了这个任务","克拉兹克 藏宝海湾"}},{q="赫米特·奈辛瓦里是谁？",a="赫米特·奈辛瓦里是一位著名的大型猎物矮人猎人和探险家。消息传到藏宝海湾，称他正在纳菲瑞提湖附近的猎人营地中，由于他极高的声望和人脉，这一消息引起了人们的关注。",al={"赫米特·奈辛瓦里 荆棘谷","赫米特·奈辛瓦里是谁","著名矮人猎人 荆棘谷"}},{q="猎人营地在哪里？",a="猎人们在荆棘谷北部纳菲瑞提湖沿岸的荆棘谷地精采矿作业点的上游建立了营地。",al={"猎人营地位置","奈辛瓦里营地在哪里","上游营地在哪里"}},{q="为什么克拉兹克对这个狩猎营地感兴趣？",a="通常情况下，一个偏远的猎人营地不会引起藏宝海湾的太大兴趣，但关于赫米特·奈辛瓦里这样有影响力且关系广泛的人物出现在那里的报告，引起了警惕和好奇。",al={"克拉兹克为何关心","为何调查猎人","克拉兹克动机"}},{q="猎人与荆棘谷地精是什么关系？",a="猎人们并不属于荆棘谷地精；他们的营地只是位于纳菲瑞提湖附近该地精集团的采矿设施的上游，仅作为地理标志。",al={"荆棘谷地精关系","猎人是否属于荆棘谷地精","荆棘谷地精 纳菲瑞提湖"}},{q="找到营地后向谁汇报？",a="一旦定位并侦察了河边的营地，你需要回到南方的藏宝海湾，直接向克拉兹克交付报告。",al={"找到营地后做什么","向谁汇报","调查营地任务交还地点"}}},fp="20,289,21.405.0,19.370.0,43.159.0,24.220.0,35.149.0,46.196.0,57.180.0,45.135.0"}
P.entries["quest:202"] = {n="库尔森上校",s="多伦上尉要求你对库尔森上校及其内卫部队进行最后一击。你被派往库存区，去消灭这位叛变的指挥官和他剩余的头目，以确保反抗军营地的生存。",h="多伦上尉要求你对库尔森上校及其内卫部队进行最后一击。你被派往库存区，去消灭这位叛变的指挥官和他剩余的头目，以确保反抗军营地的生存。",kw={"库尔森上校","库尔森","多伦上尉","反抗军营地","库存区","荆棘谷"},ang={["faction:Alliance"]="消灭库尔森可以打破一位暴风城叛变军官对荆棘谷北部地区的控制。"},sec={{t="库存区的核心",b="多伦上尉和他的一群变节者已经达到了与前任指挥官斗争的高潮。在镇压了库尔森的精锐专家后，多伦认识到，只要库尔森还控制着他在丛林中的堡垒，反抗军就永远不会真正安全。他指引你进入库存区的洞穴，库尔森正和他的副官及精锐部队在那里指挥他的军队。"},{t="斩首行动",b="为了彻底消除威胁，多伦要求你带回库尔森的头颅作为他覆灭的决定性证据，并击败他的精锐和副官。进入洞穴直面库尔森的领导层，是反抗军在荆棘谷北部险境中唯一能喘息的机会。"}},faq={{q="谁指派了这个任务？",a="在完成“特种部队”任务后，多伦上尉会从位于荆棘谷北部的反抗军营地派你去追捕库尔森。",al={"任务发放者","任务给予者","库尔森上校任务接取地点"}},{q="库尔森上校在哪里？",a="库尔森在荆棘谷北部库尔森营地内的库存区洞穴深处指挥他的部队。",al={"库尔森在哪里","库尔森位置","如何找到库尔森上校"}},{q="多伦上尉需要什么证据？",a="多伦上尉要求你带回库尔森的头颅，以确凿地证明这位叛变的指挥官已经倒下，此外还需要击败他的精锐和副官。",al={"需要什么证明","库尔森的证明","任务交还物品"}},{q="在这次对抗之前发生了什么？",a="这次对抗紧接在“特种部队”任务之后，在那个任务中，你削弱了库尔森的特种战场作战人员，随后才将目标对准了他的核心指挥结构。",al={"前置任务","上一个任务是什么","库尔森任务线"}}},fp="14,231,26.397.0,27.320.0,22.156.0,32.149.0,41.153.0,36.162.0"}
P.entries["quest:203"] = {n="以彼之道还施彼身",s="在北荆棘谷的反抗军营地中，尤瓦中士正在寻求帮助，以对抗库尔森上校那势不可挡的军队。面对人数十倍于己的狡诈战术家，反抗军必须依靠迅捷的隐秘打击才能生存。消灭库尔森的丛林战士是减轻他们据点所受压力的第一步。",h="在北荆棘谷的反抗军营地中，尤瓦中士正在寻求帮助，以对抗库尔森上校那势不可挡的军队。面对人数十倍于己的狡诈战术家，反抗军必须依靠迅捷的隐秘打击才能生存。消灭库尔森的丛林战士是减轻他们据点所受压力的第一步。",kw={"库尔森上校","丛林战士","库尔森","反抗军营地","尤瓦中士","特种部队","荆棘谷","尤瓦"},sec={{t="节节败退",b="反抗军营地的士兵们面对库尔森上校时正处于极其不利的境地。尤瓦解释说，上校是一位杰出的军事战术家，其部队人数至少是反抗军的十倍。由于无法进行公开的消耗战，反抗军别无选择，只能采取上校自己的隐秘战术，对他的营地发动快速突袭以削减其兵力，并在重装援军赶来报复之前撤离。"},{t="突袭营地",b="为了扭转局势，尤瓦请求你向东深入库尔森的据点，消灭他麾下大量丛林战士。消灭这些步兵可以缓解反抗军营地所承受的压力。"}},faq={{q="尤瓦中士是谁？",a="尤瓦中士是一位驻扎在北荆棘谷反抗军营地的军官，负责协调针对库尔森上校所率领军队的隐秘打击行动。",al={"尤瓦","谁发布第二次叛乱","尤瓦中士"}},{q="库尔森上校的营地在哪里？",a="库尔森上校的营地位于反抗军营地以东，北荆棘谷茂密的荒野之中。",al={"库尔森营地位置","丛林战士在哪里","库尔森位置"}},{q="为什么反抗军使用隐秘战术而不是进行公开战争？",a="反抗军面对的是由杰出军事战略家库尔森上校所率领的部队，人数比例至少为一比十。面对如此悬殊的兵力差距，直接进攻是不可能的，这迫使反抗军只能依赖快速的游击战。",al={"为何隐秘行动","为何不与库尔森公开作战","反抗军战术"}},{q="“第二次叛乱”之后是什么？",a="在消灭了库尔森的丛林战士后，尤瓦中士会提供后续任务，名为“特种部队”。",al={"下一个任务","第二次叛乱之后是什么","第二次叛乱后续任务"}}},fp="20,345,15.431.0,21.213.0,22.156.0,39.116.0,60.211.0,38.108.0"}
P.entries["quest:2038"] = {n="宾格斯的补给品",s="在驾驶旋翼机坠入洛克湖后，古怪的侏儒工程师宾格斯·雷管遭到了当地穴居人的伏击，重要的装备也被抢走。他目前被困在湖的东南岸，急需找回被偷走的扳手、螺丝刀、锤子以及定制的雷管爆破器，以便修理他的飞行器，重新投入诺莫瑞根的战斗。",h="在驾驶旋翼机坠入洛克湖后，古怪的侏儒工程师宾格斯·雷管遭到了当地穴居人的伏击，重要的装备也被抢走。他目前被困在湖的东南岸，急需找回被偷走的扳手、螺丝刀、锤子以及定制的雷管爆破器，以便修理他的飞行器，重新投入诺莫瑞根的战斗...",kw={"宾格斯","爆破器","雷管","诺莫瑞根","旋翼机","锤子","洛克莫丹","螺丝刀","洛克湖","穴居人","扳手"},ang={["faction:Alliance"]="在洛克莫丹中心地带协助一名联盟飞行员，不仅能保障水道安全，还有助于收复卡兹莫丹失地的宏大战略战争。",["profession:Engineering"]="将雷管爆破器这类专用工具和易爆军火留在穴居人粗鄙的手中，是对工匠精神的亵渎，也随时可能引发灾难性的事故。",["race:Dwarf"]="洛克湖岛屿上的穴居人暴乱威胁着当地的贸易与通行，因此任何打击他们营地的行动都是对山脉之王探险队的一大助力。",["race:Gnome"]="每找回一件工具，侏儒族离发动对窒息诺莫瑞根的穴居人和麻风侏儒的空中反攻就更近了一步。"},sec={{t="潮湿的降落",b="宾格斯·雷管在驾驶旋翼机飞越洛克莫丹时，一场突如其来的事故让他直接坠入了冰冷的洛克湖中。虽然侥幸在坠机中幸存，但爬上岸仅仅是磨难的开始。盘踞在湖心岛上的穴居人趁着他头晕目眩、立足未稳，蜂拥而上洗劫了他最宝贵的财物。"},{t="身陷重围的侏儒科技",b="抢掠成性的穴居人将宾格斯的重要装备分散藏在他们的岛屿营地中。失窃的物资包括他标准的野外作业工具——扳手、螺丝刀和锤子，还有他引以为傲的发明：雷管爆破器。丢失普通的工具虽然麻烦，但在穴居人横行的地区遗落威力巨大的高能炸药，对任何经过洛克莫丹的旅行者来说都是极大的威胁。"},{t="为了诺莫瑞根",b="宾格斯在卡兹莫丹的天空中飞行不仅仅是为了消遣；他自认为是收复故土的空中先锋。由于诺莫瑞根目前被地下穴居人和遭受辐射的麻风侏儒占领，宾格斯计划发动一场决定性的空袭来打破敌人的封锁。然而，如果缺少修理飞行机器的工具和爆破器，他的宏大空中作战计划只能永远搁浅在芦苇丛中。"}},faq={{q="为什么宾格斯·雷管会困在洛克莫丹？",a="宾格斯的旋翼机直接坠入了洛克湖。当他在东南岸试图从事故中恢复时，遭到了附近岛屿穴居人的伏击，他们抢走了他的工具和实验性军火。",al={"宾格斯为什么在这里","宾格斯是如何坠机的","宾格斯坠机"}},{q="穴居人偷走了什么物资？",a="穴居人抢走了四样关键物品：宾格斯的扳手、螺丝刀、锤子，以及一种被称为雷管爆破器的专用爆炸装置。",al={"穴居人偷了什么","宾格斯的补给品","宾格斯的物品"}},{q="穴居人把宾格斯的装备带到了哪里？",a="穴居人将赃物带回了他们位于洛克湖北部的岛屿营地，并将工具桶和炸药散落在岩石密布的岸边。",al={"宾格斯的工具在哪里","穴居人岛屿位置","爆破器在哪里"}},{q="什么是爆破器？",a="爆破器是宾格斯·雷管自行研发的专用爆炸装置，旨在用于对占据诺莫瑞根的敌人进行空袭。",al={"什么是爆破器","雷管爆破器","宾格斯的炸药"}},{q="宾格斯提到的运动是指什么？",a="宾格斯致力于收复诺莫瑞根。他计划发动一场空中轰炸行动，清除盘踞在侏儒首都的地下穴居人和麻风侏儒。",al={"什么运动","为了诺莫瑞根","宾格斯的事业"}},{q="为什么宾格斯不能自己取回物资？",a="宾格斯在遭遇严重的坠机事故后，目前孤立无援、浑身湿透，而且手无寸铁。在没有武器或飞行器的情况下，面对水对面守卫森严的穴居人营地，对一名孤身一人的工程师来说无异于自杀。",al={"为什么宾格斯不自己去取","宾格斯在等什么"}}},fx={["008fc445"]={q="为什么宾格斯·雷管想找回他的补给品？",a="宾格斯在测试飞行器时坠入洛克湖，失去装备所带来的危险不止是无法打捞回物品。他专门为侏儒空中攻势打造了特制工具和专利爆炸物“雷管爆破帽”，以夺回诺莫瑞根。没有工具就无法修复设备，也没有军火可供投放，轰炸占据家园的穴居人和麻疯侏儒的行动就无从进行。",al={"宾格斯的动机","宾格斯为什么需要他的工具","为什么帮宾格斯"}},["0d3e655b"]={q="谁拿走了宾格斯的补给品？他们为什么会在这里？",a="洛克莫丹岛屿上的穴居人在宾格斯坠毁后不久伏击了他，并搜走了他的装备。这些原始的地下蛮兽是在卡兹莫丹各地的矮人挖掘作业中被挖出来的。它们受暴戾的领地本能驱使，又喜欢抢夺闪亮的机械玩意，于是把宾格斯的工具箱和不稳定的炸药拖回湖边营地。",al={"谁偷了宾格斯的工具","洛克莫丹的穴居人和宾格斯","穴居人为什么在岛上"}}},fp="25,387,14.419.0,29.443.0,14.446.0,52.210.0,40.155.0,40.188.0,26.169.0,38.192.0,48.227.0"}
P.entries["quest:2039"] = {n="寻找宾格斯",s="“寻找宾格斯”是联盟的一项引导任务，由铁炉堡的侏儒诺恩发起。由于担心一位在一周前执行飞往陷落的诺莫瑞根的空中侦察任务时失踪的飞行员，诺恩指示冒险者去搜寻洛克莫丹的岸边。追踪这位失踪的飞行员会直接找到宾格斯·雷管，他安然无恙，但急需机械打捞。",h="“寻找宾格斯”是联盟的一项引导任务，由铁炉堡的侏儒诺恩发起。由于担心一位在一周前执行飞往陷落的诺莫瑞根的空中侦察任务时失踪的飞行员，诺恩指示冒险者去搜寻洛克莫丹的岸边。追踪这位失踪的飞行员会直接找到宾格斯·雷管，他安然无...",kw={"宾格斯","雷管","飞行器","诺恩","诺莫瑞根","铁炉堡","洛克莫丹","侦察","tinker town"},ang={["faction:Alliance"]="联盟侦察兵经常在铁炉堡大厅和洛克莫丹的实地行动之间架起通讯桥梁。",["profession:Engineering"]="工程师们能够理解侏儒航空的职业危害，在那里，丢掉一个翼螺母或引擎爆炸只是实地工作中平常的周二。",["race:Gnome"]="对侏儒来说，找回宾格斯意味着保持收复诺莫瑞根的希望，每一个侦察兵和飞行器都很重要。"},sec={{t="失踪的飞行员",b="在铁炉堡繁华的侏儒聚集区Tinker Town，人们对失踪的亲人和丢失的机械感到焦虑。侏儒飞行员宾格斯·雷管被派遣去诺莫瑞根的辐射废墟上空执行空中侦察任务。当一周多过去仍杳无音讯时，诺恩预感到了最坏的结果——怀疑宾格斯遭受了侏儒工程学特有的职业危害，把自己炸飞出了天空。最后一次有人目击这位古怪的飞行员是在洛克湖水域上空。"},{t="在洛克湖",b="搜索者并没有发现一堆悲惨的冒烟残骸，而是发现宾格斯在洛克莫丹的岸边活蹦乱跳。这位搁浅的发明家对自己的长期失踪毫不在意，甚至因为自己的飞行技术受到质疑而感到些许冒犯，他完全专注于自己更宏大的事业。宾格斯没有立即回去向诺恩汇报，而是立即请求他的救援者帮助找回被穴居人偷走的工具和雷管炸药，这样他才能继续为侏儒的事业履行职责。"}},faq={{q="宾格斯·雷管是谁？",a="宾格斯·雷管是一位古怪的侏儒飞行员和机械师。他被派往高空对沦陷的诺莫瑞根进行空中监视，随后他的飞行器在洛克莫丹附近坠毁。",al={"宾格斯是谁","宾格斯·雷管背景故事","飞行员是谁"}},{q="为什么宾格斯要在诺莫瑞根上空飞行？",a="在诺莫瑞根因穴居人和辐射而悲惨沦陷后，侏儒的领导层和技师们一直在持续监控它。宾格斯飞上天空从高处侦察敌人的阵地和环境状况，为收复家园的更大努力做出贡献。",al={"宾格斯的任务","为什么宾格斯在飞行","诺莫瑞根侦察"}},{q="宾格斯在哪里？",a="宾格斯可以在洛克莫丹的洛克湖岸边找到，他在东南岸，正试图整理他坠毁的飞行器。",al={"宾格斯在哪里","寻找宾格斯的位置","去哪里找宾格斯"}},{q="诺恩是谁？",a="诺恩是铁炉堡Tinker Town的一名侏儒协调员。他负责追踪侏儒人员和任务，并在宾格斯未能按时返回时发起搜救。",al={"诺恩是谁","任务发布者诺恩"}},{q="找到宾格斯之后会发生什么？",a="找到宾格斯会开启后续任务“宾格斯的失物”，在该任务中，冒险者需要从洛克湖岛屿上的穴居人那里找回他的扳手、螺丝刀、锤子和雷管炸药。",al={"找到宾格斯后接下来做什么","翼螺母任务","宾格斯后续任务"}},{q="宾格斯在坠机中受伤了吗？",a="宾格斯完全没有受伤，尽管因为诺恩怀疑他的飞行技术，他的自尊心受到了些许伤害。他真正关心的是找回被穴居人偷走的工具和炸药。",al={"宾格斯受伤了吗","宾格斯死了吗"}}},fx={b67b7bf8={q="为什么诺恩想找到宾格斯？",a="宾格斯奉命驾驶侦察机飞越沦陷的诺莫瑞根，至今已超过一周没有音讯。考虑到侏儒机械状况多变，而宾格斯又总能惹出灾祸，诺恩担心这名飞行员已经在荒野某处把自己炸上了天。他需要有人搜索洛克莫丹附近的区域——宾格斯最后一次被人发现的地方——查明他的下落。",al={"为什么要找到宾格斯","诺恩的动机","为什么派人去找宾格斯"}}},fp="12,409,15.522.0,16.513.0,29.203.0,39.253.0,25.145.0,14.187.0,35.197.0,31.191.0"}
P.entries["quest:204"] = {n="库尔森的药物",s="在北荆棘谷的反抗军营地，尤瓦中士试图通过打击库尔森上校的医疗支援来削弱其军事优势。这些叛军依靠他们的医务人员调配的强效药物和毒药，迫使反抗军战士们渴望能将这些药物化为己用。",h="在北荆棘谷的反抗军营地，尤瓦中士试图通过打击库尔森上校的医疗支援来削弱其军事优势。这些叛军依靠他们的医务人员调配的强效药物和毒药，迫使反抗军战士们渴望能将这些药物化为己用。",kw={"丛林药物","库尔森","库尔森营地","巫医","反抗军营地","尤瓦中士","荆棘谷","毒草汁液"},ang={["faction:Alliance"]="切断库尔森的治疗支援能让更多的反抗军战士在对抗他的部队时幸存下来。"},sec={{t="切断营地的补给",b="库尔森上校在他的丛林部队中配置了许多巫医，他们不仅治疗库尔森的部队，还用毒草汁液毒害尤瓦的战士。为了扭转战局，尤瓦中士指派冒险者进入库尔森营地搜寻这些关键物资。获得他们的丛林药物将有助于治疗反抗军营地的伤员，而捕获一份毒草汁液的样本则能让反抗军得以研究这种毒素并制造出相应的解药。"}},faq={{q="是谁发布了这个任务？",a="位于北荆棘谷反抗军营地的尤瓦中士请求你找回这些医疗物资。",al={"谁发布了坏药任务","坏药任务发布者","尤瓦任务"}},{q="尤瓦中士为什么需要丛林药物？",a="库尔森的巫医使用这些药物来治疗他们自己的士兵。反抗军战士需要同样的物资来治疗并维持他们伤员的生命。",al={"为何需要丛林药物","丛林药物的作用"}},{q="毒草汁液是用来做什么的？",a="库尔森的部队使用毒草汁液来毒害尤瓦的战士。尤瓦中士需要一份样本，以便营地能研究这种化合物并研制出对抗它的解药。",al={"为何需要毒草汁液","汁液用途"}},{q="这些医疗物资存放在哪里？",a="这两样物资都存放在库尔森营地内。巫医随身携带药物，而毒草汁液则存放在营地各处的补给箱里。",al={"哪里能找到丛林药物","汁液位置"}}},fp="12,331,32.489.0,27.120.0,45.164.0,40.175.0,38.171.0"}
P.entries["quest:2040"] = {n="地底突袭",s="“地下突击”是一个联盟任务，由暴风城Dwarven District的沉默的舒尼提供。冒险者受命帮助流离失所的侏儒，深入死亡矿井，从一台地精伐木机中回收完好的动力核心。这个被盗的组件将被用来为钻地机提供动力，旨在作为解放诺莫瑞根的先锋。",h="“地下突击”是一个联盟任务，由暴风城Dwarven...",kw={"死亡矿井","小型高能发动机","诺莫瑞根","地精伐木机","陀螺钻掘挖掘机","沉默的舒尼","穴居人","地下突击"},ang={["faction:Alliance"]="协助Dwarven District流离失所的侏儒不仅加强了暴风城与其流亡盟友之间的纽带，同时也打击了迪菲亚的补给线。",["profession:Engineering"]="工匠们会欣赏这种大胆的工程手段：将残暴的地精伐木机动力核心改造成精确的侏儒挖掘机械的燃料。",["race:Gnome"]="对于流亡的侏儒冒险者来说，回收这个动力核心是刺穿他们陷落家园的岩石壁并驱逐诺莫瑞根穴居人的个人重要一步。"},sec={{t="绝望的创造力",b="在诺莫瑞根被原始的穴居人攻陷后，幸存的侏儒技师被迫流亡在卡兹莫丹和暴风城各地。像沉默的舒尼这样的工程师并没有沉溺于失败，而是已经在构思各种机械行动来突破他们失落的家园。主要的障碍是环绕这座技术官僚城市的厚重地下岩层，需要用到被称为“陀螺钻掘挖掘机”的大型隧道挖掘机。由于人类领地缺乏必要的局部电网，侏儒们将目光投向了一种意想不到且不稳定的替代方案：在犯罪地下世界运作的地精重型机械。"},{t="洗劫迪菲亚铸造厂",b="在西部荒野的死亡矿井蜿蜒的矿道深处，艾德温·范克里夫的迪菲亚潜行者雇佣地精工程师制造战争机器，其中包括一台功能齐全的地精伐木机。舒尼指示联盟特工潜入这座铸造厂，摧毁或拆解这台笨重的自动机械，并找回其特殊的“心脏”——小型高能发动机。通过征用这种强大的地精电源，流离失所的侏儒们获得了钻透地下周边地区所需的原始机械动力，并能发起反攻以夺回诺莫瑞根。"}},faq={{q="谁发放“地下突击”任务？",a="该任务由沉默的舒尼发放，她是一位位于暴风城Dwarven District的侏儒工程师。在与其他提到她宏伟计划的侏儒交谈后，冒险者通常会被引荐给她。",al={"地下突击任务发放者","谁发放地下突击任务","舒尼任务"}},{q="我在哪里能找到小型高能发动机？",a="小型高能发动机可以从西部荒野死亡矿井中铸造厂隧道深处的一台功能性地精伐木机上回收。",al={"小型高能发动机位置","小型高能发动机在哪里","死亡矿井伐木机零件"}},{q="为什么舒尼需要地精伐木机的零件？",a="侏儒的陀螺钻掘挖掘机需要巨大的便携式电源来突破诺莫瑞根周围加固的地下边界。驱动迪菲亚潜行者地精伐木机的大功率动力核心提供了钻机所需要的精确机械动力。",al={"为什么要地精零件","为什么是伐木机电源","小型高能发动机用途"}},{q="这个任务的更宏大的目标是什么？",a="该任务支持未来的诺莫瑞根解放行动。通过为重型挖掘机提供动力，流离失所的侏儒们打算直接挖掘穿过被占领城市的岩石周边，并发动突袭以对抗占领那里的穴居人。",al={"为什么要完成地下突击","夺回诺莫瑞根任务","侏儒突袭计划"}},{q="诺莫瑞根发生了什么导致了这个突袭计划？",a="诺莫瑞根被从城市深处涌出的地下穴居人入侵淹没了。在混乱的防御战中，城市被有毒辐射污染，迫使幸存的侏儒平民作为难民逃往铁炉堡和暴风城。",al={"诺莫瑞根为何陷落","诺莫瑞根发生了什么","穴居人入侵"}},{q="迪菲亚潜行者和穴居人是盟友吗？",a="不，他们没有任何联系。迪菲亚潜行者只是雇佣地精技师在西部荒野制造战争机器。舒尼只是利用迪菲亚在死亡矿井的存在，将其作为获取高产地精技术的便捷来源。",al={"迪菲亚和穴居人","穴居人是迪菲亚的同伙吗"}}},fx={["41842bc5"]={q="什么是小型高能发动机？",a="小型高能发动机是一个完好的高效地精动力装置，装在死亡矿井深处运行的一台伐木机内。沉默的舒尼打算将这个动力核心直接装进侏儒陀螺钻掘机。这种大型钻机需要极其强劲的能源，才能钻穿诺莫瑞根周围坚硬岩层构成的地下屏障，为等待夺回家园的侏儒突击部队开辟入口。",al={"什么是小型高能发动机","小型高能发动机的用途","伐木机的动力装置有什么用"}},["37ad24fa"]={q="为什么舒尼要你去死亡矿井寻找地精伐木机？",a="迪菲亚潜行者运用先进的地精工程技术，包括一台功能完备的伐木采矿机，在月溪镇地下挖掘并建造秘密据点。这些战争机器使用的动力核心格外强劲，因此舒尼把这台机器列为首要回收目标。你奉命深入矿井内部，拆解或摧毁伐木机，并取出完好的动力装置，以免迪菲亚潜行者继续利用它。",al={"死亡矿井里的目标是谁","为什么要摧毁伐木机","死亡矿井里为什么有伐木机"}}},fp="19,356,21.658.0,28.571.0,40.214.0,43.135.0,49.279.0,41.251.0,67.253.0,49.230.0"}
P.entries["quest:2041"] = {n="沉默的舒尼",s="这个引导任务召唤联盟的冒险者从铁炉堡出发，前往暴风城寻找沉默的舒尼。舒尼负责领导一支地底突袭部队，旨在支持诺莫瑞根的持续收复工作。",h="这个引导任务召唤联盟的冒险者从铁炉堡出发，前往暴风城寻找沉默的舒尼。舒尼负责领导一支地底突袭部队，旨在支持诺莫瑞根的持续收复工作。",kw={"矿道地铁","dwarven district","诺莫瑞根","陀螺钻挖掘机","铁炉堡","沉默的舒尼","暴风城","技工镇","地底突袭"},ang={["faction:Alliance"]="这项任务展示了联盟各首都之间紧密的后勤联系，利用矿道地铁在铁炉堡和暴风城之间运送人员。",["profession:Engineering"]="舒尼的项目涉及陀螺钻挖掘机，这是一种专为深层挖掘而设计的复杂侏儒机械工程成果。",["race:Gnome"]="铁炉堡的每一位侏儒都梦想着收复他们那片充满辐射的家园；接受舒尼的命令意味着为收复诺莫瑞根的技术努力做出积极贡献。"},sec={{t="来自技工镇的召唤",b="诺莫瑞根遭受辐射陷落后，幸存的侏儒在铁炉堡建立了一个流亡区。他们的工程师、工匠和战略家们不断谋划着打通回家的路。虽然核心规划仍扎根在技工镇，但前线的准备工作早已延伸至卡兹莫丹之外。山城中富有进取心的冒险者被指引向南前往暴风城，那里正在为地底战争准备专门的军事装备。"},{t="地底野心",b="沉默的舒尼指挥着一支驻扎在暴风城Dwarven District铁砧和熔炉之间的精英地底突袭小队。为了深入穴居人出没的区域，她的工兵需要一种被称为陀螺钻挖掘机的特殊机械。多亏了新开通的矿道地铁，前往暴风城寻找舒尼非常方便，它将铁炉堡与暴风城在山脉下直接相连。"}},faq={{q="沉默的舒尼是谁？",a="沉默的舒尼是一位驻扎在暴风城的侏儒军官。尽管有“沉默”这个绰号，她却指挥着一支地底突袭部队，负责制造和部署重型挖掘装备，以协助收复诺莫瑞根。",al={"沉默的舒尼是谁","沉默的舒尼","这个npc是谁"}},{q="我在哪里可以找到沉默的舒尼？",a="舒尼位于暴风城的Dwarven District，就在矿道地铁终点站外几步之遥的锻造训练师和熔炉附近。",al={"舒尼在哪里","舒尼的位置","舒尼的坐标"}},{q="我该如何从铁炉堡前往暴风城？",a="最快的路线是矿道地铁，这是一项位于铁炉堡技工镇东北侧的工程奇迹。它能直接将旅客送达暴风城的Dwarven District，无需穿越野外。",al={"前往暴风城","从铁炉堡到暴风城","如何到达暴风城"}},{q="舒尼需要什么帮助？",a="舒尼正在装备一支地底突袭小队，需要为她的陀螺钻挖掘机提供必要的组件，这项任务最终会将冒险者引向西部荒野和死亡矿井。",al={"舒尼的任务目标","舒尼想要什么"}},{q="接取地底突袭任务必须先完成这个任务吗？",a="不，这是一个可选的引导任务。你可以直接前往暴风城的Dwarven District，亲自与舒尼交谈来接取地底突袭。",al={"与舒尼交谈是必须的吗","我可以直接去找舒尼吗"}},{q="这与诺莫瑞根有什么联系？",a="侏儒领导层正在集结部队和挖掘技术，以突破诺莫瑞根的防御。舒尼的团队正在开发闯入这座受污染城市所必需的地底钻探装置。",al={"为什么要诺莫瑞根","侏儒的联系"}}},fx={["3fdd7df6"]={q="为什么任务发布者要你去找沉默的舒尼？",a="侏儒们正在艰难地争取夺回沦陷的家园诺莫瑞根。沉默的舒尼指挥着一支地下突击队，正在为战争行动准备特制的侏儒陀螺钻掘机，但她在暴风城的行动人手不足。铁炉堡的中央指挥部需要能干的冒险者南下支援她的重要工程项目，才能推动攻势继续进行。",al={"为什么要和舒尼交谈","为什么派我去找舒尼","为什么拜访舒尼"}}},fp="16,216,22.474.0,22.407.0,25.235.0,35.148.0,41.216.0,31.196.0,50.165.0,36.210.0"}
P.entries["quest:205"] = {n="巨魔巫术",s="尼麦兹修士试图通过检查黑暗巨魔的附魔来洞察库尔森上校的腐化原因。在完成“库尔森的秘密”之后，他请求你冒险前往南方的裂颅者领地，从他们的施法者手中获取巫毒咒符。",h="尼麦兹修士试图通过检查黑暗巨魔的附魔来洞察库尔森上校的腐化原因。在完成“库尔森的秘密”之后，他请求你冒险前往南方的裂颅者领地，从他们的施法者手中获取巫毒咒符。",kw={"尼麦兹修士","库尔森上校","秘术师","反抗军营地","裂颅者","荆棘谷","巨魔巫术","巫医"},ang={["faction:Alliance"]="尼麦兹修士在反抗军营地开展工作，征召联盟旅行者去揭开腐化库尔森上校的真相。"},sec={{t="揭开腐化的真相",b="在回顾从丛林中找回的传说时，尼麦兹修士将注意力转向了徘徊在更南方的第二个巨魔部落。他怀疑黑暗巨魔巫术可能是导致库尔森上校堕落成魔的原因。为了验证他的理论，他请求你冒险进入裂颅者的领地，直接从他们的巫医和秘术师手中夺取巫毒咒符，以便他能在反抗军营地研究这些魔法。"}},faq={{q="谁发布了“巨魔巫术”这个任务？",a="尼麦兹修士在荆棘谷北部的反抗军营地发布该任务。",al={"巨魔巫术任务发布者","谁开启巨魔巫术","哪里领取巨魔巫术"}},{q="尼麦兹修士为什么要收集裂颅者巫毒咒符？",a="尼麦兹修士打算研究这些黑暗魔法器具，看看巨魔巫术是否能解释库尔森上校为何陷入邪恶。",al={"为什么尼麦兹修士需要巫毒咒符","巨魔巫术的目的","库尔森腐化巫毒咒符"}},{q="哪些敌人携带巫毒咒符？",a="巫毒咒符由裂颅者领地内的裂颅者巫医和裂颅者秘术师携带。",al={"谁掉落裂颅者巫毒咒符","哪些巨魔有巫毒咒符","巨魔巫术巫毒咒符来源"}},{q="“巨魔巫术”的前置任务是什么？",a="该任务紧随“库尔森的秘密”之后，继续尼麦兹修士对这位上校疯狂行为的调查。",al={"巨魔巫术任务线","巨魔巫术的前置任务是什么","巨魔巫术的前提条件"}}},fp="14,235,25.415.0,35.73.0,52.128.0,33.113.0,35.111.0"}
P.entries["quest:206"] = {n="麦佐斯",s="尼麦兹修士认为库尔森上校是被一股依然存在的隐藏力量逼入了邪道。一个被称为Mai'Zoth的食人魔术士潜伏在东部的群山之中，掌控着一件据说能扭曲并控制心智的神器。消灭他并收回这件圣物，是为了确保不再有其他指挥官遭受同样的腐蚀。",h="尼麦兹修士认为库尔森上校是被一股依然存在的隐藏力量逼入了邪道。一个被称为Mai'Zoth的食人魔术士潜伏在东部的群山之中，掌控着一件据说能扭曲并控制心智的神器。消灭他并收回这件圣物，是为了确保不再有其他指挥官遭受同样的腐...",kw={"尼麦兹修士","库尔森","mai'zoth","maizoth","心灵之眼","食人魔土堆","反抗军营地","荆棘谷"},ang={["faction:Alliance"]="尼麦兹修士在荆棘谷北部的反抗军营地开展工作，寻求联盟的勇士来终结那个腐蚀了库尔森的隐藏邪恶。"},sec={{t="腐蚀的源头",b="尽管库尔森已经倒下，但尼麦兹修士坚称导致叛乱的主要诱因依然存在。他的调查指向了Mai'Zoth，一个居住在荆棘谷东部高地深处的一座食人魔土堆里的食人魔术士。尼麦兹确信Mai'Zoth利用了能改变心智的巫术来扭曲库尔森的思想，并警告说如果留下这个食人魔，可能会导致另一位指挥官屈服于同样的邪恶影响。"},{t="回收圣物",b="为了彻底消除威胁，你被要求击杀Mai'Zoth，从他手中夺取心灵之眼，并将这件具有腐蚀性的神器带回反抗军营地。"},{t="交付之后",b="尼麦兹会给予带回心灵之眼的人以祝福，并打算研究这件神器，看看它的力量是否能为正义所用。如果不能，他说这件东西必须被销毁。"}},faq={{q="Mai'Zoth是谁？",a="Mai'Zoth是一个居住在荆棘谷东部群山中一座食人魔土堆里的食人魔术士。尼麦兹修士认为他通过邪恶的魔法在精神上腐蚀了库尔森上校，因此他对此负有责任。",al={"maizoth是谁","maizoth背景故事","食人魔术士maizoth"}},{q="什么是心灵之眼？",a="心灵之眼是一件由Mai'Zoth持有的神器，据说拥有精神控制魔法，这位食人魔术士利用它来腐蚀并影响他人。",al={"心灵之眼背景故事","这个神器是什么","心灵之眼"}},{q="为什么尼麦兹修士想要杀死Mai'Zoth？",a="尼麦兹修士担心，只要Mai'Zoth活着，他的腐蚀力量就可能将其他人变成另一个库尔森。",al={"尼麦兹的动机","为什么要杀maizoth","追捕maizoth的原因"}}},fp="8,325,24.437.0,18.164.0,18.181.1,16.208.0,23.146.0,44.112.0"}
P.entries["quest:207"] = {n="库尔森的秘密",s="反抗军营地的尼麦兹修士想知道是什么让库尔森上校堕落腐化。尼麦兹怀疑巨魔魔法控制了他，因此派你去荆棘谷的巨魔废墟，抄录刻在四块石板上的传说。",h="反抗军营地的尼麦兹修士想知道是什么让库尔森上校堕落腐化。尼麦兹怀疑巨魔魔法控制了他，因此派你去荆棘谷的巨魔废墟，抄录刻在四块石板上的传说。",kw={"巴拉尔废墟","尼麦兹修士","库尔森上校","反抗军营地","荆棘谷","巨魔传说","暗礁海","祖昆达"},sec={{t="寻找答案",b="库尔森上校曾经是一位伟大而高尚的人，尼麦兹修士想要查明是什么导致了他的堕落。尼麦兹怀疑巨魔魔法控制了上校。为了验证这一点，必须阅读古老的巨魔传说，它们被刻在藏于荆棘谷巨魔废墟中的四块石板上。你被要求抄录每一块石板上的铭文，并将这些副本带回来。"},{t="石板所在地",b="一块石板位于巴拉尔废墟。另一块位于海岸外的深水区，也就是暗礁海，靠近一个被盐鳞鱼人占据的沉没城市。最后两块在祖昆达废墟。"}},faq={{q="谁发起了寻找巨魔石板的任务？",a="在反抗军营地由尼麦兹修士给予。",al={"谁给予库尔森的秘密","在哪里开始库尔森的秘密","尼麦兹修士任务"}},{q="为什么尼麦兹修士想要巨魔传说的副本？",a="尼麦兹修士想知道曾经伟大而高尚的库尔森上校为何会堕落。巨魔魔法可能是罪魁祸首，而石板上的传说或许能证实这一点。",al={"为什么要巨魔石板","库尔森的秘密目的","为什么尼麦兹想要传说"}},{q="四块巨魔石板位于何处？",a="巴拉尔废墟有一块。另一块位于格罗姆高西边的暗礁海深处。还有两块在祖昆达废墟。",al={"石板位置","石板在哪里","库尔森石板地图"}},{q="带回四块石板后接下来会发生什么？",a="尼麦兹修士会研究这些传说，寻找巨魔与库尔森上校堕落之间的联系，故事随后在“巨魔巫术”中继续。",al={"库尔森的秘密之后是什么","库尔森的秘密后续","石板之后的任务线"}}},fp="16,224,21.384.0,21.191.0,44.43.0,53.175.0,41.126.0,51.133.0"}
P.entries["quest:2078"] = {n="基尔卡克的报复",s="基尔卡克·旋杆正寻求向当地的鱼人复仇，因为它们洗劫了他搁浅在黑海岸边的沉船。为了实施他的复仇计划，这位古怪的船长派遣冒险者去重新启动他的机械大副——“重击者4100型”。",h="基尔卡克·旋杆正寻求向当地的鱼人复仇，因为它们洗劫了他搁浅在黑海岸边的沉船。为了实施他的复仇计划，这位古怪的船长派遣冒险者去重新启动他的机械大副——“重击者4100型”。",kw={"黑海岸","基尔卡克","魔像","旋杆","钥匙","鱼人","重击者","重击者4100型"},ang={["faction:Alliance"]="清理掉故障机器和具有攻击性的鱼人，有助于确保黑海岸线对于联盟在奥伯丁与南部地区之间的往来畅通无阻。",["profession:Engineering"]="基尔卡克的机械大副展示了一位搁浅的船长对他的工程设备有多么依赖。",["race:Gnome"]="侏儒或许会将这把发条钥匙认作是一种激活机械自动装置的常用手段。"},sec={{t="船长的复仇",b="搁浅在黑海岸迷雾笼罩的沙滩上，基尔卡克·旋杆拒绝接受被岸上的鱼人击败的命运。在打捞出实施计划所需的零件后，这位古怪的船长将目标锁定为向这个鱼人部落及其首领进行彻底的报复。基尔卡克没有手持弯刀冲入海浪，而是依靠精湛的工程学来实施他的复仇。他将一把发条钥匙交给任何勇敢的陆地生物，委托他们去操控他的机械下属。"},{t="大副的叛变",b="基尔卡克信赖的大副并非什么矮人或水手，而是“重击者4100型”——一个被遗弃在沉船以南浅滩上的叮当作响的机械魔像。虽然发条自动化装置预示着能轻松屠杀鱼人，但这台机器却证明极其不可靠。在被上好发条并带回船长身边后，该构装体发生了灾难性的故障，将它的救助者和制造者误判为敌对目标，从而在海滩上引发了一场战斗。"}},faq={{q="基尔卡克的大副是谁？",a="基尔卡克的大副是“重击者4100型”，这是一个停留在搁浅船长营地南面海岸上的自动化机械魔像。",al={"大副","基尔卡克的大副","谁是大副"}},{q="基尔卡克为什么要复仇？",a="基尔卡克的船在黑海岸遇难，当地的灰雾鱼人搜刮了残骸，并偷走了他大副钥匙的一部分。基尔卡克打算利用他的魔像来粉碎该部落及其首领。",al={"为什么复仇","鱼人复仇","基尔卡克的动机"}},{q="把“重击者”带回去会发生什么？",a="用钥匙激活大副后，将其引导回基尔卡克身边。它抵达船长身边后的行为将在护送过程中揭晓。",al={"重击者攻击","机器人故障","为什么魔像会攻击"}},{q="任务完成后，我该如何处理基尔卡克的钥匙？",a="这把钥匙用于激活“重击者”。任务完成后，它就没有任何用途了。",al={"旋杆的钥匙用途","保留旋杆的钥匙","我可以删除钥匙吗"}},{q="基尔卡克从哪里弄来的“重击者”？",a="该魔像是基尔卡克在卡利姆多北部那次厄运航行中打捞出的货物和装备的一部分，旨在为其船员提供强大的机械助力。",al={"谁制造了重击者","重击者来源"}},{q="魔像被毁后，基尔卡克会放弃吗？",a="当你把他的大副带回时，基尔卡克的计划以及他对你工作的反应将会揭晓。",al={"基尔卡克会怎样","旋杆的复仇之后"}}},fx={a39a7119={q="为什么基尔卡克·旋杆要你去找回他的大副，而不是亲自去？",a="一场灾难性的海难后，基尔卡克被困在黑海岸的海滩上，一心想找回沉船上的货物，并向当地的灰雾鱼人复仇。他已经让你潜水打捞机械大副所需的重要部件，此刻仍守在自己 salvaged gear 旁边，命令你这个雇来的船员——用他的话说，就是个旱鸭子——启动那台机器，再安全地把它带回来。",al={"为什么找我帮基尔卡克·旋杆","为什么基尔卡克需要帮助","为什么基尔卡克不能自己取回魔像"}}},fp="18,252,20.490.0,23.473.1,27.138.0,29.226.0,54.140.1,59.97.1,42.159.0,49.93.1"}
P.entries["quest:208"] = {n="王牌猎人",s="在荆棘谷猎杀过该地区最致命的猛兽并证明了自己的实力后，赫米特·奈辛瓦里提出了最后一项终极挑战。这位著名的神枪手要求得到国王邦加拉什的头颅，这是一头巨大的白虎，也是赫米特来到这片丛林的真正原因。",h="在荆棘谷猎杀过该地区最致命的猛兽并证明了自己的实力后，赫米特·奈辛瓦里提出了最后一项终极挑战。这位著名的神枪手要求得到国王邦加拉什的头颅，这是一头巨大的白虎，也是赫米特来到这片丛林的真正原因。",kw={"邦加拉什","巴格拉","王牌猎人","赫米特·奈辛瓦里","辛达尔","荆棘谷","泰希斯","白虎"},ang={["class:Hunter"]="赫米特·奈辛瓦里认为，击倒国王邦加拉什是追踪和狩猎大师能力的终极证明。"},sec={{t="大师的猎物",b="在完成了探险队猎人设下的考验——击杀辛达尔、巴格拉和泰希斯之后，赫米特·奈辛瓦里认可了你的武艺。据这位老牌神枪手所言，他将你的实力与从洛丹伦战场到丛林深处见过的最出色的表现相提并论，认为只有最后一次狩猎才能证明你无人能及的实力：击倒国王邦加拉什，这头巨大的白虎正是探险队队长真正的目标。"},{t="传奇野兽",b="赫米特透露，国王邦加拉什就是他来到荆棘谷的原因。这头强大的野兽曾多次让这位探险队队长本人惨败而归。献上这头野兽的头颅将证明你的狩猎技巧无人能及。"}},faq={{q="谁发布了这个狩猎任务？",a="在你完成之前所有的狩猎大师任务后，赫米特·奈辛瓦里本人会在荆棘谷北部的探险队营地发布这个任务。",al={"任务发布者","谁开启王牌猎人","赫米特·奈辛瓦里任务"}},{q="必须先完成哪些前置狩猎任务？",a="你必须完成营地的整个狩猎系列任务：在“虎之大师”任务中击杀辛达尔，在“豹之大师”任务中击杀巴格拉，以及在“迅猛龙之大师”任务中击杀泰希斯。",al={"前置条件","王牌猎人的前置任务","邦加拉什要求"}},{q="为什么赫米特·奈辛瓦里想要猎杀国王邦加拉什？",a="国王邦加拉什是赫米特前往荆棘谷的全部原因。这头大白虎屡次从他手中逃脱，多次迫使这位老牌神枪手退回营地。",al={"为什么是国王邦加拉什","为什么猎杀邦加拉什","邦加拉什背景故事"}},{q="赫米特需要什么证明？",a="赫米特需要国王邦加拉什的头颅来确认这头大白虎已被确实击杀。",al={"我需要什么物品","邦加拉什任务目标","击杀证明"}},{q="赫米特说他在哪里经历过战斗？",a="赫米特没有讲述他自己的战斗经历；他只是将你使用武器的技巧与他在洛丹伦战场和丛林深处所见过的表现相提并论，并称他很少见到比这更好的水平。",al={"赫米特战争经历","赫米特过往","洛丹伦猎人"}}},fp="15,268,19.451.0,15.243.0,20.146.0,47.153.0,46.187.0,30.101.0,47.192.0"}
P.entries["quest:209"] = {n="劈颅巨魔的獠牙",s="藏宝海湾的科博克需要筹集材料，以满足南海地区对虎牙的出口需求。由于猎杀真正的丛林掠食者成本过高，他设计了一种无法被察觉的伪造工艺，利用从裂颅者巨魔身上获取的长牙来制作虎牙。",h="藏宝海湾的科博克需要筹集材料，以满足南海地区对虎牙的出口需求。由于猎杀真正的丛林掠食者成本过高，他设计了一种无法被察觉的伪造工艺，利用从裂颅者巨魔身上获取的长牙来制作虎牙。",kw={"藏宝海湾","伪造","科博克","裂颅者","南海","荆棘谷","虎牙","长牙"},sec={{t="有利可图的替代品",b="通过常规狩猎向南海各岛屿的买家供应虎牙，其成本和难度已经变得过高。为了不放弃这笔交易，科博克设计了一种无法被察觉的伪造方法，能将普通的角状物体变成令人信服的仿制品。与这些虎牙物理特性最接近的物品，正是直接取自当地裂颅者巨魔的下颚。因此，科博克雇佣冒险者从这个丛林部族那里收集十八根长牙，以完成他即将到来的出口订单。"}},faq={{q="科博克为什么需要裂颅者长牙？",a="猎杀足够数量的真老虎以供应南海的买家，已被证明过于昂贵且困难。科博克发现，巨魔的长牙可以被伪造成无法被察觉的虎牙复制品，这使得他的贸易业务能够完成每月的出口订单。",al={"为什么需要裂颅者长牙","科博克的长牙计划","为什么要伪造虎牙"}},{q="谁在购买这些虎牙？",a="这些成品仿制虎牙被运往位于南海各岛屿的贸易伙伴手中。",al={"谁购买这些长牙","南海买家","虎牙的去向"}},{q="这个任务在科博克的任务链中处于什么位置？",a="这项任务是继科博克之前要求收集血顶耳朵之后的后续内容。",al={"裂颅者长牙的前序任务是什么","裂颅者长牙任务前置条件","科博克任务顺序"}}},fp="19,262,22.504.0,40.260.0,24.120.0,43.68.0"}
P.entries["quest:2098"] = {n="基尔卡克的钥匙",s="在Darkshore那雾气缭绕的海岸上，古怪的侏儒海盗基尔卡克·旋杆正在寻求帮助，以修复他的机械大副。他至关重要的发条钥匙在岩石上撞得粉碎，散落的碎片被当地的野生动物和鱼人捡走了。找回这三块碎片是让他那船员恢复正常工作的第一步。",h="在Darkshore那雾气缭绕的海岸上，古怪的侏儒海盗基尔卡克·旋杆正在寻求帮助，以修复他的机械大副。他至关重要的发条钥匙在岩石上撞得粉碎，散落的碎片被当地的野生动物和鱼人捡走了。找回这三块碎片是让他那船员恢复正常工作的...",kw={"darkshore","大副","foreststrider","基尔卡克·旋杆","greymist","gyromast's retrieval","海盗","reef crawler","threshadon"},ang={["profession:Engineering"]="工程师们一定能理解，在经历过盐水中的剧烈海难后，要让发条装置保持功能是一项多么艰巨的挑战。",["race:Gnome"]="侏儒们会立刻认出基尔卡克为何宁愿依赖发条装置也不愿使用血肉之躯的船员，即便他这种海盗生活方式在他们的族人看来确实相当罕见。"},sec={{t="Darkshore的落难者",b="基尔卡克·旋杆在Darkshore阴沉的沙滩上是一个极其怪异的存在：一个远离南海常规航线的侏儒海盗。据基尔卡克所言，他的船只在遭到好战的Threshadon袭击并沉没后，在这片海岸附近遭遇了不幸。他随残骸漂流至此，发现自己彻底孤立无援，与他那值得信赖的船员失散了。"},{t="被搜刮走的钥匙",b="基尔卡克目前最关心的不是食物或黄金，而是他的大副。启动并操作这位同伴需要一把特殊的钥匙，这把钥匙在基尔卡克撞上礁石时碎成了三块。在他来得及收集碎片之前，当地的野生动物——海滩上乱爬的Reef crawler，林地附近的巨型Foreststrider，以及当地Greymist鱼人部落的拾荒者——把这些闪亮的金属片抢走了。"},{t="一位奇特的同伴",b="基尔卡克谈起他的大副时，带着海船长特有的那种忠诚，尽管他提到需要让这位同伴“恢复工作状态”，暗示了这并非普通的船员。一名流落异乡的侏儒水手自然会依赖机械天赋，而重组那把破碎的钥匙，对于重启基尔卡克从深海中拖出的某个发条奇迹至关重要。"}},faq={{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是一位古怪的侏儒海盗，当掠食性的Threshadon袭击并击沉了他的船时，他在Darkshore海岸附近遭遇了海难。",al={"基尔卡克·旋杆","这个侏儒海盗是谁","darkshore侏儒海盗"}},{q="这把钥匙是用来做什么的？",a="这把钥匙是重新激活并给基尔卡克的大副上发条所需的，那是一个在灾难性的海难中停机的机械造物。",al={"基尔卡克为什么需要钥匙","基尔卡克钥匙用途","大副钥匙"}},{q="钥匙的三块碎片去了哪里？",a="当钥匙在岸上摔碎时，碎片被当地生物搜刮走了：顶部的碎片被Foreststrider拿走，中间的被Greymist鱼人拿走，底部则被沿海的Reef crawler拿走。",al={"钥匙碎片在哪里","谁偷了钥匙","darkshore断裂的钥匙"}},{q="为什么一个侏儒海盗会在Darkshore附近航行？",a="基尔卡克当时正在卡利姆多北部的海域搜寻战利品，但敌对的Threshadon突然终结了他的航行。",al={"基尔卡克为什么在darkshore","darkshore的海盗"}},{q="钥匙重组后会发生什么？",a="一旦基尔卡克集齐了钥匙的三块碎片，他就可以继续为他的同伴上发条，这将直接开启任务“Gyromast's Revenge”。",al={"钥匙之后做什么","gyromast's retrieval后续"}},{q="持有钥匙碎片的鱼人是谁？",a="中间的碎片被Greymist鱼人部落捡走了，它们在Darkshore礁石边沉船的残骸中安了家。",al={"darkshore鱼人","greymist鱼人钥匙","沉船鱼人"}}},fx={["460afe34"]={q="为什么基尔卡克·旋杆想修复他的钥匙？",a="基尔卡克·旋杆的船在黑海岸外海遭到海潮龙袭击而沉没。他被困在岸边，四周都是凶险的野兽，急需让机械大副恢复运作，以保护自己并向毁掉他航程的生物复仇。没有那三块破碎的发条钥匙碎片，他的发条伙伴就完全无法运作。",al={"基尔卡克为什么要钥匙","基尔卡克·旋杆的目的","为什么要帮基尔卡克"}},["234cb20d"]={q="为什么基尔卡克·旋杆需要你的帮助？",a="基尔卡克是个孤立无援的海盗，身边没有船员，在当地暗夜精灵中也没有朋友。他的船沉没后，自己也遍体鳞伤地被冲上岸，几乎是死里逃生；如今根本无力对付夺走他破碎钥匙碎片的凶猛礁石爬行者、森林陆行鸟和鱼人。",al={"基尔卡克为什么需要我","基尔卡克为什么不能自己找回钥匙","为什么找我帮基尔卡克·旋杆"}}},fp="20,328,21.381.0,17.468.0,20.376.1,23.148.0,25.145.0,41.194.0,46.137.0,42.144.1,42.150.0"}
P.entries["quest:21"] = {n="回音山清剿行动",s="回音山小规模冲突是治安官玛克布莱德下令进行的一项直接军事行动，旨在清除回音山矿洞中的狗头人劳工。在初步侦察之后，这次打击行动旨在防止地下的侵扰在北郡山谷建立永久据点。",h="回音山小规模冲突是治安官玛克布莱德下令进行的一项直接军事行动，旨在清除回音山矿洞中的狗头人劳工。在初步侦察之后，这次打击行动旨在防止地下的侵扰在北郡山谷建立永久据点。",kw={"回音山","回音山矿洞","elwynn","狗头人","劳工","治安官玛克布莱德","北郡","小规模冲突","暴风城军队"},ang={["class:Warrior"]="与成群的劳工进行的地下肉搏战，为年轻的战士们提供了第一次对抗多个据守敌人的近战体验。",["faction:Alliance"]="每一座从入侵怪物手中夺回的矿洞，都能确保战后重建和加固人类定居点所必需的重要石料和矿石。",["profession:Mining"]="清除侵扰重燃了希望，使北郡山谷各处的宝贵矿脉能够再次被安全地开采和冶炼。",["race:Human"]="清理回音山代表了新兵在保卫其祖国时的第一次真正的武力考验，向暴风城的军队高层证明了他们的勇气。"},sec={{t="清理矿洞",b="在早期的侦察确认狗头人已经占领了回音山矿洞后，治安官玛克布莱德立即组织了反击。如果不加干涉，这些地下的害虫会迅速加固隧道、囤积窃取的资源，并无节制地繁殖。为了保护北郡山谷这一重要的农业和精神避难所，当地守军依靠新兵直接与狗头人劳工交战，并在他们进一步扎根之前削减其数量。"},{t="薄弱的防御",b="必须雇佣刚入伍的新兵进行直接正面突击，反映了暴风城军队紧张的处境。由于前线驻军在南部边界兵力吃紧，且整个Elwynn动荡的传言四起，像治安官玛克布莱德这样的地方军官必须尽可能召集任何愿意效力的人手。回音山小规模冲突的成功证明了新兵的可靠性，为他们赢得了正式的尊重，并使他们为王国其他地方更关键的任务做好了准备。"}},faq={{q="为什么狗头人会侵扰回音山矿洞？",a="狗头人天生被矿产丰富的地下隧道和废弃的采石场所吸引。由于暴风城的军事力量捉襟见肘，像回音山这样无人看守的地方就成了害虫们挖掘洞穴、囤积黄金和建立地下据点的轻松目标。",al={"为什么矿洞里有狗头人","回音山狗头人","狗头人在做什么"}},{q="谁下令进行这次小规模冲突？",a="驻扎在北郡修道院的暴风城军队最高军官治安官玛克布莱德指挥了这次行动。他负责监督山谷的防御，尽管军事人力有限，仍肩负着维持秩序的重任。",al={"谁发布了小规模冲突任务","治安官玛克布莱德的命令"}},{q="回音山矿洞有什么战略重要性？",a="回音山提供对北郡的维护以及暴风城更大规模的重建工作至关重要的原石和矿石。任由侵扰在北郡北部边界滋生，会对修道院和附近的葡萄园构成直接的物理威胁。",al={"为什么回音山很重要","回音山矿洞的重要性"}},{q="这个任务接下来会引导至何处？",a="一旦矿洞清除了最初的劳工抵抗，治安官玛克布莱德就会认可The Adventurer的实战能力，并指引他们前往闪金镇，协助更广泛的区域防御。",al={"小规模冲突之后的任务","回音山之后的下一步"}},{q="为什么暴风城军队不亲自清理矿洞？",a="暴风城军队严重缺乏人员，在保卫遥远的边界和应对Elwynn各处的土匪活动方面疲于奔命。像治安官玛克布莱德这样的军官必须依靠刚宣誓入伍的新兵来处理当地威胁，而经验丰富的卫兵则负责守住防御防线。",al={"为什么需要新兵","暴风城士兵在哪里"}},{q="狗头人有足够的智慧成为有组织的军事威胁吗？",a="虽然单个狗头人劳工胆小且头脑简单，但当他们成群结队时，却有着危险的领地意识和侵略性。如果不加遏制，他们会迅速挖掘迷宫般的隧道，设置洞穴陷阱，并引诱更庞大、装备更好的害虫加入他们。",al={"狗头人聪明吗","狗头人的危险程度"}}},fp="22,140,16.357.0,14.348.0,46.214.0,24.153.0,52.176.0,34.132.0,57.206.0,66.198.0"}
P.entries["quest:210"] = {n="克拉兹克的烹调锅",s="卡雷布下士从藏宝海湾的一个地精商人那里买来的机械烹调锅本来是个奇迹，直到它坏掉为止。卡雷布让你把它带回去给地精克拉兹克修理。",h="卡雷布下士从藏宝海湾的一个地精商人那里买来的机械烹调锅本来是个奇迹，直到它坏掉为止。卡雷布让你把它带回去给地精克拉兹克修理。",kw={"藏宝海湾","卡雷布下士","烹调锅","克拉兹克","荆棘谷"},sec={{t="破损的锅",b="卡雷布下士承担了营地里大部分的烹饪工作。这曾经是非常繁重的工作，直到卡雷布从藏宝海湾的一个地精商人那里买到了一个机械锅，这口锅为他节省了大量的时间。然而它坏了。克拉兹克的烹调锅必须送回给地精克拉兹克修理，卡雷布希望你能把它带去那里。"},{t="克拉兹克的检视",b="克拉兹克称这口锅设计精妙，虽然时不时会蹦出一个弹簧或齿轮打滑。在检查一番后，克拉兹克发现蒸汽充能器生锈了，指节垫圈裂开了，调频器也缺了齿。克拉兹克可以修理它，但天下没有免费的午餐，修理也是要收费的。"}},faq={{q="谁派你去找克拉兹克的？",a="负责营地大部分烹饪工作的卡雷布下士派你去的。卡雷布买的那口机械锅坏了。",al={"谁给予克拉兹克的烹调锅任务","谁开启克拉兹克的烹调锅任务","卡雷布下士任务"}},{q="克拉兹克在哪里可以找到？",a="克拉兹克就是藏宝海湾那个把锅卖给卡雷布的地精商人。",al={"克拉兹克在哪里","克拉兹克位置","藏宝海湾的克拉兹克"}},{q="卡雷布下士想让你带什么给克拉兹克？",a="一个叫做克拉兹克的烹调锅的机械烹饪锅，它在为卡雷布节省了大量工作后坏掉了。",al={"什么是克拉兹克的烹调锅","我要带给克拉兹克什么"}},{q="卡雷布为什么要从克拉兹克那里买烹饪锅？",a="卡雷布负责营地里大部分的烹饪工作，这口锅在他坏掉之前为他节省了大量时间。",al={"为什么要机械烹饪锅","卡雷布的烹饪锅"}}},fp="16,175,12.312.0,19.293.1,24.116.0,26.67.0,48.104.0,44.101.0"}
P.entries["quest:2118"] = {n="瘟疫蔓延",s="“瘟疫之地”是联盟的一项任务，由黑海岸的萨纳瑞恩·绿树提供。为了消除折磨本地野生动物的蔓延腐化，萨纳瑞恩委托冒险者使用一件附魔圣物活捉一只狂暴的蓟熊，试图寻找治愈之法。",h="“瘟疫之地”是联盟的一项任务，由黑海岸的萨纳瑞恩·绿树提供。为了消除折磨本地野生动物的蔓延腐化，萨纳瑞恩委托冒险者使用一件附魔圣物活捉一只狂暴的蓟熊，试图寻找治愈之法。",kw={"净化感染者","黑海岸","瘟疫之地","狂暴的蓟熊","萨纳瑞恩·绿树","萨纳瑞恩的希望","蓟熊"},ang={["class:Druid"]="德鲁伊们在目睹自然遭受腐化后与萨纳瑞恩感同身受，而熊的悲惨死亡更加凸显了这片土地上蔓延的疾病是多么阴险。",["faction:Alliance"]="在卡利姆多北部旅行的联盟旅者必须面对那些正逼近定居领土边界的未受遏制的腐化。",["race:NightElf"]="对于卡多雷而言，看到黑海岸的本土动植物腐朽成狂暴的癫狂，是对塞纳留斯以及他们誓死捍卫的自然平衡的亵渎。"},sec={{t="荒野之灾",b="一种邪恶的疾病正在黑海岸的森林中蔓延，将这里的野兽扭曲成了疯狂而具有攻击性的旧日残影。当地的蓟熊受到的折磨最深，它们陷入了狂暴的癫狂，威胁着过往的旅人和海岸脆弱的生态平衡。暗夜精灵哨兵通常会用刀剑回应，而德鲁伊则试图理解并治愈其根源。"},{t="萨纳瑞恩的希望",b="萨纳瑞恩·绿树拒绝在尝试拯救之前就屠杀这些受腐化的野兽，于是制造了一种名为“萨纳瑞恩的希望”的特制陷阱。冒险者将该装置放置在森林地面上，利用其柔和的光芒暂时平复狂怒蓟熊的心智。一旦被安抚，野兽就会温顺地跟随旅行者回到萨纳瑞恩的前哨站接受研究。"},{t="悲剧的药剂",b="当冒险者成功将一只受感染的熊引导至营地时，萨纳瑞恩立即尝试用恢复魔法来净化疾病。遗憾的是，他的初步尝试带来了灾难性的后果：旋转的净化能量超出了野兽虚弱的体质承受极限，导致它当场倒地死亡。这次失败揭示了黑暗瘟疫的渗透究竟有多深。"}},faq={{q="谁提供了“瘟疫之地”任务？",a="该任务由萨纳瑞恩·绿树提供，他是一位位于黑海岸奥伯丁的暗夜精灵德鲁伊，致力于治愈受感染的野生动物。",al={"瘟疫之地任务发布者","萨纳瑞恩黑海岸任务","谁开启瘟疫之地任务"}},{q="“瘟疫之地”的任务目标是什么？",a="你必须使用提供的物品“萨纳瑞恩的希望”来诱捕并安抚黑海岸的狂暴的蓟熊，然后将受控的野兽活着带回给萨纳瑞恩。",al={"瘟疫之地目标","瘟疫之地怎么做","如何在黑海岸抓熊"}},{q="当你把熊带回来时会发生什么？",a="萨纳瑞恩试图用治疗魔法净化这种动物，但病情已经恶化得太深了。压力超出了野兽的承受极限，它在治疗后立即死亡。",al={"熊会死吗","萨纳瑞恩的治愈结果","瘟疫之地熊死亡"}},{q="你用什么物品来捕获这只熊？",a="萨纳瑞恩提供了一个名为“萨纳瑞恩的希望”的附魔捕获装置，它发出的平静光芒可以安抚狂怒的熊，使其跟随你。",al={"瘟疫之地陷阱","萨纳瑞恩的希望物品","黑海岸捕熊"}},{q="“瘟疫之地”之后的任务是什么？",a="“瘟疫之地”是一个三部分任务链的第一章。完成它可以解锁后续任务“净化感染者”，该任务最终通向最终任务“萨纳瑞恩的希望”。",al={"瘟疫之地后续任务","瘟疫之地任务链","萨纳瑞恩后续"}},{q="为什么蓟熊会狂暴？",a="一种潜行的腐化瘟疫正在黑海岸蔓延，毒害着当地野生动物的身心，驱使高贵的蓟熊陷入无脑的攻击状态。",al={"为什么黑海岸的熊生病了","黑海岸瘟疫熊","黑海岸腐化"}}},fx={bbb593c2={q="为什么萨纳瑞恩·绿树要你捕获一只狂暴的蓟熊？",a="一种黑暗的疾病正在黑海岸蔓延，侵蚀当地野生动物的身心。蓟熊受害最深，从高贵的林地野兽变成了狂乱的破坏机器。萨纳瑞恩·绿树认为自己或许已经研制出治疗这种疾病的方法，但他需要你把一只活着的狂暴蓟熊直接带给他，好测试药剂，并在腐化侵袭森林中所有生灵之前阻止它。",al={"为什么要捕获蓟熊","萨纳瑞恩对疫病之地的打算","萨纳瑞恩为什么要一头熊"}},["1b7f183c"]={q="狂暴的蓟熊是什么？为什么要对付它们？",a="蓟熊是黑海岸本地的森林掠食者，通常被视为坚毅而高贵的野兽。然而，一种反常的疫病最近感染了它们，令它们陷入疯狂并扭曲了心智。你接到的任务不是直接将它们杀死，而是用萨纳瑞恩的陷阱引诱并安抚一只患病的蓟熊，以便安全地检查它，并希望借此研制出解药。",al={"狂暴的蓟熊是什么","为什么要对付狂暴的蓟熊","黑海岸的狂暴蓟熊"}}},fp="13,269,26.422.0,17.371.0,15.390.1,34.139.0,39.161.0,48.186.1,41.155.0,33.189.0,32.171.0"}
P.entries["quest:213"] = {n="恶性竞争",s="盖尔瑞兹一直在排挤贸易大王任命的权贵，现在更是向最臭名昭著的海盗发难，大财主里维加兹绝不会坐视不理。作为回应，藏宝海湾的科博克指派冒险者去偷取风险投资公司地质学家在纳菲瑞提湖附近发现的奇怪蓝色水晶。",h="盖尔瑞兹一直在排挤贸易大王任命的权贵，现在更是向最臭名昭著的海盗发难，大财主里维加兹绝不会坐视不理。作为回应，藏宝海湾的科博克指派冒险者去偷取风险投资公司地质学家在纳菲瑞提湖附近发现的奇怪蓝色水晶。",kw={"藏宝海湾","盖尔瑞兹","吉格尔方特","科博克","纳菲瑞提湖","里维加兹","翻滚的水晶","风险投资公司"},sec={{t="商业问题",b="盖尔瑞兹不仅排挤贸易大王任命的权贵，还向最臭名昭著的海盗发难，此举已然越界。大财主里维加兹无法容忍这种傲慢，指示科博克采取任何必要手段处理这次入侵。科博克选择的对策是直接窃取，目标就是风险投资公司采矿队挖掘出的那些奇怪的蓝色石头。"},{t="地质学家的藏品",b="在纳菲瑞提湖周围活动的风险投资公司地质学家对这些不同寻常的水晶表现出了极大的兴趣。科博克想要八份样本带回藏宝海湾，他并不关心这些样本是如何获取的，只要能落到他手里就行。"},{t="翻滚的发现",b="对归还的标本进行检查后发现，它们经过了翻滚工艺处理，这表明风险投资公司打算将其用作燃料或工业催化剂。科博克打算将样本送往首席药剂师吉格尔方特处进行更详细的研究。"}},faq={{q="谁给予了“恶意收购”这个任务？",a="科博克，他在荆棘谷的海盗避风港藏宝海湾活动，代表大财主里维加兹下达了这项任务。",al={"恶意收购任务发布者","谁开启恶意收购","科博克任务"}},{q="大财主里维加兹为什么对盖尔瑞兹感到愤怒？",a="盖尔瑞兹排挤了贸易大王任命的权贵，现在又向最臭名昭著的海盗发难，里维加兹无法容忍这一点。",al={"里维加兹为何愤怒","盖尔瑞兹里维加兹冲突","科博克为什么想要水晶"}},{q="水晶位于何处？",a="水晶由在纳菲瑞提湖周围工作的风险投资公司地质学家携带。",al={"去哪里寻找翻滚的水晶","翻滚的水晶位置","纳菲瑞提湖水晶"}}},fp="16,324,20.384.0,21.241.0,20.261.1,37.127.0,40.158.0,31.85.0"}
P.entries["quest:2138"] = {n="清除疫病",s="“净除感染”是黑海岸的一项联盟任务，由奥伯丁的萨纳瑞恩·绿树发布。在他试图治愈的尝试失败，未能阻止林地瘟疫后，这位看守者不情愿地命令清理游荡在雾气弥漫的荒野中的狂犬蓟熊。这是一个痛苦的转折点，标志着保护让位于遏制。",h="“净除感染”是黑海岸的一项联盟任务，由奥伯丁的萨纳瑞恩·绿树发布。在他试图治愈的尝试失败，未能阻止林地瘟疫后，这位看守者不情愿地命令清理游荡在雾气弥漫的荒野中的狂犬蓟熊。这是一个痛苦的转折点，标志着保护让位于遏制。",kw={"奥伯丁","净除","黑海岸","感染","狂犬蓟熊","萨纳瑞恩","绿树"},ang={["class:Druid"]="崇敬野生熊灵的德鲁伊们发现萨纳瑞恩的命令尤其令人感伤：这是一种出于慈悲和森林分流的举措，而非例行的狩猎。",["class:Hunter"]="猎人们明白，即便根本原因尚未解决，清理患病的掠食者有时也是保护更广泛生态系统的必要之举。",["race:NightElf"]="对于卡多雷来说，下令屠杀被腐化的野兽是一种沉重的负担，这凸显了战后的腐化已深深渗透进他们的祖居之地。"},sec={{t="痛苦的必要之举",b="萨纳瑞恩·绿树花费了很长时间寻找一种能遏制侵蚀黑海岸野生动物的瘟疫的疗法。尽管他尝试净化了一头被捕获的熊，但这些蓟熊依然病入膏肓且极具攻击性。在尝试了所有温和的手段后，这位暗夜精灵看守者断定，除掉这些野兽是目前唯一能防止它们伤害其他生物，并将瘟疫进一步传播到古老林地的直接方法。"},{t="遏制荒野",b="清理二十头狂犬熊对于任何自然之仆来说都是一项痛苦的职责。萨纳瑞恩坦言，杀死这些野兽并不能治愈潜在的瘟疫，但它能为奥伯丁的保卫者争取宝贵的时间。在查明并切断森林腐化的根源之前，减少这些具有攻击性的种群是该定居点防止灾难的唯一缓冲。"}},faq={{q="为什么萨纳瑞恩想要杀死蓟熊而不是治愈它们？",a="萨纳瑞恩此前曾尝试净化一头被捕获的熊，但治愈失败，野兽死去了。随着病变的熊变得充满攻击性并威胁到其他生物，杀死它们是减缓瘟疫传播的最后手段。",al={"为什么要杀死熊","为什么不治愈熊","萨纳瑞恩的熊任务"}},{q="萨纳瑞恩·绿树是谁？",a="萨纳瑞恩是驻扎在奥伯丁的一名暗夜精灵看守者。他研究侵蚀黑海岸动植物的疾病，致力于在不断蔓延的腐化中维持自然平衡。",al={"萨纳瑞恩的角色","谁给予净除感染任务"}},{q="杀死狂犬熊真的能终结瘟疫吗？",a="不能。萨纳瑞恩明确警告说，杀死狂犬熊并不能阻止瘟疫。它只是通过减缓感染和暴力行为的发生率，为森林和奥伯丁的居民争取了宝贵的时间。",al={"这能修复黑海岸吗","瘟疫治愈了吗"}},{q="“净除感染”之后是什么任务？",a="当你回到萨纳瑞恩那里报告后，他会请你做好面对更多杀戮的心理准备，并提供后续任务“萨纳瑞恩的希望”，以继续处理受枯萎病影响的野生动物。",al={"净除感染后的下一个任务","净除感染后续"}},{q="哪里可以找到狂犬蓟熊？",a="狂犬蓟熊在黑海岸中部的沿海和内陆林区游荡，常出没于奥伯丁东南部雾气弥漫的松林中。",al={"狂犬蓟熊位置","黑海岸的熊在哪里"}},{q="什么导致了蓟熊变得狂暴？",a="这些熊是席卷卡利姆多北部林区的一场神秘腐化的受害者，这场腐化将原本平静的野生动物变成了狂暴且极具攻击性的野兽，无视了萨纳瑞恩的治愈尝试。",al={"熊为什么会生病","黑海岸的熊病"}}},fx={acd0862d={q="狂暴的蓟熊是什么？为什么必须杀死它们？",a="蓟熊是当地的森林掠食者，通常与黑海岸的荒野和谐共处。然而，一种在林间蔓延的诡异瘟疫已令许多蓟熊发狂，变得凶暴而失常。受污染的野兽在疯狂中袭击其他野生动物，威胁奥伯丁附近的旅行者，还破坏林地生态。由于治疗这种疾病的尝试都已失败，杀死它们是遏制破坏的唯一办法。",al={"狂暴的蓟熊","狂暴的蓟熊是谁","为什么杀死狂暴的蓟熊"}}},fp="25,344,18.466.0,20.402.1,67.232.0,29.192.0,53.202.0,43.189.0,40.159.0,42.192.0"}
P.entries["quest:2139"] = {n="萨纳瑞恩的希望",s="“萨纳瑞恩的希望”是萨纳瑞恩·绿树为遏制黑海岸野生动物疫病所做努力的沉重总结。在击杀森林中无数感染的野兽以使其解脱后，联盟勇士被指派去消灭奥伯丁东北部那头患有狂犬病的“大兽穴”之母。",h="“萨纳瑞恩的希望”是萨纳瑞恩·绿树为遏制黑海岸野生动物疫病所做努力的沉重总结。在击杀森林中无数感染的野兽以使其解脱后，联盟勇士被指派去消灭奥伯丁东北部那头患有狂犬病的“大兽穴”之母。",kw={"奥伯丁","巴莎兰","净化感染者","黑海岸","大兽穴之母","染病的刺鬃熊","萨纳瑞恩·绿树","萨纳瑞恩的希望"},ang={["class:Druid"]="德鲁伊通过乌索克的教导，在精神上非常尊崇熊。处决一头被腐蚀的大兽穴之母，是关于自然的微妙平衡以及腐蚀所带来的悲剧的一次庄严提醒。",["class:Hunter"]="猎人们理解被疾病折磨至疯狂的顶级掠食者的悲剧，懂得在何时扑杀感染的野兽才是真正的仁慈之举。",["faction:Alliance"]="保护奥伯丁加强了联盟在卡利姆多北部海岸的据点，证明了他们捍卫暗夜精灵领地免受日益严重的荒野威胁的决心。",["race:NightElf"]="对于暗夜精灵而言，杀害林地野兽——尤其是母熊——违背了他们对自然的基本敬畏，这使得这项职责成为一种痛苦而悲伤的必然。"},sec={{t="悲剧性的必要之举",b="第三次战争后，黑海岸的野生生物开始染上一种非自然的狂犬病。驻守奥伯丁的萨纳瑞恩·绿树花费了数日时间，指派过往的旅者去解决那些受感染的野兽，以减轻森林的苦痛。然而，扑杀染病的刺鬃熊仅仅是治标。为了阻止瘟疫蔓延，他断定必须根除当地熊群中的源头：那位被称为“大兽穴”之母的雌兽。"},{t="大兽穴之母",b="“大兽穴”之母潜伏在奥伯丁东北部、巴莎兰古迹附近的一个洞穴中，它曾是林地动物群的重要守护者。受困于席卷卡利姆多北部的疯狂折磨，它不断产下并抚育着患有狂犬病的幼崽。通过在洞穴中猎杀这位母亲，联盟英雄结束了它的痛苦，也遏制了那群在沿海公路上徘徊的狂暴熊群。"},{t="卡利姆多的严酷现实",b="在大兽穴之母死后，萨纳瑞恩表达了深切的感激，但同时也笼罩在忧郁之中。对于卡多雷来说，对林地生物举起武器是一种痛苦的职责。然而，随着黑暗力量压向他们的新家园，许多人感到绝望或寻求庇护，像这样的行动证明了奥伯丁的保卫者们愿意承担起保护荒野所必需的沉重道德负担。"}},faq={{q="谁是萨纳瑞恩·绿树？",a="萨纳瑞恩·绿树是驻扎在奥伯丁的一位暗夜精灵照看者。由于黑海岸的野生动物被枯萎和疯狂所扭曲，他深感不安，并负责监督对这些受苦动物的研究、追踪以及最终让它们解脱的工作。",al={"萨纳瑞恩","谁提供萨纳瑞恩的希望","绿树 奥伯丁"}},{q="大兽穴之母位于何处？",a="它栖息在奥伯丁东北部山丘中的一个洞穴里，就在巴莎兰遗迹的东面。",al={"大兽穴之母在哪里","大兽穴之母洞穴位置","找到大兽穴之母"}},{q="为什么必须杀死大兽穴之母，而不是治愈它？",a="肆虐黑海岸野生动物的瘟疫已经深入骨髓，并正驱使野兽陷入狂暴。由于目前没有立竿见影的治疗方法，且大兽穴之母还在不断繁育染病的后代，萨纳瑞恩断定，将其击杀是阻止瘟疫进一步蔓延的唯一途径。",al={"大兽穴之母能被拯救吗","为什么要杀大兽穴之母","治疗大兽穴之母"}},{q="哪些任务引导至“萨纳瑞恩的希望”？",a="该任务是三部分任务链的最后一步。它始于“被瘟疫感染的土地”，经过“净化感染者”，最后以“萨纳瑞恩的希望”结束。",al={"萨纳瑞恩的希望前置任务","萨纳瑞恩任务链"}},{q="是什么让黑海岸的动物生病？",a="萨纳瑞恩没有指明源头。他只知道某种瘟疫正在黑海岸蔓延，控制着它所触及的一切生物的思想和身体，而刺鬃熊受到的影响最为严重。",al={"为什么黑海岸的熊会患狂犬病","黑海岸动物瘟疫起因","什么腐蚀了这些熊"}},{q="为什么萨纳瑞恩会提到人们逃往防御更严密的领地？",a="奥伯丁是一个暴露在外的沿海哨所，饱受幽灵、堕落野生动物和敌对生物的困扰。随着暗夜精灵文明在燃烧军团入侵后的废墟上艰难重建，一些居民感到不堪重负，选择躲藏起来或撤往更安全的联盟堡垒。",al={"逃离奥伯丁","防御严密的联盟领地"}}},fx={f873ab28={q="兽穴之母是谁？",a="兽穴之母是一头体型庞大、受到腐化的熊，栖居在巴莎兰废墟东北方附近的一处洞穴中。她是这片地区狂暴蓟熊的源头，负责繁衍或庇护这些肆虐的野兽。杀死她就能切断患病野兽的来源，免得它们继续威胁奥伯丁。",al={"兽穴之母是什么","兽穴之母是谁","黑海岸的兽穴之母"}}},fp="17,272,18.445.0,14.431.1,28.400.0,29.234.0,32.110.0,51.305.0,41.170.0,45.198.0,63.294.0"}
P.entries["quest:214"] = {n="红色丝质面罩",s="“红色丝绸面罩”是一项由哨兵瑞尔代表人民民兵团发布的任务。该任务指引联盟的冒险者进入死亡矿井，猎杀高级别的迪菲亚潜行者，并将他们标志性的红色丝绸面罩带回来作为凭证。",h="“红色丝绸面罩”是一项由哨兵瑞尔代表人民民兵团发布的任务。该任务指引联盟的冒险者进入死亡矿井，猎杀高级别的迪菲亚潜行者，并将他们标志性的红色丝绸面罩带回来作为凭证。",kw={"死亡矿井","迪菲亚潜行者","月溪镇","人民民兵团","红色丝绸面罩","哨兵瑞尔","范克里夫","西部荒野"},ang={["class:Rogue"]="迪菲亚的红色丝绸面罩代表了一种臭名昭著的地下贸易传统，用以标识资深的恶棍和隐秘的阴谋分子。",["faction:Alliance"]="每一名在死亡矿井中倒下的军官，都在削弱兄弟会对暴风城王国粮仓的铁腕统治。",["profession:Tailoring"]="对于普通强盗来说，上等的红色丝绸是一种昂贵的奢侈品，这突显了兄弟会的高层拥有多么豪奢的装备和资金。"},sec={{t="布料背后的阶级",b="虽然西部荒野随处可见的剪径强盗和拦路劫匪都在脸上缠着粗糙的红布，但迪菲亚潜行者内部维持着严格的阶级制度，而这种制度通过布料来体现。哨兵瑞尔和人民民兵团已经发现，普通的流寇佩戴的是粗织布，而资深的阴谋分子和核心成员则以精致的红色丝绸来区分身份。剥下这些面罩，相当于直接针对那些正在策划艾德温·范克里夫起义的经验丰富的军官。"},{t="直击核心",b="因为丝绸象征着资历，这些高级别的不法之徒大多聚集在月溪镇地下深处的死亡矿井内。驻扎在哨兵岭外的哨兵和侦察兵依靠自由勇士深入这些充满危险的地下隧道。每带回一条丝绸面罩，就意味着少了一名策划伏击、守卫军火库或在西部荒野执行范克里夫统治的副官。"}},faq={{q="为什么迪菲亚成员戴红色面罩？",a="红色面罩是迪菲亚潜行者在暴风城领地内的统一徽记和标志。它既能掩盖他们的身份，也象征着对艾德温·范克里夫叛乱运动的效忠。",al={"迪菲亚面罩含义","为什么戴红色面罩","迪菲亚制服"}},{q="红色丝绸面罩与普通面罩有什么特别之处？",a="据哨兵瑞尔所说，布料的材质代表了在兄弟会中的地位。普通的街头暴徒佩戴粗糙廉价的材料，而老兵、军官和备受信任的副官则会被授予红色丝绸面罩。",al={"为什么是红色丝绸","丝绸与布料的区别","丝绸面罩的区别"}},{q="哨兵瑞尔是谁？",a="哨兵瑞尔是一名服务于西部荒野人民民兵团的特工，负责追踪迪菲亚的动向，并指引冒险者袭击他们在死亡矿井周边的据点。",al={"哨兵瑞尔 西部荒野","谁发布红色丝绸面罩任务"}},{q="佩戴丝绸面罩的迪菲亚成员在哪里？",a="他们聚集在月溪镇地下的死亡矿井内及其周边地区，艾德温·范克里夫的高级部下在那里指挥着地下行动。",al={"哪里寻找丝绸面罩","死亡矿井丝绸面罩位置"}},{q="什么是人民民兵团？",a="人民民兵团是由格里安·斯托曼和饱受战火蹂躏的西部荒野农民组成的志愿防御部队，旨在暴风城军队未能提供足够的驻军后保护他们的土地。",al={"谁是人民民兵团","人民民兵团 西部荒野"}},{q="除了作为击杀凭证，这些面罩还有其他用处吗？",a="对于人民民兵团来说，它们纯粹是消灭了高级不法之徒的无可辩驳的证据，削弱了兄弟会的指挥体系。",al={"可以佩戴红色丝绸面罩吗","面罩的用途是什么"}}},fx={["09c03d28"]={q="为什么哨兵瑞尔要收集迪菲亚头巾？",a="哨兵瑞尔代表人民军，正设法给迪菲亚潜行者的首领以沉重打击。民兵知道，丝质头巾代表高阶军官，而非普通暴徒。瑞尔希望除掉这些关键人物，并以他们的头巾作为凭证，从而瓦解潜行者的指挥体系，最终让西部荒野重归人民手中。",al={"瑞尔为什么要头巾","哨兵瑞尔的目的","为什么收集红色丝质头巾"}},["762e9a74"]={q="你要对付的是谁？",a="你要追猎的是驻扎在死亡矿井及其周边、效忠于艾德温·范克里夫的迪菲亚潜行者精锐军官和老兵。他们不同于在西部荒野农场周围游荡的粗野匪徒，这些高阶成员守卫着潜行者的行动据点，监管月溪镇深处的秘密工程，并指挥他们在整个地区的行动。",al={"我们要追猎谁","红色丝质头巾的目标","谁会掉落丝质头巾"}},["966e78fe"]={q="为什么哨兵瑞尔找你帮忙，而不是找暴风城卫兵？",a="暴风城几乎已经放弃了西部荒野，基本没有提供军事支援，而贵族议会也对日益严重的危机视而不见。当地人民军兵力捉襟见肘，缺少足够的人手、训练和资源，无法正面攻打戒备森严的罪犯据点。瑞尔和她的同伴只能依靠有本事的冒险者潜入危机四伏的死亡矿井，直接对付潜行者的首领。",al={"为什么不派暴风城军队","为什么派冒险者去","为什么需要我"}}},fp="17,240,20.475.0,17.421.0,36.216.0,70.196.0,19.186.0,51.149.0,29.201.0,57.165.0"}
P.entries["quest:215"] = {n="丛林中的秘密",s="在北荆棘谷从一场伏击中被救出后，列兵索尔森解释了他为何重新加入库尔森上校的部队。他指引你回到反抗军营地，以便他的指挥官能核实他的秘密意图。",h="在北荆棘谷从一场伏击中被救出后，列兵索尔森解释了他为何重新加入库尔森上校的部队。他指引你回到反抗军营地，以便他的指挥官能核实他的秘密意图。",kw={"doren","库尔森","反抗军营地","荆棘谷","索尔森","叛徒","尤瓦"},ang={["faction:Alliance"]="反抗军营地依赖于列兵索尔森希望能从库尔森的部队中带回的急需情报。"},sec={{t="一项秘密行动",b="在被救出后，列兵索尔森承认现场的情况看起来很糟糕，并请求解释。他声称多伦上尉命令他重新加入库尔森上校的部队，为反抗军收集急需的情报。原本看似是渗透进库尔森的营地的机会，很快就演变成了一场灾难，迫使索尔森要求你直接去找反抗军营地的多伦进行官方确认，同时乞求绝对的保密。"},{t="营地疑云",b="多伦上尉证实，索尔森确实是在执行他的命令。反抗军曾经对库尔森极其忠诚，直到库尔森的腐化将他们的忠诚扭曲成了愤怒，如果索尔森的行为被发现，他会被自己的同志割喉。因为只有多伦、尤瓦中士和索尔森应该知道这个计划，伏击的失败揭示了一个令人不安的事实：队伍中潜伏着一个未知的叛徒。"}},faq={{q="为什么列兵索尔森要与库尔森的部队会面？",a="他是在执行多伦上尉的命令，重新加入库尔森上校的部队担任间谍，并为反抗军收集重要的军事机密。",al={"为什么索尔森要见库尔森","索尔森是叛徒吗","为什么索尔森在营地外"}},{q="列兵索尔森让你去哪里？",a="他指引你与北荆棘谷反抗军营地的多伦上尉交谈，以便该指挥官核实他的说辞。",al={"我该去哪里","索尔森任务交还","多伦在哪里"}},{q="为什么索尔森坚持要保密？",a="反抗军曾经对库尔森上校极其忠诚。如果索尔森曾与库尔森的部队有往来的消息传出去，他可能会在夜里被杀。",al={"为什么要保密","为什么要进行秘密任务"}},{q="向多伦上尉汇报后会发生什么？",a="在与多伦上尉交谈后，你的搜寻工作将进入下一步：赌徒赫洛德。",al={"下一个任务","丛林秘密之后是什么"}}},fp="14,218,20.446.0,18.442.1,53.152.0,36.134.0,35.152.0,47.102.0"}
P.entries["quest:2158"] = {n="休息和放松",s="“休息和放松”是联盟的一项新手任务，引导刚受训的冒险者从北郡山谷沿路向南前往Lion's Pride Inn。这家繁华的闪金镇旅店由旅店老板法雷经营，为那些寻求休憩的旅人提供食物、饮料和温暖的炉火。",h="“休息和放松”是联盟的一项新手任务，引导刚受训的冒险者从北郡山谷沿路向南前往Lion's Pride Inn。这家繁华的闪金镇旅店由旅店老板法雷经营，为那些寻求休憩的旅人提供食物、饮料和温暖的炉火。",kw={"联盟旅店","艾尔文森林","闪金镇","旅店老板法雷","lion's pride inn","北郡","休息和放松"},ang={["faction:Alliance"]="Lion's Pride Inn是联盟旅人前往艾尔文森林探险时的主要避风港和社交中心。",["race:Human"]="从北郡山谷出发的新兵自然会沿南向大路前往闪金镇，在那里，旅店老板法雷在暴风城附近为他们提供了宾至如归的服务。"},sec={{t="路上的避风港",b="在北郡山谷历练之后，疲惫的旅人会被指引向南，前往闪金镇的Lion's Pride Inn。沿南向大路走，可以直接到达这家深受欢迎的旅店，其经营者正是旅店老板法雷。对于走出森林大道的冒险者而言，这是他们离开修道院后遇到的第一个提供炉火、住所和热食的主要前哨站。"},{t="法雷的炉火与好客之道",b="旅店老板法雷以其旅店的热情好客为荣，他的座右铭是为疲惫和寒冷的人们提供休息与放松。提到介绍信的冒险者可以受到法雷的优待，坐在炉火旁享用热餐和浓郁的麦芽酒，在深入艾尔文森林继续冒险之前，获得急需的休憩。"}},faq={{q="我在哪里可以找到Lion's Pride Inn？",a="Lion's Pride Inn位于北郡山谷主路向南，坐落在闪金镇的中心。向南旅行的旅人绝不会错过这家温馨的旅店。",al={"lion's pride inn在哪里","如何前往lion's pride inn","寻找lion's pride"}},{q="谁是旅店老板法雷？",a="旅店老板法雷是闪金镇Lion's Pride Inn热情好客的主人。他是北郡山谷当地联络人的挚友，总是用食物、饮料和温暖的炉火欢迎疲惫的冒险者。",al={"旅店老板法雷是谁","法雷 lion's pride"}},{q="“休息和放松”任务的目的是什么？",a="“休息和放松”引导离开北郡山谷的初级冒险者前往闪金镇的核心地带，并向他们介绍旅店老板法雷在Lion's Pride Inn提供的服务、补给和住宿。",al={"这个任务的目的是什么","为什么要前往lion's pride inn"}},{q="旅店老板法雷真的提供打折的食物和饮料吗？",a="向旅店老板法雷出示介绍信后，旅人可以咨询关于旅店优质食物和饮料的特别优惠价格，以便在旅途后恢复精力。",al={"lion's pride折扣","我能从法雷那里得到更便宜的食物吗"}},{q="为什么休息对旅行的冒险者很重要？",a="在艾尔文森林中冒险既艰苦又危险重重。旅店为荒野中的人们提供了安全的避难所，让旅人可以在炉火旁温暖身体、恢复体力，并在接受新任务前补充补给。",al={"为什么冒险者需要休息","休息和放松背景知识"}},{q="Lion's Pride Inn的座右铭是什么？",a="据旅店老板法雷所说，旅店的座右铭是“为疲惫和寒冷的人们提供休息与放松”。他致力于确保每一位疲惫的客都能在他的炉火旁感受到舒适与好客。",al={"lion's pride inn的座右铭是什么","lion's pride口号"}}},fp="19,288,19.349.0,31.355.0,38.197.0,24.198.0,43.211.0,61.173.0,48.230.0,42.179.0"}
P.entries["quest:2159"] = {n="多兰纳尔的货物",s="多兰纳尔的货物是托付给即将离开幽影谷的庇护枝干、前往泰达希尔更广阔区域的年轻暗夜精灵的一项差事。伯萨努斯因当地德鲁伊的事务缠身，便委托旅行者将一包草药带往南方的旅店老板凯达米尔处。这段简单的旅程标志着一名新手向繁华的多兰纳尔枢纽的过渡。",h="多兰纳尔的货物是托付给即将离开幽影谷的庇护枝干、前往泰达希尔更广阔区域的年轻暗夜精灵的一项差事。伯萨努斯因当地德鲁伊的事务缠身，便委托旅行者将一包草药带往南方的旅店老板凯达米尔处。这段简单的旅程标志着一名新手向繁华的多兰...",kw={"运送","多兰纳尔","多兰纳尔的货物","草药","旅店老板凯达米尔","暗夜精灵","伯萨努斯","幽影谷","泰达希尔"},ang={["class:Druid"]="伯萨努斯对幽影谷德鲁伊事务的专注，暗示了塞纳里奥议会在树枝间所面临的更深层的精神职责和自然失衡问题。",["profession:Herbalism"]="这次运送展示了来自幽影谷肥沃土壤的原材料草药对于多兰纳尔的治疗者、厨师和照料者来说是多么重要。",["race:NightElf"]="接受这项任务标志着暗夜精灵离开了奥达希尔的庇护摇篮，开始承担守护泰达希尔的更广泛责任。"},sec={{t="幽影谷的信使",b="在新冒险者离开幽影谷的训练场之前，伯萨努斯会寻找前往泰达希尔其余地区的人。由于被照顾林地的德鲁伊们的紧急事务缠身，他无法分身亲自处理日常差事。于是，他将一捆刚采集的草药交到一位有抱负的英雄手中，以确保这些重要的物资能沿着林间小路送往南方。"},{t="通往多兰纳尔之路",b="沿着幽谷南面的道路前行，会将旅行者引向多兰纳尔，这是位于泰达希尔巨枝上的重要暗夜精灵定居点之一。在那里，旅店老板凯达米尔负责为流浪者、哨兵和德鲁伊提供食宿、休息和补给。凯达米尔代表伯萨努斯收下草药，并借此机会劝诫年轻的冒险者在面对世界之树上日益严重的腐蚀之前，先让身心得到充分的休息。"}},faq={{q="谁是伯萨努斯？",a="伯萨努斯是一位居住在泰达希尔起始林地——幽影谷的暗夜精灵。在与当地德鲁伊密切合作的同时，他会招募离开林地的旅行者代他向南运送物资。",al={"伯萨努斯","多兰纳尔的货物任务发布者","任务发布者伯萨努斯"}},{q="为什么伯萨努斯不能亲自运送草药？",a="伯萨努斯有紧迫且未完成的事务需要与幽影谷的德鲁伊处理。由于职责使他必须留在幽谷之内，他不得不依靠路过的冒险者来完成向南的旅程。",al={"伯萨努斯为什么需要帮助","为什么伯萨努斯不能亲自去"}},{q="包裹里装的是什么？",a="包裹里装的是在幽影谷内采集的草药，准备用于多兰纳尔的旅店。",al={"多兰纳尔的货物包裹内容","这些草药是什么"}},{q="旅店老板凯达米尔是谁？",a="旅店老板凯达米尔经营着多兰纳尔的旅店。除了为旅行者提供食宿和炉石，他还经常协调与泰达希尔各地定居点之间的贸易和物资交换。",al={"凯达米尔","多兰纳尔旅店老板","谁来接收这些草药"}},{q="多兰纳尔位于何处？",a="多兰纳尔位于幽影谷以南。沿着通往林地出口的主路走，旅行者可以直接到达城镇中心。",al={"多兰纳尔在哪里","多兰纳尔位置","去往多兰纳尔的路线"}},{q="这次运送任务对年轻的冒险者为何重要？",a="这既是对幽影谷之外世界的初步接触，也鼓励新手走出训练场，去探索多兰纳尔的旅店、训练师和服务提供者。",al={"运送任务的意义","为什么要运送草药"}}},fx={e1815add={q="为什么伯萨努斯需要把这包东西送到多兰纳尔？",a="伯萨努斯准备了一包在幽影谷采集的新鲜草药，旅店老板凯达米尔正在多兰纳尔等着收货。然而，伯萨努斯有紧急事务要与当地德鲁伊处理，无法亲自沿路前往。为了让旅店老板及时收到这些必需的补给，他只好拜托一位正要深入泰达希尔的过路旅人。",al={"伯萨努斯送货的原因","为什么把草药送到多兰纳尔","多兰纳尔的货物的用途"}}},fp="17,359,26.414.0,20.466.0,19.211.0,48.201.0,27.111.0,26.216.0,26.140.0,53.187.0"}
P.entries["quest:2160"] = {n="塔诺克的补给品",s="“交给塔诺克的补给品”是一项委托给初出茅庐的冒险者的任务，他们将离开寒脊山谷，穿过危险的山间小径，进入更为广阔的丹莫罗。侏儒修补匠汉兹·跳链需要将一箱必需的补给品送给卡拉诺斯雷酒酿制厂旅店的塔诺克·霜锤，以此绕过那些阻断了常规贸易、到处都是穴居人的小径。",h="“交给塔诺克的补给品”是一项委托给初出茅庐的冒险者的任务，他们将离开寒脊山谷，穿过危险的山间小径，进入更为广阔的丹莫罗。侏儒修补匠汉兹·跳链需要将一箱必需的补给品送给卡拉诺斯雷酒酿制厂旅店的塔诺克·霜锤，以此绕过那些阻断...",kw={"安威玛尔","寒脊山小径","汉兹·跳链","卡拉诺斯","交给塔诺克的补给品","塔诺克·霜锤","雷酒","穴居人"},ang={["faction:Alliance"]="尽管有凶猛的穴居人入侵，恢复孤立前哨站之间的贸易依然能让铁炉堡的内陆补给线保持畅通。",["race:Dwarf"]="将补给品从安威玛尔运送到卡拉诺斯，标志着你完成了走出庇护山谷的成年礼，开始为更广阔的铁炉堡王国效力。",["race:Gnome"]="帮助汉兹·跳链展现了诺莫瑞根流亡者与他们在丹莫罗的矮人东道主之间可靠的合作关系。"},sec={{t="被封锁的山谷",b="寒脊山谷一直是年轻的铁炉堡矮人和诺莫瑞根流亡者幸存者的试炼场与避难所，但最近发生的事件导致其与丹莫罗其他地区的联系变得紧张。穴居人的入侵淹没了寒脊山小径，使得这条山路变得危机四伏。山地巡逻队员们为了守卫定居点和防御周界已经分身乏术，导致原本计划好的补给护送任务一再延误。"},{t="汉兹与旅店老板的助手",b="汉兹·跳链，一位在寒脊山小径入口处等待的侏儒，发现自己手中有一箱运往卡拉诺斯的重要旅店补给品，却苦于没有安全的方式亲自运送。他意识到勇敢的冒险者们正准备闯过这条危险的小径，便征募了这些外出的旅行者，将货物带给在繁忙的雷酒旅店工作的助手塔诺克·霜锤。"},{t="卡拉诺斯温馨的炉火",b="到达卡拉诺斯标志着冒险者正式进入了更为广阔的丹莫罗世界。塔诺克·霜锤急切地收下了这批货物，并提到自从穴居人阻断了这条山路后，安威玛尔的消息就变得非常匮乏。运送这些物资恢复了这两个孤立的矮人社区之间脆弱的通讯和贸易往来。"}},faq={{q="汉兹·跳链是谁？",a="汉兹·跳链是一位驻扎在寒脊山谷寒脊山小径入口处的进取心十足的侏儒。由于无法独自穿过危险的山间小径，他依靠有能力的旅行者将货物运往卡拉诺斯。",al={"汉兹·跳链","任务发布者","谁把补给品交给塔诺克"}},{q="塔诺克·霜锤是谁？",a="塔诺克·霜锤是卡拉诺斯雷酒酿制厂的一位旅店助理。他协助管理当地酒馆的物流，并负责接收来自安威玛尔等前哨站运送来的补给品。",al={"塔诺克","塔诺克·霜锤","卡拉诺斯旅店助理"}},{q="为什么汉兹不能亲自运送补给品？",a="连接寒脊山谷和卡拉诺斯的小径已被敌对的穴居人占领。汉兹没有装备来独自杀出一条血路，而官方的山地巡逻队护送任务也严重延误了。",al={"为什么汉兹不能运送补给品","为什么需要冒险者","为什么小径危险"}},{q="卡拉诺斯的旅店在哪里？",a="塔诺克·霜锤位于雷酒酿制厂内，这是一家大型旅店，位于卡拉诺斯的中心，紧邻通往东面铁炉堡的主干道。",al={"塔诺克在哪里","雷酒酿制厂位置","卡拉诺斯旅店位置"}},{q="一箱旅店补给品里有什么？",a="这个箱子里装满了在安威玛尔收集的必要酒馆杂货和补给品，用于补充卡拉诺斯雷酒旅店的库存。",al={"箱子里装了什么","一箱旅店补给品"}},{q="为什么安威玛尔和卡拉诺斯之间的通讯中断了？",a="从地下隧道涌出的穴居人淹没了寒脊山小径。它们咄咄逼人的存在切断了寒脊山谷与丹莫罗其他地区之间便捷的步行路线和定期的派遣往来。",al={"为什么安威玛尔消息匮乏","小径的穴居人问题"}}},fx={["6d15a4f4"]={q="为什么汉兹·跳链要把补给品送到卡拉诺斯？",a="汉兹·跳链答应给卡拉诺斯旅店的助手塔诺克·霜锤送去重要补给，但穴居人的袭击使穿过寒脊山谷的道路无法通行。常规货运被困在路上，山地卫兵的护送也要几天后才能抵达，塔诺克只能眼看补给逐渐耗尽，焦急地等待。汉兹想履行送货的承诺，确保热闹的雷酒酿制厂和旅店能为风尘仆仆的旅人备足物资。",al={"为什么把补给品送给塔诺克","汉兹·跳链的目的","为什么要运送一箱旅店补给品"}}},fp="18,367,18.421.0,35.402.0,30.353.0,28.224.0,26.196.0,45.192.0,37.174.0,41.140.0,59.201.0"}
P.entries["quest:2161"] = {n="苦工的重担",s="“苦工的重担”是一项入门级的递送任务，由乌克尔发布，他是一位焦虑的兽人劳工，被困在试炼谷外的道路上。在试图向并不需要补给的新兵运送物资后，乌克尔委托路过的旅者将这沉重的货物安全送回剃刀岭。",h="“苦工的重担”是一项入门级的递送任务，由乌克尔发布，他是一位焦虑的兽人劳工，被困在试炼谷外的道路上。在试图向并不需要补给的新兵运送物资后，乌克尔委托路过的旅者将这沉重的货物安全送回剃刀岭。",kw={"杜隆塔尔","食物","旅店老板格罗斯克","苦工","剃刀岭","补给","乌克尔","试炼谷"},ang={["faction:Horde"]="这段路程是走出试炼场的过渡，引导旅者前往剃刀岭，那里是杜隆塔尔南部部落防御和后勤的中心枢纽。",["race:Orc"]="兽人文化崇尚体能与勇气，这使得像乌克尔这样的苦工处于社会等级的最底层；承担他的差事向人们展示了即使是卑微的劳作，也能让杜隆塔尔这个新兴国家正常运转。"},sec={{t="误送的货物",b="乌克尔是一位诚恳的苦工，他怀着好意从剃刀岭出发，拖着沉重的补给包前往试炼谷。他认为在红色峡谷中训练的新兵急需口粮，于是冒险上路，结果却被拒之门外。负责监督试炼的训练师故意让补给保持在匮乏水平——正如旅店老板格罗斯克后来指出的那样，靠微薄的口粮生存被视为磨练年轻部落勇士纪律和耐力的一种方式。"},{t="红色荒原的危险",b="虽然他设法到达了山口，但乌克尔却被要在杜隆塔尔那被烈日炙烤的土地上原路返回的恐惧所笼罩。沿途的岩壁上挤满了具有攻击性的蝎子、毒蜘蛛和徘徊的野猪。这位受惊的劳工既没有武器、盔甲，也不具备兽人步兵应有的战斗精神，他只能守在路边，恳求任何离开试炼场、路过的冒险者帮他扛起重担，送回旅店。"}},faq={{q="乌克尔是谁？",a="乌克尔是一位驻扎在通往试炼谷道路上的兽人苦工。他心地善良但性格胆怯，从剃刀岭出发去运送补给，后来意识到自己太害怕当地的野生生物，无法独自踏上归途。",al={"乌克尔","路上的苦工是谁","试炼谷附近的苦工"}},{q="为什么试炼谷的训练师不要这些食物？",a="试炼谷的监督者们相信对新兵进行严格的纪律训练。正如旅店老板格罗斯克幽默地指出的那样，教官们更愿意让受训者保持饥饿以考验他们的勇气并磨练意志，这使得乌克尔的一片好心成了多余。",al={"为何拒收食物","乌克尔为何搬运食物","旅店老板格罗斯克与饥饿训练"}},{q="这份货物需要送到哪里？",a="这份货物必须沿着杜隆塔尔的主干道向北运送至剃刀岭，并交给位于营地旅店内的旅店老板格罗斯克。",al={"剃刀岭在哪里","我该把食物交给谁","乌克尔的货物送到哪里"}},{q="是什么让苦工的旅程变得危险？",a="杜隆塔尔的岩石荒原上到处都是领地意识极强的蝎子、毒爬蛛和野猪。虽然经验丰富的新兵可以对付这些害虫，但像乌克尔这样没有盔甲、未经训练的劳工一旦被袭击，几乎毫无生还希望。",al={"乌克尔为何害怕","杜隆塔尔路上的危险"}},{q="苦工在部落中的角色是什么？",a="苦工处于兽人社会的底层，负责搬运补给、砍伐木材和建造防御工事等琐碎劳作。虽然步兵和勇士们能获得赞美与荣耀，但苦工们尽管让营地得以维持和运转，却常常被人们所忽视。",al={"兽人苦工背景资料","苦工的地位","什么是苦工"}},{q="旅店老板格罗斯克是谁？",a="旅店老板格罗斯克经营着剃刀岭的旅店。他管理着城镇的住宿和补给，为路过的勇士提供食物、饮料和温暖的壁炉，并提醒新兵在面对更广阔的世界之前，休息至关重要。",al={"旅店老板格罗斯克","格罗斯克与剃刀岭","剃刀岭旅店老板"}}},fx={["777a74e1"]={q="为什么乌克尔要把食物送回剃刀岭？",a="乌克尔把补给品从剃刀岭运出来时确实是出于好意，希望帮助在试炼谷烈日下训练的新兵。教官们拒收了这些口粮，他也不能就这样把补给品丢下，或任由它们在路上变质。这些食物应该放回旅店老板格罗斯克的储藏室，但乌克尔刚刚才勉强穿过当地的蝎子和蜘蛛，吓得不敢独自踏上危险的归途。",al={"为什么要把食物送回去","乌克尔的目的","为什么把食物交给格罗斯克"}},fe82ef3c={q="为什么乌克尔让你替他扛这个担子，而不是自己送回去？",a="乌克尔只是个普通苦工，不习惯暴力，也没有武器来对付荒野里的危险。他虽然成功穿过了剃刀岭外的蝎子和蜘蛛，但想到还要再次面对那些凶残的掠食者，恐惧便让他动弹不得。他看到你从试炼谷凯旋而归，认定你是无所畏惧的能干英雄，希望你能顺路把这副担子带回剃刀岭。",al={"乌克尔为什么不能自己搬","苦工的重担为什么找我","乌克尔为什么找我帮忙"}}},fp="15,305,20.477.0,23.460.0,12.254.0,62.278.0,36.156.0,44.229.0,39.269.0,23.222.0"}
P.entries["quest:217"] = {n="保卫国王的领土",s="“保卫国王领地”的任务最终将演变成对洛克莫丹穴居人入侵者首领的直接打击。矮人侦察兵追踪到了这起暴力入侵事件的源头，发现碎石怪之谷深处盘踞着格拉姆格酋长及其残暴的保镖。拉格弗斯上尉委派勇敢的联盟冒险者去击杀这位酋长，以粉碎穴居人的士气并收复王国的南部边境。",h="“保卫国王领地”的任务最终将演变成对洛克莫丹穴居人入侵者首领的直接打击。矮人侦察兵追踪到了这起暴力入侵事件的源头，发现碎石怪之谷深处盘踞着格拉姆格酋长及其残暴的保镖。拉格弗斯上尉委派勇敢的联盟冒险者去击杀这位酋长，以粉碎...",kw={"布劳勒","格纳舍","格拉姆格","国王领地","洛克莫丹","拉格弗斯","碎石怪","穴居人"},ang={["faction:Alliance"]="保卫洛克莫丹可以维护铁炉堡与东部边境之间至关重要的陆路连接，确保所有联盟部队的补给线安全。",["race:Dwarf"]="对于矮人而言，将穴居人从卡兹莫丹古老的土地上赶走是保卫家园与荣誉的问题，确保山堡不被地下灾祸所玷污。"},sec={{t="斩首虫群",b="在洛克莫丹南部肆虐的穴居人威胁已经不仅仅是随机的地下爬行生物骚扰了。拉格弗斯上尉的侦察兵发现，碎石怪穴居人在一个名叫格拉姆格的酋长的粗暴指挥下行动。与通常四散的掠夺者不同，这群穴居人展现出了协同一致的侵略性，如果不加以遏制，它们可能会践踏国王的领地。通过深入它们的巢穴，将格拉姆格及其私人打手一并处决，矮人守卫希望能够瓦解这群怪物的凝聚力并扭转局势。"},{t="深入碎石怪巢穴",b="格拉姆格盘踞在碎石怪之谷东南部悬崖内的一个阴暗洞穴中。在它最信任的打手——格纳舍和布劳勒——的簇拥下，这位酋长对孤身冒险者构成了巨大的挑战。击杀这个核心集团将迫使剩余的穴居人陷入混乱，从而为处境艰难的登山者们争取到宝贵的机会，以便他们能够加固道路并将这些野兽赶回黑暗的深渊。"}},faq={{q="谁是格拉姆格？",a="格拉姆格是那名邪恶的穴居人酋长，他正集结洛克莫丹南部的碎石怪穴居人发动攻击。矮人侦察兵确认他就是骚扰山谷的组织化袭击背后的主谋，他的身边时刻带着两名强大的保镖：格纳舍和布劳勒。",al={"格拉姆格背景故事","穴居人首领是谁","格拉姆格酋长"}},{q="格拉姆格和他的守卫在哪里？",a="格拉姆格、格纳舍和布劳勒都在洛克莫丹碎石怪之谷东南边缘的一个洞穴中安营扎寨。他们共同居住在洞穴深处。",al={"格拉姆格位置","格拉姆格在哪里","格拉姆格怎么找"}},{q="谁是拉格弗斯上尉？",a="拉格弗斯上尉是驻扎在洛克莫丹南部岗哨的矮人军官。他负责监督针对穴居人入侵的防御行动，并发布保护国王领地领土完整的命令。",al={"拉格弗斯","拉格弗斯上尉职责","谁发布保卫国王领地的任务"}},{q="为什么格拉姆格的保镖也必须被击杀？",a="格纳舍和布劳勒是格拉姆格的私人打手，从不离他左右。要消灭这位酋长并彻底粉碎穴居人攻势的领导核心，必须将这两名强大的守卫与他们的头领一起击败。",al={"为什么击杀格纳舍和布劳勒","格纳舍和布劳勒","格拉姆格保镖"}},{q="格拉姆格被消灭后会发生什么？",a="击杀格拉姆格将为洛克莫丹带来至关重要的缓解。失去了指挥突袭的酋长，碎石怪穴居人将失去组织性，这将使当地的矮人民兵有机会守住边境，并将这些野兽赶回地下。",al={"击杀格拉姆格的结果","格拉姆格死后穴居人会怎样","洛克莫丹安全了吗"}},{q="为什么穴居人会入侵洛克莫丹？",a="穴居人长期以来一直在卡兹莫丹地下的地穴中滋生。挖掘工作和未封闭的洞穴让它们能够涌上地表，肆意驱逐定居点并攻击国王道路上的旅客。",al={"为什么这里有穴居人","洛克莫丹穴居人入侵","碎石怪穴居人起源"}}},fx={["440a3b53"]={q="为什么拉格弗斯上尉要杀死格拉乌姆格？",a="拉格弗斯上尉认为，威胁洛克莫丹的穴居人入侵都是格拉乌姆格在幕后主使。矮人的驻军一直在竭力抵挡穴居人的地下大军，拉格弗斯相信，只要斩断他们的领导核心——尤其是除掉格拉乌姆格及其精锐护卫——就能挫败他们的攻势，让矮人有机会把他们赶回地下。",al={"拉格弗斯上尉的目的","为什么杀死格拉乌姆格","保卫国王领地的用途"}}},fp="30,391,22.553.0,23.450.0,15.278.0,41.171.0,25.246.0,43.231.0,41.266.1,35.241.0"}
P.entries["quest:2178"] = {n="炖陆行鸟",s="“简单的陆行鸟生活”是奥伯丁的奥兰达利亚·夜歌提供的一项当地烹饪任务。如果冒险者愿意在黑海岸狩猎那些凶猛的森林陆行鸟并取回它们的肉，她很乐意分享她那珍贵的炖陆行鸟食谱。",h="“简单的陆行鸟生活”是奥伯丁的奥兰达利亚·夜歌提供的一项当地烹饪任务。如果冒险者愿意在黑海岸狩猎那些凶猛的森林陆行鸟并取回它们的肉，她很乐意分享她那珍贵的炖陆行鸟食谱。",kw={"奥兰达利亚·夜歌","奥伯丁","烹饪","黑海岸","简单的陆行鸟生活","森林陆行鸟","陆行鸟肉","炖陆行鸟"},ang={["class:Hunter"]="森林陆行鸟既是敏捷的猎物，也可能是潜在的动物伙伴，在黑海岸雾气弥漫的小径上提供了追踪和狩猎的练习。",["profession:Cooking"]="对于在黑海岸旅行的烹饪者来说，这项任务至关重要，它奖励使用当地野生生物制作营养丰富的炖陆行鸟的食谱。",["race:NightElf"]="在卡利姆多和谐地生活通常意味着靠山吃山，而丰盛的炖陆行鸟已经成为奥伯丁暗夜精灵的一种沿海主食。"},sec={{t="荒野之味",b="奥伯丁或许是一个安静的港口村庄，但在海岸边生存需要善用当地的野生生物。奥兰达利亚·夜歌研制出了一种丰盛的炖陆行鸟秘制食谱，这道美味佳肴的原料来自于那些在黑海岸阴暗树林中潜行的身材高大、行动敏捷的森林陆行鸟。她并没有直接传授烹饪秘诀，而是让有志于成为厨师和猎人的冒险者亲自前往狩猎这些鸟类。"},{t="狩猎森林陆行鸟",b="森林陆行鸟是敏捷、长着锋利喙的禽类掠食者，它们漫游在奥伯丁南北两侧那雾气笼罩的林地和海滩上。虽然它们在受到挑衅时会变得暴躁且具有攻击性，但它们多汁的肉是制作浓郁炖菜的绝佳基础。带回新鲜的肉不仅能填满奥兰达利亚那饥渴的炖锅，还能为猎人赢得她珍视的食谱。"}},faq={{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌是一位居住在黑海岸奥伯丁的暗夜精灵。她以那锅咕嘟作响的炖陆行鸟而闻名，并主动提出向展现出狩猎实力的旅行者传授她的烹饪技艺。",al={"奥兰达利亚","奥兰达利亚·夜歌是谁","炖菜 厨师 奥伯丁"}},{q="我在哪里可以找到陆行鸟肉？",a="陆行鸟肉是通过在整个黑海岸狩猎森林陆行鸟获得的。这些不会飞的大型鸟类在奥伯丁之外的沙滩海岸线和森林树丛中漫游。",al={"陆行鸟肉位置","森林陆行鸟在哪里","如何获得陆行鸟肉"}},{q="这个任务的目的是什么？",a="该任务要求你狩猎森林陆行鸟，为奥兰达利亚·夜歌带回五块肉，以换取学习烹饪炖陆行鸟的方法。",al={"为什么要完成简单的陆行鸟生活","任务目的","简单的陆行鸟生活目标"}},{q="森林陆行鸟狩猎起来危险吗？",a="森林陆行鸟是具有领地意识的鸟类，长着锋利的喙且双腿敏捷，这使得它们在被接近时具有攻击性。然而，一个装备合理的冒险者可以在没有太大危险的情况下猎杀它们。",al={"陆行鸟难杀吗","森林陆行鸟危险"}},{q="这个任务会解锁烹饪食谱吗？",a="是的。在给奥兰达利亚带回她要求的肉后，她会分享她的烹饪秘诀，教冒险者制作炖陆行鸟的食谱。",al={"我能得到食谱吗","炖陆行鸟食谱","烹饪奖励"}},{q="这个任务在哪里进行？",a="任务在奥伯丁定居点开始和结束，狩猎活动则在黑海岸的荒野中进行。",al={"任务区域","简单的陆行鸟生活在哪里"}}},fx={["64984ff6"]={q="为什么奥兰达利亚·夜歌要你完成这件事？",a="奥兰达利亚·夜歌的锅里空空如也，正想吃新鲜的陆行鸟炖肉。她愿意分享自己的秘方之前，坚持要看看你是否有胆量亲自去猎杀高脚鸟，并为她的炉火带回新鲜的肉。",al={"奥兰达利亚·夜歌的目的","奥兰达利亚为什么要陆行鸟肉","为什么要炖陆行鸟"}},["624f04e5"]={q="陆行鸟肉有什么用？",a="鲜嫩多汁的肉是奥兰达利亚炖陆行鸟的主要材料。给她带去五块肉，既能装满她空空的锅，也能证明你有资格学习她的野外烹饪秘方。",al={"陆行鸟肉有什么用","为什么要陆行鸟肉","陆行鸟肉的用途"}}},fp="19,267,19.430.0,26.361.0,29.202.0,33.176.0,34.165.0,41.196.0,40.133.0,33.119.0"}
P.entries["quest:218"] = {n="被窃取的日记",s="“被窃的日记”是丹莫罗的一项早期联盟任务，格瑞林·白须委托冒险者进入寒脊山谷的巨魔洞穴，找回他被窃的笔记。为了找回它，你必须击败强大的巨魔首领格里克尼尔。找回日记后，格瑞林就能完成他对寒脊山谷内巨魔威胁的评估了。",h="“被窃的日记”是丹莫罗的一项早期联盟任务，格瑞林·白须委托冒险者进入寒脊山谷的巨魔洞穴，找回他被窃的笔记。为了找回它，你必须击败强大的巨魔首领格里克尼尔。找回日记后，格瑞林就能完成他对寒脊山谷内巨魔威胁的评估了。",kw={"寒脊山谷","丹莫罗","霜鬃巨魔要塞","霜鬃巨魔","格瑞林·白须","格里克尼尔","森内尔·白须","被窃的日记"},ang={["faction:Alliance"]="压制具有侵略性的霜鬃部族，确保了丹莫罗的初始山谷免受内部破坏的影响。",["race:Dwarf"]="扫除寒脊山谷中霜鬃部族的领导层，保护了走出安威玛尔、踏出第一步的年轻矮人新兵。",["race:Gnome"]="在安威玛尔避难的侏儒难民依赖寒脊山谷通道的安全性，以便在矮人领地内重新集结。"},sec={{t="学者遗失的笔记",b="格瑞林·白须一直在观察侵扰寒脊山谷的霜鬃巨魔，并详细记录下它们的习性和突发的侵略行为。在动乱期间，一个极其强壮的巨魔偷走了他的私人日记，并退回了它们巢穴的深处。对于格瑞林来说，这次丢失不仅仅是情感上的损失；笔记本中包含了他大部分的侦察记录，导致他的正式评估工作在找回日记前不得不停滞不前。"},{t="直面格里克尼尔",b="偷走日记的那个野蛮家伙是格里克尼尔，一个强大的霜鬃巨魔。他的身体和脸上涂着独特的纹饰，盘踞在山谷巨魔洞穴的中心。击杀格里克尼尔可以粉碎该洞穴巨魔在当地的直接领导层，并夺回格瑞林的日记。除掉这个首领后，格瑞林感到很有把握报告说山谷的巨魔局势已经得到控制，并将他完成的调查结果寄给了他的兄弟森内尔。"}},faq={{q="是谁偷走了格瑞林·白须的日记？",a="日记是被格里克尼尔偷走的，这是一个巨大的霜鬃巨魔，他的皮肤和脸上有着奇怪的斑纹，潜伏在巨魔洞穴的深处。",al={"谁偷了日记","谁拿着格瑞林的日记","日记窃贼"}},{q="在哪里可以找到格里克尼尔？",a="格里克尼尔位于寒脊山谷南部的巨魔洞穴内。",al={"格里克尼尔在哪里","格里克尼尔的位置","如何找到格里克尼尔"}},{q="为什么这本日记对格瑞林很重要？",a="日记里记载了格瑞林·白须关于寒脊山谷巨魔活动的笔记和发现。他需要取回日记，以便为他的兄弟森内尔汇总一份完整的报告。",al={"格瑞林为什么要找回日记","格瑞林的日记里有什么"}},{q="归还日记后会发生什么？",a="一旦日记被找回，格瑞林就会完成他那份关于寒脊山谷巨魔局势的评估报告，并要求你将他的观察结果送到卡拉诺斯，转交给他的兄弟森内尔·白须。",al={"完成“被窃的日记”后接下来做什么","被窃的日记后续任务"}},{q="霜鬃巨魔在任务后被赶出寒脊山谷了吗？",a="格瑞林认为在击败格里克尼尔后，寒脊山谷的巨魔局势已得到控制，尽管霜鬃部族在丹莫罗更广阔的山路上依然是一个长期的威胁。",al={"寒脊山谷的巨魔被击败了吗","寒脊山谷是否没有巨魔威胁了"}},{q="森内尔·白须是谁？",a="森内尔·白须是格瑞林的兄弟，驻扎在寒脊山谷外靠近卡拉诺斯的一名联盟侦察兵，负责收集王国所面临的威胁情报。",al={"森内尔是谁","格瑞林的兄弟森内尔"}}},fx={["78f0c4e3"]={q="为什么格瑞林·白须要你完成这件事？",a="格瑞林正在为他的兄弟塞尼尔汇总寒脊山谷霜鬃巨魔威胁的正式报告。没有他的日志，他就无法完成笔记或评估山谷的安全状况，当地领袖也会因此缺少有关巨魔活动的重要情报。",al={"格瑞林为什么要他的日志","格瑞林·白须的目的","为什么找回格瑞林的日志"}},beb6a987={q="为什么格瑞林要你帮忙找回他的日志？",a="格瑞林是个观察者，并非前线战士；他的日志被一个强壮的巨魔暴徒带进了寒脊山谷深处的巨魔洞穴。他已经亲眼见识过你击退山谷中巨魔的本领，于是找你深入洞穴，处理其中的危险。",al={"格瑞林为什么需要我","为什么派冒险者去找日志","格瑞林为什么不能自己找回日志"}}},fp="18,368,22.459.0,29.474.0,37.160.0,37.95.0,39.176.0,42.193.1,67.198.0,24.160.0"}
P.entries["quest:219"] = {n="失踪人员",s="“失踪的士兵”是一个联盟护送任务，地点在赤脊山，目的是将基沙恩下士从黑石兽人的俘虏中解救出来。他的部队在山里被全歼后，基沙恩被打晕并拖进了一座洞穴要塞。将这位受伤的士兵安全带回湖畔镇，可以帮助当地驻军确认他们失踪士兵的悲惨命运。",h="“失踪的士兵”是一个联盟护送任务，地点在赤脊山，目的是将基沙恩下士从黑石兽人的俘虏中解救出来。他的部队在山里被全歼后，基沙恩被打晕并拖进了一座洞穴要塞。将这位受伤的士兵安全带回湖畔镇，可以帮助当地驻军确认他们失踪士兵的悲...",kw={"黑石兽人","基沙恩下士","护送任务","基沙恩","湖畔镇","治安官马瑞斯","失踪的士兵","赤脊山"},ang={["class:Warrior"]="将基沙恩从武装的兽人营地中救出，需要抵御一波又一波冷酷的黑石攻击者，同时还要保护脑部受创的战友。",["faction:Alliance"]="湖畔镇的驻军已紧绷到崩溃的边缘，这使得每一位获救的士兵对于王国抵御黑石氏族的防御战来说都至关重要。"},sec={{t="全军覆没",b="随着黑石兽人从北方的山峰蜂拥而下，赤脊山变得越来越危险。镇卫兵派出的巡逻队经常遭到伏击，而基沙恩下士的部队遭受了最惨重的损失。由于寡不敌众，他部队中的大多数士兵当场被杀。基沙恩之所以能活下来，只是因为在被处决前的一记重击让他昏了过去，兽人便把他拖回洞穴作为俘虏。"},{t="逃离洞穴",b="基沙恩遍体鳞伤、脑部受创，且被关在敌方领地的深处，他无法独自走下山。护送他前往湖畔镇的安全地带，需要穿过盘踞在山脊上蜂拥的兽人战团。活着回到湖畔镇让治安官马瑞斯感到一丝慰藉，他一直在设法拼凑失踪部队的遭遇，同时还要让湖畔镇做好抵御进一步袭击的准备。"}},faq={{q="谁是基沙恩下士？",a="基沙恩下士是一名驻扎在赤脊山的联盟步兵。在多岩石的山丘进行巡逻时，他的部队被黑石兽人压制，在被拖走关押之前，他是已知唯一的幸存者。",al={"基沙恩下士","基沙恩是谁","基沙恩背景故事"}},{q="基沙恩下士在哪里被俘的？",a="他被关押在赤脊山北部丘陵中一个兽人出没的洞穴深处，周围是敌对的黑石战士。",al={"基沙恩在哪里","基沙恩位置","基沙恩的洞穴"}},{q="基沙恩部队的其他成员遭遇了什么？",a="据基沙恩说，黑石兽人伏击并压制了他的部队，在最初的冲突中杀死了几乎所有人。",al={"基沙恩的小队","部队的遭遇","基沙恩的部下"}},{q="谁派玩家去营救基沙恩？",a="该任务直接由关押在洞穴里的基沙恩下士本人发布，联盟的冒险者发现并解救他时即可接到。",al={"谁发布失踪的士兵任务","任务发布者","如何接取失踪的士兵"}},{q="基沙恩被释放后去了哪里？",a="他必须被护送下山前往湖畔镇，在那里他会向镇子桥附近的治安官马瑞斯报告。",al={"失踪的士兵任务交付","基沙恩逃往何处","基沙恩的目的地"}},{q="为什么黑石兽人会在赤脊山？",a="黑石氏族从他们位于燃烧平原的据点向南推进到赤脊山，威胁着防御薄弱的湖畔镇聚居点，并伏击王国的巡逻队。",al={"赤脊山的黑石兽人","为什么湖畔镇有兽人","黑石入侵"}}},fx={["64cb6fe2"]={q="基沙恩下士为什么需要你帮他逃出去？",al={"为什么要帮基沙恩","基沙恩的动机","基沙恩为什么需要救援"}},["1d637b84"]={q="为什么基沙恩不能独自逃出去，或等湖畔镇的卫兵来救？",a="基沙恩伤势严重，需要帮助才能杀出黑石掠夺者的包围。与此同时，湖畔镇的守军已竭尽全力抵御豺狼人和兽人，根本抽不出人手深入敌境搜救。当你偶然发现他的牢房时，你确实是他活着回去的唯一希望。",al={"基沙恩为什么不能独自逃走","基沙恩为什么需要我","为什么没有镇卫兵"}}},fp="17,365,18.474.0,21.424.0,24.243.0,36.128.0,44.138.0,36.131.0,40.129.0,39.181.0"}
P.entries["quest:22"] = {n="猪肝馅饼",s="血牙野猪的肝馅饼是为西部荒野萨丁农场的萨尔玛·萨丁完成的一项烹饪差事。随着王国的粮仓被强盗洗劫一空，当地农户只能依靠捕猎凶猛的本地野猪来为餐桌增添一道丰盛的佳肴。帮助萨尔玛能在这片凄凉的边境之地，带来一丝难得的舒适和家常般的款待。",h="血牙野猪的肝馅饼是为西部荒野萨丁农场的萨尔玛·萨丁完成的一项烹饪差事。随着王国的粮仓被强盗洗劫一空，当地农户只能依靠捕猎凶猛的本地野猪来为餐桌增添一道丰盛的佳肴。帮助萨尔玛能在这片凄凉的边境之地，带来一丝难得的舒适和家常...",kw={"野猪","烹饪","血牙野猪","肝馅饼","萨丁农场","萨尔玛·萨丁","西部荒野"},ang={["faction:Alliance"]="帮助像萨丁一家这样的农村农户，能直接支持那些在暴风城军队缺席的情况下，仍努力守护王国边境的忠诚人类家庭。",["profession:Cooking"]="萨尔玛的这道菜展现了传统的人类乡村烹饪技艺，使用大蒜、迷迭香和莳萝等园艺香料，将野味内脏提升为一道主食。"},sec={{t="边境的款待",b="西部荒野曾是暴风城肥沃的粮仓，但近年来境况不佳。由于基础设施缺乏维护、强盗横行以及农田荒废，仅存的定居者们生活日益艰难。在萨丁农场，萨尔玛·萨丁不辞辛劳，努力在日益逼近的威胁中守护着家的温馨。制作一份传统的肉馅饼，是那些试图保全生活方式的农户们所能享受到的为数不多的简单奢侈之一。"},{t="西部荒野的野兽",b="西部荒野的平原上到处都是血牙野猪，这种凶猛的野猪以皮糙肉厚和獠牙锋利而闻名。虽然它们对落单的农场工人来说很危险，但对那些与正常贸易隔绝的家庭来说，它们也是重要的肉食来源。萨尔玛的食谱需要仔细处理——加入碎迷迭香、蒜末、莳萝碎和炖肉汁——才能将这些强壮野兽的浓腥内脏变成一道香气四溢的盛宴。"}},faq={{q="谁是萨尔玛·萨丁？",a="萨尔玛·萨丁是一位坚韧的农妇，她和丈夫农夫萨丁住在位于西部荒野中部的农场里。她以擅长家常料理而闻名，尽管面临强盗和野兽的威胁，她依然竭尽全力保持乐观的精神。",al={"萨尔玛·萨丁","谁是萨尔玛","萨丁的妻子"}},{q="萨尔玛为什么需要血牙野猪的肝？",a="萨尔玛正在准备她那著名的鲜美肉馅饼，准备和丈夫一起享用。馅饼皮已经烤好了，调料也准备就绪，只需要当地血牙野猪的肝脏来完成馅料的炖煮。",al={"为什么需要血牙野猪的肝","馅饼的原料","肝馅饼的用途"}},{q="血牙野猪在西部荒野通常出现在哪里？",a="血牙野猪在西部荒野的金色平原和休耕的农田上四处游荡，它们在荒废的田地里翻找食物，并在土路上漫步。",al={"血牙野猪的位置","哪里能找到野猪","血牙野猪肝狩猎"}},{q="血牙野猪对当地农民有危险吗？",a="是的。血牙野猪是一种凶猛的领地型野猪，长有尖锐的獠牙。它们对平原上的牲畜和毫无防备的旅行者构成了重大威胁。",al={"血牙野猪是否具有敌意","西部荒野的野猪危险"}},{q="为什么西部荒野现在的食物如此短缺？",a="由于暴风城缺乏王室支持，加上有组织的强盗频繁劫掠，许多农民被迫背井离乡，使曾经的王国粮仓变成了贫困挣扎的边境之地。",al={"西部荒野饥荒","为什么西部荒野缺乏食物","西部荒野的艰难时期"}},{q="完成这项任务能帮助萨丁农场生存下去吗？",a="虽然这不能解决西部荒野面临的更广泛的危机，但收集新鲜肉类可以直接维持萨丁一家的生计，并为旅行者提供旅途所需的丰盛口粮。",al={"馅饼是否重要","萨丁农场的食物供应"}}},fp="18,200,20.417.0,23.390.0,21.212.0,36.218.0,48.146.0,45.169.0,44.210.0,56.160.0"}
P.entries["quest:220"] = {n="水之召唤",s="这段萨满祭司试炼的任务是让初学者将净化后的水带回贫瘠之地，交给水之先知伊斯伦。这瓶水由隐士Brine准备并祝福过，其中含有调制精神sapta所需的催化剂。一旦酿成，这种药剂将揭示居住在遥远银松森林水域中的元素之灵。",h="这段萨满祭司试炼的任务是让初学者将净化后的水带回贫瘠之地，交给水之先知伊斯伦。这瓶水由隐士Brine准备并祝福过，其中含有调制精神sapta所需的催化剂。一旦酿成，这种药剂将揭示居住在遥远银松森林水域中的元素之灵。",kw={"brine","call of water","水之先知伊斯伦","sapta","银松森林","贫瘠之地","一瓶最纯净的水","water sapta","水之图腾"},ang={["class:Shaman"]="每一位部落萨满祭司都必须完成Call of Water仪式，以与灵魂沟通并获得携带水之图腾的权利，该图腾掌管着治疗和补给。",["faction:Horde"]="这项试炼横跨卡利姆多和洛丹伦，展示了部落广阔的地理版图，年轻的初学者从贫瘠之地一路前往被遗忘者控制的银松森林。"},sec={{t="返回岸边",b="在穿越了南贫瘠之地并完成了Brine设下的试炼后，萨满祭司学徒将获得一瓶最纯净的水。这个容器中装满了来自纯净泉水的水，并经由Brine的隐居仪式所祝圣，代表了元素纯粹的潜力。将其安全地带回水之先知伊斯伦守望的东海岸，是连接Brine质朴智慧与正式图腾仪式的关键纽带。"},{t="sapta的用途",b="收到纯净的水后，水之先知伊斯伦解释说，凡人的眼睛无法轻易看到难以捉摸的水之灵。为了与它们沟通，初学者必须饮用一种被称为sapta的特制药水。从Brine那里带来的液体将成为这种药水强有力的基础，开启萨满祭司的感官，去察觉那些隐藏在凡人视线之外的力量。然而，正如水之先知伊斯伦所警告的那样，沟通仅仅是旅程的一半；灵魂本身还需要考验。"},{t="前往洛丹伦",b="水之先知伊斯伦透露，试炼的高潮不会在卡利姆多干燥的广袤土地上进行。相反，萨满祭司必须横跨大海，前往位于幽暗城以南、古老且迷雾笼罩的银松森林海岸。在那里，在这一座与世隔绝的神龛旁，必须喝下sapta，这样初学者才能直面元素生物，并获得显现水之图腾的权利。"}},faq={{q="一瓶最纯净的水里装着什么？",a="这瓶子里装着由初学者从纯净泉水中收集，并经由隐士Brine的仪式祝圣过的水。它代表了未受污染的元素之水，这是酿制与水之灵沟通所需的炼金sapta的关键。",al={"一瓶最纯净的水","brine的水","brine给了我什么"}},{q="谁是水之先知伊斯伦？",a="水之先知伊斯伦是一位居住在贫瘠之地东南偏远海岸线上（棘齿城以南）的年长萨满祭司。她是部落萨满祭司寻求与水元素沟通并获得水之图腾的主要导师。",al={"伊斯伦","谁是水之先知伊斯伦","水之先知伊斯伦的背景故事"}},{q="什么是sapta？",a="sapta是一种由萨满导师制作的仪式药剂。饮用后，它会改变饮用者的感知，使萨满祭司能够清晰地看到并与凡人视线中不可见的元素之灵互动。",al={"sapta的含义","water sapta","sapta有什么用"}},{q="为什么我接下来必须去银松森林？",a="与此次沟通有关的元素神龛位于东部王国幽暗城以南的银松森林沿海水域。居住在那里的灵魂在授予对其元素的掌控权之前，需要进行沟通和最终的考验。",al={"为什么去银松森林","银松森林的水之图腾","银松森林的神龛"}},{q="Brine住在哪里？",a="Brine住在南贫瘠之地山丘高处的一间僻静小屋里，位于通往升降梯和千针石林的道路以西。",al={"brine的位置","brine在哪里","寻找brine"}},{q="有萨满祭司可以跳过制作sapta的步骤吗？",a="不可以。沟通仪式要求萨满祭司的精神与不可见的世界保持协调。如果没有sapta所提供的感官桥梁，神龛处的水之灵就无法被呼唤或挑战。",al={"跳过sapta","需要sapta吗","萨满幻象任务"}}},fx={["5a67c999"]={q="为什么布莱恩要让你回去找水之先知伊斯伦？",a="布莱恩已经尽了自己的职责，将你在卡利姆多各处收集的水净化，并封存在祝福过的瓶中。她知道自己只是指引你前行的人，并非引导你领悟更深奥秘的先知。水之先知伊斯伦派你去找布莱恩，是为了考验你的毅力；如今最纯净的水已经备好，只有伊斯伦才有智慧调制你的萨普塔，并指引你完成最终的元素沟通试炼。",al={"布莱恩为什么派你去","布莱恩的水之召唤任务动机","为什么要回去找伊斯伦"}},["51ede7cd"]={q="为什么布莱恩需要你带着水瓶回去，而不亲自送回去？",a="这场朝圣是你作为萨满祭司的试炼，不是图方便跑腿。瓶中的水是你亲自在贫瘠之地布莱恩小屋下方的水池、塔伦米尔的井，以及灰谷的星尘废墟取来的，并由你亲手完成祝福。带着它穿过平原回到伊斯伦那里，能让你在尝试与灵魂沟通前，亲自与元素建立联系。",al={"为什么必须由我送水瓶","布莱恩的水之召唤任务为什么找我","布莱恩为什么不能自己送去"}}},fp="13,347,19.429.0,24.444.0,23.397.1,40.257.0,23.238.0,16.225.0,46.247.0,22.146.0,39.206.0"}
P.entries["quest:2205"] = {n="军情七处",s="“寻找军情七处”是科瑞恩·塞尔留斯在艾尔文森林为潜行者新手提供的入门任务。新手特工需要带着一个小包裹从闪金镇前往暴风城，并以此为契机拜见军情七处首领、国王秘密情报网络的核心人物马迪亚斯·肖尔大师。",h="“寻找军情七处”是科瑞恩·塞尔留斯在艾尔文森林为潜行者新手提供的入门任务。新手特工需要带着一个小包裹从闪金镇前往暴风城，并以此为契机拜见军情七处首领、国王秘密情报网络的核心人物马迪亚斯·肖尔大师。",kw={"闪金镇","科瑞恩·塞尔留斯","mathias shaw","old town","潜行者","寻找军情七处","军情七处","暴风城"},ang={["class:Rogue"]="这项任务标志着一名潜行者正式进入暴风城最高间谍机构服役，从街头小巷的伎俩转变为效力于王室的侦察工作。",["faction:Alliance"]="军情七处充当着王国的耳目，以应对内外威胁，在瓦里安·乌瑞恩国王失踪期间默默守护着王国。"},sec={{t="信使的考验",b="在闪金镇的Lion's Pride Inn里，潜行者训练师科瑞恩·塞尔留斯从不浪费时间去恭维新人。虽然她觉得这些新招募的菜鸟看起来更像是送奶酪的伙计，而不是能干的秘密特工，但她还是下达了一个跑腿任务：将一件密封的货物送往都城。这项任务既是一次可靠的信使工作，也是对那些希望效力于王国、更广阔的情报工作的斥候们进行的一场低调的审查。"},{t="旧城区的紧闭之门",b="目的地位于Old Town深处，这是暴风城中繁忙而古老的一个区域。在Old Town的东南角坐落着军情七处（SI:7）的Command Center——暴风城情报局第七分部。马迪亚斯·肖尔大师就在这里统筹王国的秘密行动。当他以其标志性的冷淡和怀疑态度接过包裹时，他也在评估这位旅行者是否具备进行真实间谍活动所需的胆识。"}},faq={{q="什么是军情七处？",a="军情七处（SI:7）即“暴风城情报局第七分部”。它是暴风城王国的秘密情报和隐秘行动部门，由马迪亚斯·肖尔大师从他们位于Old Town的总部进行领导。",al={"军情七处的意思","什么是军情七处","军情七处背景故事"}},{q="科瑞恩·塞尔留斯是谁？",a="科瑞恩·塞尔留斯是一位驻扎在闪金镇Lion's Pride Inn的潜行者训练师。她与军情七处保持联络，负责评估当地的招募人员，并将有潜力的斥候引荐给暴风城的马迪亚斯·肖尔大师。",al={"科瑞恩·塞尔留斯","闪金镇潜行者训练师"}},{q="马迪亚斯·肖尔在暴风城什么位置？",a="马迪亚斯·肖尔大师位于暴风城Old Town东南角的军情七处总部楼上，穿过该城的潜行者训练师区域即可到达。",al={"肖尔在哪","找到马迪亚斯·肖尔","马迪亚斯·肖尔位置"}},{q="把包裹交给肖尔之后会发生什么？",a="一旦你向马迪亚斯·肖尔报到，他会立即通过一项秘密行动来测试你的潜行者实战技能，让你前往杰罗德码头从一名迪菲亚码头管理员手中窃取一份Shipping Schedule。",al={"寻找军情七处之后的任务","肖尔想要什么"}},{q="为什么科瑞恩在交出货物前要嘲讽玩家？",a="军情七处特工以高超的能力和敏锐的直觉自豪。塞尔留斯对新兵表现严厉，旨在测试他们的脾性，确保只有那些脸皮够厚、意志坚定的人才能去打扰肖尔大师。",al={"为什么科瑞恩要侮辱我","奶酪递送侮辱"}}},fp="14,192,16.335.0,31.331.0,13.186.0,21.184.0,43.154.0,50.149.1,64.186.0"}
P.entries["quest:2206"] = {n="连偷带抢",s="“抓捕与夺取”是军情七处首领马迪亚斯·肖尔派给有潜力的潜行者的卧底任务。任务要求特工潜入杰罗德码头，从迪菲亚潜行者手中窃取船运情报。",h="“抓捕与夺取”是军情七处首领马迪亚斯·肖尔派给有潜力的潜行者的卧底任务。任务要求特工潜入杰罗德码头，从迪菲亚潜行者手中窃取船运情报。",kw={"水晶湖","迪菲亚","码头管理员","闪金镇","杰罗德码头","mathias shaw","shipping schedule","军情七处","抓捕与夺取"},ang={["class:Rogue"]="这项任务标志着潜行者正式加入军情七处，通过考验潜行和扒窃本能来赢得认可，并从马迪亚斯·肖尔那里获得一把标志性的匕首。",["faction:Alliance"]="在杰罗德码头拦截迪菲亚的补给链不仅保护了艾尔文森林，还削弱了威胁暴风城周边领土的犯罪集团。"},sec={{t="技艺的考验",b="对于暴风城中一位胸怀大志的特工来说，站在马迪亚斯·肖尔面前便是进入王国秘密情报机构的真正考验。肖尔要求的不是单纯的蛮力，而是精妙的技巧和潜行能力。在不引起王国公开丑闻的情况下悄无声息地解决关键人物并取回重要文件，这是军情七处的核心准则，而这项任务就是新人的试炼场。"},{t="河上的走私者",b="杰罗德码头坐落在艾尔文森林南部的河边，位于闪金镇以南，马科伦农场正东方。这里曾是一个安静的地方码头，但迪菲亚潜行者夺取了该地的控制权，并将其建立为一条非法的运输走廊。通过在水中转运走私的武器、补给品和违禁品，将它们从赤脊山运往西部荒野，这些盗贼完全绕过了王国的道路巡逻队。"},{t="合理的推诿",b="在派遣特工进入现场之前，肖尔明确传达了军情七处不成文的准则：如果特工被捕、身份暴露或被杀，王国及其情报首脑将否认对此人的任何知情权。找回迪菲亚码头管理员的时间表，既能获取迪菲亚潜行者补给线的关键证据，又能让暴风城的官方介入保持在阴影之中。"}},faq={{q="是谁发布了“抓捕与夺取”任务？",a="暴风城情报机构军情七处的首领马迪亚斯·肖尔在旧城区的军情七处总部内发布该任务。",al={"谁发布抓捕与夺取任务","抓捕与夺取任务发布者"}},{q="杰罗德码头在哪里？",a="杰罗德码头是位于艾尔文森林南部河流上的一个码头，在闪金镇以南，马科伦农场正东方。迪菲亚潜行者已经征用了那里的码头和码头房屋。",al={"杰罗德码头位置","杰罗德码头在哪里","码头管理员位置"}},{q="迪菲亚潜行者通过杰罗德码头走私什么？",a="迪菲亚潜行者利用杰罗德码头在赤脊山和西部荒野之间的水域运送大量的违禁品和补给品，从而绕过王国的岗哨和道路检查站。",al={"他们走私什么","迪菲亚违禁品"}},{q="谁携带着迪菲亚船运时间表？",a="船运时间表由迪菲亚码头管理员携带，他就在杰罗德码头的码头房屋旁守卫。",al={"船运时间表在哪里","谁掉落时间表","迪菲亚码头管理员"}},{q="如果特工在任务中被俘会发生什么？",a="正如马迪亚斯·肖尔所警告的那样，军情七处奉行严格的“合理推诿”原则。如果特工身份暴露或被捕，军情七处将否认与他们有任何联系。",al={"如果我失败了会怎样","被军情七处否认"}},{q="为什么军情七处需要这份船运时间表？",a="这份文件详细说明了迪菲亚潜行者如何在赤脊山和西部荒野之间运输违禁品。获取它能让暴风城的情报网络在不惊动该组织的情况下绘制出敌人的后勤地图。",al={"为什么需要时间表","军情七处船运时间表"}}},fp="15,149,20.321.0,22.319.0,21.324.0,38.121.0,25.187.0,54.135.0,41.97.0,61.104.0,48.197.0"}
